/* Ghi chú học từ – chủ đề, kỹ năng, chuyên ngành, kỳ thi (tự biên soạn) – Lexkite, CC BY-SA 4.0 */
(function (g) { const N = g.WORD_NOTES = g.WORD_NOTES || {}; Object.assign(N, {
  "curriculum": { m: "Gốc Latin 'curriculum' = đường đua → con đường học sinh phải 'chạy' qua các môn → chương trình học.", e: "Sai: the curriculums of school → Đúng: the school curricula/curriculums. Sai: add skills in curriculum → Đúng: add skills to the curriculum.", u: "Writing Task 2 về giáo dục: 'Financial literacy should be included in the national curriculum'. Speaking Part 3: so sánh chương trình học các nước.", f: "curriculum (n), curricula (pl), curricular (adj), extracurricular (adj)" },
  "literacy": { m: "liter- = chữ cái (như 'letter', 'literature') → biết chữ → khả năng đọc viết.", e: "Sai: literacy rate is increase → Đúng: the literacy rate has increased. Sai: a literacy person → Đúng: a literate person.", u: "Writing Task 2/Task 1: literacy rate ở nước đang phát triển. Speaking: digital literacy, media literacy khi bàn về công nghệ và giáo dục.", f: "literacy (n), literate (adj), illiterate (adj), illiteracy (n)" },
  "vocational": { m: "voc- = gọi (vocation = 'tiếng gọi' nghề nghiệp) → học để theo nghề mình được gọi → dạy nghề.", e: "Sai: vocation training → Đúng: vocational training. Nhầm với 'vacation' (kỳ nghỉ): vocational ≠ vacational.", u: "Writing Task 2: 'Should young people go to university or receive vocational training?'. Speaking Part 3: vocational schools, practical skills, job market.", f: "vocational (adj), vocation (n), vocationally (adv); technical college, apprenticeship" },
  "compulsory": { m: "compel = ép buộc → compulsory = bị ép phải làm → bắt buộc, trái với 'optional'.", e: "Sai: compulsive education → Đúng: compulsory education. Lưu ý: compulsive = nghiện, không kiểm soát được (compulsive gambler).", u: "Writing Task 2: 'Should community service be compulsory for teenagers?'. Speaking Part 1: compulsory subjects at school, school uniforms.", f: "compulsory (adj), compel (v), compulsion (n); mandatory, obligatory (đồng nghĩa)" },
  "undergraduate": { m: "under- (dưới) + graduate (người tốt nghiệp) → chưa tới mức tốt nghiệp → sinh viên đại học.", e: "Sai: I am an undergraduated student → Đúng: I am an undergraduate (student). Sai: undergraduate of Hanoi University → Đúng: undergraduate at Hanoi University.", u: "Speaking Part 1 (Work or study?): 'I'm an undergraduate studying economics'. Writing: undergraduate degree, tuition fees, student debt.", f: "undergraduate (n/adj), graduate (n/v), postgraduate (n/adj), graduation (n)" },
  "rote learning": { m: "Hình ảnh: 'rote' = lặp máy móc, như con vẹt nói lại không hiểu → học thuộc lòng máy móc.", e: "Sai: learning by rotes → Đúng: learning by rote. Sai: rote learning make students bored → Đúng: rote learning makes students bored.", u: "Writing Task 2 so sánh hệ thống giáo dục: 'Asian schools rely heavily on rote learning'. Đối lập với critical thinking, creativity.", f: "learn by rote (v phrase), memorisation (n), cramming (n); critical thinking (trái nghĩa)" },
  "extracurricular": { m: "extra- (ngoài) + curricular (chương trình học) → hoạt động nằm ngoài giờ học chính → ngoại khóa.", e: "Sai: extra-curriculum activities → Đúng: extracurricular activities. Sai: join extracurricular → Đúng: join/take part in extracurricular activities.", u: "Speaking Part 1/2: kể về câu lạc bộ ở trường. Writing Task 2: lợi ích của extracurricular activities đối với kỹ năng mềm.", f: "extracurricular (adj), curriculum (n), curricular (adj); after-school activities" },
  "deforestation": { m: "de- (lấy đi) + forest (rừng) + -ation → hành động lấy rừng đi → nạn phá rừng.", e: "Sai: the deforestation are serious → Đúng: deforestation is serious (danh từ không đếm được). Sai: deforest the trees → Đúng: clear the forest.", u: "Writing Task 2 môi trường: nguyên nhân biến đổi khí hậu, mất môi trường sống. Collocation: tackle/halt deforestation, illegal logging.", f: "deforestation (n), deforest (v), forest (n), reforestation/afforestation (n, trồng lại rừng)" },
  "emission": { m: "e- (ra ngoài) + mit (gửi, như 'transmit') → gửi ra ngoài → khí thải được thải ra.", e: "Sai: reduce carbon emission → Đúng: reduce carbon emissions (thường số nhiều). Sai: emiss gases → Đúng: emit gases.", u: "Writing Task 2/Task 1: greenhouse gas emissions, vehicle emissions, cut emissions. Speaking Part 3: giải pháp giảm khí thải ở thành phố.", f: "emission (n), emit (v), emitter (n); zero-emission (adj), exhaust fumes" },
  "renewable": { m: "re- (lại) + new (mới) + -able → có thể làm mới lại → năng lượng tái tạo không cạn.", e: "Sai: renewal energy → Đúng: renewable energy. Sai: renewable energies is cheap → Đúng: renewable energy is cheap / renewables are cheap.", u: "Writing Task 2: 'Governments should invest in renewable energy such as solar and wind power'. Speaking Part 3: tương lai năng lượng.", f: "renewable (adj), renewables (n pl), renew (v), renewal (n), non-renewable (adj)" },
  "sustainable": { m: "sustain = nâng đỡ, duy trì → sustainable = duy trì được lâu dài không cạn kiệt → bền vững.", e: "Sai: sustainable develop → Đúng: sustainable development. Sai: sustainablity → Đúng: sustainability.", u: "Writing Task 2: sustainable development, sustainable tourism, sustainable lifestyle. Speaking Part 3: doanh nghiệp xanh, tiêu dùng bền vững.", f: "sustainable (adj), sustainability (n), sustain (v), sustainably (adv), unsustainable (adj)" },
  "biodiversity": { m: "bio- (sự sống) + diversity (đa dạng) → sự đa dạng của sự sống → đa dạng sinh học.", e: "Sai: biodiversities of forest → Đúng: the biodiversity of the forest (không đếm được). Sai: bio-diversity loses → Đúng: biodiversity loss.", u: "Writing Task 2 môi trường/động vật hoang dã: 'Deforestation leads to a loss of biodiversity'. Collocation: protect/preserve biodiversity.", f: "biodiversity (n), diverse (adj), diversity (n), biological (adj); ecosystem (n)" },
  "conservation": { m: "conserve = giữ gìn (như 'preserve') → conservation = sự gìn giữ thiên nhiên, năng lượng → bảo tồn.", e: "Sai: conversation of wildlife → Đúng: conservation of wildlife (đừng nhầm 'conversation' = cuộc trò chuyện).", u: "Writing Task 2: wildlife conservation, energy conservation, conservation areas. Speaking Part 3: vai trò của vườn quốc gia trong bảo tồn.", f: "conservation (n), conserve (v), conservationist (n), conservative (adj, nghĩa khác: bảo thủ)" },
  "habitat": { m: "Gốc Latin 'habitare' = sinh sống (như 'inhabit') → nơi loài vật sinh sống tự nhiên → môi trường sống.", e: "Sai: habitat of human → Đúng: dùng 'habitat' chủ yếu cho động thực vật. Sai: destroy habitat of animals → Đúng: destroy animals' habitats.", u: "Writing Task 2: habitat loss/destruction do đô thị hóa, phá rừng. Speaking Part 3: 'Zoos cannot replace animals' natural habitats'.", f: "habitat (n), inhabit (v), inhabitant (n), habitable (adj), uninhabitable (adj)" },
  "contaminate": { m: "con- (cùng) + tag/tam (chạm) → chạm vào chất bẩn → làm nhiễm bẩn, ô nhiễm.", e: "Sai: water is contaminate → Đúng: water is contaminated. Sai: contaminate with the air → Đúng: contaminate the air.", u: "Writing Task 2: 'Industrial waste contaminates rivers and drinking water'. Speaking Part 3: thực phẩm, nước sạch, an toàn vệ sinh.", f: "contaminate (v), contamination (n), contaminant (n), contaminated (adj); pollute (đồng nghĩa)" },
  "landfill": { m: "land (đất) + fill (lấp đầy) → lấy rác lấp đầy hố đất → bãi chôn lấp rác.", e: "Sai: throw rubbish to landfill → Đúng: send rubbish to landfill / dump waste in landfills. Sai: land-fill site → Đúng: landfill site.", u: "Writing Task 2 về rác thải: 'Most plastic ends up in landfill'. Speaking Part 3: recycling, reducing waste, landfill sites.", f: "landfill (n), landfill site (n), dump (n/v), waste disposal (n); recycling, incineration" },
  "endangered": { m: "en- (đưa vào) + danger (nguy hiểm) + -ed → bị đưa vào cảnh nguy → loài sắp tuyệt chủng.", e: "Sai: endanger species → Đúng: endangered species. Sai: dangerous species (loài nguy hiểm) khi muốn nói loài nguy cấp.", u: "Writing Task 2: 'Governments should protect endangered species'. Speaking Part 2: mô tả một loài động vật có nguy cơ tuyệt chủng.", f: "endangered (adj), endanger (v), danger (n), dangerous (adj); threatened, at risk of extinction" },
  "automation": { m: "auto- (tự) + -mation (như 'motion', chuyển động) → máy tự chạy không cần người → tự động hóa.", e: "Sai: automation will replace many works → Đúng: automation will replace many jobs. Sai: automatic the process → Đúng: automate the process.", u: "Writing Task 2 công nghệ/việc làm: 'Automation could lead to mass unemployment'. Speaking Part 3: robots trong nhà máy, ngân hàng.", f: "automation (n), automate (v), automated (adj), automatic (adj), automatically (adv)" },
  "breakthrough": { m: "Hình ảnh: break (phá) + through (xuyên qua) → phá vỡ bức tường bế tắc → bước đột phá.", e: "Sai: make a break through → Đúng: make a breakthrough (một từ). Sai: breakthrough of medicine → Đúng: a breakthrough in medicine.", u: "Writing Task 2 khoa học/công nghệ: a major breakthrough in cancer research. Speaking Part 3: phát minh quan trọng nhất thế kỷ.", f: "breakthrough (n), break through (phrasal v); milestone, advance, discovery (đồng nghĩa)" },
  "obsolete": { m: "Liên tưởng 'ob-so-old': quá cũ đến mức không ai dùng nữa → lỗi thời.", e: "Sai: become obsolescence → Đúng: become obsolete. Sai: an obsolete person → Đúng: dùng cho đồ vật, công nghệ, kỹ năng.", u: "Writing Task 2: 'Some jobs will become obsolete due to AI'. Speaking Part 3: thiết bị cũ như DVD, máy fax.", f: "obsolete (adj), obsolescence (n), obsolescent (adj); outdated, out of date (đồng nghĩa)" },
  "artificial": { m: "art (nghệ thuật, tay nghề) + -ficial (làm ra) → do bàn tay con người làm ra → nhân tạo.", e: "Sai: artificial intelligent → Đúng: artificial intelligence. Sai: artificial flowers is fake → Đúng: artificial flowers are not real.", u: "Writing Task 2: artificial intelligence (AI), artificial sweeteners. Speaking Part 3: 'Will AI replace teachers?'.", f: "artificial (adj), artificially (adv), artifice (n); man-made, synthetic, natural (trái nghĩa)" },
  "surveillance": { m: "sur- (trên) + veiller (canh, Pháp) → canh chừng từ trên cao → sự giám sát, theo dõi.", e: "Sai: surveillant cameras → Đúng: surveillance cameras / CCTV. Sai: under the surveillance of → thường nói: under surveillance.", u: "Writing Task 2 công nghệ/tội phạm: CCTV surveillance và quyền riêng tư. Speaking Part 3: 'Is mass surveillance justified?'.", f: "surveillance (n), survey (v/n, khác nghĩa), monitor (v), CCTV (n); under surveillance" },
  "cutting-edge": { m: "Hình ảnh: lưỡi dao (cutting edge) là phần sắc nhất, đi đầu → công nghệ đi đầu, tiên tiến nhất.", e: "Sai: cutting edge technology không gạch nối khi đứng trước danh từ → Đúng: cutting-edge technology. Sai: very cutting-edge.", u: "Speaking Part 2/3: mô tả thiết bị hiện đại, 'cutting-edge medical equipment'. Writing Task 2: đầu tư vào nghiên cứu.", f: "cutting-edge (adj), the cutting edge (n); state-of-the-art, advanced, high-tech (đồng nghĩa)" },
  "privacy": { m: "private (riêng tư) → privacy: khoảng không gian chỉ của riêng mình, người khác không xen vào.", e: "Sai: invade my private → Đúng: invade my privacy. Sai: privacies of users → Đúng: users' privacy (không đếm được).", u: "Writing Task 2: social media, data protection, invasion of privacy. Speaking Part 3: 'Do celebrities deserve privacy?'.", f: "privacy (n), private (adj), privately (adv); data protection, invasion of privacy" },
  "addictive": { m: "addict (người nghiện) + -ive → có tính làm người ta thành người nghiện → gây nghiện.", e: "Sai: I am addictive to games → Đúng: I am addicted to games. 'Addictive' mô tả thứ gây nghiện: Games are addictive.", u: "Speaking Part 1/3: smartphones, social media, video games are highly addictive. Writing Task 2: tác hại công nghệ với trẻ em.", f: "addictive (adj), addicted (adj), addiction (n), addict (n); be hooked on (thân mật)" },
  "user-friendly": { m: "Hình ảnh: thiết bị 'thân thiện' như bạn bè với người dùng → dễ sử dụng, không cần hướng dẫn.", e: "Sai: friendly-user app → Đúng: a user-friendly app. Sai: user friendly (thiếu gạch nối trước danh từ).", u: "Speaking Part 2: mô tả app hoặc website bạn hay dùng. Writing Task 2: công nghệ giúp người già khi giao diện user-friendly.", f: "user-friendly (adj), user (n), friendliness (n); easy to use, intuitive (đồng nghĩa)" },
  "obesity": { m: "Liên tưởng 'obese' đọc gần 'ô-bi' tròn vo → người tròn quá mức → béo phì.", e: "Sai: obesity people → Đúng: obese people. Sai: the obesity are rising → Đúng: obesity is rising / obesity rates are rising.", u: "Writing Task 2 sức khỏe: childhood obesity, fast food, sugar tax. Task 1: biểu đồ tỷ lệ béo phì theo năm.", f: "obesity (n), obese (adj), overweight (adj); childhood obesity, obesity rate" },
  "sedentary": { m: "Gốc Latin 'sedere' = ngồi (như 'sediment') → lối sống ngồi nhiều → ít vận động.", e: "Sai: sedentary lifestyles is → Đúng: a sedentary lifestyle is. Sai: lifestyle sedentary → Đúng: sedentary lifestyle.", u: "Writing Task 2: 'Office workers lead a sedentary lifestyle, causing health problems'. Speaking Part 3: thói quen hiện đại.", f: "sedentary (adj); inactive, desk-bound (đồng nghĩa), active (trái nghĩa)" },
  "epidemic": { m: "epi- (trên) + demos (dân chúng) → bệnh lan trên đầu dân chúng → dịch bệnh.", e: "Sai: epidemic of disease spread → Đúng: an epidemic spread / the disease became an epidemic. Phân biệt pandemic (toàn cầu).", u: "Writing Task 2: obesity epidemic, flu epidemic. Speaking Part 3: phòng chống dịch, vai trò của chính phủ.", f: "epidemic (n/adj), pandemic (n), endemic (adj), epidemiology (n), outbreak (n)" },
  "vaccine": { m: "Gốc Latin 'vacca' = con bò; vắc-xin đầu tiên từ bệnh đậu bò → vaccine.", e: "Sai: inject vaccine for children → Đúng: vaccinate children / give children vaccines. Sai: vaccin → Đúng: vaccine.", u: "Writing Task 2 y tế: 'Should vaccination be compulsory?'. Speaking Part 3: chiến dịch tiêm chủng, sức khỏe cộng đồng.", f: "vaccine (n), vaccinate (v), vaccination (n), unvaccinated (adj); immunise, jab (thân mật)" },
  "well-being": { m: "well (tốt) + being (trạng thái tồn tại) → trạng thái sống tốt cả thân lẫn tâm → khỏe mạnh, hạnh phúc.", e: "Sai: wellbeings of people → Đúng: people's well-being (không đếm được). Sai: improve well-being of them → Đúng: improve their well-being.", u: "Writing Task 2: mental well-being, employee well-being. Speaking Part 3: 'Does money improve well-being?'.", f: "well-being/wellbeing (n), wellness (n), welfare (n); health, happiness" },
  "life expectancy": { m: "life (đời sống) + expectancy (điều được kỳ vọng) → số năm sống được kỳ vọng → tuổi thọ trung bình.", e: "Sai: life expectancy is longer → Đúng: life expectancy is higher. Sai: life expectation → Đúng: life expectancy.", u: "Writing Task 1: biểu đồ tuổi thọ theo quốc gia. Task 2: 'Rising life expectancy puts pressure on pension systems'.", f: "life expectancy (n), expect (v), expectancy (n); lifespan, longevity (đồng nghĩa)" },
  "prevention": { m: "pre- (trước) + vent (đến) → chặn trước khi nó đến → phòng ngừa. 'Prevention is better than cure'.", e: "Sai: prevention to diseases → Đúng: prevention of diseases. Sai: prevent people do → Đúng: prevent people from doing.", u: "Writing Task 2: crime prevention, disease prevention. Speaking Part 3: 'Prevention is better than cure' khi bàn chi tiêu y tế.", f: "prevention (n), prevent (v), preventive/preventative (adj), preventable (adj)" },
  "redundancy": { m: "redundant = thừa ra → nhân viên bị coi là thừa → bị cắt giảm, mất việc.", e: "Sai: I was redundancy → Đúng: I was made redundant. Sai: make redundancy to staff → Đúng: make staff redundant.", u: "Writing Task 2 việc làm: automation causing redundancies. Speaking Part 3: job security, redundancy pay (tiền trợ cấp thôi việc).", f: "redundancy (n), redundant (adj); lay off (v), layoff (n), dismissal (n)" },
  "inequality": { m: "in- (không) + equal (bằng nhau) + -ity → sự không bằng nhau → bất bình đẳng.", e: "Sai: inequality between rich and poor are growing → Đúng: inequality between rich and poor is growing. Sai: unequality → Đúng: inequality.", u: "Writing Task 2: income inequality, gender inequality, wealth gap. Speaking Part 3: giải pháp thu hẹp khoảng cách giàu nghèo.", f: "inequality (n), equality (n), unequal (adj), equal (adj), inequity (n)" },
  "generation gap": { m: "Hình ảnh: một khe hở (gap) ngăn hai thế hệ ông bà, con cháu → khác biệt quan điểm.", e: "Sai: the gap of generation → Đúng: the generation gap. Sai: generation gap between me with my parents → Đúng: between me and my parents.", u: "Speaking Part 3 gia đình: bất đồng về công nghệ, âm nhạc. Writing Task 2: bridge/widen the generation gap.", f: "generation gap (n), generation (n), generational (adj); bridge the gap" },
  "ageing population": { m: "ageing (đang già đi) + population (dân số) → tỷ lệ người già tăng dần → dân số già hóa.", e: "Sai: aging people population → Đúng: an ageing population. Sai: population is old → Đúng: the population is ageing.", u: "Writing Task 2: tác động của ageing population lên lương hưu, y tế. Task 1: biểu đồ cơ cấu tuổi.", f: "ageing population (n), age (v), aged (adj), elderly (adj/n); aging (Mỹ)" },
  "discrimination": { m: "discriminate = tách biệt, phân loại → đối xử khác vì giới, màu da → phân biệt đối xử.", e: "Sai: discriminate with women → Đúng: discriminate against women. Sai: discrimination to minorities → Đúng: discrimination against minorities.", u: "Writing Task 2: gender/racial/age discrimination in the workplace. Speaking Part 3: luật chống phân biệt đối xử.", f: "discrimination (n), discriminate (v), discriminatory (adj); prejudice, bias (đồng nghĩa)" },
  "upbringing": { m: "Hình ảnh: bring up (nuôi lớn) đảo thành up-bringing → quá trình nuôi dạy một đứa trẻ.", e: "Sai: my parents upbringing me → Đúng: my parents brought me up. Sai: a strict bring-up → Đúng: a strict upbringing.", u: "Speaking Part 2/3: ảnh hưởng của cách nuôi dạy tới tính cách. Writing Task 2: parents vs schools in a child's upbringing.", f: "upbringing (n), bring up (phrasal v), raise (v); parenting, nurture (đồng nghĩa)" },
  "nuclear family": { m: "Hình ảnh: hạt nhân (nucleus) là lõi nhỏ → gia đình lõi gồm bố mẹ và con.", e: "Sai: core family → Đúng: nuclear family. Sai: I live in nuclear family → Đúng: I live in a nuclear family.", u: "Speaking Part 1/3: so sánh nuclear family với extended family (đại gia đình). Writing Task 2: thay đổi cấu trúc gia đình.", f: "nuclear family (n), extended family (n), single-parent family (n), household (n)" },
  "offender": { m: "offend = phạm, xúc phạm (luật) → offender = người phạm tội. Repeat offender = tái phạm.", e: "Sai: offenders who commits → Đúng: offenders who commit. Sai: young offend → Đúng: young offenders.", u: "Writing Task 2 tội phạm: punish or rehabilitate offenders, young offenders, repeat offenders. Speaking Part 3: hệ thống tư pháp.", f: "offender (n), offend (v), offence/offense (n), offensive (adj); criminal, convict" },
  "deterrent": { m: "de- (khỏi) + terr (làm sợ, như 'terror') → làm sợ để tránh xa → biện pháp răn đe.", e: "Sai: a deterrent for crime → Đúng: a deterrent to crime / against crime. Sai: deterrent people → Đúng: deter people from doing.", u: "Writing Task 2: 'Prison acts as a deterrent to potential criminals'. Speaking Part 3: hình phạt nặng có ngăn được tội phạm?", f: "deterrent (n/adj), deter (v), deterrence (n); act as a deterrent" },
  "rehabilitation": { m: "re- (lại) + habil (có khả năng, như 'ability') → làm cho có khả năng trở lại → phục hồi, cải tạo.", e: "Sai: rehabilitation for prisoners back to society → Đúng: rehabilitation of prisoners into society. Sai: rehabilitate prisoners to society.", u: "Writing Task 2: 'Prisons should focus on rehabilitation rather than punishment'. Còn dùng cho drug rehabilitation (cai nghiện).", f: "rehabilitation (n), rehabilitate (v), rehab (n, thân mật); reform (n/v)" },
  "custodial sentence": { m: "custody = sự giam giữ → custodial sentence = bản án phải vào nơi giam giữ → án tù.", e: "Sai: give custodial sentence for him → Đúng: give him a custodial sentence. Sai: custody sentence → Đúng: custodial sentence.", u: "Writing Task 2: so sánh custodial sentences với community service hoặc phạt tiền cho tội nhẹ.", f: "custodial sentence (n), custody (n), non-custodial (adj); prison sentence, imprisonment" },
  "juvenile": { m: "Gốc Latin 'juvenis' = trẻ (như 'junior') → thuộc lứa tuổi trẻ, chưa thành niên.", e: "Sai: juvenile crimes are increase → Đúng: juvenile crime is increasing. Sai: juvenile people → Đúng: juveniles / young people.", u: "Writing Task 2: juvenile delinquency, juvenile offenders. Speaking Part 3: nguyên nhân thanh thiếu niên phạm tội.", f: "juvenile (adj/n), juvenile delinquency (n); youth, adolescent, minor (đồng nghĩa)" },
  "crime rate": { m: "crime (tội phạm) + rate (tỷ lệ) → số vụ phạm tội trên dân số → tỷ lệ tội phạm.", e: "Sai: crime rate is more → Đúng: the crime rate is higher. Sai: the crimes rate → Đúng: the crime rate.", u: "Writing Task 1: biểu đồ crime rate theo năm. Task 2: 'Unemployment leads to a rise in the crime rate'.", f: "crime rate (n), crime (n), criminal (n/adj); criminality, crime figures" },
  "prosecute": { m: "pro- (đi tới) + sequi (đuổi theo) → đuổi theo kẻ phạm tội đến tòa → truy tố.", e: "Sai: prosecute him because of theft → Đúng: prosecute him for theft. Nhầm 'persecute' = ngược đãi.", u: "Writing Task 2: 'Companies that pollute should be prosecuted'. Speaking Part 3: luật pháp, xử lý tội phạm mạng.", f: "prosecute (v), prosecution (n), prosecutor (n); charge, sue (đồng nghĩa)" },
  "capital punishment": { m: "capital gốc 'caput' = cái đầu → hình phạt mất đầu → án tử hình.", e: "Sai: capital punish → Đúng: capital punishment. Sai: abolish the capital punishment → Đúng: abolish capital punishment (không mạo từ).", u: "Writing Task 2 tranh luận: 'Is capital punishment an effective deterrent?'. Speaking Part 3: quan điểm đạo đức.", f: "capital punishment (n), death penalty (n), execution (n), execute (v)" },
  "censorship": { m: "censor = người kiểm duyệt (thời La Mã) → censorship: việc cắt bỏ nội dung bị cấm.", e: "Sai: the government censorship the news → Đúng: the government censors the news. Sai: censor-ship → Đúng: censorship.", u: "Writing Task 2 truyền thông: internet censorship, freedom of speech. Speaking Part 3: có nên kiểm duyệt phim bạo lực?", f: "censorship (n), censor (v/n), censored (adj), uncensored (adj)" },
  "sensationalism": { m: "sensation (cảm giác mạnh) + -ism → kiểu đưa tin cố gây cảm giác sốc → giật gân.", e: "Sai: sensational news are popular → Đúng: sensational news is popular. Sai: sensationism → Đúng: sensationalism.", u: "Writing Task 2 truyền thông: 'Tabloids rely on sensationalism to sell copies'. Speaking Part 3: độ tin cậy của báo chí.", f: "sensationalism (n), sensational (adj), sensationalise (v), sensation (n); clickbait" },
  "tabloid": { m: "Gốc 'tablet' (viên nén) → báo khổ nhỏ, nén tin vắn gọn, giật gân → báo lá cải.", e: "Sai: read tabloid newspapers news → Đúng: read the tabloids / tabloid newspapers. Sai: a tabloid news → Đúng: a tabloid story.", u: "Speaking Part 3: so sánh tabloids với broadsheets (báo nghiêm túc). Writing Task 2: đời tư người nổi tiếng.", f: "tabloid (n/adj), broadsheet (n, trái nghĩa), gutter press (n), paparazzi (n)" },
  "persuasive": { m: "persuade (thuyết phục) + -ive → có khả năng thuyết phục người khác.", e: "Sai: persuasive me to buy → Đúng: persuade me to buy. Sai: a persuade argument → Đúng: a persuasive argument.", u: "Writing Task 2 quảng cáo: 'Adverts use persuasive techniques'. Speaking Part 2: mô tả một người có tài thuyết phục.", f: "persuasive (adj), persuade (v), persuasion (n), persuasively (adv); convincing" },
  "misinformation": { m: "mis- (sai) + information (thông tin) → thông tin sai, thường lan vô tình. Disinformation = cố ý.", e: "Sai: a misinformation / misinformations → Đúng: misinformation (không đếm được) / a piece of misinformation.", u: "Writing Task 2: misinformation spreads rapidly on social media. Speaking Part 3: cách kiểm chứng thông tin, fake news.", f: "misinformation (n), misinform (v), disinformation (n), fake news (n)" },
  "urbanisation": { m: "urban (thành thị) + -isation (quá trình biến thành) → quá trình biến nông thôn thành thành phố.", e: "Sai: urbanisation make cities crowded → Đúng: urbanisation makes cities crowded. Sai: urbanization of people → Đúng: urbanisation (quá trình chung).", u: "Writing Task 2: rapid urbanisation gây kẹt xe, ô nhiễm. Task 1: biểu đồ dân số thành thị và nông thôn.", f: "urbanisation/urbanization (n), urban (adj), urbanise (v), suburban (adj)" },
  "overcrowded": { m: "over- (quá mức) + crowded (đông người) → đông vượt sức chứa → quá đông đúc.", e: "Sai: the city is over crowd → Đúng: the city is overcrowded. Sai: overcrowded of people → Đúng: overcrowded with people.", u: "Speaking Part 1/3: overcrowded cities, buses, classrooms, prisons. Writing Task 2: hệ quả của dân số đô thị tăng.", f: "overcrowded (adj), overcrowding (n), crowded (adj), crowd (n); congested, packed" },
  "public transport": { m: "public (chung, công cộng) + transport (vận chuyển) → phương tiện ai cũng đi được: xe buýt, tàu điện.", e: "Sai: use public transports → Đúng: use public transport (không đếm được). Sai: go by the public transport → Đúng: go by public transport.", u: "Speaking Part 1: 'How do you get to work?'. Writing Task 2: đầu tư public transport để giảm tắc đường và khí thải.", f: "public transport (n), public transportation (Mỹ), commute (v), commuter (n)" },
  "housing": { m: "house (nhà) + -ing → nói chung về nhà ở cho người dân, không phải một ngôi nhà.", e: "Sai: a cheap housing / housings → Đúng: cheap housing (không đếm được). Sai: housing price → Đúng: house prices / housing costs.", u: "Writing Task 2: affordable housing, housing shortage ở thành phố lớn. Speaking Part 3: giá nhà cho người trẻ.", f: "housing (n), house (n/v), household (n), accommodation (n); affordable housing" },
  "sprawl": { m: "Hình ảnh: người nằm dang tay chân (sprawl) ra khắp ghế → thành phố lan rộng lộn xộn.", e: "Sai: city sprawling (dùng như danh từ) → Đúng: urban sprawl. Sai: the sprawl are bad → Đúng: sprawl is bad.", u: "Writing Task 2 đô thị: 'Urban sprawl destroys farmland and increases car dependency'. Speaking Part 3: quy hoạch thành phố.", f: "sprawl (n/v), sprawling (adj), urban sprawl (n); suburbanisation (n)" },
  "heritage": { m: "herit- (thừa kế, như 'inherit') → những gì ta thừa kế từ tổ tiên → di sản.", e: "Sai: heritages of Vietnam → Đúng: Vietnam's heritage (thường không đếm được). Sai: a world heritage → Đúng: a World Heritage Site.", u: "Speaking Part 2: mô tả một di tích lịch sử. Writing Task 2: preserve cultural heritage vs phát triển hiện đại.", f: "heritage (n), inherit (v), inheritance (n), heir (n); legacy, tradition" },
  "ecotourism": { m: "eco- (sinh thái) + tourism (du lịch) → du lịch tôn trọng thiên nhiên, hỗ trợ cộng đồng địa phương.", e: "Sai: eco tourism → Đúng: ecotourism (một từ). Sai: go ecotourism → Đúng: go on an eco-tour / try ecotourism.", u: "Writing Task 2: lợi ích và rủi ro của ecotourism với môi trường. Speaking Part 2: kể chuyến đi thiên nhiên.", f: "ecotourism (n), ecotourist (n), eco-friendly (adj); sustainable tourism, green travel" },
  "landmark": { m: "land (vùng đất) + mark (dấu mốc) → dấu mốc dễ nhận ra của một vùng → địa danh nổi tiếng.", e: "Sai: famous landmark place → Đúng: a famous landmark. Sai: visit landmarks of Paris → Đúng: visit the landmarks in Paris.", u: "Speaking Part 2: mô tả một landmark ở thành phố bạn. Writing Task 1 bản đồ: vị trí các công trình.", f: "landmark (n/adj), landmark decision (n); monument, attraction, sight (đồng nghĩa)" },
  "souvenir": { m: "Gốc Pháp 'souvenir' = nhớ lại → món đồ mua để nhớ chuyến đi → quà lưu niệm.", e: "Sai: buy souvenir for my friend → Đúng: buy a souvenir for my friend. Sai: souvenir of Japan's → Đúng: a souvenir from Japan.", u: "Speaking Part 1/2: 'Do you buy souvenirs when travelling?'; kể món quà lưu niệm đáng nhớ. Từ liên quan: souvenir shop.", f: "souvenir (n), memento (n), keepsake (n); souvenir shop" },
  "globalisation": { m: "global (toàn cầu) + -isation (quá trình) → quá trình các nước kết nối thành một thị trường chung.", e: "Sai: globalisation make countries similar → Đúng: globalisation makes countries more similar. Sai: the globalisation → thường không cần 'the'.", u: "Writing Task 2: tác động của globalisation lên văn hóa địa phương, việc làm. Speaking Part 3: thương hiệu toàn cầu.", f: "globalisation/globalization (n), global (adj), globalise (v), globally (adv)" },
  "plummet": { m: "Gốc 'plumb' = quả dọi chì rơi thẳng xuống → giảm mạnh, lao dốc.", e: "Sai: plummeted down sharply → Đúng: plummeted (đã hàm nghĩa mạnh). Sai: plumet → Đúng: plummet, plummeted.", u: "Writing Task 1: 'Sales plummeted from 80% to 20% in 2010'. Tránh lặp 'decrease' trong mô tả biểu đồ.", f: "plummet (v/n); plunge, nosedive, collapse (đồng nghĩa), soar (trái nghĩa)" },
  "surge": { m: "Hình ảnh: con sóng (surge) bất ngờ dâng cao → sự tăng vọt đột ngột.", e: "Sai: a surge of 20% → Đúng: a surge in sales of 20%. Sai: surge up quickly → Đúng: surge (đã mang nghĩa nhanh).", u: "Writing Task 1: 'There was a surge in demand in 2015'. Task 2: surge in tourism, surge in prices.", f: "surge (n/v); soar, rocket, jump, spike (đồng nghĩa), plummet (trái nghĩa)" },
  "plateau": { m: "Hình ảnh: cao nguyên (plateau) là vùng cao bằng phẳng → số liệu tăng rồi đi ngang.", e: "Sai: plateaued at stable level → Đúng: plateaued at around 50%. Sai: reached to a plateau → Đúng: reached a plateau.", u: "Writing Task 1: 'The figure rose steadily before plateauing at 60%'. Đa dạng từ thay cho 'remain stable'.", f: "plateau (v/n), plateaus/plateaux (pl); level off, stabilise, remain steady" },
  "gradual": { m: "grad- (bước, như 'grade') → đi từng bước nhỏ → từ từ, dần dần.", e: "Sai: increased gradual → Đúng: increased gradually. Sai: a gradually rise → Đúng: a gradual rise.", u: "Writing Task 1: 'a gradual increase/decline'. Task 2: 'gradual change in attitudes'. Đối lập với sharp, dramatic.", f: "gradual (adj), gradually (adv); steady, slight, sharp (trái nghĩa)" },
  "overtake": { m: "over (vượt lên) + take (lấy) → chạy lên giành vị trí trước → vượt qua.", e: "Sai: overtook to coal → Đúng: overtook coal. Sai: overtaked → Đúng: overtook (quá khứ), overtaken (phân từ).", u: "Writing Task 1: 'By 2020, solar power had overtaken coal as the main source'. Diễn tả hai đường cắt nhau.", f: "overtake (v), overtook, overtaken; surpass, exceed, outstrip (đồng nghĩa)" },
  "detrimental": { m: "Gốc Latin 'detrimentum' = sự mài mòn, hao tổn → gây tổn hại dần dần → có hại.", e: "Sai: detrimental for health → Đúng: detrimental to health. Sai: it detriments → Đúng: it is detrimental / it harms.", u: "Writing Task 2: 'Excessive screen time is detrimental to children's development'. Thay cho 'bad for' để học thuật hơn.", f: "detrimental (adj), detriment (n), detrimentally (adv); harmful, damaging, beneficial (trái nghĩa)" },
  "alleviate": { m: "levi- = nhẹ (như 'levitate', 'lever') → làm cho nhẹ bớt gánh nặng → làm giảm bớt.", e: "Sai: alleviate for poverty → Đúng: alleviate poverty. Sai: alleviate the happiness → chỉ dùng với vấn đề, nỗi đau.", u: "Writing Task 2 (giải pháp): alleviate poverty, traffic congestion, pressure on hospitals. Speaking Part 3: giảm căng thẳng.", f: "alleviate (v), alleviation (n); ease, relieve, reduce (đồng nghĩa)" },
  "mitigate": { m: "mitis = mềm (Latin) → làm cho mềm, dịu tác động xấu → giảm nhẹ hậu quả.", e: "Sai: mitigate climate change completely → mitigate chỉ là giảm bớt. Sai: militate → Đúng: mitigate the effects.", u: "Writing Task 2: 'mitigate the impact of climate change', 'mitigate risks'. Thay cho 'reduce' ở phần giải pháp.", f: "mitigate (v), mitigation (n), mitigating (adj); lessen, minimise" },
  "prioritise": { m: "prior (trước) + -itise → đặt việc gì lên trước hết → ưu tiên.", e: "Sai: prioritise on education → Đúng: prioritise education. Sai: give priority education → Đúng: give priority to education.", u: "Writing Task 2: 'Governments should prioritise healthcare over space exploration'. Speaking Part 3: cân bằng công việc.", f: "prioritise/prioritize (v), priority (n), prior (adj); put first, focus on" },
  "masterpiece": { m: "master (bậc thầy) + piece (tác phẩm) → tác phẩm của bậc thầy → kiệt tác.", e: "Sai: master piece → Đúng: masterpiece (một từ). Sai: a masterpiece of Picasso's → Đúng: one of Picasso's masterpieces.", u: "Speaking Part 2: mô tả một bức tranh, bộ phim hay cuốn sách bạn yêu thích. Writing Task 2: nghệ thuật và bảo tàng.", f: "masterpiece (n), masterwork (n), master (n/v), masterful (adj)" },
  "artefact": { m: "arte (bằng tay nghề) + fact (làm ra) → đồ vật con người làm ra thời xưa → hiện vật.", e: "Sai: museum has many artefact → Đúng: many artefacts. Lưu ý: artefact (Anh) / artifact (Mỹ) đều đúng.", u: "Speaking Part 2/3: kể chuyến tham quan bảo tàng. Writing Task 2: 'Should artefacts be returned to their country of origin?'.", f: "artefact/artifact (n); relic, antique, exhibit (đồng nghĩa)" },
  "aesthetic": { m: "Gốc Hy Lạp 'aisthesis' = cảm nhận → cảm nhận cái đẹp → thẩm mỹ. Đọc /esˈθetɪk/.", e: "Sai: aesthetic value of a building is look nice → Đúng: the building has aesthetic value. Sai: esthetic (Mỹ, ít dùng IELTS).", u: "Writing Task 2 kiến trúc/nghệ thuật: aesthetic appeal vs function. Speaking Part 3: 'Is aesthetic design important?'.", f: "aesthetic (adj/n), aesthetics (n), aesthetically (adv); artistic, visual appeal" },
  "indigenous": { m: "indi- (trong) + gen (sinh ra) → sinh ra ngay tại nơi đó → bản địa.", e: "Sai: indigenous with Australia → Đúng: indigenous to Australia. Sai: indigenous peoples' culture are → Đúng: culture is.", u: "Writing Task 2: protect indigenous cultures, languages. Speaking Part 3: ảnh hưởng của toàn cầu hóa với cộng đồng bản địa.", f: "indigenous (adj); native, aboriginal, local (đồng nghĩa)" },
  "folklore": { m: "folk (dân gian) + lore (tri thức truyền miệng) → truyện, phong tục dân gian truyền đời.", e: "Sai: folklores of Vietnam → Đúng: Vietnamese folklore (không đếm được). Sai: a folklore → Đúng: a folk tale.", u: "Speaking Part 2: kể một câu chuyện dân gian thời thơ ấu. Writing Task 2: giữ gìn văn hóa truyền thống.", f: "folklore (n), folk (adj/n), folk tale (n), legend (n), myth (n)" },
  "craftsmanship": { m: "craftsman (thợ thủ công) + -ship (phẩm chất) → phẩm chất tay nghề của người thợ.", e: "Sai: craftmanship → Đúng: craftsmanship (có 's'). Sai: a good craftsmanships → Đúng: fine craftsmanship.", u: "Speaking Part 2: mô tả đồ thủ công, làng nghề. Writing Task 2: đồ thủ công vs sản xuất hàng loạt.", f: "craftsmanship (n), craftsman (n), craft (n/v), crafty (adj, nghĩa khác: xảo quyệt)" },
  "curator": { m: "cur- (chăm sóc, như 'cure') → người chăm sóc, sắp xếp hiện vật bảo tàng.", e: "Sai: museum manager curates (nói chung chung) → Đúng: the curator. Sai: curater → Đúng: curator.", u: "Speaking Part 3 bảo tàng/nghệ thuật: vai trò curator. Còn dùng mở rộng: content curator trên mạng.", f: "curator (n), curate (v), curation (n), curatorial (adj)" },
  "performing arts": { m: "performing (biểu diễn) + arts (nghệ thuật) → nghệ thuật trình diễn trực tiếp: kịch, múa, nhạc.", e: "Sai: perform arts → Đúng: performing arts. Sai: the performing art is → Đúng: the performing arts are.", u: "Writing Task 2: 'Should governments fund the performing arts?'. Speaking Part 1/3: đi xem kịch, hòa nhạc.", f: "performing arts (n), performance (n), perform (v); visual arts, fine arts" },
  "cultural identity": { m: "cultural (văn hóa) + identity (bản thân là ai) → cái làm nên 'mình là ai' về văn hóa.", e: "Sai: culture identity → Đúng: cultural identity. Sai: lose our identity culture → Đúng: lose our cultural identity.", u: "Writing Task 2: toàn cầu hóa đe dọa cultural identity. Speaking Part 3: ngôn ngữ, lễ hội giữ bản sắc.", f: "cultural identity (n), identity (n), identify (v), national identity (n)" },
  "assimilate": { m: "as- (về phía) + simil (giống, như 'similar') → trở nên giống cộng đồng mới → hòa nhập, đồng hóa.", e: "Sai: assimilate with new culture → Đúng: assimilate into a new culture. Sai: assimilate knowledges → Đúng: assimilate knowledge.", u: "Writing Task 2 nhập cư: 'Immigrants should assimilate into the local culture'. Speaking Part 3: du học, hòa nhập.", f: "assimilate (v), assimilation (n); integrate, adapt (đồng nghĩa)" },
  "stamina": { m: "Gốc Latin 'stamen' = sợi chỉ sự sống → sợi sức lực kéo dài → sức bền.", e: "Sai: have a good staminas → Đúng: have good stamina (không đếm được). Sai: increase my stamina power.", u: "Speaking Part 1/2: chạy bộ, bơi giúp build stamina. Writing Task 2: lợi ích thể thao với sức khỏe.", f: "stamina (n); endurance, staying power, energy (đồng nghĩa)" },
  "sportsmanship": { m: "sportsman (vận động viên) + -ship (phẩm chất) → phẩm chất đẹp của người chơi thể thao: fair play.", e: "Sai: sportmanship → Đúng: sportsmanship. Sai: show good sport spirit → Đúng: show good sportsmanship.", u: "Writing Task 2: thể thao dạy trẻ em sportsmanship. Speaking Part 2: mô tả vận động viên bạn ngưỡng mộ.", f: "sportsmanship (n), sportsman (n), sporting (adj); fair play, sportsmanlike (adj)" },
  "doping": { m: "dope = thuốc kích thích (lóng) → doping: dùng chất cấm để tăng thành tích.", e: "Sai: athletes doping drugs → Đúng: athletes use performance-enhancing drugs. Sai: doping scandals is → Đúng: a doping scandal is.", u: "Writing Task 2 thể thao: doping scandals, drug testing, công bằng thi đấu. Speaking Part 3: thể thao chuyên nghiệp.", f: "doping (n), dope (n/v), drug test (n); performance-enhancing drugs" },
  "sponsorship": { m: "sponsor (nhà tài trợ) + -ship → mối quan hệ tài trợ: đưa tiền đổi lấy quảng cáo.", e: "Sai: sponsorship for team by company → Đúng: corporate sponsorship of the team. Sai: sponsor money → Đúng: sponsorship money.", u: "Writing Task 2: sponsorship của hãng đồ uống, thuốc lá cho thể thao. Speaking Part 3: thương mại hóa thể thao.", f: "sponsorship (n), sponsor (n/v), sponsored (adj); funding, backing" },
  "endurance": { m: "endure = chịu đựng lâu (en- + dur 'kéo dài', như 'during') → sức chịu đựng.", e: "Sai: endurance sport like running are → Đúng: endurance sports like running are. Sai: endurable → nghĩa là 'chịu được'.", u: "Speaking Part 2: kể một hoạt động thử thách sức chịu đựng (marathon). Writing Task 2: tinh thần kiên trì.", f: "endurance (n), endure (v), enduring (adj), durable (adj); stamina, perseverance" },
  "extreme sports": { m: "extreme (cực độ) + sports → môn thể thao rủi ro cao: nhảy dù, leo núi, lướt sóng.", e: "Sai: play extreme sports → Đúng: do/take part in extreme sports. Sai: extremely sports → Đúng: extreme sports.", u: "Speaking Part 1/3: 'Would you try extreme sports?'. Writing Task 2: có nên cấm thể thao nguy hiểm?", f: "extreme sports (n), adrenaline (n), thrill-seeker (n); adventure sports" },
  "pastime": { m: "pass (trôi qua) + time (thời gian) → việc làm cho thời gian trôi vui → thú tiêu khiển.", e: "Sai: passtime → Đúng: pastime. Sai: my pastime is play chess → Đúng: my favourite pastime is playing chess.", u: "Speaking Part 1: 'What do you do in your free time?' – dùng pastime thay cho hobby. Writing: national pastime.", f: "pastime (n); hobby, leisure activity, recreation (đồng nghĩa)" },
  "team spirit": { m: "team (đội) + spirit (tinh thần) → tinh thần cả đội cùng hướng về mục tiêu chung.", e: "Sai: teamwork spirit → Đúng: team spirit. Sai: have the team spirit → Đúng: have/show team spirit.", u: "Speaking Part 2/3: thể thao đồng đội, dự án nhóm. Writing Task 2: team sports build team spirit ở trẻ em.", f: "team spirit (n), teamwork (n), team player (n); camaraderie, cooperation" },
  "underdog": { m: "Hình ảnh: chú chó (dog) bị đè bên dưới (under) trong trận vật → kẻ yếu thế ít ai tin thắng.", e: "Sai: the underdog team won easily (không hợp lý) → Đúng: the underdogs won against all odds. Sai: under dog → Đúng: underdog.", u: "Speaking Part 2: kể một trận đấu mà đội yếu thế lội ngược dòng. Writing: support the underdog.", f: "underdog (n), favourite (n, trái nghĩa); against all odds, dark horse" },
  "rivalry": { m: "rival (đối thủ) gốc Latin 'rivus' = con suối: hai làng tranh nhau một dòng suối → kình địch.", e: "Sai: rivalry with each others → Đúng: rivalry between the two teams. Sai: rival relationship → Đúng: rivalry.", u: "Speaking Part 2/3: rivalry giữa hai câu lạc bộ, anh chị em. Writing Task 2: cạnh tranh lành mạnh.", f: "rivalry (n), rival (n/v/adj), unrivalled (adj); competition, opponent" },
  "findings": { m: "find (tìm thấy) + -ings → những điều tìm thấy được sau nghiên cứu → kết quả nghiên cứu.", e: "Sai: the finding show → Đúng: the findings show (thường số nhiều). Sai: findings about the research → Đúng: research findings.", u: "Writing Task 2: 'Recent findings suggest that...'. Speaking Part 3: báo cáo khoa học, research findings.", f: "findings (n pl), find (v), finding (n); results, conclusions, outcome" },
  "methodology": { m: "method (phương pháp) + -ology (môn học) → hệ thống các phương pháp dùng trong nghiên cứu.", e: "Sai: methodology to do research → Đúng: research methodology. Dùng 'method' cho một cách cụ thể, 'methodology' cho cả hệ thống.", u: "Speaking Part 3 khoa học/học thuật: phương pháp nghiên cứu. Writing Task 2: tranh luận độ tin cậy của nghiên cứu.", f: "methodology (n), method (n), methodical (adj), methodological (adj)" },
  "peer review": { m: "peer (người ngang hàng) + review (đánh giá) → chuyên gia cùng ngành đánh giá bài trước khi đăng.", e: "Sai: peer reviewed study (thiếu gạch nối trước danh từ) → Đúng: a peer-reviewed study. Sai: peers review → Đúng: peer review.", u: "Speaking Part 3/Writing Task 2 khoa học: độ tin cậy nghiên cứu, 'published in peer-reviewed journals'.", f: "peer review (n), peer-review (v), peer-reviewed (adj), peer (n)" },
  "cloning": { m: "clone gốc Hy Lạp 'klon' = cành giâm → tạo bản sao giống hệt từ một cá thể → nhân bản.", e: "Sai: clone of human are illegal → Đúng: human cloning is illegal. Sai: cloned (danh từ) → Đúng: a clone.", u: "Writing Task 2 khoa học/đạo đức: 'Should human cloning be allowed?'. Speaking Part 3: công nghệ gen.", f: "cloning (n), clone (n/v), cloned (adj); genetic engineering, replicate" },
  "ethical": { m: "ethic (đạo lý) + -al → liên quan tới đúng sai về đạo đức. Unethical = phi đạo đức.", e: "Sai: it is not ethic → Đúng: it is not ethical / it is unethical. Sai: ethical problems → nên nói: ethical issues/concerns.", u: "Writing Task 2: ethical issues of animal testing, AI, cloning. Speaking Part 3: ethical shopping, kinh doanh có đạo đức.", f: "ethical (adj), ethics (n), ethically (adv), unethical (adj); moral (đồng nghĩa)" },
  "replicate": { m: "re- (lại) + plic (gấp, như 'duplicate') → gấp lại làm bản nữa → lặp lại thí nghiệm, sao chép.", e: "Sai: replicate again → Đúng: replicate (đã có nghĩa 'lại'). Sai: the result was replicate → Đúng: the result was replicated.", u: "Speaking Part 3 khoa học: 'Results must be replicated by other scientists'. Writing Task 2: sao chép mô hình thành công.", f: "replicate (v), replication (n), replica (n); reproduce, duplicate, copy" },
  "funding": { m: "fund (quỹ tiền) + -ing → việc cấp tiền từ quỹ cho một dự án → kinh phí.", e: "Sai: a funding / fundings → Đúng: funding (không đếm được). Sai: funding to research → Đúng: funding for research.", u: "Writing Task 2: 'Should governments increase funding for scientific research or the arts?'. Speaking Part 3: cut/allocate funding.", f: "funding (n), fund (n/v), fundraising (n), underfunded (adj); financing, grant" },
  "pioneer": { m: "Gốc Pháp 'pionnier' = lính bộ đi mở đường → người đi đầu mở lối mới → tiên phong.", e: "Sai: a pioneer of space exploration field → Đúng: a pioneer in/of space exploration. Sai: pioneering person → nói: a pioneer.", u: "Speaking Part 2: mô tả nhà khoa học bạn ngưỡng mộ. Writing Task 2: 'pioneer new technologies'.", f: "pioneer (n/v), pioneering (adj); trailblazer, innovator, forerunner" },
  "rigorous": { m: "rigor = sự cứng nhắc, nghiêm (như 'rigid') → làm cực kỳ cẩn thận, chặt chẽ.", e: "Sai: rigorous with students → nên nói: strict with students. Dùng rigorous cho quy trình: rigorous testing.", u: "Writing Task 2: rigorous testing of new drugs, rigorous academic standards. Speaking Part 3: kỳ thi đầu vào.", f: "rigorous (adj), rigour/rigor (n), rigorously (adv); thorough, meticulous, strict" },
  "bureaucracy": { m: "bureau (bàn giấy, văn phòng) + -cracy (cai trị) → bộ máy cai trị bằng bàn giấy, thủ tục rườm rà.", e: "Sai: bureaucracy are slow → Đúng: bureaucracy is slow. Sai: bureacracy → Đúng: bureaucracy.", u: "Writing Task 2: 'cut red tape and reduce bureaucracy'. Speaking Part 3: thủ tục hành chính khi xin visa, mở doanh nghiệp.", f: "bureaucracy (n), bureaucrat (n), bureaucratic (adj); red tape, paperwork" },
  "corruption": { m: "cor- (hoàn toàn) + rupt (vỡ, như 'interrupt') → làm mục nát, hư hỏng → tham nhũng.", e: "Sai: corrupt is a problem → Đúng: corruption is a problem. Sai: fight against corruptions → Đúng: fight corruption.", u: "Writing Task 2 chính phủ: tackle corruption, transparency. Speaking Part 3: niềm tin vào chính trị gia.", f: "corruption (n), corrupt (adj/v), corruptible (adj); bribery (n), bribe (n/v)" },
  "taxation": { m: "tax (thuế) + -ation → việc và hệ thống đánh thuế của nhà nước.", e: "Sai: high taxations → Đúng: high taxation / high taxes. Sai: taxation on rich → Đúng: taxation of the rich.", u: "Writing Task 2: 'Higher taxation on sugary drinks and fuel'. Speaking Part 3: thuế và dịch vụ công.", f: "taxation (n), tax (n/v), taxpayer (n), taxable (adj), tax-free (adj)" },
  "parliament": { m: "parler = nói (Pháp) → nơi các đại biểu ngồi nói, tranh luận → quốc hội.", e: "Sai: parliment → Đúng: parliament (có 'a' câm). Sai: in the Parliament (Anh) → Đúng: in Parliament.", u: "Writing Task 2: 'Parliament should pass laws to protect...'. Speaking Part 3: hệ thống chính trị nước bạn.", f: "parliament (n), parliamentary (adj), MP (Member of Parliament); congress, legislature" },
  "sovereignty": { m: "sovereign = vua, người tối cao → sovereignty = quyền tối cao của một quốc gia → chủ quyền.", e: "Sai: sovereign of the sea (danh từ) → Đúng: sovereignty over the sea. Sai: soverignty → Đúng: sovereignty.", u: "Writing Task 2: toàn cầu hóa và national sovereignty. Speaking Part 3: quan hệ quốc tế, tổ chức quốc tế.", f: "sovereignty (n), sovereign (adj/n); independence, autonomy (đồng nghĩa)" },
  "diplomacy": { m: "diploma (văn bản gấp đôi, thư ủy nhiệm) → nghề mang thư ủy nhiệm giữa các nước → ngoại giao.", e: "Sai: diplomatic is important → Đúng: diplomacy is important. Sai: a diplomacy person → Đúng: a diplomat / a diplomatic person.", u: "Writing Task 2: giải quyết xung đột bằng diplomacy. Speaking Part 3: kỹ năng khéo léo trong giao tiếp.", f: "diplomacy (n), diplomat (n), diplomatic (adj), diplomatically (adv)" },
  "electorate": { m: "elect (bầu) + -orate (tập thể) → toàn bộ những người có quyền bầu cử → cử tri.", e: "Sai: the electorates votes → Đúng: the electorate votes / voters vote. Đây là danh từ tập hợp.", u: "Writing Task 2: chính trị, quyền bầu cử, giáo dục cử tri. Speaking Part 3: 'Should the voting age be lowered?'.", f: "electorate (n), elect (v), election (n), electoral (adj), voter (n)" },
  "accountable": { m: "account (giải trình sổ sách) + -able → có thể bị yêu cầu giải trình → chịu trách nhiệm.", e: "Sai: accountable with the public → Đúng: accountable to the public for their decisions. Sai: hold them accountability.", u: "Writing Task 2: 'Politicians/companies must be held accountable for...'. Speaking Part 3: trách nhiệm của lãnh đạo.", f: "accountable (adj), accountability (n); responsible, answerable; hold sb accountable" },
  "public spending": { m: "public (công) + spending (chi tiêu) → tiền nhà nước chi cho trường học, bệnh viện, đường sá.", e: "Sai: public spendings → Đúng: public spending (không đếm được). Sai: increase public spending for health → Đúng: on health.", u: "Writing Task 2: tranh luận ưu tiên public spending cho y tế hay quốc phòng. Task 1: biểu đồ ngân sách.", f: "public spending (n), government expenditure (n), budget (n), spend (v)" },
  "transparency": { m: "trans- (xuyên qua) + parent (hiện ra) → nhìn xuyên qua được, không giấu giếm → minh bạch.", e: "Sai: the government should transparency → Đúng: the government should be transparent / ensure transparency.", u: "Writing Task 2: transparency in government, business. Speaking Part 3: chống tham nhũng, công khai ngân sách.", f: "transparency (n), transparent (adj), transparently (adv); openness, accountability" },
  "referendum": { m: "refer = đưa đến → đưa vấn đề đến toàn dân quyết → trưng cầu dân ý.", e: "Sai: make a referendum → Đúng: hold a referendum on something. Số nhiều: referendums/referenda.", u: "Writing Task 2/Speaking Part 3: dân chủ trực tiếp, ví dụ Brexit referendum.", f: "referendum (n), referenda (pl); vote, ballot, plebiscite" },
  "interest rate": { m: "interest (tiền lãi) + rate (mức) → mức tiền lãi khi vay hoặc gửi → lãi suất.", e: "Sai: interest rate is up → nên nói: interest rates have risen. Sai: interesting rate → Đúng: interest rate.", u: "Writing Task 2 kinh tế: vay mua nhà, tiết kiệm. Speaking Part 3: 'Do young people save money?'.", f: "interest rate (n), interest (n), borrow (v), loan (n), mortgage (n)" },
  "economic growth": { m: "economic (thuộc kinh tế) + growth (sự lớn lên) → nền kinh tế lớn dần → tăng trưởng kinh tế.", e: "Sai: economical growth → Đúng: economic growth. 'Economical' = tiết kiệm. Sai: economy growth.", u: "Writing Task 2: economic growth vs environmental protection. Task 1: GDP growth theo năm.", f: "economic growth (n), economy (n), economic (adj), economical (adj, tiết kiệm), grow (v)" },
  "tariff": { m: "Gốc Ả Rập 'ta'rif' = bảng thông báo giá → bảng thuế đánh vào hàng nhập khẩu.", e: "Sai: tariff of imported goods → Đúng: tariffs on imported goods. Sai: tarif → Đúng: tariff.", u: "Writing Task 2: free trade vs protecting local industries bằng tariffs. Speaking Part 3: giá hàng nhập khẩu.", f: "tariff (n); import duty, customs duty, trade barrier, free trade" },
  "prosperity": { m: "prosper (phát đạt) → prosperity: trạng thái phát đạt, giàu mạnh → thịnh vượng.", e: "Sai: the prosperity country → Đúng: a prosperous country. Sai: bring prosperity for → Đúng: bring prosperity to the region.", u: "Writing Task 2: tourism brings prosperity to rural areas. Speaking Part 3: thịnh vượng kinh tế và hạnh phúc.", f: "prosperity (n), prosper (v), prosperous (adj); wealth, affluence" },
  "affluent": { m: "af- (về phía) + flu (chảy, như 'fluent') → tiền chảy vào dồi dào → giàu có.", e: "Sai: affluent of money → Đúng: affluent / wealthy. Sai: an affluence family → Đúng: an affluent family.", u: "Writing Task 2: affluent societies, consumerism. Speaking Part 3: so sánh vùng giàu nghèo trong thành phố.", f: "affluent (adj), affluence (n); wealthy, well-off, prosperous (đồng nghĩa)" },
  "stock market": { m: "stock (cổ phiếu) + market (chợ) → chợ mua bán cổ phiếu → thị trường chứng khoán.", e: "Sai: invest to stock market → Đúng: invest in the stock market. Sai: stocks market → Đúng: stock market.", u: "Speaking Part 3 tiền bạc: 'Is investing in the stock market risky?'. Writing Task 2: tài chính cá nhân.", f: "stock market (n), stock exchange (n), shares (n), stock (n), investor (n)" },
  "fossil fuel": { m: "fossil (hóa thạch) + fuel (nhiên liệu) → than, dầu hình thành từ sinh vật chết hàng triệu năm.", e: "Sai: fossil fuel is running out → thường: fossil fuels are running out. Sai: fossils fuels → Đúng: fossil fuels.", u: "Writing Task 2: reduce reliance on fossil fuels, switch to renewables. Task 1: nguồn năng lượng theo năm.", f: "fossil fuel (n), fossil (n); coal, oil, natural gas; renewable energy (đối lập)" },
  "wind turbine": { m: "wind (gió) + turbine (tua-bin quay) → cánh quạt khổng lồ quay nhờ gió tạo điện.", e: "Sai: wind turbin → Đúng: wind turbine. Sai: windmill (cối xay gió, cổ) khi nói máy phát điện hiện đại.", u: "Writing Task 1: quy trình sản xuất điện gió. Task 2/Speaking Part 3: wind farms ảnh hưởng cảnh quan.", f: "wind turbine (n), wind farm (n), wind power (n), turbine (n)" },
  "nuclear power": { m: "nuclear (hạt nhân) + power (điện năng) → điện tạo từ phân hạch hạt nhân nguyên tử.", e: "Sai: nuclear energy plant explode → Đúng: a nuclear power plant exploded. Sai: nucleus power → Đúng: nuclear power.", u: "Writing Task 2: ưu nhược điểm nuclear power: ít khí thải nhưng rủi ro và chất thải phóng xạ.", f: "nuclear power (n), nuclear energy (n), nuclear power station/plant (n), radioactive (adj)" },
  "carbon footprint": { m: "Hình ảnh: dấu chân (footprint) carbon mỗi người để lại trên Trái Đất → lượng khí thải mình gây ra.", e: "Sai: decrease carbon footprints of me → Đúng: reduce my carbon footprint. Sai: carbon foot print.", u: "Writing Task 2: đi máy bay, ăn thịt làm tăng carbon footprint. Speaking Part 3: thói quen sống xanh.", f: "carbon footprint (n), carbon emissions (n), carbon-neutral (adj), footprint (n)" },
  "grid": { m: "Hình ảnh: lưới ô vuông (grid) dây điện nối mọi nhà máy với mọi nhà → lưới điện.", e: "Sai: connect to grid → Đúng: connect to the grid / the national grid. Sai: off grid house → Đúng: an off-grid house.", u: "Writing Task 2/Speaking Part 3 năng lượng: đưa solar power vào national grid; sống off-grid.", f: "grid (n), national grid (n), power grid (n), off-grid (adj)" },
  "hydroelectric": { m: "hydro- (nước) + electric (điện) → điện tạo từ sức nước chảy qua đập → thủy điện.", e: "Sai: hydroelectric is cheap (thiếu danh từ) → Đúng: hydroelectric power is cheap. Sai: hydro-electricity dam.", u: "Writing Task 1: quy trình thủy điện. Task 2: lợi ích và tác hại của đập thủy điện với sông, làng mạc.", f: "hydroelectric (adj), hydroelectricity (n), hydropower (n), dam (n)" },
  "reserves": { m: "reserve (để dành) → reserves: lượng tài nguyên còn để dành dưới lòng đất → trữ lượng.", e: "Sai: oil reserve is running out → Đúng: oil reserves are running out. Sai: reservation (đặt chỗ) ≠ reserves.", u: "Writing Task 2: dwindling oil and gas reserves. Task 1: so sánh trữ lượng tài nguyên các nước.", f: "reserves (n pl), reserve (n/v), reservoir (n); stocks, supplies, deposits" },
  "insulation": { m: "insula = hòn đảo (Latin) → cô lập như ở đảo, ngăn nóng lạnh thoát ra → cách nhiệt.", e: "Sai: insulate (danh từ) → Đúng: insulation. Sai: house insulation bad → Đúng: the house is poorly insulated.", u: "Writing Task 2/Speaking Part 3: tiết kiệm năng lượng gia đình bằng loft insulation, double glazing.", f: "insulation (n), insulate (v), insulated (adj), insulator (n)" },
  "depletion": { m: "de- (lấy đi) + plete (đầy, như 'complete') → lấy đi đến hết → sự cạn kiệt.", e: "Sai: depletion of ozone layer → Đúng: depletion of the ozone layer. Sai: deplete of resources → Đúng: resource depletion.", u: "Writing Task 2: resource depletion, ozone depletion, fish stock depletion. Speaking Part 3: tương lai tài nguyên.", f: "depletion (n), deplete (v), depleted (adj); exhaustion, running out" },
  "biofuel": { m: "bio- (sinh vật) + fuel (nhiên liệu) → nhiên liệu từ cây trồng như ngô, mía.", e: "Sai: bio fuel → Đúng: biofuel. Sai: biofuels is clean → Đúng: biofuels are cleaner.", u: "Writing Task 2: biofuels vs food security (dùng đất nông nghiệp). Speaking Part 3: thay thế xăng dầu.", f: "biofuel (n), biodiesel (n), ethanol (n); fossil fuel (đối lập)" },
  "power station": { m: "power (điện năng) + station (trạm) → trạm lớn sản xuất điện → nhà máy điện.", e: "Sai: electric station → Đúng: power station / power plant. Sai: build power stations near city centre.", u: "Writing Task 1 quy trình/bản đồ: vị trí power station. Task 2: coal-fired power stations và ô nhiễm.", f: "power station (n), power plant (n), generate (v), generator (n)" },
  "energy-efficient": { m: "energy + efficient (hiệu quả) → làm được nhiều với ít điện → tiết kiệm năng lượng.", e: "Sai: energy-saving efficient → Đúng: energy-efficient. Sai: energy efficient lights (thiếu gạch nối trước danh từ).", u: "Writing Task 2: energy-efficient appliances, buildings. Speaking Part 3: cách gia đình tiết kiệm điện.", f: "energy-efficient (adj), energy efficiency (n), efficient (adj); energy-saving (adj)" },
  "decarbonise": { m: "de- (bỏ đi) + carbon + -ise → loại bỏ carbon khỏi nền kinh tế → khử carbon.", e: "Sai: decarbonise the carbon → thừa. Đúng: decarbonise the economy/transport sector.", u: "Writing Task 2 biến đổi khí hậu: 'Countries must decarbonise their energy systems by 2050'.", f: "decarbonise/decarbonize (v), decarbonisation (n); net zero, carbon-neutral" },
  "extinction": { m: "ex- (ra) + stinguere (dập tắt, như 'extinguish') → bị dập tắt hoàn toàn → tuyệt chủng.", e: "Sai: animals are extinction → Đúng: animals face extinction / are extinct. Sai: extinct of species → Đúng: extinction.", u: "Writing Task 2: 'Many species are on the brink of extinction'. Speaking Part 3: vai trò sở thú trong bảo tồn.", f: "extinction (n), extinct (adj); endangered (adj), die out (phrasal v)" },
  "ecosystem": { m: "eco- (nhà, môi trường) + system (hệ thống) → mọi sinh vật và môi trường tạo một hệ thống.", e: "Sai: eco system → Đúng: ecosystem. Sai: destroy ecosystem → Đúng: destroy the ecosystem / fragile ecosystems.", u: "Writing Task 2: tourism damages fragile ecosystems. Speaking Part 3: bảo vệ rạn san hô, rừng.", f: "ecosystem (n), ecology (n), ecological (adj), ecologist (n)" },
  "predator": { m: "Gốc Latin 'praeda' = chiến lợi phẩm (như 'prey') → loài đi săn chiến lợi phẩm → động vật săn mồi.", e: "Sai: predator eat preys → Đúng: predators eat prey. Sai: predatory (tính từ) dùng như danh từ.", u: "Writing Task 2: predators giữ cân bằng hệ sinh thái. Speaking Part 2: mô tả loài vật hoang dã.", f: "predator (n), predatory (adj), predation (n), prey (n, đối lập)" },
  "prey": { m: "Phát âm như 'pray' (cầu nguyện): con mồi chỉ biết cầu nguyện thoát khỏi kẻ săn.", e: "Sai: preys → Đúng: prey (thường không đếm được). Sai: pray on → Đúng: prey on smaller animals.", u: "Writing Task 2/Speaking Part 3: chuỗi thức ăn. Nghĩa bóng: fall prey to scams.", f: "prey (n/v), prey on (phrasal v), predator (n); fall prey to" },
  "poaching": { m: "poach = luộc trứng; kẻ săn trộm 'thò tay' lấy trộm thú như móc trứng khỏi tổ.", e: "Sai: poaching animals is legal → Đúng: poaching is illegal. Sai: poachers is → Đúng: poachers are.", u: "Writing Task 2: ivory poaching đe dọa voi, tê giác. Speaking Part 3: bảo vệ động vật hoang dã.", f: "poaching (n), poach (v), poacher (n); illegal hunting, wildlife trafficking" },
  "captivity": { m: "capt- (bắt, như 'capture') → bị bắt giữ, nhốt → sự nuôi nhốt.", e: "Sai: animals in captive → Đúng: animals in captivity. Sai: keep animals captivity → Đúng: keep animals in captivity.", u: "Writing Task 2: 'Should animals be kept in captivity in zoos?'. Speaking Part 3: rạp xiếc, công viên biển.", f: "captivity (n), captive (adj/n), capture (v/n), captor (n)" },
  "mammal": { m: "Gốc Latin 'mamma' = vú → loài nuôi con bằng sữa mẹ → động vật có vú.", e: "Sai: whale is a fish → Đúng: the whale is a mammal. Sai: mamal → Đúng: mammal.", u: "Speaking Part 2/3: mô tả loài động vật. Writing Task 1: bảng số loài thú bị đe dọa.", f: "mammal (n), mammalian (adj); reptile, amphibian, bird (nhóm khác)" },
  "marine": { m: "Gốc Latin 'mare' = biển (như 'submarine') → thuộc về biển.", e: "Sai: sea life marine → thừa. Đúng: marine life. Sai: marine pollutions → Đúng: marine pollution.", u: "Writing Task 2: plastic waste threatens marine life. Speaking Part 3: bảo vệ đại dương, marine reserves.", f: "marine (adj), maritime (adj), submarine (n), mariner (n); oceanic, aquatic" },
  "nocturnal": { m: "noct- = đêm (như 'nocturne', bản nhạc đêm) → hoạt động về đêm, trái với 'diurnal'.", e: "Sai: owls are night animal → Đúng: owls are nocturnal (animals). Sai: nocturnal at night → thừa.", u: "Speaking Part 1/2: 'I'm quite nocturnal – I study best at night'. Writing: hành vi động vật.", f: "nocturnal (adj), nocturnally (adv), diurnal (adj, trái nghĩa); night owl (người thức khuya)" },
  "food chain": { m: "Hình ảnh: chuỗi xích (chain), mỗi mắt xích là loài ăn loài trước nó → chuỗi thức ăn.", e: "Sai: in the top of food chain → Đúng: at the top of the food chain. Sai: chain of food.", u: "Writing Task 2: mất một loài phá vỡ food chain. Task 1 sơ đồ: mô tả chuỗi thức ăn.", f: "food chain (n), food web (n), predator, prey; ecosystem" },
  "animal welfare": { m: "welfare = sự sống tốt (well + fare) → đời sống tốt cho động vật → quyền lợi động vật.", e: "Sai: animal's welfares → Đúng: animal welfare (không đếm được). Phân biệt animal rights (quyền).", u: "Writing Task 2: animal welfare trong trang trại, sở thú, thí nghiệm. Speaking Part 3: ăn chay vì động vật.", f: "animal welfare (n), welfare (n), animal rights (n); cruelty, humane (adj)" },
  "vulnerable": { m: "vulner- = vết thương (Latin) → dễ bị thương, tổn hại.", e: "Sai: vulnerable with diseases → Đúng: vulnerable to diseases. Sai: vulnerability people → Đúng: vulnerable people.", u: "Writing Task 2: vulnerable species, vulnerable groups (người già, trẻ em). Speaking Part 3: bảo vệ người yếu thế.", f: "vulnerable (adj), vulnerability (n), invulnerable (adj); at risk, susceptible" },
  "fauna": { m: "Fauna – thần rừng La Mã chăm thú; Flora – nữ thần hoa → fauna = động vật, flora = thực vật.", e: "Sai: faunas of Vietnam → Đúng: the fauna of Vietnam. Sai: fauna and flowers → Đúng: flora and fauna.", u: "Writing Task 2/Speaking Part 3: rich flora and fauna của vườn quốc gia. Ngữ cảnh học thuật, ecotourism.", f: "fauna (n), flora (n); wildlife, flora and fauna, biodiversity" },
  "invasive": { m: "invade (xâm chiếm) + -ive → loài ngoại lai lấn chiếm môi trường của loài bản địa.", e: "Sai: invaded species → Đúng: invasive species. Sai: invasive to environment → Đúng: invasive in the local environment.", u: "Writing Task 2: invasive species threaten native wildlife. Y học: invasive surgery (phẫu thuật xâm lấn).", f: "invasive (adj), invade (v), invasion (n), invader (n); non-native, alien species" },
  "domesticated": { m: "domestic (thuộc nhà) → domesticated = được đưa vào sống trong nhà → thuần hóa.", e: "Sai: domestic animal (vật nuôi) khi muốn nói 'đã thuần hóa' → Đúng: domesticated. Sai: domesticate dogs is.", u: "Speaking Part 3: thú cưng, chăn nuôi. Writing Task 2: so sánh domesticated animals và wild animals.", f: "domesticated (adj), domesticate (v), domestication (n), domestic (adj); tame" },
  "hibernate": { m: "hibern- = mùa đông (Latin) → ngủ suốt mùa đông.", e: "Sai: bears hibernate in summer → Đúng: bears hibernate during winter. Sai: hybernate → Đúng: hibernate.", u: "Speaking Part 1 (thời tiết): 'In winter I just want to hibernate'. Writing: hành vi động vật.", f: "hibernate (v), hibernation (n); go into hibernation, dormant (adj)" },
  "rainforest": { m: "rain (mưa) + forest (rừng) → rừng mưa quanh năm, nóng ẩm → rừng mưa nhiệt đới.", e: "Sai: rain forests is disappearing → Đúng: rainforests are disappearing. Sai: tropical rain-forest.", u: "Writing Task 2: destruction of the Amazon rainforest, biodiversity. Speaking Part 3: phá rừng và khí hậu.", f: "rainforest (n), tropical (adj), jungle (n); deforestation, canopy" },
  "skyscraper": { m: "Hình ảnh: sky (bầu trời) + scraper (cái cào) → tòa nhà cao đến mức cào vào trời.", e: "Sai: sky scraper → Đúng: skyscraper. Sai: a skyscraper building → Đúng: a skyscraper (đã là tòa nhà).", u: "Speaking Part 2: mô tả tòa nhà nổi bật. Writing Task 2: skyscrapers giải quyết thiếu đất ở đô thị.", f: "skyscraper (n), high-rise (n/adj), tower block (n), skyline (n)" },
  "high-rise": { m: "high (cao) + rise (vươn lên) → tòa nhà vươn lên nhiều tầng → cao tầng.", e: "Sai: high rise building (thiếu gạch nối) → Đúng: high-rise building. Sai: high-rising → Đúng: high-rise.", u: "Writing Task 2: high-rise apartments vs nhà truyền thống. Task 1 bản đồ: 'High-rise flats replaced the park'.", f: "high-rise (adj/n), low-rise (adj), skyscraper (n), tower block (n)" },
  "facade": { m: "Gốc Pháp 'face' = khuôn mặt → mặt ngoài của tòa nhà. Nghĩa bóng: vẻ ngoài giả tạo.", e: "Sai: front facade of the building (thừa) → Đúng: the facade of the building. Đọc /fəˈsɑːd/, không phải 'fa-cây'.", u: "Speaking Part 2: mô tả kiến trúc. Writing Task 2: giữ facade cổ khi cải tạo. Nghĩa bóng: behind a facade of happiness.", f: "facade/façade (n); exterior, front (đồng nghĩa)" },
  "cramped": { m: "cramp = chuột rút, co quắp → phòng chật đến mức phải co người → chật chội.", e: "Sai: cramp apartment → Đúng: cramped apartment. Sai: cramped with people (đông người) → nên dùng: crowded.", u: "Speaking Part 1 (nhà ở): 'My flat is a bit cramped'. Writing Task 2: điều kiện sống ở đô thị.", f: "cramped (adj), cramp (n/v); poky, confined, spacious (trái nghĩa)" },
  "detached": { m: "de- (tách) + attach (gắn) → không gắn với nhà nào → nhà riêng biệt. Nghĩa khác: tách biệt, thờ ơ.", e: "Sai: a detach house → Đúng: a detached house. Phân biệt: semi-detached (chung một vách), terraced (dãy liền).", u: "Speaking Part 1/2 (nhà ở): 'I live in a detached house in the suburbs'. Writing Task 1: bản đồ khu dân cư.", f: "detached (adj), semi-detached (adj), detach (v), detachment (n), terraced (adj)" },
  "storey": { m: "Nhà cao tầng như cuốn truyện (story) chia chương → mỗi chương là một tầng. Anh: storey, Mỹ: story.", e: "Sai: a ten-storeys building → Đúng: a ten-storey building. Sai: storey (tầng) nhầm floor (sàn): on the fifth floor.", u: "Speaking Part 2/Writing Task 1: 'a 50-storey office block'. Dùng khi mô tả kích thước tòa nhà.", f: "storey/story (n), multi-storey (adj), floor (n), level (n)" },
  "dwelling": { m: "dwell = cư ngụ → dwelling = nơi người ta cư ngụ. Từ trang trọng cho 'home'.", e: "Sai: dwell in (danh từ) → Đúng: dwelling. Sai: dwellings place → Đúng: dwellings / places of residence.", u: "Writing Task 1/Task 2: thống kê số dwellings, loại nhà ở. Dùng trang trọng thay 'house' để đa dạng từ.", f: "dwelling (n), dwell (v), dweller (n), city-dweller (n); residence, abode" },
  "skyline": { m: "sky (trời) + line (đường) → đường viền các tòa nhà in lên nền trời.", e: "Sai: the sky line → Đúng: the skyline. Sai: skyline of the city is beautiful view → Đúng: the city's skyline is stunning.", u: "Speaking Part 2: mô tả thành phố bạn yêu thích. Writing Task 2: nhà cao tầng thay đổi skyline.", f: "skyline (n); cityscape, horizon (n), skyscraper (n)" },
  "restoration": { m: "restore = trả lại như cũ → restoration: làm cho công trình cũ trở lại như xưa → trùng tu.", e: "Sai: restoration of old building is expensive (thiếu mạo từ) → Đúng: the restoration of old buildings is expensive.", u: "Writing Task 2: chi tiền cho restoration of historic buildings. Speaking Part 2: kể một công trình được trùng tu.", f: "restoration (n), restore (v), restorative (adj); renovation, preservation" },
  "materialistic": { m: "material (vật chất) + -istic → đặt vật chất, của cải lên hàng đầu → thực dụng.", e: "Sai: materialism people → Đúng: materialistic people. Sai: materialistic with money → Đúng: obsessed with possessions.", u: "Writing Task 2: 'Society is becoming increasingly materialistic'. Speaking Part 3: quảng cáo và giá trị của giới trẻ.", f: "materialistic (adj), materialism (n), materialist (n), material (adj/n)" },
  "impulse buying": { m: "impulse = cú thúc bất chợt → mua vì cú thúc nhất thời, không định trước → mua sắm bốc đồng.", e: "Sai: impulsive buying → cũng đúng, nhưng phổ biến: impulse buying. Sai: buy by impulse → Đúng: buy on impulse.", u: "Writing Task 2/Speaking Part 3: quảng cáo, mua online gây impulse buying. Part 1: 'Are you a careful shopper?'.", f: "impulse buying (n), impulse buy (n), impulsive (adj), buy on impulse" },
  "brand loyalty": { m: "brand (thương hiệu) + loyalty (lòng trung thành) → luôn mua một hãng quen như người bạn chung thủy.", e: "Sai: loyalty brand → Đúng: brand loyalty. Sai: loyal with a brand → Đúng: loyal to a brand.", u: "Speaking Part 3 mua sắm: 'Do young people have brand loyalty?'. Writing Task 2: tác động quảng cáo.", f: "brand loyalty (n), loyal (adj), loyalty (n); brand-conscious (adj), loyal customer" },
  "e-commerce": { m: "e- (electronic, điện tử) + commerce (thương mại) → mua bán qua mạng.", e: "Sai: ecommerces → Đúng: e-commerce (không đếm được). Sai: e-commerce website is grow → Đúng: e-commerce is growing.", u: "Writing Task 2: e-commerce vs cửa hàng truyền thống. Speaking Part 1/3: thói quen mua sắm online.", f: "e-commerce (n), online shopping (n), commerce (n), commercial (adj)" },
  "splurge": { m: "Âm 'splurge' như tiếng tiền vung ra tung tóe → vung tiền mua đồ đắt tiền.", e: "Sai: splurge for a bag → Đúng: splurge on a bag. Sai: make a splurge money → Đúng: splurge money on...", u: "Speaking Part 1/2: 'I splurged on a new phone after getting my first salary'. Tự nhiên, ghi điểm từ vựng.", f: "splurge (v/n); treat oneself, blow money on (thân mật), save (trái nghĩa)" },
  "extravagant": { m: "extra- (ra ngoài) + vagant (đi lang thang) → tiêu xài vượt ra ngoài giới hạn → phung phí.", e: "Sai: an extravagance wedding → Đúng: an extravagant wedding. Sai: extravagant with spend → Đúng: extravagant spending.", u: "Writing Task 2: extravagant weddings, lifestyles. Speaking Part 2: kể một lần tiêu tiền quá tay.", f: "extravagant (adj), extravagance (n), extravagantly (adv); lavish, wasteful, frugal (trái nghĩa)" },
  "disposable": { m: "dispose of (vứt bỏ) + -able → có thể vứt đi sau một lần dùng.", e: "Sai: dispose plastic cups → Đúng: disposable plastic cups. Sai: dispose the rubbish → Đúng: dispose of the rubbish.", u: "Writing Task 2: ban disposable plastics. Nghĩa khác: disposable income (thu nhập khả dụng).", f: "disposable (adj), dispose of (v), disposal (n); single-use, reusable (trái nghĩa)" },
  "counterfeit": { m: "counter- (đối ngược) + feit (làm ra) → làm ra bản đối diện, bắt chước → hàng giả.", e: "Sai: counterfeit goods is cheap → Đúng: counterfeit goods are cheap. Sai: conterfeit → Đúng: counterfeit.", u: "Writing Task 2: counterfeit goods, bản quyền, thương hiệu. Speaking Part 3: 'Why do people buy fake designer goods?'.", f: "counterfeit (adj/n/v), counterfeiter (n); fake, imitation, knock-off (thân mật)" },
  "shopaholic": { m: "shop + -aholic (như 'alcoholic', người nghiện rượu) → người nghiện mua sắm.", e: "Sai: shopping-holic → Đúng: shopaholic. Sai: she is shopaholic → Đúng: she is a shopaholic.", u: "Speaking Part 1 (shopping): 'I'm not a shopaholic, I only buy what I need'. Part 3: chủ nghĩa tiêu dùng.", f: "shopaholic (n), workaholic (n), chocoholic (n); compulsive shopper" },
  "status symbol": { m: "status (địa vị) + symbol (biểu tượng) → món đồ khoe địa vị: xe sang, đồng hồ đắt.", e: "Sai: symbol of status → được, nhưng tự nhiên hơn: a status symbol. Sai: status symbols is → Đúng: are.", u: "Speaking Part 3: 'Are smartphones a status symbol?'. Writing Task 2: chủ nghĩa tiêu dùng, áp lực xã hội.", f: "status symbol (n), status (n), luxury goods (n); show off, keeping up with the Joneses" },
  "throwaway": { m: "throw away (vứt đi) ghép thành tính từ → đồ dùng rồi vứt; throwaway culture = văn hóa vứt bỏ.", e: "Sai: throw-away society (chấp nhận) nhưng phổ biến: throwaway society. Sai: a throw away culture.", u: "Writing Task 2: 'We live in a throwaway society'. Speaking Part 3: rác nhựa, sửa đồ thay vì mua mới.", f: "throwaway (adj), throw away (phrasal v); disposable, single-use" },
  "frugal": { m: "Gốc Latin 'frugi' = đạm bạc, hữu ích → sống tiết kiệm, không phung phí.", e: "Sai: frugal money → Đúng: frugal with money. Sai: frugally lifestyle → Đúng: a frugal lifestyle.", u: "Speaking Part 1/3: 'My grandparents are very frugal'. Writing Task 2: lối sống tối giản, tiết kiệm.", f: "frugal (adj), frugality (n), frugally (adv); thrifty, economical, extravagant (trái nghĩa)" },
  "astronaut": { m: "astro- (ngôi sao) + naut (thủy thủ, như 'nautical') → thủy thủ đi giữa các vì sao.", e: "Sai: astronout → Đúng: astronaut. Sai: spaceman astronaut → thừa, chọn một.", u: "Speaking Part 1/2: ước mơ thời thơ ấu thành astronaut. Writing Task 2: chi phí thám hiểm vũ trụ.", f: "astronaut (n), cosmonaut (n, Nga), astronomy (n), spaceflight (n)" },
  "orbit": { m: "Gốc Latin 'orbis' = vòng tròn → đường vòng vật thể bay quanh hành tinh → quỹ đạo.", e: "Sai: orbit around the Earth (v) → Đúng: orbit the Earth. Danh từ: in orbit around the Earth.", u: "Speaking Part 3 khoa học: vệ tinh in orbit, space station. Writing Task 2: rác vũ trụ trên quỹ đạo.", f: "orbit (n/v), orbital (adj); go into orbit, satellite (n)" },
  "galaxy": { m: "Gốc Hy Lạp 'gala' = sữa → Milky Way (Dải Ngân Hà) như dòng sữa → thiên hà.", e: "Sai: our galaxy is Milky Way → Đúng: our galaxy is the Milky Way. Sai: galaxys → Đúng: galaxies.", u: "Speaking Part 3 vũ trụ: sự sống ở thiên hà khác. Writing Task 2: lý do khám phá vũ trụ.", f: "galaxy (n), galactic (adj), intergalactic (adj); the Milky Way, universe" },
  "exploration": { m: "explore = thám hiểm → exploration: hành trình khám phá vùng chưa biết.", e: "Sai: exploration on space → Đúng: space exploration / the exploration of space. Sai: exploitation (khai thác) ≠ exploration.", u: "Writing Task 2: 'Is space exploration a waste of money?'. Speaking Part 3: thám hiểm đại dương.", f: "exploration (n), explore (v), explorer (n), exploratory (adj)" },
  "spacecraft": { m: "space (vũ trụ) + craft (phương tiện, như 'aircraft') → phương tiện bay vào vũ trụ.", e: "Sai: spacecrafts → Đúng: spacecraft (số nhiều giữ nguyên). Sai: space craft → Đúng: spacecraft.", u: "Speaking Part 3/Writing Task 2: công nghệ vũ trụ, tàu thăm dò sao Hỏa. Dùng học thuật thay cho spaceship.", f: "spacecraft (n), spaceship (n), space shuttle (n), aircraft (n)" },
  "telescope": { m: "tele- (xa, như 'telephone') + scope (nhìn) → dụng cụ nhìn xa → kính thiên văn.", e: "Sai: see stars by telescope → Đúng: look at stars through a telescope. Sai: telescop → Đúng: telescope.", u: "Speaking Part 2: mô tả thiết bị khoa học thú vị. Writing Task 2: thiên văn và giáo dục khoa học.", f: "telescope (n), telescopic (adj); microscope, binoculars (n)" },
  "gravity": { m: "Gốc Latin 'gravis' = nặng (như 'grave') → lực kéo vật nặng xuống → trọng lực.", e: "Sai: the gravity of Earth pull → Đúng: Earth's gravity pulls. Nghĩa khác: the gravity of the situation (mức nghiêm trọng).", u: "Speaking Part 3 khoa học: cuộc sống không trọng lực. Writing: 'the gravity of the problem'.", f: "gravity (n), gravitational (adj), gravitate (v); zero gravity, weightlessness" },
  "astronomy": { m: "astro- (ngôi sao) + -nomy (quy luật) → môn học quy luật các vì sao → thiên văn học.", e: "Sai: astrology (chiêm tinh) khi muốn nói thiên văn → Đúng: astronomy. Sai: an astronomy → Đúng: an astronomer.", u: "Speaking Part 1/2: sở thích ngắm sao. Writing Task 2: giá trị nghiên cứu vũ trụ.", f: "astronomy (n), astronomer (n), astronomical (adj); astrology (n, khác nghĩa)" },
  "colonise": { m: "colony (thuộc địa) + -ise → biến nơi khác thành thuộc địa, đến định cư → khai phá hành tinh.", e: "Sai: colonise to Mars → Đúng: colonise Mars. Sai: colonisation Mars → Đúng: the colonisation of Mars.", u: "Writing Task 2/Speaking Part 3: 'Should humans colonise Mars?'. Lịch sử: thời kỳ thực dân.", f: "colonise/colonize (v), colonisation (n), colony (n), colonist (n), colonial (adj)" },
  "extraterrestrial": { m: "extra- (ngoài) + terrestrial (thuộc Trái Đất, 'terra' = đất) → ngoài Trái Đất. E.T. là viết tắt.", e: "Sai: extra-terrestrial life is exist → Đúng: extraterrestrial life exists. Sai: alien life form từ ngoài.", u: "Speaking Part 3: 'Do you believe in extraterrestrial life?'. Writing Task 2: tìm kiếm sự sống ngoài Trái Đất.", f: "extraterrestrial (adj/n), terrestrial (adj); alien (n), E.T." },
  "solar system": { m: "solar (thuộc Mặt Trời, 'sol') + system (hệ) → Mặt Trời cùng các hành tinh quay quanh nó.", e: "Sai: sun system → Đúng: the solar system. Sai: in solar system → Đúng: in the solar system.", u: "Speaking Part 3 vũ trụ, giáo dục khoa học. Writing Task 2: khám phá các hành tinh trong solar system.", f: "solar system (n), solar (adj), planet (n), solar energy (n)" },
  "asteroid": { m: "aster (ngôi sao, như 'asterisk' *) + -oid (giống) → vật trông như sao nhỏ → tiểu hành tinh.", e: "Sai: asteroid hit to Earth → Đúng: an asteroid hit Earth. Phân biệt: comet (sao chổi), meteor (sao băng).", u: "Speaking Part 3: 'asteroid strikes' làm tuyệt chủng khủng long. Writing Task 2: lý do theo dõi vũ trụ.", f: "asteroid (n), meteor (n), meteorite (n), comet (n); asteroid belt" },
  "space debris": { m: "debris (mảnh vỡ, từ Pháp) → mảnh vệ tinh, tên lửa cũ trôi trong vũ trụ → rác vũ trụ.", e: "Sai: space debrises → Đúng: space debris (không đếm được). Đọc /ˈdebriː/, chữ 's' câm.", u: "Writing Task 2: mặt trái thám hiểm vũ trụ. Speaking Part 3: vệ tinh hỏng và rác quỹ đạo.", f: "space debris (n), space junk (n), debris (n), satellite (n)" },
  "probe": { m: "probe = cây que dò (gốc 'prove', kiểm tra) → tàu không người lái đi dò xét hành tinh.", e: "Sai: send a probe into the Mars → Đúng: send a probe to Mars. Động từ: probe into an issue.", u: "Speaking Part 3/Writing Task 2: space probes vs manned missions. Nghĩa khác: a probe into corruption (điều tra).", f: "probe (n/v), probing (adj); space probe, rover, investigation" },
  "cosmos": { m: "Gốc Hy Lạp 'kosmos' = trật tự → vũ trụ như một tổng thể trật tự, bao la.", e: "Sai: a cosmos → Đúng: the cosmos. Sai: cosmo → Đúng: cosmos.", u: "Speaking Part 3: suy ngẫm về vị trí con người trong the cosmos. Văn phong trang trọng hơn 'universe'.", f: "cosmos (n), cosmic (adj), cosmology (n), cosmonaut (n); universe" },
  "bilingual": { m: "bi- (hai) + lingua (lưỡi, ngôn ngữ) → nói thạo hai ngôn ngữ → song ngữ.", e: "Sai: bilingual in English with Vietnamese → Đúng: bilingual in English and Vietnamese. Sai: a bilingualism child.", u: "Writing Task 2: 'Children should learn a second language early'. Speaking Part 3: bilingual education.", f: "bilingual (adj/n), bilingualism (n), multilingual (adj), monolingual (adj)" },
  "dialect": { m: "dia- (xuyên) + lect (nói) → cách nói riêng của từng vùng → phương ngữ.", e: "Sai: speak with dialect → Đúng: speak in a dialect. Phân biệt accent (giọng) với dialect (cả từ vựng, ngữ pháp).", u: "Speaking Part 3: phương ngữ Bắc, Trung, Nam. Writing Task 2: ngôn ngữ thiểu số có nguy cơ biến mất.", f: "dialect (n), dialectal (adj); accent, regional language, vernacular" },
  "mother tongue": { m: "Hình ảnh: tongue (lưỡi, ngôn ngữ) học từ mẹ → ngôn ngữ đầu tiên → tiếng mẹ đẻ.", e: "Sai: mother language → Đúng: mother tongue / native language / first language.", u: "Speaking Part 1/3: 'My mother tongue is Vietnamese'. Writing Task 2: giữ tiếng mẹ đẻ khi học ngoại ngữ.", f: "mother tongue (n), native language (n), first language (n), native speaker (n)" },
  "vocabulary": { m: "voc- = giọng nói, từ (như 'vocal') → kho từ mình có thể nói ra → vốn từ.", e: "Sai: learn many vocabularies → Đúng: learn a lot of vocabulary / many words. Sai: my vocabulary is many → Đúng: wide.", u: "Speaking Part 1/3: 'How do you learn English vocabulary?'. Writing: expand/build vocabulary, a wide range of vocabulary.", f: "vocabulary (n), vocab (n, thân mật), lexicon (n), word (n)" },
  "pronunciation": { m: "Lưu ý chính tả: pronounce (động từ) có 'ou' nhưng pronunciation mất 'o' → pro-NUN-ciation.", e: "Sai: pronounciation → Đúng: pronunciation. Sai: my pronounce is bad → Đúng: my pronunciation is poor.", u: "Speaking: tiêu chí chấm Pronunciation trong IELTS. Part 1: 'What's difficult about learning English?'.", f: "pronunciation (n), pronounce (v), pronounced (adj, rõ rệt), mispronounce (v)" },
  "articulate": { m: "articul- = khớp nối (như 'article') → nối từ ngữ mạch lạc, rõ ràng → diễn đạt lưu loát.", e: "Sai: articulate in speak → Đúng: articulate (adj) / able to articulate ideas. Đọc tính từ /-lət/, động từ /-leɪt/.", u: "Speaking Part 2: mô tả người diễn đạt giỏi. Writing Task 2: articulate one's views clearly.", f: "articulate (adj/v), articulation (n), articulately (adv), inarticulate (adj)" },
  "eloquent": { m: "e- (ra) + loqu (nói, như 'loquacious') → nói ra trôi chảy, cuốn hút → hùng hồn.", e: "Sai: eloquent speak → Đúng: an eloquent speech/speaker. Sai: eloquence speaker → Đúng: eloquent speaker.", u: "Speaking Part 2: mô tả một diễn giả, lãnh đạo bạn ngưỡng mộ. Writing: an eloquent argument.", f: "eloquent (adj), eloquence (n), eloquently (adv); articulate, persuasive" },
  "idiom": { m: "Gốc Hy Lạp 'idios' = riêng (như 'idiosyncrasy') → cách nói riêng, không dịch từng chữ → thành ngữ.", e: "Sai: use idioms in Writing Task 2 bừa bãi → Đúng: dùng idiom tự nhiên trong Speaking. Sai: idiomatic (n).", u: "Speaking: dùng idioms tự nhiên (a piece of cake) để tăng điểm Lexical Resource; tránh trong Writing học thuật.", f: "idiom (n), idiomatic (adj), idiomatically (adv); expression, saying, proverb" },
  "linguistic": { m: "lingua (lưỡi, ngôn ngữ) + -istic → thuộc về ngôn ngữ và ngôn ngữ học.", e: "Sai: linguistic is my major → Đúng: linguistics is my major. Sai: language diversity (được) / linguistic diversity.", u: "Writing Task 2: linguistic diversity, linguistic barriers. Speaking Part 3: ngôn ngữ và văn hóa.", f: "linguistic (adj), linguistics (n), linguist (n), lingual (adj)" },
  "multilingual": { m: "multi- (nhiều) + lingua (ngôn ngữ) → nói được nhiều ngôn ngữ → đa ngôn ngữ.", e: "Sai: multi-languages country → Đúng: a multilingual country. Sai: multilingual of three languages.", u: "Writing Task 2: lợi ích nhân viên multilingual trong toàn cầu hóa. Speaking Part 3: Singapore, Thụy Sĩ.", f: "multilingual (adj), multilingualism (n), bilingual (adj), polyglot (n)" },
  "body language": { m: "Hình ảnh: cơ thể 'nói' bằng cử chỉ, nét mặt, tư thế → ngôn ngữ cơ thể.", e: "Sai: body languages → Đúng: body language (không đếm được). Sai: use body language to speak → Đúng: communicate through body language.", u: "Speaking Part 3: giao tiếp liên văn hóa, phỏng vấn xin việc. Writing Task 2: giao tiếp trực tiếp vs online.", f: "body language (n), gesture (n), facial expression (n), non-verbal communication (n)" },
  "jargon": { m: "Gốc Pháp cổ 'jargon' = tiếng chim líu lo, khó hiểu → biệt ngữ chuyên ngành người ngoài khó hiểu.", e: "Sai: jargons → Đúng: jargon (không đếm được). Sai: use many technical jargon words → Đúng: use too much technical jargon.", u: "Speaking Part 3/Writing Task 2: 'Doctors should avoid medical jargon'. Ngữ cảnh: luật, y khoa, IT.", f: "jargon (n), jargon-free (adj); terminology, technical terms, slang" },
  "pesticide": { m: "pest (sâu bọ) + -cide (giết, như 'suicide') → chất giết sâu bọ.", e: "Sai: farmers use many pesticide → Đúng: farmers use many pesticides / a lot of pesticide. Chú ý đọc /ˈpes.tɪ.saɪd/.", u: "IELTS Writing (food, environment): 'the overuse of pesticides contaminates soil and water'. Speaking: lý do chọn rau hữu cơ.", f: "pesticide (n), pesticide-free (adj), insecticide, herbicide (n, cùng đuôi -cide)" },
  "fertiliser": { m: "fertile (màu mỡ) + -iser (làm cho) → thứ làm đất màu mỡ → phân bón.", e: "Sai: put fertiliser to the plants → Đúng: apply fertiliser to the plants. Anh-Mỹ viết fertilizer.", u: "IELTS Writing: 'chemical fertilisers boost yields but pollute rivers'. Process diagram về trồng trọt cũng hay có từ này.", f: "fertile (adj), fertility (n), fertilise (v), fertiliser (n), organic fertiliser" },
  "harvest": { m: "Liên tưởng 'harvest moon' – trăng tròn mùa gặt, nông dân thu hoạch dưới trăng.", e: "Sai: a good harvesting this year → Đúng: a good harvest this year. Sai: harvest the rice field → Đúng: harvest the rice.", u: "IELTS Speaking (hometown, countryside): 'villagers celebrate after the rice harvest'. Writing: poor harvests do thời tiết khắc nghiệt.", f: "harvest (n/v), harvester (n), harvesting (n), bumper harvest, crop" },
  "livestock": { m: "live (sống) + stock (hàng dự trữ) → 'kho hàng sống' của nông trại: bò, lợn, gà.", e: "Sai: many livestocks → Đúng: a lot of livestock (danh từ không đếm/tập hợp). Sai: livestock is grazing (số nhiều) → livestock are grazing đều chấp nhận.", u: "IELTS Writing (food, climate): 'livestock farming produces large amounts of methane'. Speaking: mô tả quê có nuôi gia súc.", f: "livestock (n), cattle, poultry, livestock farming, graze (v)" },
  "genetically modified": { m: "gene (gen) + modified (đã sửa đổi) → cây/con đã được 'chỉnh sửa gen', viết tắt GM/GMO.", e: "Sai: genetic modified food → Đúng: genetically modified food (cần trạng từ -ly trước tính từ).", u: "IELTS Writing (food, technology): 'Are genetically modified crops a solution to world hunger?'. Nêu cả lợi ích năng suất và lo ngại sức khỏe.", f: "genetically modified (adj), GM, GMO (n), genetic modification (n), genetically engineered" },
  "processed food": { m: "process (xử lý qua máy móc) → thực phẩm đã qua nhà máy: xúc xích, mì gói, đồ hộp.", e: "Sai: process food → Đúng: processed food (phân từ quá khứ làm tính từ). Sai: processed foods is → Đúng: processed foods are.", u: "IELTS Speaking (food, health): 'I try to avoid processed food because it's high in salt'. Writing: nguyên nhân béo phì.", f: "processed food (n), ultra-processed (adj), junk food, convenience food, whole food" },
  "irrigation": { m: "irrigate gần âm 'ì ri' tiếng nước chảy vào ruộng → dẫn nước tưới đồng.", e: "Sai: irrigation the fields → Đúng: irrigate the fields (động từ). Sai: water irrigation system → Đúng: irrigation system.", u: "IELTS Writing (agriculture, water): 'modern irrigation systems reduce water waste'. Map/process task: kênh tưới tiêu.", f: "irrigate (v), irrigation (n), irrigated (adj), drip irrigation, irrigation canal" },
  "malnutrition": { m: "mal- (xấu, như 'malfunction') + nutrition (dinh dưỡng) → dinh dưỡng kém → suy dinh dưỡng.", e: "Sai: children suffer malnutrition → Đúng: children suffer from malnutrition. Sai: a malnutrition child → Đúng: a malnourished child.", u: "IELTS Writing (poverty, food): 'malnutrition remains a major cause of child mortality in developing countries'.", f: "malnutrition (n), malnourished (adj), nutrition (n), nutritious (adj), undernourished (adj)" },
  "food security": { m: "security = an ninh: đảm bảo mọi người luôn có đủ đồ ăn, như 'an ninh' cho cái bụng.", e: "Sai: food safety (an toàn vệ sinh) dùng nhầm cho đủ lương thực → Đúng: food security. Sai: the food securities → Đúng: food security.", u: "IELTS Writing (global issues): 'climate change threatens food security in poorer nations'. Kết hợp: ensure / improve food security.", f: "food security (n), food insecurity (n), food-secure (adj), food safety (khác nghĩa)" },
  "famine": { m: "Gần 'famished' (đói lả) → cả vùng đói lả kéo dài → nạn đói.", e: "Sai: hunger hit the country (khi nói thảm họa diện rộng) → Đúng: famine hit the country. Đọc /ˈfæm.ɪn/, không phải 'fa-mai'.", u: "IELTS Writing: 'droughts can lead to famine and mass migration'. Dùng khi bàn về viện trợ quốc tế.", f: "famine (n), famine-stricken (adj), famished (adj), starvation (n), starve (v)" },
  "cultivate": { m: "Cùng gốc 'culture' (văn hóa – ban đầu là 'vun trồng') → vun xới đất; cũng 'vun đắp' mối quan hệ.", e: "Sai: cultivate on the land → Đúng: cultivate the land. Sai: cultivate a habit of (ít tự nhiên hơn) → develop a habit of.", u: "IELTS Writing: 'land once cultivated for rice is now used for housing'. Speaking: cultivate a hobby, cultivate friendships.", f: "cultivate (v), cultivation (n), cultivated (adj), cultivator (n), culture (n, cùng gốc)" },
  "agriculture": { m: "agri- (đồng ruộng) + culture (trồng trọt) → nghề trồng trọt trên đồng → nông nghiệp.", e: "Sai: the agriculture is important → Đúng: agriculture is important (không cần 'the'). Sai: agriculture products → Đúng: agricultural products.", u: "IELTS Writing (economy, environment): 'agriculture accounts for a large share of water use'. Bar chart theo ngành kinh tế.", f: "agriculture (n), agricultural (adj), agriculturally (adv), agronomist (n), farming" },
  "intensive farming": { m: "intensive (dồn dập, tập trung) → dồn nhiều phân, máy, vật nuôi vào ít đất → thâm canh.", e: "Sai: intensively farming (khi cần danh từ) → Đúng: intensive farming. Trái nghĩa là extensive farming, không phải 'unintensive'.", u: "IELTS Writing: 'intensive farming increases output but harms animal welfare and soil quality'.", f: "intensive farming (n), factory farming, extensive farming, organic farming, intensify (v)" },
  "additive": { m: "add (thêm vào) + -itive → chất được thêm vào đồ ăn: màu, hương, chất bảo quản.", e: "Sai: food has many addition → Đúng: food contains many additives. Sai: additive-free food is contain → Đúng: additive-free food contains no additives.", u: "IELTS Speaking (food): 'snacks are full of artificial additives'. Writing: lo ngại sức khỏe của thực phẩm công nghiệp.", f: "add (v), addition (n), additive (n), additive-free (adj), preservative (n)" },
  "perishable": { m: "perish (chết, hư) + -able → thứ dễ hư: sữa, rau, cá phải bảo quản lạnh.", e: "Sai: this food is easy perishable → Đúng: this food is highly perishable. Sai: perishable goods last long → Đúng: perishable goods spoil quickly.", u: "IELTS Writing (food waste, trade): 'perishable goods need refrigerated transport'. Logistics: perishables (n).", f: "perish (v), perishable (adj), perishables (n), non-perishable (adj), imperishable (adj)" },
  "cut down on": { m: "Hình ảnh: cắt (cut) bớt xuống (down) lượng thứ gì (on) → ăn/dùng ít đi chứ không bỏ hẳn.", e: "Sai: cut down sugar → Đúng: cut down on sugar. Sai: cut down on to eat sweets → Đúng: cut down on eating sweets.", u: "IELTS Speaking (health): 'I've been trying to cut down on fast food'. Writing: governments should urge people to cut down on plastic.", f: "cut down on (phr v), cut back on, reduce, cut out (bỏ hẳn)" },
  "look forward to": { m: "Hình ảnh: nhìn (look) về phía trước (forward) tới (to) điều sắp đến → háo hức chờ.", e: "Sai: I look forward to see you → Đúng: I look forward to seeing you ('to' là giới từ, theo sau là V-ing).", u: "IELTS Speaking: 'I'm really looking forward to travelling after my exams'. Email trang trọng: I look forward to hearing from you.", f: "look forward to (phr v), can't wait to, anticipate (v), eagerly await" },
  "come up with": { m: "Hình ảnh: ý tưởng 'trồi lên' (come up) trong đầu và bạn cầm lấy nó (with).", e: "Sai: come up an idea → Đúng: come up with an idea. Sai: come up with to solve → Đúng: come up with a way to solve.", u: "IELTS Speaking: 'we came up with a plan to raise money'. Writing: governments must come up with solutions to traffic congestion.", f: "come up with (phr v), think of, devise (v), propose (v), dream up" },
  "put off": { m: "Hình ảnh: đặt (put) việc ra xa (off) khỏi lịch hôm nay → để sau → trì hoãn.", e: "Sai: put off to do homework → Đúng: put off doing homework. Đại từ đứng giữa: put it off, không nói put off it.", u: "IELTS Speaking (habits): 'I tend to put off difficult tasks until the last minute'. Cũng nghĩa 'làm mất hứng': the smell put me off.", f: "put off (phr v), postpone (v), delay (v), procrastinate (v), off-putting (adj)" },
  "take up": { m: "Hình ảnh: nhặt (take) một sở thích lên (up) để bắt đầu chơi.", e: "Sai: I took up to play guitar → Đúng: I took up the guitar / took up playing the guitar.", u: "IELTS Speaking (hobbies): 'I took up yoga last year to reduce stress'. Còn nghĩa chiếm chỗ: it takes up too much time.", f: "take up (phr v), start, pick up, get into, uptake (n)" },
  "give up": { m: "Hình ảnh: giơ tay lên (up) và trao (give) lại → đầu hàng, bỏ cuộc.", e: "Sai: give up to smoke → Đúng: give up smoking. Sai: don't give up yourself → Đúng: don't give up.", u: "IELTS Speaking: 'I almost gave up learning English, but my teacher encouraged me'. Writing: give up private cars.", f: "give up (phr v), quit (v), abandon (v), surrender (v), never give up" },
  "hang out": { m: "Hình ảnh: 'treo' (hang) mình ở ngoài (out) cùng bạn, không làm gì cụ thể → la cà, đi chơi.", e: "Sai: hang out to the mall → Đúng: hang out at the mall / hang out with friends.", u: "IELTS Speaking Part 1 (free time, friends): 'At weekends I usually hang out with my friends at a café'.", f: "hang out (phr v), hangout (n: chỗ hay tụ tập), spend time with, socialise (v)" },
  "catch up with": { m: "Hình ảnh: chạy theo bắt kịp (catch up) người đi trước; với bạn cũ là 'bắt kịp' tin tức của nhau.", e: "Sai: catch up my old friends → Đúng: catch up with my old friends. Sai: catch up the class → Đúng: catch up with the class.", u: "IELTS Speaking (friends, family): 'I meet my school friends to catch up with them during Tết'.", f: "catch up with (phr v), catch-up (n), keep up with, fall behind (trái nghĩa)" },
  "get along with": { m: "Hình ảnh: đi (get) cùng dọc (along) con đường với ai mà không va chạm → hòa hợp.", e: "Sai: I get along my roommate → Đúng: I get along with my roommate. Sai: get along well each other → Đúng: get along well with each other.", u: "IELTS Speaking (family, neighbours, colleagues): 'I get along really well with my younger sister'. Anh-Anh hay dùng get on with.", f: "get along with (phr v), get on with, have a good relationship with, clash with (trái nghĩa)" },
  "look up to": { m: "Hình ảnh: ngước nhìn lên (look up) một người đứng cao hơn mình → kính trọng.", e: "Sai: I look up my father → Đúng: I look up to my father ('look up' là tra cứu). Sai: as role model → as a role model.", u: "IELTS Speaking Part 2 'Describe a person you admire': 'I've always looked up to my grandmother because...'.", f: "look up to (phr v), admire (v), respect (v), role model (n), look down on (trái nghĩa)" },
  "run out of": { m: "Hình ảnh: nguồn dự trữ chảy cạn (run out) → không còn gì (of) để dùng.", e: "Sai: we ran out money → Đúng: we ran out of money. Sai: the milk ran out of → Đúng: the milk ran out (không có tân ngữ).", u: "IELTS Writing (resources): 'the world may run out of fossil fuels'. Speaking: I often run out of time in exams.", f: "run out of (phr v), run short of, use up, be out of, exhaust (v)" },
  "figure out": { m: "Hình ảnh: tính toán ra con số (figure) đáp án → hiểu ra, giải được.", e: "Sai: figure out how to do it is hard → Đúng: figuring out how to do it is hard. Đại từ: figure it out, không nói figure out it.", u: "IELTS Speaking (technology, studies): 'it took me ages to figure out how to use the new app'.", f: "figure out (phr v), work out, find out, understand (v), solve (v)" },
  "end up": { m: "Hình ảnh: đi một hồi rồi rốt cuộc dừng ở cuối (end) chỗ không định trước.", e: "Sai: we ended up to stay home → Đúng: we ended up staying home (end up + V-ing hoặc + nơi chốn).", u: "IELTS Speaking (stories, Part 2): 'we got lost and ended up in a tiny fishing village'. Kể chuyện tự nhiên.", f: "end up (phr v), wind up, finish up, eventually (adv), in the end" },
  "set up": { m: "Hình ảnh: dựng (set) lều lên (up) → dựng công ty, lắp đặt thiết bị.", e: "Sai: set up a new business company by myself (thừa) → Đúng: set up my own business. Danh từ viết liền: a setup.", u: "IELTS Speaking (work): 'my uncle set up a small coffee shop'. Writing: governments should set up recycling centres.", f: "set up (phr v), setup / set-up (n), establish (v), found (v), install (v)" },
  "carry on": { m: "Hình ảnh: tiếp tục mang (carry) gánh đi tới (on) không dừng lại.", e: "Sai: carry on to study → Đúng: carry on studying / carry on with your studies.", u: "IELTS Speaking (study, future plans): 'I'd like to carry on learning Japanese after university'.", f: "carry on (phr v), go on, continue (v), keep on, carry-on (n: hành lý xách tay)" },
  "turn down": { m: "Hình ảnh: úp (turn) lá bài xuống (down) → không nhận → từ chối; cũng là vặn nhỏ âm lượng.", e: "Sai: she turned down to join → Đúng: she turned down the offer / refused to join. Đại từ: turn it down.", u: "IELTS Speaking (work, decisions): 'I turned down a job offer because it was too far from home'.", f: "turn down (phr v), reject (v), decline (v), refuse (v), turn up (vặn to)" },
  "bring up": { m: "Hình ảnh: mang (bring) đứa trẻ lên (up) từ bé tới lớn → nuôi dạy; mang chủ đề lên bàn → nêu ra.", e: "Sai: I was grown up by my grandparents → Đúng: I was brought up by my grandparents.", u: "IELTS Speaking (family, childhood): 'I was brought up in a small town'. Writing: parents bring up children differently today.", f: "bring up (phr v), upbringing (n), raise (v), rear (v), raise a topic" },
  "pick up": { m: "Hình ảnh: nhặt (pick) lên dọc đường → học lỏm một ngôn ngữ, hoặc đón ai bên đường.", e: "Sai: I picked English up from school lessons (khi học bài bản) → Đúng: I picked up some English from watching films.", u: "IELTS Speaking (languages, skills): 'I picked up a bit of Korean from K-dramas'. Giao tiếp: pick someone up at the airport.", f: "pick up (phr v), pickup (n), acquire (v), learn (v), pick up a habit" },
  "grow up": { m: "Hình ảnh: cây mọc (grow) cao lên (up) → người lớn dần.", e: "Sai: I was grown up in Hanoi → Đúng: I grew up in Hanoi. Sai: my parents grew me up → Đúng: my parents brought me up.", u: "IELTS Speaking Part 1 (hometown): 'I grew up in a coastal city, so I love seafood'.", f: "grow up (phr v), grown-up (n/adj), upbringing (n), growing up (n: tuổi thơ)" },
  "settle down": { m: "Hình ảnh: hạt bụi lắng (settle) xuống (down) → cuộc sống yên ổn, có nhà, có gia đình.", e: "Sai: settle down a family → Đúng: settle down and start a family. Sai: settle down in Hanoi city → Đúng: settle down in Hanoi.", u: "IELTS Speaking (future plans): 'I'd like to travel more before I settle down'. Cũng nghĩa lắng xuống: the class settled down.", f: "settle down (phr v), settle (v), settled (adj), settlement (n), put down roots" },
  "put up with": { m: "Hình ảnh: đặt lên (put up) vai và mang theo (with) điều khó chịu → chịu đựng.", e: "Sai: I can't put up with to wait → Đúng: I can't put up with waiting. Sai: put up noise → Đúng: put up with noise.", u: "IELTS Speaking (city life, neighbours): 'I have to put up with heavy traffic every morning'.", f: "put up with (phr v), tolerate (v), stand (v), bear (v), endure (v)" },
  "go through": { m: "Hình ảnh: đi xuyên qua (through) đường hầm tối → trải qua giai đoạn khó khăn.", e: "Sai: go through a difficulty time → Đúng: go through a difficult time. Sai: I went through with hardship → Đúng: I went through hardship.", u: "IELTS Speaking Part 2 (challenges): 'my family went through a tough period when my dad lost his job'.", f: "go through (phr v), experience (v), undergo (v), endure (v), get through" },
  "look after": { m: "Hình ảnh: nhìn (look) theo sau (after) đứa trẻ khi nó chạy chơi → trông nom, chăm sóc.", e: "Sai: look after for my sister → Đúng: look after my sister. Sai: look for (tìm) dùng nhầm → look after (chăm sóc).", u: "IELTS Speaking (family, pets): 'I look after my little brother when my parents work late'.", f: "look after (phr v), take care of, care for, babysit (v), caregiver (n)" },
  "keep up with": { m: "Hình ảnh: giữ (keep) mình ngang hàng (up) với người chạy cạnh → theo kịp.", e: "Sai: keep up the latest news → Đúng: keep up with the latest news. Sai: keep up with to learn → keep up with my classmates.", u: "IELTS Speaking (technology, fashion): 'it's hard to keep up with the latest smartphones'.", f: "keep up with (phr v), keep pace with, stay up to date, fall behind (trái nghĩa)" },
  "work out": { m: "Hình ảnh: cơ bắp 'làm việc' (work) ra (out) mồ hôi → tập thể dục; đầu óc làm việc ra đáp án → tìm ra.", e: "Sai: I work out at gym every day → Đúng: I work out at the gym every day. Danh từ viết liền: a workout.", u: "IELTS Speaking (health, sport): 'I work out three times a week'. Cũng: things worked out well.", f: "work out (phr v), workout (n), exercise (v/n), figure out, train (v)" },
  "come across": { m: "Hình ảnh: đang đi thì băng ngang (across) qua một thứ → tình cờ gặp/thấy.", e: "Sai: I came across with an old photo → Đúng: I came across an old photo (không cần 'with').", u: "IELTS Speaking Part 2 (a book, a place, a website): 'I came across this café while wandering around the old quarter'.", f: "come across (phr v), stumble upon, run into, chance upon, discover (v)" },
  "fall out with": { m: "Hình ảnh: rơi (fall) ra khỏi (out) vòng tình bạn với ai → cãi nhau, giận nhau.", e: "Sai: I fell out my best friend → Đúng: I fell out with my best friend. Danh từ: a falling-out.", u: "IELTS Speaking (friends, family): 'I fell out with a classmate over a group project, but we made up later'.", f: "fall out with (phr v), falling-out (n), argue with, make up with (làm lành)" },
  "drop out": { m: "Hình ảnh: rớt (drop) ra khỏi (out) đoàn tàu học hành giữa đường → bỏ học.", e: "Sai: he dropped out university → Đúng: he dropped out of university. Danh từ: a dropout.", u: "IELTS Writing (education): 'financial pressure causes many students to drop out of school'. Speaking: dropout rates.", f: "drop out (of) (phr v), dropout (n), quit school, leave school early" },
  "take after": { m: "Hình ảnh: 'lấy theo' (take after) khuôn của bố mẹ → giống người lớn trong nhà.", e: "Sai: I take after with my mother → Đúng: I take after my mother. Sai: I am taking after (tiếp diễn) → Đúng: I take after.", u: "IELTS Speaking (family): 'I take after my dad – we're both quiet and love fixing things'.", f: "take after (phr v), resemble (v), look like, be similar to, run in the family" },
  "show off": { m: "Hình ảnh: đưa (show) đồ ra ngoài (off) cho mọi người trầm trồ → khoe khoang.", e: "Sai: he shows off about his car → Đúng: he shows off his car. Danh từ: a show-off (người hay khoe).", u: "IELTS Speaking (social media, shopping): 'some people buy luxury goods just to show off on Instagram'.", f: "show off (phr v), show-off (n), boast (v), brag (v), flaunt (v)" },
  "chill out": { m: "Hình ảnh: cho mình 'lạnh' (chill) xuống, xả (out) căng thẳng → thư giãn.", e: "Sai: I chill out myself → Đúng: I chill out. Văn viết trang trọng không dùng; thay bằng relax.", u: "IELTS Speaking Part 1 (weekends): 'I usually chill out at home and watch Netflix'. Chỉ dùng trong Speaking, khẩu ngữ.", f: "chill out (phr v), chill (v/adj), chilled-out (adj), relax (v), unwind (v)" },
  "calm down": { m: "Hình ảnh: sóng đang dâng rồi lặng (calm) xuống (down) → bình tĩnh lại.", e: "Sai: please calm → Đúng: please calm down. Sai: calm down yourself → Đúng: calm yourself down / calm down.", u: "IELTS Speaking (stress, exams): 'I take a few deep breaths to calm down before speaking tests'.", f: "calm down (phr v), calm (adj/v), calmness (n), calmly (adv), settle down" },
  "cheer up": { m: "Hình ảnh: tiếng hò reo (cheer) kéo tinh thần lên (up) → vui lên.", e: "Sai: cheer up me → Đúng: cheer me up. Sai: she cheered up her sadness → Đúng: she cheered up.", u: "IELTS Speaking (music, friends): 'listening to upbeat songs always cheers me up'.", f: "cheer up (phr v), cheerful (adj), cheer (n/v), lift someone's spirits" },
  "eat out": { m: "Hình ảnh: ăn (eat) ở bên ngoài (out) nhà → đi ăn nhà hàng.", e: "Sai: we eat outside at a restaurant → Đúng: we eat out (at a restaurant). 'Eat outside' là ăn ngoài trời.", u: "IELTS Speaking (food): 'young people eat out more often than their parents did'. Writing: chi tiêu cho eating out.", f: "eat out (phr v), dine out, eating out (n), takeaway (n), eat in (ăn ở nhà)" },
  "dress up": { m: "Hình ảnh: nâng (up) cấp bộ quần áo (dress) → ăn diện; còn là hóa trang.", e: "Sai: dress up like a pirate costume → Đúng: dress up as a pirate. Sai: dress up nice → Đúng: dress up nicely.", u: "IELTS Speaking (clothes, festivals): 'people dress up in áo dài during Tết'. Halloween: dress up as a ghost.", f: "dress up (phr v), dressed up (adj), dress down (mặc giản dị), get dressed" },
  "head off": { m: "Hình ảnh: hướng đầu (head) đi xa (off) → lên đường.", e: "Sai: we headed off to home → Đúng: we headed off home (home không cần 'to'). Sai: head off at the airport → head off to the airport.", u: "IELTS Speaking (travel, daily routine): 'we headed off early to avoid the traffic'.", f: "head off (phr v), set off, set out, leave (v), head for" },
  "get over": { m: "Hình ảnh: trèo qua (over) chướng ngại vật → vượt qua cú sốc, khỏi bệnh.", e: "Sai: get over from a cold → Đúng: get over a cold. Sai: I can't get over with it → Đúng: I can't get over it.", u: "IELTS Speaking (difficulties): 'it took me months to get over failing my driving test'.", f: "get over (phr v), recover from, overcome (v), move on, bounce back" },
  "stand out": { m: "Hình ảnh: một người đứng (stand) nhô ra (out) giữa đám đông → nổi bật.", e: "Sai: she stands out than others → Đúng: she stands out from others. Tính từ: outstanding, không nói 'standing out' thay.", u: "IELTS Speaking Part 2 (a building, a person): 'what makes it stand out is its colourful design'.", f: "stand out (phr v), outstanding (adj), standout (n/adj), noticeable (adj)" },
  "come down with": { m: "Hình ảnh: bệnh 'đổ xuống' (come down) người bạn → mắc bệnh nhẹ.", e: "Sai: I came down a cold → Đúng: I came down with a cold. Dùng cho bệnh nhẹ, không dùng cho cancer.", u: "IELTS Speaking (health, weather): 'I often come down with the flu when the seasons change'.", f: "come down with (phr v), catch (v), get sick, be under the weather" },
  "sign up for": { m: "Hình ảnh: ký (sign) tên lên (up) danh sách cho (for) khóa học → đăng ký.", e: "Sai: sign up a course → Đúng: sign up for a course. Sai: sign in for (đăng nhập) → Đúng: sign up for.", u: "IELTS Speaking (study, hobbies): 'I signed up for a cooking class last summer'.", f: "sign up for (phr v), sign-up (n), register for, enrol in, join (v)" },
  "give back": { m: "Hình ảnh: trao (give) ngược lại (back) cho cộng đồng đã nuôi lớn mình.", e: "Sai: give back for society → Đúng: give back to society. Trả đồ cụ thể: give it back, không nói give back it.", u: "IELTS Speaking (volunteering): 'successful people should give back to their communities'. Writing: corporate social responsibility.", f: "give back (phr v), contribute (v), donate (v), pay it forward, return (v)" },
  "count on": { m: "Hình ảnh: đếm (count) người đứng trên (on) danh sách tin cậy → trông cậy vào.", e: "Sai: you can count me → Đúng: you can count on me. Sai: count on him to helping → Đúng: count on him to help.", u: "IELTS Speaking (friends, family): 'my best friend is someone I can always count on'.", f: "count on (phr v), rely on, depend on, trust (v), reliable (adj)" },
  "run into": { m: "Hình ảnh: đang chạy (run) thì va vào (into) ai/thứ gì → tình cờ gặp, gặp rắc rối.", e: "Sai: I ran into with my teacher → Đúng: I ran into my teacher. Sai: run into a trouble → Đúng: run into trouble.", u: "IELTS Speaking: 'I ran into an old classmate at the supermarket'. Writing: projects run into financial problems.", f: "run into (phr v), bump into, come across, encounter (v), face (v)" },
  "opt for": { m: "Gần 'option' (lựa chọn) → opt for = chọn lấy phương án nào.", e: "Sai: I opted the cheaper one → Đúng: I opted for the cheaper one. Sai: opt for to go → Đúng: opt to go.", u: "IELTS Writing/Speaking: 'more consumers opt for electric cars'. Trang trọng hơn choose, hợp Task 2.", f: "opt (v), option (n), optional (adj), opt for, opt out (of)" },
  "get by": { m: "Hình ảnh: lách qua (get by) khe hẹp với vừa đủ chỗ → xoay xở vừa đủ sống.", e: "Sai: I can get by English → Đúng: I can get by in English. Sai: get by with low salary → Đúng: get by on a low salary.", u: "IELTS Speaking (money, languages): 'students get by on part-time jobs'. 'I know enough Thai to get by'.", f: "get by (phr v), manage (v), make ends meet, cope (v), scrape by" },
  "make up for": { m: "Hình ảnh: đắp (make up) thêm cho (for) phần bị hụt → bù đắp.", e: "Sai: make up the lost time → Đúng: make up for lost time. Sai: make up for to be late → make up for being late.", u: "IELTS Speaking: 'I study extra at weekends to make up for missed lessons'. Writing: compensate cho thiệt hại.", f: "make up for (phr v), compensate for, offset (v), make amends" },
  "brush up on": { m: "Hình ảnh: phủi (brush) bụi lên (up) kiến thức cũ → ôn lại cho sáng.", e: "Sai: brush up my English skill → Đúng: brush up on my English (Anh-Anh cũng nói brush up my English).", u: "IELTS Speaking (study, travel): 'I need to brush up on my French before the trip'.", f: "brush up on (phr v), revise (v), refresh (v), polish up, review (v)" },
  "look into": { m: "Hình ảnh: nhìn (look) sâu vào bên trong (into) sự việc → xem xét kỹ.", e: "Sai: we will look into about the problem → Đúng: we will look into the problem.", u: "IELTS Speaking (future plans): 'I'm looking into studying abroad'. Văn phòng: we'll look into your complaint.", f: "look into (phr v), investigate (v), examine (v), explore (v), research (v)" },
  "go back to": { m: "Hình ảnh: đi (go) ngược lại (back) tới (to) chỗ cũ, việc cũ.", e: "Sai: go back to home → Đúng: go back home. Sai: go back to study → Đúng: go back to studying / go back to school.", u: "IELTS Speaking (hometown, childhood): 'I'd love to go back to my primary school one day'.", f: "go back to (phr v), return to (v), revisit (v), come back to" },
  "slow down": { m: "Hình ảnh: kéo nhịp sống chậm (slow) xuống (down) như đạp phanh.", e: "Sai: you should slow → Đúng: you should slow down. Sai: slow down the speed of life → Đúng: slow down the pace of life.", u: "IELTS Speaking (lifestyle, stress): 'people in big cities rarely slow down'. Writing: the economy is slowing down.", f: "slow down (phr v), slowdown (n), slow (adj/v), decelerate (v), speed up (trái nghĩa)" },
  "turn up": { m: "Hình ảnh: như lá bài lật (turn) ngửa lên (up) → bất ngờ xuất hiện.", e: "Sai: he turned up at late → Đúng: he turned up late. Sai: few people turned up the meeting → Đúng: few people turned up for the meeting.", u: "IELTS Speaking (events): 'only a handful of guests turned up because of the rain'. Danh từ: turnout.", f: "turn up (phr v), show up, arrive (v), appear (v), turnout (n)" },
  "fit in": { m: "Hình ảnh: mảnh ghép vừa khít (fit) vào trong (in) bức tranh → hòa nhập.", e: "Sai: fit in the new class (thiếu with/at) → Đúng: fit in at the new school / fit in with my classmates.", u: "IELTS Speaking (moving, studying abroad): 'it took me a while to fit in at my new university'.", f: "fit in (phr v), blend in, belong (v), integrate (v), adapt (v)" },
  "take off": { m: "Hình ảnh: máy bay rời (off) mặt đất bay vút lên → sự nghiệp, xu hướng 'cất cánh'.", e: "Sai: her career was taken off → Đúng: her career took off (nội động từ, không bị động).", u: "IELTS Speaking (trends): 'online shopping really took off during the pandemic'. Writing: describe a sharp rise.", f: "take off (phr v), takeoff (n), boom (v), soar (v), skyrocket (v)" },
  "save up": { m: "Hình ảnh: để dành (save) tiền chồng dần lên (up) cho tới khi đủ mua thứ mình muốn.", e: "Sai: save up to a new laptop → Đúng: save up for a new laptop. Sai: save up money to buying → save up to buy.", u: "IELTS Speaking (money, shopping): 'I saved up for six months to buy my first motorbike'.", f: "save up (phr v), savings (n), put aside, set aside, splash out (trái nghĩa)" },
  "splash out on": { m: "Hình ảnh: té nước (splash) tung tóe → vung tiền tung tóe vào (on) món đồ đắt.", e: "Sai: splash out for a bag → Đúng: splash out on a bag. Sai: splash money → Đúng: splash out.", u: "IELTS Speaking (shopping, celebrations): 'I splashed out on a nice dinner for my mum's birthday'. Khẩu ngữ Anh-Anh.", f: "splash out on (phr v), splurge on, treat yourself, save up (trái nghĩa)" },
  "wind down": { m: "Hình ảnh: dây cót đồng hồ (wind) chạy chậm dần xuống (down) → thư giãn sau ngày dài.", e: "Sai: wind down myself → Đúng: wind down. Đọc wind /waɪnd/ như 'quấn', không phải /wɪnd/ (gió).", u: "IELTS Speaking (evening routine, stress): 'I read a novel to wind down before bed'.", f: "wind down (phr v), unwind (v), relax (v), chill out, de-stress (v)" },
  "stay in": { m: "Hình ảnh: ở lại (stay) bên trong (in) nhà thay vì ra phố.", e: "Sai: stay in home → Đúng: stay in / stay at home. Sai: I stayed in yesterday night → Đúng: I stayed in last night.", u: "IELTS Speaking Part 1 (weekends): 'I'm a homebody, so I prefer to stay in and cook'.", f: "stay in (phr v), stay at home, homebody (n), go out (trái nghĩa), night in (n)" },
  "put on": { m: "Hình ảnh: đặt (put) thêm lên (on) người → mặc áo vào, hoặc tăng cân.", e: "Sai: I put on weights → Đúng: I put on weight. Sai: put on clothes (đang mặc sẵn) → Đúng: wear clothes.", u: "IELTS Speaking (health, food): 'I put on a few kilos during the holidays'. Writing: obesity khi nói về cân nặng.", f: "put on (phr v), gain weight, wear (v), take off (cởi ra), lose weight" },
  "get round to": { m: "Hình ảnh: cuối cùng cũng 'đi vòng' (round) tới (to) việc bị bỏ xó lâu.", e: "Sai: I haven't got round to call her → Đúng: I haven't got round to calling her ('to' là giới từ).", u: "IELTS Speaking (habits, plans): 'I keep meaning to learn the piano but never get round to it'. Anh-Mỹ: get around to.", f: "get round to (phr v), get around to, eventually do, finally do, put off (trái nghĩa)" },
  "tidy up": { m: "Hình ảnh: sắp xếp gọn gàng (tidy) toàn bộ (up) căn phòng.", e: "Sai: tidy up my room clean → Đúng: tidy up my room. Sai: tidy up the dishes → Đúng: wash/clear the dishes.", u: "IELTS Speaking (home, housework): 'I tidy up my room every Sunday morning'.", f: "tidy up (phr v), tidy (adj/v), tidiness (n), clean up, messy (adj, trái nghĩa)" },
  "a piece of cake": { m: "Hình ảnh: ăn một miếng bánh ngọt – chẳng tốn sức gì → việc cực dễ.", e: "Sai: the test was piece of cake → Đúng: the test was a piece of cake (giữ mạo từ 'a'). Không dùng số nhiều.", u: "IELTS Speaking: 'the first part of the exam was a piece of cake, but the essay was tough'. Chỉ dùng văn nói.", f: "a piece of cake (idiom), a walk in the park, child's play, easy as pie" },
  "once in a blue moon": { m: "Hình ảnh: 'trăng xanh' – lần trăng tròn thứ hai trong tháng, rất hiếm → năm thì mười họa.", e: "Sai: I go swimming once in blue moon → Đúng: once in a blue moon. Đặt cuối câu tự nhiên hơn.", u: "IELTS Speaking Part 1 (frequency): 'I only eat fast food once in a blue moon'. Thay cho 'rarely'.", f: "once in a blue moon (idiom), rarely (adv), hardly ever, very seldom" },
  "hit the books": { m: "Hình ảnh: 'đập' vào sách vở – lao vào học hành cật lực.", e: "Sai: hit the book → Đúng: hit the books (luôn số nhiều, có 'the').", u: "IELTS Speaking (study): 'I need to hit the books before my finals'. Khẩu ngữ, tránh dùng trong Writing.", f: "hit the books (idiom), study hard, cram (v), burn the midnight oil" },
  "the best of both worlds": { m: "Hình ảnh: sống ở hai thế giới và lấy phần tốt nhất của cả hai → vẹn cả đôi đường.", e: "Sai: the best of both world → Đúng: the best of both worlds. Sai: have both worlds best → have the best of both worlds.", u: "IELTS Speaking (work, housing): 'living in the suburbs gives me the best of both worlds – quiet but close to the city'.", f: "the best of both worlds (idiom), win-win (adj), have your cake and eat it" },
  "break the bank": { m: "Hình ảnh: tiêu nhiều tới mức làm 'vỡ' cả ngân hàng → tốn quá nhiều tiền.", e: "Sai: it doesn't break my bank → Đúng: it doesn't break the bank. Thường dùng dạng phủ định.", u: "IELTS Speaking (shopping, travel): 'a trip to Đà Lạt won't break the bank'.", f: "break the bank (idiom), cost a fortune, cost an arm and a leg, affordable (adj)" },
  "cost an arm and a leg": { m: "Hình ảnh: phải đổi cả một cánh tay và một cái chân để mua → đắt cắt cổ.", e: "Sai: it costs a arm and leg → Đúng: it costs an arm and a leg. Sai: I cost an arm and a leg → Đúng: it cost me...", u: "IELTS Speaking (housing, shopping): 'renting a flat in the city centre costs an arm and a leg'.", f: "cost an arm and a leg (idiom), cost a fortune, pricey (adj), break the bank" },
  "under the weather": { m: "Hình ảnh: bị thời tiết xấu đè lên người → thấy uể oải, hơi ốm.", e: "Sai: I feel under weather → Đúng: I feel under the weather. Dùng cho mệt nhẹ, không dùng cho bệnh nặng.", u: "IELTS Speaking (health): 'I was a bit under the weather last week, so I stayed home'.", f: "under the weather (idiom), unwell (adj), off colour, poorly (adj, Anh-Anh)" },
  "a breath of fresh air": { m: "Hình ảnh: hít một hơi không khí trong lành giữa phòng ngột ngạt → điều mới mẻ dễ chịu.", e: "Sai: she is a fresh air → Đúng: she is a breath of fresh air. Sai: breath (n) nhầm với breathe (v).", u: "IELTS Speaking Part 2 (a person, a film): 'the new teacher was a breath of fresh air in our school'.", f: "a breath of fresh air (idiom), refreshing (adj), a welcome change, novel (adj)" },
  "on the go": { m: "Hình ảnh: lúc nào cũng trong trạng thái 'đang đi' – không ngồi yên một chỗ.", e: "Sai: I am always on go → Đúng: I am always on the go. Sai: eating on the going → Đúng: eating on the go.", u: "IELTS Speaking (lifestyle, food): 'busy office workers eat on the go'. Cũng: snacks for people on the go.", f: "on the go (idiom), busy (adj), hectic (adj), on the move, rushed off your feet" },
  "couch potato": { m: "Hình ảnh: củ khoai tây nằm ì trên ghế sofa (couch) cả ngày xem TV.", e: "Sai: he is couch potato → Đúng: he is a couch potato. Số nhiều: couch potatoes (thêm -es).", u: "IELTS Speaking (health, free time): 'I used to be a couch potato, but now I jog every morning'.", f: "couch potato (n, idiom), sedentary (adj), lazy (adj), homebody (n)" },
  "in the long run": { m: "Hình ảnh: một cuộc chạy đường dài (long run) – kết quả chỉ thấy khi về đích.", e: "Sai: in a long run → Đúng: in the long run. Sai: in long term → Đúng: in the long term.", u: "IELTS Writing Task 2: 'investing in public transport will save money in the long run'. Ăn điểm Coherence.", f: "in the long run (idiom), in the long term, eventually (adv), in the short run (trái nghĩa)" },
  "get the hang of": { m: "Hình ảnh: nắm được 'cái cách treo' (hang) đồ cho đúng → quen tay, biết cách làm.", e: "Sai: get the hang of to drive → Đúng: get the hang of driving. Sai: get a hang of → Đúng: get the hang of.", u: "IELTS Speaking (skills, technology): 'it took me a week to get the hang of the new software'.", f: "get the hang of (idiom), master (v), get used to, learn the ropes" },
  "call it a day": { m: "Hình ảnh: tuyên bố 'thế là đủ một ngày' (call it a day) rồi buông việc.", e: "Sai: let's call it the day → Đúng: let's call it a day. Buổi tối có thể nói call it a night.", u: "IELTS Speaking (work, study): 'after eight hours of revision, I decided to call it a day'.", f: "call it a day (idiom), call it a night, wrap up, knock off, finish (v)" },
  "burn the midnight oil": { m: "Hình ảnh: đốt dầu đèn tới nửa đêm để làm việc, như sĩ tử thời xưa.", e: "Sai: burn the midnight oils → Đúng: burn the midnight oil (oil không đếm được).", u: "IELTS Speaking (study, work): 'I burned the midnight oil before my IELTS test'. Khẩu ngữ, không dùng Writing.", f: "burn the midnight oil (idiom), stay up late, pull an all-nighter, night owl" },
  "see eye to eye": { m: "Hình ảnh: hai người nhìn thẳng mắt nhau, cùng tầm nhìn → đồng quan điểm.", e: "Sai: we see eyes to eyes → Đúng: we see eye to eye. Sai: see eye to eye about him → see eye to eye with him.", u: "IELTS Speaking (family, generation gap): 'my parents and I don't always see eye to eye on careers'.", f: "see eye to eye (idiom), agree (v), be on the same page, disagree (trái nghĩa)" },
  "not my cup of tea": { m: "Hình ảnh: kiểu người Anh nói 'không phải tách trà của tôi' → không hợp gu.", e: "Sai: it is not my tea cup → Đúng: it's not my cup of tea. Sai: horror films are not my cups of tea → not my cup of tea.", u: "IELTS Speaking Part 1 (music, sport): 'jazz isn't really my cup of tea – I prefer pop'.", f: "not my cup of tea (idiom), not my thing, not into, not keen on" },
  "go the extra mile": { m: "Hình ảnh: đi thêm một dặm (extra mile) dù đường đã đủ xa → làm hơn mức yêu cầu.", e: "Sai: go an extra mile for → Đúng: go the extra mile for. Sai: go the extra miles → Đúng: go the extra mile.", u: "IELTS Speaking Part 2 (a helpful person, service): 'the hotel staff went the extra mile to help us'.", f: "go the extra mile (idiom), go above and beyond, make an extra effort" },
  "the tip of the iceberg": { m: "Hình ảnh: chỉ phần chóp (tip) tảng băng nổi lên, phần lớn chìm dưới nước.", e: "Sai: it's only a top of iceberg → Đúng: it's only the tip of the iceberg.", u: "IELTS Writing Task 2 (crime, pollution): 'reported cases are only the tip of the iceberg'. Hợp văn viết bán trang trọng.", f: "the tip of the iceberg (idiom), a small part, the surface, hidden problem" },
  "keep an eye on": { m: "Hình ảnh: giữ (keep) một con mắt đặt lên (on) thứ gì → trông chừng.", e: "Sai: keep eyes on my bag → Đúng: keep an eye on my bag. Sai: keep an eye for → Đúng: keep an eye on.", u: "IELTS Speaking (family, children): 'grandparents often keep an eye on the kids while parents work'.", f: "keep an eye on (idiom), watch (v), monitor (v), look after, supervise (v)" },
  "out of the blue": { m: "Hình ảnh: tia sét đánh ra từ bầu trời xanh (blue) không mây → hoàn toàn bất ngờ.", e: "Sai: out of blue → Đúng: out of the blue. Sai: an out of blue call → Đúng: a call out of the blue.", u: "IELTS Speaking Part 2 (a surprise): 'an old friend called me out of the blue last month'.", f: "out of the blue (idiom), unexpectedly (adv), suddenly (adv), all of a sudden" },
  "over the moon": { m: "Hình ảnh: vui đến mức nhảy qua cả mặt trăng.", e: "Sai: I was over the moon of the result → Đúng: I was over the moon about/with the result.", u: "IELTS Speaking Part 2 (good news, achievement): 'I was over the moon when I got my scholarship'.", f: "over the moon (idiom), thrilled (adj), delighted (adj), on cloud nine, ecstatic (adj)" },
  "take it easy": { m: "Hình ảnh: cầm (take) mọi chuyện một cách nhẹ nhàng (easy) → thư giãn, đừng gắng quá.", e: "Sai: take easy → Đúng: take it easy (không bỏ 'it'). Sai: I take it easily → Đúng: I take it easy.", u: "IELTS Speaking (weekends, holidays): 'on Sundays I just take it easy at home'.", f: "take it easy (idiom), relax (v), chill out, unwind (v), easy-going (adj)" },
  "through thick and thin": { m: "Hình ảnh: đi xuyên qua rừng rậm (thick) lẫn rừng thưa (thin) cùng nhau → lúc sướng lúc khổ.", e: "Sai: through thin and thick → Đúng: through thick and thin (giữ đúng trật tự).", u: "IELTS Speaking Part 2 (a friend): 'she has stood by me through thick and thin'.", f: "through thick and thin (idiom), stand by someone, loyal (adj), through good times and bad" },
  "a blessing in disguise": { m: "Hình ảnh: phước lành (blessing) đội lốt (in disguise) một điều xui → trong rủi có may.", e: "Sai: it was blessing in disguise → Đúng: it was a blessing in disguise. Sai: disguised blessing (ít tự nhiên).", u: "IELTS Speaking Part 2 (a failure, a change): 'losing that job was a blessing in disguise'.", f: "a blessing in disguise (idiom), every cloud has a silver lining, lucky break" },
  "ring a bell": { m: "Hình ảnh: cái tên làm chuông (bell) trong đầu khẽ reo lên → nghe quen quen.", e: "Sai: it rings bell → Đúng: it rings a bell. Sai: his name rings me a bell → Đúng: his name rings a bell.", u: "IELTS Speaking (memory, people): 'the name rings a bell, but I can't remember where we met'.", f: "ring a bell (idiom), sound familiar, familiar (adj), jog your memory" },
  "from scratch": { m: "Hình ảnh: vạch xuất phát (scratch) khắc trên mặt đất, mọi người bắt đầu từ đó → từ con số không.", e: "Sai: from the scratch → Đúng: from scratch (không mạo từ). Sai: start at scratch → Đúng: start from scratch.", u: "IELTS Speaking (cooking, business): 'I baked the cake from scratch'. Writing: rebuild the system from scratch.", f: "from scratch (idiom), from the ground up, from nothing, start over" },
  "learn the ropes": { m: "Hình ảnh: thủy thủ mới phải học cách buộc dây thừng (ropes) trên thuyền buồm.", e: "Sai: learn the rope → Đúng: learn the ropes (số nhiều). Người dạy: show someone the ropes.", u: "IELTS Speaking (work, first job): 'during my first month, a senior colleague helped me learn the ropes'.", f: "learn the ropes (idiom), show someone the ropes, get the hang of, newcomer (n)" },
  "on a shoestring": { m: "Hình ảnh: ngân sách mỏng như sợi dây giày (shoestring).", e: "Sai: travel on shoestring → Đúng: travel on a shoestring. Tính từ: a shoestring budget.", u: "IELTS Speaking (travel, students): 'as a student, I travelled around Thailand on a shoestring'.", f: "on a shoestring (idiom), shoestring budget (n), on a tight budget, cheaply (adv)" },
  "a far cry from": { m: "Hình ảnh: cách xa tới mức gọi to (cry) cũng không nghe → khác xa.", e: "Sai: it is far cry with → Đúng: it is a far cry from. Giới từ luôn là 'from'.", u: "IELTS Speaking/Writing (change over time): 'today's city is a far cry from the quiet town I grew up in'.", f: "a far cry from (idiom), very different from, poles apart, nothing like" },
  "hustle and bustle": { m: "Âm láy 'hustle – bustle' như tiếng xe cộ, người chen chúc → ồn ào náo nhiệt.", e: "Sai: bustle and hustle → Đúng: hustle and bustle. Sai: the hustle and bustle city → Đúng: the hustle and bustle of the city.", u: "IELTS Speaking (city life): 'I sometimes need to escape the hustle and bustle of Hồ Chí Minh City'.", f: "hustle and bustle (n), bustling (adj), hectic (adj), busy (adj), tranquil (trái nghĩa)" },
  "off the beaten track": { m: "Hình ảnh: rẽ khỏi (off) con đường mòn (beaten track) nhiều người đã giẫm → nơi hẻo lánh.", e: "Sai: out of the beaten track → Đúng: off the beaten track. Anh-Mỹ hay nói off the beaten path.", u: "IELTS Speaking Part 2 (a place you visited): 'Hà Giang is off the beaten track but absolutely stunning'.", f: "off the beaten track (idiom), off the beaten path, remote (adj), secluded (adj)" },
  "the ins and outs": { m: "Hình ảnh: biết mọi lối vào (ins) lối ra (outs) của một tòa nhà → rành mọi chi tiết.", e: "Sai: the ins and outs about the job → Đúng: the ins and outs of the job. Sai: the in and out → the ins and outs.", u: "IELTS Speaking (work, hobbies): 'my mentor taught me the ins and outs of photography'.", f: "the ins and outs (idiom), details (n), nuts and bolts, the nitty-gritty" },
  "have a lot on my plate": { m: "Hình ảnh: đĩa ăn (plate) chất đầy món – ăn mãi không hết → quá nhiều việc.", e: "Sai: I have many on my plate → Đúng: I have a lot on my plate. Đổi đại từ: she has a lot on her plate.", u: "IELTS Speaking (work, study): 'I have a lot on my plate this term with exams and a part-time job'.", f: "have a lot on one's plate (idiom), swamped (adj), snowed under, busy (adj)" },
  "up in the air": { m: "Hình ảnh: đồng xu tung lên không trung (in the air), chưa biết rơi mặt nào.", e: "Sai: my plan is on the air → Đúng: my plan is up in the air ('on the air' là đang phát sóng).", u: "IELTS Speaking (future plans): 'my plans for next year are still up in the air'.", f: "up in the air (idiom), undecided (adj), uncertain (adj), unsettled (adj)" },
  "night owl": { m: "Hình ảnh: con cú (owl) thức suốt đêm (night) → người hay thức khuya.", e: "Sai: I am night owl → Đúng: I am a night owl. Sai: night bird (ít dùng) → Đúng: night owl.", u: "IELTS Speaking Part 1 (daily routine, sleep): 'I'm definitely a night owl – I study best after 10 p.m.'.", f: "night owl (n), early bird (trái nghĩa), stay up late, nocturnal (adj)" },
  "early bird": { m: "Chim dậy sớm bắt được sâu – 'the early bird catches the worm' → người dậy sớm.", e: "Sai: I am early bird → Đúng: I am an early bird (dùng 'an' trước early).", u: "IELTS Speaking (routine): 'I'm an early bird, so I go jogging at 5 a.m.'. Marketing: early-bird discount.", f: "early bird (n), early-bird (adj: early-bird ticket), morning person, night owl (trái nghĩa)" },
  "learn by heart": { m: "Hình ảnh: khắc bài vào tim (heart) → thuộc lòng không cần nhìn sách.", e: "Sai: learn by my heart → Đúng: learn something by heart. Sai: learn heart the poem → Đúng: learn the poem by heart.", u: "IELTS Speaking (education): 'at primary school we had to learn poems by heart'. Writing: rote learning.", f: "learn by heart (idiom), memorise (v), rote learning (n), know by heart" },
  "at the drop of a hat": { m: "Hình ảnh: chỉ cần chiếc mũ rơi xuống (hiệu lệnh) là lao đi ngay → không chần chừ.", e: "Sai: at a drop of hat → Đúng: at the drop of a hat. Đặt cuối mệnh đề.", u: "IELTS Speaking (travel, personality): 'I'd fly to Japan at the drop of a hat if I had the money'.", f: "at the drop of a hat (idiom), immediately (adv), without hesitation, in a heartbeat" },
  "spoilt for choice": { m: "Hình ảnh: được chiều hư (spoilt) vì có quá nhiều thứ để chọn.", e: "Sai: spoiled of choice → Đúng: spoilt/spoiled for choice. Sai: I am spoilt for choices → Đúng: spoilt for choice.", u: "IELTS Speaking (food, shopping): 'in Hà Nội you're spoilt for choice when it comes to street food'.", f: "spoilt for choice (idiom), plenty of options, a wide range of, a wealth of" },
  "in the middle of nowhere": { m: "Hình ảnh: đứng ngay giữa 'chẳng nơi nào' – không nhà, không đường → khỉ ho cò gáy.", e: "Sai: in middle of nowhere → Đúng: in the middle of nowhere. Sai: at the middle of nowhere → Đúng: in the middle.", u: "IELTS Speaking (places, holidays): 'the resort was in the middle of nowhere, perfect for switching off'.", f: "in the middle of nowhere (idiom), remote (adj), isolated (adj), off the beaten track" },
  "glued to the screen": { m: "Hình ảnh: mắt bị dính keo (glued) vào màn hình, không rời ra được.", e: "Sai: glued on the screen → Đúng: glued to the screen. Sai: kids glue to phones → Đúng: kids are glued to their phones.", u: "IELTS Speaking/Writing (technology, children): 'many teenagers are glued to their screens for hours'.", f: "glued to the screen (idiom), screen time (n), addicted to, hooked on" },
  "bite off more than you can chew": { m: "Hình ảnh: cắn một miếng to hơn mức nhai nổi → nhận việc quá sức.", e: "Sai: bite more than you can chew → Đúng: bite off more than you can chew (không bỏ 'off').", u: "IELTS Speaking (work, study): 'I bit off more than I could chew by taking five courses'.", f: "bite off more than you can chew (idiom), overcommit (v), take on too much, overstretch (v)" },
  "sleep on it": { m: "Hình ảnh: ngủ một đêm trên quyết định → sáng ra đầu óc tỉnh táo mới chốt.", e: "Sai: let me sleep with it → Đúng: let me sleep on it. Sai: sleep on that decision tomorrow → Đúng: sleep on it.", u: "IELTS Speaking (decisions): 'when I face a big decision, I usually sleep on it first'.", f: "sleep on it (idiom), think it over, mull over, consider (v)" },
  "word of mouth": { m: "Hình ảnh: lời nói (word) đi từ miệng (mouth) người này sang người khác → truyền miệng.", e: "Sai: by the word of mouth → Đúng: by word of mouth. Tính từ: word-of-mouth advertising.", u: "IELTS Speaking/Writing (advertising, business): 'small restaurants rely on word of mouth rather than ads'.", f: "word of mouth (n), word-of-mouth (adj), recommendation (n), buzz (n), viral (adj)" },
  "go with the flow": { m: "Hình ảnh: thả mình trôi theo dòng nước (flow), không bơi ngược.", e: "Sai: go with flow → Đúng: go with the flow. Sai: follow the flow (ít tự nhiên) → go with the flow.", u: "IELTS Speaking (personality, travel): 'on holiday I don't plan much – I just go with the flow'.", f: "go with the flow (idiom), easy-going (adj), play it by ear, adaptable (adj)" },
  "make ends meet": { m: "Hình ảnh: kéo hai đầu (ends) sợi dây thu chi cho gặp (meet) nhau → đủ sống.", e: "Sai: make the end meet → Đúng: make ends meet. Sai: make ends meet with money → Đúng: struggle to make ends meet.", u: "IELTS Writing (poverty, cost of living): 'many families struggle to make ends meet'. Speaking: part-time jobs.", f: "make ends meet (idiom), get by, scrape by, live hand to mouth, cope (v)" },
  "a stone's throw from": { m: "Hình ảnh: khoảng cách chỉ bằng một lần ném hòn đá (stone) → rất gần.", e: "Sai: a stone throw from → Đúng: a stone's throw from (có 's). Sai: stone's throw to → Đúng: from.", u: "IELTS Speaking (home, accommodation): 'my flat is a stone's throw from the beach'.", f: "a stone's throw from (idiom), within walking distance, close to, nearby (adj)" },
  "the last straw": { m: "Hình ảnh: cọng rơm (straw) cuối cùng làm gãy lưng lạc đà → giọt nước tràn ly.", e: "Sai: the last drop → Đúng: the last straw (tiếng Anh dùng rơm, không dùng giọt nước).", u: "IELTS Speaking Part 2 (a decision, a complaint): 'the noise at 2 a.m. was the last straw, so I moved out'.", f: "the last straw (idiom), the final straw, the straw that broke the camel's back" },
  "play it by ear": { m: "Hình ảnh: nhạc công chơi theo tai nghe (by ear), không cần bản nhạc → tùy cơ ứng biến.", e: "Sai: play by ear it → Đúng: play it by ear. Sai: play it by ears → Đúng: play it by ear.", u: "IELTS Speaking (plans, travel): 'we haven't booked anything – we'll play it by ear'.", f: "play it by ear (idiom), improvise (v), go with the flow, wing it" },
  "in the blink of an eye": { m: "Hình ảnh: chỉ trong một cái chớp (blink) mắt → nhanh vô cùng.", e: "Sai: in a blink of eye → Đúng: in the blink of an eye. Sai: in the blink of the eyes → Đúng: of an eye.", u: "IELTS Speaking (time, childhood): 'my university years went by in the blink of an eye'.", f: "in the blink of an eye (idiom), in a flash, instantly (adv), in no time" },
  "breathtaking": { m: "breath (hơi thở) + taking (lấy mất) → đẹp đến nghẹt thở.", e: "Sai: a breath-taken view → Đúng: a breathtaking view. Sai: very breathtaking → Đúng: absolutely breathtaking.", u: "IELTS Speaking Part 2 (a place): 'the view from the top of Fansipan was breathtaking'. Thay cho 'very beautiful'.", f: "breathtaking (adj), breathtakingly (adv), take your breath away, stunning, spectacular" },
  "down-to-earth": { m: "Hình ảnh: chân luôn chạm đất (down to earth) – không bay bổng, không làm cao → giản dị.", e: "Sai: he is very down to earth person → Đúng: he is a very down-to-earth person (có gạch nối trước danh từ).", u: "IELTS Speaking Part 2 (a person you admire): 'despite being famous, she's really down-to-earth'.", f: "down-to-earth (adj), humble (adj), unpretentious (adj), modest (adj), arrogant (trái nghĩa)" },
  "easy-going": { m: "easy (dễ) + going (đi) → đi đâu cũng dễ, chuyện gì cũng xuề xòa → dễ tính.", e: "Sai: she is easy going with → Đúng: she is easy-going. Sai: an easy-go person → Đúng: an easy-going person.", u: "IELTS Speaking (personality, friends): 'my roommate is very easy-going, so we never argue'.", f: "easy-going (adj), laid-back (adj), relaxed (adj), go with the flow, uptight (trái nghĩa)" },
  "picturesque": { m: "picture (bức tranh) + -esque (giống như) → đẹp như tranh vẽ.", e: "Sai: a picturesque person → Đúng: a picturesque village (dùng cho cảnh, không cho người). Đọc /ˌpɪk.tʃərˈesk/.", u: "IELTS Speaking Part 2 (a place, hometown): 'Hội An is a picturesque town with lantern-lit streets'.", f: "picturesque (adj), picture (n), scenic (adj), idyllic (adj), quaint (adj)" },
  "bustling": { m: "Âm 'bus-' như tiếng xe buýt, xe cộ bấm còi rộn ràng → phố xá tấp nập.", e: "Sai: a bustle city → Đúng: a bustling city. Sai: bustling with people crowded → Đúng: bustling with people.", u: "IELTS Speaking (hometown, city): 'I live in a bustling district full of street vendors'. Writing: urbanisation.", f: "bustle (n/v), bustling (adj), hustle and bustle (n), busy (adj), lively (adj)" },
  "tranquil": { m: "Gần 'tranquilliser' (thuốc an thần) → khung cảnh làm lòng lắng dịu → yên tĩnh.", e: "Sai: a tranquil person → Đúng: a tranquil lake / setting (thường cho cảnh vật). Danh từ: tranquillity.", u: "IELTS Speaking Part 2 (a quiet place): 'the countryside is tranquil, far from city noise'.", f: "tranquil (adj), tranquillity (n), tranquilly (adv), peaceful (adj), serene (adj)" },
  "vibrant": { m: "Gần 'vibrate' (rung) → nơi chốn rung lên vì năng lượng, màu sắc → sôi động, rực rỡ.", e: "Sai: a vibrating city → Đúng: a vibrant city. Sai: vibrant of colours → Đúng: vibrant colours / vibrant with colour.", u: "IELTS Speaking (cities, culture): 'Bangkok has a vibrant nightlife'. Writing: a vibrant economy.", f: "vibrant (adj), vibrancy (n), vibrantly (adv), lively (adj), dynamic (adj)" },
  "spectacular": { m: "Cùng gốc 'spectator' (khán giả) → cảnh đáng để cả khán đài ngắm → ngoạn mục.", e: "Sai: a spectacle view (spectacle là danh từ) → Đúng: a spectacular view. Sai: very spectacular → Đúng: truly spectacular.", u: "IELTS Speaking Part 2 (an event, nature): 'the fireworks on New Year's Eve were spectacular'.", f: "spectacle (n), spectacular (adj), spectacularly (adv), spectator (n), breathtaking (adj)" },
  "unforgettable": { m: "un- (không) + forget (quên) + -able (có thể) → không thể nào quên.", e: "Sai: an unforgotten trip (ít dùng) → Đúng: an unforgettable trip. Sai: very unforgettable → Đúng: truly unforgettable.", u: "IELTS Speaking Part 2 (an experience, a trip): 'my first trip abroad was an unforgettable experience'.", f: "forget (v), forgettable (adj), unforgettable (adj), unforgettably (adv), memorable (adj)" },
  "memorable": { m: "memory (ký ức) + -able → đáng để giữ trong ký ức → đáng nhớ.", e: "Sai: a memorial day (ngày tưởng niệm) dùng nhầm → Đúng: a memorable day. Sai: memorizable → memorable.", u: "IELTS Speaking Part 2 (a birthday, a journey): 'the most memorable part was watching the sunrise'.", f: "memory (n), memorable (adj), memorably (adv), memorise (v), memorial (n, khác nghĩa)" },
  "cosy": { m: "Âm 'cô-zi' như cái chăn ấm trong căn phòng nhỏ mùa đông → ấm cúng.", e: "Sai: a cosy weather → Đúng: cosy room / café (dùng cho không gian). Anh-Mỹ viết cozy.", u: "IELTS Speaking (home, café): 'my favourite café is small and cosy with soft lighting'.", f: "cosy (adj), cosiness (n), cosily (adv), snug (adj), warm and welcoming" },
  "run-down": { m: "Hình ảnh: tòa nhà 'chạy xuống dốc' (run down) theo năm tháng → xuống cấp.", e: "Sai: a run down building (thiếu gạch nối trước danh từ) → Đúng: a run-down building. Cũng nghĩa 'mệt mỏi': feel run-down.", u: "IELTS Speaking/Writing (housing, urban areas): 'the government renovated many run-down neighbourhoods'.", f: "run-down (adj), dilapidated (adj), shabby (adj), neglected (adj), well-maintained (trái nghĩa)" },
  "lively": { m: "live (sống) + -ly → tràn đầy sức sống → sôi nổi. Chú ý: là tính từ, không phải trạng từ.", e: "Sai: she talked lively → Đúng: she talked in a lively way. Sai: a live atmosphere → Đúng: a lively atmosphere.", u: "IELTS Speaking (places, people): 'the night market is really lively at weekends'.", f: "life (n), lively (adj), liveliness (n), liven up (v), vibrant (adj)" },
  "charismatic": { m: "charisma (sức hút đặc biệt) + -tic → người có 'hào quang' làm người khác bị cuốn theo.", e: "Sai: he has charismatic → Đúng: he is charismatic / he has charisma. Đọc /ˌkær.ɪzˈmæt.ɪk/, âm đầu 'k'.", u: "IELTS Speaking Part 2 (a leader, a teacher): 'our coach was so charismatic that everyone listened to him'.", f: "charisma (n), charismatic (adj), charismatically (adv), magnetic (adj), inspiring (adj)" },
  "outgoing": { m: "out (ra ngoài) + going (đi) → người thích đi ra ngoài gặp gỡ → hướng ngoại.", e: "Sai: she is very outgo → Đúng: she is very outgoing. Đừng nhầm với outgoings (n, Anh-Anh: các khoản chi tiêu).", u: "IELTS Speaking Part 1 (personality): 'I'm quite outgoing, so I enjoy meeting new people'.", f: "outgoing (adj), extroverted (adj), sociable (adj), introverted (trái nghĩa), shy (adj)" },
  "hard-working": { m: "hard (vất vả) + working (làm việc) → làm việc cật lực → chăm chỉ.", e: "Sai: he is hardly working → Đúng: he is hard-working (hardly = hầu như không). Sai: work hardly → work hard.", u: "IELTS Speaking (people, colleagues): 'my mother is the most hard-working person I know'.", f: "hard-working (adj), hard work (n), work hard (v), diligent (adj), industrious (adj)" },
  "witty": { m: "wit (sự nhanh trí) + -y → nói câu nào cũng thông minh và buồn cười → dí dỏm.", e: "Sai: a witty joke person → Đúng: a witty person / witty remark. Witty khác funny: cần thông minh, nhanh trí.", u: "IELTS Speaking Part 2 (a friend, a comedian): 'he's witty and always lightens the mood'.", f: "wit (n), witty (adj), wittily (adv), quick-witted (adj), humorous (adj)" },
  "laid-back": { m: "Hình ảnh: ngả lưng (laid back) ra ghế thư thái → thoải mái, không vội vàng.", e: "Sai: a lay-back lifestyle → Đúng: a laid-back lifestyle. Sai: I feel laid back myself → Đúng: I feel laid-back.", u: "IELTS Speaking (lifestyle, hometown): 'life in Đà Lạt is much more laid-back than in Sài Gòn'.", f: "laid-back (adj), relaxed (adj), easy-going (adj), chilled-out (adj), uptight (trái nghĩa)" },
  "thought-provoking": { m: "thought (suy nghĩ) + provoking (khơi gợi) → khơi dậy suy nghĩ của người xem.", e: "Sai: a thought-provoked film → Đúng: a thought-provoking film (đuôi -ing cho vật gây ra cảm giác).", u: "IELTS Speaking Part 2 (a film, a book): 'it was a thought-provoking documentary about climate change'.", f: "thought-provoking (adj), provoke (v), stimulating (adj), insightful (adj)" },
  "nerve-racking": { m: "nerve (thần kinh) + rack (cái giá kéo căng) → kéo căng dây thần kinh → căng thẳng.", e: "Sai: I was nerve-racking → Đúng: it was nerve-racking / I was nervous. Cũng viết nerve-wracking.", u: "IELTS Speaking (exams, interviews): 'my first job interview was incredibly nerve-racking'.", f: "nerve-racking (adj), nervous (adj), nerves (n), stressful (adj), tense (adj)" },
  "rewarding": { m: "reward (phần thưởng) + -ing → công việc tự nó là phần thưởng tinh thần.", e: "Sai: I feel rewarding → Đúng: I find it rewarding / the job is rewarding. Không phải nói về tiền thưởng.", u: "IELTS Speaking (work, volunteering): 'teaching is a challenging but rewarding job'.", f: "reward (n/v), rewarding (adj), unrewarding (adj), fulfilling (adj), satisfying (adj)" },
  "exhilarating": { m: "Gần 'hilarious' (vui cười) → cảm giác vui sướng dâng trào, tim đập mạnh.", e: "Sai: I was exhilarating → Đúng: I was exhilarated / it was exhilarating. Đọc /ɪɡˈzɪl.ə.reɪ.tɪŋ/.", u: "IELTS Speaking Part 2 (an adventure): 'paragliding over the valley was exhilarating'.", f: "exhilarate (v), exhilarating (adj), exhilarated (adj), exhilaration (n), thrilling (adj)" },
  "hilarious": { m: "Âm 'hi-la' như tiếng cười 'hi hi, ha ha' → cực kỳ buồn cười.", e: "Sai: very hilarious → Đúng: absolutely hilarious (tính từ mạnh, không dùng 'very'). Đọc /hɪˈleə.ri.əs/.", u: "IELTS Speaking (films, friends): 'the comedy was absolutely hilarious – I couldn't stop laughing'.", f: "hilarious (adj), hilariously (adv), hilarity (n), hysterical (adj), very funny" },
  "mouth-watering": { m: "Hình ảnh: nhìn món ăn tới mức nước (water) chảy trong miệng (mouth).", e: "Sai: mouth-watered dishes → Đúng: mouth-watering dishes. Sai: watering-mouth → Đúng: mouth-watering.", u: "IELTS Speaking (food, local dishes): 'the market is full of mouth-watering street food like bánh xèo'.", f: "mouth-watering (adj), delicious (adj), appetising (adj), tempting (adj), scrumptious (adj)" },
  "stunning": { m: "stun (làm choáng) + -ing → đẹp tới mức choáng váng, đứng hình.", e: "Sai: I was stunning by the view → Đúng: I was stunned by the view / the view was stunning.", u: "IELTS Speaking Part 2 (places, photos): 'the beaches in Phú Quốc are stunning'.", f: "stun (v), stunning (adj), stunned (adj), stunningly (adv), gorgeous (adj)" },
  "idyllic": { m: "Gần 'idyll' (thơ đồng quê) → khung cảnh như trong bài thơ điền viên → thơ mộng.", e: "Sai: an idyllic person → Đúng: an idyllic setting / childhood. Đọc /ɪˈdɪl.ɪk/, không đọc 'ai-đi-lic'.", u: "IELTS Speaking (countryside, childhood): 'I had an idyllic childhood in a small village'.", f: "idyll (n), idyllic (adj), idyllically (adv), picturesque (adj), tranquil (adj)" },
  "magnificent": { m: "magni- (lớn, như 'magnify') → công trình lớn lao, tráng lệ.", e: "Sai: a magnificent price → Đúng: a magnificent palace / view. Sai: magnificently building → Đúng: magnificent building.", u: "IELTS Speaking Part 2 (a building): 'the Imperial City in Huế is magnificent'. Writing: describe architecture.", f: "magnificent (adj), magnificence (n), magnificently (adv), grand (adj), splendid (adj)" },
  "quaint": { m: "Hình ảnh: căn nhà gỗ nhỏ kiểu xưa, hơi lạ mà duyên dáng → cổ kính, xinh xắn.", e: "Sai: a quaint skyscraper → Đúng: a quaint cottage / village (dùng cho cái cũ, nhỏ, duyên). Đọc /kweɪnt/.", u: "IELTS Speaking (towns, cafés): 'we stayed in a quaint guesthouse in the old quarter'.", f: "quaint (adj), quaintly (adv), quaintness (n), charming (adj), old-fashioned (adj)" },
  "eye-opening": { m: "Hình ảnh: trải nghiệm làm mắt mở to (eye-opening) ra, thấy điều mới.", e: "Sai: an eye-opened trip → Đúng: an eye-opening trip. Danh từ: an eye-opener.", u: "IELTS Speaking Part 2 (travel, volunteering): 'volunteering in rural areas was truly eye-opening'.", f: "eye-opening (adj), eye-opener (n), enlightening (adj), revealing (adj), insightful (adj)" },
  "overwhelming": { m: "over (quá) + whelm (nhấn chìm) → cảm xúc/khối lượng nhấn chìm mình → choáng ngợp.", e: "Sai: I am overwhelming → Đúng: I am overwhelmed / the workload is overwhelming.", u: "IELTS Speaking (stress, cities): 'the amount of choice in big shopping malls can be overwhelming'.", f: "overwhelm (v), overwhelming (adj), overwhelmed (adj), overwhelmingly (adv)" },
  "nostalgic": { m: "nostos (trở về nhà, gốc Hy Lạp) + algia (đau) → nỗi đau nhớ ngày xưa → hoài niệm.", e: "Sai: I feel nostalgic of my childhood → Đúng: nostalgic about/for my childhood.", u: "IELTS Speaking (childhood, music): 'old songs make me feel nostalgic about my school days'.", f: "nostalgia (n), nostalgic (adj), nostalgically (adv), sentimental (adj), wistful (adj)" },
  "gripping": { m: "grip (nắm chặt) + -ing → câu chuyện nắm chặt lấy bạn, không buông được.", e: "Sai: I was gripping by the story → Đúng: I was gripped by the story / the story was gripping.", u: "IELTS Speaking Part 2 (a book, a film): 'the thriller was so gripping that I finished it in one night'.", f: "grip (n/v), gripping (adj), gripped (adj), page-turner (n), compelling (adj)" },
  "inspiring": { m: "in (vào) + spire (thở, như 'respiration') → thổi luồng hơi mới vào người khác → truyền cảm hứng.", e: "Sai: I felt inspiring → Đúng: I felt inspired / her speech was inspiring.", u: "IELTS Speaking Part 2 (a person, a talk): 'her story of overcoming poverty is truly inspiring'.", f: "inspire (v), inspiring (adj), inspired (adj), inspiration (n), inspirational (adj)" },
  "jaw-dropping": { m: "Hình ảnh: kinh ngạc tới mức quai hàm (jaw) rơi xuống (dropping) → há hốc mồm.", e: "Sai: a jaw-dropped scene → Đúng: a jaw-dropping scene. Không nói 'very jaw-dropping'.", u: "IELTS Speaking (places, performances): 'the view of Hạ Long Bay was jaw-dropping'.", f: "jaw-dropping (adj), astonishing (adj), stunning (adj), breathtaking (adj), mind-blowing (adj)" },
  "in addition": { m: "addition = phép cộng → cộng thêm một ý nữa vào lập luận.", e: "Sai: In addition, to this → Đúng: In addition to this, ... Sai: in addition to protect → Đúng: in addition to protecting.", u: "IELTS Writing Task 2: mở ý bổ sung 'In addition, public transport reduces emissions'. Đầu câu, có dấu phẩy.", f: "in addition (to) (phrase), additionally (adv), furthermore (adv), moreover (adv), besides" },
  "what is more": { m: "Nghĩa đen: 'điều còn hơn nữa là' → thêm ý mạnh hơn ý trước.", e: "Sai: What more, ... → Đúng: What is more, ... / What's more, ... (không bỏ 'is').", u: "IELTS Speaking: 'What's more, it's really cheap'. Writing: dùng thay 'moreover' để tránh lặp từ nối.", f: "what is more (phrase), what's more, moreover (adv), furthermore (adv), on top of that" },
  "not only ... but also": { m: "Cặp đôi: 'không chỉ' (not only) A 'mà còn' (but also) B – hai vế cân xứng.", e: "Sai: Not only it is cheap → Đúng: Not only is it cheap (đầu câu phải đảo ngữ) but it is also convenient.", u: "IELTS Writing Task 2: câu đảo ngữ 'Not only does tourism create jobs, but it also...' nâng điểm ngữ pháp.", f: "not only ... but also (phrase), both ... and, as well as, besides" },
  "on the other hand": { m: "Hình ảnh: tay này cầm ý A, tay kia (other hand) cầm ý B ngược lại → mặt khác.", e: "Sai: In the other hand → Đúng: On the other hand. Dùng để so sánh hai mặt, không dùng để thêm ý.", u: "IELTS Writing Task 2 (discuss both views): 'On the other hand, critics argue that...'. Thường đi sau 'On the one hand'.", f: "on the other hand (phrase), on the one hand, however (adv), whereas (conj)" },
  "in contrast": { m: "contrast = độ tương phản như ảnh đen–trắng → đặt hai thứ cạnh nhau thấy khác hẳn.", e: "Sai: In contrast with, ... (khi không có tân ngữ) → Đúng: In contrast, ... / In contrast to X, ...", u: "IELTS Writing Task 1: 'Sales in Japan rose. In contrast, figures for Korea fell'. So sánh số liệu.", f: "contrast (n/v), in contrast (to), by contrast, contrasting (adj), conversely (adv)" },
  "conversely": { m: "converse (đảo ngược) + -ly → lật ngược chiều quan hệ: A tăng thì B giảm.", e: "Sai: Conversely of this → Đúng: Conversely, ... (đứng một mình đầu câu, sau đó dấu phẩy).", u: "IELTS Writing Task 1/2: 'Conversely, rural areas saw a decline in population'. Trang trọng, học thuật.", f: "converse (adj/n), conversely (adv), in contrast, on the contrary, inversely (adv)" },
  "in spite of": { m: "spite (sự trái ý) → bất chấp trở ngại vẫn làm → mặc dù. Theo sau là danh từ.", e: "Sai: in spite of it was raining → Đúng: in spite of the rain / in spite of it raining. Sai: in spite the rain.", u: "IELTS Writing Task 2: 'In spite of government efforts, pollution remains high'. Dùng thay 'although' cho đa dạng.", f: "in spite of (prep), despite (prep), although (conj), even though, nevertheless (adv)" },
  "even though": { m: "even (thậm chí) + though (mặc dù) → 'dù thậm chí như vậy' – nhấn mạnh hơn although.", e: "Sai: Even though it was late, but we stayed → Đúng: Even though it was late, we stayed (không thêm 'but').", u: "IELTS Speaking/Writing: 'Even though I'm busy, I always make time for exercise'. Nối hai mệnh đề đầy đủ.", f: "even though (conj), although (conj), though (conj/adv), even if (khác nghĩa), despite" },
  "on the contrary": { m: "Hình ảnh: đứng hẳn ở phía đối lập (contrary) để bác bỏ ý vừa nêu → trái lại.", e: "Sai: dùng On the contrary để so sánh A với B → Đúng: dùng In contrast. On the contrary là bác bỏ: 'It's not cheap. On the contrary, ...'.", u: "IELTS Writing Task 2: 'Technology does not isolate people; on the contrary, it connects them'.", f: "on the contrary (phrase), contrary to (prep), quite the opposite, in contrast (khác cách dùng)" },
  "as a result": { m: "result = kết quả → 'như một kết quả' của điều vừa nói.", e: "Sai: As result, ... → Đúng: As a result, ... Sai: as a result to → Đúng: as a result of + danh từ.", u: "IELTS Writing Task 2: 'Fewer people farm. As a result, food prices rise'. Nối nguyên nhân – hậu quả.", f: "result (n/v), as a result (of), consequently (adv), therefore (adv), result in (v)" },
  "due to": { m: "due (đến hạn, thuộc về) → kết quả 'thuộc về' nguyên nhân này → do, bởi.", e: "Sai: due to it rained → Đúng: due to the rain / due to the fact that it rained. Sau due to là danh từ.", u: "IELTS Writing Task 1/2: 'the drop was due to economic recession'. TOEIC: delays due to bad weather.", f: "due to (prep), owing to, because of, on account of, as a result of" },
  "owing to": { m: "owe (nợ) → kết quả 'nợ' nguyên nhân này → vì, do. Trang trọng hơn because of.", e: "Sai: owing to he was ill → Đúng: owing to his illness. Sai: owe to → Đúng: owing to.", u: "IELTS Writing: 'Owing to rapid urbanisation, green spaces are shrinking'. Đầu câu, theo sau là cụm danh từ.", f: "owe (v), owing to (prep), due to, because of, thanks to" },
  "as a consequence": { m: "consequence = hệ quả (con-sequ: đi theo sau) → điều kéo theo sau như cái đuôi.", e: "Sai: As consequence, ... → Đúng: As a consequence, ... Sai: as a consequence for → Đúng: as a consequence of.", u: "IELTS Writing Task 2: 'As a consequence, many young people leave rural areas'. Thay 'as a result' để tránh lặp.", f: "consequence (n), consequent (adj), consequently (adv), as a consequence (of), in consequence" },
  "for instance": { m: "instance = trường hợp cụ thể → lấy một trường hợp ra làm ví dụ.", e: "Sai: For instance: Vietnam, Thailand → Đúng: For instance, Vietnam and Thailand... Sai: for an instance → for instance.", u: "IELTS Writing Task 2: 'For instance, Singapore has strict anti-littering laws'. Đổi xen với 'for example'.", f: "instance (n), for instance (phrase), for example, such as, to illustrate" },
  "such as": { m: "Nghĩa đen: 'giống như là' → liệt kê vài ví dụ ngay sau danh từ.", e: "Sai: Such as, many people... (đầu câu) → Đúng: For example, many people... 'Such as' đứng sau danh từ: fruits such as mangoes.", u: "IELTS Writing: 'renewable sources such as wind and solar power'. Không thêm 'etc.' sau such as.", f: "such as (phrase), like (prep), for example, including (prep), namely" },
  "namely": { m: "name (gọi tên) + -ly → gọi đích danh ra từng thứ cụ thể là gì.", e: "Sai: namely, for example, A and B (thừa) → Đúng: two cities, namely Hà Nội and Huế. Dùng cho danh sách đầy đủ.", u: "IELTS Writing Task 2: 'two factors, namely cost and convenience, influence choices'. Chính xác hơn 'such as'.", f: "namely (adv), that is, i.e., specifically (adv), in particular" },
  "to illustrate": { m: "illustrate = minh họa bằng tranh → vẽ ra một ví dụ để người đọc thấy rõ.", e: "Sai: To illustrate, for example, ... (thừa) → Đúng: To illustrate, ... / To illustrate this point, ...", u: "IELTS Writing Task 2: 'To illustrate this, Finland's education system...'. Mở câu ví dụ, đa dạng từ nối.", f: "illustrate (v), illustration (n), illustrative (adj), for instance, to give an example" },
  "a case in point": { m: "Hình ảnh: một trường hợp (case) trúng ngay điểm (point) đang bàn → ví dụ điển hình.", e: "Sai: a point in case → Đúng: a case in point. Sai: Case in point is Japan → Đúng: Japan is a case in point.", u: "IELTS Writing Task 2: 'Ageing populations strain healthcare; Japan is a case in point'. Hay, ít người dùng.", f: "a case in point (phrase), a prime example, a typical example, for instance" },
  "in particular": { m: "particular = riêng biệt → chỉ thẳng một phần riêng giữa cả nhóm → đặc biệt là.", e: "Sai: in particularly → Đúng: in particular / particularly. Sai: In particular of young people → Đúng: Young people in particular.", u: "IELTS Writing: 'children, in particular, are vulnerable to advertising'. Speaking: I love Asian food, Thai food in particular.", f: "particular (adj), particularly (adv), in particular, especially (adv), specifically (adv)" },
  "notably": { m: "note (ghi chú) + -ably → điều đáng được ghi chú lại → đáng chú ý là.", e: "Sai: Notably to mention → Đúng: Notably, ... / most notably. Đừng nhầm với noticeably (rõ ràng thấy được).", u: "IELTS Writing Task 1: 'several countries, notably China and India, saw rapid growth'. Nêu ví dụ nổi bật.", f: "note (v/n), notable (adj), notably (adv), noteworthy (adj), in particular" },
  "in fact": { m: "fact = sự thật → 'trong thực tế' mà nói, thường để nhấn mạnh hoặc sửa ý.", e: "Sai: In the fact, ... → Đúng: In fact, ... Sai: in fact of → Đúng: in view of / due to.", u: "IELTS Speaking: 'In fact, I've never been abroad'. Writing: 'In fact, studies show...' nhấn mạnh bằng chứng.", f: "fact (n), factual (adj), in fact, actually (adv), as a matter of fact" },
  "in other words": { m: "Nghĩa đen: 'bằng những từ khác' → diễn đạt lại ý vừa nói cho dễ hiểu hơn.", e: "Sai: In other word, ... → Đúng: In other words, ... (luôn số nhiều).", u: "IELTS Writing Task 2: diễn giải ý phức tạp 'In other words, the policy benefits only the rich'. Speaking: paraphrase.", f: "in other words (phrase), that is to say, to put it another way, i.e., namely" },
  "above all": { m: "Hình ảnh: đặt điều này lên trên (above) tất cả (all) các điều khác → quan trọng nhất.", e: "Sai: Above of all, ... → Đúng: Above all, ... Dùng cho ý quan trọng nhất, thường đặt cuối danh sách.", u: "IELTS Writing Task 2: 'Above all, education is the key to reducing poverty'. Kết thúc chuỗi lý do mạnh mẽ.", f: "above all (phrase), most importantly, first and foremost, primarily (adv)" },
  "provided that": { m: "provide (cung cấp) → điều kiện phải được 'cung cấp' trước thì việc kia mới xảy ra.", e: "Sai: provided that it will rain → Đúng: provided that it rains (không dùng will sau provided that).", u: "IELTS Writing Task 2: 'Online learning is effective, provided that students are self-disciplined'. Câu điều kiện trang trọng.", f: "provided (that) (conj), providing (that), as long as, on condition that, if" },
  "in conclusion": { m: "conclude (khép lại) → in conclusion = mở đầu đoạn kết khép bài viết.", e: "Sai: In conclusions, ... / As a conclusion, ... → Đúng: In conclusion, ... Không dùng trong Speaking Part 1.", u: "IELTS Writing Task 2: mở đoạn kết 'In conclusion, I firmly believe...'. Không đưa ý mới trong đoạn này.", f: "conclude (v), conclusion (n), conclusive (adj), to conclude, to sum up" },
  "to sum up": { m: "sum = tổng → cộng tất cả các ý lại thành một tổng ngắn gọn.", e: "Sai: To summary, ... → Đúng: To sum up, ... / To summarise, ... (summary là danh từ).", u: "IELTS Writing Task 2: 'To sum up, both approaches have merits'. Speaking Part 3: tóm ý câu trả lời dài.", f: "sum up (phr v), summary (n), summarise (v), in summary, in conclusion" },
  "all things considered": { m: "Nghĩa đen: 'mọi thứ đã được cân nhắc' → sau khi xét hết, kết luận là...", e: "Sai: All things considering, ... → Đúng: All things considered, ... (dùng phân từ quá khứ).", u: "IELTS Writing Task 2 (kết bài): 'All things considered, the advantages outweigh the drawbacks'. Speaking Part 3.", f: "all things considered (phrase), on balance, overall (adv), taking everything into account" },
  "on balance": { m: "Hình ảnh: đặt ưu và nhược lên bàn cân (balance) xem bên nào nặng hơn.", e: "Sai: In balance, ... → Đúng: On balance, ... Sai: on the balance → Đúng: on balance (không mạo từ).", u: "IELTS Writing Task 2 (advantages/disadvantages): 'On balance, I believe remote work is beneficial'.", f: "on balance (phrase), all things considered, overall (adv), weigh up (v)" },
  "pose a threat": { m: "pose (đặt ra, tạo dáng) → 'đặt' mối đe dọa (threat) trước mặt ai đó.", e: "Sai: pose a threat for wildlife → Đúng: pose a threat to wildlife. Sai: make a threat (dọa nạt) dùng nhầm.", u: "IELTS Writing Task 2 (environment, technology): 'plastic waste poses a serious threat to marine life'.", f: "pose a threat (to), threaten (v), threat (n), pose a risk, endanger (v)" },
  "play a pivotal role": { m: "pivot = trục xoay của bản lề → vai trò làm 'trục' cho mọi thứ xoay quanh → then chốt.", e: "Sai: play a pivotal role on → Đúng: play a pivotal role in. Sai: take a pivotal role in (sắc thái khác).", u: "IELTS Writing Task 2: 'teachers play a pivotal role in shaping young minds'. Nâng cấp từ 'important role'.", f: "pivot (n/v), pivotal (adj), play a key / crucial / vital role, instrumental (adj)" },
  "raise awareness": { m: "raise = nâng lên → nâng mức hiểu biết (awareness) của cộng đồng.", e: "Sai: rise awareness → Đúng: raise awareness (raise là ngoại động từ). Sai: raise the awareness people → Đúng: raise people's awareness.", u: "IELTS Writing Task 2: 'campaigns should raise awareness of the dangers of smoking'. Rất phổ biến trong đề môi trường, sức khỏe.", f: "raise awareness (of), aware (adj), awareness (n), awareness campaign, educate the public" },
  "address the issue": { m: "address = gửi thư thẳng tới địa chỉ → nhắm thẳng vào vấn đề để giải quyết.", e: "Sai: address to the issue → Đúng: address the issue (không 'to'). Sai: address the problems of → address the problem of.", u: "IELTS Writing Task 2: 'governments must address the issue of youth unemployment'. TOEIC: address customer complaints.", f: "address (v), deal with, tackle (v), handle (v), resolve (v)" },
  "tackle the problem": { m: "tackle = cú xoạc bóng trong bóng đá → lao thẳng vào vấn đề để giành quyền kiểm soát.", e: "Sai: tackle with the problem → Đúng: tackle the problem (không 'with'). Sai: tackle to solve → Đúng: tackle the problem.", u: "IELTS Writing Task 2 (solutions): 'several measures could be taken to tackle the problem of obesity'.", f: "tackle (v/n), tackle the problem / issue, address (v), combat (v), deal with" },
  "meet the demand": { m: "meet = gặp → nguồn cung 'gặp' đúng nhu cầu (demand) → đáp ứng.", e: "Sai: meet the demands of customers' need → Đúng: meet customer demand. Sai: reach the demand → Đúng: meet the demand.", u: "IELTS Writing Task 1/2 (energy, housing): 'supply cannot meet the growing demand for housing'. TOEIC: meet demand.", f: "meet the demand (for), satisfy demand, supply and demand, demanding (adj)" },
  "bridge the gap": { m: "Hình ảnh: bắc cây cầu (bridge) qua khe hở (gap) giữa hai bờ → thu hẹp khoảng cách.", e: "Sai: bridge the gap of rich and poor → Đúng: bridge the gap between rich and poor.", u: "IELTS Writing Task 2 (inequality, education): 'free online courses help bridge the gap between urban and rural students'.", f: "bridge the gap (between), narrow the gap, close the gap, gap (n), widen the gap (trái nghĩa)" },
  "take measures": { m: "measure = thước đo, biện pháp → 'lấy ra' các biện pháp đo lường để xử lý.", e: "Sai: take a measure to → Đúng: take measures to (thường số nhiều). Sai: take measures for preventing → take measures to prevent.", u: "IELTS Writing Task 2: 'authorities should take strict measures to reduce air pollution'.", f: "take measures / steps / action, measure (n/v), adopt measures, implement measures" },
  "reach a consensus": { m: "con- (cùng) + sensus (cảm nhận) → mọi người cùng chung cảm nhận → đồng thuận.", e: "Sai: reach a consensus of opinion (thừa) → Đúng: reach a consensus. Sai: reach the consensus about → reach a consensus on.", u: "IELTS Writing/Speaking (politics, teamwork): 'world leaders failed to reach a consensus on climate targets'.", f: "consensus (n), consensual (adj), reach / build a consensus, agreement (n), unanimous (adj)" },
  "draw a conclusion": { m: "Hình ảnh: 'kéo' (draw) kết luận ra từ đống dữ liệu, như kéo nước lên từ giếng.", e: "Sai: make a conclusion / take a conclusion → Đúng: draw a conclusion. Sai: draw conclusion from → Đúng: draw a conclusion from.", u: "IELTS Writing Task 1/2: 'It is difficult to draw a firm conclusion from...'. Dùng ở đoạn kết hoặc khi bình luận số liệu hạn chế.", f: "conclude (v), conclusion (n), conclusive (adj); reach/come to a conclusion" },
  "have a profound impact on": { m: "profound = sâu (như 'fond' đáy) → tác động chạm tới tận đáy, không chỉ bề mặt.", e: "Sai: have a profound impact to society → Đúng: have a profound impact on society. Sai: profound impacts in → Đúng: impact on.", u: "IELTS Writing Task 2: nâng cấp 'affect a lot', vd. 'Technology has a profound impact on how children learn.'", f: "profound (adj), profoundly (adv); have a significant/far-reaching effect on" },
  "exert pressure on": { m: "exert = dùng hết sức (ex- ra ngoài) → đẩy lực ra ngoài, đè lên ai đó.", e: "Sai: exert pressure to the government → Đúng: exert pressure on the government. Sai: exert a pressure → Đúng: exert pressure.", u: "IELTS Writing Task 2 (xã hội, môi trường): 'Consumers can exert pressure on companies to...'. Trang trọng hơn 'put pressure on'.", f: "exert (v), exertion (n); put pressure on, apply pressure to" },
  "impose restrictions on": { m: "impose = im (vào) + pose (đặt) → đặt hạn chế đè lên ai đó từ trên xuống.", e: "Sai: impose restrictions to drivers → Đúng: impose restrictions on drivers. Sai: impose restrict → Đúng: impose restrictions.", u: "IELTS Writing Task 2: đề luật lệ, giao thông, quảng cáo: 'Governments should impose strict restrictions on junk food advertising.'", f: "impose (v), imposition (n), restrict (v), restrictive (adj); place limits on" },
  "allocate funds": { m: "allocate = al + locate (đặt chỗ) → đặt tiền vào đúng chỗ cần dùng.", e: "Sai: allocate funds for to hospitals → Đúng: allocate funds to hospitals. Sai: allocate fund → Đúng: allocate funds.", u: "IELTS Writing Task 2 đề ngân sách: 'The government should allocate more funds to public healthcare than to the arts.'", f: "allocate (v), allocation (n); allocate resources, budget allocation, earmark funds" },
  "curb emissions": { m: "curb = lề đường chặn xe tràn ra → chặn khí thải không cho tăng thêm.", e: "Sai: curb the emission of car → Đúng: curb emissions from cars. Sai: curb emission (không số nhiều) → Đúng: curb emissions.", u: "IELTS Writing Task 2 đề môi trường: 'Fuel taxes could help curb carbon emissions from transport.' Thay thế 'reduce pollution'.", f: "curb (v/n), emit (v), emission (n); cut/reduce emissions, rein in" },
  "boost the economy": { m: "boost = đẩy mạnh từ phía sau (như tên lửa đẩy) → giúp kinh tế tăng tốc.", e: "Sai: boost the economic → Đúng: boost the economy. Sai: boost economy development → Đúng: boost economic development.", u: "IELTS Writing Task 2 (du lịch, sự kiện, đầu tư): 'Hosting international events can boost the local economy.'", f: "boost (v/n), economy (n), economic (adj); stimulate growth, give a boost to" },
  "foster creativity": { m: "foster = nuôi dưỡng (foster parents: cha mẹ nuôi) → chăm sóc cho sáng tạo lớn lên.", e: "Sai: foster the creative → Đúng: foster creativity. Sai: foster students creativity → Đúng: foster creativity in students.", u: "IELTS Writing Task 2 đề giáo dục: 'Art and music lessons foster creativity in young learners.'", f: "foster (v), creative (adj), creativity (n); nurture/encourage creativity, foster innovation" },
  "broaden horizons": { m: "Hình ảnh: đường chân trời (horizon) được kéo rộng ra → nhìn thấy thế giới xa hơn.", e: "Sai: broaden my horizon (số ít) → Đúng: broaden my horizons. Sai: broad horizons (động từ) → Đúng: broaden horizons.", u: "IELTS Speaking Part 3/Writing đề du lịch, du học: 'Travelling abroad broadens young people's horizons.'", f: "broaden (v), broad (adj), horizon (n); widen one's perspective, open one's eyes" },
  "gain insight into": { m: "insight = nhìn (sight) vào bên trong (in) → thấu hiểu bản chất bên trong.", e: "Sai: gain insight about/of → Đúng: gain insight into. Sai: gain an insights → Đúng: gain insight / gain insights.", u: "IELTS Speaking/Writing: 'Reading novels helps us gain insight into other cultures.' Hợp đề giáo dục, văn hóa.", f: "insight (n), insightful (adj); gain an understanding of, shed light on" },
  "strike a balance": { m: "Hình ảnh: gõ (strike) cho kim cân dừng đúng giữa → đạt điểm cân bằng hai bên.", e: "Sai: strike a balance among work and life → Đúng: strike a balance between work and life. Sai: make balance → Đúng: strike a balance.", u: "IELTS Writing Task 2 dạng discuss/both views: 'Governments must strike a balance between economic growth and environmental protection.'", f: "balance (n/v), balanced (adj); find/achieve a balance, work-life balance" },
  "pay the price": { m: "Hình ảnh: hưởng xong thì phải 'trả giá' → gánh hậu quả cho hành động trước đó.", e: "Sai: pay the price of ignoring (khi nói hậu quả, hay dùng for) → Đúng: pay the price for ignoring the problem.", u: "IELTS Writing Task 2: 'Future generations will pay the price for today's pollution.' Dùng nhấn mạnh hậu quả.", f: "pay a heavy/high price for; suffer the consequences, bear the cost" },
  "run the risk of": { m: "Hình ảnh: chạy (run) trên đường có rủi ro → tự đặt mình vào nguy cơ.", e: "Sai: run the risk to lose → Đúng: run the risk of losing. Sau 'of' dùng V-ing.", u: "IELTS Writing Task 2: 'Children who spend too long online run the risk of becoming isolated.'", f: "risk (n/v), risky (adj); be at risk of, take the risk of" },
  "make a contribution to": { m: "con- (cùng) + tribute (góp) → cùng góp phần vào cái chung.", e: "Sai: make a contribution for society → Đúng: make a contribution to society. Sai: do a contribution → Đúng: make a contribution.", u: "IELTS Writing Task 2: 'Elderly people make a valuable contribution to the community.' Có thể thêm significant, valuable.", f: "contribute (v), contribution (n), contributor (n); contribute to, play a part in" },
  "conduct research": { m: "conduct = dẫn dắt (như nhạc trưởng conductor) → chỉ đạo cả quá trình nghiên cứu.", e: "Sai: conduct a research / researches → Đúng: conduct research (không đếm được). Sai: make research → Đúng: conduct/do research.", u: "IELTS Writing Task 2 đề khoa học: 'Universities should conduct more research into renewable energy.' Đi với into/on.", f: "conduct (v), research (n/v), researcher (n); carry out research, conduct a study" },
  "place emphasis on": { m: "Hình ảnh: đặt (place) dấu nhấn (emphasis) lên một điểm → coi nó quan trọng nhất.", e: "Sai: place emphasis in/to → Đúng: place emphasis on. Sai: emphasize on the issue → Đúng: emphasize the issue.", u: "IELTS Writing Task 2: 'Schools place too much emphasis on exam results.' Đi với great, too much, greater.", f: "emphasis (n), emphasize (v), emphatic (adj); put stress on, prioritize" },
  "adopt an approach": { m: "adopt = nhận nuôi → 'nhận về' một cách làm và dùng như của mình.", e: "Sai: adapt an approach (adapt = điều chỉnh) → Đúng: adopt an approach. Sai: approach to solve → Đúng: approach to solving.", u: "IELTS Writing Task 2 phần giải pháp: 'Governments should adopt a more holistic approach to tackling obesity.'", f: "adopt (v), adoption (n), approach (n/v); take an approach, implement a strategy" },
  "rely heavily on": { m: "Hình ảnh: tựa (rely) cả sức nặng (heavily) lên vật khác → bỏ đi là ngã.", e: "Sai: rely heavily in/to → Đúng: rely heavily on. Sai: rely on heavily (ít tự nhiên) → Đúng: rely heavily on.", u: "IELTS Writing Task 1/2: 'Many rural areas rely heavily on agriculture.' 'The country relies heavily on imported oil.'", f: "rely (v), reliance (n), reliant (adj), reliable (adj); depend heavily on" },
  "widen the gap": { m: "Hình ảnh: khe hở (gap) giữa hai bên bị kéo rộng ra (widen) → chênh lệch tăng.", e: "Sai: widen the gap of rich and poor → Đúng: widen the gap between rich and poor.", u: "IELTS Writing Task 2 đề bất bình đẳng, công nghệ: 'Private education may widen the gap between rich and poor.'", f: "widen (v), wide (adj), width (n); narrow/close/bridge the gap" },
  "reap the benefits": { m: "reap = gặt lúa → gieo công sức trước, sau gặt về lợi ích.", e: "Sai: reap the benefit from (thường số nhiều) → Đúng: reap the benefits of. Sai: rip the benefits → Đúng: reap.", u: "IELTS Writing Task 2: 'Countries that invest in education reap the benefits for decades.' Hợp đề đầu tư, sức khỏe.", f: "reap (v), benefit (n/v), beneficial (adj); enjoy the benefits, reap the rewards" },
  "reach their full potential": { m: "Hình ảnh: leo tới (reach) đỉnh cao nhất mà năng lực có thể đạt.", e: "Sai: reach their full potentials → Đúng: reach their full potential. Sai: reach full of potential → Đúng: reach their full potential.", u: "IELTS Writing Task 2 đề giáo dục, trẻ em: 'Every child should be given the chance to reach their full potential.'", f: "potential (n/adj), potentially (adv); realise/fulfil one's potential" },
  "set an example": { m: "Hình ảnh: đặt (set) một mẫu trước mặt người khác để họ làm theo.", e: "Sai: set an example to do → Đúng: set an example for/to others. Sai: give an example (= cho ví dụ) khi muốn nói làm gương.", u: "IELTS Writing Task 2 đề người nổi tiếng, cha mẹ: 'Celebrities should set a good example for young people.'", f: "set a good/bad example; role model, lead by example" },
  "take responsibility for": { m: "Hình ảnh: 'nhận lấy' (take) gánh trách nhiệm đặt lên vai mình.", e: "Sai: take responsibility of → Đúng: take responsibility for. Sai: take the responsible → Đúng: take responsibility.", u: "IELTS Writing Task 2: 'Individuals must take responsibility for their own health.' Đề ai chịu trách nhiệm.", f: "responsible (adj), responsibility (n), responsibly (adv); be responsible for, be accountable for" },
  "lay the foundation for": { m: "Hình ảnh: xây nhà phải đổ móng (foundation) trước → tạo nền cho sự phát triển sau.", e: "Sai: lay the foundation of success (ít dùng) → Đúng: lay the foundation for success. Sai: lie the foundation → Đúng: lay.", u: "IELTS Writing Task 2 đề giáo dục sớm: 'Primary education lays the foundation for lifelong learning.'", f: "foundation (n), found (v), fundamental (adj); pave the way for, lay the groundwork for" },
  "meet the needs of": { m: "meet = gặp → nhu cầu 'được gặp' đúng thứ nó cần, tức được đáp ứng.", e: "Sai: meet the need of people (thường số nhiều) → Đúng: meet the needs of people. Sai: satisfy needs of → Đúng: meet the needs of.", u: "IELTS Writing Task 2: 'Public transport must meet the needs of a growing population.' Đề nhà ở, y tế, giáo dục.", f: "need (n/v), needy (adj); cater for, satisfy demand, fulfil the needs of" },
  "a growing concern": { m: "Hình ảnh: nỗi lo như cái cây đang lớn (growing) → mỗi năm một nhiều hơn.", e: "Sai: a grow concern → Đúng: a growing concern. Sai: is a growing concern for → Đúng: is a growing concern among people.", u: "IELTS Writing Task 2 mở bài: 'Childhood obesity has become a growing concern in many developed countries.'", f: "concern (n/v), concerned (adj), concerning (adj); increasing worry, mounting concern" },
  "a pressing issue": { m: "pressing = đang ép (press) vào → vấn đề đè nặng, cần giải quyết ngay.", e: "Sai: a pressed issue → Đúng: a pressing issue. Sai: an urgently issue → Đúng: an urgent issue.", u: "IELTS Writing Task 2 mở bài: 'Traffic congestion is one of the most pressing issues facing big cities today.'", f: "press (v), pressure (n), pressing (adj); urgent problem, burning issue" },
  "a vicious circle": { m: "vicious = độc ác → vòng tròn ác: cái xấu sinh cái xấu, quay mãi không thoát.", e: "Sai: a vicious cycle of (vẫn dùng được) nhưng Sai: a viscous circle → Đúng: a vicious circle (vicious, không phải viscous = sệt).", u: "IELTS Writing Task 2 đề nghèo đói, sức khỏe: 'Poverty and poor education create a vicious circle.'", f: "vicious (adj), viciously (adv); vicious cycle, downward spiral; trái nghĩa: virtuous circle" },
  "a double-edged sword": { m: "Hình ảnh: kiếm có hai lưỡi → chém được đối thủ nhưng cũng có thể đứt tay mình.", e: "Sai: a two-edges knife → Đúng: a double-edged sword. Sai: double-edge sword → Đúng: double-edged sword.", u: "IELTS Writing Task 2 dạng advantages/disadvantages: 'Social media is a double-edged sword for teenagers.' Hợp mở bài.", f: "edge (n), edged (adj); mixed blessing, cuts both ways" },
  "a key factor": { m: "Hình ảnh: chìa khóa (key) mở được cửa → yếu tố quyết định kết quả.", e: "Sai: a key factor of success → Đúng: a key factor in success. Sai: key factors is → Đúng: key factors are.", u: "IELTS Writing Task 2: 'Parental support is a key factor in children's academic success.'", f: "factor (n/v); a major/crucial factor, determinant, contributing factor" },
  "long-term consequences": { m: "consequence = con (cùng) + sequ (theo sau) → thứ đi theo sau, kéo dài nhiều năm.", e: "Sai: long term consequence (thiếu gạch nối, số nhiều) → Đúng: long-term consequences. Sai: consequences to → Đúng: consequences for.", u: "IELTS Writing Task 2: 'Deforestation may have serious long-term consequences for the climate.'", f: "consequence (n), consequently (adv), consequent (adj); long-term effects; trái nghĩa: short-term" },
  "sustainable development": { m: "sustain = giữ vững → phát triển mà vẫn giữ được tài nguyên cho đời sau.", e: "Sai: sustainability development → Đúng: sustainable development. Sai: a sustainable developments → Đúng: sustainable development (không đếm được).", u: "IELTS Writing Task 2 đề môi trường, đô thị: 'Tourism must be managed to support sustainable development.'", f: "sustain (v), sustainable (adj), sustainability (n), sustainably (adv)" },
  "social cohesion": { m: "cohesion = dính (như keo, co-here) → xã hội dính kết với nhau, không chia rẽ.", e: "Sai: social coherence (= mạch lạc) → Đúng: social cohesion. Sai: social cohesive (adj) → Đúng: social cohesion (n).", u: "IELTS Writing Task 2 đề cộng đồng, nhập cư, thể thao: 'Community events strengthen social cohesion.'", f: "cohesion (n), cohesive (adj), cohere (v); community spirit, social unity" },
  "a sense of belonging": { m: "belong = thuộc về → cảm giác mình là một phần của nhóm, có chỗ đứng.", e: "Sai: a sense of belong → Đúng: a sense of belonging. Sai: belonging feeling → Đúng: a sense of belonging.", u: "IELTS Speaking/Writing đề cộng đồng, trường học: 'Team sports give children a sense of belonging.'", f: "belong (v), belonging (n), belongings (n, đồ đạc); sense of community, sense of identity" },
  "environmental degradation": { m: "degrade = hạ cấp (de- xuống + grade bậc) → môi trường bị tụt hạng, xấu dần.", e: "Sai: environment degradation → Đúng: environmental degradation. Sai: degradation of environmental → Đúng: degradation of the environment.", u: "IELTS Writing Task 2 đề công nghiệp, du lịch: 'Mass tourism can lead to environmental degradation.'", f: "degrade (v), degradation (n), degrading (adj), environment (n), environmental (adj)" },
  "a financial burden": { m: "burden = gánh nặng đè trên vai → khoản tiền đè nặng lên ai.", e: "Sai: a financial burden for families (được) nhưng hay dùng on → Đúng: a financial burden on families. Sai: finance burden → Đúng: financial burden.", u: "IELTS Writing Task 2 đề học phí, người già: 'University fees place a heavy financial burden on families.'", f: "burden (n/v), burdensome (adj), finance (n), financial (adj); economic strain" },
  "undergo changes": { m: "undergo = đi (go) xuyên qua bên dưới (under) → trải qua quá trình thay đổi.", e: "Sai: undergo a lot of change (thường số nhiều) → Đúng: undergo significant changes. Sai: undergo through changes → Đúng: undergo changes.", u: "IELTS Writing Task 1 (map, process): 'The town centre underwent dramatic changes between 1990 and 2020.'", f: "undergo (v, underwent, undergone); go through, experience changes" },
  "combat climate change": { m: "combat = chiến đấu → coi biến đổi khí hậu là kẻ thù phải đánh lại.", e: "Sai: combat with climate change → Đúng: combat climate change (không cần with). Sai: climate changes → Đúng: climate change.", u: "IELTS Writing Task 2 đề môi trường: 'International cooperation is essential to combat climate change.'", f: "combat (v/n), combative (adj); tackle/fight/address climate change" },
  "promote equality": { m: "promote = đẩy về phía trước (pro-) → đẩy xã hội tiến tới bình đẳng.", e: "Sai: promote the equal → Đúng: promote equality. Sai: promote equality among men and women → Đúng: between men and women.", u: "IELTS Writing Task 2 đề giới tính, giáo dục: 'Free education helps promote equality of opportunity.'", f: "promote (v), promotion (n), equal (adj), equality (n); gender equality, equal opportunities" },
  "encounter difficulties": { m: "encounter = đụng mặt (counter = đối diện) → bất ngờ đối diện khó khăn.", e: "Sai: encounter with difficulties → Đúng: encounter difficulties. Sai: encounter difficulty in to adapt → Đúng: in adapting.", u: "IELTS Speaking/Writing đề du học, nhập cư: 'International students often encounter difficulties adapting to a new culture.'", f: "encounter (v/n); face/experience difficulties, run into problems" },
  "acquire knowledge": { m: "acquire = thu về, có được (như acquisition) → gom kiến thức về làm của mình.", e: "Sai: acquire knowledges → Đúng: acquire knowledge (không đếm được). Sai: require knowledge (= đòi hỏi) khi muốn nói tiếp thu.", u: "IELTS Writing Task 2 đề giáo dục: 'Students acquire knowledge more effectively through hands-on experience.'", f: "acquire (v), acquisition (n); gain/obtain knowledge, knowledgeable (adj)" },
  "enhance the quality of life": { m: "enhance = nâng cao lên (như 'high') → kéo chất lượng sống lên mức cao hơn.", e: "Sai: enhance the life quality of → Đúng: enhance the quality of life. Sai: enhance quality of living → Đúng: quality of life.", u: "IELTS Writing Task 2 đề đô thị, công nghệ: 'Green spaces significantly enhance the quality of life in cities.'", f: "enhance (v), enhancement (n); improve living standards, raise quality of life" },
  "jeopardise the future": { m: "jeopardy = hiểm nguy → đẩy tương lai vào vùng nguy hiểm.", e: "Sai: jeopardise to the future → Đúng: jeopardise the future. Anh-Mỹ viết jeopardize; đừng viết jeopadise.", u: "IELTS Writing Task 2: 'Overfishing could jeopardise the future of coastal communities.' Trang trọng hơn 'threaten'.", f: "jeopardise (v), jeopardy (n); put at risk, threaten, endanger" },
  "devote time to": { m: "devote = hiến dâng (như devoted) → dâng thời gian cho việc mình coi trọng.", e: "Sai: devote time to study → Đúng: devote time to studying (to là giới từ, + V-ing).", u: "IELTS Speaking/Writing: 'Working parents struggle to devote enough time to their children.'", f: "devote (v), devoted (adj), devotion (n); dedicate time to, spend time on" },
  "make the most of": { m: "Hình ảnh: vắt kiệt giá trị lớn nhất (most) từ cơ hội đang có.", e: "Sai: make the best use the opportunity → Đúng: make the most of the opportunity. Sai: make most of → Đúng: make the most of.", u: "IELTS Speaking Part 2/3: 'I try to make the most of my weekends by exploring new places.'", f: "make the best of, take full advantage of, maximise" },
  "take into account": { m: "Hình ảnh: đưa (take) yếu tố vào sổ tính toán (account) trước khi quyết định.", e: "Sai: take into account of → Đúng: take into account / take account of. Tân ngữ dài đặt sau: take into account the cost.", u: "IELTS Writing Task 2: 'Planners must take into account the needs of elderly residents.'", f: "take account of, consider, factor in, bear in mind" },
  "pursue a career": { m: "pursue = đuổi theo → theo đuổi một nghề như chạy theo mục tiêu.", e: "Sai: pursue a career of law → Đúng: pursue a career in law. Sai: persue → Đúng: pursue.", u: "IELTS Speaking Part 1/3 đề công việc: 'I'd like to pursue a career in medicine.'", f: "pursue (v), pursuit (n); follow a career, embark on a career" },
  "cause irreversible damage": { m: "ir- (không) + reverse (quay ngược) → hỏng rồi không thể quay lại như cũ.", e: "Sai: cause irreversible damages to (damages = tiền bồi thường) → Đúng: cause irreversible damage to.", u: "IELTS Writing Task 2 đề môi trường: 'Plastic waste can cause irreversible damage to marine ecosystems.'", f: "reverse (v), reversible (adj), irreversible (adj), irreversibly (adv); permanent harm" },
  "a wide range of": { m: "Hình ảnh: dải (range) trải rộng (wide) → nhiều loại khác nhau trên một dải dài.", e: "Sai: a wide range of option → Đúng: a wide range of options (danh từ số nhiều). Sai: wide range of (thiếu a).", u: "IELTS Speaking/Writing: thay 'many', vd. 'The city offers a wide range of leisure activities.'", f: "range (n/v); a variety of, a diverse array of, a broad spectrum of" },
  "an integral part of": { m: "integral = toàn vẹn (integer: số nguyên) → bỏ phần này thì tổng thể không còn trọn.", e: "Sai: an integrate part of → Đúng: an integral part of. Sai: a integral part → Đúng: an integral part.", u: "IELTS Speaking/Writing: 'Smartphones have become an integral part of modern life.'", f: "integral (adj), integrate (v), integration (n); an essential part of, indispensable" },
  "it could be argued that": { m: "could = có thể → đưa ra lập luận mềm, không khẳng định chắc chắn là của mình.", e: "Sai: It could be argue that → Đúng: It could be argued that. Sai: It could argued that → Đúng: It could be argued that.", u: "IELTS Writing Task 2: mở một quan điểm phản biện hoặc ý dè dặt, vd. 'It could be argued that zoos protect endangered species.'", f: "argue (v), argument (n), arguably (adv); one might argue that, some may claim that" },
  "to a certain extent": { m: "extent = mức độ trải rộng → chỉ đồng ý tới một mức nhất định, không hoàn toàn.", e: "Sai: in a certain extent → Đúng: to a certain extent. Sai: to certain extend → Đúng: to a certain extent.", u: "IELTS Writing Task 2 dạng agree/disagree: 'I agree with this view to a certain extent.' Thể hiện quan điểm cân bằng.", f: "to some extent, to a large extent, partly, up to a point" },
  "in my view": { m: "view = tầm nhìn → 'trong tầm nhìn của tôi' tức là theo ý tôi.", e: "Sai: In my view point → Đúng: In my view / From my viewpoint. Sai: In my view, I think → Đúng: In my view, ...", u: "IELTS Writing Task 2: nêu quan điểm ở mở bài/kết bài, vd. 'In my view, the benefits outweigh the drawbacks.'", f: "in my opinion, from my perspective, personally, to my mind" },
  "from my point of view": { m: "Hình ảnh: đứng ở điểm (point) của tôi mà nhìn (view) vấn đề.", e: "Sai: According to my point of view → Đúng: From my point of view. Sai: In my point of view → Đúng: From my point of view.", u: "IELTS Speaking Part 3: mở câu trả lời ý kiến, vd. 'From my point of view, public transport should be free.'", f: "viewpoint (n), standpoint (n), perspective (n); from my perspective" },
  "i am convinced that": { m: "convince = thuyết phục → tôi đã bị bằng chứng thuyết phục, nên tin chắc.", e: "Sai: I am convincing that → Đúng: I am convinced that. Sai: I convinced that → Đúng: I am convinced that.", u: "IELTS Writing Task 2: nêu lập trường mạnh, vd. 'I am convinced that early education shapes a child's future.'", f: "convince (v), convinced (adj), convincing (adj), conviction (n); I firmly believe that" },
  "i firmly believe that": { m: "firm = chắc, vững (như nền móng) → niềm tin đứng vững, không lung lay.", e: "Sai: I firmly believe in that + mệnh đề → Đúng: I firmly believe that... Sai: I firm believe → Đúng: I firmly believe.", u: "IELTS Writing Task 2 dạng agree/disagree: nêu lập trường rõ ở mở bài, vd. 'I firmly believe that cycling should be encouraged.'", f: "firm (adj), firmly (adv), belief (n); I strongly believe, I am convinced that" },
  "it is widely believed that": { m: "widely = rộng rãi → niềm tin lan rộng khắp, nhiều người cùng nghĩ vậy.", e: "Sai: It is wide believed that → Đúng: It is widely believed that. Sai: It widely believes that → Đúng: It is widely believed that.", u: "IELTS Writing Task 2 mở bài: giới thiệu quan điểm phổ biến, vd. 'It is widely believed that money brings happiness.'", f: "it is commonly thought that, many people believe, it is generally accepted that" },
  "there is no doubt that": { m: "Hình ảnh: không còn chút nghi ngờ (doubt) nào → sự thật hiển nhiên.", e: "Sai: There is no doubt about that + mệnh đề → Đúng: There is no doubt that... Sai: No doubtly → Đúng: undoubtedly.", u: "IELTS Writing Task 2: nhấn mạnh sự thật hiển nhiên trước khi tranh luận, vd. 'There is no doubt that technology has changed education.'", f: "doubt (n/v), doubtless (adv), undoubtedly (adv); without a doubt, undeniably" },
  "i would argue that": { m: "would làm mềm giọng → 'tôi sẽ lập luận rằng', khẳng định lịch sự, học thuật.", e: "Sai: I would argue about that + mệnh đề → Đúng: I would argue that... Sai: I would argued → Đúng: I would argue.", u: "IELTS Writing Task 2/Speaking Part 3: nêu quan điểm học thuật, vd. 'I would argue that both factors matter equally.'", f: "argue (v), argument (n), argumentative (adj); I would suggest that, I maintain that" },
  "it seems to me that": { m: "seem = có vẻ → 'với tôi thì có vẻ như', nêu ý nhẹ nhàng, không áp đặt.", e: "Sai: It seems for me that → Đúng: It seems to me that. Sai: It is seem to me → Đúng: It seems to me.", u: "IELTS Speaking Part 3: mở ý kiến tự nhiên, vd. 'It seems to me that young people read less nowadays.'", f: "seem (v), seemingly (adv); it appears that, I get the impression that" },
  "as far as i am concerned": { m: "concerned = liên quan → 'xét trong phạm vi liên quan tới tôi' = theo tôi.", e: "Sai: As far as I concern → Đúng: As far as I am concerned. Sai: As long as I am concerned → Đúng: As far as.", u: "IELTS Speaking Part 3: nêu quan điểm cá nhân, vd. 'As far as I'm concerned, homework should be limited.' Hơi khẩu ngữ cho Writing.", f: "concern (n/v), concerned (adj); personally, in my opinion, as for me" },
  "i am inclined to think that": { m: "incline = nghiêng (như inclined plane) → ý tôi nghiêng về phía này, chưa chắc tuyệt đối.", e: "Sai: I am inclining to think → Đúng: I am inclined to think that. Sai: I incline think → Đúng: I am inclined to think.", u: "IELTS Speaking Part 3: trả lời câu hỏi khó một cách dè dặt, vd. 'I'm inclined to think that cities will keep growing.'", f: "incline (v), inclined (adj), inclination (n); I tend to think that" },
  "it is undeniable that": { m: "un- (không) + deny (phủ nhận) + -able → không ai phủ nhận được.", e: "Sai: It is undeniably that → Đúng: It is undeniable that. Sai: It is undenied that → Đúng: It is undeniable that.", u: "IELTS Writing Task 2: thừa nhận một sự thật trước khi phản biện, vd. 'It is undeniable that cars offer convenience.'", f: "deny (v), denial (n), undeniable (adj), undeniably (adv); there is no denying that" },
  "proponents of": { m: "pro- (ủng hộ) + pon (đặt) → người đặt mình về phía ủng hộ.", e: "Sai: proponents for/to → Đúng: proponents of. Sai: proponents of believes → Đúng: proponents of X believe.", u: "IELTS Writing Task 2 dạng discuss both views: 'Proponents of nuclear power argue that it is clean and reliable.'", f: "proponent (n), propose (v); supporters of, advocates of; trái nghĩa: opponents of" },
  "opponents of": { m: "op- (chống lại) + pon (đặt) → người đặt mình ở phía đối lập.", e: "Sai: opponents with/against → Đúng: opponents of. Sai: opposers of → Đúng: opponents of.", u: "IELTS Writing Task 2 dạng discuss both views: 'Opponents of the policy claim it harms small businesses.'", f: "oppose (v), opponent (n), opposition (n); critics of; trái nghĩa: proponents of" },
  "while it is true that": { m: "while = trong khi → thừa nhận một điểm đúng trước, rồi đưa ý ngược lại.", e: "Sai: While it is true that A, but B → Đúng: While it is true that A, B (không dùng but).", u: "IELTS Writing Task 2: câu nhượng bộ, vd. 'While it is true that tourism creates jobs, it also damages local culture.'", f: "although, admittedly, granted that, even though" },
  "admittedly": { m: "admit = thừa nhận → 'phải thừa nhận là', nhường đối phương một điểm.", e: "Sai: Admitedly → Đúng: Admittedly (hai chữ t). Sai: Admittedly, ... but → Đúng: Admittedly, ... However, ...", u: "IELTS Writing Task 2: mở câu nhượng bộ trong đoạn phản biện, vd. 'Admittedly, online courses are cheaper.'", f: "admit (v), admission (n), admittedly (adv); granted, it must be said that" },
  "arguably": { m: "argue + -ably → có thể lập luận được, tức là 'cho là' kèm ý dè dặt.", e: "Sai: Arguably the more important → Đúng: arguably the most important. Sai: Arguely → Đúng: Arguably.", u: "IELTS Writing Task 2: hedging khi khẳng định mạnh, vd. 'Education is arguably the most important investment a country can make.'", f: "argue (v), argument (n), arguable (adj), arguably (adv); possibly, it could be said" },
  "it is likely that": { m: "likely = có khả năng → dự đoán xác suất cao nhưng chưa chắc chắn 100%.", e: "Sai: It is likely to that → Đúng: It is likely that... Sai: It is likely happen → Đúng: It is likely to happen.", u: "IELTS Writing Task 1/2: dự đoán xu hướng, vd. 'It is likely that sales will continue to rise.'", f: "likely (adj), likelihood (n), unlikely (adj); probably, there is a good chance that" },
  "there is a tendency for": { m: "tend = nghiêng về → có khuynh hướng nghiêng về một hành vi chung.", e: "Sai: There is a tendency for people buy → Đúng: There is a tendency for people to buy. Sai: tendency of → for + sb + to V.", u: "IELTS Writing Task 2: mô tả xu hướng xã hội, vd. 'There is a tendency for young adults to live with their parents longer.'", f: "tend (v), tendency (n); there is a trend towards, people tend to" },
  "it is generally accepted that": { m: "generally accepted = được chấp nhận chung → điều phần lớn mọi người đã đồng thuận.", e: "Sai: It is generally accept that → Đúng: It is generally accepted that. Sai: It generally accepts that → Đúng: It is generally accepted that.", u: "IELTS Writing Task 2 mở bài: nêu nhận định chung trước khi đưa quan điểm riêng, vd. 'It is generally accepted that exercise improves health.'", f: "accept (v), acceptance (n), acceptable (adj); it is widely recognised that" },
  "the advantages outweigh the disadvantages": { m: "outweigh = nặng cân hơn → đặt lên cân, phía lợi ích nặng hơn phía tác hại.", e: "Sai: the advantages outweigh than the disadvantages → Đúng: the advantages outweigh the disadvantages (không dùng than).", u: "IELTS Writing Task 2 dạng 'Do the advantages outweigh the disadvantages?': nêu rõ ở mở bài và kết bài.", f: "outweigh (v); the benefits outweigh the drawbacks, the pros outweigh the cons" },
  "there is a strong case for": { m: "case = hồ sơ lập luận (như vụ kiện) → có hồ sơ lý lẽ vững chắc ủng hộ.", e: "Sai: There is a strong case to + N → Đúng: There is a strong case for + N/V-ing, hoặc for sb to V.", u: "IELTS Writing Task 2: đề xuất giải pháp, vd. 'There is a strong case for taxing sugary drinks.'", f: "make a case for, argue for; a compelling argument for, strong grounds for" },
  "to my mind": { m: "Hình ảnh: 'đối với tâm trí tôi' → theo cách tôi nghĩ.", e: "Sai: In my mind (= trong đầu tôi, không phải 'theo tôi') → Đúng: To my mind, ...", u: "IELTS Speaking Part 3: thay 'I think' cho đa dạng, vd. 'To my mind, the best solution is better public transport.'", f: "in my view, in my opinion, as I see it" },
  "it is worth noting that": { m: "worth = đáng giá → điều này đáng giá để ghi nhận (note).", e: "Sai: It is worth to note that → Đúng: It is worth noting that (worth + V-ing). Sai: It is worthy noting → Đúng: worth noting.", u: "IELTS Writing Task 1: nhấn mạnh chi tiết nổi bật, vd. 'It is worth noting that car usage fell sharply after 2010.'", f: "worth (adj/n), worthwhile (adj); it should be noted that, notably" },
  "i partly agree": { m: "partly = một phần (part) → đồng ý một nửa, còn nửa kia giữ ý riêng.", e: "Sai: I partly agree this view → Đúng: I partly agree with this view. Sai: I agree partially with (được), nhưng Sai: I am partly agree.", u: "IELTS Writing Task 2 dạng agree/disagree: 'I partly agree with this statement.' Bài cần trình bày cả hai mặt rõ ràng.", f: "partly (adv), partial (adj), partially (adv); I agree to some extent" },
  "i strongly disagree": { m: "strongly = mạnh mẽ → phản đối dứt khoát, không lưỡng lự.", e: "Sai: I am strongly disagree → Đúng: I strongly disagree. Sai: I strongly disagree this idea → Đúng: disagree with this idea.", u: "IELTS Writing Task 2: nêu lập trường phản đối rõ ở mở bài, vd. 'I strongly disagree with the idea that art is a waste of money.'", f: "disagree (v), disagreement (n); I totally disagree, I am firmly opposed to" },
  "this is not to say that": { m: "Hình ảnh: 'điều này không phải để nói rằng' → chặn người đọc hiểu quá đà.", e: "Sai: This is not to say about → Đúng: This is not to say that... Sai: This not to say → Đúng: This is not to say.", u: "IELTS Writing Task 2: làm rõ, giới hạn lập luận, vd. 'This is not to say that technology is harmful.'", f: "that does not mean that, this does not imply that" },
  "a compelling argument": { m: "compel = ép buộc → lập luận mạnh tới mức 'ép' người nghe phải tin.", e: "Sai: a compelled argument → Đúng: a compelling argument. Sai: a compelling argument to (+ N) → Đúng: a compelling argument for.", u: "IELTS Writing Task 2: đánh giá lý lẽ, vd. 'There is a compelling argument for banning cars from city centres.'", f: "compel (v), compelling (adj), compulsion (n); a persuasive/convincing argument" },
  "surname": { m: "sur- (bên trên, thêm vào) + name → tên thêm vào sau tên riêng, tức họ.", e: "Sai: My surname is Minh (tên riêng) → Đúng: My surname is Nguyen. Đánh vần họ phải chính xác từng chữ.", u: "IELTS Listening Section 1: điền form, 'Could you spell your surname?'. Nghe kỹ phần đánh vần, chú ý chữ đôi (double L).", f: "surname (n); family name, last name; first name, forename" },
  "postcode": { m: "post (bưu điện) + code (mã) → mã giúp bưu điện tìm đúng khu vực.", e: "Sai: post code number → Đúng: postcode. Anh-Mỹ gọi là zip code. Nghe chữ cái và số lẫn lộn (BS8 1TH).", u: "IELTS Listening Section 1: điền địa chỉ; postcode Anh gồm chữ và số, chú ý phân biệt 'zero' và chữ O.", f: "postcode (n), postal (adj); zip code (Mỹ), postal code" },
  "date of birth": { m: "Viết tắt DOB → ngày (date) bạn được sinh ra (birth).", e: "Sai: birth date of me is → Đúng: My date of birth is 3rd May. Sai: date of born → Đúng: date of birth.", u: "IELTS Listening Section 1: điền form; chú ý viết ngày đúng kiểu (3 May / 3rd May) và nghe năm sinh.", f: "birth (n), birthday (n), birthplace (n); DOB" },
  "reference number": { m: "refer = tra cứu lại → dãy số giúp tra lại hồ sơ, đơn hàng của bạn.", e: "Sai: refer number → Đúng: reference number. Sai: nghe 'double 7' viết 7 → Đúng: viết 77.", u: "IELTS Listening Section 1: đặt phòng, khiếu nại; dãy chữ số dài, chú ý 'double', 'triple' và chữ cái.", f: "refer (v), reference (n); booking reference, ref. no." },
  "contact number": { m: "contact = liên lạc → số điện thoại để người khác liên lạc được với bạn.", e: "Sai: contact phone number of me → Đúng: my contact number. Sai: viết thiếu số 0 đầu khi nghe 'oh'.", u: "IELTS Listening Section 1: điền form; người nói đọc 'oh' thay số 0 và nhóm số theo cụm.", f: "contact (n/v); phone number, mobile number, landline" },
  "home address": { m: "home (nhà) + address (địa chỉ) → nơi bạn sống, khác work address.", e: "Sai: home adress → Đúng: home address (hai chữ d, hai chữ s). Sai: my address home → Đúng: my home address.", u: "IELTS Listening Section 1: nghe số nhà, tên phố đánh vần; chú ý Road/Street/Avenue khác nhau.", f: "address (n/v); postal address, permanent address, work address" },
  "application form": { m: "apply → application (đơn xin) + form (mẫu) → tờ mẫu để nộp đơn.", e: "Sai: fill the application form → Đúng: fill in/fill out the application form. Sai: apply form → Đúng: application form.", u: "IELTS Listening Section 1/2: đăng ký khóa học, thành viên, việc làm; câu hỏi về hạn nộp và giấy tờ kèm.", f: "apply (v), applicant (n), application (n); registration form, enrolment form" },
  "membership fee": { m: "member + -ship (tư cách) + fee (phí) → tiền trả để có tư cách hội viên.", e: "Sai: member fee → Đúng: membership fee. Sai: pay the membership fees for (số ít/nhiều tùy) nhưng Sai: membership cost fee.", u: "IELTS Listening Section 1: câu lạc bộ, phòng gym; thường có bẫy giá (annual vs monthly, có giảm giá).", f: "member (n), membership (n), fee (n); annual subscription, joining fee" },
  "admission fee": { m: "admit = cho vào → phí để được cho vào bảo tàng, công viên.", e: "Sai: entrance fees of → Đúng: admission fee to/for. Sai: admit fee → Đúng: admission fee.", u: "IELTS Listening Section 1/2: giá vé tham quan; bẫy giá người lớn, trẻ em, nhóm, concession.", f: "admit (v), admission (n); entrance fee, entry charge, ticket price" },
  "free of charge": { m: "free of = không có → không có khoản thu (charge) nào, miễn phí.", e: "Sai: free of charges → Đúng: free of charge. Sai: It is free of charge fee → Đúng: It is free of charge.", u: "IELTS Listening Section 1/2: 'Parking is free of charge'; thường là đáp án 'free' hoặc bẫy so với dịch vụ có phí.", f: "free (adj), charge (n/v); at no cost, complimentary, for nothing" },
  "concession": { m: "concede = nhượng bộ → giá 'nhượng bộ' dành cho sinh viên, người già.", e: "Sai: concession price for student → Đúng: concession price for students. Không nhầm với 'confession' (lời thú tội).", u: "IELTS Listening Section 1/2: bảng giá vé, 'concessions £5'; thường hỏi ai được giảm giá.", f: "concede (v), concession (n), concessionary (adj); discount, reduced rate" },
  "senior citizen": { m: "senior = lớn tuổi hơn + citizen (công dân) → công dân cao tuổi, thường trên 65.", e: "Sai: senior citizens is → Đúng: senior citizens are. Sai: old citizen (thiếu lịch sự) → Đúng: senior citizen.", u: "IELTS Listening Section 1/2: đối tượng giảm giá vé; IELTS Writing dùng thay 'old people' cho lịch sự.", f: "senior (adj/n), seniority (n); pensioner, elderly people, the over-65s" },
  "cheque": { m: "check (kiểm tra) → tờ séc ngân hàng kiểm tra trước khi trả tiền; Anh viết cheque.", e: "Sai: pay with cheque → Đúng: pay by cheque. Anh viết cheque, Mỹ viết check; đừng viết chque.", u: "IELTS Listening Section 1: hỏi phương thức thanh toán (by cash, by card, by cheque); chú ý chính tả kiểu Anh.", f: "cheque (n), chequebook (n); check (Mỹ), bank transfer" },
  "en suite": { m: "Tiếng Pháp 'en suite' = liền kề → phòng tắm nằm liền trong phòng ngủ.", e: "Sai: ensuit / on suite → Đúng: en suite (hoặc ensuite). Sai: a room with en suite (thiếu danh từ) → Đúng: an en suite bathroom.", u: "IELTS Listening Section 1: thuê nhà, khách sạn, ký túc xá; thường là đáp án điền về tiện nghi phòng.", f: "en suite (adj/n), ensuite; private bathroom, shared bathroom" },
  "studio flat": { m: "studio (xưởng một gian) + flat → căn hộ chỉ một phòng gộp ngủ, sinh hoạt, bếp.", e: "Sai: studio apartment flat → Đúng: studio flat (Anh) / studio apartment (Mỹ). Sai: a studio flats → Đúng: a studio flat.", u: "IELTS Listening Section 1: tìm chỗ ở; so sánh giá thuê, diện tích, vị trí giữa các loại nhà.", f: "flat (n); studio apartment, bedsit, one-bedroom flat" },
  "terraced house": { m: "terrace = dãy bậc nối liền → các nhà nối nhau thành một dãy liền kề.", e: "Sai: terrace house / terrased house → Đúng: terraced house. Sai: a terraced houses → Đúng: a terraced house.", u: "IELTS Listening Section 1: mô tả loại nhà khi thuê/mua; phân biệt với detached và semi-detached.", f: "terrace (n), terraced (adj); row house (Mỹ), end-of-terrace, semi-detached" },
  "semi-detached": { m: "semi (nửa) + detached (tách rời) → nhà chỉ tách một nửa, chung một bức tường.", e: "Sai: semi detach house → Đúng: semi-detached house. Nhớ gạch nối và đuôi -ed.", u: "IELTS Listening Section 1: loại nhà trong form thuê/mua; cũng gọi tắt 'a semi'.", f: "detach (v), detached (adj), semi-detached (adj/n); terraced, a semi" },
  "landlady": { m: "land (đất) + lady (bà) → người phụ nữ sở hữu nhà, đất cho thuê.", e: "Sai: land lady (tách) → Đúng: landlady. Nam là landlord; đừng gọi người thuê là landlady (người thuê = tenant).", u: "IELTS Listening Section 1: hội thoại thuê nhà; hỏi tên, quy định, tiền đặt cọc của bà chủ nhà.", f: "landlord (n), landlady (n), tenant (n), lodger (n)" },
  "estate agent": { m: "estate (bất động sản) + agent (đại lý) → người làm trung gian mua bán, cho thuê nhà.", e: "Sai: estate agency person → Đúng: estate agent. Anh-Mỹ gọi là real estate agent hoặc realtor.", u: "IELTS Listening Section 1: gọi cho công ty môi giới hỏi nhà; nghe giá thuê, khu vực, ngày xem nhà.", f: "estate agent (n), estate agency (n); real estate agent, realtor (Mỹ)" },
  "furnished": { m: "furniture (đồ đạc) → furnished: đã được trang bị đồ đạc sẵn.", e: "Sai: furnitured flat → Đúng: furnished flat. Trái nghĩa: unfurnished; part-furnished = có một phần.", u: "IELTS Listening Section 1: câu hỏi điền tiện nghi nhà thuê; bẫy giữa fully furnished và unfurnished.", f: "furnish (v), furnished (adj), unfurnished (adj), furniture (n), furnishings (n)" },
  "utility bills": { m: "utility = tiện ích thiết yếu (điện, nước, gas) → hóa đơn tiện ích hằng tháng.", e: "Sai: utilities bill → Đúng: utility bills. Sai: The rent include bills → Đúng: The rent includes utility bills.", u: "IELTS Listening Section 1: hỏi tiền thuê đã gồm hóa đơn chưa ('bills included'); dễ có bẫy giá.", f: "utility (n), utilities (n); household bills, energy bills, bills included" },
  "flatmate": { m: "flat (căn hộ) + mate (bạn) → người bạn ở chung một căn hộ.", e: "Sai: flat mate / roommate (= chung phòng) khi chỉ chung căn hộ → Đúng: flatmate. Mỹ dùng roommate.", u: "IELTS Listening Section 1/3: sinh viên tìm bạn ở cùng; nghe tính cách, chia tiền nhà.", f: "flatmate (n), housemate (n), roommate (n), classmate (n)" },
  "hall of residence": { m: "hall (tòa nhà lớn) + residence (nơi cư trú) → tòa nhà cho sinh viên ở.", e: "Sai: hall of residences → Đúng: halls of residence. Sai: residence hall of students (cứng) → Đúng: hall of residence.", u: "IELTS Listening Section 1/3: chỗ ở năm nhất đại học; hỏi giá, bữa ăn, phòng đơn hay đôi.", f: "residence (n), resident (n), reside (v); dormitory (Mỹ), student halls" },
  "childcare": { m: "child + care (chăm sóc) → dịch vụ chăm trẻ khi bố mẹ đi làm.", e: "Sai: child care service of → Đúng: childcare services. Sai: a childcare (không đếm được) → Đúng: childcare.", u: "IELTS Listening Section 1/2: dịch vụ tại trung tâm, phòng gym; IELTS Writing đề phụ nữ đi làm.", f: "childcare (n), childminder (n), carer (n); daycare, babysitting" },
  "nursery": { m: "nurse = nuôi nấng → nơi nuôi dưỡng trẻ nhỏ; cũng là vườn ươm cây non.", e: "Sai: nursery school for teenagers → Đúng: nursery school for young children. Không nhầm với nurse (y tá).", u: "IELTS Listening Section 1/2: dịch vụ trông trẻ; cũng gặp nghĩa vườn ươm cây ở bài về làm vườn.", f: "nurse (v/n), nursery (n); nursery school, kindergarten, plant nursery" },
  "under-fives": { m: "under (dưới) + five(s) → nhóm trẻ dưới năm tuổi.", e: "Sai: under five (thiếu s, không gạch nối) khi là danh từ nhóm → Đúng: the under-fives. Sai: under-fives is → Đúng: are.", u: "IELTS Listening Section 1/2: điều kiện vé, hoạt động: 'free for under-fives'. Hay xuất hiện trong bảng giá.", f: "under-fives (n); under-fives' group, under-18s, over-65s" },
  "fortnight": { m: "Rút gọn 'fourteen nights' → mười bốn đêm, tức hai tuần.", e: "Sai: two fortnights = 2 tuần → Đúng: a fortnight = 2 tuần. Sai: fortnightly = mỗi tuần → Đúng: hai tuần một lần.", u: "IELTS Listening Section 1/2: thời hạn khóa học, kỳ nghỉ; đáp án có thể là '2 weeks' hoặc '14 days'.", f: "fortnight (n), fortnightly (adj/adv); two weeks, biweekly" },
  "per head": { m: "Hình ảnh: đếm theo đầu người → giá tính cho mỗi người.", e: "Sai: per heads → Đúng: per head. Sai: £10 for per head → Đúng: £10 per head.", u: "IELTS Listening Section 1/2: giá tour, tiệc: 'It costs £15 per head'; cần nhân đúng với số người.", f: "per person, each, a head; per capita (trang trọng)" },
  "in advance": { m: "advance = tiến lên phía trước → làm trước thời điểm cần.", e: "Sai: book in advanced → Đúng: book in advance. Sai: in advance of two days → Đúng: two days in advance.", u: "IELTS Listening Section 1/2: đặt chỗ, thanh toán trước; câu hỏi 'How far in advance must you book?'", f: "advance (n/v), advanced (adj); beforehand, ahead of time, in advance of" },
  "return ticket": { m: "return = trở về → vé đi rồi trở về, khứ hồi.", e: "Sai: two-way ticket → Đúng: return ticket (Anh) / round-trip ticket (Mỹ). Vé một chiều là single ticket.", u: "IELTS Listening Section 1/2: mua vé tàu, xe buýt; so sánh giá single, return, day return.", f: "return (n/v); single ticket, round-trip (Mỹ), open return, day return" },
  "off-peak": { m: "off (ngoài) + peak (đỉnh) → ngoài giờ đỉnh đông, nên rẻ và vắng.", e: "Sai: off peak hour (thiếu gạch nối) → Đúng: off-peak hours. Sai: off-peak = giờ cao điểm → Đúng: peak = cao điểm.", u: "IELTS Listening Section 1/2: giá vé tàu, phòng gym rẻ hơn vào giờ off-peak; hay bị hỏi về thời gian.", f: "peak (n/adj), off-peak (adj/adv); peak time, rush hour, quiet period" },
  "rush hour": { m: "rush = vội vã → giờ mọi người vội vã đi làm, về nhà.", e: "Sai: rush hours time → Đúng: rush hour. Sai: in rush hour (vẫn đúng) nhưng Sai: at the rush hours → Đúng: during rush hour.", u: "IELTS Listening/Speaking đề giao thông: 'Avoid travelling during rush hour'; Writing đề tắc đường.", f: "rush (v/n); peak hours, morning/evening rush; trái nghĩa: off-peak" },
  "car park": { m: "car + park (bãi để) → bãi đỗ ô tô. Mỹ gọi parking lot.", e: "Sai: car parking place → Đúng: car park. Sai: park the car in car park (thiếu the) → Đúng: in the car park.", u: "IELTS Listening Section 2: bản đồ, chỉ đường; thường là nhãn trên map cần điền.", f: "car park (n), parking (n); parking lot (Mỹ), multi-storey car park" },
  "roundabout": { m: "round (vòng) + about (quanh) → chỗ xe chạy vòng quanh, bùng binh.", e: "Sai: round about (tách) → Đúng: roundabout. Sai: turn left in the roundabout → Đúng: at the roundabout.", u: "IELTS Listening Section 2: chỉ đường trên map: 'Go straight over the roundabout'; nghe exit thứ mấy.", f: "roundabout (n/adj); traffic circle (Mỹ), junction, crossroads" },
  "crossroads": { m: "cross (cắt nhau) + roads → nơi hai con đường cắt nhau, ngã tư.", e: "Sai: a crossroad → Đúng: a crossroads (luôn có s, vẫn số ít). Sai: at the cross road → Đúng: at the crossroads.", u: "IELTS Listening Section 2: chỉ đường trên map; Speaking nghĩa bóng 'at a crossroads in my career'.", f: "crossroads (n); intersection (Mỹ), junction; be at a crossroads (idiom)" },
  "traffic lights": { m: "Ánh đèn (lights) điều khiển dòng xe (traffic): đỏ, vàng, xanh.", e: "Sai: traffic light is red (được) nhưng Sai: turn right at the traffic light → Đúng: at the traffic lights.", u: "IELTS Listening Section 2: mốc chỉ đường: 'Turn left at the second set of traffic lights'.", f: "traffic (n), light (n); signals, stoplight (Mỹ), set of lights" },
  "junction": { m: "junct = nối (như conjunction) → chỗ các con đường nối vào nhau.", e: "Sai: juntion / junktion → Đúng: junction. Sai: in the junction → Đúng: at the junction.", u: "IELTS Listening Section 2: map, chỉ đường: 'at the T-junction, turn right'; cũng gặp junction trên đường cao tốc.", f: "join (v), junction (n), conjunction (n); T-junction, intersection, crossroads" },
  "pedestrian crossing": { m: "ped = chân (như pedal) → người đi bộ + chỗ băng qua đường.", e: "Sai: pedestrian cross → Đúng: pedestrian crossing. Sai: pedestrain → Đúng: pedestrian.", u: "IELTS Listening Section 2: mốc trên bản đồ; Writing đề an toàn giao thông.", f: "pedestrian (n/adj), cross (v), crossing (n); zebra crossing, crosswalk (Mỹ)" },
  "cycle lane": { m: "cycle (xe đạp) + lane (làn) → làn đường riêng dành cho xe đạp.", e: "Sai: bicycle line / cycling road → Đúng: cycle lane. Sai: ride in the cycle lane (đúng); Sai: ride on cycle lane thiếu the.", u: "IELTS Listening Section 2: quy hoạch thành phố; Writing đề giao thông xanh: 'build more cycle lanes'.", f: "cycle (v/n), cyclist (n); bike lane (Mỹ), cycle path, cycleway" },
  "footpath": { m: "foot (chân) + path (lối) → lối mòn chỉ đi bằng chân.", e: "Sai: foot path road → Đúng: footpath. Phân biệt: footpath ở ngoại ô, pavement là vỉa hè trong phố.", u: "IELTS Listening Section 2: bản đồ công viên, nông trại; nghe hướng 'follow the footpath along the river'.", f: "footpath (n); path, trail, pavement, sidewalk (Mỹ), public footpath" },
  "clockwise": { m: "clock + -wise (theo hướng) → xoay theo hướng kim đồng hồ.", e: "Sai: clockwisely → Đúng: clockwise (vừa adj vừa adv). Sai: turn it in clockwise → Đúng: turn it clockwise.", u: "IELTS Listening Section 2/4: chỉ hướng trên map, mô tả quy trình xoay máy móc.", f: "clockwise (adj/adv), anticlockwise, counterclockwise (Mỹ)" },
  "anticlockwise": { m: "anti (ngược) + clockwise → xoay ngược chiều kim đồng hồ.", e: "Sai: anti-clock wise → Đúng: anticlockwise (Anh) / counterclockwise (Mỹ). Sai: unclockwise → Đúng: anticlockwise.", u: "IELTS Listening Section 2/4: hướng đi quanh triển lãm, hướng vặn van trong bài mô tả thiết bị.", f: "anticlockwise (adj/adv), counterclockwise (Mỹ), clockwise" },
  "ground floor": { m: "ground = mặt đất → tầng sát mặt đất, tầng trệt. Tầng trên là first floor.", e: "Sai: on the first floor (khi ý là tầng trệt kiểu Anh) → Đúng: on the ground floor. Sai: in ground floor → Đúng: on the ground floor.", u: "IELTS Listening Section 2: sơ đồ tòa nhà; bẫy giữa ground floor và first floor kiểu Anh.", f: "ground floor (n); first floor (Mỹ = tầng trệt), basement, upper floor" },
  "staircase": { m: "stair (bậc) + case (khung) → cả khối cầu thang gồm bậc, tay vịn.", e: "Sai: a stairs case → Đúng: a staircase. Sai: go up the staircases (một cầu thang) → Đúng: go up the staircase / the stairs.", u: "IELTS Listening Section 2: sơ đồ tòa nhà, bảo tàng; nhãn 'main staircase' hay xuất hiện trên map.", f: "stair (n), stairs (n), staircase (n), stairway (n); lift, escalator" },
  "fire exit": { m: "Lối ra (exit) khi có cháy (fire) → cửa thoát hiểm.", e: "Sai: fire out / emergency out → Đúng: fire exit. Sai: the fire exits is → Đúng: the fire exits are.", u: "IELTS Listening Section 2: hướng dẫn an toàn tại tòa nhà; vị trí cửa thoát hiểm trên sơ đồ.", f: "exit (n/v); emergency exit, fire escape, fire alarm, assembly point" },
  "cloakroom": { m: "cloak = áo choàng → phòng gửi áo choàng, áo khoác. Trong nhà Anh còn là phòng vệ sinh nhỏ.", e: "Sai: clock room → Đúng: cloakroom (cloak, không phải clock). Sai: leave coat in cloakroom (thiếu the) → Đúng: in the cloakroom.", u: "IELTS Listening Section 2: tiện ích nhà hát, bảo tàng; vị trí cạnh lối vào trên sơ đồ.", f: "cloak (n), cloakroom (n); coat check (Mỹ), left luggage" },
  "foyer": { m: "Gốc Pháp 'foyer' = lò sưởi, nơi tụ tập → sảnh chờ chung khi bước vào.", e: "Sai: wait in foyer (thiếu the) → Đúng: wait in the foyer. Phát âm Anh /ˈfɔɪeɪ/, đừng đọc 'foi-ơ'.", u: "IELTS Listening Section 2: nhà hát, khách sạn: 'Meet in the main foyer'; nhãn trên sơ đồ.", f: "foyer (n); lobby, entrance hall, reception area" },
  "box office": { m: "Xưa vé bán ở ô cửa nhỏ như cái hộp (box) → quầy bán vé.", e: "Sai: ticket box office → Đúng: box office. Nghĩa bóng 'a box office hit' = phim ăn khách.", u: "IELTS Listening Section 2: nhà hát, rạp; giờ mở quầy, cách đặt vé, giảm giá.", f: "box office (n); ticket office, booking office; box-office hit/success" },
  "information centre": { m: "Trung tâm (centre) cung cấp thông tin (information) cho du khách.", e: "Sai: informations centre → Đúng: information centre. Anh viết centre, Mỹ viết center; đừng lẫn trong một bài.", u: "IELTS Listening Section 2: bản đồ khu du lịch; nơi lấy bản đồ, đặt tour.", f: "inform (v), information (n), informative (adj); tourist office, visitor centre" },
  "picnic area": { m: "Khu (area) dành riêng để ăn picnic ngoài trời.", e: "Sai: picnic place zone → Đúng: picnic area. Sai: picnicing → Đúng: picnicking (thêm k).", u: "IELTS Listening Section 2: bản đồ công viên; câu hỏi vị trí 'next to the lake'.", f: "picnic (n/v), picnicker (n), picnicking; picnic site, barbecue area" },
  "campsite": { m: "camp (cắm trại) + site (địa điểm) → nơi dựng lều cắm trại.", e: "Sai: camping site place → Đúng: campsite / camping site. Sai: camp side → Đúng: campsite.", u: "IELTS Listening Section 1/2: đặt chỗ cắm trại; nghe giá theo đêm, tiện ích, quy định.", f: "camp (n/v), camper (n), camping (n); campground (Mỹ), caravan park" },
  "nature reserve": { m: "reserve = giữ lại → vùng thiên nhiên được giữ lại để bảo vệ.", e: "Sai: nature reservation → Đúng: nature reserve. Sai: natural reserve → Đúng: nature reserve.", u: "IELTS Listening Section 2: tour khu bảo tồn; Writing đề bảo vệ động vật hoang dã.", f: "reserve (n/v), reservation (n), nature (n); wildlife reserve, national park" },
  "bird hide": { m: "hide = trốn → chòi để người núp ngắm chim mà chim không thấy.", e: "Sai: bird hiding house → Đúng: bird hide. Ở đây hide là danh từ, không phải động từ 'giấu'.", u: "IELTS Listening Section 2: map khu bảo tồn; nhãn vị trí chòi quan sát chim.", f: "hide (n/v), birdwatching (n), birdwatcher (n); observation hut" },
  "viewing platform": { m: "view (ngắm) + platform (bục) → bục cao để ngắm cảnh.", e: "Sai: view platform → Đúng: viewing platform. Sai: observe platform → Đúng: observation platform.", u: "IELTS Listening Section 2: điểm tham quan trên map; Speaking mô tả nơi ngắm cảnh đẹp.", f: "view (n/v), viewer (n), viewpoint (n); observation deck, lookout" },
  "harbour": { m: "Hình ảnh: nơi tàu thuyền được 'che chở' khỏi sóng gió; Anh viết -our.", e: "Sai: harbor trong bài viết kiểu Anh → Đúng: harbour. Sai: at harbour (thiếu the) → Đúng: in the harbour.", u: "IELTS Listening Section 2: bản đồ thị trấn ven biển; chú ý chính tả kiểu Anh khi điền.", f: "harbour (n/v), harbor (Mỹ); port, dock, marina" },
  "lighthouse": { m: "light (đèn) + house (nhà) → ngôi nhà có đèn chỉ đường cho tàu.", e: "Sai: light house (tách) → Đúng: lighthouse. Sai: lighthouses keeper → Đúng: lighthouse keeper.", u: "IELTS Listening Section 2: bản đồ bờ biển; Speaking mô tả công trình lịch sử.", f: "lighthouse (n), lighthouse keeper (n); beacon, lightship" },
  "woodland": { m: "wood (rừng nhỏ) + land (vùng đất) → vùng đất phủ cây, nhỏ hơn forest.", e: "Sai: woodlands area of forest → Đúng: woodland. Sai: a big woodland = rừng rậm (nên dùng forest).", u: "IELTS Listening Section 2: map công viên, khu bảo tồn; Writing Task 1 bản đồ thay đổi đất rừng.", f: "wood (n), woods (n), wooded (adj), woodland (n); forest, copse" },
  "refreshments": { m: "refresh = làm tươi lại → đồ ăn uống nhẹ giúp người tươi tỉnh.", e: "Sai: refreshment will be served (thường số nhiều) → Đúng: refreshments will be served.", u: "IELTS Listening Section 2: thông báo sự kiện: 'Refreshments will be available in the hall'.", f: "refresh (v), refreshing (adj), refreshments (n); snacks, drinks" },
  "first-aid kit": { m: "first aid (cứu giúp đầu tiên) + kit (bộ đồ) → hộp đồ dùng sơ cứu.", e: "Sai: first-aid box kit → Đúng: first-aid kit. Sai: first aids → Đúng: first aid (không đếm được).", u: "IELTS Listening Section 1/2: danh sách đồ cần mang khi đi dã ngoại, cắm trại.", f: "first aid (n), first-aider (n), kit (n); medical kit" },
  "changing rooms": { m: "change (thay) + rooms → phòng để thay quần áo trước khi tập, bơi.", e: "Sai: change rooms → Đúng: changing rooms. Sai: dressing room (thường là hậu trường) khi ở hồ bơi.", u: "IELTS Listening Section 2: tiện ích trung tâm thể thao; vị trí trên sơ đồ, có tủ khóa không.", f: "change (v), changing room (n); locker room (Mỹ), fitting room (cửa hàng)" },
  "sports centre": { m: "Trung tâm (centre) có nhiều môn thể thao (sports) dưới một mái nhà.", e: "Sai: sport centre / sports center (kiểu Mỹ trong bài Anh) → Đúng: sports centre.", u: "IELTS Listening Section 1/2: đăng ký thành viên, lịch lớp; Speaking nói về nơi tập thể thao.", f: "sport (n), sporty (adj), sports centre (n); leisure centre, gym" },
  "aerobics": { m: "aero = không khí, oxy → tập nhịp nhanh để cơ thể hút nhiều oxy.", e: "Sai: aerobic (thiếu s) khi chỉ môn → Đúng: do aerobics. Sai: play aerobics → Đúng: do aerobics.", u: "IELTS Listening Section 1/2: lịch lớp ở trung tâm thể thao; Speaking đề tập luyện.", f: "aerobic (adj), aerobics (n); aerobic exercise, cardio, step class" },
  "noticeboard": { m: "notice (thông báo) + board (bảng) → bảng ghim thông báo.", e: "Sai: notice table → Đúng: noticeboard. Sai: on noticeboard (thiếu the) → Đúng: on the noticeboard.", u: "IELTS Listening Section 2/3: 'details are on the noticeboard'; nơi đăng lịch, kết quả.", f: "notice (n/v), noticeboard (n); bulletin board (Mỹ), announcement" },
  "leaflet": { m: "leaf (lá) + -let (nhỏ) → tờ giấy nhỏ như chiếc lá để phát.", e: "Sai: a leaflets → Đúng: a leaflet. Sai: give out leaflet about → Đúng: hand out leaflets about.", u: "IELTS Listening Section 2: tài liệu thông tin được phát; hỏi nơi lấy tờ rơi.", f: "leaflet (n/v); flyer, brochure, pamphlet, handout" },
  "guided tour": { m: "guide (hướng dẫn) → tour có người dẫn và thuyết minh đi kèm.", e: "Sai: guide tour → Đúng: guided tour. Sai: join a guided tour of → hay dùng: take/go on a guided tour of.", u: "IELTS Listening Section 2: giờ khởi hành, giá, thời lượng tour; Speaking kể trải nghiệm du lịch.", f: "guide (n/v), guided (adj), guidance (n); self-guided tour, audio guide" },
  "raffle": { m: "Mua vé số nhỏ ở sự kiện từ thiện, rút thăm trúng quà → gây quỹ.", e: "Sai: lottery (xổ số quốc gia) cho sự kiện nhỏ → Đúng: raffle. Sai: buy raffle → Đúng: buy a raffle ticket.", u: "IELTS Listening Section 2: sự kiện cộng đồng, gây quỹ trường học; giá vé, giải thưởng.", f: "raffle (n/v), raffle ticket (n); prize draw, lottery, tombola" },
  "fundraising": { m: "fund (quỹ) + raise (nâng lên) → nâng quỹ lên, tức gây quỹ.", e: "Sai: fund rising → Đúng: fundraising. Sai: raise fund → Đúng: raise funds.", u: "IELTS Listening Section 2/3: sự kiện từ thiện; Writing đề cộng đồng: 'fundraising events'.", f: "fund (n/v), fundraiser (n), fundraising (n); raise money, charity event" },
  "marquee": { m: "Lều bạt lớn dựng cho tiệc, lễ hội; phân biệt với tent nhỏ để ngủ.", e: "Sai: marquee small tent → Đúng: marquee = lều lớn. Viết đúng: marquee (đừng viết marque, markee).", u: "IELTS Listening Section 2: sơ đồ lễ hội, đám cưới; vị trí đồ ăn, sân khấu trong marquee.", f: "marquee (n); tent, pavilion, gazebo" },
  "greenhouse": { m: "Nhà kính giữ hơi ấm cho cây xanh (green) bên trong.", e: "Sai: green house (= nhà sơn màu xanh) → Đúng: greenhouse. Sai: greenhouse effects → Đúng: the greenhouse effect.", u: "IELTS Listening Section 2: map vườn, nông trại; Writing đề môi trường: greenhouse gases.", f: "greenhouse (n); glasshouse, greenhouse effect, greenhouse gases" },
  "orchard": { m: "Hình ảnh: những hàng cây ăn quả trong vườn, như táo, lê, đào.", e: "Sai: fruit garden → Đúng: orchard. Sai: orchid (hoa lan) → Đúng: orchard.", u: "IELTS Listening Section 2: bản đồ nông trại, điền nhãn; Writing Task 1 map đất nông nghiệp.", f: "orchard (n); fruit trees, vineyard, plantation, grove" },
  "windmill": { m: "wind (gió) + mill (cối xay) → cối xay chạy bằng sức gió.", e: "Sai: wind mill (tách) → Đúng: windmill. Tua-bin phát điện gió hiện đại gọi là wind turbine.", u: "IELTS Listening Section 2: điểm tham quan trên map; Writing Task 1 bản đồ, đề năng lượng gió.", f: "windmill (n), mill (n), miller (n); wind turbine, watermill" },
  "gluten-free": { m: "-free = không có → hoàn toàn không chứa gluten (protein trong lúa mì).", e: "Sai: gluten free food without hyphen trước danh từ → Đúng: gluten-free food. Sai: free gluten → Đúng: gluten-free.", u: "IELTS Listening Section 1/2: đặt món, nhu cầu ăn đặc biệt; hay là đáp án điền vào form.", f: "gluten (n), -free: sugar-free, dairy-free, vegan, vegetarian" },
  "handout": { m: "hand (tay) + out (ra) → tài liệu đưa ra tận tay người học.", e: "Sai: hand-outs paper → Đúng: handouts. Sai: hand in (= nộp) khi muốn nói phát → Đúng: hand out.", u: "IELTS Listening Section 3/4: 'Look at the handout'; sinh viên bàn về tài liệu buổi học.", f: "hand out (phr v), handout (n); worksheet, leaflet, notes" },
  "reading list": { m: "Danh sách (list) sách cần đọc (reading) trước khóa học.", e: "Sai: read list → Đúng: reading list. Sai: books on reading list (thiếu the) → Đúng: books on the reading list.", u: "IELTS Listening Section 3: sinh viên bàn với tutor nên đọc sách nào trước.", f: "read (v), reading (n), list (n); bibliography, required reading, syllabus" },
  "word limit": { m: "Giới hạn (limit) số từ (word) được viết trong bài.", e: "Sai: words limit → Đúng: word limit. Sai: exceed over the word limit → Đúng: exceed the word limit.", u: "IELTS Listening Section 3: yêu cầu bài tập, 'a word limit of 3,000'; nhớ cả giới hạn trong đề Reading/Listening.", f: "word count (n), limit (n/v); maximum length, within the word limit" },
  "interviewee": { m: "Đuôi -ee = người được (bị) làm → người được phỏng vấn; -er là người phỏng vấn.", e: "Sai: interviewer (người hỏi) khi ý là người trả lời → Đúng: interviewee.", u: "IELTS Listening Section 3: sinh viên làm khảo sát, chọn người phỏng vấn; Speaking nói về phỏng vấn xin việc.", f: "interview (n/v), interviewer (n), interviewee (n); employee/employer, trainee" },
  "work placement": { m: "place = đặt → nhà trường 'đặt' sinh viên vào công ty làm thực tập.", e: "Sai: work placement in company to learn (thiếu mạo từ) → Đúng: a work placement at a company. Sai: practice job → Đúng: work placement.", u: "IELTS Listening Section 3: sinh viên bàn về kỳ thực tập; Writing đề kinh nghiệm làm việc.", f: "place (v), placement (n); internship, work experience, traineeship" },
  "group project": { m: "Dự án (project) làm theo nhóm (group), chia việc cho nhau.", e: "Sai: group's project of us → Đúng: our group project. Sai: do a group project alone (mâu thuẫn).", u: "IELTS Listening Section 3: thảo luận chia việc, deadline; Speaking đề học tập, làm việc nhóm.", f: "group work, team project, collaboration; project (n/v)" },
  "divide up": { m: "Hình ảnh: cắt (divide) chiếc bánh thành phần (up) cho mỗi người.", e: "Sai: divide up the work for three parts → Đúng: divide up the work into three parts / between us.", u: "IELTS Listening Section 3: nhóm sinh viên phân công: 'Let's divide up the research'. Hay hỏi ai làm phần nào.", f: "divide (v), division (n); split up, share out, allocate" },
  "tutor feedback": { m: "feedback = phản hồi quay lại (back) → nhận xét tutor gửi lại sau khi chấm bài.", e: "Sai: tutor feedbacks → Đúng: tutor feedback (không đếm được). Sai: give feedback for → Đúng: give feedback on.", u: "IELTS Listening Section 3: sinh viên nói về nhận xét của giảng viên; câu hỏi điểm mạnh, cần cải thiện.", f: "tutor (n/v), tutorial (n), feedback (n); comments, assessment" },
  "hand in": { m: "Hình ảnh: đưa bằng tay (hand) bài vào (in) cho thầy.", e: "Sai: hand on the essay → Đúng: hand in the essay. Sai: hand out (= phát ra) khi muốn nói nộp.", u: "IELTS Listening Section 3: hạn nộp bài: 'We must hand in the report by Friday'; nghe ngày tháng.", f: "submit, turn in (Mỹ), hand out (trái nghĩa hướng)" },
  "go over": { m: "Hình ảnh: đi (go) lướt qua (over) lại một lượt để kiểm tra.", e: "Sai: go over on the notes → Đúng: go over the notes. Sai: overgo → Đúng: go over.", u: "IELTS Listening Section 3/4: 'Let's go over the main points again'; dấu hiệu tóm tắt quan trọng.", f: "review, look over, run through, revise" },
  "cut down": { m: "Hình ảnh: cắt (cut) bớt cho ngắn (down) lại, như tỉa cây.", e: "Sai: cut down the essay into 2,000 words → Đúng: cut the essay down to 2,000 words. Hoặc: cut down on (giảm tiêu thụ).", u: "IELTS Listening Section 3: rút gọn bài, bài thuyết trình; Speaking: 'cut down on sugar'.", f: "cut down on, reduce, shorten, trim" },
  "visual aids": { m: "visual (nhìn) + aids (công cụ hỗ trợ) → hình, biểu đồ giúp người nghe dễ hiểu.", e: "Sai: visual aid tools → Đúng: visual aids. Sai: visual aides (aide = trợ lý) → Đúng: visual aids.", u: "IELTS Listening Section 3: chuẩn bị thuyết trình: slide, biểu đồ, video; bàn cái nào hiệu quả.", f: "visual (adj), visualise (v), aid (n/v); slides, charts, diagrams" },
  "time management": { m: "Quản lý (management) thời gian (time) như quản lý tiền bạc.", e: "Sai: management time → Đúng: time management. Sai: manage time well (được) nhưng Sai: good time manage → Đúng: good time management.", u: "IELTS Listening Section 3: kỹ năng học tập; Speaking Part 1/3 đề học, làm việc.", f: "manage (v), management (n), manager (n); organisational skills, prioritising" },
  "catch up on": { m: "Hình ảnh: chạy đuổi (catch up) theo phần việc bị bỏ lại phía sau.", e: "Sai: catch up with my homework → Đúng: catch up on my homework (with dùng cho người). Sai: catch on → Đúng: catch up on.", u: "IELTS Listening Section 3: sinh viên ốm, phải bù bài; Speaking: 'catch up on sleep'.", f: "catch up with (sb), make up for, keep up with" },
  "bibliographical details": { m: "biblio (sách) + graph (viết) → thông tin viết về nguồn sách: tác giả, năm, NXB.", e: "Sai: bibliography details → Đúng: bibliographical details. Sai: biographical (tiểu sử) → Đúng: bibliographical.", u: "IELTS Listening Section 3: hướng dẫn trích dẫn trong bài luận; ghi lại nguồn khi đọc tài liệu.", f: "bibliography (n), bibliographical (adj); reference list, citation, source details" },
  "lecture hall": { m: "Hội trường (hall) lớn để nghe giảng (lecture) đông sinh viên.", e: "Sai: lecture room hall → Đúng: lecture hall / lecture theatre. Sai: in lecture hall (thiếu the) → Đúng: in the lecture hall.", u: "IELTS Listening Section 3/4: địa điểm học; Section 2 sơ đồ khuôn viên trường.", f: "lecture (n/v), lecturer (n); lecture theatre, auditorium, seminar room" },
  "in today's lecture": { m: "Cụm mở đầu bài giảng → báo hiệu chủ đề chính sắp nói hôm nay.", e: "Sai: In the today lecture → Đúng: In today's lecture. Sai: In today lecture (thiếu 's) → Đúng: today's.", u: "IELTS Listening Section 4: câu mở đầu nêu chủ đề; nghe kỹ để biết khung bài giảng.", f: "today I'm going to talk about, this lecture will focus on" },
  "turn to": { m: "Hình ảnh: quay người (turn) sang hướng (to) chủ đề mới.", e: "Sai: turn to talk about → Đúng: turn to (talking about) the next point. Sau 'to' là danh từ hoặc V-ing.", u: "IELTS Listening Section 4: 'Let's now turn to the effects...'; tín hiệu chuyển sang câu hỏi tiếp theo.", f: "move on to, shift to, come to; turn to sb (nhờ cậy)" },
  "move on to": { m: "Hình ảnh: bước tiếp (move on) sang (to) phần kế tiếp.", e: "Sai: move on to discuss → Đúng: move on to discussing / move on to the next topic. Sai: move to on → Đúng: move on to.", u: "IELTS Listening Section 3/4: tín hiệu chuyển ý; Speaking Part 2: 'Moving on to why I like it...'", f: "turn to, proceed to, go on to, next" },
  "to begin with": { m: "begin (bắt đầu) → 'để bắt đầu' liệt kê ý thứ nhất, hoặc 'lúc đầu'.", e: "Sai: To begin, with → Đúng: To begin with,... Sai: For begin with → Đúng: To begin with.", u: "IELTS Listening Section 4: tín hiệu ý đầu tiên; Speaking Part 2/3 mở ý cho mạch lạc.", f: "first of all, firstly, initially, to start with" },
  "the main point": { m: "Ý (point) chính (main) → điều quan trọng nhất cần nhớ.", e: "Sai: the most main point → Đúng: the main point. Sai: main point is → Đúng: The main point is that...", u: "IELTS Listening Section 4: dấu hiệu ý quan trọng sắp được nói; Speaking tóm tắt quan điểm.", f: "main (adj), mainly (adv); the key point, the gist, the crux" },
  "trial and error": { m: "Thử (trial) rồi sai (error), sửa rồi thử lại cho đến khi đúng.", e: "Sai: try and error → Đúng: trial and error. Sai: by trial and errors → Đúng: by trial and error.", u: "IELTS Listening Section 4: lịch sử phát minh; Speaking: 'I learned to cook by trial and error'.", f: "trial (n), try (v), error (n), err (v); experimentation, learning by doing" },
  "setback": { m: "Hình ảnh: bị đẩy lùi (set back) một bước trên đường tiến tới mục tiêu.", e: "Sai: set back (danh từ, tách) → Đúng: a setback. Động từ: set sb back. Sai: suffer a setbacks → Đúng: a setback.", u: "IELTS Listening Section 4: dự án gặp trục trặc; Speaking Part 2 kể khó khăn đã vượt qua.", f: "set back (phr v), setback (n); obstacle, hitch, reversal" },
  "durability": { m: "dur = kéo dài (như during, endure) → khả năng dùng lâu không hỏng.", e: "Sai: durable (adj) khi cần danh từ → Đúng: durability. Sai: durablity → Đúng: durability.", u: "IELTS Listening Section 4: bài giảng vật liệu, kiến trúc; so sánh độ bền của chất liệu.", f: "durable (adj), durability (n), endure (v); toughness, longevity" },
  "irrigation channel": { m: "irrigate = dẫn nước tưới → kênh dẫn nước vào ruộng.", e: "Sai: irrigate channel → Đúng: irrigation channel. Sai: irigation → Đúng: irrigation (hai chữ r).", u: "IELTS Listening Section 4: bài giảng nông nghiệp, lịch sử cổ đại; Writing Task 1 quy trình, bản đồ.", f: "irrigate (v), irrigation (n); canal, ditch, irrigation system" },
  "nesting site": { m: "nest (tổ) + site (địa điểm) → chỗ chim, rùa chọn để làm tổ.", e: "Sai: nest site place → Đúng: nesting site. Sai: nesting sites is → Đúng: nesting sites are.", u: "IELTS Listening Section 4: bài giảng sinh thái, chim, rùa biển; điền nơi làm tổ.", f: "nest (n/v), nesting (n/adj); breeding ground, habitat" },
  "insulating": { m: "insula = hòn đảo → cô lập nhiệt như đảo cách biệt với biển.", e: "Sai: insulted (= bị xúc phạm) → Đúng: insulating material. Sai: insulating for heat → Đúng: insulating against heat.", u: "IELTS Listening Section 4: bài giảng vật liệu xây dựng, động vật giữ nhiệt (lông, mỡ).", f: "insulate (v), insulating (adj), insulation (n), insulator (n)" },
  "wavelength": { m: "wave (sóng) + length (độ dài) → khoảng cách giữa hai đỉnh sóng.", e: "Sai: wave length (tách) → Đúng: wavelength. Thành ngữ: on the same wavelength = hợp ý nhau.", u: "IELTS Listening Section 4: bài giảng ánh sáng, âm thanh, màu sắc; Speaking dùng thành ngữ.", f: "wave (n/v), wavelength (n), frequency (n); be on the same wavelength" },
  "mineral content": { m: "Lượng (content) khoáng chất (mineral) chứa bên trong nước, đất, thức ăn.", e: "Sai: minerals content → Đúng: mineral content. Sai: high mineral contents → Đúng: a high mineral content.", u: "IELTS Listening Section 4: bài giảng đất, nước, dinh dưỡng; điền đặc điểm mẫu vật.", f: "mineral (n/adj), content (n); nutrient content, mineral water" },
  "oxygen levels": { m: "level = mức → mức oxy trong nước, máu hay không khí.", e: "Sai: oxygen level is decreasing (đúng) nhưng Sai: level of oxygens → Đúng: levels of oxygen.", u: "IELTS Listening Section 4: bài giảng sinh thái biển, sức khỏe; Writing Task 1 biểu đồ nồng độ.", f: "oxygen (n), oxygenate (v); carbon dioxide levels, concentration" },
  "landline": { m: "land (mặt đất) + line (đường dây) → điện thoại đi bằng dây cố định.", e: "Sai: land phone → Đúng: landline. Sai: home mobile → Đúng: landline.", u: "IELTS Listening Section 1: số liên hệ thứ hai; Speaking đề công nghệ: 'Few people use a landline now'.", f: "landline (n), mobile (n), cell phone (Mỹ); home phone" },
  "expiry date": { m: "expire = hết hơi thở, hết hạn → ngày hết hạn.", e: "Sai: expire date → Đúng: expiry date (Anh) / expiration date (Mỹ). Sai: out of expiry → Đúng: past its expiry date.", u: "IELTS Listening Section 1: thẻ thành viên, hộ chiếu, thẻ ngân hàng; nghe ngày tháng chính xác.", f: "expire (v), expiry (n), expiration (n, Mỹ); use-by date, best-before date" },
  "hand luggage": { m: "Hành lý (luggage) xách bằng tay (hand) lên máy bay.", e: "Sai: hand luggages → Đúng: hand luggage (không đếm được). Sai: a hand luggage → Đúng: a piece of hand luggage.", u: "IELTS Listening Section 1/2: quy định hành lý; nghe giới hạn cân nặng, kích thước.", f: "luggage (n), baggage (n); carry-on (Mỹ), cabin bag, checked baggage" },
  "excess baggage": { m: "excess = vượt quá (exceed) → hành lý vượt quá mức cho phép.", e: "Sai: excess baggages → Đúng: excess baggage. Sai: access baggage → Đúng: excess baggage.", u: "IELTS Listening Section 1/2: phí trả thêm khi hành lý quá cân; câu hỏi về giá mỗi kg.", f: "exceed (v), excess (n/adj), excessive (adj); overweight baggage, baggage allowance" },
  "departure gate": { m: "depart = rời đi → cửa (gate) nơi hành khách rời ga để lên máy bay.", e: "Sai: departure door → Đúng: departure gate. Sai: at departure gate (thiếu the) → Đúng: at the departure gate.", u: "IELTS Listening Section 2: thông báo sân bay; nghe số cổng và giờ lên máy bay.", f: "depart (v), departure (n); boarding gate, arrivals, departure lounge" },
  "car hire": { m: "hire = thuê (Anh) → dịch vụ thuê ô tô.", e: "Sai: hire car service company → Đúng: car hire company. Mỹ dùng car rental. Sai: car hiring → Đúng: car hire.", u: "IELTS Listening Section 1: đặt thuê xe; nghe loại xe, giá ngày, bảo hiểm, giấy tờ.", f: "hire (v/n), hire car (n); car rental (Mỹ), rent a car" },
  "driving licence": { m: "licence = giấy phép → giấy phép lái xe. Anh viết licence (danh từ).", e: "Sai: driving license (kiểu Mỹ) trong bài Anh → Đúng: driving licence. Sai: driver licence → Đúng: driving licence.", u: "IELTS Listening Section 1: giấy tờ cần mang khi thuê xe; chú ý chính tả kiểu Anh.", f: "licence (n), license (v / n Mỹ); driver's license (Mỹ), permit" },
  "dual carriageway": { m: "dual (đôi) + carriageway (lòng đường) → hai lòng đường tách nhau bởi dải phân cách.", e: "Sai: dual carriage way → Đúng: dual carriageway. Sai: duel (đấu tay đôi) → Đúng: dual.", u: "IELTS Listening Section 2: chỉ đường, bản đồ giao thông; Writing Task 1 bản đồ thay đổi đường.", f: "dual (adj), carriageway (n); divided highway (Mỹ), motorway, A-road" },
  "one-way street": { m: "one way = một hướng → phố chỉ cho xe đi một chiều.", e: "Sai: one way road street → Đúng: one-way street. Nhớ gạch nối khi đứng trước danh từ.", u: "IELTS Listening Section 2: chỉ đường, map thành phố; Writing đề quy hoạch giao thông.", f: "one-way (adj), two-way (adj); one-way system, no entry" },
  "signpost": { m: "sign (biển) + post (cột) → cột cắm biển chỉ hướng.", e: "Sai: sign board post → Đúng: signpost. Động từ: signpost = chỉ dẫn rõ (một bài viết 'well signposted').", u: "IELTS Listening Section 2: 'Follow the signposts to the car park'; Writing nghĩa bóng: signposting language.", f: "sign (n/v), signpost (n/v), signposting (n); road sign, direction sign" },
  "bandstand": { m: "band (ban nhạc) + stand (bục) → bục có mái để ban nhạc biểu diễn.", e: "Sai: band stage stand → Đúng: bandstand. Sai: band stand (tách) → Đúng: bandstand.", u: "IELTS Listening Section 2: bản đồ công viên; điền vị trí bandstand gần hồ, vườn hoa.", f: "band (n), stand (n); stage, pavilion, gazebo, open-air stage" },
  "climbing wall": { m: "Bức tường (wall) gắn mấu bám để tập leo (climbing) trong nhà.", e: "Sai: climb wall → Đúng: climbing wall. Sai: play climbing wall → Đúng: use the climbing wall / go climbing.", u: "IELTS Listening Section 1/2: tiện ích trung tâm thể thao, trại hè; nghe giá, độ tuổi.", f: "climb (v), climber (n), climbing (n); bouldering, rock climbing" },
  "life jacket": { m: "Áo khoác (jacket) giữ mạng sống (life) khi rơi xuống nước.", e: "Sai: life jackets must wear → Đúng: Life jackets must be worn. Sai: live jacket → Đúng: life jacket.", u: "IELTS Listening Section 1/2: quy định an toàn khi chèo thuyền, đi biển; đồ được cung cấp.", f: "life jacket (n); lifebelt, buoyancy aid, life vest (Mỹ)" },
  "sleeping bag": { m: "Túi (bag) chui vào để ngủ (sleeping) khi cắm trại.", e: "Sai: sleep bag → Đúng: sleeping bag. Sai: bring sleeping bag (thiếu a) → Đúng: bring a sleeping bag.", u: "IELTS Listening Section 1/2: danh sách đồ mang đi cắm trại; nghe đồ nào được cung cấp sẵn.", f: "sleep (v), sleeping (adj); camping gear, tent, sleeping mat" },
  "vending machine": { m: "vend = bán (như vendor: người bán) → máy tự bán đồ.", e: "Sai: selling machine → Đúng: vending machine. Sai: buy from vending machine (thiếu a/the) → Đúng: from the vending machine.", u: "IELTS Listening Section 2: tiện ích ở trường, nhà ga; vị trí trên sơ đồ.", f: "vend (v), vendor (n), vending (n); snack machine, ticket machine" },
  "caretaker": { m: "care (chăm sóc) + taker (người nhận việc) → người nhận việc trông nom tòa nhà, trường học.", e: "Sai: the caretaker of the building is a caretaker man → Đúng: the building's caretaker. Đừng nhầm với 'carer' (người chăm bệnh nhân).", u: "IELTS Listening Section 1-2: hỏi chìa khóa, sửa chữa phòng trọ, 'contact the caretaker', thường cần điền tên hoặc số điện thoại.", f: "caretaker (n), care (n/v), take care of (v), janitor (n, Mỹ)" },
  "hourly rate": { m: "hour (giờ) + rate (mức) → số tiền tính cho mỗi giờ làm việc.", e: "Sai: the hour rate is 12 pounds → Đúng: the hourly rate is £12. Sai: pay by hourly → Đúng: paid by the hour.", u: "IELTS Listening Section 1: phỏng vấn việc làm thêm, 'What's the hourly rate?' – chú ý số tiền và đơn vị £ khi điền.", f: "hourly (adj/adv), hour (n), rate of pay, wage (n), salary (n)" },
  "bank holiday": { m: "Ngày ngân hàng (bank) đóng cửa nghỉ → ngày lễ chung toàn nước Anh.", e: "Sai: on bank holiday → Đúng: on the bank holiday / on a bank holiday. Không phải 'kỳ nghỉ của ngân hàng'.", u: "IELTS Listening: lịch mở cửa, đặt phòng – 'closed on bank holidays', 'the bank holiday weekend'; dễ là bẫy ngày tháng.", f: "public holiday (n), national holiday (n), bank holiday Monday, long weekend" },
  "mature student": { m: "mature (trưởng thành) → sinh viên đã đi làm, trên ~21–25 tuổi mới vào đại học.", e: "Sai: an old student → Đúng: a mature student (lịch sự hơn). Không nhầm với 'senior student' (sinh viên năm cuối).", u: "IELTS Listening Section 3-4: hội thảo đại học, quyền lợi mature students, học bổng; Speaking: nói về học tập suốt đời.", f: "mature (adj/v), maturity (n), adult learner (n), lifelong learning (n)" },
  "consent form": { m: "consent (đồng ý) + form (mẫu đơn) → tờ giấy ký để đồng ý tham gia, chữa trị.", e: "Sai: sign the agree form → Đúng: sign a consent form. Sai: consent with → Đúng: consent to something.", u: "IELTS Listening Section 3: dự án nghiên cứu, khảo sát cần 'participants signed a consent form'; cũng gặp ở bệnh viện, trường học.", f: "consent (n/v), informed consent (n), permission slip (n), waiver (n)" },
  "fieldwork": { m: "field (cánh đồng, hiện trường) + work → làm việc ngoài hiện trường thay vì trong phòng thí nghiệm.", e: "Sai: do a fieldwork → Đúng: do fieldwork (không đếm được). Sai: field work trip → Đúng: a fieldwork trip.", u: "IELTS Listening Section 3: sinh viên bàn kế hoạch fieldwork môn địa lý, sinh học; Speaking: kể về chuyến học ngoài trời.", f: "fieldwork (n), field trip (n), field study (n), in the field (phrase)" },
  "mind map": { m: "Bản đồ (map) của suy nghĩ (mind) → ý chính ở giữa, nhánh tỏa ra xung quanh.", e: "Sai: draw a mind mapping → Đúng: draw a mind map / use mind mapping. Sai: brain map → Đúng: mind map.", u: "IELTS Listening Section 3: cách ôn thi, lập dàn ý; Speaking Part 2: mô tả phương pháp học hiệu quả bằng mind map.", f: "mind map (n/v), mind mapping (n), diagram (n), brainstorm (v)" },
  "transcribe": { m: "trans (chuyển) + scribe (viết) → chuyển lời nói từ băng ghi âm thành chữ viết.", e: "Sai: transcribe the interview to paper → Đúng: transcribe the interview. Không nhầm với 'translate' (dịch sang ngôn ngữ khác).", u: "IELTS Listening Section 3: nhóm nghiên cứu chia việc 'transcribe the recordings' sau phỏng vấn; cũng dùng trong ngành y, pháp lý.", f: "transcribe (v), transcript (n), transcription (n), transcriber (n)" },
  "pie chart": { m: "Hình tròn như chiếc bánh (pie) cắt thành miếng → mỗi miếng là một phần trăm.", e: "Sai: the circle chart shows → Đúng: the pie chart shows. Sai: a pie chart about 30 percents → Đúng: 30 percent.", u: "IELTS Writing Task 1 và Listening: 'the pie chart shows the proportion of...'; dùng 'segment', 'slice', 'account for'.", f: "pie chart (n), bar chart (n), line graph (n), segment (n), slice (n)" },
  "assert": { m: "Nghe như 'ơ-xớt' khẳng định chắc nịch → nói điều gì với giọng tự tin tuyệt đối.", e: "Sai: he asserted me that... → Đúng: he asserted that... Sai: assert about → Đúng: assert that / assert one's rights.", u: "IELTS Reading: câu hỏi 'Does the writer assert...?'; Writing Task 2: 'Some critics assert that...' để giới thiệu quan điểm.", f: "assert (v), assertion (n), assertive (adj), assertiveness (n)" },
  "contend": { m: "con (cùng) + tend (căng ra) → căng mình tranh luận, khăng khăng cho rằng.", e: "Sai: they contend about that tax is unfair → Đúng: they contend that tax is unfair. 'contend with' = đối phó với khó khăn.", u: "IELTS Reading: xác định quan điểm tác giả – 'Smith contends that...'; Writing: 'Opponents contend that...' trang trọng hơn 'say'.", f: "contend (v), contention (n), contentious (adj), contender (n)" },
  "postulate": { m: "post (đặt) → đặt ra một tiền đề để lập luận dù chưa chứng minh.", e: "Sai: postulate a hypothesis is true → Đúng: postulate that a hypothesis is true. Phát âm động từ: /ˈpɒstjʊleɪt/.", u: "IELTS Reading bài khoa học: 'Einstein postulated that...'; nối với Matching features – ai đưa ra giả thuyết nào.", f: "postulate (v/n), postulation (n), posit (v), hypothesise (v)" },
  "speculate": { m: "spec (nhìn) → nhìn xa và đoán khi chưa đủ thông tin; cũng 'đầu cơ' tài chính.", e: "Sai: speculate the cause → Đúng: speculate about/on the cause. Sai: speculate that it will surely → Đúng: speculate that it might.", u: "IELTS Reading: 'Scientists speculate that...' báo hiệu thông tin chưa chắc (Not Given/False); Speaking: đoán xu hướng tương lai.", f: "speculate (v), speculation (n), speculative (adj), speculator (n)" },
  "refute": { m: "re (lại) + fute (đánh) → đánh bật lại lập luận bằng chứng cứ, chứng minh là sai.", e: "Sai: refute to the claim → Đúng: refute the claim. 'refute' = chứng minh sai; 'deny' chỉ là phủ nhận.", u: "IELTS Reading: 'The study refutes earlier theories' – khớp đáp án NO/FALSE; Writing: refute counter-arguments.", f: "refute (v), refutation (n), irrefutable (adj), rebut (v), disprove (v)" },
  "concede": { m: "con + cede (nhường) → nhường một bước, miễn cưỡng thừa nhận đối phương đúng.", e: "Sai: he conceded his mistake to be wrong → Đúng: he conceded that he was wrong. Sai: concede the defeat → Đúng: concede defeat.", u: "IELTS Writing Task 2: 'Admittedly, it must be conceded that...' để nhượng bộ; Reading: tác giả thừa nhận điểm yếu.", f: "concede (v), concession (n), concessive (adj), admit (v)" },
  "ascribe": { m: "a (đến) + scribe (viết) → ghi tên nguyên nhân/tác giả vào một sự việc.", e: "Sai: ascribe the failure for bad luck → Đúng: ascribe the failure to bad luck. Luôn đi với 'to'.", u: "IELTS Reading: 'The poem is ascribed to Homer', 'ascribe the decline to...' – dạng câu hỏi Matching nguyên nhân.", f: "ascribe (v), ascription (n), attribute to (v), credit with (v)" },
  "corroborate": { m: "co (cùng) + robor (sức mạnh) → thêm bằng chứng cùng hướng làm lời khai mạnh hơn.", e: "Sai: corroborate with the theory → Đúng: corroborate the theory. Sai: the data corroborates to → Đúng: the data corroborate the findings.", u: "IELTS Reading bài nghiên cứu: 'Further studies corroborated these results'; cũng gặp trong ngành luật, báo chí điều tra.", f: "corroborate (v), corroboration (n), corroborative (adj), confirm (v)" },
  "substantiate": { m: "substance (thực chất) → đưa thực chất, chứng cứ vào để lời nói có cơ sở.", e: "Sai: substantiate about the claim → Đúng: substantiate the claim. Sai: unsubstantial claims → Đúng: unsubstantiated claims.", u: "IELTS Reading: 'claims that remain unsubstantiated' → đáp án Not Given/False; Writing: substantiate arguments with examples.", f: "substantiate (v), substantiation (n), unsubstantiated (adj), substance (n)" },
  "undermine": { m: "Hình ảnh: đào hầm (mine) dưới (under) chân tường → làm sụp từ từ, ngầm làm yếu đi.", e: "Sai: undermine to the trust → Đúng: undermine trust. Không nhầm 'underestimate' (đánh giá thấp).", u: "IELTS Writing Task 2: 'Social media may undermine face-to-face communication'; Reading: yếu tố làm suy yếu lý thuyết.", f: "undermine (v), undermining (n), weaken (v), erode (v), sabotage (v)" },
  "cast doubt on": { m: "Hình ảnh: ném (cast) đám mây nghi ngờ phủ lên một kết luận.", e: "Sai: cast doubt to the theory → Đúng: cast doubt on the theory. Sai: casted doubt → Đúng: cast doubt (quá khứ không đổi).", u: "IELTS Reading: 'New evidence casts doubt on this view' – báo hiệu quan điểm cũ bị thách thức; dùng tốt trong Writing.", f: "throw doubt on, call into question, question (v), doubtful (adj)" },
  "call into question": { m: "Hình ảnh: gọi (call) một điều vào vùng câu hỏi → không còn chắc chắn nữa.", e: "Sai: call into question about the method → Đúng: call the method into question. Tân ngữ dài đặt sau: call into question the validity of...", u: "IELTS Reading/Writing: 'These findings call into question the effectiveness of...' – trang trọng, học thuật.", f: "cast doubt on, challenge (v), question (v), questionable (adj)" },
  "endorse": { m: "en (lên) + dorse (lưng giấy) → ký sau lưng tờ giấy → chính thức ủng hộ.", e: "Sai: endorse for the plan → Đúng: endorse the plan. Sai: celebrity endorse product → Đúng: a celebrity endorses a product.", u: "IELTS Writing Task 2 về quảng cáo: celebrity endorsements; Reading: chính phủ endorse chính sách; TOEIC: ký hậu séc.", f: "endorse (v), endorsement (n), endorser (n), back (v), approve (v)" },
  "uphold": { m: "up (lên) + hold (giữ) → giữ cho đứng vững: luật lệ, truyền thống, phán quyết.", e: "Sai: uphold on the law → Đúng: uphold the law. Quá khứ: upheld, không phải 'upholded'.", u: "IELTS Writing Task 2: 'uphold traditional values', 'uphold human rights'; Reading: tòa án upheld the decision.", f: "uphold (v), upheld (past), upholder (n), maintain (v), defend (v)" },
  "posit": { m: "Cùng gốc 'position' → đặt (một ý) vào vị trí tiền đề để bắt đầu lập luận.", e: "Sai: posit about that → Đúng: posit that... Không nhầm với 'post' (đăng) hay 'positive'.", u: "IELTS Reading bài học thuật: 'The theory posits that language is innate'; Matching researchers with claims.", f: "posit (v), position (n), postulate (v), propose (v), premise (n)" },
  "emphasise": { m: "emphasis (sự nhấn) → ấn mạnh bút dạ vào ý quan trọng.", e: "Sai: emphasise on the importance → Đúng: emphasise the importance / put emphasis on. Mỹ viết emphasize.", u: "IELTS Writing: 'It should be emphasised that...'; Reading: tác giả emphasises điều gì thường là đáp án chính.", f: "emphasise (v), emphasis (n), emphatic (adj), emphatically (adv), stress (v)" },
  "point out": { m: "Hình ảnh: chỉ ngón tay (point) ra ngoài (out) cho người khác thấy điều họ chưa để ý.", e: "Sai: point out me the mistake → Đúng: point out the mistake to me. Sai: point out about → Đúng: point out that...", u: "IELTS Reading: 'The author points out that...' giới thiệu ý quan trọng; Speaking: 'As my teacher pointed out...'", f: "point out (phr v), indicate (v), highlight (v), note (v), mention (v)" },
  "hypothesise": { m: "hypothesis (giả thuyết) + -ise → biến một phỏng đoán thành giả thuyết cần kiểm chứng.", e: "Sai: hypothesise about that → Đúng: hypothesise that... Số nhiều danh từ: hypotheses, không phải 'hypothesises'.", u: "IELTS Reading bài khoa học: 'Researchers hypothesised that sleep aids memory'; Listening Section 4 về thí nghiệm.", f: "hypothesise (v), hypothesis (n), hypotheses (pl), hypothetical (adj)" },
  "theorise": { m: "theory + -ise → xây dựng một lý thuyết để giải thích hiện tượng.", e: "Sai: theorise the reason is → Đúng: theorise that the reason is... / theorise about the reason.", u: "IELTS Reading: 'Some historians theorise that the city was abandoned due to drought'; dễ ra câu Matching ý kiến.", f: "theorise (v), theory (n), theorist (n), theoretical (adj), theoretically (adv)" },
  "debunk": { m: "de (bỏ) + bunk (chuyện nhảm) → gỡ bỏ chuyện nhảm, vạch trần huyền thoại.", e: "Sai: debunk about the myth → Đúng: debunk the myth. Dùng cho niềm tin sai, không dùng cho người.", u: "IELTS Reading: 'This study debunks the myth that...' – báo hiệu niềm tin phổ biến là sai (FALSE).", f: "debunk (v), debunker (n), disprove (v), expose (v), refute (v)" },
  "overstate": { m: "over (quá) + state (nói) → nói quá mức thực tế.", e: "Sai: its importance cannot be overstated enough → Đúng: its importance cannot be overstated (= cực kỳ quan trọng).", u: "IELTS Writing Task 2: 'The importance of education cannot be overstated'; Reading: tác giả cho rằng nguy cơ bị overstated.", f: "overstate (v), overstatement (n), exaggerate (v), understate (v, trái nghĩa)" },
  "underestimate": { m: "under (dưới) + estimate (ước tính) → ước tính thấp hơn thực tế.", e: "Sai: underestimate about the risk → Đúng: underestimate the risk. Sai: lowly estimate → Đúng: underestimate.", u: "IELTS Writing: 'People often underestimate the impact of...'; Speaking Part 3: đánh giá thấp vai trò của công nghệ.", f: "underestimate (v/n), underestimation (n), overestimate (v), underrate (v)" },
  "overestimate": { m: "over (quá) + estimate → ước tính vượt quá thực tế, kỳ vọng quá cao.", e: "Sai: overestimate oneself's ability → Đúng: overestimate one's ability. Sai: over-estimate too much → Đúng: greatly overestimate.", u: "IELTS Reading: 'Earlier figures overestimated the population'; Writing: tránh overestimate lợi ích của công nghệ.", f: "overestimate (v/n), overestimation (n), overrate (v), underestimate (v)" },
  "rule out": { m: "Hình ảnh: dùng thước kẻ (rule) gạch bỏ một khả năng ra khỏi danh sách.", e: "Sai: rule out of the possibility → Đúng: rule out the possibility. Sai: rule out to → Đúng: cannot be ruled out.", u: "IELTS Reading: 'Scientists cannot rule out other causes' – chú ý vì dễ thành Not Given; cũng dùng trong y khoa.", f: "rule out (phr v), exclude (v), eliminate (v), dismiss (v)" },
  "bear out": { m: "Hình ảnh: bằng chứng 'mang' (bear) lời tuyên bố ra ngoài ánh sáng và chống đỡ nó.", e: "Sai: the data bear out with the theory → Đúng: the data bear out the theory. Quá khứ: borne out.", u: "IELTS Reading: 'This claim is not borne out by the evidence' – đáp án NO/FALSE; Writing học thuật.", f: "bear out (phr v), confirm (v), corroborate (v), support (v)" },
  "point to": { m: "Hình ảnh: bằng chứng như ngón tay chỉ về (point to) một nguyên nhân.", e: "Sai: evidence points that → Đúng: evidence points to a link / suggests that. Sau 'to' là danh từ.", u: "IELTS Reading: 'Recent studies point to stress as a key factor'; Writing Task 2: 'Statistics point to a rise in...'", f: "point to (phr v), indicate (v), suggest (v), imply (v)" },
  "shed light on": { m: "Hình ảnh: rọi (shed) đèn vào góc tối → làm rõ vấn đề còn bí ẩn.", e: "Sai: shed a light to the issue → Đúng: shed light on the issue. Sai: shedded → Đúng: shed.", u: "IELTS Reading: 'The discovery sheds light on early human migration'; Writing: research can shed light on...", f: "throw light on, clarify (v), illuminate (v), elucidate (v)" },
  "lend support to": { m: "Hình ảnh: cho mượn (lend) cây chống để quan điểm đứng vững hơn.", e: "Sai: lend support for the idea → Đúng: lend support to the idea. Sai: lends supports → Đúng: lends support.", u: "IELTS Reading: 'These findings lend support to the hypothesis' – đáp án YES/TRUE; dùng tốt trong Writing Task 2.", f: "lend weight to, support (v), back up (phr v), reinforce (v)" },
  "be credited with": { m: "credit (ghi công) → tên người được ghi vào thành tựu như ghi có trong sổ.", e: "Sai: he is credited for invent → Đúng: he is credited with inventing the telephone. Sau 'with' là V-ing/danh từ.", u: "IELTS Reading Matching people: 'Bell is credited with inventing...'; cẩn thận vì có thể chỉ 'được cho là', chưa chắc.", f: "credit (n/v), give credit to, be attributed to, take credit for" },
  "draw on": { m: "Hình ảnh: kéo (draw) nước từ giếng kinh nghiệm hay nguồn tài liệu để dùng.", e: "Sai: draw on from my experience → Đúng: draw on my experience. Không nhầm 'draw up' (soạn thảo).", u: "IELTS Writing: 'The essay draws on recent research'; Speaking: 'I drew on my own experience when...'", f: "draw on/upon (phr v), rely on (phr v), make use of, utilise (v)" },
  "tentatively": { m: "tentative (thử) + -ly → làm/nói một cách dè dặt, chưa chốt.", e: "Sai: tentatively agree finally → Đúng: tentatively agreed (tạm đồng ý). Vị trí: đứng trước động từ chính.", u: "IELTS Reading: 'Researchers tentatively suggest...' = chưa chắc → không chọn TRUE tuyệt đối; TOEIC: lịch hẹn tạm thời.", f: "tentatively (adv), tentative (adj), tentativeness (n), provisionally (adv)" },
  "tentative": { m: "tent- (thử, như 'attempt') → kế hoạch mới thử, chưa chính thức.", e: "Sai: a tentatively plan → Đúng: a tentative plan. Sai: tentative date is confirmed → Đúng: the date is tentative.", u: "IELTS Reading: 'tentative conclusions'; TOEIC Part 7: 'a tentative schedule' – lịch có thể thay đổi.", f: "tentative (adj), tentatively (adv), provisional (adj), preliminary (adj)" },
  "supposedly": { m: "suppose (cho là) + -edly → người ta cho là vậy, nhưng người nói nghi ngờ.", e: "Sai: supposely → Đúng: supposedly (có -ed-). Không dùng để khẳng định chắc chắn.", u: "IELTS Reading: 'The drug supposedly cures...' báo hiệu tác giả hoài nghi; Speaking: thể hiện thái độ khéo léo.", f: "supposedly (adv), suppose (v), supposed (adj), be supposed to" },
  "allegedly": { m: "allege (cáo buộc) → bị cho là đã làm, nhưng chưa có bằng chứng.", e: "Sai: he allegedly is guilty proven → Đúng: he allegedly stole the money. Sai: alledgedly → Đúng: allegedly.", u: "IELTS Reading và báo chí: 'The company allegedly polluted the river' – chưa phải sự thật, cẩn trọng với TRUE.", f: "allegedly (adv), allege (v), allegation (n), alleged (adj)" },
  "ostensibly": { m: "ostens- (phô bày, như 'ostentatious') → điều phô ra ngoài, còn mục đích thật thì khác.", e: "Sai: ostensibly means obviously → Đúng: ostensibly = bề ngoài là (ẩn ý khác). Vd: ostensibly for safety.", u: "IELTS Reading: 'The law was ostensibly introduced to protect consumers' – tác giả gợi động cơ ẩn.", f: "ostensibly (adv), ostensible (adj), apparently (adv), seemingly (adv)" },
  "seemingly": { m: "seem (có vẻ) + -ingly → trông có vẻ như vậy, thực tế có thể khác.", e: "Sai: seemingly it seems → Đúng: seemingly simple / it seems. Tránh lặp hai từ cùng nghĩa.", u: "IELTS Writing: 'a seemingly simple solution'; Reading: 'seemingly unrelated factors' báo hiệu nghịch lý sắp giải thích.", f: "seemingly (adv), seem (v), seeming (adj), apparently (adv)" },
  "purportedly": { m: "purport (tự xưng) → được nói là, tự nhận là, nhưng nghi ngờ.", e: "Sai: purposely → Đúng: purportedly (khác nghĩa: purposely = cố ý). Đặt trước động từ/tính từ.", u: "IELTS Reading: 'a letter purportedly written by Shakespeare' – chưa xác thực, cẩn thận đáp án TRUE.", f: "purportedly (adv), purport (v/n), purported (adj), allegedly (adv)" },
  "conceivably": { m: "conceive (hình dung) + -ably → có thể nghĩ tới được, khả năng có thật.", e: "Sai: it conceivably will surely → Đúng: it could conceivably happen. Thường đi với could/might.", u: "IELTS Writing Task 2: 'This could conceivably lead to...' dè dặt học thuật; Reading: khả năng, không phải chắc chắn.", f: "conceivably (adv), conceivable (adj), inconceivable (adj), conceive (v)" },
  "implausible": { m: "im (không) + plausible (nghe hợp lý) → nghe không lọt tai, khó tin.", e: "Sai: an unplausible story → Đúng: an implausible story. Sai: implausible to believe → Đúng: it seems implausible that...", u: "IELTS Reading: 'The theory was dismissed as implausible'; Writing: phản bác ý kiến đối lập một cách lịch sự.", f: "implausible (adj), plausible (adj), plausibility (n), implausibly (adv)" },
  "conclusive": { m: "conclude (kết luận) → bằng chứng đủ mạnh để chốt hạ, không cần bàn nữa.", e: "Sai: a conclusion evidence → Đúng: conclusive evidence. Sai: evidence is conclusive that it maybe → Đúng: evidence is conclusive.", u: "IELTS Reading: 'There is no conclusive proof that...' → thường đáp án NO/NOT GIVEN; Writing học thuật.", f: "conclusive (adj), conclusively (adv), conclude (v), conclusion (n), inconclusive (adj)" },
  "inconclusive": { m: "in (không) + conclusive → kết quả lửng lơ, chưa chốt được điều gì.", e: "Sai: the results are unconclusive → Đúng: the results are inconclusive. Sai: inconclusive result → Đúng: inconclusive results (thường số nhiều).", u: "IELTS Reading: 'The trials proved inconclusive' – tránh chọn TRUE cho khẳng định chắc chắn; Listening Section 4 về nghiên cứu.", f: "inconclusive (adj), inconclusively (adv), conclusive (adj), unresolved (adj)" },
  "anecdotal": { m: "anecdote (giai thoại, chuyện kể) → bằng chứng chỉ từ chuyện kể cá nhân, không đo đếm.", e: "Sai: anecdote evidence → Đúng: anecdotal evidence. Sai: an anecdotal → Đúng: an anecdote (danh từ).", u: "IELTS Reading: 'evidence is largely anecdotal' = chưa khoa học; Speaking Part 3: phân biệt kinh nghiệm cá nhân và số liệu.", f: "anecdotal (adj), anecdote (n), anecdotally (adv), empirical (adj, trái nghĩa)" },
  "speculative": { m: "speculate (suy đoán) → mang tính phỏng đoán, chưa có căn cứ vững.", e: "Sai: a speculation theory → Đúng: a speculative theory. Sai: speculative about → Đúng: speculation about.", u: "IELTS Reading: 'Such claims remain speculative' báo hiệu chưa chứng minh; kinh tế: speculative investment (đầu cơ).", f: "speculative (adj), speculate (v), speculation (n), speculatively (adv)" },
  "debatable": { m: "debate (tranh luận) + -able → điều có thể đem ra tranh luận, chưa ngã ngũ.", e: "Sai: it is debating whether → Đúng: it is debatable whether... Sai: debatable about → Đúng: debatable.", u: "IELTS Writing Task 2: 'It is debatable whether homework benefits children'; Speaking Part 3 để giữ thái độ cân bằng.", f: "debatable (adj), debate (n/v), arguable (adj), questionable (adj)" },
  "contentious": { m: "contend (tranh) → chủ đề khiến người ta tranh cãi gay gắt.", e: "Sai: a contented issue → Đúng: a contentious issue (contented = hài lòng). Sai: contentious for → Đúng: contentious among.", u: "IELTS Writing Task 2: 'Animal testing remains a contentious issue'; Reading: chủ đề gây tranh cãi trong giới khoa học.", f: "contentious (adj), contention (n), contend (v), controversial (adj)" },
  "dubious": { m: "dub- (hai, như 'double') → lưỡng lự giữa hai ý, thấy đáng ngờ.", e: "Sai: dubious of honesty → Đúng: of dubious honesty / dubious about something. Không nhầm 'doubtful'.", u: "IELTS Reading: 'dubious claims', 'dubious methods'; Writing: phê phán quảng cáo hoặc nguồn tin đáng ngờ.", f: "dubious (adj), dubiously (adv), doubtful (adj), questionable (adj)" },
  "sceptical": { m: "scept- (xem xét) → người luôn soi xét trước khi tin.", e: "Sai: sceptical with the idea → Đúng: sceptical about/of the idea. Mỹ viết skeptical.", u: "IELTS Speaking Part 3: 'I'm a bit sceptical about online learning'; Reading: thái độ hoài nghi của chuyên gia.", f: "sceptical (adj), sceptic (n), scepticism (n), sceptically (adv)" },
  "counterintuitive": { m: "counter (ngược) + intuitive (trực giác) → kết quả ngược với điều ta tưởng tự nhiên.", e: "Sai: counter intuitive with logic → Đúng: it seems counterintuitive, but... Viết liền hoặc có gạch nối.", u: "IELTS Reading: 'Counterintuitively, more choice makes people less happy'; Writing: giới thiệu nghịch lý thú vị.", f: "counterintuitive (adj), counterintuitively (adv), intuition (n), intuitive (adj)" },
  "unprecedented": { m: "un + precedent (tiền lệ) → chưa từng có tiền lệ trong quá khứ.", e: "Sai: unprecedent growth → Đúng: unprecedented growth. Sai: never unprecedented → Đúng: unprecedented (đã mang nghĩa phủ định).", u: "IELTS Writing Task 2: 'an unprecedented rate of urbanisation'; Reading về biến đổi khí hậu, công nghệ.", f: "unprecedented (adj), precedent (n), set a precedent, unparalleled (adj)" },
  "consensus": { m: "con (cùng) + sens (cảm nhận) → mọi người cùng chung cảm nhận, đồng thuận.", e: "Sai: general consensus of opinion → Đúng: a consensus / general consensus. Sai: concensus → Đúng: consensus.", u: "IELTS Reading: 'There is a scientific consensus that...'; Writing: 'reach a consensus', 'no consensus on'.", f: "consensus (n), consensual (adj), reach a consensus, agreement (n)" },
  "contention": { m: "contend (khăng khăng) → luận điểm người ta giữ chặt, hoặc điểm gây tranh cãi.", e: "Sai: my contention is about that → Đúng: my contention is that... 'bone of contention' = nguyên nhân tranh cãi.", u: "IELTS Reading: 'The author's main contention is...' – câu hỏi ý chính; Writing: 'It is my contention that...'", f: "contention (n), contend (v), contentious (adj), bone of contention" },
  "rationale": { m: "ratio (lý trí) → lý do có lý đằng sau một quyết định.", e: "Sai: rational behind the plan → Đúng: rationale behind the plan (rational là tính từ). Phát âm /ˌræʃəˈnɑːl/.", u: "IELTS Writing: 'The rationale behind this policy is...'; TOEIC/công sở: trình bày rationale cho đề xuất ngân sách.", f: "rationale (n), rational (adj), rationalise (v), justification (n)" },
  "anomaly": { m: "a (không) + nomal ~ normal → điều không bình thường, lệch quy luật.", e: "Sai: an anomaly result → Đúng: an anomalous result / an anomaly. Số nhiều: anomalies.", u: "IELTS Reading bài khoa học: 'This anomaly puzzled researchers'; Writing Task 1: chỉ ra điểm bất thường trên biểu đồ.", f: "anomaly (n), anomalous (adj), anomalies (pl), irregularity (n)" },
  "causal link": { m: "causal (thuộc nguyên nhân, ≠ casual) → sợi dây nối nguyên nhân với kết quả.", e: "Sai: casual link → Đúng: causal link. Sai: causal link of A and B → Đúng: causal link between A and B.", u: "IELTS Reading: 'no causal link has been established' → khác tương quan; Writing: phân biệt correlation và causation.", f: "causal (adj), cause (n/v), causation (n), causality (n), correlation (n)" },
  "peer-reviewed": { m: "peer (đồng nghiệp ngang hàng) + review → bài được các nhà khoa học khác thẩm định.", e: "Sai: a peer review journal → Đúng: a peer-reviewed journal. Danh từ: peer review (không gạch nối).", u: "IELTS Reading: 'published in a peer-reviewed journal' = nguồn đáng tin; Speaking Part 3 về độ tin cậy thông tin.", f: "peer review (n), peer-review (v), peer (n), refereed (adj)" },
  "randomised controlled trial": { m: "Chia ngẫu nhiên (random) người tham gia vào nhóm thử và nhóm đối chứng (control).", e: "Sai: random control trial → Đúng: randomised controlled trial (RCT). Mỹ viết randomized.", u: "IELTS Reading bài y học: 'A randomised controlled trial showed...'; ngành y dược, nghiên cứu lâm sàng.", f: "RCT (abbr), clinical trial (n), control group (n), placebo (n), randomise (v)" },
  "prevalence": { m: "prevail (thắng thế) → mức độ một thứ chiếm ưu thế, phổ biến trong dân số.", e: "Sai: the prevalence about obesity → Đúng: the prevalence of obesity. Sai: prevalency → Đúng: prevalence.", u: "IELTS Writing Task 1/2: 'the prevalence of smartphones'; Reading y tế: prevalence of a disease.", f: "prevalence (n), prevalent (adj), prevail (v), prevailing (adj)" },
  "onset": { m: "on + set → lúc mọi thứ bắt đầu 'được bật lên', nhất là bệnh tật hay mùa.", e: "Sai: the onset from winter → Đúng: the onset of winter. Dùng cho điều xấu/khó chịu bắt đầu.", u: "IELTS Reading y học: 'the onset of dementia'; Writing: 'with the onset of the digital age'.", f: "onset (n), outset (n), beginning (n), start (n), set in (phr v)" },
  "proliferation": { m: "proli- (con cái) + fer (sinh) → sinh sôi nảy nở rất nhanh.", e: "Sai: the proliferation in fast-food → Đúng: the proliferation of fast-food outlets. Thường mang sắc thái tiêu cực.", u: "IELTS Writing Task 2: 'the proliferation of social media'; Reading: nuclear proliferation, cell proliferation.", f: "proliferation (n), proliferate (v), spread (n), surge (n)" },
  "deterioration": { m: "deterior (tệ hơn) → càng ngày càng xấu đi.", e: "Sai: deterioration of health is getting worse → Đúng: health is deteriorating / deterioration in health. Sai: deteroration.", u: "IELTS Writing Task 2: 'the deterioration of air quality in cities'; Reading môi trường, sức khỏe.", f: "deterioration (n), deteriorate (v), decline (n), worsening (n)" },
  "dwindle": { m: "Hình ảnh: ngọn nến nhỏ dần nhỏ dần rồi gần tắt.", e: "Sai: the number was dwindled → Đúng: the number dwindled (nội động từ). Sai: dwindle down to zero quickly → dần dần.", u: "IELTS Reading: 'dwindling fish stocks'; Writing Task 1: 'numbers dwindled to just 200 by 2010'.", f: "dwindle (v), dwindling (adj), decrease (v), diminish (v), shrink (v)" },
  "curtail": { m: "cur ~ cut + tail (đuôi) → cắt bớt đuôi → cắt giảm, rút ngắn.", e: "Sai: curtail on spending → Đúng: curtail spending. Không nhầm 'curtain' (rèm cửa).", u: "IELTS Writing Task 2: 'governments should curtail car use'; Reading: chính sách curtail freedoms, budgets.", f: "curtail (v), curtailment (n), cut back (phr v), restrict (v), limit (v)" },
  "exacerbate": { m: "ex + acer (chua, gắt) → làm vấn đề vốn tệ càng gắt, càng tệ hơn.", e: "Sai: exacerbate the good situation → Đúng: exacerbate the problem. Chỉ dùng cho điều vốn đã xấu.", u: "IELTS Writing Task 2: 'Urban sprawl exacerbates traffic congestion'; Reading môi trường, y tế.", f: "exacerbate (v), exacerbation (n), worsen (v), aggravate (v), intensify (v)" },
  "aggravate": { m: "a + grav (nặng, như 'gravity') → làm nặng thêm vết thương, vấn đề.", e: "Sai: aggravate the success → Đúng: aggravate the injury. Thân mật 'aggravate' còn = làm bực mình.", u: "IELTS Reading y khoa: 'Stress can aggravate asthma'; ngành luật: aggravated assault (tình tiết tăng nặng).", f: "aggravate (v), aggravation (n), aggravating (adj), exacerbate (v)" },
  "counteract": { m: "counter (ngược lại) + act → hành động ngược chiều để trung hòa tác hại.", e: "Sai: counteract against the effect → Đúng: counteract the effect. Không cần giới từ sau động từ.", u: "IELTS Writing Task 2: 'measures to counteract obesity'; Reading y học: thuốc counteract tác dụng phụ.", f: "counteract (v), counteraction (n), offset (v), neutralise (v)" },
  "precipitate": { m: "Hình ảnh: đẩy ai rơi đầu xuống trước (praeceps) → khiến sự việc xảy ra đột ngột, sớm hơn.", e: "Sai: precipitate to a crisis → Đúng: precipitate a crisis. Danh từ 'precipitation' còn = lượng mưa.", u: "IELTS Reading lịch sử, kinh tế: 'The scandal precipitated his resignation'; hóa học: kết tủa.", f: "precipitate (v/adj/n), precipitation (n), trigger (v), spark (v)" },
  "give rise to": { m: "Hình ảnh: trao cho (give) một thứ sự trỗi dậy (rise) → làm nó xuất hiện.", e: "Sai: give rise to increase → Đúng: give rise to an increase / give rise to concerns. Không chia 'raise'.", u: "IELTS Writing Task 2: 'Urbanisation has given rise to many social problems'; Reading: chuỗi nguyên nhân – hệ quả.", f: "give rise to, lead to, bring about, result in, cause (v)" },
  "stem from": { m: "Hình ảnh: cành mọc ra từ thân cây (stem) → vấn đề mọc ra từ gốc rễ.", e: "Sai: the problem is stemmed from → Đúng: the problem stems from... (chủ động). Sai: stem by → Đúng: stem from.", u: "IELTS Writing Task 2: 'Many health issues stem from poor diet'; Reading: tìm nguyên nhân gốc.", f: "stem from, arise from, result from, originate in, derive from" },
  "account for": { m: "account (bản kê) → kê ra phần chiếm bao nhiêu, hoặc giải thích lý do.", e: "Sai: 30% is accounted for by coal (nghĩa chiếm) → Đúng: coal accounts for 30%. Sai: account 30% → thiếu 'for'.", u: "IELTS Writing Task 1: 'Coal accounted for 40% of energy use'; Reading: 'This accounts for the decline'.", f: "account for, make up, represent (v), constitute (v), explain (v)" },
  "attributable": { m: "attribute (quy cho) + -able → có thể quy nguyên nhân cho cái gì.", e: "Sai: attributable for smoking → Đúng: attributable to smoking. Luôn đi với 'to'.", u: "IELTS Reading: 'deaths attributable to air pollution'; Writing Task 2: phân tích nguyên nhân bằng văn phong học thuật.", f: "attributable (adj), attribute (v), attribution (n), due to, owing to" },
  "precursor": { m: "pre (trước) + cursor (người chạy) → người chạy trước mở đường.", e: "Sai: precursor to be the internet → Đúng: a precursor to/of the internet. Không nhầm 'predecessor' (người tiền nhiệm).", u: "IELTS Reading lịch sử công nghệ: 'ARPANET was a precursor to the internet'; y học: precursor of disease.", f: "precursor (n), forerunner (n), predecessor (n), antecedent (n)" },
  "forerunner": { m: "fore (phía trước) + runner (người chạy) → người/vật chạy trước, báo hiệu cái sau.", e: "Sai: forerunner for the computer → Đúng: forerunner of the computer. Sai: fore-runner → Đúng: forerunner.", u: "IELTS Reading: 'The abacus was a forerunner of the calculator'; dạng câu Matching phát minh – thời kỳ.", f: "forerunner (n), precursor (n), pioneer (n), harbinger (n)" },
  "advent": { m: "ad (đến) + vent (đi) → sự đến của một thứ quan trọng, như Mùa Vọng chờ Giáng sinh.", e: "Sai: since the advent the internet → Đúng: since the advent of the internet. Không dùng cho việc nhỏ.", u: "IELTS Writing Task 2: 'With the advent of smartphones, communication has changed'; Reading lịch sử công nghệ.", f: "advent (n), arrival (n), emergence (n), coming (n)" },
  "inception": { m: "in + cept (lấy, nhận) → thời điểm bắt đầu nhận hình hài, thành lập.", e: "Sai: from the inception → Đúng: since its inception / from its inception. Thường đi với tính từ sở hữu.", u: "IELTS Reading: 'Since its inception in 1990, the charity has...'; TOEIC: lịch sử công ty.", f: "inception (n), beginning (n), outset (n), founding (n), establishment (n)" },
  "emergence": { m: "emerge (trồi lên khỏi mặt nước) → sự trồi lên, xuất hiện rõ ràng.", e: "Sai: the emergency of new technology → Đúng: the emergence of new technology (emergency = khẩn cấp).", u: "IELTS Writing Task 2: 'the emergence of the gig economy'; Reading: sự xuất hiện của loài, xu hướng mới.", f: "emergence (n), emerge (v), emerging (adj), emergent (adj)" },
  "milestone": { m: "Hình ảnh: cột đá (stone) ghi số dặm (mile) bên đường → mốc quan trọng.", e: "Sai: a mile stone → Đúng: a milestone. Sai: reach to a milestone → Đúng: reach a milestone.", u: "IELTS Speaking Part 2: 'a milestone in my life'; Reading: milestones in medicine; công sở: project milestones.", f: "milestone (n), landmark (n), turning point (n), achievement (n)" },
  "pioneering": { m: "pioneer (người đi khai hoang) → đi đầu, mở lối mới chưa ai làm.", e: "Sai: a pioneer work → Đúng: pioneering work. Sai: pioneering of → Đúng: a pioneer of / pioneering research.", u: "IELTS Reading: 'her pioneering research on vaccines'; Speaking Part 2: mô tả nhà khoa học hoặc doanh nhân tiên phong.", f: "pioneering (adj), pioneer (n/v), innovative (adj), groundbreaking (adj)" },
  "groundbreaking": { m: "Hình ảnh: nhát cuốc đầu tiên phá đất (break ground) khởi công → mở ra hướng mới hoàn toàn.", e: "Sai: a ground breaking → Đúng: a groundbreaking discovery. Không dùng cho việc bình thường.", u: "IELTS Reading/Writing: 'groundbreaking research in genetics'; Speaking: mô tả phát minh ấn tượng.", f: "groundbreaking (adj), break new ground, revolutionary (adj), pioneering (adj)" },
  "seminal": { m: "semen (hạt giống) → công trình như hạt giống mọc ra cả một lĩnh vực.", e: "Sai: a seminal of research → Đúng: a seminal study / seminal work. Không nhầm 'seminar' (hội thảo).", u: "IELTS Reading học thuật: 'Darwin's seminal work On the Origin of Species'; Writing: trích nghiên cứu nền tảng.", f: "seminal (adj), influential (adj), formative (adj), landmark (adj)" },
  "prevailing": { m: "prevail (chiếm ưu thế) → quan điểm hay gió đang thắng thế lúc này.", e: "Sai: the prevailed view → Đúng: the prevailing view. Sai: prevailing to → Đúng: prevailing in/among.", u: "IELTS Reading: 'contrary to the prevailing view'; địa lý: prevailing winds; Writing: thay cho 'common'.", f: "prevailing (adj), prevail (v), prevalent (adj), dominant (adj)" },
  "prevalent": { m: "prevail → điều xuất hiện ở khắp nơi trong một nhóm hay khu vực.", e: "Sai: prevalent with young people → Đúng: prevalent among young people. Sai: prevalant → Đúng: prevalent.", u: "IELTS Writing Task 2: 'Obesity is increasingly prevalent among children'; Reading y tế, xã hội.", f: "prevalent (adj), prevalence (n), prevail (v), widespread (adj), common (adj)" },
  "ubiquitous": { m: "ubique (khắp nơi, Latin) → có mặt ở mọi nơi, như smartphone bây giờ.", e: "Sai: ubiquitous everywhere → Đúng: ubiquitous (đã có nghĩa khắp nơi). Phát âm /juːˈbɪkwɪtəs/.", u: "IELTS Writing Task 2: 'Smartphones have become ubiquitous'; Speaking Part 3: nói về công nghệ, quảng cáo.", f: "ubiquitous (adj), ubiquity (n), ubiquitously (adv), omnipresent (adj)" },
  "scarce": { m: "Nghe như 'scare' (sợ) → sợ vì thứ cần dùng quá khan hiếm.", e: "Sai: water is scarcely → Đúng: water is scarce. 'scarcely' = hầu như không. Sai: scarce of → Đúng: short of.", u: "IELTS Writing Task 2: 'as natural resources become scarce'; Reading môi trường, kinh tế: scarce water supplies.", f: "scarce (adj), scarcity (n), scarcely (adv), rare (adj), limited (adj)" },
  "abundant": { m: "ab + und (sóng, như 'undulate') → tràn trề như sóng, dồi dào.", e: "Sai: abundant of fish → Đúng: abundant in fish / an abundance of fish. Sai: abundent → Đúng: abundant.", u: "IELTS Reading sinh thái: 'Fish were once abundant in this river'; Writing: abundant resources, abundant evidence.", f: "abundant (adj), abundance (n), abound (v), abundantly (adv), plentiful (adj)" },
  "sparse": { m: "Nghe như 'spare' (dư ra, rải rác) → thưa thớt, lác đác vài chỗ.", e: "Sai: the population is sparsity → Đúng: the population is sparse. Sai: sparse information many → Đúng: sparse information.", u: "IELTS Reading địa lý: 'sparsely populated areas'; Writing Task 1 bản đồ: sparse vegetation.", f: "sparse (adj), sparsely (adv), sparsity (n), thin (adj), scattered (adj)" },
  "dormant": { m: "dorm (ngủ, như 'dormitory') → đang ngủ yên, chưa hoạt động nhưng có thể thức dậy.", e: "Sai: a dead volcano can erupt → Đúng: a dormant volcano can erupt (dead/extinct = tắt hẳn).", u: "IELTS Reading tự nhiên: 'dormant volcanoes', 'seeds lie dormant in winter'; kinh doanh: dormant accounts.", f: "dormant (adj), dormancy (n), inactive (adj), latent (adj), extinct (adj)" },
  "viable": { m: "vi- (sự sống, như 'vital') → có thể sống sót, tồn tại được lâu dài.", e: "Sai: a viable plan to be fail → Đúng: a viable plan. Sai: viability option → Đúng: viable option.", u: "IELTS Writing Task 2: 'a viable alternative to fossil fuels'; kinh doanh: commercially viable; sinh học: viable seeds.", f: "viable (adj), viability (n), feasible (adj), workable (adj)" },
  "feasible": { m: "feas- ~ 'do' (làm, tiếng Pháp faire) → làm được trong thực tế.", e: "Sai: it is feasible to be done easily → Đúng: it is feasible to do. Sai: feasibility plan → Đúng: feasible plan / feasibility study.", u: "IELTS Writing Task 2: 'This solution is not economically feasible'; công sở: feasibility study trước dự án.", f: "feasible (adj), feasibility (n), infeasible (adj), practicable (adj)" },
  "robust": { m: "robur (gỗ sồi, Latin) → chắc như gỗ sồi, không dễ gãy.", e: "Sai: robust and strongly → Đúng: robust evidence / a robust system. Không dùng cho người khỏe mạnh lực lưỡng thông thường.", u: "IELTS Reading/Writing: 'robust evidence', 'a robust economy'; công nghệ: robust software chịu lỗi tốt.", f: "robust (adj), robustness (n), robustly (adv), sturdy (adj), solid (adj)" },
  "fragile": { m: "frag- (vỡ, như 'fragment') → dễ vỡ thành mảnh, mong manh.", e: "Sai: fragile of breaking → Đúng: fragile / easily broken. Sai: fragility ecosystem → Đúng: fragile ecosystem.", u: "IELTS Writing Task 2 môi trường: 'fragile ecosystems'; Reading: fragile economy, fragile peace.", f: "fragile (adj), fragility (n), delicate (adj), vulnerable (adj), brittle (adj)" },
  "resilient": { m: "re (lại) + sil (nhảy) → bị ép xuống rồi bật lại như lò xo.", e: "Sai: resilient with stress → Đúng: resilient to stress. Sai: resilent → Đúng: resilient.", u: "IELTS Speaking Part 2: mô tả người kiên cường; Writing: resilient communities, resilient crops chịu hạn.", f: "resilient (adj), resilience (n), resiliently (adv), tough (adj), adaptable (adj)" },
  "susceptible": { m: "sus (dưới) + cept (nhận) → dễ tiếp nhận tác động xấu từ bên ngoài.", e: "Sai: susceptible with infection → Đúng: susceptible to infection. Luôn đi với 'to'.", u: "IELTS Reading y học: 'Children are more susceptible to the disease'; Writing: susceptible to advertising.", f: "susceptible (adj), susceptibility (n), vulnerable (adj), prone to (adj)" },
  "prone to": { m: "prone = nằm sấp, nghiêng về phía trước → có xu hướng ngả về điều xấu.", e: "Sai: prone to get sick → Đúng: prone to illness / prone to getting sick. Thường đi với danh từ hoặc V-ing.", u: "IELTS Writing Task 2: 'Elderly people are prone to loneliness'; Reading: flood-prone areas, error-prone.", f: "prone to, susceptible to, liable to, flood-prone (adj), accident-prone (adj)" },
  "endemic": { m: "en (trong) + demos (dân) → chỉ có trong một vùng/dân cư nhất định.", e: "Sai: endemic in Australia only for koalas → Đúng: koalas are endemic to Australia. Không nhầm 'epidemic' (dịch bùng phát).", u: "IELTS Reading sinh học: 'species endemic to Madagascar'; y tế: malaria is endemic in parts of Africa.", f: "endemic (adj), endemism (n), native (adj), epidemic (n), pandemic (n)" },
  "trait": { m: "Nghe như 'nét' của tính cách → nét đặc trưng của một người hay loài.", e: "Sai: personal trait good → Đúng: a good personality trait. Phát âm Anh /treɪ/ hoặc /treɪt/.", u: "IELTS Speaking Part 2: mô tả tính cách người thân; Reading di truyền: genetic traits, inherited traits.", f: "trait (n), characteristic (n), feature (n), attribute (n), quality (n)" },
  "inherit": { m: "in + heir (người thừa kế) → nhận lại từ cha mẹ: tài sản hoặc gen.", e: "Sai: inherit to my father → Đúng: inherit something from my father. Không nhầm 'inhabit' (cư trú).", u: "IELTS Reading sinh học: 'traits inherited from parents'; Speaking: 'I inherited my mother's sense of humour'.", f: "inherit (v), inheritance (n), heir (n), hereditary (adj), heritage (n)" },
  "cognitive": { m: "cogn- (biết, như 'recognise') → liên quan đến quá trình hiểu biết, suy nghĩ, nhớ.", e: "Sai: cognition skills → Đúng: cognitive skills. Sai: cognitive of children → Đúng: children's cognitive development.", u: "IELTS Writing Task 2: video games and cognitive development; Reading tâm lý học: cognitive decline, cognitive ability.", f: "cognitive (adj), cognition (n), cognitively (adv), recognise (v)" },
  "deprivation": { m: "de + priv (riêng, tước) → bị tước mất thứ cần thiết.", e: "Sai: sleep deprive → Đúng: sleep deprivation. Sai: deprived from food → Đúng: deprived of food.", u: "IELTS Reading/Writing: 'sleep deprivation impairs memory'; xã hội học: social deprivation, poverty.", f: "deprivation (n), deprive (v), deprived (adj), privation (n), lack (n)" },
  "intake": { m: "in + take → lượng được 'lấy vào' cơ thể; cũng là số học viên tuyển vào.", e: "Sai: the intake of sugar is too many → Đúng: sugar intake is too high. Sai: in-take → Đúng: intake.", u: "IELTS Reading/Writing sức khỏe: daily calorie intake, reduce salt intake; giáo dục: annual student intake.", f: "intake (n), take in (phr v), consumption (n), input (n)" },
  "threshold": { m: "Hình ảnh: bậc cửa (threshold) → bước qua là sang mức khác, như ngưỡng.", e: "Sai: treshold → Đúng: threshold. Sai: above threshold → Đúng: above the threshold. Sai: threshold for pain (y học) → Đúng: pain threshold.", u: "IELTS Reading y khoa: pain threshold; kinh tế: tax threshold; Writing: 'on the threshold of a new era'.", f: "threshold (n), limit (n), boundary (n), on the threshold of" },
  "magnitude": { m: "magn- (lớn, như 'magnify') → độ lớn, mức độ to tát của sự việc.", e: "Sai: the magnitude of problem → Đúng: the magnitude of the problem. Sai: magnitude big → Đúng: great magnitude.", u: "IELTS Reading: earthquake of magnitude 7; Writing Task 2: 'the magnitude of climate change'.", f: "magnitude (n), magnify (v), scale (n), extent (n), order of magnitude" },
  "negligible": { m: "neglect (bỏ qua) + -ible → nhỏ đến mức có thể bỏ qua.", e: "Sai: negligent effect → Đúng: negligible effect (negligent = cẩu thả). Sai: neglectable → Đúng: negligible.", u: "IELTS Writing Task 1: 'a negligible change'; Reading: 'the risk is negligible'.", f: "negligible (adj), negligibly (adv), neglect (v), insignificant (adj), minimal (adj)" },
  "disproportionate": { m: "dis + proportion (tỉ lệ) → lệch tỉ lệ, nhiều hoặc ít bất hợp lý.", e: "Sai: disproportionate with → Đúng: disproportionate to. Sai: disproportional effect on poor → Đúng: a disproportionate effect on the poor.", u: "IELTS Writing Task 2: 'Pollution has a disproportionate impact on low-income families'; Reading xã hội học.", f: "disproportionate (adj), disproportionately (adv), proportion (n), proportionate (adj)" },
  "trade-off": { m: "trade (đổi) + off → đổi cái này lấy cái kia, được cái này mất cái khác.", e: "Sai: a trade-off of cost and quality → Đúng: a trade-off between cost and quality. Động từ: trade off (không gạch).", u: "IELTS Writing Task 2: 'a trade-off between economic growth and environmental protection'; kinh tế, quản lý.", f: "trade-off (n), trade off (phr v), compromise (n), balance (n)" },
  "by-product": { m: "by (bên cạnh) + product → sản phẩm sinh ra bên lề quy trình chính.", e: "Sai: side-product → Đúng: by-product. Sai: by-product from the process of → Đúng: a by-product of the process.", u: "IELTS Writing Task 1 quy trình: 'Waste heat is a by-product'; Reading công nghiệp, môi trường.", f: "by-product (n), byproduct (n, Mỹ), side effect (n), spin-off (n)" },
  "impetus": { m: "im + pet (lao tới) → lực đẩy lao tới, cú hích cho sự thay đổi.", e: "Sai: impetus to do → Đúng: an impetus for change / impetus to reform. Sai: impetuses nhiều → hiếm dùng số nhiều.", u: "IELTS Reading: 'The crisis gave fresh impetus to reform'; Writing: động lực thúc đẩy chính sách.", f: "impetus (n), stimulus (n), momentum (n), incentive (n), drive (n)" },
  "underpin": { m: "Hình ảnh: đóng cọc (pin) bên dưới (under) móng nhà để đỡ cả công trình.", e: "Sai: underpin on the theory → Đúng: underpin the theory. Quá khứ: underpinned (gấp đôi n).", u: "IELTS Reading: 'the principles that underpin modern science'; Writing: values underpinning education.", f: "underpin (v), underpinning (n), support (v), form the basis of" },
  "underlying": { m: "under + lying (nằm) → nằm bên dưới, khó thấy nhưng là gốc.", e: "Sai: the underlined cause → Đúng: the underlying cause. Không nhầm 'underlined' (gạch chân).", u: "IELTS Writing Task 2: 'address the underlying causes of crime'; y học: underlying health conditions.", f: "underlying (adj), underlie (v), fundamental (adj), root (adj), hidden (adj)" },
  "hitherto": { m: "hither (đến đây) + to → tính đến thời điểm đó.", e: "Sai: hitherto known now → Đúng: hitherto unknown. Rất trang trọng, không dùng trong Speaking thường ngày.", u: "IELTS Reading học thuật: 'a hitherto unknown species'; Writing: dùng tiết kiệm thay cho 'previously'.", f: "hitherto (adv), previously (adv), until now, thus far, heretofore (adv)" },
  "to date": { m: "Tính đến (to) ngày (date) hôm nay → tới thời điểm hiện tại.", e: "Sai: to date, scientists found → Đúng: to date, scientists have found (hiện tại hoàn thành).", u: "IELTS Reading/Writing: 'To date, no cure has been found'; báo cáo công việc: progress to date.", f: "to date, so far, up to now, thus far, up-to-date (adj, khác nghĩa)" },
  "as yet": { m: "as + yet (chưa) → cho đến giờ vẫn chưa, có thể sau này.", e: "Sai: as yet it has been solved → Đúng: it has as yet not been solved / as yet unknown. Đi với phủ định.", u: "IELTS Reading: 'The cause is as yet unknown' → thông tin chưa có, cẩn thận Not Given; Writing trang trọng.", f: "as yet, so far, still (adv), yet (adv), to date" },
  "by and large": { m: "Thành ngữ hàng hải: tàu đi được cả ngược lẫn xuôi gió → nhìn tổng thể.", e: "Sai: by and large of people → Đúng: By and large, people agree. Đứng đầu câu, có dấu phẩy.", u: "IELTS Speaking Part 3: 'By and large, I think young people are...'; Writing: khái quát ý trước khi nêu ngoại lệ.", f: "by and large, on the whole, generally, overall, all in all" },
  "in essence": { m: "essence (tinh chất) → gạn hết chi tiết, còn lại cốt lõi.", e: "Sai: in the essence → Đúng: in essence. Sai: essentially in essence → tránh lặp nghĩa.", u: "IELTS Writing Task 2 kết luận: 'In essence, both sides have merit'; Speaking: tóm ý ngắn gọn.", f: "in essence, essentially (adv), basically (adv), essence (n), essential (adj)" },
  "contrary to": { m: "contra (ngược) → đi ngược với điều mọi người tin hay mong đợi.", e: "Sai: contrary with popular belief → Đúng: contrary to popular belief. Không nhầm 'on the contrary' (ngược lại).", u: "IELTS Writing/Reading: 'Contrary to popular belief, ...' – báo hiệu thông tin đối lập, hay ra câu FALSE.", f: "contrary to, on the contrary, contrary (adj), contrast (n), in contrast to" },
  "akin to": { m: "a + kin (họ hàng) → như có họ với nhau, rất giống nhau.", e: "Sai: akin with → Đúng: akin to. Sai: it is akin a game → Đúng: it is akin to a game.", u: "IELTS Writing Task 2: 'Addiction to phones is akin to substance abuse'; Reading: so sánh tương đồng.", f: "akin to, similar to, comparable to, kin (n), kinship (n)" },
  "analogous": { m: "analogy (phép loại suy) → giống đến mức có thể đem so sánh.", e: "Sai: analogous with → Đúng: analogous to. Phát âm /əˈnæləɡəs/.", u: "IELTS Reading khoa học: 'The heart is analogous to a pump'; Writing: lập luận bằng so sánh.", f: "analogous (adj), analogy (n), analogue (n), comparable (adj), similar (adj)" },
  "tantamount to": { m: "tant (bằng chừng ấy) + amount → có giá trị bằng chừng ấy, chẳng khác gì.", e: "Sai: tantamount as → Đúng: tantamount to. Thường dùng cho điều tiêu cực: tantamount to theft.", u: "IELTS Writing Task 2: 'Banning cars is tantamount to punishing commuters'; Reading pháp lý, chính trị.", f: "tantamount to, equivalent to, as good as, amount to (phr v)" },
  "synonymous with": { m: "syn (cùng) + onym (tên) → cùng một cái tên, nghĩ đến cái này là ra cái kia.", e: "Sai: synonymous to Paris → Đúng: synonymous with Paris. Sai: synonym with → Đúng: synonymous with.", u: "IELTS Speaking Part 2: 'My hometown is synonymous with pho'; Writing: brand synonymous with quality.", f: "synonymous with, synonym (n), associated with, identical to" },
  "in the wake of": { m: "Hình ảnh: vệt sóng (wake) để lại sau con tàu → hệ quả ngay sau một sự kiện.", e: "Sai: in the wake to the crisis → Đúng: in the wake of the crisis. Thường dùng sau sự kiện lớn, tiêu cực.", u: "IELTS Reading/Writing: 'In the wake of the pandemic, remote work boomed'; báo chí, kinh tế.", f: "in the wake of, following (prep), as a result of, in the aftermath of" },
  "as opposed to": { m: "opposed (đối lập) → đặt hai thứ đối diện để phân biệt rõ.", e: "Sai: as opposed with → Đúng: as opposed to. Sau 'to' là danh từ/V-ing: as opposed to driving.", u: "IELTS Writing Task 2: 'online learning, as opposed to classroom teaching'; Speaking: phân biệt hai lựa chọn.", f: "as opposed to, rather than, in contrast to, unlike (prep)" },
  "the graph shows": { m: "Câu mở bài Task 1 an toàn nhất: graph (đồ thị) + shows (cho thấy) → paraphrase đề.", e: "Sai: the graph show → Đúng: the graph shows (chủ ngữ số ít). Sai: the graph is showing about → Đúng: the graph shows.", u: "IELTS Writing Task 1 mở bài: 'The graph shows changes in...'; nên đổi sang illustrates, compares để tránh lặp đề.", f: "the graph shows/illustrates/depicts/reveals, line graph (n), graph (n)" },
  "the chart illustrates": { m: "illustrate (minh họa bằng hình) → biểu đồ vẽ ra số liệu thay cho lời.", e: "Sai: the chart illustrate → Đúng: the chart illustrates. Sai: illustrates about → Đúng: illustrates how/what...", u: "IELTS Writing Task 1: 'The bar chart illustrates the number of...'; dùng thay 'shows' để đa dạng từ vựng.", f: "illustrate (v), illustration (n), the chart shows/depicts/presents" },
  "the table compares": { m: "Bảng (table) đặt các cột cạnh nhau → so sánh (compares) trực tiếp.", e: "Sai: the table compares between A and B → Đúng: the table compares A and B / A with B.", u: "IELTS Writing Task 1 dạng bảng: 'The table compares the cost of living in five cities'.", f: "compare (v), comparison (n), comparative (adj), the table gives information about" },
  "the diagram depicts": { m: "depict (vẽ lại) → sơ đồ vẽ lại quy trình hoặc cấu tạo.", e: "Sai: the diagram depicts about → Đúng: the diagram depicts how... Sai: depicted → dùng hiện tại đơn khi mô tả.", u: "IELTS Writing Task 1 quy trình/bản đồ: 'The diagram depicts how glass is recycled'.", f: "depict (v), depiction (n), the diagram shows/outlines/illustrates" },
  "it is clear that": { m: "clear (rõ) → câu mở Overview: điều ai nhìn biểu đồ cũng thấy ngay.", e: "Sai: it is clearly that → Đúng: it is clear that / clearly,... Sai: it's clear to see that rambling → ngắn gọn.", u: "IELTS Writing Task 1 overview: 'Overall, it is clear that car use rose'; Task 2: dẫn đến kết luận.", f: "clearly (adv), it is evident that, it is apparent that, overall" },
  "as can be seen": { m: "Như (as) có thể thấy (can be seen) → mời người đọc nhìn vào số liệu.", e: "Sai: as can be seen in the graph that → Đúng: as can be seen from the graph, sales rose. Bỏ 'that'.", u: "IELTS Writing Task 1: 'As can be seen from the chart, ...' dẫn vào chi tiết; tránh dùng quá 1 lần.", f: "as can be seen, as is shown, according to the chart, it can be seen that" },
  "over the period": { m: "over (trải dài suốt) + the period → cả khoảng thời gian từ đầu đến cuối.", e: "Sai: during over the period → Đúng: over the period 1990–2010. Sai: in the period of from → Đúng: over the period shown.", u: "IELTS Writing Task 1: 'over the period shown', 'over the 20-year period' – thường trong overview.", f: "over the period, throughout the period, during, over the course of" },
  "a striking feature": { m: "striking (đập vào mắt) → điểm nổi bật khiến người đọc chú ý ngay.", e: "Sai: a strike feature → Đúng: a striking feature. Sai: the most striking features is → Đúng: feature is.", u: "IELTS Writing Task 1 overview: 'A striking feature of the graph is the sharp drop in...'", f: "striking (adj), strikingly (adv), notable feature, key feature, noticeable trend" },
  "rise sharply": { m: "sharp (sắc, dốc) → đường đồ thị dựng đứng lên, tăng mạnh.", e: "Sai: rise sharp → Đúng: rise sharply (trạng từ). Sai: rose sharply up → Đúng: rose sharply.", u: "IELTS Writing Task 1: 'Sales rose sharply to 500 units in 2010'; biến thể: a sharp rise in.", f: "rise sharply, a sharp rise, soar (v), surge (v), rocket (v)" },
  "increase steadily": { m: "steady (vững, đều) → đường đồ thị đi lên đều đều, không giật.", e: "Sai: increase steady → Đúng: increase steadily / a steady increase. Sai: increased steadily up → bỏ 'up'.", u: "IELTS Writing Task 1: 'The figure increased steadily over the decade'; đối lập với fluctuate.", f: "steadily (adv), steady (adj), gradual increase, rise consistently" },
  "level off": { m: "Hình ảnh: máy bay cất cánh xong thì bay ngang (level) → đường đồ thị đi ngang.", e: "Sai: was levelled off → Đúng: levelled off (nội động từ). Sai: level off to stable → Đúng: level off at 50%.", u: "IELTS Writing Task 1: 'Unemployment levelled off at 5% after 2008'; tương tự plateau, stabilise.", f: "level off/out, plateau (v/n), stabilise (v), flatten out" },
  "remain stable": { m: "remain (vẫn giữ) + stable (ổn định) → con số đứng yên, không đổi.", e: "Sai: remain stably → Đúng: remain stable (remain + tính từ). Sai: remained stable in 20% → Đúng: at 20%.", u: "IELTS Writing Task 1: 'Prices remained stable at around $3'; thay bằng stay constant, remain unchanged.", f: "remain stable/constant/unchanged, stability (n), stabilise (v)" },
  "stabilise": { m: "stable (vững) + -ise → làm cho/trở nên vững lại sau dao động.", e: "Sai: stabilise at stable → Đúng: stabilise at 40%. Mỹ viết stabilize.", u: "IELTS Writing Task 1: 'The rate stabilised at 40% in 2015'; kinh tế: stabilise prices.", f: "stabilise (v), stable (adj), stability (n), stabilisation (n)" },
  "dip": { m: "Hình ảnh: nhúng (dip) bánh vào nước rồi nhấc lên → giảm nhẹ rồi hồi lại.", e: "Sai: a dip of sales → Đúng: a dip in sales. Sai: dipped drastically → dip chỉ là giảm nhẹ.", u: "IELTS Writing Task 1: 'There was a slight dip in 2005 before figures recovered'.", f: "dip (n/v), drop (n), slight fall, decline (n), recover (v)" },
  "hit a low": { m: "Hình ảnh: quả bóng rơi chạm (hit) điểm thấp nhất (low).", e: "Sai: hit the lowest point at → Đúng: hit a low of 10% / hit its lowest point. Sai: hitted → hit.", u: "IELTS Writing Task 1: 'Sales hit a low of 200 units in 2009'; tương tự reach a trough.", f: "hit a low, reach a trough, bottom out, all-time low, record low" },
  "reach a peak": { m: "peak (đỉnh núi) → leo đến điểm cao nhất của đường đồ thị.", e: "Sai: reach to a peak → Đúng: reach a peak of 80%. Sai: peaked at the peak → Đúng: peaked at 80%.", u: "IELTS Writing Task 1: 'Visitor numbers reached a peak of 2 million in 2015'.", f: "reach a peak, peak (v), hit a high, the highest point, peak at" },
  "bottom out": { m: "Hình ảnh: hòn đá chìm chạm đáy (bottom) → ngừng giảm, sắp hồi lên.", e: "Sai: bottomed out to zero → Đúng: bottomed out at 5%. Không dùng tân ngữ trực tiếp.", u: "IELTS Writing Task 1: 'Prices bottomed out in 2009 and then recovered'; tin tài chính.", f: "bottom out, hit a low, reach a trough, level off" },
  "rocket": { m: "Hình ảnh: tên lửa (rocket) phóng thẳng lên trời → tăng vọt bất ngờ.", e: "Sai: rocket up sharply → Đúng: rocketed to 90% (đã mang nghĩa mạnh). Sai: rockets of prices → Đúng: prices rocketed.", u: "IELTS Writing Task 1: 'House prices rocketed between 2000 and 2007'; tránh lạm dụng, chỉ cho mức tăng rất mạnh.", f: "rocket (v/n), soar (v), skyrocket (v), shoot up (phr v)" },
  "slump": { m: "Hình ảnh: người ngồi phịch (slump) xuống ghế → số liệu sụt mạnh, đột ngột.", e: "Sai: slump down quickly → Đúng: slumped to 20%. Danh từ: a slump in sales.", u: "IELTS Writing Task 1: 'Exports slumped in 2009'; kinh tế: economic slump, slump in demand.", f: "slump (v/n), plummet (v), plunge (v), collapse (v), recession (n)" },
  "marginal": { m: "margin (lề giấy) → thay đổi nhỏ như nằm sát mép lề.", e: "Sai: a marginally increase → Đúng: a marginal increase / increased marginally.", u: "IELTS Writing Task 1: 'a marginal rise of 1%'; kinh tế: marginal cost; xã hội: marginal groups.", f: "marginal (adj), marginally (adv), margin (n), slight (adj), negligible (adj)" },
  "upward trend": { m: "upward (hướng lên) + trend (xu hướng) → cả chặng dài đi lên.", e: "Sai: an up trend → Đúng: an upward trend. Sai: show upward trend → Đúng: show an upward trend.", u: "IELTS Writing Task 1 overview: 'There was an upward trend in internet use'; kinh doanh, báo cáo.", f: "upward trend, upward (adj/adv), rising trend, growth (n), downward trend" },
  "downward trend": { m: "downward (đi xuống) + trend → chiều hướng giảm kéo dài.", e: "Sai: a down trend → Đúng: a downward trend. Sai: downwards trend → downward (tính từ không -s).", u: "IELTS Writing Task 1 overview: 'Coal consumption followed a downward trend'.", f: "downward trend, downward (adj), downwards (adv), decline (n), upward trend" },
  "erratic": { m: "err (lạc đường) → đi lung tung không theo quy luật.", e: "Sai: an erratically trend → Đúng: an erratic trend / fluctuated erratically.", u: "IELTS Writing Task 1: 'Rainfall was erratic throughout the year'; mô tả dao động bất thường.", f: "erratic (adj), erratically (adv), fluctuating (adj), irregular (adj), volatile (adj)" },
  "is projected to": { m: "project (phóng chiếu) → chiếu đường đồ thị về tương lai để dự báo.", e: "Sai: is projected to increasing → Đúng: is projected to increase. Sai: projects to rise → Đúng: is projected to rise.", u: "IELTS Writing Task 1 dạng dự báo: 'The population is projected to reach 10 million by 2050'.", f: "be projected/predicted/expected/forecast to, projection (n)" },
  "it is estimated that": { m: "estimate (ước tính) → con số chỉ gần đúng, không chính xác tuyệt đối.", e: "Sai: it is estimating that → Đúng: it is estimated that... Sai: it estimates that → dùng bị động.", u: "IELTS Writing Task 1/2: 'It is estimated that 1 billion people lack clean water'; tránh nêu số tự bịa.", f: "estimate (v/n), estimation (n), it is thought/believed that, approximately" },
  "the figure for": { m: "figure (con số) + for (của) → con số thuộc về một nhóm, một nước.", e: "Sai: the figure of Japan → Đúng: the figure for Japan. Sai: the figures for Japan was → Đúng: were.", u: "IELTS Writing Task 1: 'The figure for France was much lower'; dùng để tránh lặp danh từ dài.", f: "the figure for, figures (n), the number of, the percentage of" },
  "the proportion of": { m: "proportion (phần, tỉ lệ) → phần chiếm trong tổng thể.", e: "Sai: the proportion of people are → Đúng: the proportion of people is. Sai: proportion of in → Đúng: the proportion of.", u: "IELTS Writing Task 1: 'The proportion of students who walk to school fell'; dùng cho dữ liệu %.", f: "proportion (n), proportional (adj), percentage (n), share (n)" },
  "the vast majority": { m: "vast (rộng lớn) + majority (đa số) → phần đa áp đảo.", e: "Sai: the vast majority of people thinks → Đúng: think (theo danh từ số nhiều). Sai: most majority → the vast majority.", u: "IELTS Writing Task 1: 'The vast majority of respondents (85%)'; Task 2: khái quát quan điểm.", f: "the vast majority, majority (n), most (det), the bulk of, a minority" },
  "a small minority": { m: "minority (thiểu số) → nhóm ít người, ngược với majority.", e: "Sai: a small minority of people agrees → Đúng: agree. Sai: a few minority → Đúng: a small minority.", u: "IELTS Writing Task 1: 'Only a small minority (3%) cycled to work'; Task 2: ý kiến thiểu số.", f: "minority (n), minor (adj), a handful of, a fraction of, the majority" },
  "nearly half": { m: "nearly (gần) + half (nửa) → thiếu một chút là một nửa.", e: "Sai: nearly half of the people was → Đúng: nearly half of the people were. Sai: near half → nearly half.", u: "IELTS Writing Task 1: 'Nearly half of all households owned a car (48%)'; diễn đạt số gần đúng.", f: "nearly half, almost half, just under half, roughly 50%" },
  "just over": { m: "just (vừa) + over (trên) → vượt quá một mốc tròn chút xíu.", e: "Sai: just over than 50% → Đúng: just over 50%. Sai: a little over than → bỏ 'than'.", u: "IELTS Writing Task 1: 'just over a quarter (26%)' – làm tròn số mềm mại, tăng điểm Lexical Resource.", f: "just over, slightly more than, a little over, just under" },
  "just under": { m: "just (vừa) + under (dưới) → thiếu một chút là chạm mốc tròn.", e: "Sai: just under of 30% → Đúng: just under 30%. Sai: just under than → bỏ 'than'.", u: "IELTS Writing Task 1: 'just under a third of the budget (32%)'; ghép với phân số.", f: "just under, slightly less than, almost, nearly, just over" },
  "two-thirds": { m: "Chia bánh làm 3, lấy 2 phần → khoảng 66%.", e: "Sai: two-third → Đúng: two-thirds (mẫu số số nhiều). Sai: the two-thirds of → Đúng: two-thirds of.", u: "IELTS Writing Task 1: 'Roughly two-thirds of respondents preferred online shopping'; diễn đạt % bằng phân số.", f: "two-thirds (n), a third, three-quarters, a fraction (n)" },
  "twice as many": { m: "twice (gấp đôi) + as many as → gấp đôi số lượng đếm được.", e: "Sai: twice more people than → Đúng: twice as many people as. Không đếm được: twice as much.", u: "IELTS Writing Task 1: 'Twice as many men as women worked in IT'; so sánh số lượng.", f: "twice as many/much as, double (v), three times as many, half as many" },
  "outnumber": { m: "out (vượt) + number (số) → vượt về số lượng.", e: "Sai: women outnumber than men → Đúng: women outnumber men. Sai: outnumbered by → nghĩa bị động, đổi chủ ngữ.", u: "IELTS Writing Task 1: 'Female students outnumbered male students in 2020'; câu so sánh gọn.", f: "outnumber (v), outweigh (v), exceed (v), surpass (v)" },
  "make up": { m: "Hình ảnh: các mảnh ghép lại tạo nên (make up) tổng thể.", e: "Sai: is made up 30% → Đúng: makes up 30%. 'is made up of' = gồm có.", u: "IELTS Writing Task 1: 'Women make up 45% of the workforce'; thay cho account for.", f: "make up, be made up of, comprise (v), constitute (v), account for" },
  "in comparison": { m: "comparison (sự so sánh) → đặt cạnh nhau để thấy khác biệt.", e: "Sai: in comparison of → Đúng: in comparison with/to. Đứng đầu câu: In comparison, ...", u: "IELTS Writing Task 1: 'In comparison, Italy spent far less'; Task 2: so sánh hai lựa chọn.", f: "in comparison, compared with/to, by comparison, comparatively (adv)" },
  "in stark contrast": { m: "stark (trơ trọi, rõ mồn một) → tương phản rõ như trắng với đen.", e: "Sai: in a stark contrast → Đúng: in stark contrast. Sai: in stark contrast of → Đúng: in stark contrast to/with.", u: "IELTS Writing Task 1: 'In stark contrast, sales in Asia doubled'; nhấn mạnh sự trái ngược.", f: "in stark contrast, in contrast, by contrast, whereas (conj), conversely (adv)" },
  "the former": { m: "former (trước đó) → cái được nhắc trước trong hai thứ.", e: "Sai: the former is cars, the after is buses → Đúng: the former..., the latter... Chỉ dùng khi có hai đối tượng.", u: "IELTS Writing Task 1/2: 'Of cars and trains, the former is cheaper'; tránh lặp danh từ.", f: "the former, the latter, former (adj, cựu), formerly (adv)" },
  "the latter": { m: "latter ~ later (sau) → cái được nhắc sau trong hai thứ.", e: "Sai: the later → Đúng: the latter (khác nghĩa). Sai: the latter of three → chỉ dùng với hai.", u: "IELTS Writing Task 2: 'I agree with the latter view'; Task 1: đối chiếu hai nhóm.", f: "the latter, the former, latterly (adv), last-mentioned" },
  "followed by": { m: "follow (theo sau) → xếp hạng: đứng sau là cái gì.", e: "Sai: China was the highest, following by Japan → Đúng: followed by Japan (bị động rút gọn).", u: "IELTS Writing Task 1: 'Coal was the main source, followed by gas and nuclear'; quy trình: bước kế tiếp.", f: "followed by, then, next, subsequently (adv), preceded by" },
  "the process begins with": { m: "Câu mở quy trình: begin (bắt đầu) + with (bằng) bước đầu tiên.", e: "Sai: the process begins by the harvest → Đúng: begins with the harvesting of... Sai: process begin → begins.", u: "IELTS Writing Task 1 quy trình: 'The process begins with the collection of raw materials'.", f: "the process begins/starts with, commence (v), initial stage, first step" },
  "in the first stage": { m: "stage (giai đoạn) → bậc đầu tiên trong chuỗi bước.", e: "Sai: at first stage → Đúng: in/at the first stage. Sai: in the stage one → Đúng: in stage one.", u: "IELTS Writing Task 1 quy trình: 'In the first stage, leaves are picked'; tiếp theo: in the next stage, finally.", f: "in the first stage, initially (adv), at the outset, in the final stage" },
  "after which": { m: "after + which (thay cho cả mệnh đề trước) → nối hai bước, khỏi tách câu.", e: "Sai: after which they are dried, after that packed → bỏ lặp. Sai: after that which → Đúng: , after which...", u: "IELTS Writing Task 1 quy trình: 'Beans are roasted, after which they are ground' – điểm cộng ngữ pháp.", f: "after which, following which, whereupon, subsequently (adv)" },
  "is transported": { m: "trans (qua) + port (mang) → được chở từ nơi này qua nơi khác.", e: "Sai: the milk transported to → Đúng: the milk is transported to the factory. Thiếu 'is' là lỗi bị động.", u: "IELTS Writing Task 1 quy trình: 'The waste is transported by truck to a recycling plant'.", f: "transport (v/n), transportation (n), be delivered, be carried, be shipped" },
  "is filtered": { m: "filter (lưới lọc) → cho đi qua lưới để giữ lại cặn.", e: "Sai: water is filter → Đúng: water is filtered (V3). Sai: filtered by remove → Đúng: filtered to remove impurities.", u: "IELTS Writing Task 1 quy trình nước, bia: 'The water is then filtered to remove impurities'.", f: "filter (v/n), filtration (n), be purified, be strained" },
  "is packaged": { m: "package (gói hàng) → được cho vào bao bì trước khi bán.", e: "Sai: is packed and packaged → chọn một. Sai: is package → Đúng: is packaged.", u: "IELTS Writing Task 1 quy trình: 'Finally, the product is packaged and distributed'; TOEIC: packaging department.", f: "package (v/n), packaging (n), be packed, be wrapped, be bottled" },
  "end product": { m: "end (cuối) + product → thứ thu được ở cuối quy trình.", e: "Sai: the final end product → Đúng: the end product (tránh lặp). Sai: end-products of → Đúng: the end product of.", u: "IELTS Writing Task 1 quy trình: 'The end product is sold to supermarkets'; sản xuất, công nghiệp.", f: "end product, final product, finished product, by-product, output (n)" },
  "in a cyclical manner": { m: "cycle (vòng tròn) → các bước lặp lại như vòng tròn, không có điểm kết.", e: "Sai: in cycle manner → Đúng: in a cyclical manner. Sai: cyclic manner of → Đúng: occurs in a cyclical manner.", u: "IELTS Writing Task 1 vòng đời, chu trình nước: 'The process repeats in a cyclical manner'.", f: "cyclical (adj), cycle (n), cyclically (adv), repeatedly (adv)" },
  "is fed into": { m: "Hình ảnh: cho máy 'ăn' (feed) nguyên liệu vào miệng phễu.", e: "Sai: is feed into → Đúng: is fed into (V3 của feed). Sai: is fed to the machine → Đúng: into.", u: "IELTS Writing Task 1 quy trình: 'The pulp is fed into a large press'; ngành sản xuất.", f: "feed into, be loaded into, be placed in, be poured into" },
  "was replaced by": { m: "re (lại) + place (đặt) → đặt cái mới vào chỗ cái cũ.", e: "Sai: was replaced with by → chọn một. Sai: the park replaced by → Đúng: the park was replaced by a car park.", u: "IELTS Writing Task 1 bản đồ: 'The forest was replaced by housing'; chỉ thay đổi theo thời gian.", f: "replace (v), replacement (n), give way to, make way for, be substituted" },
  "was converted into": { m: "con + vert (xoay) → xoay chức năng, biến cái này thành cái khác.", e: "Sai: was converted to be a hotel → Đúng: was converted into a hotel. Không thêm 'be'.", u: "IELTS Writing Task 1 bản đồ: 'The warehouse was converted into flats'; xây dựng, bất động sản.", f: "convert (v), conversion (n), be turned into, be transformed into" },
  "was demolished": { m: "de (phá) + mol (khối lớn) → đập bỏ cả khối công trình.", e: "Sai: was demolish → Đúng: was demolished. Sai: the factory was destroyed (do thiên tai) → demolished (chủ ý).", u: "IELTS Writing Task 1 bản đồ: 'The old school was demolished to make way for a car park'.", f: "demolish (v), demolition (n), be knocked down, be torn down, be pulled down" },
  "make way for": { m: "Hình ảnh: tránh đường (make way) để cái khác đi qua → nhường chỗ.", e: "Sai: make a way for → Đúng: make way for. Sai: made way to → Đúng: made way for.", u: "IELTS Writing Task 1 bản đồ: 'Trees were cut down to make way for a road'.", f: "make way for, give way to, be replaced by, clear (v)" },
  "to the north of": { m: "Định hướng bản đồ: ở phía bắc, nằm ngoài vùng được nhắc.", e: "Sai: in the north of the park (nằm bên trong) ≠ to the north of the park (nằm bên ngoài).", u: "IELTS Writing Task 1 bản đồ: 'A hospital was built to the north of the river'; Listening Section 2.", f: "to the north/south/east/west of, in the north of, north of, northern (adj)" },
  "adjacent to": { m: "ad (kề) + jac (nằm) → nằm sát bên cạnh.", e: "Sai: adjacent with the park → Đúng: adjacent to the park. Sai: adjacent of → Đúng: adjacent to.", u: "IELTS Writing Task 1 bản đồ: 'A car park was built adjacent to the station'; bất động sản.", f: "adjacent to, next to, beside, alongside, neighbouring (adj)" },
  "overlooking": { m: "over (từ trên cao) + look → nhìn từ trên cao ra phía ngoài.", e: "Sai: overlooking to the sea → Đúng: overlooking the sea. Động từ 'overlook' còn nghĩa bỏ sót.", u: "IELTS Writing Task 1 bản đồ: 'a hotel overlooking the lake'; Speaking: mô tả căn phòng có tầm nhìn đẹp.", f: "overlook (v), overlooking (prep/adj), facing (prep), with a view of" },
  "pedestrianised": { m: "pedestrian (người đi bộ) + -ised → biến phố thành chỉ cho người đi bộ.", e: "Sai: was pedestrian → Đúng: was pedestrianised. Mỹ viết pedestrianized.", u: "IELTS Writing Task 1 bản đồ: 'The high street was pedestrianised'; Task 2: giải pháp giao thông đô thị.", f: "pedestrianise (v), pedestrian (n/adj), pedestrianisation (n), car-free (adj)" },
  "redeveloped": { m: "re (lại) + developed → khu vực được xây dựng, quy hoạch lại.", e: "Sai: the area was redevelop → Đúng: the area was redeveloped. Sai: re-developped → Đúng: redeveloped.", u: "IELTS Writing Task 1 bản đồ: 'The dock area was redeveloped into a leisure complex'; quy hoạch đô thị.", f: "redevelop (v), redevelopment (n), regenerate (v), renovate (v)" },
  "farmland": { m: "farm (trang trại) + land (đất) → đất dùng để trồng trọt, chăn nuôi.", e: "Sai: farmlands were converted → thường dùng không đếm được: farmland was converted. Sai: farm land → farmland.", u: "IELTS Writing Task 1 bản đồ: 'Farmland was replaced by a housing estate'; Task 2: đô thị hóa.", f: "farmland (n), agricultural land, arable land, countryside (n)" },
  "some people believe": { m: "Câu mở Task 2 dạng thảo luận: nêu quan điểm thứ nhất một cách khách quan.", e: "Sai: some people believes → Đúng: some people believe. Sai: some of people → Đúng: some people.", u: "IELTS Writing Task 2: 'Some people believe that university should be free'; nên paraphrase: It is argued by some.", f: "some people believe/argue/claim, it is believed that, proponents (n)" },
  "others argue": { m: "others (những người khác) → giới thiệu phe đối lập sau 'some people'.", e: "Sai: others argues → Đúng: others argue. Sai: other argue → Đúng: others argue (đại từ có -s).", u: "IELTS Writing Task 2 dạng Discuss both views: 'while others argue that it should be paid'.", f: "others argue/maintain/contend, opponents (n), critics (n), on the other hand" },
  "this essay will discuss": { m: "Câu cuối mở bài: báo trước bài sẽ bàn gì → định hướng người chấm.", e: "Sai: this essay will discuss about → Đúng: this essay will discuss both views. 'discuss' không đi với 'about'.", u: "IELTS Writing Task 2 mở bài: 'This essay will discuss both views before giving my opinion'.", f: "this essay will examine/argue/outline, discussion (n), I will argue that" },
  "both views": { m: "both (cả hai) + views (quan điểm) → xem xét cả hai phía.", e: "Sai: both view → Đúng: both views. Sai: the both views → Đúng: both views / both of these views.", u: "IELTS Writing Task 2: 'Discuss both views and give your opinion' – phải trình bày đủ hai bên.", f: "both views, both sides, either view, each perspective" },
  "on the one hand": { m: "Hình ảnh: một bên tay cầm lý lẽ này, tay kia cầm lý lẽ khác.", e: "Sai: on one hand... on another hand → Đúng: on the one hand... on the other hand.", u: "IELTS Writing Task 2: bắt đầu thân bài 1; Speaking Part 3: 'On the one hand, it saves time...'", f: "on the one hand, on the other hand, while (conj), whereas (conj)" },
  "the main reason": { m: "main (chính) + reason → lý do quan trọng nhất trong số nhiều lý do.", e: "Sai: the main reason is because → Đúng: the main reason is that... Sai: main reason of → Đúng: reason for.", u: "IELTS Writing Task 2 dạng nguyên nhân: 'The main reason for this trend is...'; Speaking Part 3.", f: "the main reason, the primary cause, the chief factor, a key reason" },
  "another factor": { m: "another (thêm một) + factor (yếu tố) → bổ sung nguyên nhân tiếp theo.", e: "Sai: another factors → Đúng: another factor / other factors. Sai: an another → Đúng: another.", u: "IELTS Writing Task 2: 'Another factor contributing to obesity is...'; nối ý thân bài mượt mà.", f: "another factor, a further factor, additionally (adv), moreover (adv)" },
  "lead to": { m: "Hình ảnh: con đường 'dẫn' (lead) bạn tới một kết quả → A lead to B = A gây ra B.", e: "Sai: lead to increase → Đúng: lead to an increase. Sai: leads people suffer → Đúng: leads to people suffering (to + danh từ/V-ing).", u: "Writing Task 2 đoạn nguyên nhân – hệ quả: 'Excessive screen time can lead to sleep problems.' Kết hợp: inevitably/ultimately lead to.", f: "lead (v) – led – led; leading (adj); result in, give rise to (đồng nghĩa)" },
  "result in": { m: "IN = đi VÀO kết quả: nguyên nhân result in hệ quả. Ngược lại 'result from' = bắt nguồn từ.", e: "Sai: Pollution results from health problems (đảo nghĩa) → Đúng: Pollution results in health problems.", u: "Writing Task 2: 'Deforestation results in the loss of habitats.' Dùng xen kẽ với lead to để tránh lặp từ.", f: "result (n/v), resultant (adj), result from (ngược chiều), as a result (of)" },
  "contribute to": { m: "con- (cùng) + tribute (góp) → cùng góp phần vào một kết quả, tốt hoặc xấu.", e: "Sai: contribute to solve → Đúng: contribute to solving. Sai: contribute for the problem → Đúng: contribute to the problem.", u: "Writing Task 2: 'Fast food contributes to obesity' – nhấn mạnh là một trong nhiều nguyên nhân. Kết hợp: significantly contribute to.", f: "contribution (n), contributor (n), contributory (adj), contributing factor (n)" },
  "bring about": { m: "Hình ảnh: 'mang (bring) tới quanh đây' một sự thay đổi → tạo ra, gây ra (thường là change).", e: "Sai: bring about to changes → Đúng: bring about changes. Không dùng với người: Sai: bring about my friend.", u: "Writing Task 2: 'Technology has brought about profound changes in education.' Rất hợp với change, reform, improvement.", f: "bring about (phr v); cause, trigger, give rise to (đồng nghĩa)" },
  "arise from": { m: "arise = trỗi dậy → vấn đề 'trỗi dậy từ' một nguồn gốc → nảy sinh từ.", e: "Sai: problems arise by poverty → Đúng: problems arise from poverty. Sai: arised → Đúng: arose, arisen.", u: "Writing Task 2: 'Many social issues arise from income inequality.' Trang trọng hơn 'come from'.", f: "arise – arose – arisen (v); stem from, originate from (đồng nghĩa)" },
  "a knock-on effect": { m: "Hình ảnh: quân domino gõ (knock) vào quân kế tiếp → tác động dây chuyền.", e: "Sai: a knock-on effect to the economy → Đúng: a knock-on effect on the economy. Nhớ giữ gạch nối knock-on.", u: "Writing Task 2: 'Rising fuel prices have a knock-on effect on food costs.' Cách nói Anh-Anh, ghi điểm Lexical Resource.", f: "knock-on (adj); domino effect, chain reaction, ripple effect (gần nghĩa)" },
  "a ripple effect": { m: "Hình ảnh: ném hòn đá xuống hồ, gợn sóng (ripple) lan dần ra xa.", e: "Sai: a ripple effect for society → Đúng: a ripple effect on/throughout society. Sai: ripples effect → Đúng: ripple effect.", u: "Writing Task 2: 'Job losses in one industry can create a ripple effect across the economy.' Hợp: create/have/cause a ripple effect.", f: "ripple (n/v); knock-on effect, domino effect (gần nghĩa)" },
  "root cause": { m: "Hình ảnh: rễ (root) cây nằm sâu dưới đất → nguyên nhân sâu xa nhất, không phải triệu chứng bề mặt.", e: "Sai: the root reason of → Đúng: the root cause of. Sai: root causes is → Đúng: root causes are.", u: "Writing Task 2 dạng Problem–Solution: 'Poverty is the root cause of crime.' Kết hợp: address/tackle the root cause.", f: "root (n/v), rooted in (adj); underlying cause (đồng nghĩa)" },
  "adverse effect": { m: "ad- (ngược) + verse (quay) → tác động quay ngược lại mình → bất lợi.", e: "Sai: adverse effect to health → Đúng: adverse effect on health. Đừng nhầm adverse (bất lợi) với averse (không thích).", u: "Writing Task 2: 'Air pollution has an adverse effect on public health.' Học thuật hơn 'bad effect'.", f: "adverse (adj), adversely (adv), adversity (n), adversary (n)" },
  "detrimental effect": { m: "detriment = thiệt hại; nghe như 'đè trĩu' → đè nặng gây hại.", e: "Sai: detrimental effect for children → Đúng: detrimental effect on children. Sai: detriment effect → Đúng: detrimental effect.", u: "Writing Task 2: 'Social media can have a detrimental effect on teenagers' self-esteem.' Kết hợp: seriously detrimental.", f: "detriment (n), detrimental (adj), detrimentally (adv); harmful (đồng nghĩa)" },
  "beneficial effect": { m: "bene- (tốt, như benefit) → tác động mang lại điều tốt.", e: "Sai: beneficial effect to the environment → Đúng: beneficial effect on the environment. Sai: benefit effect → Đúng: beneficial effect.", u: "Writing Task 2 đoạn ủng hộ: 'Regular exercise has a beneficial effect on mental health.' Đối lập với adverse effect.", f: "benefit (n/v), beneficial (adj), beneficiary (n); positive impact (đồng nghĩa)" },
  "in the long term": { m: "long term = kỳ hạn dài → nhìn xa vài năm, vài chục năm sau.", e: "Sai: in long term → Đúng: in the long term (nhớ 'the'). Sai: in a long-term → Đúng: long-term (adj) + danh từ.", u: "Writing Task 2: 'In the long term, investing in education boosts the economy.' Hay đi cặp với in the short term.", f: "long-term (adj), in the long run (đồng nghĩa), over time" },
  "in the short term": { m: "short term = kỳ hạn ngắn → hiệu quả trước mắt, vài tháng tới.", e: "Sai: in short term → Đúng: in the short term. Sai: a short term plan → Đúng: a short-term plan (gạch nối khi làm tính từ).", u: "Writing Task 2 so sánh: 'In the short term, the tax may be unpopular, but in the long term it pays off.'", f: "short-term (adj), in the short run, for the time being (gần nghĩa)" },
  "on a global scale": { m: "scale = thang đo, quy mô; global = cả quả địa cầu → nhìn ở tầm toàn thế giới.", e: "Sai: in a global scale → Đúng: on a global scale. Sai: on global scale → Đúng: on a global scale.", u: "Writing Task 2 chủ đề môi trường: 'Climate change must be tackled on a global scale.'", f: "global (adj), globally (adv), globalisation (n); worldwide (đồng nghĩa)" },
  "at a local level": { m: "level = tầng, cấp; local = địa phương → giải quyết ở cấp xã, thành phố.", e: "Sai: in local level → Đúng: at a local level / at the local level.", u: "Writing Task 2: 'Recycling schemes work best when organised at a local level.' Đối chiếu với at a national level.", f: "local (adj), locally (adv), locality (n); at national/international level" },
  "one possible solution": { m: "possible = có thể xảy ra → 'một' giải pháp khả thi, ngầm ý còn giải pháp khác.", e: "Sai: one possible solution is ban → Đúng: one possible solution is to ban / banning...", u: "Writing Task 2 dạng Problem–Solution, mở đoạn giải pháp: 'One possible solution is to introduce congestion charges.'", f: "solution (n), solve (v), solvable (adj); one viable option, one way to address" },
  "curb": { m: "curb = lề đường chắn xe → hình ảnh chặn lại, kìm hãm không cho lan rộng.", e: "Sai: curb the pollution increasing → Đúng: curb the increase in pollution. Sai: curb on spending (động từ) → Đúng: curb spending.", u: "Writing Task 2: 'Governments should curb plastic use.' Kết hợp: curb emissions/inflation/consumption.", f: "curb (v/n: a curb on), kerb (Anh-Anh: lề đường); restrict, rein in" },
  "combat": { m: "com- (cùng) + bat (đánh, như battle) → xông vào đánh nhau → chống lại.", e: "Sai: combat with crime → Đúng: combat crime (không giới từ). Trọng âm: COMbat (động từ cũng được /kəmˈbæt/).", u: "Writing Task 2: 'measures to combat climate change / obesity / fake news'. Mạnh và trang trọng hơn 'fight'.", f: "combat (v/n), combatant (n), combative (adj); tackle, fight (đồng nghĩa)" },
  "remedy": { m: "remedy gốc nghĩa 'thuốc chữa' → chữa lành một tình trạng xấu → khắc phục.", e: "Sai: remedy for the situation (dùng như động từ) → Đúng: remedy the situation. Danh từ mới đi với for: a remedy for.", u: "Writing Task 2: 'Steps must be taken to remedy the shortage of housing.' Kết hợp: remedy a problem/situation.", f: "remedy (v/n), remedial (adj), irremediable (adj); rectify (đồng nghĩa)" },
  "crack down on": { m: "Hình ảnh: đập (crack) mạnh xuống (down) lên (on) kẻ vi phạm → trấn áp quyết liệt.", e: "Sai: crack down drunk driving → Đúng: crack down on drunk driving (bắt buộc có on).", u: "Writing Task 2 chủ đề tội phạm: 'Police should crack down on speeding.' Danh từ: a crackdown on illegal logging.", f: "crackdown (n); clamp down on, take tough action against (đồng nghĩa)" },
  "impose a ban on": { m: "impose = đặt (pose) lên (im-) → đặt lệnh cấm lên một thứ gì đó.", e: "Sai: impose a ban to smoking → Đúng: impose a ban on smoking. Sai: put a ban for → Đúng: impose a ban on.", u: "Writing Task 2: 'The government should impose a ban on junk food advertising.' Biến thể: lift a ban (gỡ bỏ lệnh cấm).", f: "imposition (n); ban (v/n); outlaw, prohibit (đồng nghĩa)" },
  "raise taxes on": { m: "raise = nâng lên → nâng mức thuế đánh vào (on) một mặt hàng.", e: "Sai: rise taxes on → Đúng: raise taxes on (raise là ngoại động từ). Sai: raise taxes for cigarettes → Đúng: on cigarettes.", u: "Writing Task 2: 'Raising taxes on sugary drinks could reduce consumption.' Đối lập: cut taxes on.", f: "tax (n/v), taxation (n), taxable (adj); levy a tax on (đồng nghĩa)" },
  "subsidise": { m: "sub- (bên dưới) → nhà nước đỡ từ bên dưới một phần chi phí → trợ cấp.", e: "Sai: subsidise for farmers → Đúng: subsidise farmers. Anh-Anh: subsidise; Anh-Mỹ: subsidize – giữ một kiểu thống nhất.", u: "Writing Task 2: 'The state should subsidise public transport to cut traffic.' Kết hợp: heavily subsidised.", f: "subsidy (n), subsidised (adj), subsidisation (n); fund (gần nghĩa)" },
  "public awareness campaign": { m: "aware = biết, nhận thức → chiến dịch giúp công chúng 'biết' về vấn đề.", e: "Sai: a public aware campaign → Đúng: a public awareness campaign. Sai: make a campaign → Đúng: launch/run a campaign.", u: "Writing Task 2 giải pháp mềm: 'The government could launch public awareness campaigns about recycling.'", f: "aware (adj), awareness (n), raise awareness (of); campaign (n/v)" },
  "stricter regulations": { m: "strict = nghiêm; -er = hơn → luật lệ siết chặt hơn hiện tại.", e: "Sai: more stricter regulations → Đúng: stricter regulations. Sai: regulations about → Đúng: regulations on.", u: "Writing Task 2: 'Stricter regulations on factory emissions are needed.' Kết hợp: introduce/enforce stricter regulations.", f: "strict (adj), strictly (adv); regulate (v), regulation (n), regulatory (adj)" },
  "tougher penalties": { m: "tough = cứng rắn → hình phạt cứng rắn hơn để răn đe.", e: "Sai: more tough penalties → Đúng: tougher penalties. Sai: penalties to offenders → Đúng: penalties for offenders.", u: "Writing Task 2 chủ đề tội phạm/giao thông: 'Tougher penalties for drink-driving would act as a deterrent.'", f: "penalty (n), penalise (v), penal (adj); harsher punishments (đồng nghĩa)" },
  "it is imperative that": { m: "imperative = mệnh lệnh (câu mệnh lệnh = imperative sentence) → bắt buộc phải làm.", e: "Sai: It is imperative that the government takes → Đúng: ...that the government take (động từ nguyên mẫu, giả định).", u: "Writing Task 2 kết bài/đề xuất: 'It is imperative that action be taken now.' Mạnh hơn 'it is important that'.", f: "imperative (adj/n), imperatively (adv); it is essential that, it is crucial that" },
  "it is vital that": { m: "vital = thuộc sự sống (vitamin) → quan trọng sống còn.", e: "Sai: It is vital that everyone recycles (vẫn dùng được) — chuẩn học thuật hơn: that everyone recycle. Sai: It is vital to that → Đúng: It is vital that.", u: "Writing Task 2: 'It is vital that young people learn financial skills.' Thay cho 'very important' để đa dạng từ.", f: "vital (adj), vitally (adv), vitality (n); it is essential/crucial that" },
  "should be encouraged to": { m: "Bị động + to V: ai đó 'được khích lệ' để làm việc gì → đề xuất nhẹ nhàng.", e: "Sai: should be encouraged to using → Đúng: should be encouraged to use. Sai: should encourage to → Đúng: should be encouraged to.", u: "Writing Task 2 đề xuất: 'Students should be encouraged to volunteer.' Lịch sự hơn 'must'.", f: "encourage (v), encouragement (n), encouraging (adj); discourage (trái nghĩa)" },
  "a balanced approach": { m: "Hình ảnh: cán cân thăng bằng (balance) → không nghiêng hẳn về bên nào.", e: "Sai: a balance approach → Đúng: a balanced approach. Sai: approach to solve → Đúng: approach to solving.", u: "Writing Task 2 dạng Discuss both views: 'A balanced approach combining regulation and education is best.'", f: "balance (n/v), balanced (adj), imbalance (n); middle ground, compromise (gần nghĩa)" },
  "the onus is on": { m: "onus (Latin) = gánh nặng → gánh trách nhiệm đặt lên vai ai.", e: "Sai: the onus is for parents → Đúng: the onus is on parents (to do something).", u: "Writing Task 2 dạng Who is responsible: 'The onus is on manufacturers to reduce packaging.' Rất trang trọng.", f: "onus (n); the responsibility lies with, it is up to (đồng nghĩa)" },
  "a step in the right direction": { m: "Hình ảnh: bước một bước đúng hướng → chưa tới đích nhưng tiến triển tốt.", e: "Sai: a step to the right direction → Đúng: a step in the right direction.", u: "Writing Task 2 đánh giá chính sách: 'The plastic bag tax is a step in the right direction, but more is needed.'", f: "a move in the right direction; progress (n); a positive first step" },
  "take, for instance,": { m: "'Lấy (take) làm ví dụ' → đưa một trường hợp cụ thể ra soi.", e: "Sai: Take for instance Japan (thiếu dấu phẩy) → Đúng: Take, for instance, Japan. Không viết Take for example that...", u: "Writing Task 2 đoạn thân bài, giới thiệu dẫn chứng: 'Take, for instance, Singapore, where public transport is efficient.'", f: "for instance, for example, such as, a case in point is" },
  "this is because": { m: "this = điều vừa nói; because = vì → nối câu nhận định với câu giải thích.", e: "Sai: This is because of people are busy → Đúng: This is because people are busy (because + mệnh đề).", u: "Writing Task 2: câu thứ hai trong đoạn để giải thích luận điểm. Tránh lặp quá nhiều; xen kẽ 'The reason is that'.", f: "because (conj), because of (prep); the reason for this is that" },
  "this means that": { m: "mean = có nghĩa → 'điều này có nghĩa là' nối nguyên nhân với hệ quả.", e: "Sai: This is mean that → Đúng: This means that. Sai: It's mean → Đúng: It means.", u: "Writing Task 2: phát triển ý, đưa hệ quả: 'Fewer people cycle. This means that pollution rises.'", f: "mean (v), meaning (n); as a result, consequently, therefore" },
  "it is often argued that": { m: "argue = lập luận; often = thường → nêu quan điểm của số đông, chưa phải ý mình.", e: "Sai: It is often argued about that → Đúng: It is often argued that. Sai: It often argues that → Đúng: It is often argued that.", u: "Writing Task 2 mở bài hoặc nêu quan điểm đối lập: 'It is often argued that zoos are cruel.'", f: "argue (v), argument (n), arguably (adv); some people claim that" },
  "outweigh": { m: "out (vượt) + weigh (cân nặng) → đặt lên cân, bên này nặng hơn bên kia.", e: "Sai: The benefits outweigh than the drawbacks → Đúng: The benefits outweigh the drawbacks (không 'than').", u: "Writing Task 2 dạng Advantages outweigh disadvantages: 'I believe the advantages far outweigh the disadvantages.'", f: "outweigh (v); weigh (v), weight (n); override, exceed (gần nghĩa)" },
  "counterargument": { m: "counter- (ngược lại) + argument (lập luận) → lập luận đối lập.", e: "Sai: counter argument (tách rời) → Đúng: counterargument hoặc counter-argument. Sai: give a counterargument with → Đúng: against.", u: "Writing Task 2: nêu counterargument rồi phản bác (refute) để thể hiện tư duy phản biện.", f: "counter (v/prep), argue (v), argument (n), rebuttal (n, gần nghĩa)" },
  "in summary": { m: "summary = bản tóm tắt → 'trong bản tóm tắt' = tóm lại.", e: "Sai: In summarize → Đúng: In summary. Sai: In sum up → Đúng: To sum up.", u: "Writing Task 2 mở đoạn kết luận. Tránh dùng 'In conclusion' lẫn 'In summary' cùng lúc.", f: "summary (n), summarise (v); to sum up, in conclusion, overall" },
  "to conclude": { m: "con- + clude (đóng lại, như close) → khép bài viết lại.", e: "Sai: To conclusion → Đúng: To conclude / In conclusion. Không đặt cuối câu: To conclude, ...", u: "Writing Task 2 đầu đoạn kết: 'To conclude, both sides have merit, but...' Nhắc lại quan điểm chính.", f: "conclude (v), conclusion (n), conclusive (adj), in conclusion" },
  "for the reasons outlined above": { m: "outline = phác họa đường nét → những lý do đã phác ra ở trên.", e: "Sai: for the reasons outline above → Đúng: for the reasons outlined above (quá khứ phân từ).", u: "Writing Task 2 đoạn kết: 'For the reasons outlined above, I firmly believe that...' Liên kết thân bài với kết luận.", f: "outline (v/n); for the reasons mentioned above, given these points" },
  "wholeheartedly agree": { m: "whole + heart → đồng ý bằng cả trái tim → hoàn toàn đồng tình.", e: "Sai: I wholeheartedly agree this opinion → Đúng: I wholeheartedly agree with this opinion.", u: "Writing Task 2 dạng Agree/Disagree, nêu quan điểm rõ ở mở bài: 'I wholeheartedly agree with this statement.'", f: "wholehearted (adj), wholeheartedly (adv); fully/completely agree" },
  "in today's society": { m: "today's = của ngày nay → bối cảnh xã hội hiện đại.", e: "Sai: in nowadays society → Đúng: in today's society / in modern society. Đừng dùng 'nowadays' như tính từ.", u: "Writing Task 2 mở bài, nhưng tránh lạm dụng vì giám khảo coi là sáo rỗng; nên kèm ý cụ thể.", f: "contemporary society, modern society, nowadays (adv)" },
  "a growing number of": { m: "growing = đang lớn lên → số lượng cứ tăng dần.", e: "Sai: A growing number of people is → Đúng: A growing number of people are (động từ số nhiều).", u: "Writing Task 2 mở bài nêu xu hướng: 'A growing number of employees work from home.' Thay cho 'more and more'.", f: "growing (adj), grow (v), growth (n); an increasing number of" },
  "play a crucial role in": { m: "Hình ảnh: diễn viên đóng (play) vai (role) then chốt (crucial) trong vở kịch.", e: "Sai: play a crucial role on → Đúng: play a crucial role in. Sai: play an crucial → Đúng: a crucial.", u: "Writing Task 2: 'Teachers play a crucial role in shaping children's values.' Biến thể: pivotal/key/vital role.", f: "crucial (adj), crucially (adv); play a key/pivotal/vital role in" },
  "have a vested interest in": { m: "vested = đã được trao quyền, gắn chặt → có quyền lợi gắn chặt nên thiên vị.", e: "Sai: have a vested interest to → Đúng: have a vested interest in (+ N/V-ing).", u: "Writing Task 2: 'Oil companies have a vested interest in delaying green policies.' Hàm ý thiếu khách quan.", f: "vested interest (n); stake (n): have a stake in (gần nghĩa)" },
  "go hand in hand": { m: "Hình ảnh: hai người nắm tay nhau đi → hai thứ luôn đi kèm.", e: "Sai: go hand by hand → Đúng: go hand in hand (with). Sai: goes hand in hands → Đúng: hand in hand.", u: "Writing Task 2: 'Economic growth often goes hand in hand with pollution.'", f: "hand in hand (adv); be closely linked, go together" },
  "at the expense of": { m: "expense = chi phí → điều tốt có được phải 'trả giá' bằng thứ khác.", e: "Sai: at the expense for the environment → Đúng: at the expense of the environment.", u: "Writing Task 2: 'Economic development should not come at the expense of the environment.'", f: "expense (n), expensive (adj), expend (v); at the cost of (đồng nghĩa)" },
  "with the advent of": { m: "advent = sự đến (adventure cùng gốc 'đến') → khi thứ mới xuất hiện.", e: "Sai: with the advent the internet → Đúng: with the advent of the internet.", u: "Writing Task 2 mở bài chủ đề công nghệ: 'With the advent of AI, many jobs are changing.'", f: "advent (n); with the emergence/rise of, since the introduction of" },
  "be held accountable": { m: "account = giải trình → bị 'giữ lại' để giải trình hành vi → phải chịu trách nhiệm.", e: "Sai: be held accountable of → Đúng: be held accountable for their actions.", u: "Writing Task 2: 'Companies that pollute should be held accountable.' Trang trọng, hợp chủ đề luật pháp, chính phủ.", f: "accountable (adj), accountability (n); be held responsible (đồng nghĩa)" },
  "raise living standards": { m: "raise = nâng lên; standard of living = mức sống → nâng mức sống.", e: "Sai: rise living standards → Đúng: raise living standards. Sai: living standard of people raise → Đúng: living standards rise.", u: "Writing Task 2 chủ đề kinh tế, toàn cầu hóa: 'Tourism can raise living standards in rural areas.'", f: "standard of living (n), living standards (n); improve quality of life" },
  "a drain on resources": { m: "drain = ống thoát nước → tiền và nguồn lực cứ chảy mất đi.", e: "Sai: a drain of resources → Đúng: a drain on resources. Sai: a drain to the budget → Đúng: a drain on the budget.", u: "Writing Task 2: 'An ageing population can be a drain on healthcare resources.'", f: "drain (v/n), drainage (n); a burden on (gần nghĩa)" },
  "the pros and cons": { m: "pro (ủng hộ, cộng) và con (chống, trừ) → mặt cộng và mặt trừ.", e: "Sai: the pro and con of → Đúng: the pros and cons of (số nhiều). Văn học thuật nên dùng advantages and disadvantages.", u: "Writing Task 2: dùng ở mở bài nhẹ; Speaking: 'There are pros and cons to living abroad.'", f: "advantages and disadvantages, merits and drawbacks, upsides and downsides" },
  "weigh up": { m: "Hình ảnh: đặt hai lựa chọn lên cân (weigh) để so sánh trước khi quyết định.", e: "Sai: weigh up about the options → Đúng: weigh up the options. Sai: weight up → Đúng: weigh up.", u: "Writing Task 2: 'Governments must weigh up the costs and benefits.' Speaking: 'I weighed up my options.'", f: "weigh (v), weight (n); consider, assess (đồng nghĩa)" },
  "to be honest": { m: "honest = thật thà → mở lời 'nói thật nhé' trước khi nêu ý thật lòng.", e: "Sai: To honest, I don't like it → Đúng: To be honest, I don't like it. Sai: Honestly to say → Đúng: Honestly.", u: "Speaking Part 1–3: mở câu trả lời tự nhiên, nhất là khi trả lời ngược kỳ vọng. Đừng lặp ở mọi câu.", f: "honest (adj), honestly (adv), honesty (n); to tell you the truth, frankly" },
  "i'd say": { m: "I'd = I would → 'tôi sẽ nói là' → đưa ra ước đoán, nhận xét mềm mỏng.", e: "Sai: I'd say that is about 20 people come → Đúng: I'd say about 20 people came.", u: "Speaking Part 1–3: dùng khi ước lượng hoặc đánh giá: 'I'd say I'm more of a night owl.'", f: "I would say; I guess, I reckon, I'd imagine (gần nghĩa)" },
  "i reckon": { m: "reckon gốc là 'tính toán' → tính nhẩm trong đầu ra một nhận định → tôi nghĩ.", e: "Sai: I reckon about it → Đúng: I reckon (that) it'll rain. Không dùng trong Writing học thuật.", u: "Speaking: cách nói Anh-Anh thân mật, giúp nghe tự nhiên: 'I reckon most young people prefer online shopping.'", f: "reckon (v), reckoning (n); I think, I guess, I'd say" },
  "i suppose": { m: "suppose = giả định → 'chắc là vậy', nói khi chưa thật chắc chắn.", e: "Sai: I suppose to go → Đúng: I'm supposed to go (= phải đi) khác với I suppose so (= chắc vậy).", u: "Speaking Part 3: thể hiện sự cân nhắc: 'I suppose technology has made us lazier in some ways.'", f: "suppose (v), supposedly (adv), supposition (n); I guess, I assume" },
  "it depends": { m: "depend = phụ thuộc → 'còn phụ thuộc' vào hoàn cảnh nữa.", e: "Sai: It depends of the weather → Đúng: It depends on the weather. Sai: It's depend → Đúng: It depends.", u: "Speaking Part 1–3: mở câu rồi phân tích hai trường hợp; đừng dừng lại chỉ với 'It depends.'", f: "depend (v), dependent (adj), dependence (n); it varies, that depends on" },
  "that's a tricky question": { m: "tricky = có mẹo, dễ mắc bẫy → câu hỏi hóc búa, cần suy nghĩ.", e: "Sai: That's a trick question (nghĩa khác: câu hỏi gài bẫy) → Đúng: That's a tricky question.", u: "Speaking Part 3: câu câu giờ lịch sự khi gặp câu hỏi trừu tượng, rồi trả lời ngay.", f: "tricky (adj), trick (n/v); that's a difficult/tough question" },
  "i've never really thought about it": { m: "Hiện tại hoàn thành + never → từ trước tới giờ chưa từng nghĩ tới.", e: "Sai: I never really think about it before → Đúng: I've never really thought about it before.", u: "Speaking Part 1–3: câu nối thật thà khi bị hỏi bất ngờ, sau đó vẫn phải đưa ý: '...but I guess...'", f: "think – thought – thought (v); it's never crossed my mind" },
  "off the top of my head": { m: "Hình ảnh: ý nghĩ lấy ngay trên đỉnh đầu, chưa cần đào sâu → nghĩ ra liền.", e: "Sai: on the top of my head → Đúng: off the top of my head.", u: "Speaking Part 2–3: khi liệt kê ví dụ nhanh: 'Off the top of my head, I can think of two reasons.'", f: "offhand (adv); without thinking/checking, right now" },
  "if i remember correctly": { m: "correctly = chính xác → 'nếu trí nhớ không lừa tôi'.", e: "Sai: If I remember correct → Đúng: If I remember correctly (trạng từ). Cũng nói: If I remember rightly.", u: "Speaking Part 2: kể chuyện quá khứ: 'If I remember correctly, it was in 2019.' Giúp nói lưu loát.", f: "remember (v), memory (n); if my memory serves me (right), as I recall" },
  "as far as i know": { m: "Hình ảnh: hiểu biết của tôi chỉ xa (far) tới đó thôi → theo những gì tôi biết.", e: "Sai: As long as I know → Đúng: As far as I know. Sai: As far as I'm know → Đúng: As far as I know.", u: "Speaking Part 3: rào đón khi nói về thông tin không chắc: 'As far as I know, the city plans a metro.'", f: "to my knowledge, as far as I'm aware, as far as I can tell" },
  "it's hard to say": { m: "hard = khó; say = nói → khó mà khẳng định chắc chắn.", e: "Sai: It's hard for say → Đúng: It's hard to say. Sai: It's hard to say about → Đúng: It's hard to say whether/what...", u: "Speaking Part 3, câu hỏi dự đoán tương lai: 'It's hard to say, but I imagine robots will...'", f: "it's difficult to tell, who knows, it's anyone's guess" },
  "the thing is": { m: "'Cái chuyện là...' → dẫn vào điểm mấu chốt hoặc vấn đề thật sự.", e: "Sai: The thing is that is I'm busy → Đúng: The thing is, I'm busy / The thing is that I'm busy.", u: "Speaking: dùng khi giải thích lý do hoặc khó khăn: 'The thing is, public transport here is unreliable.'", f: "the problem is, the point is, the fact is" },
  "what i mean is": { m: "mean = có ý nói → làm rõ lại điều mình vừa nói chưa rõ.", e: "Sai: What I mean is that is → Đúng: What I mean is (that)... Sai: I mean is → Đúng: What I mean is.", u: "Speaking Part 3: tự sửa, diễn đạt lại (paraphrase) giúp tăng điểm Fluency & Coherence.", f: "mean (v), meaning (n); in other words, what I'm trying to say is" },
  "to put it simply": { m: "put = đặt; simply = đơn giản → đặt ý vào lời đơn giản nhất.", e: "Sai: To put it simple → Đúng: To put it simply (trạng từ). Sai: Put simply it → Đúng: Put simply,...", u: "Speaking Part 3: tóm gọn sau khi giải thích dài; Writing cũng dùng được: 'Put simply, ...'", f: "simple (adj), simply (adv), simplify (v); in simple terms, basically" },
  "in a nutshell": { m: "Hình ảnh: nhét cả câu chuyện vừa vào một vỏ hạt dẻ (nutshell) → cực kỳ ngắn gọn.", e: "Sai: in nutshell → Đúng: in a nutshell (có 'a'). Sai: in a nut shell → Đúng: nutshell (viết liền).", u: "Speaking Part 2–3: kết câu trả lời: 'In a nutshell, it was the best trip of my life.' Không dùng trong Writing.", f: "to sum up, basically, in short, in brief" },
  "generally speaking": { m: "general = chung → nói theo cái nhìn chung, chấp nhận có ngoại lệ.", e: "Sai: General speaking → Đúng: Generally speaking (trạng từ + V-ing).", u: "Speaking Part 3: mở câu khái quát về xã hội: 'Generally speaking, older people prefer cash.'", f: "general (adj), generally (adv), generalise (v); in general, on the whole" },
  "broadly speaking": { m: "broad = rộng → nhìn rộng ra, bỏ qua chi tiết nhỏ.", e: "Sai: Broad speaking → Đúng: Broadly speaking. Sai: Broadly speaking about → Đúng: Broadly speaking, ...", u: "Speaking Part 3 và Writing Task 1/2: 'Broadly speaking, the trend was upward.'", f: "broad (adj), broadly (adv), broaden (v); generally speaking, by and large" },
  "it goes without saying": { m: "Hình ảnh: điều tự 'đi' mà không cần 'nói' → ai cũng biết rồi.", e: "Sai: It goes without say → Đúng: It goes without saying that... (without + V-ing).", u: "Speaking Part 3: 'It goes without saying that health is more important than wealth.' Dùng tiết chế.", f: "needless to say, obviously, of course" },
  "kind of": { m: "kind = loại → 'thuộc loại như' → hơi hơi, kiểu như; giúp câu mềm hơn.", e: "Sai: I'm kind of tired person → Đúng: I'm kind of tired / I'm that kind of person. Đừng viết 'kinda' trong Writing.", u: "Speaking Part 1: 'It's kind of boring, to be honest.' Dùng vừa phải, lạm dụng sẽ nghe thiếu chắc chắn.", f: "sort of, a bit, somewhat, rather (gần nghĩa)" },
  "pretty much": { m: "pretty ở đây = khá (không phải xinh) → 'khá là hoàn toàn' → gần như.", e: "Sai: pretty much people → Đúng: pretty much everyone. Sai: It's pretty much same → Đúng: It's pretty much the same.", u: "Speaking Part 1: 'I go there pretty much every weekend.' Thân mật, tránh trong Writing.", f: "almost, nearly, more or less, virtually" },
  "a bit of a": { m: "bit = mẩu nhỏ → 'một chút là một...' → làm nhẹ danh từ phía sau.", e: "Sai: a bit of a expensive → Đúng: a bit expensive (tính từ) hoặc a bit of a problem (danh từ).", u: "Speaking Part 1–2: 'I'm a bit of a perfectionist.' Mô tả bản thân khiêm tốn, tự nhiên.", f: "something of a, rather a; a bit (+ adj)" },
  "these days": { m: "these = những... này → những ngày gần đây → dạo này, ngày nay.", e: "Sai: In these days, I am study → Đúng: These days, I'm studying a lot. Không cần 'in'.", u: "Speaking Part 1: 'These days, I'm mostly working from home.' Thường đi với thì hiện tại đơn/tiếp diễn.", f: "nowadays, currently, at the moment, lately" },
  "back in the day": { m: "Hình ảnh: quay ngược (back) về những ngày xưa ấy → hồi trước.", e: "Sai: back to the day → Đúng: back in the day. Đi với thì quá khứ: Back in the day, we played outside.", u: "Speaking Part 2–3 so sánh xưa – nay: 'Back in the day, people wrote letters.'", f: "in the old days, in the past, years ago, once upon a time" },
  "when i was a kid": { m: "kid = đứa trẻ → mốc thời gian tuổi thơ để kể chuyện.", e: "Sai: When I was kid → Đúng: When I was a kid. Sai: When I am a kid → Đúng: was.", u: "Speaking Part 1–2: 'When I was a kid, I used to collect stickers.' Kết hợp used to để ghi điểm ngữ pháp.", f: "when I was little/young, as a child, in my childhood" },
  "growing up": { m: "grow up = lớn lên → 'trong lúc đang lớn' → suốt thời thơ ấu.", e: "Sai: When growing up, I am living → Đúng: Growing up, I lived in Hue. Sai: Grew up, I... → Đúng: Growing up, I...", u: "Speaking Part 1–2: 'Growing up, I spent summers at my grandparents'.' Mở câu kể chuyện tự nhiên.", f: "grow up (phr v), grown-up (n/adj), upbringing (n)" },
  "for ages": { m: "age = thời đại → chờ cả 'mấy thời đại' → nói quá: rất lâu.", e: "Sai: I didn't see him for ages → Đúng: I haven't seen him for ages (hiện tại hoàn thành).", u: "Speaking Part 1: 'I haven't been to the cinema for ages.' Thân mật, tự nhiên hơn 'for a long time'.", f: "for a long time, for yonks (Anh-Anh, lóng), in ages" },
  "every now and then": { m: "now and then = lúc này lúc kia → thỉnh thoảng, không đều đặn.", e: "Sai: every now and there → Đúng: every now and then. Sai: every now then → Đúng: every now and then.", u: "Speaking Part 1 câu hỏi tần suất: 'I go hiking every now and then.' Thay cho 'sometimes'.", f: "now and again, from time to time, occasionally, once in a while" },
  "from time to time": { m: "Từ lúc này đến lúc khác (time to time) → lâu lâu một lần.", e: "Sai: from times to times → Đúng: from time to time (số ít).", u: "Speaking Part 1: 'I cook Vietnamese food from time to time.' Đặt đầu hoặc cuối câu đều được.", f: "occasionally (adv), every now and then, now and again" },
  "on a daily basis": { m: "basis = nền tảng → lấy 'mỗi ngày' làm nền → diễn ra hằng ngày.", e: "Sai: in a daily basis → Đúng: on a daily basis. Sai: on daily basis → Đúng: on a daily basis.", u: "Speaking Part 1 và Writing: 'I use English on a daily basis at work.' Biến thể: on a regular/weekly basis.", f: "daily (adj/adv), every day; on a regular basis" },
  "bring back memories": { m: "Hình ảnh: một bài hát 'mang trở lại' (bring back) ký ức cũ về trong đầu.", e: "Sai: bring back memory of → Đúng: bring back memories of. Sai: It brings me back memories → Đúng: It brings back memories.", u: "Speaking Part 2 chủ đề bài hát, đồ vật, nơi chốn: 'This song brings back memories of my school days.'", f: "memory (n), memorable (adj), memorise (v); evoke memories" },
  "vivid memory": { m: "vivid = sống động, rực màu → ký ức rõ nét như vừa xảy ra.", e: "Sai: a vivid memory about → Đúng: a vivid memory of. Sai: I have vivid memory → Đúng: I have a vivid memory.", u: "Speaking Part 2: 'I have a vivid memory of my first day at school.' Từ vựng ăn điểm Lexical Resource.", f: "vivid (adj), vividly (adv): vividly remember; clear/distinct memory" },
  "it reminds me of": { m: "re- (lại) + mind (tâm trí) → đưa lại vào tâm trí → gợi nhớ.", e: "Sai: It reminds me about my childhood → Đúng: It reminds me of my childhood. Sai: It remembers me → Đúng: It reminds me.", u: "Speaking Part 2: 'The smell of rain reminds me of my hometown.'", f: "remind (v), reminder (n); remind sb to do (nhắc làm gì)" },
  "the other day": { m: "'ngày kia' trong tiếng Anh = một ngày gần đây đã qua, không phải tương lai.", e: "Sai: I'll see you the other day (tưởng là ngày kia) → Đúng: I saw him the other day.", u: "Speaking Part 2: mở đầu kể chuyện gần đây: 'The other day, I tried a new café.'", f: "recently, a few days ago, not long ago" },
  "hometown": { m: "home + town → thị trấn/thành phố nơi mình lớn lên, gắn với 'nhà'.", e: "Sai: My hometown is in Hanoi city → Đúng: My hometown is Hanoi. Sai: home town of me → Đúng: my hometown.", u: "Speaking Part 1 chủ đề kinh điển: 'Where is your hometown?' Trả lời kèm đặc điểm nổi bật.", f: "home (n), town (n); place of birth, native town" },
  "born and raised": { m: "born = sinh ra; raised = được nuôi lớn → cả đời gắn bó một nơi.", e: "Sai: I born and raise in Hue → Đúng: I was born and raised in Hue (bị động, có 'was').", u: "Speaking Part 1 hometown: 'I was born and raised in Da Nang, a coastal city.'", f: "bear – bore – born (v), raise (v), upbringing (n); born and bred" },
  "close-knit": { m: "knit = đan len → các thành viên đan sát vào nhau → gắn bó khăng khít.", e: "Sai: a close-knitted family → Đúng: a close-knit family. Sai: close knit (thiếu gạch nối trước danh từ).", u: "Speaking Part 1–2 gia đình, hàng xóm: 'I come from a close-knit family.' Hợp: community, neighbourhood.", f: "knit (v); tight-knit (đồng nghĩa); close (adj): be close to" },
  "bustling city": { m: "bustle = hối hả tất bật → thành phố người qua lại nhộn nhịp không ngừng.", e: "Sai: a bustle city → Đúng: a bustling city. Sai: bustling with people city → Đúng: a city bustling with people.", u: "Speaking Part 1–2 mô tả nơi ở: 'Ho Chi Minh City is a bustling city that never sleeps.'", f: "bustle (n/v), bustling (adj); vibrant, lively city" },
  "sleepy town": { m: "Thị trấn như đang 'ngủ' → yên tĩnh, ít hoạt động.", e: "Sai: a sleeping town → Đúng: a sleepy town. Sai: a sleepy small town (trật tự hơi gượng) → Đúng: a small, sleepy town.", u: "Speaking Part 1 hometown: 'I grew up in a sleepy town where nothing much happens.'", f: "sleepy (adj), sleep (v/n); quiet, laid-back town" },
  "leafy": { m: "leaf = lá → nhiều lá cây → khu phố rợp bóng cây xanh.", e: "Sai: a leafed street → Đúng: a leafy street. Sai: leafy of trees → Đúng: leafy / full of trees.", u: "Speaking Part 1 mô tả nơi ở: 'I live in a leafy suburb.' Hợp: leafy street, suburb, area.", f: "leaf (n, số nhiều leaves), leafless (adj); green, tree-lined" },
  "well-connected": { m: "connected = được kết nối tốt → đi đâu cũng tiện xe buýt, metro.", e: "Sai: My area is well connect → Đúng: My area is well-connected. Lưu ý còn nghĩa 'có quan hệ rộng'.", u: "Speaking Part 1 nơi ở: 'My neighbourhood is well-connected to the city centre by metro.'", f: "connect (v), connection (n); conveniently located, accessible" },
  "cost of living": { m: "Chi phí (cost) để sống (living) → tiền nhà, ăn, đi lại hằng tháng.", e: "Sai: living cost is high → Đúng: the cost of living is high. Sai: high costs of living → Đúng: a high cost of living.", u: "Speaking Part 1–3, Writing chủ đề đô thị hóa: 'The cost of living in big cities keeps rising.'", f: "living costs, living expenses (n); cost-of-living crisis" },
  "work-life balance": { m: "Cân (balance) giữa công việc (work) và đời sống (life) → không bên nào lấn át.", e: "Sai: balance of work and life is → Đúng: work-life balance is. Sai: have a good work life balance (thiếu gạch nối).", u: "Speaking Part 1 work và Writing Task 2: 'Remote work can improve work-life balance.'", f: "balance (n/v), balanced (adj); maintain/strike a work-life balance" },
  "nine-to-five": { m: "Từ 9 giờ sáng đến 5 giờ chiều → công việc giờ hành chính, ổn định.", e: "Sai: a 9 to 5 job (viết số tạm được) → chuẩn: a nine-to-five job. Sai: work nine-to-five's → Đúng: work nine to five.", u: "Speaking Part 1 work: 'I'd hate a nine-to-five job; I prefer flexible hours.'", f: "nine-to-fiver (n, người làm giờ hành chính); office job, regular hours" },
  "hands-on": { m: "Hình ảnh: đặt tay (hands) lên (on) làm thật → thực hành trực tiếp.", e: "Sai: hand-on experience → Đúng: hands-on experience (hands số nhiều).", u: "Speaking Part 1 study/work: 'I prefer hands-on learning to lectures.' Hợp: hands-on experience/approach.", f: "practical (adj), hands-off (trái nghĩa)" },
  "make a living": { m: "make = làm ra; living = sự sống → làm ra tiền để sống.", e: "Sai: make a live → Đúng: make a living. Sai: make a living by sell → Đúng: make a living by selling / as a teacher.", u: "Speaking Part 1 work: 'My parents make a living as farmers.'", f: "earn a living, earn one's keep; livelihood (n)" },
  "career path": { m: "path = lối đi → con đường nghề nghiệp mình chọn bước theo.", e: "Sai: choose a career road → Đúng: choose a career path. Sai: carrier path → Đúng: career path.", u: "Speaking Part 1–3 và Writing chủ đề giáo dục: 'Many graduates change their career path.'", f: "career (n), careerist (n); career ladder, career choice" },
  "major in": { m: "major = chính → môn học chính của bạn ở đại học.", e: "Sai: I major English → Đúng: I major in English. Sai: My major is in English → Đúng: My major is English.", u: "Speaking Part 1 study: 'I'm majoring in economics at university.' (Anh-Mỹ; Anh-Anh: I'm studying...)", f: "major (n/v), minor in (phụ); specialise in (gần nghĩa)" },
  "day job": { m: "Công việc ban ngày nuôi sống, khác với đam mê làm buổi tối.", e: "Sai: My day job is a painter (đam mê) → Đúng: My day job is accounting, but I paint at night.", u: "Speaking Part 1 work: 'Don't quit your day job' (đùa: đừng bỏ nghề chính). Hữu ích khi nói về side hustle.", f: "main job, full-time job; side hustle, side job (nghề tay trái)" },
  "in my spare time": { m: "spare = dư ra → thời gian dư ra sau học, làm → lúc rảnh.", e: "Sai: in my free times → Đúng: in my free/spare time (không số nhiều). Sai: on my spare time → Đúng: in.", u: "Speaking Part 1 hobbies: 'In my spare time, I like reading thrillers.'", f: "spare time, free time, leisure time, downtime" },
  "unwind": { m: "un- (gỡ) + wind (cuộn) → gỡ dây cót đang căng → thả lỏng.", e: "Sai: unwind myself → Đúng: unwind (nội động từ). Phát âm /ʌnˈwaɪnd/, không đọc như 'wind' (gió).", u: "Speaking Part 1 leisure: 'I usually unwind by listening to music after work.'", f: "unwind – unwound (v); relax, chill out, wind down (gần nghĩa)" },
  "recharge my batteries": { m: "Hình ảnh: cơ thể như điện thoại hết pin → cắm sạc lại năng lượng.", e: "Sai: recharge my battery energy → Đúng: recharge my batteries (số nhiều). Sai: charge again my batteries.", u: "Speaking Part 1–2 holidays: 'A weekend in the countryside helps me recharge my batteries.'", f: "recharge (v), rechargeable (adj); get my energy back, rest up" },
  "binge-watch": { m: "binge = ăn/uống quá đà → xem phim quá đà, cả chục tập một lèo.", e: "Sai: binge-watch to a series → Đúng: binge-watch a series. Quá khứ: binge-watched.", u: "Speaking Part 1 TV/films: 'I binge-watched a Korean drama last weekend.'", f: "binge (n/v), binge-watching (n), binge-eat (v)" },
  "lie-in": { m: "lie (nằm) + in (trong chăn) → nằm lì trên giường → ngủ nướng.", e: "Sai: I had a lay-in → Đúng: I had a lie-in. Sai: do a lie-in → Đúng: have a lie-in.", u: "Speaking Part 1 weekend/sleep: 'On Sundays, I love having a lie-in.' Cách nói Anh-Anh.", f: "lie in (phr v); sleep in (Anh-Mỹ, đồng nghĩa)" },
  "homebody": { m: "home + body (người) → người chỉ muốn ở nhà.", e: "Sai: I'm a home person body → Đúng: I'm a homebody. Không nhầm với 'nobody' hay 'housewife'.", u: "Speaking Part 1 personality, weekends: 'I'm a bit of a homebody, so I rarely go clubbing.'", f: "homebody (n); stay-at-home type, introvert (gần nghĩa)" },
  "outdoorsy": { m: "outdoors (ngoài trời) + -y (thích) → người mê leo núi, cắm trại.", e: "Sai: I'm an outdoor person (tạm được) → tự nhiên hơn: I'm quite outdoorsy. Sai: outdoory → Đúng: outdoorsy.", u: "Speaking Part 1 hobbies: 'I'm pretty outdoorsy, so I go camping a lot.'", f: "outdoor (adj), outdoors (adv/n); indoorsy (trái nghĩa, thân mật)" },
  "sociable": { m: "soci- (xã hội, bạn bè) + -able → dễ kết bạn, thích giao du.", e: "Sai: I'm a social person (vẫn được) nhưng đừng nhầm social (thuộc xã hội) với sociable (hòa đồng).", u: "Speaking Part 1–2 personality: 'My best friend is very sociable and easygoing.'", f: "sociable (adj), sociability (n), socialise (v), unsociable (trái nghĩa)" },
  "introvert": { m: "intro- (vào trong) + vert (quay) → hướng năng lượng vào bên trong.", e: "Sai: I'm very introvert → Đúng: I'm very introverted / I'm an introvert (danh từ cần 'an').", u: "Speaking Part 1–2 personality: 'As an introvert, I recharge by spending time alone.'", f: "introvert (n), introverted (adj), introversion (n); extrovert (trái nghĩa)" },
  "extrovert": { m: "extro- (ra ngoài) + vert (quay) → năng lượng hướng ra bên ngoài, thích đám đông.", e: "Sai: She is extrovert → Đúng: She is an extrovert / She is extroverted.", u: "Speaking Part 1–2: 'I'm more of an extrovert, so I love team projects.'", f: "extrovert (n), extroverted (adj), extroversion (n); ambivert (n)" },
  "keep fit": { m: "keep = giữ; fit = khỏe, cân đối → duy trì vóc dáng và sức khỏe.", e: "Sai: keep fitness → Đúng: keep fit / stay in shape. Sai: keep fit my body → Đúng: keep fit.", u: "Speaking Part 1 sport/health: 'I go jogging three times a week to keep fit.'", f: "fit (adj), fitness (n); stay in shape, stay healthy" },
  "get some fresh air": { m: "Hình ảnh: bước ra ngoài, hít một hơi không khí mát lành.", e: "Sai: take fresh airs → Đúng: get some fresh air (không đếm được). Sai: breathe a fresh air → Đúng: breathe fresh air.", u: "Speaking Part 1 parks, weekend: 'I go to the park to get some fresh air after studying.'", f: "fresh air (n); go outside, step out for a breather" },
  "pick up a hobby": { m: "Hình ảnh: nhặt (pick up) một sở thích mới lên → bắt đầu tập.", e: "Sai: pick a hobby up new → Đúng: pick up a new hobby. Sai: catch a hobby → Đúng: take up/pick up a hobby.", u: "Speaking Part 1–2: 'During the pandemic, I picked up baking as a hobby.'", f: "take up (đồng nghĩa); hobbyist (n); give up a hobby (trái nghĩa)" },
  "get into": { m: "Hình ảnh: bước 'vào trong' (into) một thế giới mới → bắt đầu mê.", e: "Sai: I got into to jazz → Đúng: I got into jazz. Sai: I get into playing yesterday → Đúng: I got into playing...", u: "Speaking Part 1–2: 'I got into photography when I was in high school.'", f: "be into (trạng thái thích); take up, develop an interest in" },
  "be into": { m: "Hình ảnh: đắm mình 'ở trong' (into) điều gì → đang thích.", e: "Sai: I into music → Đúng: I'm into music. Sai: I'm into play games → Đúng: I'm into playing games.", u: "Speaking Part 1 hobbies, cách nói tự nhiên: 'I'm really into K-pop at the moment.'", f: "get into (bắt đầu thích); be keen on, be fond of" },
  "be keen on": { m: "keen = sắc bén, hăng hái → hăng hái với điều gì → thích.", e: "Sai: I'm keen in sport → Đúng: I'm keen on sport. Sai: keen on to swim → Đúng: keen on swimming.", u: "Speaking Part 1: 'I'm not very keen on spicy food.' Cách nói Anh-Anh, đa dạng thay 'like'.", f: "keen (adj), keenly (adv), keenness (n); be fond of, be into" },
  "be a big fan of": { m: "fan = người hâm mộ; big = rất → fan cứng của thứ gì.", e: "Sai: I'm big fan of → Đúng: I'm a big fan of. Sai: I'm a big fan with → Đúng: a big fan of.", u: "Speaking Part 1–2: 'I'm a big fan of Studio Ghibli films.' Phủ định nhẹ: I'm not a big fan of...", f: "fan (n), fanbase (n); be crazy about, be passionate about" },
  "can't stand": { m: "stand = đứng vững chịu đựng → không thể đứng mà chịu → ghét.", e: "Sai: I can't stand to wait (được) – tự nhiên hơn: I can't stand waiting. Sai: I don't can stand → Đúng: I can't stand.", u: "Speaking Part 1: 'I can't stand crowded places.' Mạnh hơn 'don't like', giúp đa dạng từ vựng.", f: "can't bear, can't stomach, detest, loathe (đồng nghĩa)" },
  "not really my thing": { m: "thing = 'gu' riêng → không hẳn hợp gu tôi → nói tránh lịch sự.", e: "Sai: It's not really my things → Đúng: It's not really my thing (số ít).", u: "Speaking Part 1: 'Clubbing is not really my thing; I prefer quiet cafés.' Lịch sự hơn 'I hate it'.", f: "not my cup of tea, not my scene, not for me (đồng nghĩa)" },
  "passionate about": { m: "passion = đam mê cháy bỏng → say mê một lĩnh vực.", e: "Sai: passionate with/in music → Đúng: passionate about music. Sai: I passion about → Đúng: I'm passionate about.", u: "Speaking Part 1–2 work/study: 'I'm passionate about environmental issues.'", f: "passion (n), passionate (adj), passionately (adv); enthusiastic about" },
  "home-cooked": { m: "home (nhà) + cooked (được nấu) → bữa cơm mẹ nấu ở nhà.", e: "Sai: home-cook meal → Đúng: home-cooked meal (phân từ -ed). Sai: food cooked home → Đúng: home-cooked food.", u: "Speaking Part 1 food: 'Nothing beats a home-cooked meal after a long week.'", f: "home cooking (n), cook (v), homemade (adj, gần nghĩa)" },
  "takeaway": { m: "take (mang) + away (đi) → đồ ăn mua mang đi ăn chỗ khác.", e: "Sai: order a take away food → Đúng: order a takeaway. Anh-Mỹ dùng takeout.", u: "Speaking Part 1 food/cooking: 'We usually get a takeaway on Friday nights.'", f: "takeaway (n/adj), takeout (Anh-Mỹ), to go; delivery (n)" },
  "street food": { m: "Đồ ăn bán ngay trên vỉa hè, đường phố → bánh mì, phở gánh.", e: "Sai: street foods are cheap (thường không đếm được) → Đúng: street food is cheap.", u: "Speaking Part 1–2 food, du lịch: 'Vietnamese street food is famous for being cheap and tasty.'", f: "street vendor (n), food stall (n), hawker food (gần nghĩa)" },
  "sweet tooth": { m: "Hình ảnh: có một chiếc răng chỉ thèm đồ ngọt → người hảo ngọt.", e: "Sai: I'm a sweet tooth → Đúng: I have a sweet tooth. Sai: sweet teeth → Đúng: sweet tooth.", u: "Speaking Part 1 food/desserts: 'I have a real sweet tooth, so I can't resist bubble tea.'", f: "sweet (adj/n), sweets (n); savoury tooth (đùa, ít dùng)" },
  "picky eater": { m: "pick = chọn lựa → người ăn mà cứ chọn tới chọn lui → kén ăn.", e: "Sai: I'm a picky eat → Đúng: I'm a picky eater. Anh-Anh còn nói: a fussy eater.", u: "Speaking Part 1 food/childhood: 'I was a picky eater as a kid, but now I eat almost anything.'", f: "picky (adj), pick (v); fussy eater (Anh-Anh)" },
  "grab a bite": { m: "grab = chộp lấy; bite = một miếng cắn → chộp vội vài miếng.", e: "Sai: grab a bite of lunch → Đúng: grab a bite (to eat). Sai: grab a bit → Đúng: grab a bite.", u: "Speaking Part 1 eating out: 'We often grab a bite near the office at lunchtime.'", f: "bite (n/v); grab a quick lunch, have a snack" },
  "treat myself": { m: "treat = món thưởng → tự đãi mình một món ngon, món quà.", e: "Sai: treat for myself a cake → Đúng: treat myself to a cake (to + món).", u: "Speaking Part 1–2 shopping, rewards: 'After exams, I treat myself to a nice dinner.'", f: "treat (v/n), treatment (n); reward myself, spoil myself" },
  "window shopping": { m: "Hình ảnh: chỉ nhìn qua cửa kính (window) tiệm, không mua gì.", e: "Sai: do window shop → Đúng: go window shopping. Sai: shopping windows → Đúng: window shopping.", u: "Speaking Part 1 shopping: 'I enjoy going window shopping at the mall on weekends.'", f: "window-shop (v), window shopper (n); browse (v)" },
  "shop around": { m: "Hình ảnh: đi vòng quanh (around) nhiều cửa hàng để so giá.", e: "Sai: shop around the price → Đúng: shop around for the best price.", u: "Speaking Part 1 shopping: 'I always shop around before buying electronics.' TOEIC cũng gặp.", f: "compare prices; bargain hunting (n); browse (v)" },
  "splash out": { m: "Hình ảnh: tạt nước (splash) tung tóe → tiêu tiền phóng tay.", e: "Sai: splash out a new phone → Đúng: splash out on a new phone (bắt buộc 'on').", u: "Speaking Part 2 a purchase: 'I splashed out on a designer bag for my birthday.'", f: "splurge (v/n), spend lavishly; tighten my belt (trái nghĩa)" },
  "pricey": { m: "price + -y → nhiều giá → hơi đắt (nói thân mật).", e: "Sai: the price is pricey → Đúng: it's pricey / the price is high. Sai: pricy (ít dùng) → chuẩn: pricey.", u: "Speaking Part 1: 'Restaurants in the city centre are a bit pricey.' Thay cho 'expensive'.", f: "price (n/v), priceless (adj: vô giá); expensive, overpriced, costly" },
  "value for money": { m: "Giá trị (value) đổi lại số tiền (money) bỏ ra → đáng đồng tiền.", e: "Sai: it is worth for money → Đúng: it's good value for money / it's worth the money.", u: "Speaking Part 1 shopping: 'This phone is great value for money.' Cũng phổ biến trong TOEIC review.", f: "valuable (adj), value (n/v); bang for your buck (thân mật)" },
  "tech-savvy": { m: "savvy = hiểu biết, sành → sành sỏi về công nghệ.", e: "Sai: tech-savy → Đúng: tech-savvy. Sai: He is very savvy tech → Đúng: He is very tech-savvy.", u: "Speaking Part 1–3 technology: 'My grandparents aren't very tech-savvy.'", f: "savvy (adj/n); computer-literate, digitally literate (gần nghĩa)" },
  "scroll through": { m: "scroll = cuộn → dùng ngón tay cuộn qua (through) nội dung.", e: "Sai: scroll the phone → Đúng: scroll through my phone/feed. Sai: scrolling on through → Đúng: scrolling through.", u: "Speaking Part 1 phones/social media: 'I waste hours scrolling through TikTok.'", f: "scroll (v/n), doomscrolling (n); browse, swipe through" },
  "screen time": { m: "Thời gian (time) dán mắt vào màn hình (screen) điện thoại, máy tính.", e: "Sai: screens time → Đúng: screen time. Sai: reduce time of screen → Đúng: reduce/limit screen time.", u: "Speaking Part 3 và Writing Task 2 trẻ em – công nghệ: 'Parents should limit children's screen time.'", f: "screen (n), screen-free (adj); device usage, time online" },
  "go viral": { m: "viral = như virus → lan từ người này sang người khác chóng mặt.", e: "Sai: become viral (tạm) → tự nhiên hơn: go viral. Sai: The video viraled → Đúng: The video went viral.", u: "Speaking Part 2–3 social media: 'A video of my cat went viral last year.'", f: "viral (adj), virality (n); spread like wildfire, blow up online" },
  "keep in touch": { m: "touch = chạm → giữ cho hai người vẫn 'chạm' được nhau → giữ liên lạc.", e: "Sai: keep in touch to him → Đúng: keep in touch with him. Sai: keep touch → Đúng: keep in touch.", u: "Speaking Part 1 friends/communication: 'I keep in touch with old classmates via Zalo.'", f: "stay in touch, get in touch, lose touch (with) (mất liên lạc)" },
  "drift apart": { m: "Hình ảnh: hai chiếc thuyền trôi (drift) dần xa nhau (apart).", e: "Sai: drift away each other → Đúng: drift apart / drift apart from each other.", u: "Speaking Part 2 a friend: 'We drifted apart after university because we moved to different cities.'", f: "drift (v/n); grow apart, lose touch (đồng nghĩa)" },
  "get on well": { m: "Hình ảnh: cùng lên (on) một chuyến xe, đi êm (well) → hòa hợp.", e: "Sai: get on well to my brother → Đúng: get on well with my brother.", u: "Speaking Part 1 family/colleagues: 'I get on well with my colleagues.' Anh-Mỹ: get along well.", f: "get along (with), be on good terms with; fall out (trái nghĩa)" },
  "hit it off": { m: "Hình ảnh: vừa gặp đã 'bắt sóng' trúng (hit) nhau → hợp nhau ngay.", e: "Sai: we hit off it → Đúng: we hit it off. Sai: I hit it off him → Đúng: I hit it off with him.", u: "Speaking Part 2 describe a friend: 'We hit it off immediately on the first day of school.'", f: "click (v, thân mật); get on like a house on fire (đồng nghĩa)" },
  "bond over": { m: "bond = sợi dây gắn kết → gắn bó vì cùng thích một thứ.", e: "Sai: bond about music → Đúng: bond over music. Sai: we bonded with music → Đúng: we bonded over music.", u: "Speaking Part 2 a friend: 'We bonded over our love of football.'", f: "bond (n/v), bonding (n); connect over, share an interest in" },
  "quality time": { m: "Thời gian có chất lượng → ở bên người thân trọn vẹn, không điện thoại.", e: "Sai: spend a quality time → Đúng: spend quality time (không 'a'). Sai: qualified time → Đúng: quality time.", u: "Speaking Part 1–3 family: 'Busy parents struggle to spend quality time with their kids.'", f: "quality (n/adj); family time, time together" },
  "family gathering": { m: "gather = tụ họp → cả nhà tụ họp, ví dụ dịp Tết.", e: "Sai: family gather → Đúng: family gathering. Sai: join in a family gathering at Tet → Đúng: attend a family gathering.", u: "Speaking Part 2 a celebration: 'During Tet, we have a big family gathering at my grandparents' house.'", f: "gather (v), gathering (n); family reunion, get-together" },
  "scorching": { m: "scorch = thiêu cháy sém → nắng đến mức cháy da.", e: "Sai: scorched weather → Đúng: scorching weather. Sai: very scorching → Đúng: absolutely scorching.", u: "Speaking Part 1 weather: 'Summers in Hanoi are scorching, often over 38 degrees.'", f: "scorch (v), scorcher (n: ngày nóng); boiling, sweltering (đồng nghĩa)" },
  "muggy": { m: "Nghe như 'mặc gì cũng ướt' → nóng ẩm dính dấp, ngột ngạt.", e: "Sai: muddy weather (lầy lội) → Đúng: muggy weather. Hai từ dễ nhầm do gần âm.", u: "Speaking Part 1 weather: 'It gets really muggy in spring when everything feels damp.'", f: "mugginess (n); humid, sticky, close (gần nghĩa)" },
  "humid": { m: "Gần 'humidity' (độ ẩm) → không khí nhiều hơi nước.", e: "Sai: The weather is humidity → Đúng: The weather is humid / humidity is high.", u: "Speaking Part 1 weather/hometown: 'Saigon is hot and humid all year round.'", f: "humidity (n), humidifier (n), dehumidifier (n); damp, muggy" },
  "drizzle": { m: "Âm thanh 'rì rì' mưa nhỏ lất phất → mưa phùn.", e: "Sai: It drizzle → Đúng: It's drizzling. Sai: a heavy drizzle (mâu thuẫn) → Đúng: a light drizzle.", u: "Speaking Part 1 weather: 'Hanoi has a lot of drizzle in late winter.'", f: "drizzle (n/v), drizzly (adj); light rain, shower" },
  "downpour": { m: "down (xuống) + pour (đổ) → trời đổ nước xuống ào ào.", e: "Sai: a heavy downpour rain → Đúng: a heavy downpour. Sai: down pour → Đúng: downpour.", u: "Speaking Part 1–2 weather: 'We got caught in a sudden downpour on the way home.'", f: "pour (v): it's pouring; torrential rain, cloudburst (gần nghĩa)" },
  "packed": { m: "pack = nhét đầy vali → nơi chốn bị nhét đầy người.", e: "Sai: packed of people → Đúng: packed with people. Sai: very packed → Đúng: absolutely packed.", u: "Speaking Part 1–2 places: 'The beach was packed during the holiday.'", f: "pack (v/n), jam-packed (adj); crowded, crammed" },
  "serene": { m: "Gần 'serenade' (khúc nhạc dịu êm) → không gian yên bình, tĩnh lặng.", e: "Sai: serene of mind → Đúng: a serene place / serenity of mind. Không dùng cho người ồn ào.", u: "Speaking Part 2 a peaceful place: 'The lake is serene early in the morning.'", f: "serenity (n), serenely (adv); tranquil, peaceful, calm" },
  "state-of-the-art": { m: "Hình ảnh: đạt đỉnh cao (state) của nghệ thuật/kỹ thuật hiện tại → tối tân.", e: "Sai: a state of art equipment → Đúng: state-of-the-art equipment (đủ 'the' và gạch nối).", u: "Speaking Part 2–3 technology/buildings: 'The library has state-of-the-art facilities.'", f: "cutting-edge, high-tech, advanced (đồng nghĩa); outdated (trái nghĩa)" },
  "old-fashioned": { m: "old + fashion (thời trang) → kiểu thời xưa, đã lỗi mốt.", e: "Sai: old-fashion → Đúng: old-fashioned (có -ed). Sai: old-fashioned person ideas → Đúng: old-fashioned ideas.", u: "Speaking Part 1–3: 'My grandparents have quite old-fashioned views about marriage.'", f: "fashion (n), fashionable (adj); outdated, dated, traditional" },
  "trendy": { m: "trend = xu hướng → đi theo xu hướng mới nhất.", e: "Sai: trendy fashion of young → Đúng: trendy among young people. Sai: trendding → Đúng: trending.", u: "Speaking Part 1 clothes/cafés: 'There are lots of trendy cafés in my neighbourhood.'", f: "trend (n), trending (adj), trendsetter (n); fashionable, stylish" },
  "must-have": { m: "'Phải có' (must have) → đã thành danh từ: món ai cũng muốn sở hữu.", e: "Sai: a must have (thiếu gạch nối) → Đúng: a must-have. Sai: must-haves item → Đúng: must-have item.", u: "Speaking Part 2 an object: 'Wireless earbuds are a must-have for students.'", f: "must-see, must-read, must-try (cùng mẫu); essential (n/adj)" },
  "time-consuming": { m: "consume = tiêu thụ → việc 'nuốt' rất nhiều thời gian.", e: "Sai: time-consumed → Đúng: time-consuming. Sai: It takes time-consuming → Đúng: It's time-consuming.", u: "Speaking Part 1–3, Writing Task 2: 'Cooking every day is time-consuming.'", f: "consume (v), consumption (n); lengthy, laborious (gần nghĩa)" },
  "step out of my comfort zone": { m: "Hình ảnh: bước khỏi vùng (zone) thoải mái quen thuộc để thử điều mới.", e: "Sai: go out my comfort zone → Đúng: step out of my comfort zone. Sai: comfortable zone → Đúng: comfort zone.", u: "Speaking Part 2 a challenge: 'Joining the debate club forced me to step out of my comfort zone.'", f: "comfort zone (n); push myself, take on a challenge" },
  "a sense of achievement": { m: "sense = cảm giác; achieve = đạt được → cảm giác 'mình làm được rồi'.", e: "Sai: a sense of achieve → Đúng: a sense of achievement. Sai: feel a sense achievement → Đúng: feel a sense of achievement.", u: "Speaking Part 2 an achievement: 'Finishing a marathon gave me a huge sense of achievement.'", f: "achieve (v), achievement (n), achiever (n); a sense of accomplishment" },
  "life-changing": { m: "Thay đổi (change) cả cuộc đời (life) → bước ngoặt lớn.", e: "Sai: life-changed experience → Đúng: life-changing experience. Sai: change-life → Đúng: life-changing.", u: "Speaking Part 2 an experience/trip: 'Studying abroad was a life-changing experience for me.'", f: "life-altering, transformative (đồng nghĩa); turning point (n)" },
  "learning curve": { m: "Đồ thị (curve) cho thấy tốc độ học; dốc càng cao càng phải học nhiều nhanh.", e: "Sai: high learning curve (dễ hiểu nhầm) → Đúng: a steep learning curve (nhiều thứ phải học).", u: "Speaking Part 2 a new job/skill: 'There was a steep learning curve in my first month at work.'", f: "learn (v), learner (n); steep/gentle learning curve" },
  "peer pressure": { m: "peer = người ngang hàng, bạn cùng lứa → áp lực phải làm giống bạn bè.", e: "Sai: pressure of peers group → Đúng: peer pressure. Sai: under the peer pressure → Đúng: under peer pressure.", u: "Speaking Part 3 và Writing Task 2 về thanh thiếu niên: 'Teenagers often smoke due to peer pressure.'", f: "peer (n), peer group (n); social pressure, conformity (n)" },
  "older generation": { m: "generation = thế hệ; older = lớn tuổi hơn → ông bà, cha mẹ.", e: "Sai: the old generations people → Đúng: the older generation. Sai: older generation is (thiếu 'the') → Đúng: The older generation is...", u: "Speaking Part 3 so sánh thế hệ: 'The older generation tends to value stability.'", f: "generation (n), generational (adj); the elderly, seniors; generation gap" },
  "younger generation": { m: "Thế hệ (generation) trẻ hơn (younger) → Gen Z, Gen Alpha.", e: "Sai: young generations nowadays → Đúng: the younger generation nowadays. Sai: younger generation is (thiếu the) → Đúng: The younger generation is.", u: "Speaking Part 3 và Writing Task 2: 'The younger generation is more tech-savvy.'", f: "youth (n), young people; generation gap, digital natives" },
  "i see where you're coming from": { m: "Hình ảnh: tôi thấy bạn 'đi ra từ' điểm xuất phát nào → hiểu lý do bạn nghĩ vậy.", e: "Sai: I see where are you coming from → Đúng: I see where you're coming from (không đảo ngữ).", u: "Speaking Part 3: thừa nhận quan điểm khác rồi phản biện: 'I see where you're coming from, but...'", f: "I understand your point, fair point, I take your point" },
  "there's no denying that": { m: "deny = phủ nhận → không có cách nào phủ nhận → chắc chắn đúng.", e: "Sai: There's no deny that → Đúng: There's no denying that (no + V-ing).", u: "Speaking Part 3 và Writing Task 2: 'There's no denying that the internet has changed education.'", f: "deny (v), denial (n), undeniable (adj), undeniably (adv)" },
  "on the flip side": { m: "Hình ảnh: lật (flip) đồng xu sang mặt kia → xét mặt ngược lại.", e: "Sai: in the flip side → Đúng: on the flip side. Thân mật; trong Writing dùng On the other hand.", u: "Speaking Part 3 nêu mặt trái: 'Social media connects people. On the flip side, it can be addictive.'", f: "on the other hand, conversely, then again" },
  "take something for granted": { m: "granted = đã được ban sẵn → coi như mặc nhiên phải có, quên trân trọng.", e: "Sai: take it as granted → Đúng: take it for granted. Sai: take for granted my parents → Đúng: take my parents for granted.", u: "Speaking Part 3: 'We often take clean water for granted.' Cũng hay dùng trong Writing Task 2.", f: "grant (v/n), granted (conj: đành rằng); appreciate (trái nghĩa)" },
  "it all boils down to": { m: "Hình ảnh: đun sôi (boil) nồi nước cho cạn → chỉ còn phần cốt lõi.", e: "Sai: it all boils down on → Đúng: it all boils down to. Sai: it boils down to that money → Đúng: it boils down to money.", u: "Speaking Part 3 kết ý: 'In the end, it all boils down to personal choice.'", f: "boil down to (phr v); come down to, essentially" },
  "speaking from experience": { m: "Nói ra (speaking) từ chính trải nghiệm (experience) của bản thân → có sức thuyết phục.", e: "Sai: speaking from my experiences, I think → Đúng: Speaking from experience, I think... (không cần 'my').", u: "Speaking Part 3: đưa ví dụ cá nhân làm dẫn chứng: 'Speaking from experience, group study really helps.'", f: "in my experience, from personal experience, firsthand (adv)" },
  "registrar": { m: "register = đăng ký → văn phòng lo đăng ký môn, lưu hồ sơ, cấp bảng điểm.", e: "Sai: go to the registration to get transcript → Đúng: go to the registrar's office to get a transcript.", u: "TOEFL Listening hội thoại campus: sinh viên tới registrar's office để đổi lớp, xin bảng điểm (transcript).", f: "register (v), registration (n), registry (n); admissions office (khác)" },
  "bursar": { m: "Gần 'purse' (ví tiền) → phòng giữ ví tiền của trường → tài vụ, học phí.", e: "Sai: pay tuition at the registrar → Đúng: pay tuition at the bursar's office.", u: "TOEFL Listening: sinh viên hỏi bursar's office về hóa đơn học phí, khoản phạt trễ hạn.", f: "bursar's office (n), bursary (n: học bổng, Anh-Anh); student accounts" },
  "financial aid": { m: "aid = trợ giúp; financial = tài chính → học bổng, khoản vay, trợ cấp học phí.", e: "Sai: financial aids → Đúng: financial aid (không đếm được). Sai: apply financial aid → Đúng: apply for financial aid.", u: "TOEFL Listening campus: hỏi văn phòng financial aid về hạn nộp đơn, điều kiện duy trì học bổng.", f: "scholarship (n), grant (n), student loan (n), FAFSA (Mỹ)" },
  "dean": { m: "Người 'đứng đầu' khoa → trưởng khoa, cao hơn trưởng bộ môn.", e: "Sai: the dean of class → Đúng: the dean of the faculty/college. Đừng nhầm dean với head of department.", u: "TOEFL Listening: dean of students giải quyết kỷ luật, đơn xin ngoại lệ; dean's list = danh sách SV giỏi.", f: "deanship (n), dean's list (n), dean of students; provost (n, cấp cao hơn)" },
  "office hours": { m: "Giờ giáo sư ngồi tại văn phòng (office) để sinh viên ghé hỏi bài.", e: "Sai: go to professor's office hour → Đúng: go to the professor's office hours (thường số nhiều).", u: "TOEFL Listening: nhiều hội thoại diễn ra trong office hours – SV hỏi về bài luận, điểm số.", f: "office (n); drop-in hours, consultation hours (gần nghĩa)" },
  "course load": { m: "load = tải trọng → khối lượng các môn mà sinh viên gánh trong một kỳ.", e: "Sai: heavy courses load → Đúng: a heavy course load. Sai: big course load → Đúng: heavy/light course load.", u: "TOEFL Listening: cố vấn khuyên giảm course load khi SV đi làm thêm; liên quan full-time status.", f: "credit hours (n), workload (n), full-time/part-time status" },
  "drop a class": { m: "drop = thả rơi → thả bớt một lớp khỏi thời khóa biểu.", e: "Sai: drop out a class → Đúng: drop a class (drop out = bỏ học hẳn).", u: "TOEFL Listening: SV muốn drop a class nhưng lo ảnh hưởng học bổng hoặc quá hạn add-drop.", f: "drop (v), withdraw from a course; drop out (bỏ học), add a class" },
  "add-drop period": { m: "add (thêm) + drop (bớt) → mấy tuần đầu kỳ được thêm bớt môn tự do.", e: "Sai: add and drop time → Đúng: the add-drop period (hoặc drop/add period).", u: "TOEFL Listening: người nghe phải nắm hạn chót add-drop period và phí khi rút môn muộn.", f: "add/drop (n), deadline (n); late withdrawal (n)" },
  "midterm": { m: "mid (giữa) + term (học kỳ) → kỳ thi giữa học kỳ.", e: "Sai: middle term exam → Đúng: midterm (exam). Sai: take midterm (thiếu mạo từ) → Đúng: take the midterm.", u: "TOEFL Listening/Speaking: SV bàn chuyện ôn midterm, xin thi bù (make-up exam).", f: "midterm (n/adj), final (n), quiz (n), make-up exam (n)" },
  "final exam": { m: "final = cuối cùng → bài thi cuối cùng của môn.", e: "Sai: last exam (mơ hồ) → Đúng: final exam / finals. Sai: do the final exam → Đúng: take the final exam.", u: "TOEFL Listening: lịch thi finals, giáo sư nói nội dung final là cumulative (tích lũy cả kỳ).", f: "finals (n), final (adj); cumulative exam, midterm" },
  "gpa": { m: "Grade Point Average → trung bình điểm hệ 4.0 tích lũy qua các kỳ.", e: "Sai: My GPA is 8.5 (thang 10 VN) → Đúng: My GPA is 3.5 (thang 4.0). Sai: GPA point → Đúng: GPA.", u: "TOEFL Listening: duy trì GPA để giữ học bổng; academic probation khi GPA quá thấp.", f: "grade (n), grade point (n), cumulative GPA, transcript (n)" },
  "honor code": { m: "honor = danh dự → bộ quy tắc danh dự: không gian lận, không đạo văn.", e: "Sai: honour code violation is small → Đúng: an honor code violation is serious. Anh-Anh viết honour.", u: "TOEFL Listening/Reading: vi phạm honor code (plagiarism, cheating) dẫn tới đình chỉ học.", f: "honor (n/v), honorable (adj); academic integrity, plagiarism (n)" },
  "work-study": { m: "work (làm) + study (học) → chương trình cho SV làm việc trong trường để trang trải học phí.", e: "Sai: a work and study job → Đúng: a work-study job / a work-study position.", u: "TOEFL Listening: SV làm work-study ở thư viện, căng tin; liên quan financial aid.", f: "work-study program (n), campus job, part-time job" },
  "resident advisor": { m: "resident = người cư trú; advisor = cố vấn → SV khóa trên quản lý tầng ký túc.", e: "Sai: room advisor → Đúng: resident advisor (RA). Chính tả cũng đúng: resident adviser.", u: "TOEFL Listening: SV báo RA về tiếng ồn, đổi phòng, sự kiện ký túc xá.", f: "RA (viết tắt), resident (n), residence hall (n), dorm (n)" },
  "meal plan": { m: "Gói (plan) bữa ăn (meal) trả trước, quẹt thẻ ăn ở nhà ăn trường.", e: "Sai: food plan → Đúng: meal plan. Sai: buy a meal plans → Đúng: buy a meal plan.", u: "TOEFL Listening: SV hỏi đổi gói meal plan, dùng 'meal swipes' hoặc dining dollars.", f: "meal (n), dining hall (n), cafeteria (n), meal swipe (n)" },
  "commencement": { m: "commence = bắt đầu → lễ tốt nghiệp là 'khởi đầu' cuộc đời mới.", e: "Sai: commencement = khai giảng (hiểu nhầm) → Đúng: commencement = lễ tốt nghiệp.", u: "TOEFL Listening/Reading: thông báo về commencement ceremony, đăng ký áo choàng, khách mời.", f: "commence (v), commencement (n); graduation ceremony, convocation (n)" },
  "freshman": { m: "fresh = mới tinh → sinh viên mới vào năm nhất.", e: "Sai: I'm a freshman student year one → Đúng: I'm a freshman. Số nhiều: freshmen.", u: "TOEFL Listening: freshman orientation, freshman dorm; chuỗi freshman → sophomore → junior → senior.", f: "freshmen (pl), first-year (n/adj), fresher (Anh-Anh)" },
  "sophomore": { m: "soph- (khôn, như philosophy) + more (ngốc) → năm hai 'khôn mà vẫn ngốc'.", e: "Sai: sophomore = năm ba → Đúng: sophomore = năm hai. Sai: sophomore year one → Đúng: sophomore year.", u: "TOEFL Listening: sinh viên năm hai thường phải chọn chuyên ngành (declare a major).", f: "sophomoric (adj: non nớt), junior (năm ba), senior (năm tư)" },
  "graduate student": { m: "graduate = đã tốt nghiệp → người đã có bằng cử nhân và học tiếp cao học.", e: "Sai: graduated student (người vừa tốt nghiệp) → Đúng: graduate student (học viên cao học).", u: "TOEFL Listening: grad student làm teaching assistant (TA) hoặc trợ lý nghiên cứu.", f: "grad student, postgraduate (Anh-Anh), undergraduate (cử nhân)" },
  "lab report": { m: "lab = phòng thí nghiệm → bản báo cáo kết quả sau buổi thí nghiệm.", e: "Sai: write a laboratory's report → Đúng: write a lab report. Sai: make a lab report → Đúng: write/submit a lab report.", u: "TOEFL Listening: SV hỏi TA về định dạng lab report, hạn nộp, phần methodology.", f: "laboratory (n), lab partner (n), lab session (n), write-up (n)" },
  "problem set": { m: "Một bộ (set) các bài toán (problem) giao về nhà → bài tập tính toán.", e: "Sai: problems set → Đúng: problem set. Sai: do the problem set's → Đúng: do the problem set.", u: "TOEFL Listening: môn toán, vật lý, kinh tế giao problem set hằng tuần; hay nói 'p-set'.", f: "p-set (viết tắt), assignment (n), homework (n), worksheet (n)" },
  "term paper": { m: "term = học kỳ → bài viết lớn nộp cuối kỳ, thường có nghiên cứu.", e: "Sai: term papers is due → Đúng: The term paper is due. Sai: do a term paper → Đúng: write a term paper.", u: "TOEFL Listening/Writing: SV xin gia hạn term paper, bàn chọn đề tài với giáo sư.", f: "research paper (n), essay (n), thesis (n), dissertation (n)" },
  "interlibrary loan": { m: "inter- (giữa) + library → mượn sách giữa các thư viện với nhau.", e: "Sai: borrow by interlibrary loans service → Đúng: request a book through interlibrary loan.", u: "TOEFL Listening: thủ thư hướng dẫn SV đặt sách qua interlibrary loan khi thư viện trường không có.", f: "loan (n/v), library (n), librarian (n); ILL (viết tắt)" },
  "on reserve": { m: "reserve = để dành → sách được giữ riêng ở quầy, chỉ mượn ngắn hạn.", e: "Sai: the book is in reserve → Đúng: the book is on reserve. Sai: reserved book to take home (thường không được).", u: "TOEFL Listening: giáo sư đặt tài liệu on reserve; SV chỉ được đọc tại chỗ vài giờ.", f: "reserve (v/n), reservation (n), reserve desk (n); course reserves" },
  "study group": { m: "Nhóm (group) học (study) cùng nhau ôn bài trước kỳ thi.", e: "Sai: learning group → Đúng: study group. Sai: join to a study group → Đúng: join a study group.", u: "TOEFL Listening/Speaking: SV đề xuất lập study group trước midterm; tranh luận ưu nhược của học nhóm.", f: "study (v/n), group (n); study session, study buddy (n)" },
  "chlorophyll": { m: "chloro- (xanh lục, như chlorine) + phyll (lá) → sắc tố xanh trong lá.", e: "Sai: chlorophyl → Đúng: chlorophyll (hai chữ l cuối). Sai: chlorophylls absorbs → Đúng: chlorophyll absorbs.", u: "TOEFL Reading/Listening sinh học: chlorophyll hấp thụ ánh sáng trong quang hợp (photosynthesis).", f: "chloroplast (n), photosynthesis (n), pigment (n), chlorophyllous (adj)" },
  "cell membrane": { m: "membrane = lớp màng mỏng; cell membrane như 'bức tường mềm' bao quanh tế bào, chọn lọc cho chất ra vào.", e: "Sai: cell membranes is thin → Đúng: cell membranes are thin. Đừng nhầm với cell wall (thành tế bào, chỉ có ở thực vật).", u: "TOEFL Reading/Lecture sinh học: 'The cell membrane regulates what enters and leaves the cell.' Hay đi với permeable, selectively.", f: "membrane (n), membranous (adj), cell wall (n, phân biệt), plasma membrane (từ đồng nghĩa)" },
  "microorganism": { m: "micro- (rất nhỏ) + organism (sinh vật) → sinh vật nhỏ tới mức phải dùng kính hiển vi mới thấy.", e: "Sai: a microorganisms → Đúng: a microorganism / microorganisms. Sai: micro organism (tách rời) → Đúng: microorganism (viết liền).", u: "TOEFL Reading về đất, bệnh, lên men: 'Soil microorganisms break down organic matter.' Thường thay bằng microbe để tránh lặp.", f: "microorganism (n), organism (n), microbe (n), microbial (adj), microscopic (adj)" },
  "fungi": { m: "fungi là số nhiều Latin của fungus; nhớ 'fun-guy' → 'cây nấm vui tính' mọc khắp nơi.", e: "Sai: a fungi → Đúng: a fungus. Sai: funguses is common → Đúng: fungi are common (số nhiều chuẩn học thuật).", u: "TOEFL Lecture sinh thái: fungi làm nhiệm vụ decomposers, phân hủy gỗ mục; cũng hay gặp trong bài về quan hệ cộng sinh với rễ cây.", f: "fungus (n, số ít), fungi (n, số nhiều), fungal (adj), fungicide (n, thuốc diệt nấm)" },
  "symbiosis": { m: "sym- (cùng) + bio (sống) → hai loài 'cùng sống' gắn bó với nhau.", e: "Sai: symbiosis between A with B → Đúng: symbiosis between A and B. Sai: a symbiosis relationship → Đúng: a symbiotic relationship.", u: "TOEFL Reading: đoạn mô tả loài A và B phụ thuộc nhau; câu hỏi thường yêu cầu phân biệt mutualism, commensalism, parasitism.", f: "symbiosis (n), symbiotic (adj), symbiotically (adv), symbiont (n, sinh vật cộng sinh)" },
  "mutualism": { m: "mutual = qua lại, cả hai bên → mutualism: quan hệ mà cả hai loài đều được lợi.", e: "Sai: mutualism is when one species benefits only → Đúng: in mutualism, both species benefit. Đó là commensalism nếu chỉ một bên lợi.", u: "TOEFL Lecture: ví dụ ong và hoa, cá hề và hải quỳ; giảng viên hay so sánh với parasitism để kiểm tra hiểu bài.", f: "mutualism (n), mutualistic (adj), mutual (adj), commensalism (n), parasitism (n)" },
  "parasite": { m: "para- (bên cạnh) + site (thức ăn, Hy Lạp) → kẻ ăn ké bên cạnh người khác, sống nhờ vật chủ.", e: "Sai: parasite lives on the host and helps it → Đúng: a parasite harms its host. Sai: parasite animal → Đúng: parasitic animal.", u: "TOEFL Reading về sinh học, y tế: parasite và host là cặp từ đi kèm. Dùng ẩn dụ chỉ người ăn bám trong bài luận.", f: "parasite (n), parasitic (adj), parasitism (n), host (n, vật chủ), parasitize (v)" },
  "camouflage": { m: "Gốc Pháp 'camoufler' = che giấu; tắc kè đổi màu hòa vào lá cây chính là camouflage.", e: "Sai: camouflage itself with (đánh vần camouflague) → Đúng: camouflage itself among the leaves. Nhớ: camou-flage, kết thúc -age.", u: "TOEFL Lecture động vật học: cơ chế tự vệ, 'Its coloration provides camouflage against predators.' Thường đặt cạnh mimicry.", f: "camouflage (n/v), camouflaged (adj), disguise (n/v, gần nghĩa), concealment (n)" },
  "mimicry": { m: "mimic = bắt chước (như diễn viên kịch câm 'mime') → mimicry: loài này giả dạng loài khác để lừa kẻ thù.", e: "Sai: mimicing → Đúng: mimicking (thêm k trước -ing/-ed). Sai: mimicry is hiding in background → Đúng: đó là camouflage.", u: "TOEFL Reading: bướm vô hại bắt chước màu bướm độc (Batesian mimicry); câu hỏi thường hỏi lợi ích tiến hóa của cơ chế này.", f: "mimic (v/n), mimicry (n), mimicked (v-ed), mimicking (v-ing), imitation (n)" },
  "mutation": { m: "mut- = thay đổi (như 'mutant' trong phim X-Men) → mutation: sự thay đổi trong gen.", e: "Sai: the gene mutated into a mutation → Đúng: the gene underwent a mutation. Sai: mutation happen → Đúng: mutations occur.", u: "TOEFL Lecture tiến hóa: 'Random mutations provide the raw material for natural selection.' Đi với genetic, beneficial, harmful.", f: "mutate (v), mutation (n), mutant (n/adj), mutational (adj)" },
  "offspring": { m: "off + spring (nảy ra) → những gì 'nảy ra' từ bố mẹ: con cái, con non.", e: "Sai: offsprings → Đúng: offspring (số nhiều giữ nguyên). Sai: an offspring are → Đúng: the offspring are healthy.", u: "TOEFL Reading động vật: 'Females invest more energy in raising offspring.' Văn phong học thuật thay cho children/babies.", f: "offspring (n, số ít = số nhiều), progeny (n), descendant (n), young (n, con non)" },
  "larva": { m: "Latin 'larva' = mặt nạ; con sâu là chiếc 'mặt nạ' che giấu hình dạng thật của con bướm sau này.", e: "Sai: larvas → Đúng: larvae (/ˈlɑːviː/). Sai: the larva of butterfly → Đúng: a butterfly larva is called a caterpillar.", u: "TOEFL Lecture côn trùng: các giai đoạn egg → larva → pupa → adult; câu hỏi sắp xếp trình tự rất hay gặp.", f: "larva (n), larvae (n, số nhiều), larval (adj), pupa (n), caterpillar (n)" },
  "metamorphosis": { m: "meta- (biến đổi) + morph (hình dạng) → thay hẳn hình dạng, như nòng nọc thành ếch.", e: "Sai: metamorphosises → Đúng: metamorphoses (số nhiều). Sai: the frog metamorphosis into → Đúng: the tadpole undergoes metamorphosis.", u: "TOEFL Reading: complete vs incomplete metamorphosis ở côn trùng. Viết luận dùng ẩn dụ: 'the city's metamorphosis'.", f: "metamorphosis (n), metamorphoses (n, số nhiều), metamorphose (v), morph (v), transformation (n)" },
  "pollination": { m: "pollen = phấn hoa → pollination: đưa phấn hoa từ nhị sang nhụy, giúp cây kết hạt.", e: "Sai: pollenation → Đúng: pollination (chữ i). Sai: bees pollination flowers → Đúng: bees pollinate flowers.", u: "TOEFL Lecture sinh thái: cross-pollination, wind pollination; nói về sự suy giảm loài ong ảnh hưởng nông nghiệp.", f: "pollen (n), pollinate (v), pollination (n), pollinator (n), cross-pollination (n)" },
  "pollinator": { m: "pollinate + -or (người/vật làm) → kẻ chở phấn hoa: ong, bướm, chim ruồi, dơi.", e: "Sai: pollinater → Đúng: pollinator (đuôi -or). Sai: pollinators is declining → Đúng: pollinator populations are declining.", u: "TOEFL Reading: hoa thu hút pollinators bằng màu sắc, mùi hương, mật; IELTS Writing môi trường: 'decline in pollinators threatens crops'.", f: "pollinator (n), pollinate (v), pollination (n), pollen (n)" },
  "nectar": { m: "Thần thoại Hy Lạp: nectar là đồ uống của thần → mật hoa ngọt 'như đồ uống của thần' dành cho ong.", e: "Sai: bees collect nectars → Đúng: bees collect nectar (không đếm được). Đừng nhầm nectar (mật hoa) với honey (mật ong).", u: "TOEFL Lecture: hoa thưởng nectar để đổi lấy dịch vụ thụ phấn; hay đi với nectar-feeding birds, nectar guides.", f: "nectar (n), nectarous (adj), nectary (n, tuyến mật), honey (n, phân biệt)" },
  "germinate": { m: "germ = mầm (cùng gốc 'germ' vi trùng = mầm bệnh) → germinate: mầm hạt bắt đầu nhú lên.", e: "Sai: the seed was germinated itself → Đúng: the seed germinated. Sai: germinate a plan → Đúng: an idea germinated (nghĩa bóng).", u: "TOEFL Reading thực vật: 'Seeds germinate only when moisture and temperature are suitable.' Câu hỏi thường về điều kiện nảy mầm.", f: "germinate (v), germination (n), germ (n), sprout (v, gần nghĩa)" },
  "seed dispersal": { m: "disperse = rải tản ra → seed dispersal: cây 'gửi' hạt đi xa nhờ gió, nước, động vật.", e: "Sai: seed dispersion by wind → Đúng: seed dispersal by wind. Sai: seeds dispersal → Đúng: seed dispersal (danh từ ghép).", u: "TOEFL Lecture thực vật: các cơ chế phát tán; ví dụ chim ăn quả rồi thải hạt nơi khác. Câu hỏi phân loại cơ chế rất phổ biến.", f: "disperse (v), dispersal (n), dispersion (n), scatter (v), spread (v)" },
  "deciduous": { m: "Latin decidere = rơi xuống → cây deciduous để lá 'rơi xuống' mỗi mùa thu.", e: "Sai: deciduos / decidious → Đúng: deciduous. Sai: deciduous trees keep leaves all year → Đúng: evergreen trees do.", u: "TOEFL Reading về rừng ôn đới: deciduous forests vs coniferous forests; câu hỏi so sánh khả năng thích nghi mùa đông.", f: "deciduous (adj), evergreen (adj, trái nghĩa), shed (v, rụng lá)" },
  "coniferous": { m: "cone (quả nón thông) + fer (mang) → cây mang quả hình nón: thông, tùng, bách.", e: "Sai: coniferous are tall → Đúng: conifers are tall / coniferous trees are tall. Coniferous là tính từ, cần danh từ đi kèm.", u: "TOEFL Lecture: rừng lá kim (taiga) ở vùng lạnh; lá hình kim giảm mất nước. Hay xuất hiện trong bài về biome.", f: "conifer (n), coniferous (adj), cone (n), evergreen (adj), taiga (n)" },
  "canopy": { m: "Hình ảnh: tán lá rừng như chiếc 'mái che' (canopy) phủ phía trên, ánh sáng khó lọt xuống đất.", e: "Sai: on the canopy of the forest live birds → Đúng: many birds live in the forest canopy. Dùng 'in the canopy'.", u: "TOEFL Reading rừng mưa nhiệt đới: các tầng canopy, understory, forest floor; câu hỏi về lượng ánh sáng mỗi tầng.", f: "canopy (n), canopies (n, số nhiều), understory (n), emergent layer (n)" },
  "tundra": { m: "Gốc tiếng Sami nghĩa 'đồng bằng không cây' → tundra: vùng lạnh giá, đất đóng băng, chỉ có rêu cỏ.", e: "Sai: tundra has many tall trees → Đúng: the tundra is treeless. Thường dùng mạo từ: the Arctic tundra.", u: "TOEFL Lecture địa lý: permafrost, mùa sinh trưởng ngắn; IELTS Writing biến đổi khí hậu: tundra tan băng giải phóng khí metan.", f: "tundra (n), permafrost (n), Arctic (adj), taiga (n, vùng kế bên)" },
  "savanna": { m: "Hình ảnh: đồng cỏ châu Phi có sư tử, ngựa vằn, cây keo lác đác — đó là savanna.", e: "Sai: savana → Đúng: savanna (hoặc savannah). Sai: savanna is a dense forest → Đúng: a savanna is grassland with scattered trees.", u: "TOEFL Reading biome: mùa mưa và mùa khô rõ rệt; câu hỏi so sánh savanna với rainforest hoặc desert.", f: "savanna/savannah (n), grassland (n), prairie (n), steppe (n)" },
  "estuary": { m: "Latin aestus = thủy triều → estuary: nơi sông gặp biển, nước ngọt hòa nước mặn theo thủy triều.", e: "Sai: estuary of the sea → Đúng: the estuary of the river. Đừng nhầm với delta (bãi bồi hình quạt).", u: "TOEFL Lecture: nước lợ (brackish water), nơi sinh sản của nhiều loài cá; IELTS Writing về ô nhiễm vùng ven biển.", f: "estuary (n), estuarine (adj), brackish (adj), river mouth (n), delta (n)" },
  "plankton": { m: "Hy Lạp planktos = trôi dạt → plankton: sinh vật nhỏ trôi theo dòng nước, không tự bơi xa.", e: "Sai: planktons → Đúng: plankton (không đếm được). Sai: a plankton is big → Đúng: plankton are tiny organisms.", u: "TOEFL Reading đại dương: nền tảng chuỗi thức ăn biển; phân biệt phytoplankton (thực vật) và zooplankton (động vật).", f: "plankton (n), phytoplankton (n), zooplankton (n), planktonic (adj)" },
  "algae": { m: "algae là số nhiều của alga; hình ảnh lớp rêu xanh nhớt nổi trên mặt ao chính là tảo.", e: "Sai: an algae → Đúng: an alga / some algae. Sai: algae is (ít trang trọng) → Đúng học thuật: algae are.", u: "TOEFL Lecture: algal bloom do phân bón chảy xuống hồ; IELTS Writing môi trường: algae làm nhiên liệu sinh học.", f: "alga (n, số ít), algae (n, số nhiều), algal (adj), seaweed (n)" },
  "invertebrate": { m: "in- (không) + vertebra (đốt sống) → động vật không có cột sống: giun, sứa, côn trùng.", e: "Sai: invertebrate animals has → Đúng: invertebrates have. Sai: inverterbrate → Đúng: invertebrate (vert-e-brate).", u: "TOEFL Reading phân loại động vật: 'Insects are the most diverse group of invertebrates.' Hay đối chiếu với vertebrates.", f: "invertebrate (n/adj), vertebrate (n/adj), vertebra (n), spine (n)" },
  "vertebrate": { m: "vertebra = đốt sống → vertebrate: động vật có xương sống, như cá, chim, người.", e: "Sai: vertebrae animals → Đúng: vertebrate animals. Vertebrae là số nhiều của vertebra (đốt sống), không phải tính từ.", u: "TOEFL Lecture tiến hóa: năm lớp vertebrates — fish, amphibians, reptiles, birds, mammals; câu hỏi phân loại hay xuất hiện.", f: "vertebrate (n/adj), vertebra (n), vertebrae (n, số nhiều), invertebrate (n), vertebral (adj)" },
  "amphibian": { m: "amphi- (hai) + bios (sống) → sống hai môi trường: nước và cạn, như ếch, kỳ nhông.", e: "Sai: amphibians are reptiles → Đúng: amphibians and reptiles are different classes. Sai: amphibia frog → Đúng: amphibious/amphibian frog.", u: "TOEFL Reading: da ẩm, đẻ trứng trong nước; amphibian decline là chỉ báo ô nhiễm môi trường.", f: "amphibian (n/adj), amphibious (adj, lội nước), amphibia (n, lớp lưỡng cư)" },
  "reptile": { m: "Latin repere = bò → reptile: loài 'bò sát' mặt đất như rắn, thằn lằn, cá sấu.", e: "Sai: reptiles are warm-blooded → Đúng: reptiles are cold-blooded (ectothermic). Sai: reptilian (danh từ) → thường dùng reptile.", u: "TOEFL Lecture: thích nghi trên cạn nhờ vảy và trứng có vỏ; câu hỏi so sánh với amphibians.", f: "reptile (n), reptilian (adj), ectotherm (n), cold-blooded (adj)" },
  "primate": { m: "prim- = đứng đầu (như 'prime') → primate: bộ 'đứng đầu' muông thú gồm khỉ, vượn, người.", e: "Sai: primate là 'động vật nguyên thủy' → Đúng: linh trưởng. Sai: primates is intelligent → Đúng: primates are intelligent.", u: "TOEFL Reading: hành vi xã hội, dùng công cụ ở tinh tinh; IELTS Speaking về động vật: 'primates share many traits with humans'.", f: "primate (n), primatology (n), primatologist (n), ape (n), monkey (n)" },
  "herbivore": { m: "herb (cỏ, thảo mộc) + -vore (ăn) → loài ăn cỏ, như bò, voi, hươu.", e: "Sai: herbivore animals eats → Đúng: herbivores eat. Sai: herbivorous (danh từ) → Đúng: herbivorous là tính từ; herbivore là danh từ.", u: "TOEFL Lecture chuỗi thức ăn: herbivores là primary consumers; câu hỏi về quan hệ với producers và carnivores.", f: "herbivore (n), herbivorous (adj), carnivore (n), omnivore (n), -vore (hậu tố: ăn)" },
  "carnivore": { m: "carn- = thịt (như 'carnival' — lễ ăn thịt trước mùa chay) + -vore → loài ăn thịt.", e: "Sai: carnivore eats plants → Đúng: carnivores eat meat. Sai: a carnivorous → Đúng: a carnivore / a carnivorous animal.", u: "TOEFL Reading: carnivores ở đầu chuỗi thức ăn (apex predators); IELTS Speaking về ăn chay: 'humans aren't pure carnivores'.", f: "carnivore (n), carnivorous (adj), predator (n), herbivore (n), omnivore (n)" },
  "forage": { m: "Gốc Pháp 'fourrage' = cỏ khô cho ngựa → forage: lùng sục tìm thức ăn.", e: "Sai: forage food (thừa) → Đúng: forage for food. Sai: animals are foraging the seeds → Đúng: foraging for seeds.", u: "TOEFL Lecture hành vi động vật: optimal foraging theory, đàn kiến kiếm ăn; dùng cả cho người săn bắt hái lượm.", f: "forage (v/n), forager (n), foraging (n), scavenge (v), graze (v)" },
  "territorial": { m: "territory = lãnh thổ + -al → territorial: hay bảo vệ 'vùng đất của mình', như chó sủa người lạ.", e: "Sai: territory behavior → Đúng: territorial behavior. Sai: a territorial dispute about → Đúng: a territorial dispute over.", u: "TOEFL Reading: chim hót để đánh dấu lãnh thổ; cũng dùng trong bài lịch sử, chính trị: territorial expansion.", f: "territory (n), territorial (adj), territoriality (n), territorially (adv)" },
  "courtship": { m: "court (tòa, cung đình; cũng là 'tán tỉnh') + -ship → courtship: màn 'trình diễn' tán tỉnh trước khi giao phối.", e: "Sai: courtship dance of birds is → Đúng: the courtship display of birds is. Sai: courtships behavior → Đúng: courtship behavior.", u: "TOEFL Lecture: chim công xòe đuôi, chim thiên đường nhảy múa; câu hỏi về vai trò chọn lọc giới tính.", f: "court (v, tán tỉnh), courtship (n), mating (n), display (n)" },
  "hibernation": { m: "Latin hibernus = mùa đông → hibernation: 'ngủ' suốt mùa đông, như gấu nằm trong hang.", e: "Sai: bears hibernation in winter → Đúng: bears hibernate in winter. Sai: go to hibernation → Đúng: go into hibernation.", u: "TOEFL Reading: nhịp tim, thân nhiệt giảm để tiết kiệm năng lượng; phân biệt với estivation (ngủ hè). Dùng bóng: 'project in hibernation'.", f: "hibernate (v), hibernation (n), dormancy (n), torpor (n), estivation (n)" },
  "sediment": { m: "sed- = ngồi (như 'sedentary') → sediment: cặn 'ngồi' lắng xuống đáy sông, hồ.", e: "Sai: sediments was carried → Đúng: sediment was carried (thường không đếm được). Sai: sedimant → Đúng: sediment.", u: "TOEFL Lecture địa chất: sông vận chuyển và bồi lắng sediment tạo đồng bằng; liên quan đến tuổi các tầng đá.", f: "sediment (n), sedimentary (adj), sedimentation (n), deposit (n/v)" },
  "sedimentary rock": { m: "Lớp cặn lắng (sediment) chồng lên nhau nhiều năm, bị nén chặt → đá trầm tích, như sa thạch, đá vôi.", e: "Sai: sediment rock → Đúng: sedimentary rock. Sai: sedimentary rocks is layered → Đúng: sedimentary rocks are layered.", u: "TOEFL Reading: nơi thường tìm thấy hóa thạch; câu hỏi so sánh ba loại đá trong chu trình đá (rock cycle).", f: "sedimentary (adj), sediment (n), igneous rock (n), metamorphic rock (n), limestone (n)" },
  "igneous rock": { m: "ign- = lửa (như 'ignite') → igneous rock: đá 'sinh ra từ lửa', do mắc-ma nguội đông lại.", e: "Sai: ignous rock → Đúng: igneous rock (i-g-n-e-o-u-s). Sai: igneous is formed by pressure → Đúng: that is metamorphic rock.", u: "TOEFL Lecture địa chất: granite (xâm nhập) và basalt (phun trào); câu hỏi về tốc độ nguội ảnh hưởng kích thước tinh thể.", f: "igneous (adj), ignite (v, cùng gốc), granite (n), basalt (n), magma (n)" },
  "metamorphic rock": { m: "meta (biến đổi) + morph (hình) → đá bị nhiệt và áp suất 'biến hình', như đá vôi thành đá hoa.", e: "Sai: metamorphosis rock → Đúng: metamorphic rock. Sai: metamorphic rock comes from lava → Đúng: it forms under heat and pressure.", u: "TOEFL Reading chu trình đá: marble từ limestone, slate từ shale; câu hỏi chi tiết về điều kiện hình thành.", f: "metamorphic (adj), metamorphism (n), metamorphose (v), marble (n), slate (n)" },
  "weathering": { m: "weather (thời tiết) + -ing → mưa, gió, nắng 'gặm mòn' đá ngày qua ngày.", e: "Sai: weathering and erosion are the same → Đúng: weathering breaks rock; erosion carries it away. Sai: weathers of rock → Đúng: weathering of rock.", u: "TOEFL Lecture địa chất: chemical vs mechanical weathering; câu hỏi phân biệt với erosion rất thường gặp.", f: "weather (v, phong hóa), weathering (n), weathered (adj), erosion (n)" },
  "glaciation": { m: "glacier = sông băng → glaciation: thời kỳ sông băng lan rộng bao phủ mặt đất.", e: "Sai: glaciations period → Đúng: a period of glaciation. Sai: glacation → Đúng: glaciation (gla-ci-a-tion).", u: "TOEFL Reading: dấu vết glaciation như thung lũng hình chữ U, đá tảng lạc; liên quan bài về ice age.", f: "glacier (n), glacial (adj), glaciation (n), glaciated (adj), ice sheet (n)" },
  "plate tectonics": { m: "tecton (Hy Lạp: thợ xây) → plate tectonics: các 'tấm' vỏ Trái Đất xô đẩy, xây nên núi và đại dương.", e: "Sai: plate tectonics are a theory → Đúng: plate tectonics is a theory (động từ số ít). Sai: plates tectonic → Đúng: tectonic plates.", u: "TOEFL Lecture: giải thích động đất, núi lửa, dãy Himalaya; thường nhắc tới lý thuyết trôi dạt lục địa của Wegener.", f: "tectonic (adj), tectonic plate (n), plate boundary (n), continental drift (n), subduction (n)" },
  "fault line": { m: "fault = vết nứt, chỗ hỏng → fault line: đường nứt giữa hai khối đá, nơi động đất dễ xảy ra.", e: "Sai: fault line là 'đường lỗi' → Đúng: đường đứt gãy. Sai: on the fault line earthquake → Đúng: earthquakes occur along fault lines.", u: "TOEFL Reading: San Andreas Fault; IELTS Writing dùng bóng: 'fault lines in society' (rạn nứt xã hội).", f: "fault (n), fault line (n), faulting (n), rift (n), fracture (n)" },
  "magma": { m: "Magma ở trong lòng đất; phun ra ngoài thì gọi là lava. 'M' = 'mặt dưới', 'L' = 'lên trên'.", e: "Sai: lava under the ground → Đúng: magma under the ground. Sai: magmas erupts → Đúng: magma erupts as lava.", u: "TOEFL Lecture núi lửa: magma chamber, độ nhớt magma quyết định kiểu phun trào; câu hỏi phân biệt magma/lava.", f: "magma (n), magmatic (adj), lava (n), magma chamber (n), molten (adj)" },
  "crust": { m: "crust = vỏ bánh mì; Trái Đất như chiếc bánh, crust là lớp vỏ mỏng ngoài cùng.", e: "Sai: the Earth's skin → Đúng: the Earth's crust. Sai: crust is the thickest layer → Đúng: crust is the thinnest layer.", u: "TOEFL Reading: oceanic crust vs continental crust; câu hỏi so sánh độ dày, mật độ. Ngoài ra: pizza crust trong đời thường.", f: "crust (n), crustal (adj), mantle (n), core (n), lithosphere (n)" },
  "mantle": { m: "mantle = áo choàng → lớp manti 'choàng' quanh lõi Trái Đất, nằm dưới vỏ.", e: "Sai: the mantle is liquid → Đúng: the mantle is mostly solid but flows slowly. Sai: mantel (bệ lò sưởi) → Đúng: mantle.", u: "TOEFL Lecture: đối lưu trong mantle đẩy các mảng kiến tạo; cũng có nghĩa bóng 'take up the mantle' (kế thừa trách nhiệm).", f: "mantle (n), crust (n), core (n), asthenosphere (n), mantel (n, dễ nhầm)" },
  "fossil record": { m: "record = hồ sơ, sổ ghi → fossil record: 'cuốn sổ' ghi lại sự sống xưa qua các hóa thạch trong đá.", e: "Sai: fossils record shows → Đúng: the fossil record shows. Sai: fossil record are incomplete → Đúng: the fossil record is incomplete.", u: "TOEFL Reading tiến hóa: 'gaps in the fossil record'; câu hỏi suy luận vì sao sinh vật thân mềm ít để lại hóa thạch.", f: "fossil (n), fossilize (v), fossilized (adj), paleontology (n), fossil record (n)" },
  "strata": { m: "strata là số nhiều của stratum; hình dung bánh nhiều lớp — mỗi lớp đá là một stratum.", e: "Sai: a strata → Đúng: a stratum. Sai: the strata is → Đúng: the strata are (học thuật).", u: "TOEFL Lecture địa chất: lớp dưới cổ hơn lớp trên (law of superposition); IELTS Writing: 'all strata of society'.", f: "stratum (n), strata (n, số nhiều), stratify (v), stratification (n), stratigraphy (n)" },
  "geyser": { m: "Từ Geysir, mạch nước nổi tiếng ở Iceland → geyser: cột nước nóng phun vọt lên định kỳ.", e: "Sai: geyser is a volcano → Đúng: a geyser is a hot spring that erupts. Sai: gayser → Đúng: geyser.", u: "TOEFL Lecture: Old Faithful ở Yellowstone; cơ chế nước ngầm bị magma đun sôi rồi phun; câu hỏi về điều kiện hình thành.", f: "geyser (n), hot spring (n), geothermal (adj), erupt (v)" },
  "delta": { m: "Chữ Hy Lạp Δ (delta) hình tam giác → bãi bồi hình tam giác ở cửa sông, như đồng bằng sông Cửu Long.", e: "Sai: the Mekong Delta river → Đúng: the Mekong Delta. Sai: delta forms where river begins → Đúng: where a river meets the sea.", u: "TOEFL Reading: sông chậm lại, trầm tích lắng tạo delta; IELTS Writing: 'the Mekong Delta is threatened by rising sea levels'.", f: "delta (n), deltaic (adj), estuary (n), alluvial (adj), sediment (n)" },
  "continental drift": { m: "drift = trôi dạt → các lục địa từ từ 'trôi' như bè trên mặt nước qua hàng triệu năm.", e: "Sai: continents drift theory → Đúng: the theory of continental drift. Sai: continental drift happen quickly → Đúng: continental drift occurs very slowly.", u: "TOEFL Lecture: Alfred Wegener và siêu lục địa Pangaea; bằng chứng hóa thạch khớp giữa châu Phi và Nam Mỹ.", f: "continent (n), continental (adj), drift (n/v), plate tectonics (n), Pangaea (n)" },
  "ice age": { m: "Hình ảnh: cả hành tinh khoác 'áo băng', sông băng phủ kín châu lục — thời kỳ băng hà.", e: "Sai: in ice age → Đúng: during the last Ice Age (cần mạo từ). Sai: the ice ages was → Đúng: the ice ages were.", u: "TOEFL Reading: voi ma mút, cầu đất Bering cho người di cư; câu hỏi nguyên nhân thay đổi khí hậu cổ.", f: "ice age (n), glacial period (n), glaciation (n), interglacial (adj/n)" },
  "celestial": { m: "Latin caelum = bầu trời → celestial: thuộc về bầu trời, các vì sao.", e: "Sai: celestial là 'thuộc thiên đàng' mọi lúc → Trong thiên văn: celestial bodies = thiên thể. Sai: celestrial → Đúng: celestial.", u: "TOEFL Lecture thiên văn: celestial bodies, celestial navigation (định hướng bằng sao) của thủy thủ xưa.", f: "celestial (adj), celestial body (n), heavenly (adj), terrestrial (adj, trái nghĩa)" },
  "comet": { m: "Hy Lạp kometes = 'có tóc dài' → sao chổi kéo theo chiếc đuôi sáng như mái tóc bay.", e: "Sai: comet and meteor are the same → Đúng: a comet orbits the Sun; a meteor burns in the atmosphere. Sai: commet → Đúng: comet.", u: "TOEFL Reading: đuôi sao chổi luôn hướng ra xa Mặt Trời do gió Mặt Trời; Halley's Comet trở lại mỗi 76 năm.", f: "comet (n), cometary (adj), asteroid (n), meteor (n), Oort cloud (n)" },
  "meteorite": { m: "meteor (sao băng) + -ite (đá) → phần đá sao băng còn sót lại rơi xuống mặt đất.", e: "Sai: meteorite burning in the sky → Đúng: a meteor burns in the sky; a meteorite reaches the ground.", u: "TOEFL Lecture: meteorite impact làm khủng long tuyệt chủng; phân biệt meteoroid, meteor, meteorite là câu hỏi quen thuộc.", f: "meteorite (n), meteor (n), meteoroid (n), meteoric (adj)" },
  "crater": { m: "Hy Lạp krater = cái bát lớn → crater: hố tròn lõm như cái bát trên Mặt Trăng hoặc đỉnh núi lửa.", e: "Sai: crater on the moon's face → Đúng: craters on the Moon's surface. Đừng nhầm crater với creator (người tạo ra).", u: "TOEFL Reading: đếm crater để ước tính tuổi bề mặt hành tinh; impact crater vs volcanic crater.", f: "crater (n), cratered (adj), impact (n), caldera (n)" },
  "nebula": { m: "Latin nebula = sương mù → tinh vân: 'đám sương' khí và bụi khổng lồ trong vũ trụ.", e: "Sai: nebulas (không chuẩn học thuật) → Đúng: nebulae. Sai: a nebula is a galaxy → Đúng: a nebula is a cloud of gas and dust.", u: "TOEFL Lecture: nebula là 'lò ấp' sinh ra sao mới; câu hỏi về vòng đời của sao.", f: "nebula (n), nebulae (n, số nhiều), nebular (adj), nebulous (adj, mơ hồ)" },
  "supernova": { m: "super (siêu) + nova (mới) → ngôi sao 'mới' bất ngờ sáng rực khi phát nổ cuối đời.", e: "Sai: supernovas (ít trang trọng) → Đúng học thuật: supernovae. Sai: the star supernova → Đúng: the star exploded as a supernova.", u: "TOEFL Reading: supernova tạo ra nguyên tố nặng như sắt, vàng; câu hỏi về giai đoạn cuối của sao khối lượng lớn.", f: "supernova (n), supernovae (n, số nhiều), nova (n), neutron star (n), black hole (n)" },
  "light-year": { m: "Bẫy: light-year đo KHOẢNG CÁCH, không đo thời gian — quãng đường ánh sáng đi trong một năm.", e: "Sai: it took light-years to finish → (sai nghĩa khoa học). Đúng: the star is 4 light-years away.", u: "TOEFL Lecture thiên văn: đơn vị khoảng cách giữa các sao; câu hỏi chi tiết dễ bẫy người tưởng là đơn vị thời gian.", f: "light-year (n), light-years (n, số nhiều), parsec (n), astronomical unit (n)" },
  "dwarf planet": { m: "dwarf = người lùn → 'hành tinh lùn', như Pluto bị 'giáng cấp' năm 2006.", e: "Sai: Pluto is a small planet → Đúng: Pluto is a dwarf planet. Sai: dwarfs planets → Đúng: dwarf planets.", u: "TOEFL Reading: ba tiêu chí của IAU để gọi là hành tinh; câu hỏi vì sao Pluto không đạt tiêu chí 'dọn sạch quỹ đạo'.", f: "dwarf planet (n), planet (n), planetoid (n), Pluto (n), Kuiper Belt (n)" },
  "gas giant": { m: "Hình ảnh: hành tinh khổng lồ toàn khí, không có mặt đất để đứng — Mộc tinh, Thổ tinh.", e: "Sai: giant gas planet → Đúng: gas giant. Sai: Jupiter has a rocky surface → Đúng: Jupiter has no solid surface.", u: "TOEFL Lecture: gas giants vs terrestrial planets; câu hỏi so sánh thành phần, kích thước, số vệ tinh.", f: "gas giant (n), ice giant (n), terrestrial planet (n), Jovian (adj)" },
  "asteroid belt": { m: "belt = thắt lưng → vành đai đá vụn 'thắt' quanh Mặt Trời, nằm giữa Sao Hỏa và Sao Mộc.", e: "Sai: asteroids belt → Đúng: the asteroid belt. Sai: between Earth and Mars → Đúng: between Mars and Jupiter.", u: "TOEFL Reading: vì sao không hình thành hành tinh ở đây (lực hấp dẫn Sao Mộc); câu hỏi suy luận phổ biến.", f: "asteroid (n), asteroid belt (n), Kuiper Belt (n), planetesimal (n)" },
  "gravitational pull": { m: "pull = kéo → lực 'kéo' vô hình của trọng lực, như Mặt Trăng kéo nước biển tạo thủy triều.", e: "Sai: gravity pull → Đúng: gravitational pull. Sai: the pull of gravitation of → Đúng: the gravitational pull of the Moon.", u: "TOEFL Lecture: thủy triều, quỹ đạo vệ tinh, hố đen; IELTS dùng bóng: 'the gravitational pull of big cities'.", f: "gravity (n), gravitation (n), gravitational (adj), gravitate (v)" },
  "eclipse": { m: "Hy Lạp ekleipsis = biến mất → Mặt Trời 'biến mất' khi Mặt Trăng che khuất.", e: "Sai: eclipse of sun → Đúng: a solar eclipse / an eclipse of the Sun. Sai: eclipe → Đúng: eclipse.", u: "TOEFL Reading: solar vs lunar eclipse, vị trí ba thiên thể; nghĩa bóng động từ: 'His success eclipsed his rivals'.", f: "eclipse (n/v), solar eclipse (n), lunar eclipse (n), eclipsed (adj)" },
  "equinox": { m: "equi (bằng) + nox (đêm) → ngày và đêm dài bằng nhau, khoảng 20/3 và 22/9.", e: "Sai: equinox là ngày dài nhất → Đúng: đó là solstice (chí). Sai: equinoxs → Đúng: equinoxes.", u: "TOEFL Lecture: công trình cổ như Stonehenge căn theo equinox, solstice; câu hỏi phân biệt hai khái niệm.", f: "equinox (n), equinoctial (adj), solstice (n), vernal equinox (n), autumnal equinox (n)" },
  "neolithic": { m: "neo (mới) + lith (đá) → thời đồ đá mới, khi con người bắt đầu trồng trọt, định cư.", e: "Sai: neolitic → Đúng: Neolithic (viết hoa khi chỉ thời kỳ). Sai: the Neolithic people hunted only → Đúng: they began farming.", u: "TOEFL Reading: Neolithic Revolution, sự chuyển từ săn bắt sang nông nghiệp; câu hỏi nguyên nhân và hệ quả.", f: "Neolithic (adj/n), Paleolithic (adj), Mesolithic (adj), lithic (adj), monolith (n)" },
  "archaeologist": { m: "archae- (cổ xưa) + -logist (nhà nghiên cứu) → người nghiên cứu đồ vật cổ xưa đào được.", e: "Sai: archaelogist → Đúng: archaeologist (Mỹ: archeologist). Đừng nhầm với paleontologist (nhà cổ sinh vật học, nghiên cứu hóa thạch).", u: "TOEFL Lecture: 'Archaeologists unearthed pottery fragments'; câu hỏi về phương pháp định tuổi như carbon dating.", f: "archaeology (n), archaeologist (n), archaeological (adj), excavate (v)" },
  "excavation": { m: "ex- (ra) + cavus (hố) → đào hố lấy ra: cuộc khai quật tìm di tích.", e: "Sai: the excavation of artifacts at → Đúng: the excavation of the site uncovered artifacts. Sai: excavate out → Đúng: excavate.", u: "TOEFL Reading khảo cổ: excavation site, carry out an excavation; cũng dùng trong xây dựng (đào móng).", f: "excavate (v), excavation (n), excavator (n, máy xúc), dig (n/v)" },
  "nomadic": { m: "nomad = người du mục cưỡi ngựa, dắt đàn gia súc theo cỏ nước, không ở cố định.", e: "Sai: a nomadic (dùng như danh từ) → Đúng: a nomad / a nomadic tribe. Sai: nomadic people lives → Đúng: nomadic people live.", u: "TOEFL Lecture: Mông Cổ, Bedouin; IELTS Speaking về du lịch: 'digital nomads' làm việc từ xa khi đi khắp nơi.", f: "nomad (n), nomadic (adj), nomadism (n), digital nomad (n), sedentary (adj, trái nghĩa)" },
  "hunter-gatherer": { m: "hunter (người săn) + gatherer (người hái lượm) → người xưa sống nhờ săn thú và hái quả.", e: "Sai: hunter and gatherer society (chấp nhận) nhưng sai: hunters-gatherers → Đúng: hunter-gatherers.", u: "TOEFL Reading: so sánh hunter-gatherer với xã hội nông nghiệp; câu hỏi về chế độ ăn, quy mô nhóm, sự di cư.", f: "hunter-gatherer (n), hunt (v), gather (v), forager (n), foraging society (n)" },
  "domestication": { m: "domus = nhà (như 'domestic') → domestication: đưa thú hoang, cây dại 'về nhà' nuôi trồng.", e: "Sai: the domestication of dogs by human → Đúng: the domestication of dogs by humans. Sai: domesticize → Đúng: domesticate.", u: "TOEFL Lecture: thuần hóa lúa mì, chó, ngựa; câu hỏi về thay đổi gen và tác động đến định cư.", f: "domesticate (v), domestication (n), domesticated (adj), domestic (adj), tame (v/adj)" },
  "civilisation": { m: "civis = công dân (như 'civil', 'city') → civilisation: xã hội có đô thị, chữ viết, luật lệ.", e: "Sai: Egyptian civilisation were → Đúng: Egyptian civilisation was. Lưu ý: civilisation (Anh) = civilization (Mỹ), dùng nhất quán.", u: "TOEFL Reading lịch sử: ancient civilisations, rise and fall of civilisations; IELTS Writing về văn hóa, tiến bộ nhân loại.", f: "civilisation/civilization (n), civilised (adj), civilise (v), civil (adj), civic (adj)" },
  "dynasty": { m: "Hy Lạp dynastes = người cầm quyền → dynasty: chuỗi vua cùng một dòng họ, như nhà Lý, nhà Trần.", e: "Sai: during Tang dynasty → Đúng: during the Tang Dynasty. Sai: dynasties is → Đúng: dynasties are.", u: "TOEFL Lecture lịch sử Trung Hoa, Ai Cập; nghĩa mở rộng: 'a political dynasty' (gia tộc nắm quyền nhiều đời).", f: "dynasty (n), dynastic (adj), dynast (n), reign (n), monarchy (n)" },
  "colonial": { m: "colony = thuộc địa → colonial: thuộc về thời kỳ một nước đi chiếm và cai trị nước khác.", e: "Sai: colonist period → Đúng: the colonial period. Sai: colonial là danh từ 'người thực dân' → Đúng: colonist/colonizer.", u: "TOEFL Reading: colonial America, kiến trúc thuộc địa; IELTS Writing về di sản lịch sử: 'colonial-era buildings'.", f: "colony (n), colonial (adj), colonist (n), colonize (v), colonialism (n)" },
  "renaissance": { m: "re (lại) + naissance (sinh ra, tiếng Pháp) → 'tái sinh' văn hóa cổ điển ở châu Âu thế kỷ 14–16.", e: "Sai: renaissence → Đúng: Renaissance (viết hoa khi chỉ thời kỳ). Sai: in Renaissance → Đúng: during the Renaissance.", u: "TOEFL Lecture nghệ thuật: Leonardo, Michelangelo, phối cảnh; nghĩa thường: 'a renaissance of the city centre' (sự hồi sinh).", f: "Renaissance (n), renaissance (n, sự hồi sinh), revival (n), rebirth (n)" },
  "industrial revolution": { m: "Hình ảnh: máy hơi nước, nhà máy dệt, khói nhà xưởng ở Anh thế kỷ 18 — cuộc cách mạng sản xuất.", e: "Sai: in Industrial Revolution → Đúng: during the Industrial Revolution (cần 'the', viết hoa). Sai: industry revolution → Đúng: industrial revolution.", u: "TOEFL Reading: đô thị hóa, lao động trẻ em, đường sắt; IELTS Writing: so sánh với cuộc cách mạng công nghệ hiện nay.", f: "industry (n), industrial (adj), industrialize (v), industrialization (n), revolution (n)" },
  "textile": { m: "Latin texere = dệt (cùng gốc 'text', 'texture') → textile: vải vóc dệt ra.", e: "Sai: textile industry products is → Đúng: textiles are. Sai: textile là 'quần áo may sẵn' → chính xác là vải, hàng dệt.", u: "TOEFL Lecture: ngành dệt đi đầu Cách mạng Công nghiệp; IELTS Writing: textile waste, ngành dệt may xuất khẩu Việt Nam.", f: "textile (n/adj), texture (n), fabric (n), weave (v), garment (n)" },
  "guild": { m: "Hình dung hội thợ rèn thời Trung cổ cùng đặt giá, đào tạo học việc — đó là guild.", e: "Sai: gild (mạ vàng) → Đúng: guild (phường hội). Sai: a guild of craftsman → Đúng: a guild of craftsmen.", u: "TOEFL Reading lịch sử kinh tế: guild kiểm soát chất lượng, hệ thống apprentice-journeyman-master; câu hỏi chức năng của guild.", f: "guild (n), guildhall (n), apprentice (n), craftsman (n), union (n, tương tự hiện đại)" },
  "trade route": { m: "Hình ảnh: đoàn lạc đà chở lụa trên Con đường Tơ lụa — một trade route điển hình.", e: "Sai: trading road → Đúng: trade route. Sai: along trade route → Đúng: along trade routes / along the trade route.", u: "TOEFL Lecture: Silk Road, trao đổi hàng hóa và văn hóa, lan truyền dịch bệnh; câu hỏi tác động kinh tế.", f: "trade (n/v), trade route (n), trade network (n), caravan (n), merchant (n)" },
  "feudal": { m: "fee (đất được ban) → feudal: chế độ vua ban đất cho lãnh chúa, nông dân làm thuê trên đất đó.", e: "Sai: feudalism society → Đúng: feudal society. Sai: feudal là danh từ → Đúng: feudalism (chế độ phong kiến).", u: "TOEFL Reading: feudal lords, vassals, serfs; IELTS Writing về lịch sử Việt Nam: 'the feudal era'.", f: "feudal (adj), feudalism (n), fief (n), lord (n), vassal (n)" },
  "peasant": { m: "Gốc Pháp 'païsant' = người nhà quê (pays = vùng quê) → peasant: nông dân nghèo thời xưa.", e: "Sai: peasent → Đúng: peasant. Lưu ý: dùng peasant cho người hiện đại có thể xúc phạm; dùng farmer.", u: "TOEFL Lecture: đời sống peasants dưới chế độ phong kiến, khởi nghĩa nông dân; câu hỏi về thuế và nghĩa vụ.", f: "peasant (n), peasantry (n), serf (n), farmer (n), rural (adj)" },
  "printing press": { m: "press = ép → máy in Gutenberg ép giấy lên khuôn chữ; phát minh lan truyền tri thức.", e: "Sai: print machine of Gutenberg → Đúng: Gutenberg's printing press. Sai: the press printing → Đúng: the printing press.", u: "TOEFL Reading: tác động lên tôn giáo, tỷ lệ biết chữ, khoa học; IELTS Writing so sánh với Internet.", f: "print (v), printer (n), printing (n), press (n), movable type (n)" },
  "fresco": { m: "Ý fresco = tươi → vẽ lên vữa còn 'tươi', ướt; màu thấm vào tường, bền hàng thế kỷ.", e: "Sai: a fresco painted on canvas → Đúng: a fresco painted on wet plaster. Số nhiều: frescoes hoặc frescos.", u: "TOEFL Lecture nghệ thuật: trần nhà nguyện Sistine; câu hỏi phân biệt fresco (vữa ướt) với secco (vữa khô).", f: "fresco (n), frescoes (n, số nhiều), mural (n), plaster (n)" },
  "mural": { m: "Latin murus = bức tường → mural: tranh vẽ thẳng lên tường.", e: "Sai: a mural painting on canvas → Đúng: a mural is painted on a wall. Sai: murals painting → Đúng: mural painting.", u: "TOEFL Reading: tranh tường Mexico của Diego Rivera; IELTS Speaking về nghệ thuật đường phố: 'street murals brighten the area'.", f: "mural (n/adj), muralist (n), fresco (n), graffiti (n)" },
  "pigment": { m: "Latin pingere = vẽ (cùng gốc 'paint', 'picture') → pigment: chất tạo màu trong sơn, da, lá cây.", e: "Sai: pigments of color → Đúng: pigments (đã bao hàm màu). Sai: pigmant → Đúng: pigment.", u: "TOEFL Lecture: họa sĩ cổ nghiền khoáng chất làm pigment; sinh học: chlorophyll là pigment xanh trong lá.", f: "pigment (n), pigmentation (n), pigmented (adj), dye (n), chlorophyll (n)" },
  "still life": { m: "still = tĩnh, đứng yên → vẽ vật 'đứng yên': bình hoa, trái cây, ly rượu.", e: "Sai: still lives → Đúng (hội họa): still lifes. Sai: a still life of a woman → vẽ người là portrait.", u: "TOEFL Reading lịch sử hội họa: still life Hà Lan thế kỷ 17 mang biểu tượng phù du (vanitas); câu hỏi về ý nghĩa ẩn dụ.", f: "still life (n), still lifes (n, số nhiều), portrait (n), landscape (n)" },
  "impressionism": { m: "Từ bức 'Impression, Sunrise' của Monet → vẽ 'ấn tượng' thoáng qua về ánh sáng, nét cọ nhanh.", e: "Sai: impressionnism → Đúng: Impressionism. Sai: impressionist movement are → Đúng: the Impressionist movement was.", u: "TOEFL Lecture: vẽ ngoài trời (en plein air), bị giới học viện chê; câu hỏi về kỹ thuật và phản ứng của công chúng.", f: "Impressionism (n), Impressionist (n/adj), impression (n), Post-Impressionism (n)" },
  "abstract art": { m: "abstract = trừu tượng → tranh không vẽ vật thật, chỉ màu, khối, đường nét gợi cảm xúc.", e: "Sai: abstraction art → Đúng: abstract art. Sai: abstract arts is → Đúng: abstract art is (không đếm được).", u: "TOEFL Reading: Kandinsky, Pollock; IELTS Speaking: 'I don't really understand abstract art, but I like the colours'.", f: "abstract (adj), abstraction (n), abstract art (n), figurative art (n, trái nghĩa)" },
  "sculptor": { m: "sculpt (đẽo, tạc) + -or (người) → người tạc tượng; sculpture là tác phẩm.", e: "Sai: he is a famous sculpture → Đúng: he is a famous sculptor. Sculpture là bức tượng, sculptor là người tạc.", u: "TOEFL Lecture: Rodin, kỹ thuật đúc đồng, tạc đá; câu hỏi phân biệt chất liệu và kỹ thuật.", f: "sculpt (v), sculptor (n), sculpture (n), sculptural (adj)" },
  "ceramic": { m: "Hy Lạp keramos = đất sét nung → ceramic: đồ gốm, sứ nung trong lò.", e: "Sai: a ceramics bowl → Đúng: a ceramic bowl. Khi nói môn/nghề làm gốm thì dùng ceramics: She studies ceramics.", u: "TOEFL Reading khảo cổ: mảnh gốm giúp định niên đại; IELTS Speaking về đồ thủ công: Bát Tràng ceramic village.", f: "ceramic (adj/n), ceramics (n, nghề gốm), pottery (n), porcelain (n), kiln (n)" },
  "mosaic": { m: "Hình ảnh: ghép hàng nghìn viên đá, kính màu nhỏ thành bức tranh lớn trên sàn, tường.", e: "Sai: mozaic → Đúng: mosaic. Sai: a mosaic made by tiles → Đúng: a mosaic made of tiles.", u: "TOEFL Lecture: tranh khảm La Mã, Byzantine; IELTS Writing dùng bóng: 'a cultural mosaic' (xã hội đa văn hóa).", f: "mosaic (n/adj), tessera (n, viên khảm), tile (n), inlay (n/v)" },
  "gothic": { m: "Hình ảnh: nhà thờ Đức Bà Paris — mái nhọn vút cao, cửa sổ kính màu, vòm nhọn.", e: "Sai: gothic style church (viết thường) → Đúng: a Gothic cathedral (viết hoa khi chỉ phong cách kiến trúc).", u: "TOEFL Reading kiến trúc: pointed arches, flying buttresses giúp tường mỏng và cửa sổ lớn; câu hỏi chức năng của kết cấu.", f: "Gothic (adj/n), Goth (n), Neo-Gothic (adj), Romanesque (adj, phong cách trước đó)" },
  "dome": { m: "Hình dung nửa quả cầu úp trên mái — như mái vòm Điện Capitol hay đền Pantheon.", e: "Sai: the dome roof of → Đúng: the domed roof of / the dome of. Sai: doom (diệt vong) → Đúng: dome.", u: "TOEFL Lecture kiến trúc: Pantheon La Mã, Brunelleschi ở Florence; câu hỏi về kỹ thuật chịu lực.", f: "dome (n), domed (adj), vault (n), cupola (n), arch (n)" },
  "motif": { m: "Từ tiếng Pháp, đọc /moʊˈtiːf/ → mô-típ: họa tiết, chủ đề lặp đi lặp lại.", e: "Sai: motive (động cơ) → Đúng: motif (họa tiết). Sai: a recurring motifs → Đúng: a recurring motif.", u: "TOEFL Reading nghệ thuật, văn học: 'a floral motif', 'a recurring motif in her novels'; câu hỏi về ý nghĩa biểu tượng.", f: "motif (n), motifs (n, số nhiều), pattern (n), theme (n), motive (n, dễ nhầm)" },
  "composer": { m: "compose (sáng tác, ghép lại) + -er → người ghép các nốt nhạc thành tác phẩm.", e: "Sai: Beethoven is a famous musician composer → Đúng: Beethoven was a famous composer. Sai: composer a song → Đúng: compose a song.", u: "TOEFL Lecture âm nhạc: Bach, Mozart, Beethoven; IELTS Speaking: 'Who is your favourite composer?'", f: "compose (v), composer (n), composition (n), conductor (n), musician (n)" },
  "symphony": { m: "sym (cùng) + phone (âm thanh) → nhiều nhạc cụ 'cùng vang lên' thành bản giao hưởng.", e: "Sai: symphony là 'dàn nhạc' → dàn nhạc là symphony orchestra. Sai: simphony → Đúng: symphony.", u: "TOEFL Lecture: cấu trúc bốn chương (movements), Beethoven's Ninth Symphony; IELTS Speaking về âm nhạc cổ điển.", f: "symphony (n), symphonic (adj), symphony orchestra (n), concerto (n), sonata (n)" },
  "lean against": { m: "lean = nghiêng → nghiêng người hoặc đồ vật tựa vào tường, cột cho đỡ.", e: "Sai: He is leaning on the wall (chấp nhận) nhưng sai: leaning to the wall → Đúng: leaning against the wall.", u: "TOEIC Part 1: 'A man is leaning against a railing.' Bẫy: đồ vật dựa tường thường mô tả bằng 'is propped against'.", f: "lean (v), leaning (adj), lean on (phr v), rest against (phr v), be propped against" },
  "lean over": { m: "over = vượt qua phía trên → nghiêng người vươn qua bàn, lan can.", e: "Sai: She is leaning over to the desk → Đúng: She is leaning over the desk. Không cần 'to'.", u: "TOEIC Part 1: 'A woman is leaning over a counter.' Phân biệt với bend over (cúi gập người xuống).", f: "lean over (phr v), lean forward (phr v), bend over (phr v), lean (v)" },
  "kneel down": { m: "knee = đầu gối → kneel: hạ đầu gối chạm đất.", e: "Sai: He is kneeing down → Đúng: He is kneeling down. Quá khứ: knelt hoặc kneeled.", u: "TOEIC Part 1: 'A worker is kneeling down to fix a tire.' Bẫy: crouching (ngồi xổm) khác kneeling (quỳ gối).", f: "kneel (v), knelt/kneeled (v-ed), knee (n), crouch (v), squat (v)" },
  "crouch": { m: "Hình ảnh: hạ thấp người, gập gối nhưng đầu gối không chạm đất — như thủ môn chờ bóng.", e: "Sai: He is crouching on his knees → Đúng: He is kneeling on his knees / He is crouching down.", u: "TOEIC Part 1: 'A man is crouching beside a box.' Hay đi với down, beside, next to.", f: "crouch (v/n), crouching (adj), squat (v), kneel (v), stoop (v)" },
  "bend over": { m: "bend = uốn cong → cong lưng gập người xuống, như nhặt đồ dưới đất.", e: "Sai: She is bending down over (thừa) → Đúng: She is bending over to pick up a box.", u: "TOEIC Part 1: 'A man is bending over a flower bed.' Hay xuất hiện cùng picking up, tying a shoe.", f: "bend (v), bent (v-ed), bend over (phr v), bend down (phr v), stoop (v)" },
  "reach for": { m: "reach = với tới → duỗi tay ra để lấy món đồ ở xa hoặc trên cao.", e: "Sai: She is reaching the shelf for → Đúng: She is reaching for an item on the shelf.", u: "TOEIC Part 1: 'A woman is reaching for a file.' Bẫy: reaching for (đang với) khác picking up (đã cầm).", f: "reach (v/n), reach for (phr v), reach out (phr v), within reach (phrase)" },
  "point at": { m: "point = chỉ, đầu nhọn → giơ ngón tay hướng thẳng vào vật.", e: "Sai: He is pointing the screen → Đúng: He is pointing at the screen (hoặc pointing to).", u: "TOEIC Part 1: 'A presenter is pointing at a chart.' Hay gặp trong ảnh thuyết trình, chỉ đường.", f: "point (v/n), point at/to (phr v), point out (phr v), pointer (n)" },
  "glance at": { m: "glance = cái nhìn chớp nhoáng → liếc qua, không nhìn chăm chú.", e: "Sai: She glanced the clock → Đúng: She glanced at the clock. Đừng nhầm glance (liếc) với stare (nhìn chằm chằm).", u: "TOEIC Part 1/3: 'He's glancing at his watch.' Part 7: 'at a glance' = nhìn qua là thấy ngay.", f: "glance (v/n), at a glance (phrase), glimpse (n/v), stare (v)" },
  "be seated": { m: "seat (chỗ ngồi) → be seated: trạng thái 'đã được xếp chỗ', đang ngồi.", e: "Sai: They are sitting down at the table (đang ngồi xuống) → Đúng mô tả trạng thái: They are seated at the table.", u: "TOEIC Part 1: 'Some people are seated on a bench.' Lời mời lịch sự ở hội nghị: 'Please be seated.'", f: "seat (n/v), seated (adj), seating (n), sit (v), be seated (phrase)" },
  "face each other": { m: "face = mặt → hai người 'quay mặt' về phía nhau.", e: "Sai: They are facing to each other → Đúng: They are facing each other (không dùng 'to').", u: "TOEIC Part 1: 'Two people are facing each other across a desk.' Bẫy: facing the same direction (cùng hướng).", f: "face (v/n), facing (adj), opposite (prep/adj), face to face (phrase)" },
  "shake hands": { m: "Hình ảnh: hai bàn tay nắm lấy nhau, lắc lên xuống — cử chỉ chào hỏi, thỏa thuận.", e: "Sai: They are shaking hand → Đúng: They are shaking hands. Sai: shake hands to him → Đúng: shake hands with him.", u: "TOEIC Part 1: 'The men are shaking hands.' Part 3/4: chốt hợp đồng, gặp đối tác mới.", f: "shake hands (phrase), handshake (n), shake (v), greet (v)" },
  "hand out": { m: "hand (đưa bằng tay) + out (ra ngoài) → đưa tận tay cho từng người.", e: "Sai: hand out to them the papers → Đúng: hand the papers out to them / hand out the papers. Danh từ: handout.", u: "TOEIC Part 1: 'A woman is handing out documents.' Part 4: 'Please review the handout before the meeting.'", f: "hand out (phr v), handout (n), distribute (v), pass out (phr v), give out (phr v)" },
  "water the plants": { m: "water dùng làm động từ: 'cho cây uống nước' — tưới cây.", e: "Sai: She is watering for the plants → Đúng: She is watering the plants. Sai: give water the plants.", u: "TOEIC Part 1: 'A man is watering some plants with a hose.' Hay đi với hose, watering can.", f: "water (v/n), watering can (n), hose (n), irrigate (v)" },
  "mop the floor": { m: "mop = cây lau nhà → dùng làm động từ: 'cầm mop chà sàn'.", e: "Sai: He is cleaning the floor by mop (vụng) → Đúng: He is mopping the floor. Phân biệt sweep (quét) với mop (lau).", u: "TOEIC Part 1: 'A worker is mopping the floor.' Bẫy: sweeping the floor dùng broom (chổi).", f: "mop (n/v), mopping (n), sweep (v), broom (n), scrub (v)" },
  "rake leaves": { m: "rake = cái cào → dùng làm động từ: cào gom lá rụng thành đống.", e: "Sai: He is raking the leafs → Đúng: He is raking leaves (số nhiều của leaf là leaves).", u: "TOEIC Part 1: 'Someone is raking leaves in a yard.' Đi kèm cảnh gardening, landscaping.", f: "rake (n/v), leaf (n), leaves (n, số nhiều), sweep (v), gather (v)" },
  "trim the hedge": { m: "trim = cắt gọn; hedge = hàng rào cây xanh → tỉa cho hàng rào cây gọn gàng.", e: "Sai: He is cutting the fence → Đúng: He is trimming the hedge (fence là hàng rào gỗ, sắt).", u: "TOEIC Part 1: 'A gardener is trimming some bushes/hedges.' Ngữ cảnh landscaping, bảo trì khuôn viên.", f: "trim (v/n), trimmer (n), hedge (n), prune (v), bush (n)" },
  "sip": { m: "Âm 'síp' như tiếng nhấp môi khẽ → uống từng ngụm nhỏ.", e: "Sai: She is sipping on coffee a lot → Đúng: She is sipping her coffee. Sip (ngụm nhỏ) khác gulp (uống ừng ực).", u: "TOEIC Part 1: 'A man is sipping from a cup.' Cũng là danh từ: 'take a sip of water'.", f: "sip (v/n), sipped (v-ed), sipping (v-ing), gulp (v), drink (v)" },
  "stroll": { m: "Hình ảnh: tản bộ thong thả trong công viên, không vội — stroll.", e: "Sai: They are strolling quickly → mâu thuẫn. Đúng: They are strolling along the beach. Sai: go stroll → Đúng: go for a stroll.", u: "TOEIC Part 1: 'People are strolling along a path.' IELTS Speaking: 'I like to stroll around the lake after dinner.'", f: "stroll (v/n), stroller (n, xe đẩy em bé), wander (v), walk (v)" },
  "push a cart": { m: "Hình ảnh: đẩy xe đẩy trong siêu thị hoặc xe chở hàng trong kho.", e: "Sai: She is pulling a cart (khi đang đẩy) → Đúng: She is pushing a cart. Sai: push the trolley car.", u: "TOEIC Part 1: 'A man is pushing a cart down an aisle.' Bẫy: pushing vs pulling, cart vs wheelbarrow.", f: "push (v), cart (n), shopping cart (n), trolley (n, Anh-Anh), wheelbarrow (n)" },
  "load a vehicle": { m: "load = chất tải → chất hàng lên xe; ngược lại unload = dỡ hàng.", e: "Sai: loading a truck with box → Đúng: loading a truck with boxes / loading boxes onto a truck.", u: "TOEIC Part 1: 'Workers are loading a vehicle.' Bẫy: loading (đang chất) khác unloading (đang dỡ).", f: "load (v/n), loading (n), unload (v), cargo (n), loading dock (n)" },
  "examine a document": { m: "examine = xem xét kỹ (như 'exam' kiểm tra) → cầm tài liệu đọc kỹ từng chi tiết.", e: "Sai: He is examining at a document → Đúng: He is examining a document (không có 'at').", u: "TOEIC Part 1: 'A woman is examining a document.' Từ đồng nghĩa hay dùng thay: reviewing, studying, looking over.", f: "examine (v), examination (n), review (v), look over (phr v), inspect (v)" },
  "take notes": { m: "take (lấy) + notes (ghi chú) → 'lấy' ý chính ghi lại trên giấy.", e: "Sai: She is writing notes of the lecture (vụng) → Đúng: She is taking notes during the lecture. Sai: take a note (khác nghĩa: ghi nhớ).", u: "TOEIC Part 1: 'Some people are taking notes.' IELTS Speaking: 'I usually take notes on my laptop in class.'", f: "take notes (phrase), note-taking (n), notebook (n), jot down (phr v)" },
  "address an audience": { m: "address (nói với, gửi tới) → đứng trước đám đông và nói với họ.", e: "Sai: address to the audience → Đúng: address the audience (ngoại động từ, không cần 'to').", u: "TOEIC Part 1: 'A man is addressing an audience.' Part 4: 'The CEO will address shareholders at the meeting.'", f: "address (v/n), keynote address (n), speak to (phr v), audience (n)" },
  "try on": { m: "try (thử) + on (mặc lên người) → mặc thử quần áo, giày trước khi mua.", e: "Sai: try on it → Đúng: try it on (đại từ nằm giữa). Sai: try the shoes (thiếu on) khi nói mặc thử.", u: "TOEIC Part 1: 'A woman is trying on a jacket.' Part 3: hội thoại cửa hàng, fitting room.", f: "try on (phr v), fitting room (n), try out (phr v, dùng thử)" },
  "plug in": { m: "plug = phích cắm → cắm phích vào ổ điện; ngược lại unplug.", e: "Sai: plug in it → Đúng: plug it in. Sai: plug the laptop to → Đúng: plug the laptop into the outlet.", u: "TOEIC Part 1: 'A man is plugging in a cord.' Part 3: sự cố thiết bị, 'Is the printer plugged in?'", f: "plug (n/v), plug in (phr v), unplug (v), outlet (n), socket (n)" },
  "be stacked": { m: "stack = chồng → đồ vật xếp chồng thẳng lên nhau, gọn gàng.", e: "Sai: Chairs are stacking → Đúng: Chairs are stacked (bị động, trạng thái). Stacked thường gọn, piled up thường lộn xộn.", u: "TOEIC Part 1: 'Boxes are stacked on a shelf.' Bẫy: 'are being stacked' (đang có người xếp) đòi hỏi ảnh có người.", f: "stack (n/v), stacked (adj), pile (n/v), heap (n)" },
  "be piled up": { m: "pile = đống → đồ vật bị chất thành đống, thường không ngay ngắn.", e: "Sai: Papers are pile up on the desk → Đúng: Papers are piled up on the desk (quá khứ phân từ, trạng thái).", u: "TOEIC Part 1: 'Some logs are piled up near a house.' Part 7 nghĩa bóng: work is piling up (dồn ứ).", f: "pile (n/v), pile up (phr v), piled (adj), stack (v), heap (n)" },
  "be lined up": { m: "line = hàng → đồ vật hoặc người đứng thành một hàng thẳng.", e: "Sai: Cars are line up → Đúng: Cars are lined up. Sai: lined up in line (thừa).", u: "TOEIC Part 1: 'Bicycles are lined up along the sidewalk.' Part 3: 'People lined up to buy tickets'.", f: "line up (phr v), lineup (n), queue (n/v), in a row (phrase), arranged (adj)" },
  "be propped against": { m: "prop = cây chống → vật được dựng nghiêng tựa vào tường, cột.", e: "Sai: A ladder is leaning to the wall → Đúng: A ladder is propped against the wall (hoặc leaning against).", u: "TOEIC Part 1: 'A bicycle is propped against a fence.' Từ đắt điểm cho đồ vật; người dùng leaning against.", f: "prop (n/v), prop up (phr v), propped (adj), lean against (phr v), rest against" },
  "be mounted": { m: "mount = gắn lên, leo lên → vật được gắn cố định lên tường, trần.", e: "Sai: A TV is hanged on the wall → Đúng: A TV is mounted on the wall. Hanged dùng cho người (treo cổ).", u: "TOEIC Part 1: 'A clock is mounted on the wall.' Ngữ cảnh văn phòng, sảnh, tủ lắp đặt.", f: "mount (v/n), mounted (adj), wall-mounted (adj), install (v), fixed (adj)" },
  "be hanging": { m: "hang = treo → vật đang lơ lửng treo trên móc, trần nhà, tường.", e: "Sai: Pictures are hanged on the wall → Đúng: Pictures are hanging / are hung on the wall.", u: "TOEIC Part 1: 'Lamps are hanging from the ceiling.' Bẫy: 'are being hung' cần người đang treo.", f: "hang (v), hung (v-ed), hanging (adj/n), hanger (n), suspend (v)" },
  "be on display": { m: "display = trưng bày → hàng hóa đặt ở chỗ dễ thấy cho mọi người xem.", e: "Sai: Items are displaying in the window → Đúng: Items are on display / are displayed in the window.", u: "TOEIC Part 1: 'Merchandise is on display.' Part 7: 'Artwork will be on display until May 30.'", f: "display (n/v), displayed (adj), exhibit (v/n), showcase (n/v), on show (phrase)" },
  "be stocked with": { m: "stock = hàng dự trữ → kệ được 'nạp đầy' hàng hóa.", e: "Sai: Shelves are stocked by goods → Đúng: Shelves are stocked with goods (dùng 'with').", u: "TOEIC Part 1: 'The shelves are stocked with merchandise.' Part 7: 'a well-stocked kitchen'.", f: "stock (n/v), stocked (adj), well-stocked (adj), restock (v), in stock (phrase)" },
  "be scattered": { m: "scatter = rải, vãi → đồ vật nằm tản mát lung tung, không theo hàng lối.", e: "Sai: Papers are scattering on the floor → Đúng: Papers are scattered on the floor (trạng thái).", u: "TOEIC Part 1: 'Leaves are scattered on the ground.' Đối lập với 'are stacked neatly'.", f: "scatter (v), scattered (adj), spread out (phr v), strewn (adj), disperse (v)" },
  "be reflected": { m: "reflect = phản chiếu → hình ảnh hiện lên trên mặt nước, gương, kính.", e: "Sai: Trees are reflecting in the water → Đúng: Trees are reflected in the water (bị động).", u: "TOEIC Part 1: 'Some buildings are reflected in the water.' Part 7 nghĩa bóng: 'reflected in sales figures'.", f: "reflect (v), reflection (n), reflective (adj), mirror (n/v)" },
  "cast a shadow": { m: "cast = ném, phóng → vật 'ném' bóng xuống đất khi bị nắng chiếu.", e: "Sai: The tree makes a shade on → Đúng: The tree casts a shadow on the ground. Quá khứ: cast (bất quy tắc).", u: "TOEIC Part 1: 'A tree is casting a shadow on the path.' Nghĩa bóng: 'cast a shadow over the event' (phủ bóng u ám).", f: "cast (v), shadow (n), shade (n), shadowy (adj), overshadow (v)" },
  "be docked": { m: "dock = bến tàu → thuyền đã cập bến, neo đậu tại cầu cảng.", e: "Sai: The boats are docking (đang cập) khi ảnh thuyền đứng yên → Đúng: The boats are docked at the pier.", u: "TOEIC Part 1: 'Several boats are docked in a harbor.' Hay đi với pier, harbor, marina.", f: "dock (n/v), docked (adj), moor (v), anchor (v), harbor (n)" },
  "be under construction": { m: "under (đang trong quá trình) + construction (xây dựng) → công trình chưa hoàn thiện.", e: "Sai: The building is under constructing → Đúng: The building is under construction.", u: "TOEIC Part 1: 'A building is under construction.' Part 4: thông báo đường, sảnh đang thi công, đi lối khác.", f: "construct (v), construction (n), under renovation (phrase), under way (phrase)" },
  "be closed off": { m: "close off = đóng kín lại → khu vực bị rào chắn, cấm đi vào.", e: "Sai: The road is closed off for traffic → Đúng: The road is closed off to traffic.", u: "TOEIC Part 1: 'An area has been closed off.' Part 4: thông báo sửa chữa, sự kiện chặn đường.", f: "close off (phr v), cordon off (phr v), block off (phr v), closure (n)" },
  "be unoccupied": { m: "un- (không) + occupied (có người dùng) → ghế, phòng đang trống người.", e: "Sai: The chairs are not occupy → Đúng: The chairs are unoccupied. Đồng nghĩa: empty, vacant.", u: "TOEIC Part 1: 'Some seats are unoccupied.' Bẫy phổ biến: ảnh không có người thì đáp án dạng này dễ đúng.", f: "occupy (v), occupied (adj), unoccupied (adj), vacant (adj), empty (adj)" },
  "awning": { m: "Hình ảnh: tấm bạt sọc che nắng trước cửa quán cà phê — đó là awning.", e: "Sai: The umbrella over the shop window → Đúng: The awning over the shop window. Sai: owning → Đúng: awning.", u: "TOEIC Part 1: 'An awning is shading the storefront.' Hay đi cùng outdoor seating, café, market stall.", f: "awning (n), canopy (n), shade (n), parasol (n)" },
  "railing": { m: "rail = thanh ngang → railing: dãy thanh chắn dọc cầu thang, ban công để vịn.", e: "Sai: He is holding the rail of the stairs (vụng) → Đúng: He is holding onto the railing.", u: "TOEIC Part 1: 'A man is leaning on a railing.' Hay xuất hiện ở ảnh cầu, ban công, bến tàu.", f: "rail (n), railing (n), handrail (n), banister (n), guardrail (n)" },
  "wheelbarrow": { m: "wheel (bánh xe) + barrow (xe chở) → xe chở có một bánh, đẩy bằng hai tay cầm.", e: "Sai: He is pushing a cart of one wheel → Đúng: He is pushing a wheelbarrow. Viết liền một từ.", u: "TOEIC Part 1: 'A worker is pushing a wheelbarrow.' Ngữ cảnh công trường, làm vườn.", f: "wheelbarrow (n), cart (n), barrow (n), wheel (n)" },
  "crate": { m: "Hình ảnh: thùng gỗ có khe hở chở táo, chai lọ — crate chắc hơn box giấy.", e: "Sai: The crates is stacked → Đúng: The crates are stacked. Đừng nhầm crate (thùng) với create (tạo ra).", u: "TOEIC Part 1: 'Some crates are stacked in a warehouse.' Ngữ cảnh kho, cảng, chợ.", f: "crate (n/v), crating (n), box (n), container (n), carton (n)" },
  "podium": { m: "Hình ảnh: diễn giả đứng sau chiếc bục có micro để nói trước khán giả.", e: "Sai: He is standing on the podium (nếu sau bục) → Đúng: He is standing at/behind the podium.", u: "TOEIC Part 1: 'A speaker is standing at a podium.' Part 4: giới thiệu diễn giả lên phát biểu.", f: "podium (n), lectern (n), stage (n), platform (n)" },
  "easel": { m: "Hình ảnh: giá ba chân dựng tranh cho họa sĩ vẽ ngoài trời.", e: "Sai: The painting is on a tripod → Đúng: The painting is on an easel. Phát âm /ˈiːzəl/.", u: "TOEIC Part 1: 'An artist is standing beside an easel.' Cũng dùng giá đỡ bảng ở hội nghị.", f: "easel (n), canvas (n), tripod (n), artist (n)" },
  "potted plant": { m: "pot (chậu) + -ed → cây 'được trồng trong chậu'.", e: "Sai: The pot plants is on the table → Đúng: The potted plants are on the table.", u: "TOEIC Part 1: 'Some potted plants have been placed by the window.' Mô tả sảnh, văn phòng.", f: "pot (n/v), potted (adj), houseplant (n), planter (n)" },
  "pier": { m: "Hình ảnh: lối đi bằng gỗ vươn ra biển, thuyền đậu hai bên — pier.", e: "Sai: The boat is at the bridge → Đúng: The boat is at the pier. Đừng nhầm pier với peer (bạn đồng trang lứa).", u: "TOEIC Part 1: 'People are walking along a pier.' Hay đi với dock, harbor, boats.", f: "pier (n), dock (n), wharf (n), jetty (n), harbor (n)" },
  "i'm afraid": { m: "Không phải 'tôi sợ' — đây là cách mở lời nhẹ nhàng trước tin không vui: 'tôi e là'.", e: "Sai: I'm afraid that I'm scared (lặp nghĩa). Đúng: I'm afraid the manager is out. Trả lời ngắn: I'm afraid not.", u: "TOEIC Part 2: đáp án gián tiếp kiểu 'I'm afraid he's on vacation.' thường đúng vì từ chối khéo câu hỏi.", f: "I'm afraid so (phrase), I'm afraid not (phrase), unfortunately (adv), I'm sorry, but…" },
  "not that i know of": { m: "Nghĩa đen: 'không, theo những gì tôi biết' → trả lời phủ định nhưng chừa đường lùi.", e: "Sai: Not that I know → Đúng: Not that I know of (phải có 'of' ở cuối).", u: "TOEIC Part 2: 'Is the meeting rescheduled?' – 'Not that I know of.' Đáp án gián tiếp rất hay đúng.", f: "not as far as I know (phrase), as far as I know (phrase), not to my knowledge (phrase)" },
  "it's up to you": { m: "Hình ảnh: quyết định 'nằm lên tay bạn' — bạn chọn thế nào cũng được.", e: "Sai: It's depend on you → Đúng: It's up to you / It depends on you. Sai: It's up for you.", u: "TOEIC Part 2: câu hỏi lựa chọn 'Should we meet Monday or Tuesday?' – 'It's up to you.' IELTS Speaking cũng dùng tự nhiên.", f: "up to (phrase), it's your call (phrase), whatever you prefer (phrase), either is fine" },
  "either is fine": { m: "either = một trong hai → 'cái nào trong hai cũng ổn', không ưu tiên bên nào.", e: "Sai: Both is fine → Đúng: Either is fine / Both are fine. Sai: Either are fine → Đúng: Either is fine.", u: "TOEIC Part 2: câu hỏi lựa chọn 'Window or aisle seat?' – 'Either is fine.' Đáp án né lựa chọn thường đúng.", f: "either (det/pron), neither (pron), either one (phrase), I don't mind (phrase)" },
  "i'd be happy to": { m: "I'd = I would → 'tôi sẽ rất vui được làm' — đồng ý lịch sự với một yêu cầu.", e: "Sai: I'd be happy to helping → Đúng: I'd be happy to help. Sau 'to' dùng động từ nguyên mẫu.", u: "TOEIC Part 2: 'Could you review my report?' – 'I'd be happy to.' Email Part 7: 'I'd be happy to assist.'", f: "I'd be glad to (phrase), sure (adv), certainly (adv), with pleasure (phrase)" },
  "that sounds good": { m: "sound = nghe có vẻ → 'nghe ổn đấy' — đồng ý với đề nghị của người khác.", e: "Sai: That sounds well → Đúng: That sounds good (sound + tính từ). Sai: That's sound good.", u: "TOEIC Part 2: đáp lại lời gợi ý 'Why don't we order lunch?' – 'That sounds good.' Rất phổ biến Part 3.", f: "sounds great (phrase), sounds like a plan (phrase), good idea (phrase), sound (v)" },
  "why don't we": { m: "Dạng câu hỏi nhưng thực chất là gợi ý: 'sao mình không… nhỉ?' = Let's.", e: "Sai: Why don't we to go → Đúng: Why don't we go. Đừng hiểu là hỏi lý do rồi trả lời 'Because…'.", u: "TOEIC Part 2: 'Why don't we take a break?' Bẫy: đáp án bắt đầu bằng Because thường sai; đúng là 'Good idea.'", f: "let's (phrase), how about (phrase), what about (phrase), why not (phrase)" },
  "would you mind": { m: "mind = phiền → hỏi 'bạn có phiền không'; trả lời 'No' nghĩa là đồng ý giúp.", e: "Sai: Would you mind to open → Đúng: Would you mind opening the window? Trả lời đồng ý: 'Not at all.'", u: "TOEIC Part 2: 'Would you mind covering my shift?' – 'Not at all.' Bẫy: trả lời 'Yes' có nghĩa là phiền.", f: "do you mind (phrase), would you mind if I… (phrase), not at all (phrase), mind (v)" },
  "i haven't decided yet": { m: "Câu né quyết định: 'tôi chưa chốt' — vẫn đang cân nhắc.", e: "Sai: I didn't decide yet (Anh-Mỹ nói thân mật) → Chuẩn: I haven't decided yet. Sai: I haven't decide.", u: "TOEIC Part 2: câu hỏi Wh- 'Where will you hold the party?' – 'I haven't decided yet.' Đáp án gián tiếp hay đúng.", f: "I'm not sure yet (phrase), it hasn't been decided (phrase), undecided (adj), decide (v)" },
  "let me check": { m: "Let me = để tôi → 'để tôi xem lại đã' — trì hoãn trả lời để kiểm tra thông tin.", e: "Sai: Let me to check → Đúng: Let me check. Sai: Let me checking.", u: "TOEIC Part 2: 'Is room 5 available?' – 'Let me check the schedule.' Đáp án gián tiếp rất phổ biến.", f: "let me see (phrase), I'll check (phrase), let me find out (phrase), check (v)" },
  "i'll look into it": { m: "look into = nhìn vào bên trong → tìm hiểu kỹ sự việc để xử lý.", e: "Sai: I'll look it into → Đúng: I'll look into it (không tách). Sai: look after it (chăm sóc) khác nghĩa.", u: "TOEIC Part 2/3: phản hồi khiếu nại 'The printer isn't working.' – 'I'll look into it.' Email Part 7 dịch vụ khách hàng.", f: "look into (phr v), investigate (v), check on (phr v), examine (v)" },
  "get back to": { m: "get back = quay lại → 'quay lại' với ai đó để trả lời sau.", e: "Sai: I'll get back you → Đúng: I'll get back to you. Sai: get back to you about it soonly → soon.", u: "TOEIC Part 2/3: 'Can I get back to you tomorrow?' Email Part 7: 'I'll get back to you by Friday.'", f: "get back to (phr v), respond (v), follow up (phr v), call back (phr v), reply (v)" },
  "put through": { m: "Hình ảnh: tổng đài viên 'đưa cuộc gọi xuyên qua' tới máy của người cần gặp.", e: "Sai: put me through with Mr. Lee → Đúng: put me through to Mr. Lee.", u: "TOEIC Part 3/4: 'Could you put me through to the sales department?' Ngữ cảnh lễ tân, tổng đài.", f: "put through (phr v), transfer a call (phrase), connect (v), hold on (phr v)" },
  "leave a message": { m: "leave = để lại → để lại lời nhắn khi người nhận vắng mặt.", e: "Sai: leave him message → Đúng: leave him a message. Sai: leave a message to him → Đúng: leave a message for him.", u: "TOEIC Part 4: lời nhắn thoại 'Please leave a message after the tone.' Part 2: 'May I leave a message?'", f: "message (n), take a message (phrase), voicemail (n), leave word (phrase)" },
  "extension number": { m: "extension = phần mở rộng → số mở rộng từ số tổng đài, tức số máy lẻ.", e: "Sai: my extension phone is 205 → Đúng: my extension number is 205 / I'm at extension 205.", u: "TOEIC Part 4: 'Please call me at extension 314.' Hay viết tắt ext. trong email Part 7.", f: "extension (n), ext. (viết tắt), extend (v), direct line (n)" },
  "voicemail": { m: "voice (giọng nói) + mail (thư) → thư bằng giọng nói lưu trong điện thoại.", e: "Sai: I left a voicemail to you → Đúng: I left you a voicemail / I left a voicemail for you.", u: "TOEIC Part 4: bài nghe chính là một voicemail; câu hỏi: 'Why is the speaker calling?' Rất phổ biến.", f: "voicemail (n), voice message (n), answering machine (n), leave a message (phrase)" },
  "conference call": { m: "conference (hội nghị) + call (cuộc gọi) → nhiều người ở nhiều nơi cùng tham gia một cuộc gọi.", e: "Sai: join in the conference call → Đúng: join the conference call. Sai: make conference call → Đúng: hold a conference call.", u: "TOEIC Part 3: lên lịch conference call với chi nhánh nước ngoài, chênh lệch múi giờ.", f: "conference call (n), video conference (n), teleconference (n), dial in (phr v)" },
  "running late": { m: "run = chạy → lịch của bạn đang 'chạy' chậm hơn dự kiến → đang bị muộn.", e: "Sai: I'm late running → Đúng: I'm running late. Sai: I'm running late 10 minutes → Đúng: I'm running 10 minutes late.", u: "TOEIC Part 3/4: 'I'm running late because of traffic.' Lý do trễ là câu hỏi phổ biến.", f: "run late (phrase), be late (phrase), behind schedule (phrase), delayed (adj)" },
  "behind schedule": { m: "Hình ảnh: tiến độ thực tế đi 'phía sau' bảng kế hoạch → chậm tiến độ.", e: "Sai: The project is late schedule → Đúng: The project is behind schedule. Sai: behind the schedules.", u: "TOEIC Part 3/4: dự án xây dựng, giao hàng behind schedule; câu hỏi nguyên nhân và giải pháp.", f: "behind schedule (phrase), on schedule (phrase), ahead of schedule (phrase), delay (n/v)" },
  "ahead of schedule": { m: "ahead = phía trước → tiến độ vượt lên trước kế hoạch, xong sớm hơn dự kiến.", e: "Sai: The project finished before schedule → Đúng: The project was completed ahead of schedule.", u: "TOEIC Part 4/7: 'Construction was completed two weeks ahead of schedule.' Hay đi với completed, finished.", f: "ahead of schedule (phrase), ahead of time (phrase), on schedule (phrase), early (adj/adv)" },
  "push back": { m: "Hình ảnh: 'đẩy lùi' mốc thời gian trên lịch về phía sau → hoãn sang muộn hơn.", e: "Sai: push back the meeting to earlier → Đúng: move up the meeting (dời sớm). Push back = dời muộn hơn.", u: "TOEIC Part 3: 'Can we push back the meeting to 3 p.m.?' Từ đồng nghĩa trong đáp án: postpone, delay.", f: "push back (phr v), postpone (v), delay (v), move up (phr v, trái nghĩa), reschedule (v)" },
  "call off": { m: "Hình ảnh: hô 'thôi!' gọi mọi người rút lại → hủy bỏ sự kiện.", e: "Sai: call off it → Đúng: call it off. Đừng nhầm call off (hủy) với call back (gọi lại).", u: "TOEIC Part 3/4: 'The outdoor event was called off due to rain.' Đáp án thường dùng từ cancel.", f: "call off (phr v), cancel (v), cancellation (n), scrap (v)" },
  "fill in for": { m: "fill in = lấp vào chỗ trống → làm thay khi ai đó vắng mặt.", e: "Sai: fill in him → Đúng: fill in for him. Sai: fill out for (điền đơn) → Đúng: fill in for.", u: "TOEIC Part 3: 'Can you fill in for me at Friday's meeting?' Đáp án paraphrase: substitute, replace temporarily.", f: "fill in for (phr v), stand in for (phr v), cover for (phr v), substitute (n/v)" },
  "cover for": { m: "cover = che phủ → 'che' chỗ trống của đồng nghiệp bằng cách làm thay ca.", e: "Sai: cover to her → Đúng: cover for her while she is away. Cũng nói: cover her shift.", u: "TOEIC Part 3: 'Could you cover for me tomorrow afternoon?' Ngữ cảnh đổi ca, nghỉ phép.", f: "cover for (phr v), cover a shift (phrase), fill in for (phr v), stand in (phr v)" },
  "be in charge of": { m: "charge = trách nhiệm → người 'nắm trách nhiệm' một việc, một bộ phận.", e: "Sai: She is in charge for marketing → Đúng: She is in charge of marketing. Sai: charge of the project.", u: "TOEIC Part 3/4: 'Who is in charge of the event?' Câu hỏi danh tính người phụ trách rất phổ biến.", f: "in charge of (phrase), responsible for (phrase), oversee (v), supervise (v), head (v)" },
  "fill out": { m: "fill (làm đầy) + out (hoàn tất) → điền đầy đủ mọi ô trên mẫu đơn.", e: "Sai: fill out it → Đúng: fill it out. Sai: fill the form (thiếu out) → Đúng: fill out/in the form.", u: "TOEIC Part 3/4: 'Please fill out this registration form.' Đáp án đồng nghĩa: complete a form.", f: "fill out (phr v), fill in (phr v), complete (v), form (n), application (n)" },
  "drop off": { m: "drop = thả xuống → 'thả' người hoặc đồ xuống một nơi rồi đi tiếp.", e: "Sai: drop off it → Đúng: drop it off. Sai: drop off at me → Đúng: drop me off at the station.", u: "TOEIC Part 3: 'I'll drop off the documents at your office.' Ngược lại pick up (đón, lấy).", f: "drop off (phr v), drop-off (n), pick up (phr v, trái nghĩa), deliver (v)" },
  "out of order": { m: "order = trật tự hoạt động → 'ra khỏi trật tự' → máy hỏng, không dùng được.", e: "Sai: The copier is out of service order → Đúng: The copier is out of order. Sai: out of oder.", u: "TOEIC Part 3/4: thang máy, máy photocopy out of order; biển báo hay gặp. Đồng nghĩa: not working, broken.", f: "out of order (phrase), out of service (phrase), broken (adj), malfunction (v/n)" },
  "paper jam": { m: "jam = kẹt, tắc (như traffic jam) → giấy kẹt trong máy in.", e: "Sai: The paper is jamming in printer → Đúng: There's a paper jam in the printer / The printer is jammed.", u: "TOEIC Part 3: sự cố văn phòng, 'The copier has a paper jam again.' Câu hỏi: 'What problem does the man mention?'", f: "jam (n/v), jammed (adj), paper jam (n), clear a jam (phrase)" },
  "filing cabinet": { m: "file (hồ sơ) + cabinet (tủ) → tủ nhiều ngăn kéo đựng hồ sơ giấy.", e: "Sai: file cabinet (Anh-Mỹ vẫn dùng); sai: filling cabinet → Đúng: filing cabinet (một chữ l).", u: "TOEIC Part 1: 'A drawer of a filing cabinet has been left open.' Part 3: tìm tài liệu trong tủ.", f: "file (n/v), filing (n), cabinet (n), drawer (n), file folder (n)" },
  "workstation": { m: "work (làm việc) + station (trạm) → 'trạm' làm việc riêng của mỗi nhân viên: bàn, máy tính.", e: "Sai: work station (tách) → thường viết workstation. Sai: workstations is → Đúng: workstations are.", u: "TOEIC Part 1: 'Workstations are arranged in rows.' Part 7: thông báo IT bảo trì workstations.", f: "workstation (n), desk (n), workspace (n), cubicle (n)" },
  "cubicle": { m: "Hình ảnh: các ô vuông có vách ngăn thấp trong văn phòng mở — mỗi người một cubicle.", e: "Sai: cubical (hình khối) → Đúng: cubicle (ô làm việc). Phát âm /ˈkjuːbɪkl/.", u: "TOEIC Part 1/3: 'His cubicle is next to the window.' Liên quan chuyển chỗ làm việc trong văn phòng.", f: "cubicle (n), partition (n), workstation (n), open-plan office (n)" },
  "bulletin board": { m: "bulletin = bản tin → bảng gắn thông báo, ghim giấy ở hành lang, phòng nghỉ.", e: "Sai: post it in the bulletin board → Đúng: post it on the bulletin board (dùng 'on').", u: "TOEIC Part 1/4: 'A notice has been posted on the bulletin board.' Anh-Anh: noticeboard.", f: "bulletin (n), bulletin board (n), noticeboard (n), post (v), notice (n)" },
  "repair person": { m: "repair (sửa) + person → người đến sửa chữa máy móc, đồ đạc.", e: "Sai: repairer person → Đúng: repair person / repairperson. Từ trung tính, thay cho repairman.", u: "TOEIC Part 3: 'A repair person is coming to fix the air conditioner.' Câu hỏi: 'Who will arrive this afternoon?'", f: "repair (v/n), repairperson (n), technician (n), repairman (n), mechanic (n)" },
  "road work": { m: "road (đường) + work (công việc) → công nhân đào, sửa mặt đường, gây tắc đường.", e: "Sai: road works is (Anh-Mỹ hay dùng số ít) → Đúng: road work is causing delays.", u: "TOEIC Part 4: bản tin giao thông, 'Road work on Main Street will continue until Friday.'", f: "road work (n), roadworks (n, Anh-Anh), construction (n), detour (n)" },
  "detour": { m: "de- (rời) + tour (đi) → đi lệch khỏi đường chính, vòng qua lối khác.", e: "Sai: take a detour road → Đúng: take a detour. Sai: make detour → Đúng: make a detour.", u: "TOEIC Part 4: 'Drivers should follow the detour signs.' Hay đi cùng road work, closure.", f: "detour (n/v), diversion (n, Anh-Anh), reroute (v), alternative route (n)" },
  "traffic jam": { m: "jam = ép chặt (như mứt dính đặc) → xe ép chặt, đứng im trên đường.", e: "Sai: I was stuck on traffic jam → Đúng: I was stuck in a traffic jam. Sai: traffic jams was.", u: "TOEIC Part 3: lý do đến trễ; IELTS Speaking về thành phố: 'traffic jams are a daily problem in Hanoi'.", f: "traffic jam (n), traffic congestion (n), gridlock (n), rush hour (n)" },
  "connecting flight": { m: "connect = nối → chuyến bay 'nối' tiếp sau khi quá cảnh để đến điểm cuối.", e: "Sai: I missed my connection flight → Đúng: I missed my connecting flight (hoặc my connection).", u: "TOEIC Part 4: thông báo sân bay, chuyến bay trễ khiến lỡ connecting flight; câu hỏi về giải pháp.", f: "connect (v), connecting flight (n), layover (n), stopover (n), transfer (n)" },
  "aisle seat": { m: "aisle (lối đi, đọc /aɪl/ — chữ s câm) → ghế sát lối đi, dễ ra vào.", e: "Sai: aile seat / phát âm 'ai-sồ' → Đúng: aisle /aɪl/. Đối lập: window seat.", u: "TOEIC Part 2: 'Would you prefer a window or an aisle seat?' Ngữ cảnh đặt vé máy bay, rạp hát.", f: "aisle (n), aisle seat (n), window seat (n), middle seat (n)" },
  "baggage claim": { m: "claim = đòi lại → nơi hành khách 'nhận lại' vali sau chuyến bay.", e: "Sai: luggage claiming area → Đúng: baggage claim. Sai: baggages → Đúng: baggage (không đếm được).", u: "TOEIC Part 4: 'Passengers can collect their luggage at baggage claim 3.' Câu hỏi địa điểm.", f: "baggage (n), luggage (n), baggage claim (n), carousel (n), carry-on (n)" },
  "round-trip": { m: "round = vòng → chuyến đi một vòng: đi rồi quay về điểm xuất phát.", e: "Sai: a two-way ticket → Đúng: a round-trip ticket (Anh-Anh: return ticket). Sai: round trip tickets is.", u: "TOEIC Part 3/7: đặt vé round-trip, so sánh giá với one-way; email xác nhận lịch trình công tác.", f: "round-trip (adj), round trip (n), one-way (adj, trái nghĩa), return ticket (n)" },
  "in stock": { m: "stock = kho hàng → món hàng đang có 'trong kho', mua được ngay.", e: "Sai: The item is on stock → Đúng: The item is in stock. Sai: in stocks.", u: "TOEIC Part 3: khách hỏi 'Do you have this in stock?'; Part 7: email báo hàng sẽ in stock lại.", f: "stock (n/v), in stock (phrase), out of stock (phrase), available (adj), inventory (n)" },
  "out of stock": { m: "out of = ra khỏi → hàng đã 'ra khỏi kho' hết, tạm không bán được.", e: "Sai: The item is out of the stock → Đúng: The item is out of stock. Sai: out-stock.", u: "TOEIC Part 3/7: lý do đơn hàng chậm; câu hỏi: 'What does the woman offer?' (sản phẩm thay thế, giảm giá).", f: "out of stock (phrase), sold out (adj), unavailable (adj), back-ordered (adj), restock (v)" },
  "back-ordered": { m: "back order = đơn hàng 'nằm phía sau' chờ hàng về → khách đặt trước, giao sau.", e: "Sai: The item is back order → Đúng: The item is back-ordered / on back order.", u: "TOEIC Part 7: email 'The desk you ordered is currently back-ordered and will ship in two weeks.'", f: "back order (n), back-order (v), back-ordered (adj), on back order (phrase), out of stock" },
  "place an order": { m: "place = đặt để → 'đặt' đơn hàng vào hệ thống của nhà cung cấp.", e: "Sai: make an order for → thường dùng place. Sai: place an order of paper → Đúng: place an order for paper.", u: "TOEIC Part 3/7: 'I'd like to place an order for office supplies.' Đồng nghĩa: order (v).", f: "order (n/v), place an order (phrase), cancel an order (phrase), purchase order (n)" },
  "sold out": { m: "sell (bán) + out (hết sạch) → vé, hàng đã bán hết không còn.", e: "Sai: The tickets are sell out → Đúng: The tickets are sold out / The tickets sold out.", u: "TOEIC Part 3/4: vé hòa nhạc, hội thảo sold out; IELTS Speaking: 'The concert sold out in minutes.'", f: "sell out (phr v), sold out (adj), sell-out (n), out of stock (phrase)" },
  "attention, passengers": { m: "Câu mở đầu thông báo ở sân bay, nhà ga — báo hiệu sắp có thông tin quan trọng.", e: "Sai: Attention passenger please (thiếu dấu phẩy, số ít) → Đúng: Attention, passengers.", u: "TOEIC Part 4: câu đầu của bài thông báo; câu hỏi: 'Where is the announcement being made?' (airport, train station).", f: "attention (n), passenger (n), may I have your attention (phrase), announcement (n)" },
  "we apologise for any inconvenience": { m: "Câu xin lỗi chuẩn trong thông báo: 'xin lỗi vì mọi bất tiện' gây ra.", e: "Sai: We apologise for any inconveniences cause → Đúng: We apologise for any inconvenience (caused).", u: "TOEIC Part 4/7: thông báo trễ chuyến, sửa chữa; Anh-Mỹ viết apologize. Câu hỏi về lý do xin lỗi.", f: "apologise/apologize (v), apology (n), inconvenience (n), inconvenient (adj)" },
  "thank you for calling": { m: "Câu chào mở đầu của tin nhắn tự động, tổng đài công ty, theo sau là tên công ty.", e: "Sai: Thank you for call → Đúng: Thank you for calling (sau giới từ for dùng V-ing).", u: "TOEIC Part 4: tin nhắn ghi âm 'Thank you for calling Brightline Electronics.' Câu hỏi: loại hình doanh nghiệp.", f: "thank you for (phrase), recorded message (n), call (v/n), caller (n)" },
  "press one": { m: "press = nhấn → hướng dẫn tổng đài tự động: nhấn phím số để chọn dịch vụ.", e: "Sai: press on one → Đúng: press one. Sai: press the one key (vụng) → Đúng: press one / press 1.", u: "TOEIC Part 4: 'For billing questions, press one.' Câu hỏi: 'What should listeners do to…?'", f: "press (v), key (n), dial (v), stay on the line (phrase), hold (v)" },
  "business hours": { m: "Khung giờ doanh nghiệp 'mở cửa làm việc', ví dụ 9 giờ sáng đến 5 giờ chiều.", e: "Sai: during the business hour → Đúng: during business hours (số nhiều). Sai: in business hours.", u: "TOEIC Part 4: 'Our business hours are 9 to 5, Monday through Friday.' Part 7: thông báo đổi giờ làm việc.", f: "business hours (n), office hours (n), opening hours (n), after hours (phrase)" },
  "grand opening": { m: "grand (hoành tráng) + opening (mở cửa) → buổi mở cửa hoành tráng đầu tiên → lễ khai trương.", e: "Sai: the opening ceremony grand of our store → Đúng: the grand opening of our store. Sai: grand open → Đúng: grand opening.", u: "Part 4 quảng cáo: 'Join us for our grand opening this Saturday', kèm giảm giá, quà tặng cho khách đầu tiên.", f: "grand opening (n), grand reopening (n), opening ceremony (n), soft opening (n)" },
  "limited time offer": { m: "Offer chỉ có trong 'limited time' – thời gian giới hạn → hết hạn là mất ưu đãi.", e: "Sai: offer in limited time → Đúng: a limited-time offer. Khi đứng trước danh từ nên có gạch nối.", u: "Part 4 quảng cáo radio: 'This limited-time offer ends Sunday'. Câu hỏi thường gặp: ưu đãi kết thúc khi nào?", f: "limited-time offer (n), special offer (n), for a limited time only (phrase), while supplies last" },
  "keynote speaker": { m: "keynote = nốt chủ âm định giọng cả bản nhạc → người phát biểu định hướng cả hội nghị.", e: "Sai: the main speaker keynote → Đúng: the keynote speaker. Sai: give a keynote speaker → Đúng: give a keynote speech.", u: "Part 4 hội nghị: 'Our keynote speaker is Dr. Lee'. Hỏi: diễn giả chính là ai, nói về chủ đề gì?", f: "keynote (n), keynote speech/address (n), guest speaker (n), keynote (v, phát biểu chính)" },
  "without further ado": { m: "ado = sự rườm rà, ồn ào. Không thêm rườm rà nữa → vào thẳng việc chính.", e: "Sai: without further adieu → Đúng: without further ado. 'adieu' là lời chào tạm biệt, khác hẳn.", u: "Part 4 giới thiệu diễn giả: 'So without further ado, please welcome Ms. Park'. Dấu hiệu sắp có người lên phát biểu.", f: "without further ado (phrase), without more ado, let's get started, much ado about nothing" },
  "round of applause": { m: "Hình ảnh: một 'vòng' (round) vỗ tay lan khắp khán phòng → một tràng pháo tay.", e: "Sai: give him a round applause → Đúng: give him a round of applause. Sai: applauses → Đúng: applause (không đếm được).", u: "Part 4 sự kiện: 'Let's give a big round of applause to our volunteers'. Kết thúc bài phát biểu hoặc trao giải.", f: "applause (n), applaud (v), clap (v), standing ovation (n)" },
  "in the meantime": { m: "meantime = 'khoảng thời gian ở giữa' → trong lúc chờ chuyện kia xảy ra.", e: "Sai: in the meantimes → Đúng: in the meantime. Sai: in meantime → Đúng: in the meantime (phải có 'the').", u: "Part 4 thông báo hoãn: 'The flight is delayed. In the meantime, please wait at Gate 5'. Hỏi người nghe nên làm gì.", f: "meantime (n), meanwhile (adv), in the interim, for now" },
  "as a reminder": { m: "remind (nhắc) → reminder (lời nhắc). 'As a reminder' = coi đây là lời nhắc lại điều đã biết.", e: "Sai: as a remind → Đúng: as a reminder. Sai: for remind you → Đúng: just to remind you.", u: "Part 4 thông báo nội bộ: 'As a reminder, the office closes early Friday'. Thông tin sau cụm này hay bị hỏi.", f: "remind (v), reminder (n), friendly reminder (n), just a reminder" },
  "weather permitting": { m: "Rút gọn từ 'if the weather permits' → thời tiết cho phép thì làm, xấu thì hủy.", e: "Sai: weather permitted → Đúng: weather permitting. Sai: if weather permitting → Đúng: weather permitting (không thêm 'if').", u: "Part 4 tour du lịch: 'Weather permitting, we'll have lunch outdoors'. Câu hỏi về điều kiện tổ chức sự kiện.", f: "permit (v), permission (n), time permitting, if conditions allow" },
  "traffic update": { m: "update = cập nhật. Cập nhật tình hình giao thông → bản tin kẹt xe, đường đóng.", e: "Sai: traffic updating news → Đúng: traffic update. Sai: update of traffic jam → Đúng: traffic update on Route 9.", u: "Part 4 radio: 'Here's your morning traffic update'. Hỏi: đường nào bị đóng, vì sao, nên đi lối nào.", f: "traffic report (n), weather update (n), road closure (n), detour (n)" },
  "in accordance with": { m: "accord = hòa hợp, khớp nhau → làm khớp với quy định → theo, phù hợp với.", e: "Sai: in accordance to the rules → Đúng: in accordance with the rules. Luôn đi với 'with'.", u: "Part 5/7 văn bản chính sách: 'in accordance with company policy'. Bẫy giới từ: chọn 'with', không chọn 'to'.", f: "accord (n/v), accordance (n), according to (prep), accordingly (adv)" },
  "in compliance with": { m: "comply (tuân theo) → compliance (sự tuân thủ). Ở trong trạng thái tuân thủ với luật.", e: "Sai: in compliance to safety rules → Đúng: in compliance with safety rules.", u: "Part 5/7: 'All products are in compliance with safety standards'. Văn bản kiểm định, an toàn lao động.", f: "comply (v), compliance (n), compliant (adj), non-compliance (n)" },
  "comply with": { m: "Liên tưởng 'complete' – làm đầy đủ yêu cầu → tuân thủ, làm theo.", e: "Sai: comply the regulations → Đúng: comply with the regulations. Sai: complied to → Đúng: complied with.", u: "Part 5: 'Employees must comply with the dress code'. Nhận biết nội động từ cần 'with'.", f: "comply (v), compliance (n), compliant (adj), conform to, abide by" },
  "adhere to": { m: "adhere = dính chặt (như 'adhesive' – keo dán) → bám sát quy tắc, tuân thủ chặt.", e: "Sai: adhere the schedule → Đúng: adhere to the schedule. Sai: adhere with → Đúng: adhere to.", u: "Part 5/7: 'Staff must strictly adhere to safety guidelines'. Hay đi với strictly, closely.", f: "adhere (v), adherence (n), adhesive (n/adj), stick to, follow" },
  "on behalf of": { m: "behalf = 'phần bên' của ai → đứng về phía, thay mặt người đó.", e: "Sai: in behalf of the team → Đúng: on behalf of the team. Sai: on behalf the company → Đúng: on behalf of the company.", u: "Part 4/7: 'On behalf of the board, I'd like to thank you'. Mở đầu bài phát biểu, thư cảm ơn.", f: "on behalf of (phrase), on sb's behalf, representative (n), represent (v)" },
  "prior to": { m: "prior = trước (như 'priority' – việc đặt lên trước) → prior to = trước khi.", e: "Sai: prior to arrive → Đúng: prior to arriving / prior to your arrival. 'to' là giới từ, sau là V-ing hoặc danh từ.", u: "Part 5/7: 'Please check in prior to the meeting'. Bẫy ngữ pháp: sau 'prior to' dùng V-ing.", f: "prior (adj), priority (n), prioritize (v), before (prep), in advance of" },
  "upon request": { m: "upon = khi có. Khi có yêu cầu thì mới cung cấp → theo yêu cầu.", e: "Sai: upon requesting of customers → Đúng: upon request / at the customer's request.", u: "Part 7 brochure: 'Vegetarian meals are available upon request'. Hỏi: muốn có dịch vụ đó cần làm gì.", f: "request (n/v), on request, at sb's request, upon arrival" },
  "upon arrival": { m: "upon = ngay khi. Vừa đến nơi là việc này xảy ra.", e: "Sai: upon arrive → Đúng: upon arrival / upon arriving. Sai: in arrival → Đúng: on/upon arrival.", u: "Part 7 khách sạn, hội thảo: 'Please show your ID upon arrival'. Hỏi: khách cần làm gì khi đến.", f: "arrive (v), arrival (n), on arrival, upon departure, upon receipt" },
  "at your earliest convenience": { m: "earliest (sớm nhất) + convenience (thuận tiện) → sớm nhất mà bạn thấy tiện → lịch sự giục khéo.", e: "Sai: in your earliest convenience → Đúng: at your earliest convenience. Sai: at your early convenience.", u: "Part 7 email: 'Please reply at your earliest convenience'. Cách nhờ phản hồi nhanh mà vẫn lịch sự.", f: "convenience (n), convenient (adj), conveniently (adv), as soon as possible, ASAP" },
  "as of": { m: "as of + mốc thời gian → tính từ mốc đó trở đi (hoặc tính đến mốc đó).", e: "Sai: as of from June 1 → Đúng: as of June 1. Không thêm 'from' hay 'since' sau 'as of'.", u: "Part 7 thông báo: 'As of March 1, parking fees will increase'. Câu hỏi chọn ngày thay đổi có hiệu lực.", f: "as of (prep), as from, effective (adj), starting from" },
  "effective immediately": { m: "effective = có hiệu lực. Hiệu lực ngay lập tức, không chờ ngày khác.", e: "Sai: effectively immediately → Đúng: effective immediately. Sai: effect immediately → Đúng: take effect immediately.", u: "Part 7 memo: 'Effective immediately, all visitors must sign in'. Hỏi: quy định mới bắt đầu khi nào.", f: "effective (adj), effect (n), take effect, effective as of + date" },
  "until further notice": { m: "notice = thông báo. Giữ nguyên tình trạng cho tới khi có 'further' (thêm) thông báo.", e: "Sai: until further notices → Đúng: until further notice. Sai: till next notice → Đúng: until further notice.", u: "Part 7: 'The cafeteria is closed until further notice'. Ý: chưa biết bao giờ mở lại.", f: "notice (n/v), notify (v), notification (n), for the time being, indefinitely" },
  "on short notice": { m: "notice ngắn → được báo quá sát giờ → gấp, bất ngờ.", e: "Sai: in short notice → Đúng: on short notice (Anh-Anh: at short notice). Sai: short noticed.", u: "Part 3/7: 'Thanks for coming in on such short notice'. Tình huống thay ca, họp đột xuất.", f: "at short notice (BrE), last-minute (adj), advance notice (n), notice period (n)" },
  "at no extra charge": { m: "charge = phí. Không có phí 'extra' (thêm) → miễn phí phần bổ sung.", e: "Sai: with no extra charge → Đúng: at no extra charge. Sai: at no extra charges → dùng số ít.", u: "Part 7 quảng cáo: 'Gift wrapping is available at no extra charge'. Hỏi dịch vụ nào miễn phí.", f: "free of charge, at no additional cost, complimentary (adj), surcharge (n)" },
  "at a discounted rate": { m: "discount (giảm giá) + rate (mức giá) → được tính ở mức giá đã giảm.", e: "Sai: at a discount rate price → Đúng: at a discounted rate. Sai: with discounted rate → Đúng: at a discounted rate.", u: "Part 7: 'Members can book rooms at a discounted rate'. Hỏi: ai được hưởng giá ưu đãi.", f: "discount (n/v), discounted (adj), at a reduced price, at a special rate" },
  "in response to": { m: "respond (đáp lại) → response. Đứng trong vai trò lời đáp cho một điều gì đó.", e: "Sai: in response for your email → Đúng: in response to your email. Sai: in responding of.", u: "Part 7 thư trả lời: 'I'm writing in response to your job posting'. Hỏi mục đích bức thư.", f: "respond (v), response (n), responsive (adj), in reply to" },
  "in light of": { m: "Hình ảnh: soi điều gì dưới ánh sáng của sự việc mới → xét đến, vì lý do đó.", e: "Sai: in the light of view → Đúng: in light of recent events. Không nhầm với 'in spite of'.", u: "Part 5/7: 'In light of budget cuts, the trip was canceled'. Nghĩa gần 'because of'.", f: "in light of (prep), in view of, given (prep), considering, owing to" },
  "with the exception of": { m: "except → exception (ngoại lệ). Tất cả đều vậy, chỉ trừ ngoại lệ này.", e: "Sai: with exception of → Đúng: with the exception of. Sai: with the exception from.", u: "Part 5/7: 'All stores are open, with the exception of the downtown branch'. Câu hỏi NOT TRUE.", f: "except (prep), exception (n), exceptional (adj), excluding, apart from" },
  "regardless of": { m: "regard = để ý. 'less' = không. Không để ý đến điều đó → bất kể.", e: "Sai: regardless the weather → Đúng: regardless of the weather. Sai: irregardless (không chuẩn).", u: "Part 5: 'The event will go ahead regardless of the weather'. Phân biệt với 'despite' (không có 'of').", f: "regard (v/n), regardless (adv), irrespective of, no matter, despite" },
  "in addition to": { m: "add (thêm) → addition. Ngoài cái này còn thêm cái kia.", e: "Sai: in addition to provide → Đúng: in addition to providing. 'to' là giới từ, sau là V-ing.", u: "Part 5: 'In addition to a salary, we offer bonuses'. Bẫy ngữ pháp V-ing sau giới từ 'to'.", f: "add (v), addition (n), additional (adj), besides, as well as, along with" },
  "in terms of": { m: "term = phương diện, thuật ngữ. Xét theo phương diện nào → về mặt.", e: "Sai: in term of price → Đúng: in terms of price. Luôn có 's' ở 'terms'.", u: "IELTS Writing Task 1: 'In terms of sales, A outperformed B'. TOEIC Part 7 so sánh sản phẩm.", f: "term (n), in terms of (prep), regarding, with respect to, as for" },
  "with regard to": { m: "regard = xem xét, để mắt tới. Đang xem xét vấn đề gì → liên quan đến.", e: "Sai: with regards to → Đúng: with regard to (trang trọng hơn). Sai: with regard of.", u: "Part 7 email: 'With regard to your inquiry, ...'. Mở đầu trả lời câu hỏi khách hàng.", f: "regard (n/v), regarding (prep), as regards, concerning, with respect to" },
  "pertaining to": { m: "per (hoàn toàn) + tain (giữ, như 'contain') → gắn chặt với vấn đề → liên quan đến.", e: "Sai: pertaining with the project → Đúng: pertaining to the project. Sai: pertain about.", u: "Part 7 văn bản pháp lý: 'documents pertaining to the merger'. Cách nói trang trọng của 'about'.", f: "pertain (v), pertinent (adj), relating to, concerning, regarding" },
  "in place of": { m: "Đứng vào 'place' (chỗ) của người khác → thay cho.", e: "Sai: in the place for Mr. Kim → Đúng: in place of Mr. Kim. Sai: instead Mr. Kim.", u: "Part 4/7: 'Ms. Ito will speak in place of the director'. Hỏi: ai thay thế ai.", f: "instead of, in lieu of, replace (v), replacement (n), substitute (n/v)" },
  "no later than": { m: "Không được muộn hơn mốc này → hạn chót, đến muộn nhất là ngày đó.", e: "Sai: no late than Friday → Đúng: no later than Friday. Sai: not later than until Friday.", u: "Part 7: 'Submit forms no later than May 5'. Câu hỏi: hạn chót là ngày nào.", f: "by (prep), before (prep), deadline (n), at the latest" },
  "be eligible for": { m: "eligible ≈ 'elect' (chọn) → đủ điều kiện để được chọn, hưởng.", e: "Sai: be eligible to a refund → Đúng: be eligible for a refund. Dùng 'eligible to + V': eligible to apply.", u: "Part 7 phúc lợi: 'Full-time staff are eligible for bonuses'. Hỏi: ai đủ điều kiện.", f: "eligible (adj), eligibility (n), ineligible (adj), qualify for, be entitled to" },
  "be entitled to": { m: "title = danh nghĩa, quyền → entitled = có danh nghĩa, có quyền hưởng.", e: "Sai: be entitled for a refund → Đúng: be entitled to a refund. Sai: entitle to do → be entitled to do.", u: "Part 7: 'Employees are entitled to 15 days of paid leave'. Văn bản hợp đồng, phúc lợi.", f: "entitle (v), entitlement (n), be eligible for, have the right to" },
  "be subject to": { m: "subject = chịu tác động. Bị đặt dưới sự chi phối của điều gì → có thể bị.", e: "Sai: be subject to change price → Đúng: Prices are subject to change. Sai: subjected for.", u: "Part 7: 'Schedules are subject to change without notice'. Hay đi với change, approval, availability.", f: "subject (adj/n/v), subjective (adj), liable to, dependent on" },
  "be responsible for": { m: "respond (đáp) + able → có khả năng đáp lại việc mình làm → chịu trách nhiệm.", e: "Sai: be responsible of → Đúng: be responsible for. Sai: responsible to manage → Đúng: responsible for managing.", u: "Part 7 tuyển dụng: 'The manager is responsible for training staff'. IELTS Writing: governments are responsible for...", f: "responsible (adj), responsibility (n), responsibly (adv), in charge of, accountable for" },
  "be familiar with": { m: "familiar ≈ family → quen như người nhà → quen thuộc, biết rõ.", e: "Sai: be familiar to Excel (người) → Đúng: I'm familiar with Excel. 'familiar to' dùng khi vật quen với người.", u: "Part 7 tuyển dụng: 'Applicants should be familiar with accounting software'. IELTS Speaking về kỹ năng.", f: "familiar (adj), familiarity (n), familiarize (v), unfamiliar (adj), acquainted with" },
  "be committed to": { m: "commit = giao phó trọn vẹn → dồn hết tâm sức vào điều gì → cam kết.", e: "Sai: committed to provide → Đúng: committed to providing. 'to' là giới từ.", u: "Part 7 sứ mệnh công ty: 'We are committed to customer satisfaction'. Bẫy V-ing ở Part 5.", f: "commit (v), commitment (n), committed (adj), dedicated to, devoted to" },
  "be compatible with": { m: "com (cùng) + pat (chịu đựng) → hợp nhau, chạy cùng nhau được → tương thích.", e: "Sai: compatible to Windows → Đúng: compatible with Windows. Sai: compatable (sai chính tả).", u: "Part 7 mô tả sản phẩm: 'This charger is compatible with most phones'. Câu hỏi đặc điểm sản phẩm.", f: "compatible (adj), compatibility (n), incompatible (adj), work with" },
  "be comparable to": { m: "compare (so sánh) + able → đủ ngang để đem ra so sánh → tương đương.", e: "Sai: comparable with price of → Đúng: comparable to that of. Trọng âm: COMparable, không phải comPArable.", u: "Part 7: 'Our prices are comparable to those of competitors'. IELTS Writing Task 1 so sánh số liệu.", f: "compare (v), comparison (n), comparable (adj), comparative (adj), similar to" },
  "be consistent with": { m: "consist = đứng cùng nhau → khớp, không mâu thuẫn → nhất quán với.", e: "Sai: consistent to the data → Đúng: consistent with the data. Sai: consistant (sai chính tả).", u: "Part 7 báo cáo: 'Results are consistent with earlier findings'. IELTS Writing học thuật.", f: "consistent (adj), consistency (n), consistently (adv), inconsistent (adj), in line with" },
  "be exempt from": { m: "ex (ra ngoài) + empt (lấy) → được lấy ra khỏi nghĩa vụ → được miễn.", e: "Sai: exempted of tax → Đúng: exempt from tax. Sai: be exempt to → Đúng: be exempt from.", u: "Part 7 thuế, phí: 'Non-profits are exempt from this fee'. Hỏi: ai không phải trả.", f: "exempt (adj/v), exemption (n), tax-exempt (adj), free from" },
  "be accessible to": { m: "access (lối vào) + ible → có lối vào cho ai đó → tiếp cận được.", e: "Sai: accessible for wheelchairs users → Đúng: accessible to wheelchair users. Sai: accessable.", u: "Part 7: 'The venue is accessible to people with disabilities'. IELTS Writing về giáo dục, y tế.", f: "access (n/v), accessible (adj), accessibility (n), inaccessible (adj), available to" },
  "be contingent on": { m: "contingent ≈ 'contact' (chạm) → phải chạm được điều kiện kia thì mới xảy ra.", e: "Sai: contingent to approval → Đúng: contingent on/upon approval.", u: "Part 7 hợp đồng, tuyển dụng: 'The offer is contingent on a background check'. Câu hỏi điều kiện.", f: "contingent (adj), contingency (n), dependent on, conditional on, depend on" },
  "be reluctant to": { m: "re (lùi) + luct (vật lộn) → vùng vằng lùi lại, không muốn làm → miễn cưỡng.", e: "Sai: reluctant for doing → Đúng: reluctant to do. Sai: reluctant in signing → Đúng: reluctant to sign.", u: "Part 7/IELTS Writing: 'Many firms are reluctant to invest'. Diễn tả thái độ e dè.", f: "reluctant (adj), reluctance (n), reluctantly (adv), unwilling (adj), hesitant (adj)" },
  "be scheduled to": { m: "schedule = lịch. Đã ghi lên lịch để làm việc gì → được lên lịch.", e: "Sai: is scheduled to opening → Đúng: is scheduled to open. Sai: is schedule to.", u: "Part 4/7: 'The plane is scheduled to depart at 9'. Hỏi thời gian dự kiến.", f: "schedule (n/v), scheduled (adj), rescheduled (adj), be due to, be set to" },
  "be pleased to": { m: "please (làm hài lòng) → pleased = vui lòng. Vui khi được làm việc này.", e: "Sai: be pleasing to announce → Đúng: be pleased to announce. Sai: pleased for inform.", u: "Part 4/7: 'We are pleased to announce our new director'. Mở đầu thông báo tin vui.", f: "please (v), pleased (adj), pleasure (n), pleasant (adj), be delighted to" },
  "meet the deadline": { m: "meet = gặp. 'Gặp' được hạn chót trước khi nó trôi qua → kịp hạn.", e: "Sai: catch the deadline → Đúng: meet the deadline. Sai: meet the deadline of Friday → Đúng: meet the Friday deadline.", u: "Part 3/7: 'We need extra staff to meet the deadline'. IELTS Speaking về áp lực công việc, học tập.", f: "miss the deadline, extend the deadline, tight deadline (n), deadline (n)" },
  "submit a proposal": { m: "sub (dưới) + mit (gửi) → gửi trình lên cấp trên → nộp đề xuất.", e: "Sai: submit a propose → Đúng: submit a proposal. Sai: submit proposal to boss → Đúng: submit a proposal to the board.", u: "Part 7: 'Proposals must be submitted by June 30'. Văn bản đấu thầu, dự án.", f: "submit (v), submission (n), propose (v), proposal (n), put forward a plan" },
  "launch a campaign": { m: "launch = phóng tên lửa → khởi động chiến dịch rầm rộ, bay lên.", e: "Sai: open a campaign → Đúng: launch a campaign. Sai: launch a campaign for promote → Đúng: to promote.", u: "Part 4/7 marketing: 'We'll launch an ad campaign next month'. Hỏi mục đích chiến dịch.", f: "launch (v/n), campaign (n/v), run a campaign, kick off, roll out" },
  "conduct a survey": { m: "conduct = dẫn dắt (như nhạc trưởng 'conductor') → điều hành một cuộc khảo sát.", e: "Sai: make a survey → Đúng: conduct/carry out a survey. Sai: conduct a survey to customers → Đúng: of customers.", u: "Part 7/IELTS Writing Task 1: 'A survey was conducted among 500 students'. Mô tả nguồn số liệu.", f: "conduct (v/n), survey (n/v), surveyor (n), carry out a survey, poll (n)" },
  "reach an agreement": { m: "reach = với tới. Thương lượng mãi mới với tới điểm chung → đạt thỏa thuận.", e: "Sai: reach to an agreement → Đúng: reach an agreement. Sai: get agreement together.", u: "Part 3/7: 'The two firms finally reached an agreement'. Tin tức sáp nhập, đàm phán.", f: "agree (v), agreement (n), come to an agreement, strike a deal, disagreement (n)" },
  "negotiate a contract": { m: "neg (không) + otium (rảnh) → bận rộn mặc cả → đàm phán hợp đồng.", e: "Sai: negotiate about a contract → Đúng: negotiate a contract. Dùng 'negotiate with' cho người: negotiate with suppliers.", u: "Part 7 kinh doanh: 'We are negotiating a contract with a new supplier'. Hỏi bên đối tác.", f: "negotiate (v), negotiation (n), negotiator (n), negotiable (adj), renegotiate (v)" },
  "renew a contract": { m: "re (lại) + new (mới) → làm mới lại hợp đồng sắp hết hạn → gia hạn.", e: "Sai: extend again contract → Đúng: renew the contract. Sai: renewal the contract (renewal là danh từ).", u: "Part 7: 'Please renew your contract before it expires'. Cũng gặp: renew a subscription, membership.", f: "renew (v), renewal (n), renewable (adj), extend a contract, expire (v)" },
  "expand operations": { m: "expand = nở rộng ra. Công ty phình to hoạt động sang nơi mới.", e: "Sai: expand the operation in Asia → Đúng: expand operations into Asia. Thường dùng số nhiều 'operations'.", u: "Part 7 tin kinh doanh: 'The firm plans to expand operations overseas'. Hỏi kế hoạch tương lai.", f: "expand (v), expansion (n), expansive (adj), grow the business, scale up" },
  "cut costs": { m: "Hình ảnh: cầm kéo 'cắt' bớt khoản chi → cắt giảm chi phí.", e: "Sai: cut down the cost spending → Đúng: cut costs / cut spending. Sai: reduce cost (thiếu s).", u: "Part 7/IELTS Writing: 'Companies automate to cut costs'. Lý do sa thải, đóng chi nhánh.", f: "cost-cutting (n/adj), reduce expenses, slash costs, cost (n/v)" },
  "boost sales": { m: "boost = đẩy mạnh lên (như nút tăng tốc). Đẩy doanh số vọt lên.", e: "Sai: boost up the sell → Đúng: boost sales. 'sale' khi nói doanh số dùng số nhiều 'sales'.", u: "Part 4/7 marketing: 'The promotion helped boost sales by 20%'. IELTS Writing về quảng cáo.", f: "boost (v/n), increase sales, drive sales, sales figures (n)" },
  "exceed expectations": { m: "ex (vượt ra) + ceed (đi) → đi vượt qua mức người ta mong đợi.", e: "Sai: exceed the expectation of us → Đúng: exceed our expectations. Sai: excess expectations.", u: "Part 7 đánh giá: 'Sales exceeded expectations this quarter'. IELTS Speaking kể trải nghiệm bất ngờ.", f: "exceed (v), excess (n), excessive (adj), surpass expectations, meet expectations" },
  "address a concern": { m: "address = hướng lời nói vào. Hướng thẳng vào mối lo để xử lý.", e: "Sai: address to the concern → Đúng: address the concern (ngoại động từ, không có 'to').", u: "Part 3/7: 'The manager addressed customers' concerns quickly'. IELTS Writing: address the problem.", f: "address (v), concern (n/v), concerned (adj), deal with, tackle, resolve" },
  "handle a complaint": { m: "handle = tay cầm → cầm lấy khiếu nại mà xử lý tận tay.", e: "Sai: handle a complain → Đúng: handle a complaint. 'complain' là động từ, 'complaint' là danh từ.", u: "Part 3/7 dịch vụ khách hàng: 'Who handles complaints about billing?' Hỏi bộ phận phụ trách.", f: "complain (v), complaint (n), deal with a complaint, file a complaint" },
  "issue a refund": { m: "issue = phát ra (như phát vé). Công ty phát tiền hoàn lại cho khách.", e: "Sai: issue a refundation → Đúng: issue a refund. Sai: refund back the money → Đúng: refund the money.", u: "Part 3/7: 'We will issue a full refund within 5 days'. Hỏi khi nào/cách nhận tiền hoàn.", f: "refund (n/v), refundable (adj), reimburse (v), give a refund, store credit" },
  "place an advertisement": { m: "place = đặt. 'Đặt' mẩu quảng cáo lên báo hoặc website.", e: "Sai: put on an advertise → Đúng: place an advertisement. 'advertise' là động từ.", u: "Part 7: 'We placed an advertisement in the local paper'. Thư tuyển dụng, bán hàng.", f: "advertise (v), advertisement (n), ad (n), advertiser (n), run an ad" },
  "fill a position": { m: "Vị trí trống như chỗ trống → 'lấp đầy' bằng nhân viên mới.", e: "Sai: fill in a position → Đúng: fill a position. 'fill in' dùng cho mẫu đơn.", u: "Part 7 tuyển dụng: 'We hope to fill the position by May'. Hỏi thời hạn tuyển.", f: "fill a vacancy, hire (v), recruit (v), open position (n), vacancy (n)" },
  "submit an application": { m: "apply (nộp đơn) → application. sub+mit = gửi trình lên.", e: "Sai: submit an apply → Đúng: submit an application. Sai: submit application for job → Đúng: for the job.", u: "Part 7: 'Submit your application online by Friday'. Hỏi cách thức và hạn nộp đơn.", f: "apply (v), applicant (n), application (n), application form (n), send in" },
  "undergo training": { m: "under (bên dưới) + go → đi xuyên qua bên dưới quá trình → trải qua.", e: "Sai: undergo a training course to → Đúng: undergo training. Sai: undergone training last year → Đúng: underwent.", u: "Part 7 nhân sự: 'New hires undergo two weeks of training'. Cũng: undergo renovation.", f: "undergo (v), underwent, undergone, go through, receive training" },
  "take effect": { m: "effect = hiệu lực. Luật 'lấy' (take) hiệu lực → bắt đầu áp dụng.", e: "Sai: take affect → Đúng: take effect. Sai: The rule will be taken effect → Đúng: will take effect.", u: "Part 7: 'The new policy takes effect on July 1'. Hỏi ngày có hiệu lực.", f: "effect (n), effective (adj), come into effect, come into force" },
  "enclosed please find": { m: "enclose = gói kèm trong phong bì. Xin tìm thấy thứ gửi kèm bên trong.", e: "Sai: enclose please find → Đúng: Enclosed please find. Lựa chọn tự nhiên hơn: I have enclosed...", u: "Part 7 thư giấy: 'Enclosed please find a copy of the invoice'. Hỏi thư gửi kèm gì.", f: "enclose (v), enclosure (n), enclosed (adj), please find attached" },
  "please find attached": { m: "attach = gắn kèm. Mời bạn tìm thấy tệp đã gắn trong email.", e: "Sai: please find attachment → Đúng: please find attached the file. Sai: attach please find.", u: "Part 7 email: 'Please find attached my résumé'. Hỏi tài liệu đính kèm là gì.", f: "attach (v), attachment (n), attached (adj), I have attached..." },
  "acknowledge receipt": { m: "acknowledge = thừa nhận. receipt = sự nhận được. Thừa nhận đã nhận được.", e: "Sai: acknowledge the receive → Đúng: acknowledge receipt of your letter. Chữ 'p' trong receipt câm.", u: "Part 7 thư từ: 'We acknowledge receipt of your payment'. Hỏi mục đích email.", f: "acknowledge (v), acknowledgment (n), receive (v), receipt (n), confirm receipt" },
  "do not hesitate to contact": { m: "hesitate = do dự. Đừng do dự gì cả, cứ liên hệ.", e: "Sai: do not hesitate contacting → Đúng: do not hesitate to contact us. Sai: contact to us.", u: "Part 7 cuối email: 'If you have questions, do not hesitate to contact me'. Câu kết lịch sự.", f: "hesitate (v), hesitation (n), hesitant (adj), feel free to contact" },
  "look forward to hearing from you": { m: "look forward = nhìn về phía trước → háo hức chờ thư hồi âm.", e: "Sai: look forward to hear from you → Đúng: look forward to hearing from you. 'to' là giới từ.", u: "Part 7/IELTS Writing General thư trang trọng: câu kết kinh điển trước 'Sincerely'.", f: "look forward to + V-ing, hear from (v), I await your reply" },
  "expense report": { m: "expense = khoản chi. Báo cáo kê các khoản đã chi khi đi công tác.", e: "Sai: expenses reports → Đúng: expense reports. Danh từ đứng trước làm tính từ thì giữ số ít.", u: "Part 7: 'Submit your expense report with receipts within 30 days'. Hỏi cần nộp kèm gì.", f: "expense (n), expensive (adj), expend (v), reimbursement (n), expense claim" },
  "travel expenses": { m: "travel (đi lại) + expenses (khoản chi) → tiền vé, khách sạn khi công tác.", e: "Sai: travel expense are covered → Đúng: travel expenses are covered. Sai: travelling fee.", u: "Part 7: 'The company will reimburse travel expenses'. Hỏi ai chi trả.", f: "expense (n), reimburse (v), per diem (n), travel allowance (n), business trip (n)" },
  "quarterly report": { m: "quarter = một phần tư → 1/4 năm = 3 tháng → báo cáo quý.", e: "Sai: quarter report → Đúng: quarterly report. Sai: quarterly reports of first quarter → Đúng: first-quarter report.", u: "Part 4/7: 'The quarterly report shows a rise in profit'. Hỏi xu hướng tài chính.", f: "quarter (n), quarterly (adj/adv), annual report (n), monthly report (n)" },
  "annual report": { m: "annual ≈ 'anniversary' (kỷ niệm năm) → mỗi năm một lần → báo cáo thường niên.", e: "Sai: yearly annual report → Đúng: annual report. Sai: anual (thiếu n).", u: "Part 7: 'The annual report will be released in March'. Cổ đông, tài chính doanh nghiệp.", f: "annual (adj), annually (adv), anniversary (n), annual meeting (n)" },
  "headquarters": { m: "head (đầu não) + quarters (khu nơi ở) → nơi đặt bộ não công ty.", e: "Sai: a headquarter → Đúng: a headquarters / the headquarters (luôn có 's'). Sai: in headquarters → Đúng: at headquarters.", u: "Part 7: 'The company moved its headquarters to Seoul'. Hỏi địa điểm trụ sở.", f: "headquarters (n, viết tắt HQ), headquartered (adj), head office (n), main office" },
  "branch office": { m: "branch = cành cây. Cành mọc ra từ thân chính → văn phòng chi nhánh.", e: "Sai: branch offices of company in → Đúng: the company's branch office in Hanoi.", u: "Part 7: 'She was transferred to the Osaka branch office'. Hỏi nơi làm việc mới.", f: "branch (n/v), branch out (v), head office (n), subsidiary (n)" },
  "customer base": { m: "base = nền móng. Tập khách hàng là nền móng doanh thu.", e: "Sai: customers base → Đúng: customer base. Sai: increase customer base number → Đúng: expand our customer base.", u: "Part 7 marketing: 'We aim to expand our customer base in Asia'. IELTS Writing kinh doanh.", f: "client base (n), clientele (n), customer (n), loyal customers, market share" },
  "feedback survey": { m: "feed back = đưa ngược lại → khách gửi ngược ý kiến qua phiếu khảo sát.", e: "Sai: a feedbacks survey → Đúng: a feedback survey. 'feedback' không đếm được, không thêm s.", u: "Part 4/7: 'Please complete our feedback survey for a discount'. Hỏi người nghe được yêu cầu làm gì.", f: "feedback (n), customer survey (n), questionnaire (n), give feedback" },
  "return policy": { m: "return = trả lại. Chính sách quy định khi nào trả hàng được.", e: "Sai: returning policy → Đúng: return policy. Sai: return back the item → Đúng: return the item.", u: "Part 7: 'Our return policy allows returns within 30 days with a receipt'. Hỏi điều kiện đổi trả.", f: "return (v/n), refund policy (n), exchange (n/v), returnable (adj)" },
  "benefits package": { m: "package = gói. Gói gồm bảo hiểm, nghỉ phép, thưởng → gói phúc lợi.", e: "Sai: benefit packages includes → Đúng: the benefits package includes. Hay dùng 'benefits' số nhiều.", u: "Part 7 tuyển dụng: 'We offer a competitive salary and benefits package'. Hỏi công ty cung cấp gì.", f: "benefit (n/v), beneficial (adj), compensation package (n), perks (n)" },
  "paid leave": { m: "leave = sự nghỉ phép. paid = vẫn được trả lương khi nghỉ.", e: "Sai: paid leaves days → Đúng: paid leave / days of paid leave. Sai: take a paid holiday leave.", u: "Part 7 nhân sự: 'Employees receive 12 days of paid leave per year'. IELTS Speaking về công việc.", f: "leave (n), unpaid leave, annual leave, maternity leave, paid time off (PTO)" },
  "sick leave": { m: "sick (ốm) + leave (nghỉ phép) → nghỉ vì ốm.", e: "Sai: I'm on sick → Đúng: I'm on sick leave. Sai: take sick leave of two days → Đúng: two days of sick leave.", u: "Part 3/7: 'Tom is on sick leave this week'. Hỏi vì sao ai đó vắng mặt.", f: "sick day (n), call in sick (v), medical leave (n), sick note (n)" },
  "probationary period": { m: "probe = thăm dò → thời gian thăm dò năng lực nhân viên mới → thử việc.", e: "Sai: probation period time → Đúng: probationary period. Sai: in probationary → Đúng: on probation.", u: "Part 7 hợp đồng: 'New employees serve a three-month probationary period'. Hỏi độ dài thử việc.", f: "probation (n), probationary (adj), trial period (n), on probation" },
  "performance review": { m: "review = xem lại. Sếp xem lại hiệu suất làm việc của bạn.", e: "Sai: performance reviewing → Đúng: performance review. Sai: do a review performance → Đúng: conduct a performance review.", u: "Part 3/7: 'Annual performance reviews are held in December'. Hỏi liên quan tăng lương.", f: "performance (n), perform (v), appraisal (n), evaluation (n), assess (v)" },
  "job opening": { m: "Vị trí 'đang mở' cửa chờ người vào → vị trí cần tuyển.", e: "Sai: job open → Đúng: job opening. Sai: There is a job opening for apply → Đúng: to apply for.", u: "Part 7: 'We have several job openings in sales'. Quảng cáo tuyển dụng.", f: "opening (n), vacancy (n), job posting (n), position (n), opportunity (n)" },
  "cover letter": { m: "Thư 'phủ' (cover) bên ngoài CV, giới thiệu bản thân → thư xin việc.", e: "Sai: an introduce letter / a cover paper → Đúng: a cover letter. Sai: send cover letter → Đúng: send a cover letter.", u: "Part 7: 'Send a résumé and cover letter to hr@...'. Hỏi hồ sơ cần những gì.", f: "cover letter (n), covering letter (BrE), résumé (n), CV (n), application (n)" },
  "credentials": { m: "cred = tin (như 'credit') → giấy tờ khiến người ta tin năng lực bạn.", e: "Sai: a credential for login → Đúng: login credentials. Thường dùng số nhiều: impressive credentials.", u: "Part 7 tuyển dụng: 'Candidates with strong academic credentials'. IT: user credentials.", f: "credential (n), credible (adj), credibility (n), qualifications (n), credit (n)" },
  "qualified": { m: "quality (chất lượng) → qualified = có đủ chất lượng, tiêu chuẩn.", e: "Sai: qualified to the job → Đúng: qualified for the job. Sai: qualify candidate → Đúng: qualified candidate.", u: "Part 5/7: 'Only qualified applicants will be contacted'. Bẫy từ loại qualify/qualified/qualification.", f: "qualify (v), qualification (n), qualified (adj), unqualified (adj), eligible (adj)" },
  "pending": { m: "pend ≈ 'pendulum' (con lắc) → còn treo lơ lửng, chưa quyết → đang chờ.", e: "Sai: The order is pend → Đúng: The order is pending. Sai: pending of approval → Đúng: pending approval.", u: "Part 7: 'Your application is pending review'. Hỏi trạng thái đơn hàng, hồ sơ.", f: "pending (adj/prep), pend (v, hiếm), awaiting (adj), outstanding (adj)" },
  "proprietary": { m: "proprietor = chủ sở hữu → thuộc về riêng chủ → độc quyền.", e: "Sai: propriety software → Đúng: proprietary software. 'propriety' là sự đúng mực.", u: "Part 7/công nghệ: 'proprietary technology', 'proprietary information'. Hợp đồng bảo mật.", f: "proprietor (n), property (n), proprietary (adj), patented (adj), exclusive (adj)" },
  "authorized": { m: "author (tác giả, người có quyền) → authorized = được trao quyền.", e: "Sai: authorize personnel only → Đúng: authorized personnel only. Sai: be authorized for sign → Đúng: authorized to sign.", u: "Part 1/7 biển báo: 'Authorized personnel only'. Part 5 từ loại.", f: "authorize (v), authority (n), authorization (n), unauthorized (adj), authorized dealer" },
  "sign off on": { m: "Hình ảnh: ký tên ở cuối văn bản để chốt lại → phê duyệt.", e: "Sai: sign off the budget → Đúng: sign off on the budget. Sai: sign on → nghĩa khác (đăng ký).", u: "Part 3/7: 'The director needs to sign off on the design'. Hỏi ai cần phê duyệt.", f: "sign-off (n), approve (v), green-light (v), give the go-ahead" },
  "notification": { m: "notify (báo cho biết) → notification = tin báo, như thông báo trên điện thoại.", e: "Sai: I received a notify → Đúng: I received a notification. Sai: notification for the change → Đúng: notification of the change.", u: "Part 7: 'You will receive a notification by email'. Thông báo đơn hàng, cập nhật hệ thống.", f: "notify (v), notice (n), notification (n), notifiable (adj), alert (n)" },
  "accommodations": { m: "accommodate = chứa, cho ở → accommodations = chỗ ăn ở cho khách.", e: "Sai: accomodations → Đúng: accommodations (2 c, 2 m). Anh-Anh thường dùng số ít: accommodation.", u: "Part 7 công tác: 'Accommodations will be provided for speakers'. Hỏi ai lo chỗ ở.", f: "accommodate (v), accommodation (n), lodging (n), housing (n)" },
  "onboarding": { m: "Hình ảnh: đưa người mới 'lên tàu' (on board) cùng đội → hội nhập nhân viên mới.", e: "Sai: on-boarding process for new staffs → Đúng: the onboarding process for new staff. 'staff' không thêm s.", u: "Part 7 nhân sự: 'Onboarding includes a tour and IT setup'. Ngành HR: onboarding checklist.", f: "onboard (v), on board (adv), orientation (n), induction (n, BrE)" },
  "punctually": { m: "punct = điểm (như 'punctuation' – dấu chấm) → đến đúng điểm giờ hẹn.", e: "Sai: arrive punctual → Đúng: arrive punctually. Sai: punctually on time (thừa ý).", u: "Part 5 từ loại: trạng từ bổ nghĩa động từ: 'The meeting started punctually at 9'.", f: "punctual (adj), punctuality (n), punctually (adv), on time, promptly" },
  "solely": { m: "sole = duy nhất (như 'solo' – đơn ca) → solely = chỉ một mình.", e: "Sai: solely responsible of → Đúng: solely responsible for. Sai: soley (sai chính tả).", u: "Part 5/7: 'The tenant is solely responsible for repairs'. Văn bản hợp đồng, miễn trừ.", f: "sole (adj), solely (adv), only (adv), exclusively (adv), entirely (adv)" },
  "markedly": { m: "mark = đánh dấu → thay đổi rõ đến mức để lại dấu → rõ rệt.", e: "Sai: increase markly → Đúng: increase markedly. Phát âm: MAR-kid-ly (3 âm tiết).", u: "Part 5/IELTS Writing Task 1: 'Sales rose markedly in 2020'. Thay cho 'significantly'.", f: "mark (n/v), marked (adj), markedly (adv), noticeably (adv), significantly (adv)" },
  "tremendously": { m: "tremble = run rẩy → to lớn đến mức làm người ta run → vô cùng.", e: "Sai: tremendous helpful → Đúng: tremendously helpful. Trạng từ bổ nghĩa tính từ.", u: "Part 5/7: 'The workshop was tremendously successful'. IELTS Speaking nhấn mạnh cảm xúc.", f: "tremendous (adj), tremendously (adv), enormously (adv), immensely (adv)" },
  "readily": { m: "ready (sẵn sàng) → readily = sẵn lòng, có sẵn dễ dàng.", e: "Sai: readyly / ready available → Đúng: readily available. Sai: agree ready → Đúng: readily agree.", u: "Part 5/7: 'Spare parts are readily available'. Hay đi với available, accessible, agree.", f: "ready (adj), readily (adv), readiness (n), easily (adv), willingly (adv)" },
  "diligently": { m: "Gốc Latin diligere = yêu quý → yêu việc nên làm chăm chỉ, cần mẫn.", e: "Sai: work diligent → Đúng: work diligently. Sai: diligence work → Đúng: diligent work.", u: "Part 5/7 thư khen: 'She worked diligently on the project'. IELTS Speaking mô tả tính cách.", f: "diligent (adj), diligence (n), diligently (adv), industriously (adv), hard-working (adj)" },
  "collaboratively": { m: "co (cùng) + labor (lao động) → cùng nhau lao động → một cách hợp tác.", e: "Sai: work collaborative → Đúng: work collaboratively. Sai: collaborate together (thừa ý).", u: "Part 5/7: 'Teams worked collaboratively across departments'. IELTS Writing giáo dục, làm việc nhóm.", f: "collaborate (v), collaboration (n), collaborative (adj), collaborator (n), jointly (adv)" },
  "conveniently located": { m: "convenient (tiện) + located (đặt ở) → đặt ở chỗ tiện đi lại.", e: "Sai: convenient located → Đúng: conveniently located. Sai: located conveniently near to → Đúng: conveniently located near.", u: "Part 7 quảng cáo khách sạn, căn hộ: 'conveniently located near the subway'. Hỏi ưu điểm vị trí.", f: "convenience (n), convenient (adj), centrally located, within walking distance" },
  "highly recommended": { m: "highly = ở mức cao. Được giới thiệu ở mức cao → rất nên dùng.", e: "Sai: high recommended → Đúng: highly recommended. Sai: recommend highly to buy → Đúng: highly recommend buying.", u: "Part 7 đánh giá, review: 'This restaurant comes highly recommended'. IELTS Speaking giới thiệu nơi chốn.", f: "recommend (v), recommendation (n), highly (adv), strongly recommend, must-try" },
  "fully refundable": { m: "refund (hoàn tiền) + able + fully (toàn bộ) → được hoàn lại hết tiền.", e: "Sai: full refundable → Đúng: fully refundable. Sai: refundable fully ticket → Đúng: fully refundable ticket.", u: "Part 7 vé, đặt phòng: 'Tickets are fully refundable until 48 hours before'. Hỏi điều kiện hủy.", f: "refund (n/v), refundable (adj), non-refundable (adj), partially refundable" },
  "competitively priced": { m: "compete (cạnh tranh) → giá đặt ở mức cạnh tranh được với đối thủ.", e: "Sai: competitive priced → Đúng: competitively priced. Sai: price competitively products → Đúng: competitively priced products.", u: "Part 7 quảng cáo: 'Our products are high quality and competitively priced'. Part 5 trạng từ + V3.", f: "compete (v), competitive (adj), competition (n), reasonably priced, affordable (adj)" },
  "widely regarded as": { m: "widely = rộng rãi. Nhiều người khắp nơi 'coi' (regard) là như vậy.", e: "Sai: widely regarded to be as → Đúng: widely regarded as. Sai: wide regarded → Đúng: widely regarded.", u: "Part 7 tiểu sử: 'She is widely regarded as a leading architect'. IELTS Writing dẫn ý kiến chung.", f: "regard (v), widely considered, generally seen as, renowned (adj)" },
  "mutually beneficial": { m: "mutual = hai chiều. beneficial = có lợi. Lợi ích chảy về cả hai phía.", e: "Sai: mutual beneficial → Đúng: mutually beneficial. Sai: beneficial for both of each.", u: "Part 7 hợp tác: 'a mutually beneficial partnership'. IELTS Writing về hợp tác quốc tế.", f: "mutual (adj), mutually (adv), benefit (n/v), beneficial (adj), win-win (adj)" },
  "newly appointed": { m: "appoint = bổ nhiệm. newly = vừa mới → vừa được bổ nhiệm.", e: "Sai: new appointed manager → Đúng: newly appointed manager. Sai: appointed newly.", u: "Part 4/7: 'Please welcome our newly appointed CEO'. Thông báo nhân sự.", f: "appoint (v), appointment (n), appointee (n), newly hired, newly elected" },
  "long-standing": { m: "Đã 'đứng' (standing) đó rất lâu (long) → lâu năm, bền vững.", e: "Sai: long-stand client → Đúng: long-standing client. Sai: longstanding of relationship → Đúng: a long-standing relationship.", u: "Part 7: 'our long-standing partnership with ABC Corp'. Hỏi mối quan hệ lâu năm.", f: "long-standing (adj), long-term (adj), established (adj), longtime (adj)" },
  "cost-effective": { m: "cost (chi phí) + effective (hiệu quả) → bỏ ít tiền mà hiệu quả cao.", e: "Sai: cost-effectively solution → Đúng: a cost-effective solution. Sai: cost effective (thiếu gạch nối khi đứng trước danh từ).", u: "Part 7/IELTS Writing: 'Public transport is a cost-effective option'. Đề xuất giải pháp.", f: "cost-effectiveness (n), cost-effectively (adv), economical (adj), cost-efficient (adj)" },
  "top priority": { m: "priority = điều đặt lên trước. top = hàng đầu → việc phải làm trước nhất.", e: "Sai: the most top priority → Đúng: a top priority. Sai: priority top of us → Đúng: our top priority.", u: "Part 4/7: 'Customer safety is our top priority'. IELTS Writing nêu ưu tiên chính phủ.", f: "prior (adj), priority (n), prioritize (v), first priority, high priority" },
  "in high demand": { m: "demand = nhu cầu. Nhu cầu ở mức cao → nhiều người cần, hàng bán chạy.", e: "Sai: in high demanding → Đúng: in high demand. Sai: high on demand → Đúng: in high demand.", u: "Part 7/IELTS Writing: 'IT skills are in high demand'. Thị trường lao động, sản phẩm hot.", f: "demand (n/v), demanding (adj), sought-after (adj), popular (adj), in short supply" },
  "algorithm": { m: "Từ tên nhà toán học al-Khwarizmi → chuỗi bước tính toán rõ ràng → thuật toán.", e: "Sai: algorythm → Đúng: algorithm. Sai: an algorithm sort the data → Đúng: an algorithm for sorting the data.", u: "Ngành IT: 'optimize the sorting algorithm', 'time complexity of an algorithm'. Phỏng vấn kỹ thuật hay hỏi.", f: "algorithm (n), algorithmic (adj), algorithmically (adv), procedure (n), heuristic (n)" },
  "source code": { m: "source = nguồn. Mã 'nguồn' gốc do lập trình viên viết, trước khi biên dịch.", e: "Sai: source codes → Đúng: source code (không đếm được). Sai: the code source → Đúng: the source code.", u: "Ngành IT: 'review the source code', 'open the source code on GitHub'. Văn bản bản quyền phần mềm.", f: "code (n/v), codebase (n), open-source (adj), binary (n), compile (v)" },
  "programming language": { m: "Ngôn ngữ để 'nói chuyện' với máy tính, như Python, Java.", e: "Sai: program language → Đúng: programming language. Sai: speak a programming language → Đúng: write in / use a programming language.", u: "Ngành IT: 'Which programming languages do you know?' CV, phỏng vấn lập trình viên.", f: "program (n/v), programmer (n), programming (n), coding language, scripting language" },
  "compiler": { m: "compile = gom lại → gom mã nguồn chuyển thành mã máy chạy được.", e: "Sai: the compiler is compile → Đúng: the compiler compiles. Nhầm compiler với interpreter (thông dịch).", u: "Ngành IT: 'The compiler throws an error on line 12'. Báo lỗi build, cấu hình C/C++.", f: "compile (v), compilation (n), compiler (n), interpreter (n), transpiler (n)" },
  "debug": { m: "de (gỡ bỏ) + bug (con bọ, lỗi) → bắt bọ khỏi chương trình.", e: "Sai: debug the bugs out → Đúng: debug the code. Sai: debuged → Đúng: debugged (gấp đôi g).", u: "Ngành IT: 'I spent hours debugging the login issue'. Họp daily, báo cáo tiến độ.", f: "debug (v), debugger (n), debugging (n), bug (n), troubleshoot (v)" },
  "loop": { m: "Hình ảnh: vòng dây khép kín → lệnh chạy đi chạy lại thành vòng.", e: "Sai: the loop is never stop → Đúng: the loop never stops (infinite loop). Sai: for-loop of each.", u: "Ngành IT: 'use a for loop to iterate over the list', 'break out of the loop'.", f: "loop (n/v), for loop, while loop, infinite loop, iterate (v), iteration (n)" },
  "array": { m: "array = dàn hàng ngay ngắn → các phần tử xếp thành hàng có chỉ số.", e: "Sai: an arrays → Đúng: an array / arrays. Sai: array start from 1 → Đúng: arrays usually start at index 0.", u: "Ngành IT: 'store the values in an array', 'array index out of bounds'.", f: "array (n), list (n), index (n), element (n), matrix (n), an array of" },
  "integer": { m: "integer = nguyên vẹn (như 'integrity') → số nguyên, không có phần lẻ.", e: "Sai: interger → Đúng: integer. Phát âm: IN-ti-jer, chữ g đọc /dʒ/.", u: "Ngành IT: 'the function returns an integer', 'integer overflow'. Toán và lập trình.", f: "integer (n), int (viết tắt), float (n), decimal (n), whole number" },
  "boolean": { m: "Từ tên nhà toán học George Boole → chỉ có hai giá trị true/false.", e: "Sai: boolean value is yes or no → Đúng: a boolean is true or false. Thường viết hoa: Boolean.", u: "Ngành IT: 'the function returns a boolean', 'boolean flag', toán tử AND/OR/NOT.", f: "Boolean (n/adj), bool (viết tắt), true/false, flag (n), logical operator" },
  "data type": { m: "type = loại. Mỗi dữ liệu thuộc một 'loại': số, chuỗi, đúng/sai.", e: "Sai: datatypes of variable is → Đúng: the variable's data type is. Viết 'data type' tách hai chữ.", u: "Ngành IT: 'string and integer are basic data types'. Thiết kế database, khai báo biến.", f: "data (n), type (n), primitive type, string (n), integer (n), type casting" },
  "object-oriented programming": { m: "Lập trình xoay quanh 'đối tượng' như đồ vật thật: có thuộc tính và hành vi.", e: "Sai: object-orientated programing → Đúng: object-oriented programming (2 m). Viết tắt: OOP.", u: "Ngành IT: phỏng vấn hỏi 4 tính chất OOP: encapsulation, inheritance, polymorphism, abstraction.", f: "OOP (n), object (n), class (n), object-oriented (adj), functional programming" },
  "inheritance": { m: "inherit = thừa kế tài sản → lớp con thừa kế thuộc tính lớp cha.", e: "Sai: inheritage → Đúng: inheritance. Sai: class B inherits of A → Đúng: class B inherits from A.", u: "Ngành IT/OOP: 'use inheritance to reuse code'. Ngoài IT: thừa kế tài sản, luật.", f: "inherit (v), inheritance (n), heir (n), parent class, subclass (n)" },
  "application programming interface": { m: "interface = mặt tiếp giáp. Cổng giao tiếp để hai phần mềm nói chuyện với nhau.", e: "Sai: application program interfaces → Đúng: application programming interface. Thường viết tắt API.", u: "Ngành IT: tài liệu kỹ thuật, 'The application programming interface (API) allows...'. Viết đầy đủ ở lần đầu.", f: "API (n), interface (n), endpoint (n), SDK (n), REST API" },
  "api": { m: "A-P-I: Application Programming Interface. Như người phục vụ nhận order giữa khách và bếp.", e: "Sai: an API key of → Đúng: an API key for. Đọc từng chữ: ây-pi-ai, không đọc 'a-pi'.", u: "Ngành IT: 'call the API', 'API documentation', 'API rate limit'. Họp kỹ thuật, tích hợp hệ thống.", f: "API (n), API key (n), API call (n), endpoint (n), REST, GraphQL" },
  "endpoint": { m: "end (cuối) + point (điểm) → điểm cuối đường dẫn nơi API nhận yêu cầu.", e: "Sai: end point of API is wrong → Đúng: the API endpoint is wrong. Viết liền: endpoint.", u: "Ngành IT: 'call the /users endpoint', 'endpoint returns 404'. Tài liệu API.", f: "endpoint (n), URL (n), route (n), API (n), request (n), response (n)" },
  "user interface": { m: "interface = bề mặt giao tiếp. Phần người dùng nhìn và bấm vào.", e: "Sai: user's interface → Đúng: user interface (UI). Sai: an UI → Đúng: a UI (đọc 'diu-ai').", u: "Ngành IT/thiết kế: 'The new UI is cleaner'. IELTS Speaking về app yêu thích.", f: "UI (n), interface (n), user experience (UX), GUI (n), layout (n)" },
  "user experience": { m: "experience = trải nghiệm. Cảm giác của người dùng khi dùng sản phẩm.", e: "Sai: user experiences design → Đúng: user experience design (UX design). Sai: an UX → Đúng: a UX.", u: "Ngành IT/sản phẩm: 'improve the user experience', 'UX research'. Phân biệt UI (giao diện) và UX (trải nghiệm).", f: "UX (n), UX designer (n), usability (n), user interface (UI), customer experience" },
  "front end": { m: "front = phía trước. Phần mặt tiền người dùng nhìn thấy trên màn hình.", e: "Sai: front-end is → Đúng: the front end is (danh từ, không gạch nối). Tính từ: front-end developer.", u: "Ngành IT: 'React is used for the front end'. Tuyển dụng: front-end developer.", f: "front-end (adj), back end (n), client side (n), frontend (cách viết liền)" },
  "back end": { m: "back = phía sau. Phần 'hậu trường' sau sân khấu: máy chủ, cơ sở dữ liệu.", e: "Sai: the back-end store data → Đúng: the back end stores data. Tính từ có gạch nối: back-end server.", u: "Ngành IT: 'The back end is built with Node.js'. Mô tả kiến trúc hệ thống.", f: "back-end (adj), server side (n), front end (n), backend (cách viết liền)" },
  "full-stack developer": { m: "stack = chồng lớp. Làm được cả chồng: front end lẫn back end.", e: "Sai: full stack developper → Đúng: full-stack developer. 'developer' chỉ có một p.", u: "Ngành IT tuyển dụng: 'We're hiring a full-stack developer'. CV, LinkedIn.", f: "full stack (n), tech stack (n), front-end developer, back-end developer" },
  "operating system": { m: "operate = vận hành. Hệ thống vận hành mọi phần của máy: Windows, macOS.", e: "Sai: operation system → Đúng: operating system (OS). Sai: install an OS new → Đúng: install a new OS.", u: "Ngành IT: 'Which operating system does the app support?' Yêu cầu hệ thống phần mềm.", f: "OS (n), operate (v), operation (n), kernel (n), Windows, Linux" },
  "web browser": { m: "browse = xem lướt (như lướt sách) → phần mềm để lướt web.", e: "Sai: web browse → Đúng: web browser. Sai: open the web by browser → Đúng: open the page in a browser.", u: "Ngành IT: 'supported web browsers: Chrome, Firefox'. Hướng dẫn kỹ thuật, kiểm thử.", f: "browse (v), browser (n), browsing (n), browser extension (n), search engine (n)" },
  "domain name": { m: "domain = lãnh địa. Tên miền là 'tên lãnh thổ' của website trên mạng.", e: "Sai: domain names is → Đúng: the domain name is. Sai: buy a domain's name → Đúng: register a domain name.", u: "Ngành IT/marketing: 'register a domain name', 'domain name renewal'. Lập website doanh nghiệp.", f: "domain (n), DNS (n), subdomain (n), URL (n), hosting (n)" },
  "ip address": { m: "IP = Internet Protocol. Địa chỉ nhà của thiết bị trên mạng Internet.", e: "Sai: an IP adress → Đúng: an IP address (2 d, 2 s). Đọc 'an' vì 'IP' bắt đầu bằng nguyên âm.", u: "Ngành IT/mạng: 'block the IP address', 'static IP address'. Bảo mật, cấu hình máy chủ.", f: "IP (n), IPv4, IPv6, address (n), subnet (n), DNS (n)" },
  "bandwidth": { m: "band (dải) + width (chiều rộng) → độ rộng 'ống' truyền dữ liệu.", e: "Sai: bandwidths high → Đúng: high bandwidth. Nghĩa bóng: I don't have the bandwidth = không có thời gian.", u: "Ngành IT: 'video calls use a lot of bandwidth'. Văn phòng: 'no bandwidth for new tasks'.", f: "bandwidth (n), throughput (n), latency (n), speed (n), capacity (n)" },
  "latency": { m: "latent = ẩn, chậm lộ ra → khoảng trễ trước khi dữ liệu tới nơi.", e: "Sai: the latency is fast → Đúng: the latency is low. Latency đo bằng thời gian, cao/thấp chứ không nhanh/chậm.", u: "Ngành IT/game: 'reduce network latency', 'low-latency streaming'. Đánh giá hiệu năng.", f: "latent (adj), latency (n), delay (n), lag (n), ping (n), bandwidth (n)" },
  "router": { m: "route = tuyến đường → router chỉ đường cho gói dữ liệu đi đúng nơi.", e: "Sai: rooter → Đúng: router. Anh-Mỹ đọc 'rao-tơ', Anh-Anh đọc 'ru-tơ'; đừng nhầm với modem.", u: "Ngành IT: 'restart the router', 'configure the Wi-Fi router'. Hỗ trợ kỹ thuật văn phòng.", f: "route (n/v), router (n), routing (n), modem (n), switch (n), gateway (n)" },
  "firewall": { m: "Hình ảnh: bức tường chống cháy lan → chặn truy cập nguy hiểm vào mạng.", e: "Sai: fire wall → Đúng: firewall (viết liền). Sai: firewall blocked to the port → Đúng: the firewall blocked the port.", u: "Ngành IT/bảo mật: 'configure firewall rules', 'the request was blocked by the firewall'.", f: "firewall (n), firewall rule (n), antivirus (n), proxy (n), network security" },
  "cloud computing": { m: "Dữ liệu và máy chủ 'bay' trên đám mây Internet, không nằm trong máy bạn.", e: "Sai: cloud computer service → Đúng: cloud computing service. Sai: on cloud → Đúng: in the cloud.", u: "Ngành IT: 'migrate to cloud computing (AWS, Azure)'. IELTS Writing về công nghệ, doanh nghiệp.", f: "cloud (n), cloud-based (adj), cloud storage (n), SaaS, on-premises (adj)" },
  "virtual machine": { m: "virtual = ảo. Chiếc máy tính 'ảo' chạy bên trong máy thật.", e: "Sai: virtual machines is → Đúng: virtual machines are. Viết tắt VM: 'spin up a VM'.", u: "Ngành IT: 'run tests in a virtual machine', 'VM instance on the cloud'. Kiểm thử, triển khai.", f: "VM (n), virtual (adj), virtualization (n), hypervisor (n), container (n)" },
  "virtualization": { m: "virtual (ảo) + -ize (biến thành) + -ation → quá trình biến phần cứng thành tài nguyên ảo.", e: "Sai: virtualisation và virtualization lẫn lộn trong một văn bản → chọn một kiểu Anh-Mỹ (z) hoặc Anh-Anh (s).", u: "Ngành IT: 'server virtualization cuts hardware costs'. Hạ tầng trung tâm dữ liệu.", f: "virtual (adj), virtualize (v), virtualization (n), virtually (adv), hypervisor (n)" },
  "microservice": { m: "micro (nhỏ) + service → chia ứng dụng thành nhiều dịch vụ nhỏ độc lập.", e: "Sai: a microservices → Đúng: a microservice / microservices architecture. Sai: micro service (nên viết liền).", u: "Ngành IT: 'split the monolith into microservices'. Thiết kế kiến trúc phần mềm.", f: "microservice (n), microservices architecture, monolith (n), service (n), API (n)" },
  "scalability": { m: "scale = thang, quy mô. Khả năng tăng quy mô mà vẫn chạy ổn.", e: "Sai: scalibility → Đúng: scalability. Sai: the system is scalability → Đúng: the system is scalable.", u: "Ngành IT: 'design for scalability', 'horizontal scalability'. Phỏng vấn system design.", f: "scale (n/v), scalable (adj), scalability (n), scale up, scale out" },
  "deploy": { m: "Gốc quân sự: triển khai quân ra trận → đưa phần mềm ra môi trường chạy thật.", e: "Sai: deploy the app to live → Đúng: deploy the app to production. Sai: deployed on yesterday.", u: "Ngành IT: 'We deploy to production every Friday'. Quân sự: deploy troops.", f: "deploy (v), deployment (n), redeploy (v), release (v/n), roll out (v)" },
  "deployment": { m: "deploy + -ment → sự triển khai, một lần phát hành phần mềm.", e: "Sai: make a deploy → Đúng: do a deployment / deploy. Sai: deployments fails → Đúng: the deployment failed.", u: "Ngành IT: 'the deployment failed', 'automated deployment pipeline'. Báo cáo sự cố.", f: "deploy (v), deployment (n), release (n), rollout (n), rollback (n)" },
  "version control": { m: "Kiểm soát (control) từng phiên bản (version) của mã → quay lại bản cũ được.", e: "Sai: version controlling system → Đúng: version control system (VCS). Sai: control version.", u: "Ngành IT: 'use Git for version control'. CV lập trình viên, quy trình làm việc nhóm.", f: "version (n), version control system (VCS), Git, commit (n/v), branch (n)" },
  "repository": { m: "reposit- = cất giữ lại → nơi cất giữ mã nguồn → kho mã (repo).", e: "Sai: repositary → Đúng: repository. Sai: push code in repo → Đúng: push code to the repo.", u: "Ngành IT: 'clone the repository', 'private repo on GitHub'. Ngoài IT: kho lưu trữ tài liệu.", f: "repository (n), repo (viết tắt), clone (v), fork (n/v), deposit (v)" },
  "code review": { m: "review = xem lại. Đồng nghiệp đọc lại mã của bạn trước khi gộp.", e: "Sai: review code for me (thiếu mạo từ) → Đúng: review my code. Sai: do a code reviewing → Đúng: do a code review.", u: "Ngành IT: 'request a code review', 'leave comments in the code review'. Quy trình pull request.", f: "review (n/v), reviewer (n), pull request (PR), peer review (n), feedback (n)" },
  "open source": { m: "Mã nguồn để 'mở' cho ai cũng xem, sửa, dùng miễn phí.", e: "Sai: opened source software → Đúng: open-source software (có gạch nối khi đứng trước danh từ).", u: "Ngành IT: 'contribute to open-source projects'. CV lập trình viên, giấy phép MIT, GPL.", f: "open-source (adj), open source (n), proprietary (adj), license (n), contributor (n)" },
  "software development life cycle": { m: "Life cycle = vòng đời: phần mềm 'sinh ra, lớn lên': lên yêu cầu → thiết kế → code → test → bảo trì.", e: "Sai: software developing life circle → Đúng: software development life cycle (SDLC). 'cycle' không phải 'circle'.", u: "Ngành IT/quản lý dự án: 'phases of the SDLC'. Phỏng vấn QA, BA.", f: "SDLC (n), life cycle (n), waterfall (n), agile (adj), development (n)" },
  "agile": { m: "agile = nhanh nhẹn → làm việc linh hoạt, chia nhỏ, thay đổi nhanh.", e: "Sai: agility methodology → Đúng: agile methodology. Đọc 'á-giồ', không đọc 'a-gai'.", u: "Ngành IT: 'We follow Agile with two-week sprints'. Ngoài IT: an agile mind (đầu óc nhanh nhạy).", f: "agile (adj), agility (n), Scrum (n), Kanban (n), sprint (n), waterfall (n)" },
  "sprint": { m: "sprint = chạy nước rút → đoạn làm việc ngắn, dồn sức hoàn thành mục tiêu.", e: "Sai: in this sprint time → Đúng: in this sprint. Sai: sprint planning meet → Đúng: sprint planning meeting.", u: "Ngành IT/Agile: 'two-week sprint', 'sprint review', 'sprint retrospective'. Họp Scrum.", f: "sprint (n/v), sprinter (n), iteration (n), Scrum (n), sprint backlog" },
  "backlog": { m: "Hình ảnh: khúc gỗ dồn phía sau lò sưởi chờ đốt → việc tồn đọng chờ làm.", e: "Sai: backlogs of work is → Đúng: the backlog of work is. Sai: back log (nên viết liền).", u: "Ngành IT: 'add it to the product backlog'. Văn phòng: 'a backlog of orders/emails'.", f: "backlog (n), product backlog, sprint backlog, pending tasks, to-do list" },
  "unit test": { m: "unit = đơn vị nhỏ nhất. Kiểm thử từng hàm nhỏ riêng lẻ.", e: "Sai: unit testing a function is → Đúng: write a unit test for the function. Sai: unit tests is passed.", u: "Ngành IT: 'all unit tests passed', 'increase unit test coverage'. Code review, CI.", f: "unit test (n), unit testing (n), test case (n), test coverage (n), integration test" },
  "integration testing": { m: "integrate = ghép lại. Kiểm thử khi ghép các mô-đun chạy cùng nhau.", e: "Sai: integrate testing → Đúng: integration testing. Đừng nhầm với unit testing (kiểm thử riêng lẻ).", u: "Ngành IT/QA: 'integration testing between the API and database'. Kế hoạch kiểm thử.", f: "integrate (v), integration (n), unit testing, end-to-end testing, system testing" },
  "quality assurance": { m: "assure = đảm bảo. Đảm bảo chất lượng trước khi giao sản phẩm.", e: "Sai: quality insurance → Đúng: quality assurance (QA). 'insurance' là bảo hiểm.", u: "Ngành IT/sản xuất: 'QA engineer', 'pass QA before release'. Phân biệt với quality control (QC).", f: "assure (v), assurance (n), QA (n), quality control (QC), tester (n)" },
  "regression": { m: "re (lùi) + gress (đi) → đi lùi: tính năng cũ đang chạy bỗng hỏng lại.", e: "Sai: regress bug → Đúng: regression bug. Sai: do regression → Đúng: run regression tests.", u: "Ngành IT: 'the update caused a regression'. Thống kê: regression analysis (hồi quy).", f: "regress (v), regression (n), regressive (adj), regression test (n), progress (n)" },
  "continuous integration": { m: "continuous = liên tục. Liên tục ghép mã mới vào nhánh chính và tự chạy test.", e: "Sai: continuously integration → Đúng: continuous integration (CI). Tính từ bổ nghĩa danh từ.", u: "Ngành IT/DevOps: 'the CI pipeline failed', 'CI/CD'. Quy trình tự động build, test.", f: "CI (n), continuous delivery (CD), pipeline (n), build (n), DevOps (n)" },
  "script": { m: "script = kịch bản → danh sách lệnh để máy làm theo từng bước.", e: "Sai: write a scripting → Đúng: write a script. Sai: run the script by manual → Đúng: run the script manually.", u: "Ngành IT: 'write a Python script to automate reports'. Phim ảnh: kịch bản phim.", f: "script (n/v), scripting (n), scripted (adj), scriptwriter (n), shell script" },
  "command line": { m: "Gõ lệnh trên một 'dòng' (line) chữ thay vì bấm chuột.", e: "Sai: type in command line → Đúng: type it on the command line. Tính từ: command-line tool.", u: "Ngành IT: 'run this from the command line'. Hướng dẫn cài đặt phần mềm.", f: "command line (n), command-line (adj), terminal (n), CLI (n), shell (n)" },
  "syntax": { m: "syn (cùng) + tax (sắp xếp) → cách sắp xếp chữ cho đúng luật → cú pháp.", e: "Sai: a syntax error in → Đúng: a syntax error on line 5. Sai: syntaxes rules → Đúng: syntax rules.", u: "Ngành IT: 'syntax error', 'Python syntax'. Ngôn ngữ học: cú pháp câu.", f: "syntax (n), syntactic (adj), syntactically (adv), grammar (n), semantics (n)" },
  "runtime": { m: "run (chạy) + time → lúc chương trình đang chạy / môi trường để nó chạy.", e: "Sai: run time error → Đúng: runtime error. Sai: in the runtime of compile → phân biệt runtime và compile time.", u: "Ngành IT: 'runtime error', 'Node.js runtime', 'reduce runtime'. Báo cáo lỗi.", f: "runtime (n/adj), compile time (n), execution (n), run (v), environment (n)" },
  "memory leak": { m: "leak = rò rỉ. Bộ nhớ bị 'rỉ' dần, không được trả lại → máy chậm dần.", e: "Sai: memory leaking problem → Đúng: memory leak. Sai: leak of memory → Đúng: a memory leak.", u: "Ngành IT: 'fix a memory leak in the app'. Báo cáo lỗi hiệu năng.", f: "leak (n/v), leakage (n), memory (n), garbage collection (n), memory usage" },
  "cache": { m: "Đọc giống 'cash' (tiền). Nơi cất sẵn dữ liệu để lấy nhanh như tiền trong túi.", e: "Sai: cache đọc là 'cát-chê' → Đúng: đọc /kæʃ/ như 'cash'. Sai: clean cache → Đúng: clear the cache.", u: "Ngành IT: 'clear your browser cache', 'cache the results'. Hướng dẫn hỗ trợ kỹ thuật.", f: "cache (n/v), cached (adj), caching (n), buffer (n), memory (n)" },
  "processor": { m: "process = xử lý. Bộ phận xử lý mọi lệnh của máy → CPU.", e: "Sai: processer → Đúng: processor. Sai: a processor of 8 cores → Đúng: an 8-core processor.", u: "Ngành IT: 'a faster processor', 'quad-core processor'. Mô tả cấu hình máy tính.", f: "process (n/v), processor (n), processing (n), CPU (n), chip (n), core (n)" },
  "ram": { m: "Random Access Memory: bộ nhớ truy cập ngẫu nhiên, mất dữ liệu khi tắt máy.", e: "Sai: RAM memory (thừa vì M là memory) → Đúng: RAM. Sai: 8G RAM → Đúng: 8 GB of RAM.", u: "Ngành IT: 'upgrade the RAM to 16 GB'. Mô tả cấu hình laptop, điện thoại.", f: "RAM (n), memory (n), ROM (n), storage (n), SSD (n), GB (gigabyte)" },
  "peripheral": { m: "peri (xung quanh) → thiết bị ở xung quanh máy chính: chuột, máy in.", e: "Sai: peripherical → Đúng: peripheral. Sai: a peripherals → Đúng: a peripheral / peripherals.", u: "Ngành IT: 'connect peripherals via USB'. Nghĩa thường: peripheral issue = vấn đề phụ.", f: "periphery (n), peripheral (n/adj), peripherally (adv), device (n), accessory (n)" },
  "firmware": { m: "firm (cứng, chắc) + ware → phần mềm gắn chặt vào phần cứng.", e: "Sai: firmwares → Đúng: firmware (không đếm được). Sai: update a firmware → Đúng: update the firmware.", u: "Ngành IT: 'install the latest firmware update for the router'. Hỗ trợ kỹ thuật thiết bị.", f: "firmware (n), software (n), hardware (n), firmware update, BIOS (n)" },
  "backup": { m: "back up = chống lưng → bản sao giữ sẵn phía sau phòng khi mất.", e: "Sai: backup your files (động từ) → Đúng: back up your files. Danh từ viết liền: a backup.", u: "Ngành IT: 'make a daily backup', 'restore from backup'. Văn phòng: backup plan.", f: "back up (v), backup (n/adj), backup plan (n), restore (v), copy (n)" },
  "data recovery": { m: "recover = lấy lại sức → lấy lại dữ liệu đã mất hoặc hỏng.", e: "Sai: recovery data → Đúng: data recovery. Sai: data recover service → Đúng: data recovery service.", u: "Ngành IT: 'data recovery after a disk failure'. Kế hoạch dự phòng thảm họa.", f: "recover (v), recovery (n), recoverable (adj), backup (n), restore (v)" },
  "cybersecurity": { m: "cyber (không gian mạng) + security (an ninh) → bảo vệ trên mạng.", e: "Sai: cyber security's threat → Đúng: cybersecurity threat. Sai: cybersecurities (không đếm được).", u: "Ngành IT: 'invest in cybersecurity'. IELTS Writing về công nghệ, tội phạm mạng.", f: "cyber (adj), cybercrime (n), cyberattack (n), information security, infosec" },
  "encryption": { m: "en (vào) + crypt (giấu kín) → giấu dữ liệu vào dạng mã → mã hóa.", e: "Sai: encription → Đúng: encryption. Sai: encrypt the data by password → Đúng: encrypt the data with a key.", u: "Ngành IT: 'end-to-end encryption', 'data encryption at rest'. Chính sách bảo mật.", f: "encrypt (v), encryption (n), decrypt (v), decryption (n), encrypted (adj), cryptography (n)" },
  "authentication": { m: "authentic = thật → xác nhận bạn đúng là người thật đó → xác thực.", e: "Sai: authentification → Đúng: authentication. Phân biệt authentication (bạn là ai) với authorization (được làm gì).", u: "Ngành IT: 'two-factor authentication', 'authentication failed'. Thiết kế đăng nhập.", f: "authentic (adj), authenticate (v), authentication (n), authorization (n), 2FA (n)" },
  "malware": { m: "mal (xấu, như 'malfunction') + ware (phần mềm) → phần mềm độc hại.", e: "Sai: malwares → Đúng: malware (không đếm được). Sai: a malware → Đúng: a piece of malware.", u: "Ngành IT/bảo mật: 'scan for malware'. IELTS Writing về tội phạm mạng.", f: "malware (n), malicious (adj), virus (n), spyware (n), ransomware (n), antivirus (n)" },
  "ransomware": { m: "ransom = tiền chuộc. Phần mềm khóa dữ liệu rồi đòi tiền chuộc.", e: "Sai: ransomwares attack → Đúng: a ransomware attack. Sai: ransome → Đúng: ransom.", u: "Ngành IT/bảo mật: 'hospital hit by ransomware'. Tin tức an ninh mạng.", f: "ransom (n), ransomware (n), malware (n), extortion (n), decrypt (v)" },
  "phishing": { m: "Đọc như 'fishing' (câu cá) → thả mồi email giả để câu mật khẩu.", e: "Sai: fishing email → Đúng: phishing email. Sai: a phishing → Đúng: a phishing attack/scam.", u: "Ngành IT/bảo mật: 'report phishing emails to IT'. Đào tạo nhận thức an ninh nhân viên.", f: "phish (v), phishing (n), spear phishing, scam (n), social engineering" },
  "vulnerability": { m: "vulnus = vết thương → điểm dễ bị thương → lỗ hổng bảo mật.", e: "Sai: vulnerabilty → Đúng: vulnerability. Sai: a vulnerability of security → Đúng: a security vulnerability.", u: "Ngành IT: 'patch a critical vulnerability'. IELTS Writing: vulnerability of the elderly.", f: "vulnerable (adj), vulnerability (n), exploit (n/v), weakness (n), flaw (n)" },
  "patch": { m: "patch = miếng vá quần áo → bản vá vá lỗ hổng phần mềm.", e: "Sai: patch the update → Đúng: apply/install the patch. Sai: patches is → Đúng: patches are.", u: "Ngành IT: 'install the latest security patch'. Thông báo bảo trì hệ thống.", f: "patch (n/v), hotfix (n), update (n), security patch, patch management" },
  "data breach": { m: "breach = chọc thủng tường → dữ liệu bị lọt ra ngoài.", e: "Sai: data breaking → Đúng: data breach. Sai: breach of datas → Đúng: a data breach.", u: "Ngành IT/pháp lý: 'report a data breach within 72 hours'. Tin tức, IELTS Writing về quyền riêng tư.", f: "breach (n/v), data leak (n), security breach, hack (n/v), privacy (n)" },
  "access control": { m: "Kiểm soát (control) ai được vào (access) hệ thống, phòng nào.", e: "Sai: control access list → Đúng: access control list (ACL). Sai: access controls is.", u: "Ngành IT/an ninh: 'role-based access control', thẻ từ ra vào tòa nhà.", f: "access (n/v), accessible (adj), ACL (n), permission (n), authorization (n)" },
  "penetration testing": { m: "penetrate = xuyên thủng → giả làm hacker xuyên thủng hệ thống để tìm lỗ.", e: "Sai: penetrate testing → Đúng: penetration testing (pen testing). Sai: pentest a system to find.", u: "Ngành IT/bảo mật: 'hire a firm for penetration testing'. Báo cáo kiểm định an ninh.", f: "penetrate (v), penetration (n), pen test (n), ethical hacking (n), audit (n)" },
  "big data": { m: "Dữ liệu 'to' đến mức máy thường không xử lý nổi.", e: "Sai: big datas → Đúng: big data (không đếm được). Sai: a big data → Đúng: big data.", u: "Ngành IT/kinh doanh: 'use big data to predict trends'. IELTS Writing về công nghệ và quyền riêng tư.", f: "data (n), big data analytics, data science (n), dataset (n), Hadoop" },
  "data analytics": { m: "analyze (phân tích) → analytics. Phân tích dữ liệu để tìm insight.", e: "Sai: data analytic is → Đúng: data analytics is. Sai: datas analysis → Đúng: data analysis.", u: "Ngành IT/kinh doanh: 'data analytics team', 'Google Analytics'. Tuyển dụng data analyst.", f: "analyze (v), analysis (n), analyst (n), analytics (n), analytical (adj)" },
  "data mining": { m: "mining = đào mỏ → đào bới dữ liệu khổng lồ tìm 'quặng' thông tin.", e: "Sai: mining data technique → Đúng: data mining technique. Sai: data mine (danh từ chỉ quá trình là mining).", u: "Ngành IT: 'data mining finds patterns in customer behavior'. Nghiên cứu, marketing.", f: "mine (n/v), mining (n), data miner (n), pattern (n), machine learning (n)" },
  "data warehouse": { m: "warehouse = nhà kho → nhà kho lớn chứa dữ liệu từ mọi nguồn.", e: "Sai: data storehouse → Đúng: data warehouse. Sai: a data warehouses → Đúng: a data warehouse.", u: "Ngành IT/BI: 'load sales data into the data warehouse'. Báo cáo quản trị.", f: "warehouse (n), data warehousing (n), data lake (n), database (n), ETL (n)" },
  "primary key": { m: "primary = chính. 'Chìa khóa chính' để nhận diện mỗi dòng dữ liệu duy nhất.", e: "Sai: main key of table → Đúng: the primary key of the table. Sai: primary keys duplicate (phải duy nhất).", u: "Ngành IT/cơ sở dữ liệu: 'set user_id as the primary key'. Thiết kế database.", f: "primary key (n), foreign key (n), unique key (n), index (n), table (n)" },
  "dataset": { m: "data (dữ liệu) + set (bộ) → một bộ dữ liệu gom chung.", e: "Sai: a datas set → Đúng: a dataset (data set). Sai: datasets is → Đúng: datasets are.", u: "Ngành IT/AI: 'train the model on a large dataset'. Nghiên cứu khoa học.", f: "data (n), dataset (n), data set, training set, test set, sample (n)" },
  "artificial intelligence": { m: "artificial = nhân tạo (do 'art', bàn tay con người làm ra) + intelligence = trí tuệ.", e: "Sai: artifical intelligent → Đúng: artificial intelligence. 'intelligent' là tính từ.", u: "IELTS Writing/Speaking chủ đề công nghệ: 'AI will replace some jobs'. Ngành IT: AI model.", f: "AI (n), artificial (adj), intelligence (n), intelligent (adj), machine learning (n)" },
  "machine learning": { m: "Máy tự 'học' từ dữ liệu thay vì được lập trình từng bước.", e: "Sai: machine learn → Đúng: machine learning (ML). Sai: a machine learning → Đúng: a machine learning model.", u: "Ngành IT: 'machine learning engineer', 'train an ML model'. IELTS Writing về công nghệ.", f: "ML (n), machine learning model, deep learning (n), AI (n), algorithm (n)" },
  "deep learning": { m: "deep = sâu: mạng nơ-ron nhiều lớp chồng sâu → học sâu.", e: "Sai: deeply learning → Đúng: deep learning. Sai: deep learning are → Đúng: deep learning is.", u: "Ngành IT/AI: 'deep learning for image recognition'. Bài báo khoa học, tuyển dụng AI.", f: "deep learning (n), neural network (n), machine learning (n), AI (n), layer (n)" },
  "neural network": { m: "neural = thần kinh (neuron) → mạng nút nối nhau như tế bào não, học từ dữ liệu.", e: "Sai: a neuron network → Đúng: a neural network. Sai: train neural network → Đúng: train a neural network.", u: "Ngành AI/IT: train/deploy a neural network, deep neural network, layers, weights. Báo cáo kỹ thuật mô tả kiến trúc mô hình.", f: "neural (adj), neuron (n), deep learning (n), neural net (n, viết tắt)" },
  "training data": { m: "Dữ liệu dùng để 'train' (luyện) mô hình, giống bài tập mẫu cho học sinh trước kỳ thi.", e: "Sai: a training datas → Đúng: training data (không đếm được). Sai: the data is train → Đúng: the data is used for training.", u: "Machine learning: collect/label training data, training set vs test set, biased training data gây kết quả lệch.", f: "train (v), training (n), dataset (n), test data (n), validation data (n)" },
  "natural language processing": { m: "natural language = ngôn ngữ con người nói → máy 'xử lý' (process) câu chữ thật. Viết tắt NLP.", e: "Sai: nature language processing → Đúng: natural language processing. Sai: the NLP → Đúng: NLP (thường không mạo từ).", u: "Ngành AI: NLP tasks như translation, sentiment analysis, chatbot; 'apply NLP techniques to customer reviews'.", f: "NLP (n), language model (n), text mining (n), computational linguistics (n)" },
  "computer vision": { m: "vision = thị lực → cho máy tính 'đôi mắt' để nhận diện ảnh, khuôn mặt, vật thể.", e: "Sai: computer view → Đúng: computer vision. Sai: a computer vision → Đúng: computer vision (lĩnh vực, không đếm được).", u: "AI/IT: computer vision for facial recognition, object detection, self-driving cars, kiểm tra lỗi sản phẩm trong nhà máy.", f: "vision (n), visual (adj), image recognition (n), object detection (n)" },
  "chatbot": { m: "chat + bot (robot) → robot biết trò chuyện bằng tin nhắn.", e: "Sai: chat bot answer customer → Đúng: the chatbot answers customers. Sai: talk with chatbot → Đúng: talk to a chatbot.", u: "IT/CSKH: deploy a chatbot on the website, AI-powered chatbot handles FAQs 24/7, chatbot escalates complex queries to staff.", f: "chat (v/n), bot (n), virtual assistant (n), conversational AI (n)" },
  "internet of things": { m: "Things = đồ vật → tủ lạnh, đèn, đồng hồ cùng 'lên mạng' và nói chuyện với nhau.", e: "Sai: internet of thing → Đúng: the Internet of Things (số nhiều, có 'the'). Sai: IoT device are → Đúng: IoT devices are.", u: "IT/kỹ thuật: IoT devices, smart home, sensors gửi dữ liệu lên cloud; bàn về bảo mật IoT.", f: "IoT (n), smart device (n), sensor (n), connected device (n)" },
  "blockchain": { m: "block (khối) + chain (chuỗi) → các khối dữ liệu nối thành chuỗi, sửa một khối là lộ.", e: "Sai: block chain technology is a coin → Đúng: blockchain is the technology behind cryptocurrencies. Viết liền: blockchain.", u: "IT/tài chính: blockchain technology, distributed ledger, smart contracts; ứng dụng truy xuất nguồn gốc chuỗi cung ứng.", f: "blockchain (n/adj), block (n), ledger (n), cryptocurrency (n), crypto (n)" },
  "digital transformation": { m: "transform = biến đổi hình dạng → doanh nghiệp 'đổi da' từ giấy tờ sang số hóa.", e: "Sai: digital transform → Đúng: digital transformation. Sai: make digital transformation → Đúng: undergo/drive digital transformation.", u: "Quản trị/IT: drive digital transformation, digital transformation strategy; chủ đề nóng trong báo cáo doanh nghiệp, hội thảo.", f: "digitalize (v), digitization (n), digitalization (n), transform (v), transformation (n)" },
  "information system": { m: "Hệ thống gom người, phần mềm, dữ liệu để xử lý thông tin. Viết tắt IS.", e: "Sai: informations system → Đúng: information system ('information' không thêm s). Sai: an informatics system → Đúng: an information system.", u: "IT/quản trị: management information system (MIS), hospital information system; ngành học Information Systems.", f: "information (n), inform (v), informative (adj), MIS (n)" },
  "enterprise resource planning": { m: "enterprise = doanh nghiệp, resource = nguồn lực → một phần mềm lập kế hoạch toàn bộ nguồn lực. ERP.", e: "Sai: an ERP software → Đúng: an ERP system / ERP software. Sai: enterprise resources planning → Đúng: enterprise resource planning.", u: "IT/doanh nghiệp: implement an ERP system (SAP, Oracle), ERP integrates finance, inventory, HR; dự án triển khai ERP.", f: "ERP (n), enterprise (n), resource (n), plan (v), planning (n)" },
  "software as a service": { m: "Thuê phần mềm như thuê dịch vụ: trả phí tháng, dùng qua trình duyệt, không cài đặt. SaaS.", e: "Sai: software as service → Đúng: software as a service (có 'a'). Sai: buy a SaaS forever → Đúng: subscribe to a SaaS product.", u: "IT/kinh doanh: SaaS platform, subscription model, monthly recurring revenue; so sánh với PaaS, IaaS trong điện toán đám mây.", f: "SaaS (n), PaaS (n), IaaS (n), cloud service (n), subscription (n)" },
  "user account": { m: "Tài khoản gắn với một 'user' (người dùng): tên đăng nhập + mật khẩu + quyền.", e: "Sai: create an user account → Đúng: create a user account ('user' đọc /ju:/). Sai: login the account → Đúng: log in to the account.", u: "IT hỗ trợ: create/disable/lock a user account, user account permissions; email 'your user account has been locked'.", f: "user (n), account (n), username (n), log in (v), sign up (v)" },
  "help desk": { m: "Bàn (desk) nơi bạn đến xin giúp (help) khi máy tính hỏng.", e: "Sai: call to help desk → Đúng: call the help desk. Sai: helpdesk staffs → Đúng: help desk staff.", u: "IT nội bộ: contact the help desk, submit a help desk ticket, help desk technician; email thông báo sự cố.", f: "helpdesk (n, biến thể), service desk (n), IT support (n), ticket (n)" },
  "troubleshoot": { m: "trouble (rắc rối) + shoot (bắn) → 'bắn hạ' từng rắc rối để tìm nguyên nhân lỗi.", e: "Sai: troubleshoot for the problem → Đúng: troubleshoot the problem. Sai: troubleshooted → Đúng: troubleshot / troubleshooted đều gặp, ưu tiên troubleshot.", u: "IT/kỹ thuật: troubleshoot network issues, troubleshooting guide, basic troubleshooting steps trong tài liệu hỗ trợ.", f: "troubleshooting (n), troubleshooter (n), trouble (n), diagnose (v)" },
  "downtime": { m: "down (sập, ngừng) + time → khoảng thời gian hệ thống 'nằm xuống', không chạy.", e: "Sai: the system has many down time → Đúng: the system had a lot of downtime (viết liền, không đếm được).", u: "IT/vận hành: minimize downtime, scheduled downtime for maintenance, unplanned downtime gây thiệt hại doanh thu.", f: "uptime (n, trái nghĩa), outage (n), down (adj), maintenance window (n)" },
  "uptime": { m: "up (đang chạy) + time → thời gian hệ thống 'đứng dậy' hoạt động; trái nghĩa downtime.", e: "Sai: uptime is 99.9 percents → Đúng: uptime is 99.9 percent. Sai: up time → Đúng: uptime (viết liền).", u: "IT/hợp đồng SLA: guarantee 99.9% uptime, monitor server uptime; chỉ số cam kết của nhà cung cấp cloud.", f: "downtime (n), availability (n), reliability (n), SLA (n)" },
  "data center": { m: "center = trung tâm → tòa nhà chứa hàng nghìn máy chủ giữ dữ liệu.", e: "Sai: datas center → Đúng: data center. Anh Anh viết 'data centre'; Mỹ viết 'data center'.", u: "IT hạ tầng: build/operate a data center, cooling, power consumption; ngành cloud và chuyển đổi số.", f: "data centre (n, Anh Anh), server farm (n), server (n), cloud (n)" },
  "load balancer": { m: "load = tải, balance = cân bằng → 'cái cân' chia đều lượt truy cập cho nhiều máy chủ.", e: "Sai: load balance server → Đúng: load balancer (thiết bị/phần mềm); load balancing (quá trình).", u: "DevOps/IT: put servers behind a load balancer, load balancing traffic, tránh quá tải khi lượng người dùng tăng đột biến.", f: "load balancing (n), balance (v), traffic (n), server (n)" },
  "upload": { m: "up (lên) + load (tải) → đẩy file từ máy mình lên mạng; ngược với download.", e: "Sai: upload the file to on the website → Đúng: upload the file to the website. Sai: upload up → Đúng: upload.", u: "IT/văn phòng: upload documents to the portal, upload speed, file size limit; hướng dẫn nộp hồ sơ trực tuyến.", f: "upload (v/n), download (v/n), uploader (n), load (v)" },
  "interface": { m: "inter (giữa) + face (mặt) → 'bề mặt' ở giữa người và máy để tương tác.", e: "Sai: interface of user → Đúng: user interface (UI). Sai: interface with the user friendly → Đúng: a user-friendly interface.", u: "IT/thiết kế: user interface, intuitive interface, API (application programming interface); đánh giá trải nghiệm người dùng.", f: "interface (n/v), interfacing (n), UI (n), API (n), interactive (adj)" },
  "configuration": { m: "configure = sắp đặt các phần cùng nhau → configuration là cách 'sắp đặt' thông số hệ thống.", e: "Sai: config the setting → Đúng: configure the settings. 'Config' chỉ là tiếng lóng; văn viết dùng configuration/configure.", u: "IT/DevOps: configuration file, default configuration, misconfiguration gây lỗ hổng bảo mật.", f: "configure (v), configuration (n), misconfiguration (n), config (n, khẩu ngữ)" },
  "technical debt": { m: "Viết code ẩu cho nhanh = 'vay nợ'; sau này phải trả lãi bằng thời gian sửa lỗi.", e: "Sai: technique debt → Đúng: technical debt. Sai: pay technical debts back money → Đúng: pay down technical debt.", u: "Phát triển phần mềm: accumulate/reduce technical debt, refactoring sprint; bàn với quản lý về chi phí bảo trì.", f: "tech debt (n, khẩu ngữ), refactor (v), legacy code (n), debt (n)" },
  "refactor": { m: "re (lại) + factor (sắp xếp thành phần) → sắp xếp lại code mà không đổi chức năng.", e: "Sai: refactor to fix new features → Đúng: refactor the code to improve its structure (không thêm tính năng).", u: "Lập trình: refactor legacy code, code review đề xuất refactoring, viết test trước khi refactor.", f: "refactoring (n), refactored (adj), restructure (v), clean code (n)" },
  "legacy system": { m: "legacy = di sản để lại → hệ thống cũ 'thừa kế' từ đời trước, vẫn phải chạy.", e: "Sai: legend system → Đúng: legacy system. Sai: an old legacy → Đúng: a legacy system / legacy software.", u: "IT doanh nghiệp: migrate from a legacy system, legacy systems are costly to maintain, tích hợp với hệ thống mới.", f: "legacy (n/adj), legacy code (n), outdated system (n), modernize (v)" },
  "migration": { m: "migrate = di cư → dữ liệu 'di cư' từ hệ thống cũ sang hệ thống mới.", e: "Sai: migrate the data from A into to B → Đúng: migrate the data from A to B. Sai: a data migrate → Đúng: a data migration.", u: "IT: data migration, cloud migration, migration plan; kế hoạch chuyển hệ thống tránh mất dữ liệu.", f: "migrate (v), migration (n), migrant (n), migratory (adj)" },
  "integration": { m: "integer = nguyên vẹn → integration là ghép các phần thành một khối nguyên.", e: "Sai: integrate A to B → Đúng: integrate A with/into B. Sai: an integrate → Đúng: an integration.", u: "IT: system integration, API integration, seamless integration with existing tools; tính năng bán hàng của SaaS.", f: "integrate (v), integration (n), integrated (adj), integral (adj)" },
  "responsive design": { m: "responsive = phản hồi → trang web 'phản ứng' theo cỡ màn hình, tự co giãn.", e: "Sai: responsible design → Đúng: responsive design. Sai: website is respond → Đúng: the website is responsive.", u: "Web/IT: build with responsive design, mobile-friendly layout, test on different screen sizes.", f: "respond (v), response (n), responsive (adj), mobile-first (adj)" },
  "search engine optimization": { m: "Tối ưu (optimize) để Google 'cỗ máy tìm kiếm' xếp trang lên đầu. Viết tắt SEO.", e: "Sai: search engine optimize → Đúng: search engine optimization. Sai: do SEO for rank → Đúng: improve SEO to rank higher.", u: "Marketing số: SEO strategy, keywords, backlinks, organic traffic; báo cáo thứ hạng trang web.", f: "SEO (n), optimize (v), optimization (n), search engine (n), SEM (n)" },
  "binary": { m: "bi = hai → hệ chỉ có hai chữ số 0 và 1.", e: "Sai: binary system have 2 numbers → Đúng: the binary system uses two digits, 0 and 1.", u: "IT/khoa học máy tính: binary code, binary file, binary search; giải thích máy tính lưu dữ liệu bằng bit.", f: "binary (adj/n), bit (n), byte (n), decimal (adj), hexadecimal (adj)" },
  "pixel": { m: "pic (picture) + el (element) → phần tử nhỏ nhất của bức ảnh.", e: "Sai: the image has 1080 pixel → Đúng: the image is 1080 pixels wide. Sai: high pixels → Đúng: high resolution.", u: "Thiết kế/IT: pixel resolution, pixel-perfect design, pixels per inch (PPI); kích thước ảnh, màn hình.", f: "pixel (n), pixelated (adj), resolution (n), megapixel (n)" },
  "encryption key": { m: "Chìa khóa (key) để khóa/mở dữ liệu đã mã hóa (encrypt).", e: "Sai: encrypt key → Đúng: encryption key. Sai: lost the key of encryption → Đúng: lost the encryption key.", u: "An ninh mạng: public/private encryption key, store keys securely, key management; mất khóa là mất dữ liệu.", f: "encrypt (v), encryption (n), decrypt (v), decryption (n), public key (n)" },
  "gross profit": { m: "gross = tổng, chưa trừ hết → lợi nhuận 'thô' = doanh thu trừ giá vốn.", e: "Sai: gross profit is profit after tax → Đúng: gross profit is revenue minus cost of goods sold.", u: "Kế toán/tài chính: gross profit margin, gross profit rose 10%; dòng đầu trong báo cáo kết quả kinh doanh.", f: "gross margin (n), net profit (n), gross (adj), profit (n/v)" },
  "net income": { m: "net = ròng, đã lọc sạch → thu nhập còn lại sau khi trừ mọi chi phí và thuế.", e: "Sai: net income before tax → Đúng: income before tax; net income is after tax. Sai: nett income → Đúng: net income.", u: "Tài chính: report net income of $5 million, net income rose year-on-year; 'bottom line' của báo cáo.", f: "net profit (n), net earnings (n), bottom line (n), gross income (n)" },
  "profit margin": { m: "margin = lề → phần 'lề' lời còn lại trên mỗi đồng doanh thu, tính theo %.", e: "Sai: profit margin is high money → Đúng: the profit margin is high (tính bằng %). Sai: margin of profits → Đúng: profit margin.", u: "Kinh doanh: thin/healthy profit margin, improve margins, operating margin; phân tích hiệu quả sản phẩm.", f: "margin (n), marginal (adj), gross margin (n), net margin (n)" },
  "break-even point": { m: "break even = hòa, không lời không lỗ → điểm doanh thu vừa đủ bù chi phí.", e: "Sai: reach the break even → Đúng: reach the break-even point / break even (động từ). Sai: break-even the cost → Đúng: break even.", u: "Kế hoạch kinh doanh: calculate the break-even point, we expect to break even in year two; phân tích chi phí-sản lượng.", f: "break even (v), break-even (adj), break-even analysis (n)" },
  "fixed cost": { m: "fixed = cố định → tiền thuê, lương cứng không đổi dù sản xuất nhiều hay ít.", e: "Sai: fix cost → Đúng: fixed cost. Sai: fixed costs change with output → Đúng: variable costs change with output.", u: "Kế toán quản trị: fixed costs such as rent and salaries, cover fixed costs; tính điểm hòa vốn.", f: "fixed (adj), overhead (n), variable cost (n), total cost (n)" },
  "variable cost": { m: "vary = thay đổi → chi phí 'biến' theo sản lượng: nguyên liệu, bao bì.", e: "Sai: variety cost → Đúng: variable cost. Sai: variable cost is same every month → Đúng: variable cost changes with output.", u: "Kế toán quản trị: variable cost per unit, reduce variable costs; phân tích lợi nhuận đóng góp.", f: "vary (v), variable (adj/n), variation (n), fixed cost (n)" },
  "cash flow": { m: "Dòng (flow) tiền mặt chảy vào và chảy ra khỏi doanh nghiệp.", e: "Sai: the company has cash flow problem → Đúng: the company has cash flow problems. Sai: cashflow money → Đúng: cash flow.", u: "Tài chính: positive/negative cash flow, cash flow statement, manage cash flow; doanh nghiệp nhỏ hay chết vì thiếu dòng tiền.", f: "cash flow statement (n), cash (n), inflow (n), outflow (n)" },
  "balance sheet": { m: "balance = cân bằng → tờ báo cáo luôn cân: tài sản = nợ + vốn chủ.", e: "Sai: balance sheet shows profit of the year → Đúng: the income statement shows profit; balance sheet shows assets and liabilities.", u: "Kế toán: on the balance sheet, strong balance sheet, assets, liabilities, equity; đọc báo cáo tài chính.", f: "statement of financial position (n), asset (n), liability (n), equity (n)" },
  "income statement": { m: "Báo cáo 'income' (thu nhập) → doanh thu trừ chi phí ra lãi/lỗ trong kỳ.", e: "Sai: income statement shows assets → Đúng: the balance sheet shows assets; the income statement shows revenue and expenses.", u: "Kế toán: prepare the income statement, also called profit and loss statement (P&L); báo cáo quý/năm.", f: "profit and loss statement (n), P&L (n), revenue (n), expense (n)" },
  "financial statement": { m: "Bộ 'statement' (bản kê) về tài chính: cân đối, kết quả kinh doanh, lưu chuyển tiền tệ.", e: "Sai: finance statement → Đúng: financial statement. Sai: audit the financial statement of 2025 year → Đúng: audit the 2025 financial statements.", u: "Kế toán/kiểm toán: prepare/audit financial statements, annual report, IFRS; nhà đầu tư đọc để đánh giá công ty.", f: "finance (n/v), financial (adj), financially (adv), statement (n)" },
  "equity": { m: "equal = bằng → phần 'công bằng' thuộc về chủ sở hữu sau khi trừ nợ.", e: "Sai: equity is the company's debt → Đúng: equity is assets minus liabilities. Lưu ý: 'equity' còn nghĩa công bằng.", u: "Tài chính: shareholders' equity, equity financing, private equity, debt-to-equity ratio.", f: "equity (n), equitable (adj), equal (adj), shareholder (n)" },
  "working capital": { m: "Vốn đang 'làm việc' hằng ngày: tài sản ngắn hạn trừ nợ ngắn hạn.", e: "Sai: working capitals → Đúng: working capital (không đếm được). Sai: capital working → Đúng: working capital.", u: "Tài chính doanh nghiệp: working capital management, shortage of working capital; vay vốn lưu động ngân hàng.", f: "capital (n), current assets (n), current liabilities (n), liquidity (n)" },
  "depreciation": { m: "de (xuống) + preci (giá, như 'price') → giá trị tài sản đi xuống theo thời gian.", e: "Sai: depreciation of the land → Đúng: land is not depreciated. Sai: the car depreciation fast → Đúng: the car depreciates fast.", u: "Kế toán: straight-line depreciation, depreciation expense, accumulated depreciation; tỷ giá: currency depreciation.", f: "depreciate (v), depreciation (n), appreciation (n, trái nghĩa), amortization (n)" },
  "accounting": { m: "account = tính toán, ghi sổ → accounting là nghề ghi chép, tổng hợp số liệu tài chính.", e: "Sai: I study accountant → Đúng: I study accounting (ngành); an accountant (người). Sai: an accounting → Đúng: accounting.", u: "Kế toán: accounting department, accounting standards, accounting software; phỏng vấn: 'I majored in accounting'.", f: "account (n/v), accountant (n), accountable (adj), accountancy (n, Anh Anh)" },
  "bookkeeping": { m: "keep the books = giữ sổ sách → ghi chép từng giao dịch hằng ngày.", e: "Sai: book keeping → Đúng: bookkeeping (viết liền). Sai: bookkeeping is same as accounting → Đúng: bookkeeping is part of accounting.", u: "Kế toán doanh nghiệp nhỏ: bookkeeping software, outsource bookkeeping, accurate bookkeeping cho khai thuế.", f: "bookkeeper (n), keep the books (v), ledger (n), accounting (n)" },
  "accounts payable": { m: "payable = phải trả → các khoản công ty còn nợ nhà cung cấp. Viết tắt AP.", e: "Sai: account payables → Đúng: accounts payable. Sai: accounts payable is money customers owe → Đúng: that is accounts receivable.", u: "Kế toán: accounts payable department, process invoices, AP clerk; email 'please contact accounts payable about payment'.", f: "AP (n), payable (adj), pay (v), payment (n), accounts receivable (n)" },
  "accounts receivable": { m: "receive = nhận → các khoản công ty sẽ nhận từ khách hàng. Viết tắt AR.", e: "Sai: account receivables → Đúng: accounts receivable. Sai: accounts receivable is our debt → Đúng: it is money owed to us.", u: "Kế toán: accounts receivable turnover, overdue receivables, AR aging report; đòi nợ khách hàng.", f: "AR (n), receivable (adj/n), receive (v), receipt (n), accounts payable (n)" },
  "value-added tax": { m: "Thuế đánh trên phần giá trị được cộng thêm (added) ở mỗi khâu. VAT.", e: "Sai: value add tax → Đúng: value-added tax. Sai: the price is not include VAT → Đúng: the price does not include VAT.", u: "Kế toán/thương mại: VAT invoice, prices exclusive of VAT, VAT rate of 10%; báo giá ghi rõ VAT.", f: "VAT (n), sales tax (n), tax (n/v), taxable (adj), value-added (adj)" },
  "corporate income tax": { m: "corporate = công ty → thuế đánh vào thu nhập (lợi nhuận) của công ty, không phải cá nhân.", e: "Sai: company income tax pay by staff → Đúng: corporate income tax is paid by companies. Sai: corporation tax income → Đúng: corporate income tax.", u: "Thuế/kế toán: corporate income tax rate of 20%, tax incentives, CIT return; tư vấn đầu tư nước ngoài.", f: "CIT (n), corporation tax (n, Anh Anh), personal income tax (n), taxation (n)" },
  "fiscal year": { m: "fisc = ngân khố (tiếng Latin) → năm tính sổ của ngân khố, không nhất thiết từ tháng 1.", e: "Sai: in fiscal year 2025 year → Đúng: in fiscal year 2025 / in FY2025. Sai: physical year → Đúng: fiscal year.", u: "Tài chính: the fiscal year ends on June 30, fiscal year budget, FY results; báo cáo thường niên.", f: "FY (n), financial year (n, Anh Anh), fiscal (adj), fiscal quarter (n)" },
  "central bank": { m: "Ngân hàng ở 'trung tâm' hệ thống, in tiền và đặt lãi suất cho cả nước.", e: "Sai: the central bank of Vietnam lend to people → Đúng: the central bank lends to commercial banks, not individuals.", u: "Kinh tế/tài chính: the central bank raised interest rates, central bank independence; IELTS Writing chủ đề lạm phát.", f: "Federal Reserve (n), State Bank (n), monetary authority (n), commercial bank (n)" },
  "collateral": { m: "co (cùng) + lateral (bên) → tài sản 'đứng cạnh' khoản vay để bảo đảm.", e: "Sai: use house as a collateral for → Đúng: use the house as collateral for the loan (thường không đếm được).", u: "Ngân hàng: pledge collateral, collateral-free loan, value of collateral; thẩm định tín dụng.", f: "collateral (n/adj), secured loan (n), pledge (v), mortgage (n)" },
  "credit rating": { m: "rating = chấm điểm → 'điểm' cho biết người/công ty đáng tin để cho vay đến đâu.", e: "Sai: credit rate → Đúng: credit rating (rate là lãi suất). Sai: get high credit rating → Đúng: have a high credit rating.", u: "Tài chính: credit rating agency (Moody's, S&P), downgrade/upgrade a credit rating; chi phí vay tăng khi bị hạ hạng.", f: "credit score (n, cá nhân), rate (v), rating (n), creditworthy (adj)" },
  "default": { m: "de + fault (lỗi) → 'thất hứa' không trả nợ đúng hạn.", e: "Sai: default the loan → Đúng: default on the loan. Sai: the country defaulted its debt → Đúng: defaulted on its debt.", u: "Ngân hàng/tài chính: default on payments, risk of default, loan default rate; IT: 'default' nghĩa mặc định.", f: "default (v/n), defaulter (n), default rate (n), insolvency (n)" },
  "liquidity": { m: "liquid = chất lỏng → tài sản 'chảy' nhanh thành tiền mặt.", e: "Sai: the liquid of the company → Đúng: the company's liquidity. Sai: high liquidity assets → Đúng: highly liquid assets.", u: "Tài chính/ngân hàng: liquidity risk, liquidity ratio, inject liquidity into the market; phân tích khả năng trả nợ ngắn hạn.", f: "liquid (adj), liquidate (v), liquidation (n), illiquid (adj)" },
  "exchange rate": { m: "exchange = đổi → 'tỷ lệ' đổi một đồng tiền sang đồng tiền khác.", e: "Sai: exchange rate of USD with VND → Đúng: the exchange rate between USD and VND / the USD-VND exchange rate.", u: "Kinh tế/thương mại: exchange rate fluctuations, favorable exchange rate; IELTS Writing Task 1 biểu đồ tỷ giá.", f: "foreign exchange (n), forex (n), currency (n), exchange (v/n)" },
  "stock exchange": { m: "Chợ (exchange) nơi mua bán cổ phiếu (stock).", e: "Sai: listed in the stock exchange → Đúng: listed on the stock exchange. Sai: stocks exchange → Đúng: stock exchange.", u: "Tài chính: be listed on the stock exchange, Ho Chi Minh Stock Exchange (HOSE), stock exchange index.", f: "stock market (n), bourse (n), listing (n), share (n), stock (n)" },
  "return on investment": { m: "return = quay về → bao nhiêu tiền 'quay về' trên mỗi đồng đầu tư. ROI.", e: "Sai: return of investment → Đúng: return on investment. Sai: the ROI is very money → Đúng: the ROI is very high.", u: "Kinh doanh/marketing: calculate ROI, high return on investment, ROI of an ad campaign; thuyết phục duyệt ngân sách.", f: "ROI (n), return (n/v), invest (v), investment (n), investor (n)" },
  "venture capital": { m: "venture = cuộc phiêu lưu mạo hiểm → vốn rót vào startup dám mạo hiểm. VC.", e: "Sai: venture capitals invested → Đúng: venture capital firms invested. Sai: adventure capital → Đúng: venture capital.", u: "Khởi nghiệp: raise venture capital, venture capital firm, VC funding round; pitch với nhà đầu tư.", f: "VC (n), venture capitalist (n), angel investor (n), seed funding (n)" },
  "initial public offering": { m: "initial = lần đầu, public = công chúng, offering = chào bán → lần đầu bán cổ phiếu ra công chúng. IPO.", e: "Sai: the company made IPO → Đúng: the company launched/held an IPO / went public. Sai: initial publish offering → Đúng: initial public offering.", u: "Tài chính: plan an IPO, IPO price, go public; tin tức doanh nghiệp niêm yết.", f: "IPO (n), go public (v), listing (n), flotation (n, Anh Anh)" },
  "market capitalization": { m: "Vốn hóa = số cổ phiếu × giá thị trường. Viết tắt market cap.", e: "Sai: market capital of company → Đúng: the company's market capitalization / market cap. Sai: capitalisation (Anh Anh vẫn đúng).", u: "Tài chính/chứng khoán: a market capitalization of $2 trillion, large-cap stocks; so sánh quy mô công ty.", f: "market cap (n), capitalize (v), large-cap (adj), small-cap (adj)" },
  "valuation": { m: "value (giá trị) + -ation → hành động 'đặt giá trị' cho công ty hay tài sản.", e: "Sai: the valuation of startup is 10 million → Đúng: the startup's valuation is $10 million. Sai: evaluation (đánh giá chung) ≠ valuation.", u: "Đầu tư: company valuation, pre-money valuation, overvalued stocks; thẩm định giá bất động sản.", f: "value (n/v), valuate (v), valuer (n), overvalued (adj), undervalued (adj)" },
  "diversification": { m: "diverse = đa dạng → đừng bỏ hết trứng vào một giỏ.", e: "Sai: diversify of products → Đúng: diversification of products. Sai: diversify into investment → Đúng: diversify your investments.", u: "Đầu tư/chiến lược: portfolio diversification, diversification into new markets; giảm rủi ro.", f: "diverse (adj), diversify (v), diversified (adj), diversity (n)" },
  "risk management": { m: "Quản lý (manage) rủi ro: nhận diện, đo lường, giảm thiểu trước khi sự cố xảy ra.", e: "Sai: risks management → Đúng: risk management. Sai: manage the risky → Đúng: manage the risk.", u: "Doanh nghiệp/ngân hàng: risk management framework, risk assessment, mitigate risks; báo cáo quản trị.", f: "risk (n/v), risky (adj), risk assessment (n), mitigate (v)" },
  "hedge": { m: "hedge = hàng rào cây → dựng 'hàng rào' bảo vệ khỏi biến động giá.", e: "Sai: hedge the risk of → Đúng: hedge against the risk of. Sai: hedging fund → Đúng: hedge fund.", u: "Tài chính: hedge against currency risk, hedging strategy, hedge fund; doanh nghiệp xuất nhập khẩu phòng ngừa tỷ giá.", f: "hedge (v/n), hedging (n), hedge fund (n), hedger (n)" },
  "subsidiary": { m: "sub = dưới → công ty 'dưới quyền' công ty mẹ (parent company).", e: "Sai: subsidary (thiếu i) → Đúng: subsidiary. Sai: a son company of Vingroup → Đúng: a subsidiary of Vingroup.", u: "Doanh nghiệp/pháp lý: wholly-owned subsidiary, open a subsidiary in Vietnam; báo cáo hợp nhất.", f: "subsidiary (n/adj), parent company (n), affiliate (n), branch (n)" },
  "joint venture": { m: "joint = chung, venture = phi vụ kinh doanh → hai bên cùng góp vốn làm chung. JV.", e: "Sai: make a joint venture with → Đúng: form/set up a joint venture with. Sai: joined venture → Đúng: joint venture.", u: "Đầu tư nước ngoài: a 50-50 joint venture, joint venture agreement, JV partner; hợp tác doanh nghiệp.", f: "JV (n), partnership (n), alliance (n), joint (adj)" },
  "sole proprietorship": { m: "sole = duy nhất, proprietor = chủ → doanh nghiệp chỉ một chủ, chịu trách nhiệm vô hạn.", e: "Sai: sole proprietor ship → Đúng: sole proprietorship. Sai: the proprietorship is owner → Đúng: the proprietor is the owner.", u: "Luật kinh doanh: register as a sole proprietorship, unlimited liability; so sánh với LLC khi khởi nghiệp.", f: "sole proprietor (n), sole trader (n, Anh Anh), proprietor (n), proprietary (adj)" },
  "limited liability company": { m: "limited liability = trách nhiệm có giới hạn → chủ chỉ chịu nợ trong phần vốn góp. LLC.", e: "Sai: limit liability company → Đúng: limited liability company. Sai: a LLC → Đúng: an LLC (đọc /el/).", u: "Pháp lý/doanh nghiệp: set up an LLC, registered capital, members' liability; tư vấn thành lập công ty.", f: "LLC (n), Ltd (n, Anh Anh), liability (n), liable (adj)" },
  "joint-stock company": { m: "joint (chung) + stock (cổ phần) → nhiều cổ đông cùng góp vốn qua cổ phần. JSC.", e: "Sai: joint stocks company → Đúng: joint-stock company. Sai: shareholder company → Đúng: joint-stock company.", u: "Pháp lý Việt Nam: tên công ty 'ABC Joint Stock Company (JSC)', shareholders' meeting, cổ phần hóa.", f: "JSC (n), corporation (n), shareholder (n), share (n), stock (n)" },
  "startup": { m: "start + up → công ty vừa 'khởi động', nhỏ, tăng trưởng nhanh.", e: "Sai: start-up a company (danh từ) → Đúng: start up a company (động từ) / a startup (danh từ).", u: "Khởi nghiệp: tech startup, startup founder, startup ecosystem; IELTS Speaking: 'Would you like to run a startup?'", f: "start-up (n, biến thể), start up (v), founder (n), entrepreneur (n)" },
  "business plan": { m: "Bản 'kế hoạch' viết ra trước khi kinh doanh: mục tiêu, thị trường, tài chính.", e: "Sai: make a business plan for borrow → Đúng: write a business plan to get a loan. Sai: business planning (quá trình) ≠ business plan (tài liệu).", u: "Khởi nghiệp/ngân hàng: draft a business plan, executive summary, financial projections; nộp kèm hồ sơ vay vốn.", f: "plan (n/v), planning (n), business proposal (n), executive summary (n)" },
  "business model": { m: "model = khuôn mẫu → khuôn cách công ty kiếm tiền.", e: "Sai: business modal → Đúng: business model. Sai: the business model of us → Đúng: our business model.", u: "Quản trị/khởi nghiệp: subscription business model, sustainable business model, business model canvas.", f: "model (n/v), revenue model (n), business plan (n), monetize (v)" },
  "stakeholder": { m: "stake = phần lợi ích đặt cược → người 'cầm phần cược', chịu ảnh hưởng của dự án.", e: "Sai: stakeholder = shareholder → Đúng: shareholders are one type of stakeholder. Sai: stake holder → Đúng: stakeholder.", u: "Quản lý dự án/doanh nghiệp: key stakeholders, stakeholder engagement, consult stakeholders; IELTS Writing chủ đề kinh tế.", f: "stake (n), shareholder (n), stakeholder engagement (n), interested party (n)" },
  "board of directors": { m: "board = cái bàn họp → nhóm người ngồi quanh bàn quyết định chiến lược công ty.", e: "Sai: board of director → Đúng: board of directors. Sai: he is in the board → Đúng: he is on the board.", u: "Quản trị doanh nghiệp: sit on the board, chairman of the board of directors, board meeting; báo cáo thường niên.", f: "board (n), director (n), chairman (n), board member (n), boardroom (n)" },
  "chief executive officer": { m: "chief = đứng đầu, executive = điều hành → người điều hành cao nhất. CEO.", e: "Sai: the CEO of company → Đúng: the CEO of the company. Sai: a CEO officer → Đúng: a CEO (đã có officer).", u: "Kinh doanh/TOEIC: appoint a new CEO, CEO announced, report to the CEO; tin doanh nghiệp.", f: "CEO (n), CFO (n), COO (n), executive (n/adj), chief (adj/n)" },
  "corporate governance": { m: "govern = cai quản → bộ quy tắc 'cai quản' công ty minh bạch, bảo vệ cổ đông.", e: "Sai: corporate government → Đúng: corporate governance. Sai: the governance is poorly → Đúng: governance is poor.", u: "Quản trị/tài chính: good corporate governance, transparency, accountability; tiêu chí ESG của nhà đầu tư.", f: "govern (v), governance (n), governing (adj), corporate (adj), corporation (n)" },
  "competitive advantage": { m: "Lợi thế (advantage) giúp thắng đối thủ trong cuộc cạnh tranh (compete).", e: "Sai: competition advantage → Đúng: competitive advantage. Sai: have an advantage to competitors → Đúng: have an advantage over competitors.", u: "Chiến lược kinh doanh: gain/maintain a competitive advantage, sustainable competitive advantage; IELTS Writing chủ đề kinh doanh.", f: "compete (v), competition (n), competitive (adj), competitor (n), edge (n)" },
  "market share": { m: "share = phần chia → phần 'miếng bánh' thị trường công ty chiếm được.", e: "Sai: market share increased to 20 percents → Đúng: market share increased to 20 percent. Sai: share of market of → Đúng: market share of.", u: "Kinh doanh: gain/lose market share, a 30% market share; IELTS Writing Task 1 biểu đồ tròn thị phần.", f: "share (n/v), market leader (n), market position (n), market (n)" },
  "market research": { m: "research = nghiên cứu → khảo sát khách hàng, đối thủ trước khi tung sản phẩm.", e: "Sai: do a market researches → Đúng: do/conduct market research (không đếm được). Sai: market search → Đúng: market research.", u: "Marketing: conduct market research, surveys, focus groups; TOEIC Part 7 báo cáo khảo sát khách hàng.", f: "researcher (n), research (v/n), market survey (n), market analysis (n)" },
  "target market": { m: "target = bia bắn → nhóm khách hàng mà sản phẩm 'nhắm' vào.", e: "Sai: target to young people → Đúng: target young people. Sai: our target market is the young → Đúng: young adults.", u: "Marketing: define the target market, target audience, reach the target market; kế hoạch tiếp thị.", f: "target (n/v), target audience (n), niche market (n), segment (n)" },
  "segmentation": { m: "segment = lát, phần cắt → chia thị trường thành từng 'lát' khách hàng giống nhau.", e: "Sai: segment the market in groups → Đúng: segment the market into groups. Sai: segmentize → Đúng: segment.", u: "Marketing: market segmentation by age, income, behavior; chọn phân khúc mục tiêu (STP).", f: "segment (n/v), segmentation (n), segmented (adj), targeting (n)" },
  "marketing": { m: "market + -ing → mọi hoạt động đưa sản phẩm 'ra chợ' và thuyết phục khách mua.", e: "Sai: I work in marketing department of → Đúng: I work in the marketing department of. Sai: a marketing → Đúng: marketing (không đếm được).", u: "Kinh doanh/TOEIC: marketing strategy, digital marketing, marketing budget; IELTS Speaking về nghề nghiệp.", f: "market (n/v), marketer (n), marketable (adj), marketplace (n)" },
  "advertising campaign": { m: "campaign = chiến dịch quân sự → 'trận đánh' quảng cáo có kế hoạch, thời hạn.", e: "Sai: advertisement campaign of → Đúng: advertising campaign for. Sai: launch campaign advertising → Đúng: launch an advertising campaign.", u: "Marketing/TOEIC: launch/run an advertising campaign, campaign budget, target audience; Part 3, 4 về quảng bá.", f: "advertise (v), advertising (n), advertisement (n), ad campaign (n)" },
  "customer retention": { m: "retain = giữ lại → giữ khách cũ quay lại, rẻ hơn tìm khách mới.", e: "Sai: retent customers → Đúng: retain customers. Sai: customers retention → Đúng: customer retention.", u: "Marketing/CSKH: improve customer retention, retention rate, loyalty program; giảm tỷ lệ rời bỏ (churn).", f: "retain (v), retention (n), customer loyalty (n), churn (n)" },
  "customer relationship management": { m: "Quản lý mối quan hệ với khách hàng, thường bằng phần mềm. CRM.", e: "Sai: customer relation management → Đúng: customer relationship management. Sai: a CRM software → Đúng: a CRM system.", u: "Kinh doanh/IT: CRM software (Salesforce), track leads, customer data; bộ phận bán hàng dùng hằng ngày.", f: "CRM (n), relationship (n), relate (v), customer service (n)" },
  "supply chain": { m: "Chuỗi (chain) các mắt xích cung ứng: nguyên liệu → nhà máy → kho → khách hàng.", e: "Sai: supplies chain → Đúng: supply chain. Sai: supply chain was broke → Đúng: the supply chain was disrupted.", u: "Logistics/kinh doanh: supply chain disruption, supply chain management; IELTS Writing chủ đề toàn cầu hóa.", f: "supply (n/v), supplier (n), supply chain management (n), logistics (n)" },
  "logistics": { m: "Gốc quân sự: lo vận chuyển, kho, tiếp tế → nay là vận hành hàng hóa đi đúng nơi, đúng lúc.", e: "Sai: a logistic company → Đúng: a logistics company. Sai: logistics are → Đúng: logistics is (thường động từ số ít).", u: "Xuất nhập khẩu/vận tải: logistics provider, third-party logistics (3PL), warehousing; TOEIC về giao hàng.", f: "logistical (adj), logistically (adv), logistician (n), supply chain (n)" },
  "procurement": { m: "procure = kiếm được, mua được → quy trình mua hàng chính thức của tổ chức.", e: "Sai: procure for materials → Đúng: procure materials. Sai: the procurement of buying → Đúng: the procurement of materials.", u: "Doanh nghiệp/nhà nước: procurement department, public procurement, tender; quy trình đấu thầu.", f: "procure (v), procurement (n), purchasing (n), sourcing (n), buyer (n)" },
  "wholesale": { m: "whole (toàn bộ) + sale → bán cả lô lớn cho người bán lại, không bán lẻ.", e: "Sai: buy with wholesale price → Đúng: buy at wholesale prices. Sai: whole sale → Đúng: wholesale.", u: "Thương mại/TOEIC: wholesale price, wholesale market, sell wholesale to retailers; so sánh với retail.", f: "wholesale (adj/adv/n), wholesaler (n), retail (n/adj), retailer (n)" },
  "distribution channel": { m: "channel = con kênh → đường 'kênh' đưa hàng từ nhà sản xuất đến người mua.", e: "Sai: distribute channel → Đúng: distribution channel. Sai: sell through many channel → Đúng: sell through multiple channels.", u: "Marketing/bán hàng: online distribution channels, wholesalers and retailers, expand distribution; chữ P 'Place' trong 4P.", f: "distribute (v), distribution (n), distributor (n), channel (n)" },
  "customs": { m: "custom = phong tục; customs (số nhiều) = 'cửa khẩu' kiểm tra, thu thuế hàng nhập.", e: "Sai: the custom checked my bag → Đúng: customs checked my bag. Sai: pass the customs → Đúng: go through customs.", u: "Xuất nhập khẩu/du lịch: customs clearance, customs declaration, customs duty; TOEIC về giao hàng quốc tế.", f: "customs officer (n), customs duty (n), clearance (n), custom (n, phong tục)" },
  "free trade agreement": { m: "Hiệp định (agreement) cho hàng hóa đi lại 'tự do', giảm thuế. FTA.", e: "Sai: free trading agreement → Đúng: free trade agreement. Sai: sign a FTA → Đúng: sign an FTA.", u: "Kinh tế/thương mại: Vietnam signed free trade agreements (EVFTA, CPTPP), tariff reduction; IELTS Writing toàn cầu hóa.", f: "FTA (n), free trade (n), tariff (n), trade deal (n), trade barrier (n)" },
  "letter of credit": { m: "Lá thư ngân hàng cam kết trả tiền thay người mua khi đủ chứng từ. L/C.", e: "Sai: open a credit letter → Đúng: open/issue a letter of credit. Sai: letters of credits → Đúng: letters of credit.", u: "Thanh toán quốc tế: issue a letter of credit, irrevocable L/C, shipping documents; ngân hàng xuất nhập khẩu.", f: "L/C (n), LC (n), credit (n), documentary credit (n)" },
  "pricing": { m: "price + -ing → việc quyết định giá bán như thế nào.", e: "Sai: the pricing is expensive → Đúng: the price is high / the pricing is competitive. Sai: pricing for → Đúng: pricing of/for đều dùng.", u: "Marketing/kinh doanh: pricing strategy, competitive pricing, dynamic pricing; chữ P 'Price' trong 4P.", f: "price (n/v), pricey (adj), priceless (adj), overpriced (adj)" },
  "quotation": { m: "quote = báo con số → bảng báo giá chính thức gửi khách.", e: "Sai: send me a quotation price → Đúng: send me a quotation / a quote. Sai: quotation for 100 unit → Đúng: for 100 units.", u: "TOEIC/thương mại: request a quotation, the quotation is valid for 30 days; email Part 7 về báo giá.", f: "quote (v/n), quotation (n), estimate (n), price list (n)" },
  "purchase order": { m: "Lệnh (order) mua hàng (purchase) chính thức người mua gửi nhà cung cấp. PO.", e: "Sai: purchasing order → Đúng: purchase order. Sai: issue a PO number for → Đúng: include the PO number on the invoice.", u: "TOEIC/mua hàng: issue a purchase order, PO number, match invoice with purchase order; quy trình kế toán.", f: "PO (n), purchase (v/n), purchaser (n), order (n/v), invoice (n)" },
  "human resources": { m: "resources = nguồn lực → con người là 'nguồn lực' của công ty. HR.", e: "Sai: human resource are busy → Đúng: human resources is busy / HR is busy. Sai: humans resources → Đúng: human resources.", u: "Văn phòng/TOEIC: contact human resources, HR manager, HR policies; email về tuyển dụng, nghỉ phép.", f: "HR (n), personnel (n), human resource management (n), staffing (n)" },
  "key performance indicator": { m: "indicator = kim chỉ → con số 'chỉ' ra hiệu quả công việc then chốt (key). KPI.", e: "Sai: reach KPI → Đúng: meet/hit a KPI / meet KPIs. Sai: key performance index → Đúng: key performance indicator.", u: "Quản trị/nhân sự: set KPIs, track KPIs monthly, KPI dashboard; đánh giá nhân viên cuối năm.", f: "KPI (n), indicate (v), indicator (n), metric (n), OKR (n)" },
  "outsourcing": { m: "out (ra ngoài) + source (nguồn) → lấy nguồn lực từ bên ngoài công ty làm thay.", e: "Sai: outsource for a company → Đúng: outsource work to a company. Sai: outsourcing staffs → Đúng: outsourced staff.", u: "Kinh doanh/IT: IT outsourcing, outsource customer service; IELTS Writing: lợi và hại của outsourcing với việc làm.", f: "outsource (v), outsourced (adj), offshoring (n), contractor (n), insourcing (n)" },
  "economies of scale": { m: "scale = quy mô → sản xuất càng nhiều, giá mỗi đơn vị càng rẻ.", e: "Sai: economy of scale → Đúng: economies of scale (số nhiều). Sai: benefit from scale economics → Đúng: benefit from economies of scale.", u: "Kinh tế/IELTS Writing: achieve economies of scale, large firms enjoy economies of scale; giải thích vì sao tập đoàn có giá rẻ.", f: "economy (n), economic (adj), scale up (v), mass production (n)" },
  "supply and demand": { m: "supply = cung, demand = cầu → cung ít cầu nhiều thì giá tăng.", e: "Sai: demand and supply law → Đúng: the law of supply and demand. Sai: supply and demand is decide price → Đúng: supply and demand determine prices.", u: "Kinh tế/IELTS Writing: the law of supply and demand, prices are driven by supply and demand; giải thích biến động giá nhà.", f: "supply (n/v), demand (n/v), equilibrium (n), shortage (n), surplus (n)" },
  "gross domestic product": { m: "gross = tổng, domestic = trong nước → tổng giá trị hàng hóa, dịch vụ trong nước. GDP.", e: "Sai: GDP of Vietnam increase 7% → Đúng: Vietnam's GDP grew by 7%. Sai: gross domestics product → Đúng: gross domestic product.", u: "Kinh tế/IELTS Writing Task 1: GDP growth, GDP per capita, as a percentage of GDP; mô tả biểu đồ kinh tế.", f: "GDP (n), GNP (n), domestic (adj), per capita (adj/adv), economy (n)" },
  "monetary policy": { m: "monetary = tiền tệ (money) → chính sách ngân hàng trung ương điều chỉnh lãi suất, lượng tiền.", e: "Sai: money policy → Đúng: monetary policy. Sai: monetary policy of the government taxes → Đúng: fiscal policy concerns taxes.", u: "Kinh tế: tighten/loosen monetary policy, interest rates, inflation targeting; bài báo kinh tế vĩ mô.", f: "monetary (adj), money (n), fiscal policy (n), interest rate (n)" },
  "fiscal policy": { m: "fisc = ngân khố → chính sách thu thuế và chi tiêu của chính phủ.", e: "Sai: fiscal policy is about interest rate → Đúng: fiscal policy is about taxation and government spending.", u: "Kinh tế/IELTS Writing: expansionary fiscal policy, public spending, tax cuts; tranh luận chi tiêu công.", f: "fiscal (adj), fiscal year (n), monetary policy (n), taxation (n), budget (n)" },
  "securities": { m: "secure = an toàn → giấy tờ 'bảo đảm' quyền sở hữu tài sản: cổ phiếu, trái phiếu.", e: "Sai: a securities company sell security → Đúng: a securities company sells securities. Dùng số nhiều khi chỉ chứng khoán.", u: "Tài chính: securities firm, trade securities, securities law, Securities Commission; ngành ngân hàng-chứng khoán.", f: "security (n), stock (n), bond (n), share (n), securities market (n)" },
  "brokerage": { m: "broker = người môi giới + -age → nghề, phí hoặc công ty môi giới.", e: "Sai: brokerage fee of the broker man → Đúng: the broker's brokerage fee. Sai: broking (Anh Anh vẫn dùng) ≠ breaking.", u: "Tài chính/bất động sản: brokerage account, online brokerage, brokerage fees; mở tài khoản chứng khoán.", f: "broker (n/v), brokerage (n), stockbroker (n), commission (n)" },
  "fintech": { m: "fin (finance) + tech (technology) → công nghệ làm dịch vụ tài chính: ví điện tử, cho vay online.", e: "Sai: fin-tech is a bank → Đúng: fintech companies offer financial services through technology. Viết liền: fintech.", u: "Tài chính/công nghệ: fintech startup, mobile payments, digital banking; chủ đề cashless society trong IELTS.", f: "financial technology (n), e-wallet (n), digital banking (n), insurtech (n)" },
  "bank transfer": { m: "transfer = chuyển từ chỗ này sang chỗ khác → chuyển tiền giữa hai tài khoản ngân hàng.", e: "Sai: pay by bank transfer money → Đúng: pay by bank transfer. Sai: transfer for me → Đúng: transfer the money to me.", u: "TOEIC/thanh toán: payment by bank transfer, transfer details, wire transfer; email hướng dẫn thanh toán hóa đơn.", f: "transfer (v/n), wire transfer (n), remittance (n), bank account (n)" },
  "due diligence": { m: "due = đúng mức cần thiết, diligence = siêng năng → kiểm tra kỹ lưỡng trước khi ký, mua.", e: "Sai: make due diligence → Đúng: conduct/carry out due diligence. Sai: due diligent → Đúng: due diligence.", u: "M&A/pháp lý/đầu tư: legal due diligence, financial due diligence before an acquisition; tư vấn thương vụ.", f: "diligent (adj), diligence (n), audit (n), vetting (n)" },
  "corporate social responsibility": { m: "Công ty 'có trách nhiệm' với xã hội và môi trường, không chỉ lo lợi nhuận. CSR.", e: "Sai: social responsible of company → Đúng: corporate social responsibility. Sai: do CSR activity → Đúng: carry out CSR activities.", u: "IELTS Writing/kinh doanh: companies should embrace CSR, CSR report, community projects; chủ đề trách nhiệm doanh nghiệp.", f: "CSR (n), responsible (adj), responsibility (n), ESG (n), sustainability (n)" },
  "benchmark": { m: "Vạch (mark) khắc trên ghế dài (bench) để đo chuẩn → mốc so sánh.", e: "Sai: benchmark with competitors → Đúng: benchmark against competitors. Sai: a bench mark → Đúng: a benchmark.", u: "Kinh doanh/IT: industry benchmark, set a benchmark, benchmark performance; so sánh chỉ số với đối thủ.", f: "benchmark (n/v), benchmarking (n), standard (n), yardstick (n)" },
  "revenue stream": { m: "stream = dòng suối → mỗi 'dòng' tiền chảy về từ một nguồn bán hàng.", e: "Sai: revenue streams of income → Đúng: revenue streams. Sai: many revenue stream → Đúng: multiple revenue streams.", u: "Khởi nghiệp/kinh doanh: diversify revenue streams, new revenue stream from subscriptions; business model canvas.", f: "revenue (n), income stream (n), source of income (n), monetize (v)" },
  "cost of goods sold": { m: "Chi phí (cost) của số hàng (goods) đã bán ra: nguyên liệu, nhân công trực tiếp. COGS.", e: "Sai: cost of good sold → Đúng: cost of goods sold. Sai: COGS includes rent of office → Đúng: office rent is an operating expense.", u: "Kế toán: calculate COGS, revenue minus COGS equals gross profit; báo cáo kết quả kinh doanh.", f: "COGS (n), cost of sales (n), gross profit (n), inventory (n)" },
  "diagnosis": { m: "dia (xuyên qua) + gnosis (biết) → 'nhìn xuyên' triệu chứng để biết bệnh gì.", e: "Sai: diagnosis him with cancer → Đúng: diagnose him with cancer (động từ). Sai: diagnosises → Đúng: diagnoses.", u: "Y khoa: make a diagnosis, early diagnosis, misdiagnosis; giải thích chẩn đoán cho bệnh nhân.", f: "diagnose (v), diagnosis (n, số nhiều diagnoses), diagnostic (adj), misdiagnosis (n)" },
  "vital signs": { m: "vital = sống còn → bốn dấu hiệu cho biết cơ thể còn ổn: mạch, huyết áp, nhịp thở, nhiệt độ.", e: "Sai: check vital sign of patient → Đúng: check the patient's vital signs. Sai: vital signals → Đúng: vital signs.", u: "Điều dưỡng/y khoa: monitor vital signs, vital signs are stable; bàn giao ca trực.", f: "vitals (n, khẩu ngữ), vital (adj), vitality (n), pulse (n)" },
  "prognosis": { m: "pro (trước) + gnosis (biết) → 'biết trước' bệnh sẽ diễn tiến ra sao.", e: "Sai: prognosis = diagnosis → Đúng: diagnosis xác định bệnh; prognosis dự đoán diễn tiến. Sai: good prognosis for → Đúng: a good prognosis.", u: "Y khoa: poor/good prognosis, long-term prognosis; trao đổi với gia đình bệnh nhân.", f: "prognosis (n, số nhiều prognoses), prognostic (adj), prognosticate (v), outlook (n)" },
  "surgeon": { m: "surgery (phẫu thuật) → surgeon là người cầm dao mổ.", e: "Sai: surgery doctor → Đúng: surgeon. Sai: he is surgery → Đúng: he is a surgeon / he had surgery.", u: "Y khoa: orthopedic surgeon, consultant surgeon, the surgeon performed the operation; IELTS Speaking về nghề.", f: "surgery (n), surgical (adj), surgically (adv), operate (v)" },
  "general practitioner": { m: "general = tổng quát, practitioner = người hành nghề → bác sĩ khám tổng quát đầu tiên. GP.", e: "Sai: general practice doctor man → Đúng: a general practitioner / a GP. Sai: go to GP → Đúng: go to the GP / see your GP.", u: "Y khoa (Anh, Úc): see your GP, GP referral to a specialist; IELTS Speaking về hệ thống y tế.", f: "GP (n), family doctor (n), practice (n), practitioner (n), physician (n)" },
  "outpatient": { m: "out (ra ngoài) → khám xong về nhà, không nằm viện.", e: "Sai: outside patient → Đúng: outpatient. Sai: outpatient department of → Đúng: the outpatient department (OPD).", u: "Bệnh viện: outpatient clinic, outpatient treatment, outpatient surgery; hướng dẫn quy trình khám.", f: "outpatient (n/adj), inpatient (n/adj), OPD (n), day patient (n)" },
  "inpatient": { m: "in (bên trong) → bệnh nhân nằm lại trong viện qua đêm.", e: "Sai: inside patient → Đúng: inpatient. Sai: be inpatient (thiếu kiên nhẫn) → Đúng: impatient; inpatient là bệnh nhân nội trú.", u: "Bệnh viện: inpatient ward, inpatient care, admitted as an inpatient; hồ sơ bảo hiểm phân biệt nội/ngoại trú.", f: "inpatient (n/adj), outpatient (n/adj), admit (v), admission (n), ward (n)" },
  "discharge": { m: "dis (bỏ) + charge (gánh) → bệnh viện 'trút gánh', cho bệnh nhân về.", e: "Sai: discharge out of hospital → Đúng: be discharged from hospital. Sai: the doctor discharged → Đúng: the doctor discharged the patient.", u: "Bệnh viện: discharge summary, discharge instructions, be discharged home; cũng nghĩa dịch tiết (discharge).", f: "discharge (v/n), admit (v, trái nghĩa), admission (n), release (v)" },
  "emergency room": { m: "Phòng (room) cho ca khẩn cấp (emergency). Mỹ: ER; Anh: A&E.", e: "Sai: take him to emergency → Đúng: take him to the emergency room / the ER. Sai: emergent room → Đúng: emergency room.", u: "Y khoa: ER doctor, rushed to the emergency room, ER wait times; Anh-Anh dùng A&E department.", f: "ER (n), A&E (n, Anh Anh), emergency department (n), emergency (n)" },
  "intensive care unit": { m: "intensive = chuyên sâu, liên tục → khu chăm sóc bệnh nặng 24/24. ICU.", e: "Sai: in the intensive care room → Đúng: in the intensive care unit / in the ICU. Sai: intensive care units nurse → Đúng: ICU nurse.", u: "Y khoa: admitted to the ICU, ICU beds, critical care; tin tức dịch bệnh, tình trạng quá tải.", f: "ICU (n), intensive care (n), critical care (n), intensive (adj)" },
  "operating room": { m: "operate = mổ → phòng nơi ca mổ diễn ra. Mỹ: OR; Anh: operating theatre.", e: "Sai: surgery room → Đúng: operating room / operating theatre. Sai: in operating room → Đúng: in the operating room.", u: "Y khoa: OR nurse, sterile operating room, scheduled into the operating room; quy trình vô khuẩn.", f: "OR (n), operating theatre (n, Anh Anh), operate (v), operation (n)" },
  "anesthesia": { m: "an (không) + esthesia (cảm giác) → mất cảm giác đau khi mổ.", e: "Sai: the patient was under anesthetic condition → Đúng: the patient was under general anesthesia. Sai: anesthesia doctor → Đúng: anesthesiologist.", u: "Y khoa: general/local anesthesia, anesthesiologist, recovery from anesthesia; tư vấn trước phẫu thuật.", f: "anesthetic (n/adj), anesthetist (n), anesthesiologist (n), anaesthesia (n, Anh Anh)" },
  "incision": { m: "in + cis (cắt, như 'scissors') → đường cắt vào da khi mổ.", e: "Sai: make an incise → Đúng: make an incision. Sai: incision wound bleed → Đúng: the incision is bleeding.", u: "Phẫu thuật: a small incision, close the incision, minimally invasive surgery with tiny incisions.", f: "incise (v), incision (n), incisive (adj), cut (n/v)" },
  "suture": { m: "Gần 'sew' (khâu) → sợi chỉ và mũi khâu khép vết thương.", e: "Sai: sew stitches into the wound → Đúng: close the wound with sutures. Sai: remove the suture next day → Đúng: remove the sutures after a week.", u: "Y khoa: absorbable sutures, suture removal, suture the wound; ghi chú phẫu thuật, phòng tiểu phẫu.", f: "suture (n/v), stitch (n/v), sew (v), wound closure (n)" },
  "dosage": { m: "dose (liều) + -age → lượng và cách dùng thuốc theo thời gian.", e: "Sai: take double dosage → Đúng: take a double dose. Sai: dosage of 2 pill → Đúng: a dosage of two tablets.", u: "Dược/y khoa: recommended dosage, adjust the dosage, dosage instructions on the label; tư vấn bệnh nhân.", f: "dose (n/v), dosage (n), overdose (n/v), underdose (n)" },
  "side effect": { m: "Tác dụng 'bên lề' (side) ngoài tác dụng chính của thuốc.", e: "Sai: the drug has side effect to the stomach → Đúng: the drug has side effects on the stomach.", u: "Y dược/IELTS Writing: common side effects, cause side effects, side effects of technology (nghĩa bóng).", f: "side-effect (n, biến thể), adverse effect (n), adverse reaction (n), effect (n)" },
  "adverse reaction": { m: "adverse = bất lợi → phản ứng xấu, ngoài ý muốn của cơ thể với thuốc.", e: "Sai: averse reaction → Đúng: adverse reaction (averse = ghét). Sai: reaction adverse with → Đúng: adverse reaction to.", u: "Dược lâm sàng: report adverse drug reactions (ADR), severe adverse reaction; cảnh giác dược.", f: "ADR (n), adverse (adj), adversely (adv), adverse event (n), side effect (n)" },
  "contraindication": { m: "contra (ngược) + indication (chỉ định) → trường hợp 'ngược chỉ định', không được dùng.", e: "Sai: this drug is contraindication for pregnant women → Đúng: this drug is contraindicated in pregnancy.", u: "Dược/y khoa: absolute contraindication, check contraindications before prescribing; tờ hướng dẫn sử dụng thuốc.", f: "contraindicate (v), contraindicated (adj), indication (n), indicate (v)" },
  "antibiotic": { m: "anti (chống) + bio (sự sống, vi khuẩn) → thuốc diệt vi khuẩn.", e: "Sai: take antibiotic for a cold virus → Đúng: antibiotics don't work against viruses. Sai: an antibiotics → Đúng: an antibiotic.", u: "Y khoa: prescribe antibiotics, a course of antibiotics, finish the course; IELTS chủ đề lạm dụng thuốc.", f: "antibiotic (n/adj), antibacterial (adj), antiviral (adj/n), penicillin (n)" },
  "antibiotic resistance": { m: "Vi khuẩn 'kháng' (resist) lại kháng sinh → thuốc mất tác dụng.", e: "Sai: people become resistant to antibiotics → Đúng: bacteria become resistant to antibiotics. Sai: antibiotics resistant → Đúng: antibiotic resistance.", u: "Y tế công cộng/IELTS Writing: overuse of antibiotics leads to antibiotic resistance; mối đe dọa toàn cầu.", f: "resist (v), resistance (n), resistant (adj), antimicrobial resistance (n), superbug (n)" },
  "vaccination": { m: "vacca = con bò (Latin) → vắc-xin đầu tiên lấy từ bệnh đậu bò.", e: "Sai: I vaccinated against flu (ý là được tiêm) → Đúng: I was vaccinated against flu / I got a flu vaccination.", u: "Y tế công cộng/IELTS Writing: vaccination programs, compulsory vaccination, vaccination rate; tranh luận bắt buộc tiêm chủng.", f: "vaccine (n), vaccinate (v), vaccination (n), immunize (v), jab (n, Anh Anh)" },
  "immunity": { m: "immune = được miễn → cơ thể 'được miễn' khỏi bệnh.", e: "Sai: immunity for the disease → Đúng: immunity to/against the disease. Sai: immunity system → Đúng: immune system.", u: "Y khoa/IELTS: herd immunity, natural immunity, boost immunity; bài viết về dịch bệnh, tiêm chủng.", f: "immune (adj), immunize (v), immunization (n), immunology (n)" },
  "immune system": { m: "immune = miễn dịch → 'đội quân' bảo vệ cơ thể khỏi vi trùng.", e: "Sai: immunity system → Đúng: immune system. Sai: weak immune → Đúng: a weak immune system.", u: "Y khoa/IELTS Speaking: boost/strengthen the immune system, weakened immune system; chủ đề sức khỏe, ăn uống.", f: "immune (adj), immunity (n), antibody (n), white blood cell (n)" },
  "inflammation": { m: "inflame = châm lửa → chỗ viêm nóng, đỏ, sưng như đang 'bốc lửa'.", e: "Sai: inflammation of the joint is inflamatory → Đúng: inflammatory (hai m). Sai: the knee is inflammation → Đúng: the knee is inflamed.", u: "Y khoa: reduce inflammation, chronic inflammation, anti-inflammatory drugs; mô tả triệu chứng.", f: "inflame (v), inflamed (adj), inflammatory (adj), anti-inflammatory (adj/n)" },
  "pathogen": { m: "patho (bệnh) + gen (sinh ra) → thứ 'sinh ra bệnh': vi khuẩn, virus, nấm.", e: "Sai: pathogens is virus only → Đúng: pathogens include viruses, bacteria and fungi. Sai: pathogene → Đúng: pathogen.", u: "Y khoa/vi sinh: airborne pathogens, pathogen transmission, infection control; báo cáo dịch tễ.", f: "pathogenic (adj), pathogenesis (n), pathology (n), germ (n), microbe (n)" },
  "pandemic": { m: "pan (tất cả) + demos (dân) → dịch lan tới mọi người trên toàn cầu.", e: "Sai: during pandemic → Đúng: during the pandemic. Sai: pandemic and epidemic are same → Đúng: a pandemic spreads globally.", u: "IELTS Writing/Speaking: the COVID-19 pandemic, post-pandemic recovery, pandemic preparedness; y tế công cộng.", f: "pandemic (n/adj), epidemic (n), endemic (adj), outbreak (n)" },
  "outbreak": { m: "break out = bùng ra → dịch bệnh hay chiến tranh 'bùng' lên đột ngột.", e: "Sai: the disease outbroke → Đúng: the disease broke out / there was an outbreak. Sai: outbreak about → Đúng: outbreak of.", u: "Y tế công cộng: an outbreak of measles, contain an outbreak, outbreak investigation; tin tức dịch bệnh.", f: "break out (v), outbreak (n), epidemic (n), flare-up (n)" },
  "quarantine": { m: "quaranta = bốn mươi (Ý) → tàu xưa phải chờ 40 ngày ngoài cảng.", e: "Sai: be quarantine at home → Đúng: be quarantined at home / be in quarantine. Sai: quarantine = isolation hoàn toàn → isolation dành cho người đã bệnh.", u: "Y tế công cộng: quarantine period, mandatory quarantine, quarantine facility; IELTS chủ đề đại dịch, du lịch.", f: "quarantine (n/v), isolate (v), isolation (n), self-isolation (n)" },
  "contagious": { m: "con (cùng) + tag (chạm) → chạm vào nhau là lây.", e: "Sai: contagious disease spread by air only → Đúng: contagious diseases spread through contact. Sai: contagion (danh từ) → Đúng: contagious (tính từ).", u: "Y khoa: highly contagious, contagious period; nghĩa bóng IELTS: 'her laughter is contagious'.", f: "contagion (n), contagiousness (n), infectious (adj), communicable (adj)" },
  "infectious disease": { m: "infect = nhiễm → bệnh do vi sinh vật xâm nhập và lây lan.", e: "Sai: infection disease → Đúng: infectious disease. Sai: an infectious diseases → Đúng: an infectious disease.", u: "Y khoa/IELTS Writing: infectious disease control, spread of infectious diseases; khoa truyền nhiễm bệnh viện.", f: "infect (v), infection (n), infectious (adj), communicable disease (n)" },
  "acute": { m: "acute = nhọn, sắc → bệnh đến nhanh, dữ dội; trái nghĩa chronic (mạn tính).", e: "Sai: acute disease lasts many years → Đúng: chronic disease lasts many years; acute illness comes on suddenly.", u: "Y khoa: acute pain, acute appendicitis, acute care; IELTS: 'an acute shortage of nurses' (nghĩa trầm trọng).", f: "acutely (adv), acuteness (n), chronic (adj, trái nghĩa), severe (adj)" },
  "diabetes": { m: "dia (xuyên qua) + bainein (đi) → nước tiểu 'chảy xuyên qua' nhiều, có đường.", e: "Sai: he has a diabetes → Đúng: he has diabetes (không mạo từ). Sai: he is diabetes → Đúng: he is diabetic.", u: "Y khoa/IELTS Writing: type 2 diabetes, manage diabetes, diabetes linked to poor diet; chủ đề béo phì.", f: "diabetic (adj/n), type 1 diabetes (n), blood sugar (n), insulin (n)" },
  "hypertension": { m: "hyper (quá mức) + tension (áp lực) → áp lực máu lên thành mạch quá cao.", e: "Sai: he has a high hypertension → Đúng: he has hypertension / high blood pressure. Sai: hypertension of blood → Đúng: hypertension.", u: "Y khoa: diagnosed with hypertension, treat hypertension, risk factor for stroke; tư vấn lối sống.", f: "hypertensive (adj), high blood pressure (n), hypotension (n, trái nghĩa)" },
  "blood pressure": { m: "pressure = áp lực → lực máu ép lên thành mạch, đo bằng mmHg.", e: "Sai: my blood pressure is high level → Đúng: my blood pressure is high. Sai: measure blood pressure for me → Đúng: take my blood pressure.", u: "Y khoa/IELTS Speaking: take/check blood pressure, high/low blood pressure, BP reading; khám sức khỏe.", f: "BP (n), hypertension (n), hypotension (n), systolic (adj), diastolic (adj)" },
  "heart rate": { m: "rate = tốc độ → số nhịp tim đập mỗi phút (bpm).", e: "Sai: heart rate is 70 times → Đúng: heart rate is 70 beats per minute. Sai: heart speed → Đúng: heart rate.", u: "Y khoa/thể thao: resting heart rate, elevated heart rate, heart rate monitor; dữ liệu đồng hồ thông minh.", f: "pulse (n), heartbeat (n), bpm (n), tachycardia (n)" },
  "cardiovascular disease": { m: "cardio (tim) + vascular (mạch máu) → bệnh của tim và mạch máu. CVD.", e: "Sai: cardiovascular diseases is → Đúng: cardiovascular disease is. Sai: cardio vascular → Đúng: cardiovascular (viết liền).", u: "Y tế/IELTS Writing: leading cause of death is cardiovascular disease, reduce the risk through exercise.", f: "CVD (n), cardiovascular (adj), cardiac (adj), heart disease (n)" },
  "heart attack": { m: "Tim bị 'tấn công' (attack) vì mạch vành tắc, cơ tim thiếu máu.", e: "Sai: he got heart attack → Đúng: he had a heart attack. Sai: heart attack = cardiac arrest → khác: cardiac arrest là tim ngừng đập.", u: "Y khoa/IELTS Speaking: suffer a heart attack, warning signs, risk factors; nói về lối sống lành mạnh.", f: "myocardial infarction (n, thuật ngữ), cardiac arrest (n), stroke (n)" },
  "tumor": { m: "tumere = sưng phồng (Latin) → khối mô 'phồng' lên bất thường.", e: "Sai: all tumors are cancer → Đúng: tumors can be benign or malignant. Anh Anh viết 'tumour'.", u: "Ung bướu: benign/malignant tumor, remove a tumor, brain tumor; báo cáo chẩn đoán hình ảnh.", f: "tumour (n, Anh Anh), growth (n), mass (n), lump (n), neoplasm (n)" },
  "benign": { m: "bene = tốt (như benefit) → u lành, không lan, không nguy hiểm.", e: "Sai: the tumor is benefit → Đúng: the tumor is benign. Phát âm: /bɪˈnaɪn/, chữ g câm.", u: "Y khoa: a benign tumor, benign lump; ngoài y khoa: a benign smile (hiền hậu).", f: "benignly (adv), malignant (adj, trái nghĩa), benevolent (adj, cùng gốc)" },
  "malignant": { m: "mal = xấu (như malware) → u ác, xâm lấn và di căn.", e: "Sai: malignant is cancer type → Đúng: a malignant tumor is cancerous. Sai: malignance → Đúng: malignancy.", u: "Ung bướu: malignant tumor, malignant melanoma, test for malignancy; giải thích kết quả sinh thiết.", f: "malignancy (n), malign (adj/v), benign (adj, trái nghĩa)" },
  "metastasis": { m: "meta (thay đổi vị trí) + stasis (đứng) → tế bào ung thư 'dời chỗ' sang cơ quan khác.", e: "Sai: the cancer metastasis to the lungs → Đúng: the cancer metastasized to the lungs. Số nhiều: metastases.", u: "Ung bướu: distant metastasis, metastatic cancer, detect metastases on scans; phân giai đoạn ung thư.", f: "metastasize (v), metastatic (adj), metastases (n, số nhiều), spread (n/v)" },
  "chemotherapy": { m: "chemo (hóa chất) + therapy (điều trị) → dùng thuốc hóa chất diệt tế bào ung thư.", e: "Sai: do chemotherapy for him → Đúng: he is having/receiving chemotherapy. Sai: a chemo → Đúng: a round of chemo.", u: "Ung bướu: undergo chemotherapy, chemotherapy cycles, side effects such as hair loss; tư vấn bệnh nhân.", f: "chemo (n, khẩu ngữ), radiotherapy (n), immunotherapy (n), therapy (n)" },
  "radiotherapy": { m: "radio (tia bức xạ) + therapy → chiếu tia phóng xạ diệt khối u.", e: "Sai: radio therapy → Đúng: radiotherapy (Anh) / radiation therapy (Mỹ). Sai: make radiotherapy → Đúng: have radiotherapy.", u: "Ung bướu: course of radiotherapy, radiotherapy sessions, combined with chemotherapy; lập kế hoạch điều trị.", f: "radiation therapy (n), radiation (n), radiologist (n), radiology (n)" },
  "biopsy": { m: "bio (sống) + opsy (nhìn) → lấy mẫu mô sống để nhìn dưới kính hiển vi.", e: "Sai: biopsy the patient → Đúng: take/perform a biopsy. Sai: biopsy test result is malignancy → Đúng: the biopsy showed malignancy.", u: "Ung bướu/bệnh học: needle biopsy, biopsy results, send a sample for biopsy; khẳng định chẩn đoán ung thư.", f: "biopsy (n/v), autopsy (n, cùng đuôi), specimen (n), tissue sample (n)" },
  "blood test": { m: "Xét nghiệm (test) lấy máu để kiểm tra chỉ số trong cơ thể.", e: "Sai: do blood test → Đúng: have/take a blood test. Sai: the blood test shows normal → Đúng: the blood test results are normal.", u: "Y khoa/IELTS Speaking: routine blood test, fasting blood test, blood test results; khám sức khỏe tổng quát.", f: "blood work (n, Mỹ), blood sample (n), lab test (n), full blood count (n)" },
  "urine test": { m: "urine = nước tiểu → xét nghiệm mẫu nước tiểu tìm dấu hiệu bệnh.", e: "Sai: urinal test → Đúng: urine test (urinal = bồn tiểu). Sai: give urine test → Đúng: provide a urine sample.", u: "Y khoa: urine test for infection, drug urine test, urinalysis; hướng dẫn lấy mẫu.", f: "urinalysis (n), urine (n), urinate (v), urinary (adj)" },
  "x-ray": { m: "Tia 'X' bí ẩn mà Röntgen phát hiện, chiếu xuyên cơ thể để thấy xương.", e: "Sai: take x-ray for the leg → Đúng: have an X-ray of the leg / X-ray the leg.", u: "Y khoa: chest X-ray, X-ray shows a fracture, X-ray department; an ninh sân bay: X-ray machine.", f: "X-ray (n/v), radiograph (n), radiology (n), radiologist (n)" },
  "ultrasound": { m: "ultra (vượt) + sound → sóng âm vượt ngưỡng tai nghe, dội lại tạo hình ảnh.", e: "Sai: do an ultrasound for baby → Đúng: have an ultrasound scan to check the baby. Sai: ultra sound → Đúng: ultrasound.", u: "Y khoa/sản khoa: ultrasound scan, abdominal ultrasound, prenatal ultrasound; chẩn đoán hình ảnh không xâm lấn.", f: "ultrasonic (adj), sonogram (n), scan (n), sonography (n)" },
  "computed tomography": { m: "tomo = lát cắt + graphy = ghi → máy tính ghép các lát cắt X-quang thành ảnh. CT.", e: "Sai: computer tomography → Đúng: computed tomography. Sai: take a CT → Đúng: have a CT scan.", u: "Chẩn đoán hình ảnh: CT scan of the head, contrast CT, detect internal bleeding; khoa cấp cứu dùng nhiều.", f: "CT (n), CT scan (n), CAT scan (n), tomography (n), scanner (n)" },
  "magnetic resonance imaging": { m: "magnetic = từ trường, resonance = cộng hưởng → dùng nam châm mạnh tạo ảnh mô mềm. MRI.", e: "Sai: magnet resonance imaging → Đúng: magnetic resonance imaging. Sai: do a MRI → Đúng: have an MRI (đọc /em/).", u: "Chẩn đoán hình ảnh: MRI scan of the brain/knee, remove metal objects before MRI; so sánh với CT.", f: "MRI (n), MRI scan (n), magnet (n), magnetic (adj), imaging (n)" },
  "medical history": { m: "history = lịch sử → 'lịch sử' bệnh tật, phẫu thuật, dị ứng của một người.", e: "Sai: history of medical → Đúng: medical history. Sai: medical histories of me → Đúng: my medical history.", u: "Y khoa: take a medical history, family medical history, past medical history; phỏng vấn bệnh nhân lần đầu.", f: "case history (n), past medical history (n), anamnesis (n), medical record (n)" },
  "medical record": { m: "record = bản ghi → hồ sơ ghi chép mọi lần khám, điều trị.", e: "Sai: medical records is → Đúng: medical records are. Sai: medicine record → Đúng: medical record.", u: "Bệnh viện/IT y tế: electronic medical records (EMR), access medical records, patient confidentiality.", f: "EMR (n), EHR (n), health record (n), record (n/v), chart (n)" },
  "physical examination": { m: "physical = thuộc cơ thể → bác sĩ khám trực tiếp: nhìn, sờ, gõ, nghe.", e: "Sai: physic examination → Đúng: physical examination. Sai: do a physical examination to the patient → Đúng: perform a physical examination on the patient.", u: "Y khoa: perform a physical examination, findings on physical examination; khám tuyển dụng, ghi bệnh án.", f: "physical exam (n), physical (n, Mỹ khẩu ngữ), examine (v), examination (n)" },
  "check-up": { m: "check up on = kiểm tra lại → đi khám định kỳ khi chưa có bệnh.", e: "Sai: check-up my health → Đúng: have a check-up. Sai: go to check-up health → Đúng: go for a check-up.", u: "Y khoa/IELTS Speaking: regular check-ups, annual check-up, dental check-up; nói về thói quen chăm sóc sức khỏe.", f: "checkup (n, Mỹ), check up (v), medical (n, Anh Anh), physical (n)" },
  "screening": { m: "screen = cái sàng → 'sàng' cả nhóm người để tìm sớm bệnh chưa có triệu chứng.", e: "Sai: screening the cancer → Đúng: screening for cancer. Sai: a screening test to sick people → Đúng: for healthy people.", u: "Y tế công cộng: cancer screening, screening program, newborn screening; IELTS Writing về y tế dự phòng.", f: "screen (v/n), screening test (n), early detection (n), check-up (n)" },
  "health insurance": { m: "insure = bảo đảm → trả phí trước để được chi trả khi ốm đau.", e: "Sai: buy health insurances → Đúng: buy health insurance (không đếm được). Sai: insurance health card → Đúng: health insurance card.", u: "Y tế/IELTS Writing: universal health insurance, coverage, premium; TOEIC: phúc lợi nhân viên.", f: "insure (v), insurance (n), insurer (n), policyholder (n), premium (n)" },
  "primary care": { m: "primary = đầu tiên → tuyến chăm sóc đầu tiên bạn gặp: GP, trạm y tế.", e: "Sai: primary health → Đúng: primary care / primary health care. Sai: primary care is hospital surgery → Đúng: primary care is first-contact care.", u: "Y tế công cộng: primary care physician, access to primary care, strengthen primary care; chính sách y tế.", f: "primary health care (n), secondary care (n), tertiary care (n), GP (n)" },
  "public health": { m: "public = cộng đồng → lo sức khỏe cả cộng đồng, không chỉ từng bệnh nhân.", e: "Sai: the public health of a person → Đúng: a person's health; public health concerns the population.", u: "IELTS Writing/y tế: public health campaign, public health crisis, threat to public health; ngành y tế dự phòng.", f: "public health official (n), epidemiology (n), community health (n), healthcare (n)" },
  "epidemiology": { m: "epi (trên) + demos (dân) + logy (môn học) → khoa học về bệnh lan trên dân số.", e: "Sai: epidemiology is study a disease in one person → Đúng: epidemiology studies diseases in populations.", u: "Y tế công cộng/nghiên cứu: epidemiology study, epidemiologist, track infection rates; báo cáo dịch tễ.", f: "epidemiologist (n), epidemiological (adj), epidemic (n), pandemic (n)" },
  "clinical trial": { m: "clinic = phòng khám, trial = thử nghiệm → thử thuốc mới trên người theo quy trình chặt.", e: "Sai: clinic trial → Đúng: clinical trial. Sai: join clinical trial → Đúng: take part in a clinical trial.", u: "Nghiên cứu y dược: phase III clinical trial, randomized controlled trial, trial participants; tin tức vắc-xin mới.", f: "clinical (adj), clinician (n), trial (n), RCT (n), placebo (n)" },
  "placebo": { m: "placebo = 'tôi sẽ làm hài lòng' (Latin) → viên thuốc giả mà người uống tin là thật.", e: "Sai: placebo is a fake doctor → Đúng: a placebo is a dummy pill. Sai: placebo affect → Đúng: placebo effect.", u: "Nghiên cứu y khoa: placebo group, placebo-controlled trial, the placebo effect; IELTS Reading tâm lý học.", f: "placebo effect (n), nocebo (n), dummy pill (n), control group (n)" },
  "evidence-based medicine": { m: "Y học dựa trên (based on) bằng chứng (evidence) nghiên cứu, không theo cảm tính.", e: "Sai: evidence-base medicine → Đúng: evidence-based medicine. Sai: medicine based evidence → Đúng: evidence-based medicine.", u: "Y khoa: practice evidence-based medicine, clinical guidelines, systematic reviews; đào tạo bác sĩ.", f: "EBM (n), evidence-based (adj), evidence (n), clinical guideline (n)" },
  "anatomy": { m: "ana (lên) + tomy (cắt) → cắt mở cơ thể để học cấu trúc.", e: "Sai: anatomy of the body function → Đúng: anatomy is structure; physiology is function. Sai: anatomic class → Đúng: anatomy class.", u: "Y khoa: human anatomy, anatomy lecture, anatomical structures; sinh viên y năm nhất.", f: "anatomical (adj), anatomically (adv), anatomist (n), physiology (n)" },
  "physiology": { m: "physio (tự nhiên, cơ thể) + logy → môn học cơ thể 'hoạt động' thế nào.", e: "Sai: physiology = physical therapy → Đúng: physiology là sinh lý học; physiotherapy là vật lý trị liệu.", u: "Y khoa/sinh học: human physiology, exercise physiology, physiological changes; giảng dạy y khoa cơ sở.", f: "physiological (adj), physiologist (n), anatomy (n), physiotherapy (n)" },
  "pathology": { m: "patho (bệnh) + logy → môn học về bệnh; khoa xem mẫu mô tìm bệnh.", e: "Sai: pathology lab do surgery → Đúng: the pathology lab examines tissue samples. Sai: a pathologic doctor → Đúng: a pathologist.", u: "Bệnh viện: pathology report, pathology department, clinical pathology; trả kết quả sinh thiết.", f: "pathologist (n), pathological (adj), pathogen (n), histopathology (n)" },
  "pharmacology": { m: "pharmaco (thuốc) + logy → khoa học về tác dụng của thuốc lên cơ thể.", e: "Sai: pharmacology = pharmacy → Đúng: pharmacy là nhà thuốc/ngành dược; pharmacology là dược lý học.", u: "Dược/y khoa: clinical pharmacology, drug interactions, pharmacology exam; nghiên cứu phát triển thuốc.", f: "pharmacologist (n), pharmacological (adj), pharmacy (n), pharmacist (n)" },
  "pediatrics": { m: "ped (trẻ em, như pediatrician) + iatr (chữa bệnh) → khoa chữa bệnh trẻ em.", e: "Sai: pediatrics are → Đúng: pediatrics is (môn học số ít). Sai: pediatric doctor → Đúng: pediatrician.", u: "Bệnh viện: pediatrics department, pediatric ward, pediatric nurse; Anh Anh viết paediatrics.", f: "pediatric (adj), pediatrician (n), paediatrics (n, Anh Anh), neonatology (n)" },
  "obstetrics": { m: "obstetrix = bà đỡ (Latin) → ngành lo mang thai và sinh nở.", e: "Sai: obstetrics is women diseases → Đúng: gynecology covers women's diseases; obstetrics covers pregnancy and childbirth.", u: "Bệnh viện: obstetrics and gynecology (OB-GYN), obstetric care, labor ward; khám thai định kỳ.", f: "obstetric (adj), obstetrician (n), OB-GYN (n), gynecology (n), midwife (n)" },
  "cardiology": { m: "cardio (tim, như cardio tập thể dục) + logy → chuyên khoa về tim.", e: "Sai: cardiology doctor → Đúng: cardiologist. Sai: go to cardiology department of → Đúng: be referred to cardiology.", u: "Bệnh viện: cardiology department, referred to cardiology, interventional cardiology; chuyển tuyến chuyên khoa.", f: "cardiologist (n), cardiac (adj), cardiovascular (adj), cardiogram (n)" },
  "neurology": { m: "neuro (thần kinh) + logy → chuyên khoa não, tủy sống, dây thần kinh.", e: "Sai: neurology = psychiatry → Đúng: neurology treats brain/nerve disorders; psychiatry treats mental illness. Sai: neurology doctor → Đúng: neurologist.", u: "Bệnh viện: neurology ward, neurological examination, stroke, epilepsy; chuyển khám chuyên khoa thần kinh.", f: "neurologist (n), neurological (adj), neuron (n), neuroscience (n)" },
  "oncology": { m: "onco (khối, u) + logy → chuyên khoa về u bướu, ung thư.", e: "Sai: oncology doctor → Đúng: oncologist. Sai: oncology is only surgery → Đúng: oncology includes chemotherapy and radiotherapy.", u: "Bệnh viện: oncology department, medical oncology, oncology nurse; điều trị đa mô thức ung thư.", f: "oncologist (n), oncological (adj), cancer (n), tumor (n)" },
  "orthopedics": { m: "ortho (thẳng) + pedics (trẻ em) → xưa là nắn thẳng xương trẻ; nay chữa xương khớp.", e: "Sai: orthopedics doctor → Đúng: orthopedic surgeon. Sai: orthopedics are → Đúng: orthopedics is.", u: "Bệnh viện: orthopedics ward, orthopedic surgery, sports injuries, joint replacement; Anh Anh: orthopaedics.", f: "orthopedic (adj), orthopedist (n), orthopaedics (n, Anh Anh), fracture (n)" },
  "dermatology": { m: "derma (da, như dermatologist) + logy → chuyên khoa về da.", e: "Sai: she is a dermatology → Đúng: she is a dermatologist. Sai: skin department → Đúng: the dermatology department.", u: "Bệnh viện/mỹ phẩm: dermatology clinic, acne treatment, dermatologist-tested products; tư vấn chăm sóc da.", f: "dermatologist (n), dermatological (adj), dermis (n), skin (n)" },
  "psychiatry": { m: "psych (tâm trí) + iatry (chữa trị) → chữa bệnh của tâm trí.", e: "Sai: psychiatry = psychology → Đúng: psychiatrists are doctors who can prescribe drugs; psychologists usually cannot.", u: "Y khoa: psychiatry department, psychiatric assessment, refer to a psychiatrist; chủ đề sức khỏe tâm thần.", f: "psychiatrist (n), psychiatric (adj), psychology (n), psychologist (n)" },
  "mental health": { m: "mental = thuộc tinh thần → sức khỏe của tâm trí, cảm xúc.", e: "Sai: mental health problem is crazy → Đúng: mental health problems include anxiety and depression. Sai: mentally health → Đúng: mental health.", u: "IELTS Speaking/Writing: social media affects young people's mental health, mental health awareness, mental health services.", f: "mental (adj), mentally (adv), mental illness (n), well-being (n)" },
  "anxiety disorder": { m: "anxiety = lo âu; disorder = rối loạn → lo âu kéo dài vượt mức bình thường.", e: "Sai: anxious disorder → Đúng: anxiety disorder. Sai: she is anxiety → Đúng: she is anxious / she has an anxiety disorder.", u: "Tâm thần học: generalized anxiety disorder (GAD), panic disorder, treated with therapy (CBT); IELTS chủ đề áp lực.", f: "anxious (adj), anxiety (n), panic attack (n), phobia (n), disorder (n)" },
  "cardiac arrest": { m: "arrest = dừng lại → tim đột ngột 'bị bắt dừng', không bơm máu.", e: "Sai: cardiac arrest = heart attack → Đúng: cardiac arrest is when the heart stops; a heart attack is a blocked artery.", u: "Cấp cứu: go into cardiac arrest, sudden cardiac arrest, start CPR immediately; báo động code blue.", f: "cardiac (adj), arrest (n/v), heart attack (n), defibrillator (n)" },
  "cardiopulmonary resuscitation": { m: "cardio (tim) + pulmonary (phổi) + resuscitate (hồi sinh) → ép tim, thổi ngạt cứu người. CPR.", e: "Sai: do a CPR → Đúng: perform CPR / give CPR. Sai: cardio pulmonary → Đúng: cardiopulmonary.", u: "Cấp cứu/sơ cứu: perform CPR, chest compressions, CPR training; khóa học kỹ năng sơ cứu.", f: "CPR (n), resuscitate (v), resuscitation (n), defibrillation (n)" },
  "first aid": { m: "aid = sự giúp đỡ → giúp 'đầu tiên' trước khi có nhân viên y tế.", e: "Sai: give the first aid → Đúng: give first aid. Sai: first aid box kit → Đúng: first aid kit.", u: "An toàn lao động/IELTS Speaking: first aid kit, first aid training, administer first aid; kỹ năng sống.", f: "first-aider (n), first aid kit (n), CPR (n), aid (n/v)" },
  "fracture": { m: "fract = gãy (như fraction, fragile) → xương bị gãy hoặc rạn nứt.", e: "Sai: he fractured his leg bone broken → Đúng: he fractured his leg. Sai: a fracture of the leg bone broken → Đúng: a leg fracture.", u: "Y khoa/chấn thương: hip fracture, stress fracture, X-ray confirmed a fracture; khoa chấn thương chỉnh hình.", f: "fracture (n/v), fractured (adj), break (n/v), fragile (adj, cùng gốc)" },
  "bleeding": { m: "bleed (chảy máu) + -ing → máu chảy ra ngoài hoặc trong cơ thể.", e: "Sai: his nose is blooding → Đúng: his nose is bleeding. Quá khứ: bleed → bled (không phải bleeded).", u: "Y khoa/sơ cứu: stop the bleeding, internal bleeding, apply pressure to control bleeding; cấp cứu chấn thương.", f: "bleed (v), blood (n), bloody (adj), hemorrhage (n), blood loss (n)" },
  "hemorrhage": { m: "hemo- (máu, như 'hemoglobin') + -rrhage (vỡ, tuôn) → máu tuôn ra → xuất huyết.", e: "Sai: The patient has a bleeding hemorrhage → Đúng: The patient has a hemorrhage. Chú ý đánh vần: hemo-rr-hage (hai chữ r).", u: "Y khoa: brain hemorrhage, postpartum hemorrhage, control the hemorrhage. Bệnh án ghi 'internal hemorrhage' khi chảy máu trong.", f: "hemorrhage (n/v), hemorrhagic (adj), haemorrhage (Anh-Anh)" },
  "blood transfusion": { m: "trans- (sang) + fuse (rót, chảy) → rót máu từ người này sang người kia → truyền máu.", e: "Sai: The patient was transferred blood → Đúng: The patient received a blood transfusion. Không dùng 'transfer' cho truyền máu.", u: "Bệnh viện: need a blood transfusion, transfusion reaction, kiểm tra nhóm máu trước khi truyền; phiếu đồng ý truyền máu.", f: "transfusion (n), transfuse (v), blood donor (n), blood type (n)" },
  "intravenous": { m: "intra- (bên trong) + venous (tĩnh mạch, như 'vein') → đưa vào trong tĩnh mạch. Viết tắt IV.", e: "Sai: give medicine by intravenous → Đúng: give medicine intravenously / by IV. 'Intravenous' là tính từ, cần danh từ đi kèm.", u: "Điều dưỡng: intravenous fluids, IV drip, IV line, administer antibiotics intravenously. Y lệnh ghi đường dùng: oral, IV, IM.", f: "intravenous (adj), intravenously (adv), IV (n), vein (n), venous (adj)" },
  "injection": { m: "in- (vào) + ject (ném, phóng, như 'project') → phóng thuốc vào cơ thể → mũi tiêm.", e: "Sai: The nurse injected me a vaccine → Đúng: The nurse gave me an injection / injected the vaccine into my arm.", u: "Y tế: have an injection, injection site, insulin injection. Ngành khác: fuel injection (động cơ), cash injection (tài chính).", f: "injection (n), inject (v), injectable (adj/n), syringe (n)" },
  "over-the-counter": { m: "Hình ảnh: thuốc mua ngay qua quầy (counter), không cần bác sĩ viết đơn. Viết tắt OTC.", e: "Sai: buy over-the-counter medicine with prescription → Đúng: buy it over the counter, without a prescription. Đứng trước danh từ thì có gạch nối.", u: "Dược: over-the-counter drugs vs prescription drugs, OTC painkillers. Tài chính: OTC market là thị trường phi tập trung.", f: "over-the-counter (adj), over the counter (adv), OTC; trái nghĩa: prescription-only" },
  "painkiller": { m: "pain (đau) + killer (kẻ giết) → thứ 'giết' cơn đau → thuốc giảm đau.", e: "Sai: I drank a painkiller → Đúng: I took a painkiller. Thuốc viên dùng động từ 'take', không dùng 'drink'.", u: "Phòng khám/nhà thuốc: take painkillers, strong painkiller, overuse of painkillers. Speaking: kể chuyện bị đau đầu, đau răng.", f: "painkiller (n), analgesic (n, thuật ngữ), pain relief (n), relieve pain (v)" },
  "asthma": { m: "Gốc Hy Lạp nghĩa là 'thở hổn hển' → bệnh khiến người bệnh thở khò khè, khó thở.", e: "Sai: He has an asthma → Đúng: He has asthma. Phát âm /ˈæzmə/, âm 'th' câm.", u: "Y khoa: asthma attack, asthma inhaler, allergic asthma. IELTS về ô nhiễm: air pollution triggers asthma in children.", f: "asthma (n), asthmatic (adj/n), inhaler (n), wheeze (v)" },
  "pneumonia": { m: "pneumo- (phổi/khí, như 'pneumatic') → bệnh ở phổi → viêm phổi. Chữ 'p' đầu câm.", e: "Sai: phát âm /pnuˈmoʊniə/ → Đúng: /nuːˈmoʊniə/. Sai: catch a pneumonia → Đúng: catch/develop pneumonia.", u: "Bệnh viện: diagnosed with pneumonia, chest X-ray, hospital-acquired pneumonia. Nhi khoa: viêm phổi ở trẻ dưới 5 tuổi.", f: "pneumonia (n), pneumonic (adj), pneumococcal (adj), lung infection" },
  "tuberculosis": { m: "tubercle (cục u nhỏ) + -osis (bệnh) → bệnh tạo các nốt nhỏ trong phổi → lao. Viết tắt TB.", e: "Sai: He is infected tuberculosis → Đúng: He is infected with tuberculosis / has TB.", u: "Y tế công cộng: TB screening, drug-resistant tuberculosis, BCG vaccine. Hồ sơ visa thường yêu cầu xét nghiệm lao.", f: "tuberculosis (n), tubercular (adj), TB (n), tuberculin test (n)" },
  "dengue fever": { m: "Dengue gốc Tây Ban Nha; fever = sốt. Muỗi vằn đốt → sốt cao, có thể xuất huyết.", e: "Sai: dengue fever virus spread by flies → Đúng: dengue is spread by Aedes mosquitoes. Phát âm /ˈdeŋɡi/.", u: "Y tế Việt Nam: dengue outbreak, mùa mưa, platelet count, dengue hemorrhagic fever. IELTS: dịch bệnh vùng nhiệt đới.", f: "dengue (n), dengue hemorrhagic fever (n), mosquito-borne (adj), Aedes (n)" },
  "dehydration": { m: "de- (lấy đi) + hydr- (nước, như 'hydrogen') → bị lấy mất nước → mất nước.", e: "Sai: I am dehydration → Đúng: I am dehydrated / I suffer from dehydration. Tính từ là 'dehydrated'.", u: "Lâm sàng: severe dehydration, oral rehydration solution (ORS) khi tiêu chảy. Speaking: nắng nóng, chạy bộ, uống đủ nước.", f: "dehydration (n), dehydrate (v), dehydrated (adj), rehydration (n), hydrate (v)" },
  "fever": { m: "Liên tưởng 'fervent' (nồng nhiệt): cơ thể nóng hừng hực → sốt.", e: "Sai: I am fever → Đúng: I have a fever / I have a temperature. Sai: high fever 39 độ → Đúng: a fever of 39°C.", u: "Khám bệnh: run a fever, fever and chills, the fever broke. Nghĩa bóng: World Cup fever (cơn sốt bóng đá).", f: "fever (n), feverish (adj), feverishly (adv), temperature (n)" },
  "chronic pain": { m: "chron- (thời gian, như 'chronology') → đau kéo dài theo thời gian, trên 3 tháng → đau mạn tính.", e: "Sai: chronic pain for two days → Đúng: acute pain for two days. 'Chronic' chỉ dùng cho đau dai dẳng, nhiều tháng.", u: "Phục hồi chức năng: manage chronic pain, chronic back pain, pain clinic. Phân biệt với acute pain (đau cấp).", f: "chronic (adj), chronically (adv), acute pain (trái nghĩa), persistent pain" },
  "physiotherapy": { m: "physio- (cơ thể, tự nhiên) + therapy (trị liệu) → chữa bằng vận động, xoa bóp, không dùng thuốc.", e: "Sai: I go to physiotherapy doctor → Đúng: I see a physiotherapist / I have physiotherapy sessions.", u: "Phục hồi chức năng: physiotherapy after surgery, sports injury, a course of physiotherapy. Anh-Mỹ hay gọi 'physical therapy'.", f: "physiotherapy (n), physiotherapist (n), physio (n, thân mật), physical therapy (Mỹ)" },
  "palliative care": { m: "palliate = làm dịu (gốc 'pallium': áo choàng che phủ) → che chở, làm dịu đau khổ cuối đời.", e: "Sai: palliative care cures cancer → Đúng: palliative care relieves symptoms and improves quality of life.", u: "Ung bướu, lão khoa: refer to palliative care, end-of-life care, hospice. Tập trung vào giảm đau, hỗ trợ gia đình.", f: "palliative (adj), palliate (v), hospice care (n), end-of-life care (n)" },
  "chronic kidney disease": { m: "chronic (kéo dài) + kidney (thận) → thận suy giảm từ từ qua nhiều năm. Viết tắt CKD.", e: "Sai: chronic kidneys disease → Đúng: chronic kidney disease. Danh từ làm định ngữ để số ít.", u: "Thận học: stage 3 chronic kidney disease, eGFR, end-stage renal disease cần lọc máu hoặc ghép thận.", f: "kidney (n), renal (adj), CKD, renal failure (n), nephrology (n)" },
  "dialysis": { m: "dia- (xuyên qua) + lysis (tách ra) → máu đi qua màng lọc để tách chất độc → chạy thận.", e: "Sai: He does dialysis machine → Đúng: He is on dialysis / He has dialysis three times a week.", u: "Bệnh viện: dialysis unit, haemodialysis, peritoneal dialysis, dialysis patient chờ ghép thận.", f: "dialysis (n, số nhiều dialyses), dialyse/dialyze (v), haemodialysis (n)" },
  "organ transplant": { m: "trans- (sang) + plant (trồng) → 'trồng' một cơ quan từ người này sang người khác.", e: "Sai: He was transplanted a new liver → Đúng: He had a liver transplant / received a transplanted liver.", u: "Y khoa: organ transplant waiting list, organ rejection, kidney transplant. IELTS Writing: tranh luận về hiến tạng.", f: "transplant (n/v), transplantation (n), organ donor (n), recipient (n)" },
  "donor": { m: "don- (cho, như 'donate') + -or (người) → người cho đi máu, tạng hoặc tiền.", e: "Sai: She is a blood donator → Đúng: She is a blood donor. Dùng 'donor', không dùng 'donator'.", u: "Y tế: blood donor, organ donor card, universal donor (nhóm O). Từ thiện: anonymous donor, international donors.", f: "donor (n), donate (v), donation (n), recipient (n, trái nghĩa)" },
  "hormone": { m: "Gốc Hy Lạp 'hormao' = thúc đẩy → chất thúc cơ thể hoạt động → hóc-môn.", e: "Sai: hormone of growth → Đúng: growth hormone. Phát âm /ˈhɔːrmoʊn/, nhấn âm đầu.", u: "Nội tiết: thyroid hormone, hormone levels, hormone therapy, hormonal imbalance. Speaking: tuổi dậy thì, căng thẳng.", f: "hormone (n), hormonal (adj), endocrine (adj), endocrinology (n)" },
  "insulin": { m: "insula (hòn đảo, Latin) → tiết từ 'đảo tụy' (islets) → hóc-môn hạ đường huyết.", e: "Sai: He drinks insulin every day → Đúng: He injects insulin / takes insulin injections every day.", u: "Tiểu đường: insulin resistance, insulin pen, insulin-dependent diabetes. Điều dưỡng hướng dẫn bệnh nhân tự tiêm.", f: "insulin (n), insulin-dependent (adj), insulin resistance (n), pancreas (n)" },
  "cholesterol": { m: "chole- (mật) + stereos (rắn) → chất béo rắn tìm thấy trong sỏi mật đầu tiên.", e: "Sai: My cholesterol is high level → Đúng: My cholesterol level is high / I have high cholesterol.", u: "Khám sức khỏe: LDL (bad) và HDL (good) cholesterol, lower cholesterol, cholesterol test. Speaking: chế độ ăn.", f: "cholesterol (n), LDL/HDL cholesterol, lipid (n), statin (n, thuốc hạ mỡ)" },
  "metabolism": { m: "meta- (thay đổi) + bole (ném) → cơ thể liên tục biến đổi thức ăn thành năng lượng.", e: "Sai: My metabolic is slow → Đúng: My metabolism is slow. 'Metabolic' là tính từ: metabolic rate.", u: "Dinh dưỡng, nội tiết: boost metabolism, slow metabolism, metabolic rate, metabolic syndrome. Speaking: giảm cân, tập luyện.", f: "metabolism (n), metabolic (adj), metabolize (v), metabolite (n)" },
  "respiratory": { m: "re- (lại) + spire (thở, như 'inspire') → hít thở lặp lại → thuộc hô hấp.", e: "Sai: respiratory problem in the stomach → Đúng: respiratory problems affect the lungs and airways. Phát âm /ˈrespərətɔːri/.", u: "Y khoa: respiratory infection, respiratory tract, respiratory failure. IELTS: air pollution causes respiratory diseases.", f: "respiratory (adj), respiration (n), respirator (n), respire (v)" },
  "nervous system": { m: "nerve (dây thần kinh) → nervous ở đây là 'thuộc thần kinh', không phải 'lo lắng'.", e: "Sai: The nervous system is very nervous → Đúng: Stress affects the nervous system. Đừng nhầm với nghĩa 'hồi hộp'.", u: "Sinh lý, thần kinh học: central nervous system (CNS), peripheral nervous system, damage to the nervous system.", f: "nerve (n), neural (adj), neurological (adj), CNS, neurology (n)" },
  "digestive system": { m: "di- (tách) + gest (mang) → mang thức ăn đi và tách nhỏ ra → hệ tiêu hóa.", e: "Sai: My digestion system is weak → Đúng: My digestive system is weak / I have poor digestion.", u: "Tiêu hóa học: digestive system disorders, digestive tract, gastroenterology. Speaking: ăn cay, đồ ăn nhanh.", f: "digest (v), digestion (n), digestive (adj), indigestion (n), gastrointestinal (adj)" },
  "sterile": { m: "Gốc Latin 'không sinh sản' → không vi khuẩn nào sống, sinh sôi được → vô trùng.", e: "Sai: The tools are sterilized clean → Đúng: The tools are sterile / have been sterilized. Không thừa 'clean'.", u: "Phòng mổ: sterile gloves, sterile field, sterile dressing. Nghĩa khác: vô sinh (người/động vật), cằn cỗi (đất).", f: "sterile (adj), sterilize (v), sterilization (n), sterility (n)" },
  "disinfect": { m: "dis- (bỏ đi) + infect (lây nhiễm) → loại bỏ mầm lây nhiễm → khử trùng.", e: "Sai: disinfect the wound with alcohol water → Đúng: disinfect the wound with antiseptic. Lưu ý: disinfectant (n) là chất khử trùng.", u: "Kiểm soát nhiễm khuẩn: disinfect surfaces, hand disinfectant, disinfect medical equipment. Thường gặp trong quy trình vệ sinh.", f: "disinfect (v), disinfection (n), disinfectant (n), antiseptic (n/adj), sanitize (v)" },
  "preventive medicine": { m: "pre- (trước) + vent (đến) → chặn trước khi bệnh đến → y học dự phòng.", e: "Sai: prevention medicine → Đúng: preventive (hoặc preventative) medicine. Dùng tính từ, không dùng danh từ.", u: "Y tế công cộng: vaccination, screening, health education. IELTS Writing: governments should invest more in preventive medicine.", f: "prevent (v), prevention (n), preventive/preventative (adj), prophylaxis (n)" },
  "mortality rate": { m: "mort- (chết, như 'mortal', 'mortuary') → tỷ lệ người chết trong một nhóm.", e: "Sai: The mortality rate increased to 5 people → Đúng: The mortality rate rose to 5 per 1,000.", u: "Dịch tễ, IELTS Writing Task 1: infant mortality rate, mortality rate fell sharply, so sánh số liệu các nước.", f: "mortality (n), mortal (adj), death rate (n), morbidity (n, tỷ lệ mắc bệnh)" },
  "informed consent": { m: "informed (đã được thông tin) + consent (đồng ý) → đồng ý sau khi hiểu rõ rủi ro.", e: "Sai: The patient signed an inform consent → Đúng: The patient signed an informed consent form. Có '-ed'.", u: "Y khoa, nghiên cứu: obtain informed consent before surgery, consent form, clinical trial ethics.", f: "consent (n/v), informed (adj), consent form (n), assent (n)" },
  "health care": { m: "health (sức khỏe) + care (chăm sóc) → mọi dịch vụ giữ gìn sức khỏe người dân.", e: "Sai: healthcares are expensive → Đúng: health care is expensive. Danh từ không đếm được; cũng viết 'healthcare'.", u: "IELTS Writing: access to health care, universal health care, public health care system. Ngành: healthcare workers.", f: "health care / healthcare (n), healthcare provider (n), health system (n)" },
  "antibody": { m: "anti- (chống) + body (thể) → 'thể chống lại' mầm bệnh → kháng thể.", e: "Sai: antibody is a medicine killing bacteria → Đúng: antibodies are proteins made by the immune system. Đừng nhầm với antibiotic.", u: "Miễn dịch, xét nghiệm: antibody test, produce antibodies, antibody levels after vaccination.", f: "antibody (n), antigen (n), immune (adj), immunity (n), antibiotic (n, khác nghĩa)" },
  "pulse": { m: "Latin 'pulsus' = nhịp đập → mạch đập theo nhịp tim, như 'pulse' âm nhạc.", e: "Sai: The doctor measured my pulse rate heart → Đúng: The doctor took/checked my pulse.", u: "Khám lâm sàng: take a pulse, weak pulse, pulse rate 72 beats per minute. Nghĩa khác: đậu (thực phẩm), xung (điện).", f: "pulse (n/v), pulsate (v), pulsation (n), heart rate (n)" },
  "engineering": { m: "engine (máy móc) + -eer (người) + -ing → nghề của người làm ra máy móc, công trình.", e: "Sai: I study engineer → Đúng: I study engineering / I am an engineering student. 'Engineer' là người.", u: "IELTS Speaking (học tập, nghề nghiệp): major in engineering, engineering degree. Ngành: engineering department, engineering team.", f: "engineering (n), engineer (n/v), engineered (adj), mechanical/electrical engineering" },
  "civil engineering": { m: "civil (dân sự, công dân) → kỹ thuật làm công trình phục vụ dân: cầu, đường, nhà.", e: "Sai: civil engineering is about laws → Đúng: civil engineering deals with roads, bridges and buildings.", u: "Xây dựng: civil engineering projects, civil engineer, structural engineering. CV: degree in civil engineering.", f: "civil engineer (n), structural engineering (n), infrastructure (n), construction (n)" },
  "manufacturing": { m: "manu- (tay) + fact (làm) → làm bằng tay, nay bằng máy → sản xuất chế tạo.", e: "Sai: a manufacturing of cars → Đúng: car manufacturing / the manufacture of cars.", u: "Nhà máy, TOEIC: manufacturing plant, manufacturing costs, manufacturing sector. IELTS: Việt Nam là trung tâm sản xuất.", f: "manufacture (v/n), manufacturer (n), manufacturing (n/adj), manufactured (adj)" },
  "production line": { m: "Hình ảnh: sản phẩm đi theo một đường thẳng (line), mỗi trạm làm một bước.", e: "Sai: The product comes out from production line → Đúng: The product comes off the production line.", u: "Nhà máy: production line stoppage, line speed, line leader, roll off the production line.", f: "production (n), produce (v), assembly line (n), line worker (n)" },
  "assembly line": { m: "assemble (ráp lại) + line → công nhân đứng dọc dây chuyền, mỗi người lắp một chi tiết.", e: "Sai: work in assemble line → Đúng: work on an assembly line. Giới từ 'on'.", u: "Ô tô, điện tử: assembly line worker, automated assembly line, Ford's moving assembly line.", f: "assemble (v), assembly (n), assembler (n), production line (n)" },
  "spare part": { m: "spare = dư ra, dự phòng (như 'spare tire') → linh kiện để sẵn thay khi hỏng.", e: "Sai: We are out of spare parts machine → Đúng: We are out of spare parts for the machine.", u: "Bảo trì, TOEIC: order spare parts, spare parts inventory, genuine spare parts, lead time.", f: "spare (adj/n), spares (n), replacement part (n), component (n)" },
  "raw material": { m: "raw = sống, chưa chế biến (như 'raw fish') → vật liệu chưa qua xử lý.", e: "Sai: raw materials price increase → Đúng: raw material prices have increased. Dùng thì đúng và 'prices'.", u: "Sản xuất, TOEIC: raw material costs, shortage of raw materials, source raw materials. IELTS: xuất khẩu nguyên liệu thô.", f: "raw (adj), material (n), commodity (n), finished goods (n, trái nghĩa)" },
  "technical drawing": { m: "technical (kỹ thuật) + drawing (bản vẽ) → bản vẽ có kích thước, ký hiệu chuẩn.", e: "Sai: read the technical draw → Đúng: read the technical drawing. Cũng nói 'engineering drawing', 'blueprint'.", u: "Cơ khí, xây dựng: interpret technical drawings, dimensions, tolerance, revision number trên khung tên.", f: "drawing (n), draw (v), draftsman (n), blueprint (n), schematic (n)" },
  "computer-aided design": { m: "aided = được trợ giúp → máy tính giúp vẽ, thiết kế. Viết tắt CAD.", e: "Sai: computer-aid design → Đúng: computer-aided design. Có '-ed' và gạch nối.", u: "Kỹ thuật: CAD software, CAD model, CAD drawing, kết hợp CAM (computer-aided manufacturing).", f: "CAD (n), CAM (n), aid (v/n), 3D modelling (n)" },
  "prototype": { m: "proto- (đầu tiên) + type (kiểu) → kiểu đầu tiên làm thử → nguyên mẫu.", e: "Sai: make a prototype product test → Đúng: build a prototype to test the design.", u: "R&D, startup: build a prototype, working prototype, rapid prototyping, prototype testing trước sản xuất hàng loạt.", f: "prototype (n/v), prototyping (n), prototypical (adj), mock-up (n)" },
  "tolerance": { m: "tolerate (chịu đựng) → mức lệch kích thước mà chi tiết 'chịu được' vẫn đạt.", e: "Sai: tolerance is ±0.05 mm error → Đúng: the tolerance is ±0.05 mm. Không thêm 'error'.", u: "Cơ khí, QC: tight tolerance, within tolerance, out of tolerance. Nghĩa chung: lòng khoan dung, khả năng chịu đựng.", f: "tolerance (n), tolerate (v), tolerant (adj), tolerable (adj)" },
  "calibration": { m: "calibre (cỡ, chuẩn) → chỉnh thiết bị về đúng chuẩn đo.", e: "Sai: calibrate the machine for correct → Đúng: calibrate the machine to ensure accuracy.", u: "Đo lường, QC, phòng thí nghiệm: calibration certificate, calibration schedule, due for calibration.", f: "calibration (n), calibrate (v), calibrated (adj), recalibrate (v)" },
  "precision": { m: "pre- (trước) + cis (cắt) → cắt sẵn thật gọn → độ chính xác, tinh xảo.", e: "Sai: high precise machine → Đúng: high-precision machine / a very precise machine.", u: "Cơ khí: precision engineering, precision components, with great precision. Thống kê: precision khác accuracy.", f: "precision (n), precise (adj), precisely (adv), imprecise (adj)" },
  "machine tool": { m: "Công cụ (tool) dạng máy để chế tạo chi tiết khác: tiện, phay, khoan, mài.", e: "Sai: machine tool means hand tools → Đúng: machine tools are powered machines like lathes and mills.", u: "Cơ khí: machine tool industry, CNC machine tools, machine tool operator.", f: "machine (n/v), machinist (n), lathe (n), milling machine (n)" },
  "lathe": { m: "Hình ảnh: phôi xoay tròn, dao cắt tiện đi → máy tiện. Phát âm /leɪð/.", e: "Sai: phát âm /læθ/ → Đúng: /leɪð/. Sai: work at lathe machine → Đúng: work on a lathe.", u: "Cơ khí: lathe operator, CNC lathe, turn a part on the lathe, lathe chuck.", f: "lathe (n), turning (n), turner (n), chuck (n)" },
  "milling": { m: "mill (cối xay) → dao phay xoay như cối xay, gọt bề mặt phôi.", e: "Sai: milling machine for flour in factory part → Đúng: a milling machine cuts metal parts. Nghĩa 'xay bột' chỉ trong thực phẩm.", u: "Gia công: CNC milling, milling cutter, end mill, face milling. Thường đi cùng turning trong báo giá gia công.", f: "mill (n/v), milling (n), miller (n), milling machine (n)" },
  "welding": { m: "weld gần 'well' (sôi) → nung kim loại nóng chảy để nối liền.", e: "Sai: welding two pipes together by glue → Đúng: welding joins two pipes by melting the metal.", u: "Cơ khí, xây dựng: arc welding, welding joint, welder certificate, welding inspection, an toàn khi hàn.", f: "weld (v/n), welder (n), welding (n), weldable (adj), solder (v, hàn thiếc)" },
  "casting": { m: "cast (ném, đổ) → đổ kim loại lỏng vào khuôn → đúc.", e: "Sai: casting by hammering → Đúng: casting is pouring molten metal into a mould; hammering is forging.", u: "Đúc: die casting, sand casting, casting defects. Nghĩa khác: tuyển diễn viên (phim).", f: "cast (v/n), casting (n), foundry (n), die-cast (adj)" },
  "mold": { m: "Hình ảnh: cái khuôn bánh → đổ vật liệu vào, lấy ra đúng hình. Anh-Anh: mould.", e: "Sai: mold is also only fungus → Đúng: mold có hai nghĩa: khuôn và nấm mốc. Anh-Anh viết 'mould'.", u: "Nhựa, đúc: mold design, mold maker, mold cavity, mold maintenance. Thường gặp trong nhà máy ép phun.", f: "mold/mould (n/v), molding (n), moldable (adj), die (n)" },
  "injection molding": { m: "injection (phun vào) + molding → phun nhựa nóng chảy vào khuôn kín.", e: "Sai: injection mold process → Đúng: injection molding process. Cũng viết 'injection moulding' (Anh).", u: "Nhựa: injection molding machine, cycle time, plastic parts, short shot, flash defect.", f: "injection molding (n), injection-molded (adj), mold (n), extrusion (n)" },
  "forging": { m: "forge (lò rèn) → nung đỏ rồi búa đập tạo hình → rèn.", e: "Sai: forging is pouring liquid metal → Đúng: forging shapes hot metal with hammers or presses.", u: "Cơ khí: hot forging, forged steel, forging press. Nghĩa khác: forge = giả mạo (chữ ký, giấy tờ).", f: "forge (v/n), forging (n), forged (adj), forger (n), forgery (n)" },
  "machining": { m: "machine dùng như động từ → gia công bằng máy để cắt gọt kim loại.", e: "Sai: machinery process the part → Đúng: machining the part. 'Machinery' là máy móc nói chung.", u: "Gia công: CNC machining, machining center, machining allowance, precision machining services.", f: "machine (v/n), machining (n), machinist (n), machinery (n), machinable (adj)" },
  "cnc": { m: "Computer Numerical Control: máy tính dùng số và mã G để điều khiển dao cắt.", e: "Sai: CNC is a type of metal → Đúng: CNC is a control method for machine tools. Viết in hoa: CNC.", u: "Gia công: CNC machine, CNC programmer, CNC milling, G-code. Tuyển dụng: CNC operator.", f: "CNC (n/adj), CNC machining (n), G-code (n), NC (n)" },
  "robot": { m: "Gốc Séc 'robota' = lao động khổ sai → cỗ máy làm việc thay người.", e: "Sai: robots will replace human totally → Đúng: robots will replace many human workers. Danh từ đếm được, chia số nhiều.", u: "Tự động hóa: industrial robot, robotic arm, robot cell. IELTS Writing: robots and unemployment.", f: "robot (n), robotic (adj), robotics (n), cobot (n), automation (n)" },
  "programmable logic controller": { m: "programmable (lập trình được) + logic controller → 'bộ não' điều khiển máy trong nhà máy. Viết tắt PLC.", e: "Sai: program logic control → Đúng: programmable logic controller (PLC).", u: "Tự động hóa: PLC programming, ladder logic, PLC wiring, Siemens hoặc Mitsubishi PLC trên dây chuyền.", f: "PLC (n), program (v/n), programmable (adj), controller (n), HMI (n)" },
  "sensor": { m: "sense (cảm nhận) + -or → thiết bị cảm nhận nhiệt, áp, chuyển động.", e: "Sai: sensor is broken so machine stops itself → Đúng: the sensor failed, so the machine stopped automatically.", u: "Kỹ thuật: temperature sensor, proximity sensor, sensor reading, IoT sensors.", f: "sensor (n), sense (v/n), sensing (n), sensory (adj)" },
  "actuator": { m: "act (hành động) → bộ phận biến tín hiệu điều khiển thành chuyển động thật.", e: "Sai: actuator detects the temperature → Đúng: a sensor detects; an actuator moves (valve, motor, cylinder).", u: "Tự động hóa: electric actuator, pneumatic actuator, valve actuator, sensor–controller–actuator loop.", f: "actuator (n), actuate (v), actuation (n), cylinder (n)" },
  "control system": { m: "Hệ thống nhận tín hiệu cảm biến, so sánh, ra lệnh cho cơ cấu chấp hành.", e: "Sai: control systems is complex → Đúng: control systems are complex / the control system is complex.", u: "Tự động hóa: closed-loop control system, PID, SCADA, control system upgrade.", f: "control (n/v), controller (n), controllable (adj), automation (n)" },
  "hydraulic": { m: "hydr- (nước) + aulos (ống) → dùng chất lỏng trong ống để truyền lực.", e: "Sai: hydraulic system uses compressed air → Đúng: hydraulic uses oil/liquid; pneumatic uses air.", u: "Máy móc: hydraulic press, hydraulic cylinder, hydraulic oil, hydraulic leak, máy xúc.", f: "hydraulic (adj), hydraulics (n), hydraulically (adv), pneumatic (adj, đối chiếu)" },
  "pneumatic": { m: "pneuma (hơi thở, không khí) → vận hành bằng khí nén.", e: "Sai: phát âm /pnuːˈmætɪk/ → Đúng: /nuːˈmætɪk/, chữ 'p' câm như 'pneumonia'.", u: "Tự động hóa: pneumatic cylinder, pneumatic tool, air supply 6 bar, pneumatic valve.", f: "pneumatic (adj), pneumatics (n), compressed air (n), hydraulic (adj, đối chiếu)" },
  "compressor": { m: "compress (nén lại) + -or → máy nén khí hoặc môi chất.", e: "Sai: the compressor makes air cold itself → Đúng: the compressor pressurizes the refrigerant or air.", u: "Nhà máy, điện lạnh: air compressor, compressor room, compressor failure, máy lạnh.", f: "compressor (n), compress (v), compression (n), compressed (adj)" },
  "valve": { m: "Hình ảnh: cánh cửa nhỏ trong ống, mở cho chất lỏng đi, đóng để chặn.", e: "Sai: open the valve water → Đúng: open the water valve. Đừng nhầm 'valve' với 'value'.", u: "Đường ống: gate valve, ball valve, safety valve, check valve. Y khoa: van tim (heart valve).", f: "valve (n), valving (n), check valve (n), faucet/tap (n)" },
  "bearing": { m: "bear (chịu, đỡ) → chi tiết đỡ trục quay, giảm ma sát → ổ bi.", e: "Sai: The bearing is broke → Đúng: The bearing is worn / has failed. Nghĩa khác: have a bearing on = liên quan.", u: "Bảo trì: ball bearing, bearing failure, grease the bearings, bearing noise, vibration analysis.", f: "bearing (n), bear (v), ball bearing (n), roller bearing (n)" },
  "shaft": { m: "Hình ảnh: thanh tròn dài như cán giáo, quay để truyền chuyển động → trục.", e: "Sai: the shaft of the motor is turning round → Đúng: the motor shaft rotates.", u: "Cơ khí: drive shaft, shaft alignment, keyway. Xây dựng, mỏ: elevator shaft, mine shaft.", f: "shaft (n), drive shaft (n), axle (n), spindle (n)" },
  "turbine": { m: "Latin 'turbo' = xoáy → cánh quạt quay nhờ dòng khí, nước, hơi.", e: "Sai: wind turbin → Đúng: wind turbine. Phát âm /ˈtɜːrbaɪn/.", u: "Năng lượng: wind turbine, steam turbine, gas turbine, turbine blade. IELTS: năng lượng tái tạo.", f: "turbine (n), turbo (n), turbocharger (n), generator (n)" },
  "conveyor belt": { m: "convey (chuyên chở) + belt (dây đai) → dải đai chạy vòng chở hàng.", e: "Sai: products move on conveyor by belt → Đúng: products move along the conveyor belt.", u: "Kho, nhà máy, sân bay: conveyor belt jam, belt speed, baggage conveyor.", f: "convey (v), conveyor (n), conveyance (n), belt (n)" },
  "lubrication": { m: "lubric- (trơn, như 'lube') → làm trơn để chi tiết chạy êm.", e: "Sai: put the lubrication on the chain → Đúng: apply lubricant to the chain. 'Lubrication' là quá trình.", u: "Bảo trì: lubrication schedule, lubrication points, poor lubrication causes wear.", f: "lubrication (n), lubricate (v), lubricant (n), lube (n, thân mật)" },
  "friction": { m: "Latin 'fricare' = chà xát → lực cản khi hai bề mặt cọ nhau.", e: "Sai: reduce the friction force between them is important → Đúng: reducing friction between them is important.", u: "Vật lý, cơ khí: coefficient of friction, friction loss. Nghĩa bóng: friction between departments (mâu thuẫn).", f: "friction (n), frictional (adj), frictionless (adj), abrasion (n)" },
  "torque": { m: "Latin 'torquere' = xoắn (như 'torture') → lực làm vật xoay quanh trục.", e: "Sai: tighten the bolt with force 50 Nm → Đúng: tighten the bolt to a torque of 50 Nm.", u: "Cơ khí, ô tô: torque wrench, torque specification, engine torque, tighten to specified torque.", f: "torque (n/v), torque wrench (n), torsion (n), moment (n)" },
  "tensile strength": { m: "tense (căng) → sức chịu lực kéo căng trước khi đứt.", e: "Sai: tension strength → Đúng: tensile strength. Dùng tính từ 'tensile'.", u: "Vật liệu: high tensile strength steel, ultimate tensile strength, tensile test, MPa.", f: "tensile (adj), tension (n), tense (adj), yield strength (n)" },
  "corrosion": { m: "cor- (hoàn toàn) + rode (gặm) → bị gặm dần → ăn mòn.", e: "Sai: The metal is corrosion → Đúng: The metal is corroded / shows corrosion.", u: "Vật liệu, xây dựng: corrosion resistance, rust, protect against corrosion, anti-corrosion coating.", f: "corrosion (n), corrode (v), corrosive (adj), corrosion-resistant (adj)" },
  "alloy": { m: "Liên tưởng 'ally' (đồng minh) → các kim loại liên kết với nhau → hợp kim.", e: "Sai: alloy is a pure metal → Đúng: an alloy is a mixture of metals, e.g. brass, steel.", u: "Vật liệu: aluminium alloy, alloy steel, alloy wheels (mâm xe). Phát âm /ˈælɔɪ/.", f: "alloy (n/v), alloyed (adj), metal (n), metallurgy (n)" },
  "stainless steel": { m: "stain (vết bẩn, gỉ) + -less (không) → thép không gỉ, inox.", e: "Sai: inox steel → Đúng: stainless steel. 'Inox' là từ tiếng Pháp, người bản ngữ nói 'stainless steel'.", u: "Cơ khí, thực phẩm, y tế: 304 stainless steel, stainless steel tank, kitchen equipment.", f: "stainless (adj), steel (n), carbon steel (n), inox (Pháp)" },
  "composite material": { m: "compose (ghép) → hai vật liệu khác nhau ghép lại cho tính năng tốt hơn.", e: "Sai: composite materials is light → Đúng: composite materials are light. Chia động từ số nhiều.", u: "Hàng không, ô tô: carbon fibre composite, fibreglass, lightweight composites.", f: "composite (adj/n), compose (v), composition (n), fibreglass (n)" },
  "reinforced concrete": { m: "re- + in- + force (sức) → thêm sức cho bê tông bằng cốt thép.", e: "Sai: concrete reinforcement building → Đúng: a reinforced concrete building. Dùng tính từ '-ed'.", u: "Xây dựng: reinforced concrete slab, column, rebar, concrete cover, structural design.", f: "reinforce (v), reinforcement (n), rebar (n), precast concrete (n)" },
  "cement": { m: "Latin 'caementum' = đá vụn → bột kết dính đá, cát thành khối.", e: "Sai: cement and concrete are the same → Đúng: cement is an ingredient of concrete.", u: "Xây dựng: cement plant, Portland cement, bag of cement, cement mortar. Nghĩa bóng: cement a relationship.", f: "cement (n/v), cementitious (adj), concrete (n), mortar (n)" },
  "beam": { m: "Hình ảnh: thanh ngang chịu tải, giống tia sáng (beam) chạy thẳng.", e: "Sai: column is horizontal beam → Đúng: beams are horizontal; columns are vertical.", u: "Kết cấu: steel beam, concrete beam, load on a beam, beam deflection. Nghĩa khác: tia sáng, cười rạng rỡ.", f: "beam (n/v), girder (n), joist (n), column (n)" },
  "scaffolding": { m: "Hình ảnh: khung ống thép dựng quanh nhà cho thợ đứng làm → giàn giáo.", e: "Sai: a scaffoldings → Đúng: scaffolding (không đếm được) / a scaffold. Không thêm 's'.", u: "An toàn công trường: erect scaffolding, scaffolding inspection, fall protection. Giáo dục: scaffolding = hỗ trợ học tập.", f: "scaffold (n), scaffolding (n), scaffolder (n), formwork (n)" },
  "construction site": { m: "construction (xây dựng) + site (địa điểm) → nơi đang xây.", e: "Sai: in the construction site → Đúng: on a construction site. Giới từ 'on'.", u: "Xây dựng: construction site safety, site manager, hard hat area. IELTS: tiếng ồn từ công trường.", f: "construct (v), construction (n), building site (n), worksite (n)" },
  "site engineer": { m: "site (công trường) + engineer → kỹ sư có mặt tại công trường giám sát thi công.", e: "Sai: She works as site engineering → Đúng: She works as a site engineer.", u: "Xây dựng: site engineer giám sát thi công, kiểm tra bản vẽ, báo cáo tiến độ, làm việc với nhà thầu.", f: "site engineer (n), project engineer (n), site manager (n), supervisor (n)" },
  "feasibility study": { m: "feasible (khả thi, gốc 'faire' = làm được) → nghiên cứu xem dự án làm được không.", e: "Sai: make a feasible study → Đúng: conduct/carry out a feasibility study.", u: "Dự án, đầu tư: feasibility study report, technical and financial feasibility, phê duyệt dự án.", f: "feasible (adj), feasibility (n), infeasible (adj), viability (n)" },
  "bill of materials": { m: "bill (danh sách) + materials → danh sách toàn bộ vật tư để làm một sản phẩm. Viết tắt BOM.", e: "Sai: bill of material list → Đúng: bill of materials (BOM). Không thừa 'list'.", u: "Sản xuất, ERP: multi-level BOM, update the BOM, BOM cost, part number.", f: "BOM (n), material (n), parts list (n), ERP (n)" },
  "quality control": { m: "control (kiểm soát) chất lượng → kiểm tra sản phẩm có đạt chuẩn không. Viết tắt QC.", e: "Sai: quality controller check → Đúng: quality control checks / a QC inspector. Phân biệt QC (kiểm tra) và QA (đảm bảo).", u: "Nhà máy, TOEIC: quality control department, QC inspection, pass quality control.", f: "quality control (n), quality assurance (n), QC, QA, inspector (n)" },
  "defect rate": { m: "defect (lỗi, khuyết tật) + rate (tỷ lệ) → bao nhiêu phần trăm sản phẩm bị lỗi.", e: "Sai: The defect rate is very high level → Đúng: The defect rate is very high. Không thừa 'level'.", u: "QC: reduce the defect rate, defect rate of 0.5%, defects per million (DPMO), báo cáo chất lượng.", f: "defect (n/v), defective (adj), reject rate (n), yield (n)" },
  "root cause analysis": { m: "Hình ảnh: đào tới rễ (root) cây để tìm nguyên nhân thật. Viết tắt RCA.", e: "Sai: analysis root cause → Đúng: carry out a root cause analysis. Không đảo trật tự.", u: "QC, bảo trì: 5 Whys, fishbone diagram, root cause analysis report, corrective action.", f: "root cause (n), RCA, 5 Whys, Ishikawa diagram, corrective action (n)" },
  "standard operating procedure": { m: "Quy trình (procedure) chuẩn (standard) để vận hành (operating) giống nhau mỗi lần. Viết tắt SOP.", e: "Sai: follow standard operation procedure → Đúng: follow the standard operating procedure (SOP).", u: "Nhà máy, y tế, phòng lab: write an SOP, SOP training, deviation from the SOP.", f: "SOP (n), procedure (n), work instruction (n), protocol (n)" },
  "iso standard": { m: "ISO gốc Hy Lạp 'isos' = bằng nhau → chuẩn chung để mọi nơi giống nhau.", e: "Sai: our company has ISO → Đúng: our company is ISO 9001 certified / meets ISO standards.", u: "Quản lý chất lượng: ISO 9001, ISO 14001, ISO certification, ISO audit.", f: "ISO (n), standard (n), standardize (v), certification (n)" },
  "lean manufacturing": { m: "lean = gầy, gọn → bỏ hết mỡ thừa, tức lãng phí, trong sản xuất.", e: "Sai: lean manufacture system → Đúng: lean manufacturing (system). Dùng dạng '-ing'.", u: "Quản lý sản xuất: eliminate waste, Toyota Production System, 5S, kanban, value stream mapping.", f: "lean (adj), lean production (n), Toyota Production System, waste (muda)" },
  "just-in-time": { m: "Hàng về 'vừa đúng lúc' cần dùng → không tồn kho thừa. Viết tắt JIT.", e: "Sai: just in time delivery system (không gạch nối) → Đúng: a just-in-time delivery system.", u: "Chuỗi cung ứng: just-in-time inventory, JIT production, giảm tồn kho nhưng dễ đứt gãy.", f: "JIT, lean manufacturing, kanban (n), inventory (n)" },
  "continuous improvement": { m: "continuous (liên tục) + improvement → cải tiến từng chút mỗi ngày (Kaizen).", e: "Sai: continuous improve → Đúng: continuous improvement. Đừng nhầm continuous với continual.", u: "Quản lý: continuous improvement culture, PDCA cycle, kaizen event, suggestion system.", f: "improve (v), improvement (n), kaizen (n), PDCA (n)" },
  "six sigma": { m: "sigma (σ) = độ lệch chuẩn; sáu sigma → gần như không lỗi (3,4 lỗi/triệu).", e: "Sai: 6 sigmas method → Đúng: the Six Sigma methodology. Viết hoa, không thêm 's'.", u: "Chất lượng: Six Sigma Green Belt, DMAIC, reduce process variation, lean six sigma.", f: "Six Sigma (n), DMAIC, Green Belt (n), Lean Six Sigma (n)" },
  "throughput": { m: "through (xuyên qua) + put → lượng sản phẩm đi qua hệ thống trong một đơn vị thời gian.", e: "Sai: increase the throughputs → Đúng: increase throughput. Thường không đếm được.", u: "Sản xuất, CNTT: line throughput, units per hour, bottleneck limits throughput, network throughput.", f: "throughput (n), output (n), capacity (n), bottleneck (n)" },
  "preventive maintenance": { m: "Bảo trì trước (pre-) khi máy hỏng, theo lịch định sẵn.", e: "Sai: we do maintenance when machine is broken, it is preventive → Đúng: that is corrective maintenance; preventive is scheduled.", u: "Bảo trì: preventive maintenance schedule, PM checklist, reduce downtime, TPM.", f: "preventive (adj), maintenance (n), maintain (v), predictive maintenance (n)" },
  "breakdown": { m: "break down (gãy xuống) → máy ngừng hoạt động → sự hỏng hóc.", e: "Sai: The machine was breakdown → Đúng: The machine broke down / had a breakdown. Động từ tách rời 'break down'.", u: "Bảo trì: machine breakdown, breakdown time. Nghĩa khác: bảng phân tích chi tiết (cost breakdown), suy sụp tinh thần.", f: "breakdown (n), break down (v), downtime (n), failure (n)" },
  "overhaul": { m: "over (toàn bộ) + haul (kéo) → kéo ra tháo toàn bộ để kiểm tra, sửa → đại tu.", e: "Sai: overhaul the small screw → Đúng: overhaul the engine. Dùng cho máy lớn, toàn bộ hệ thống.", u: "Bảo trì: engine overhaul, major overhaul, overhaul interval. Quản lý: overhaul the tax system (cải tổ).", f: "overhaul (n/v), refurbish (v), rebuild (v), renovation (n)" },
  "troubleshooting": { m: "trouble (rắc rối) + shoot (bắn hạ) → tìm và 'bắn hạ' lỗi → xử lý sự cố.", e: "Sai: troubleshoot of the printer → Đúng: troubleshoot the printer. Không thêm 'of'.", u: "Kỹ thuật, IT: troubleshooting guide, troubleshoot a fault, step-by-step diagnosis.", f: "troubleshoot (v), troubleshooter (n), troubleshooting (n), diagnose (v)" },
  "occupational safety": { m: "occupation (nghề nghiệp) + safety → an toàn trong khi làm nghề.", e: "Sai: occupation safety → Đúng: occupational safety (and health). Dùng tính từ.", u: "Nhà máy, xây dựng: occupational safety training, OSH, workplace accidents, safety officer.", f: "occupation (n), occupational (adj), OSH, workplace safety (n)" },
  "personal protective equipment": { m: "Thiết bị (equipment) bảo vệ (protective) cho từng người (personal): mũ, găng, kính. Viết tắt PPE.", e: "Sai: wear PPEs / a personal protective equipments → Đúng: wear PPE / personal protective equipment. Không đếm được.", u: "An toàn lao động: PPE required, hard hat, safety glasses, gloves, ear protection.", f: "PPE (n), protect (v), protective (adj), protection (n)" },
  "risk assessment": { m: "assess (đánh giá) rủi ro → xem nguy cơ có thể xảy ra và mức độ nặng nhẹ.", e: "Sai: do a risk assessing → Đúng: carry out a risk assessment.", u: "An toàn, dự án: risk assessment form, identify hazards, likelihood and severity, control measures.", f: "assess (v), assessment (n), risk (n/v), hazard (n), risky (adj)" },
  "voltage": { m: "Volt (tên nhà khoa học Volta) + -age → 'sức đẩy' dòng điện, đo bằng vôn.", e: "Sai: The voltage is 220 volt → Đúng: The voltage is 220 volts. Danh từ số nhiều.", u: "Điện: high voltage, low voltage, voltage drop, rated voltage, cảnh báo 'High Voltage'.", f: "voltage (n), volt (n), voltmeter (n), current (n)" },
  "circuit breaker": { m: "Hình ảnh: tự 'bẻ gãy' (break) mạch điện (circuit) khi quá tải → cầu dao, aptomat.", e: "Sai: The circuit breaker is jumped → Đúng: The circuit breaker tripped. Động từ là 'trip'.", u: "Điện: circuit breaker tripped, reset the breaker, MCB, panel board. Tài chính: ngắt giao dịch khi thị trường lao dốc.", f: "circuit (n), breaker (n), fuse (n), MCB (n)" },
  "transformer": { m: "transform (biến đổi) → máy biến điện áp cao thành thấp và ngược lại.", e: "Sai: transformer makes electricity → Đúng: a transformer changes voltage; a generator makes electricity.", u: "Điện lực: power transformer, step-down transformer, substation. Nghĩa khác: robot biến hình.", f: "transform (v), transformer (n), transformation (n), substation (n)" },
  "wiring": { m: "wire (dây) + -ing → toàn bộ việc đi dây và hệ thống dây trong nhà, máy.", e: "Sai: a wirings → Đúng: the wiring. Danh từ không đếm được.", u: "Điện: electrical wiring, faulty wiring causes fires, wiring diagram, rewire a house.", f: "wire (n/v), wiring (n), rewire (v), wireless (adj)" },
  "grounding": { m: "ground (mặt đất) → nối thiết bị xuống đất để dòng rò thoát an toàn. Anh-Anh: earthing.", e: "Sai: The machine is not grounding → Đúng: The machine is not grounded / lacks proper grounding.", u: "An toàn điện: grounding wire, grounding system, ground fault. Anh-Anh dùng 'earthing'.", f: "ground (v/n), grounded (adj), earthing (Anh-Anh), earth wire (n)" },
  "power supply": { m: "supply (cung cấp) + power → nguồn cấp điện cho thiết bị.", e: "Sai: The power supply was cut out → Đúng: The power supply was cut off / interrupted.", u: "Điện, điện tử: uninterruptible power supply (UPS), power supply unit, stable power supply.", f: "power (n/v), supply (n/v), PSU, UPS, power outage (n)" },
  "renewable energy": { m: "re- (lại) + new → nguồn năng lượng tự tái tạo: mặt trời, gió, nước.", e: "Sai: renewal energy → Đúng: renewable energy. 'Renewal' là sự gia hạn.", u: "IELTS Writing (môi trường): invest in renewable energy, reduce fossil fuels. Ngành: renewable energy projects.", f: "renew (v), renewable (adj), renewables (n), clean energy (n), fossil fuels (n)" },
  "solar panel": { m: "sol (mặt trời, Latin) + panel (tấm) → tấm hứng nắng tạo điện.", e: "Sai: sun panel → Đúng: solar panel. Sai: put solar panels in the roof → Đúng: on the roof.", u: "Năng lượng: rooftop solar panels, install solar panels, photovoltaic. IELTS Speaking: nhà xanh.", f: "solar (adj), panel (n), photovoltaic (adj), solar farm (n), solar power (n)" },
  "energy efficiency": { m: "efficient (hiệu quả) + energy → dùng ít điện hơn mà vẫn làm đủ việc.", e: "Sai: energy efficient is important → Đúng: energy efficiency is important. Danh từ 'efficiency', tính từ 'efficient'.", u: "IELTS Writing: improve energy efficiency in buildings. Kỹ thuật: energy efficiency rating, energy audit.", f: "efficiency (n), efficient (adj), energy-efficient (adj), energy-saving (adj)" },
  "heat exchanger": { m: "exchange (trao đổi) nhiệt → nóng truyền sang lạnh mà hai dòng không trộn nhau.", e: "Sai: heat exchange machine → Đúng: heat exchanger. Hậu tố '-er' chỉ thiết bị.", u: "Nhiệt, hóa chất: plate heat exchanger, shell-and-tube, fouling, HVAC.", f: "exchange (v/n), exchanger (n), heat transfer (n), radiator (n)" },
  "boiler": { m: "boil (đun sôi) + -er → thiết bị đun nước thành hơi → nồi hơi.", e: "Sai: The boiler is boiling the steam → Đúng: The boiler produces steam / heats water.", u: "Nhà máy, tòa nhà: steam boiler, boiler pressure, boiler room, boiler inspection.", f: "boil (v), boiler (n), steam (n), boiling point (n)" },
  "furnace": { m: "Latin 'fornax' = lò → lò nung nhiệt độ rất cao.", e: "Sai: The furnace is cooking metal → Đúng: The furnace melts/heats the metal.", u: "Luyện kim: blast furnace, electric arc furnace, furnace temperature. Mỹ: lò sưởi trong nhà.", f: "furnace (n), kiln (n), oven (n), blast furnace (n)" },
  "thermodynamics": { m: "thermo- (nhiệt) + dynamics (động lực) → môn học nhiệt sinh ra chuyển động, năng lượng.", e: "Sai: thermodynamics are difficult → Đúng: thermodynamics is difficult. Tên môn học dùng động từ số ít.", u: "Học thuật kỹ thuật: laws of thermodynamics, entropy, heat engine, course in thermodynamics.", f: "thermodynamics (n), thermodynamic (adj), thermal (adj), entropy (n)" },
  "fluid mechanics": { m: "fluid (chất lưu: lỏng và khí) + mechanics (cơ học) → cơ học chất lưu.", e: "Sai: fluid mechanics are → Đúng: fluid mechanics is. 'Fluid' gồm cả khí, không chỉ chất lỏng.", u: "Kỹ thuật: fluid mechanics course, flow rate, pressure drop, Bernoulli's principle.", f: "fluid (n/adj), mechanics (n), hydrodynamics (n), aerodynamics (n)" },
  "pipeline": { m: "pipe (ống) + line (tuyến) → tuyến ống dài dẫn dầu, khí, nước.", e: "Sai: The project is on the pipeline → Đúng: The project is in the pipeline (đang chuẩn bị).", u: "Dầu khí: gas pipeline, pipeline leak. Kinh doanh: sales pipeline. IT: data pipeline, CI/CD pipeline.", f: "pipe (n/v), pipeline (n), piping (n), in the pipeline (idiom)" },
  "fitting": { m: "fit (vừa khớp) → chi tiết khớp nối giữa các đoạn ống.", e: "Sai: pipe fittings are a dress try-on → Đúng: pipe fittings are connectors; 'a fitting' cũng là buổi thử đồ.", u: "Đường ống: pipe fittings, elbow, tee, reducer, compression fitting. Nội thất: light fittings.", f: "fit (v), fitting (n), fitter (n), fixture (n)" },
  "bolt": { m: "Hình ảnh: thanh kim loại có ren, vặn với đai ốc (nut) để giữ chặt.", e: "Sai: tighten the bolt by hand strongly → Đúng: tighten the bolt with a wrench to the specified torque.", u: "Cơ khí, xây dựng: nuts and bolts, anchor bolt, bolt torque. Thành ngữ: nuts and bolts (chi tiết cơ bản).", f: "bolt (n/v), nut (n), screw (n), washer (n)" },
  "fastener": { m: "fasten (buộc chặt) + -er → mọi thứ giữ chặt chi tiết: bu-lông, vít, đinh tán.", e: "Sai: fastener only means zipper → Đúng: in engineering, fasteners include bolts, screws and rivets.", u: "Cơ khí, lắp ráp: fastener supplier, threaded fasteners, fastener torque.", f: "fasten (v), fastener (n), fastening (n), unfasten (v)" },
  "batch": { m: "Liên tưởng 'bake': một mẻ bánh nướng cùng lúc → một lô sản xuất.", e: "Sai: produce in batchs → Đúng: produce in batches. Số nhiều '-es'.", u: "Sản xuất, dược: batch number, batch production, batch record, recall a batch. IT: batch processing.", f: "batch (n/v), batch number (n), lot (n), batch processing (n)" },
  "mass production": { m: "mass (khối lớn) → sản xuất số lượng khổng lồ, giống hệt nhau.", e: "Sai: produce in mass production → Đúng: be mass-produced / go into mass production.", u: "Công nghiệp: mass production lowers costs. IELTS Writing: mass-produced goods vs handmade products.", f: "mass-produce (v), mass-produced (adj), mass production (n), large-scale (adj)" },
  "packaging": { m: "package (gói) + -ing → vỏ bọc, hộp, và cả việc đóng gói.", e: "Sai: too many packagings → Đúng: too much packaging. Không đếm được.", u: "Sản xuất, marketing: packaging design, eco-friendly packaging. IELTS: reduce plastic packaging.", f: "pack (v), package (n/v), packaging (n), packer (n), unpack (v)" },
  "simulation": { m: "simil- (giống, như 'similar') → tạo mô hình giống thật để thử → mô phỏng.", e: "Sai: do a simulate → Đúng: run a simulation / simulate the process.", u: "Kỹ thuật: computer simulation, run simulations, flight simulator, simulation software.", f: "simulate (v), simulation (n), simulator (n), simulated (adj)" },
  "finite element analysis": { m: "finite (hữu hạn) + element (phần tử) → chia vật thể thành nhiều mảnh nhỏ để tính ứng suất. Viết tắt FEA.", e: "Sai: finite elements analyse → Đúng: finite element analysis (FEA). 'Element' số ít.", u: "Thiết kế cơ khí: FEA simulation, stress analysis, mesh, ANSYS, kiểm tra độ bền trước khi làm nguyên mẫu.", f: "FEA, FEM (finite element method), simulation (n), stress analysis (n)" },
  "commissioning": { m: "commission (giao nhiệm vụ) → chính thức giao máy, nhà máy vào vận hành sau chạy thử.", e: "Sai: commission fee of the machine → Đúng: commissioning of the machine. 'Commission' còn nghĩa hoa hồng.", u: "Dự án: commissioning engineer, testing and commissioning, plant commissioning, handover.", f: "commission (v/n), commissioning (n), decommission (v), handover (n)" },
  "wastewater treatment": { m: "waste (thải) + water + treatment (xử lý) → làm sạch nước thải trước khi xả.", e: "Sai: treatment of waste water plant → Đúng: wastewater treatment plant. Danh từ ghép đứng trước.", u: "Môi trường: wastewater treatment plant, effluent standards. IELTS Writing Task 1: biểu đồ quy trình xử lý nước.", f: "wastewater (n), treat (v), treatment (n), sewage (n), effluent (n)" },
  "industrial park": { m: "park (khu đất) dành cho công nghiệp → nhiều nhà máy tập trung một nơi.", e: "Sai: in the industrial park zone → Đúng: in an industrial park / industrial zone. Không lặp từ.", u: "Đầu tư, nhân sự: industrial park in Bắc Ninh, FDI, factory in an industrial zone.", f: "industry (n), industrial (adj), industrial zone (n), export processing zone (n)" },
  "drilling": { m: "drill (mũi khoan) → khoan lỗ trên kim loại, gỗ, hoặc khoan giếng dầu.", e: "Sai: drilling a hole by the drill machine → Đúng: drilling a hole with a drill.", u: "Gia công: drilling machine, drill bit. Dầu khí: offshore drilling. Nghĩa khác: luyện tập lặp lại (drill).", f: "drill (n/v), drilling (n), driller (n), drill bit (n)" },
  "grinding": { m: "grind (nghiền, xay) → đá mài xoay tốc độ cao làm nhẵn bề mặt.", e: "Sai: grinded → Đúng: ground (quá khứ của 'grind'). Ví dụ: The surface was ground smooth.", u: "Gia công: surface grinding, grinding wheel, grinding machine, deburring. Thực phẩm: grind coffee.", f: "grind (v), ground (v, quá khứ), grinder (n), grinding (n)" },
  "sheet metal": { m: "sheet (tấm mỏng) + metal → kim loại cán mỏng thành tấm để cắt, uốn, dập.", e: "Sai: metal sheets work → Đúng: sheet metal work / sheet metal fabrication.", u: "Gia công: sheet metal fabrication, bending, laser cutting, stamping, enclosures.", f: "sheet (n), metal (n), plate (n), stamping (n), fabrication (n)" },
  "work order": { m: "order (lệnh) để làm việc → phiếu ghi rõ việc gì, ai làm, khi nào xong.", e: "Sai: open a working order → Đúng: create/issue a work order.", u: "Bảo trì, sản xuất: maintenance work order, close a work order, CMMS. Công trình: lệnh giao việc.", f: "work order (n), job card (n), purchase order (n), ticket (n)" },
  "surface finish": { m: "finish (hoàn thiện) bề mặt → bề mặt nhẵn hay nhám sau gia công.", e: "Sai: The surface finishing is rough 0.8 → Đúng: The surface finish is Ra 0.8 µm.", u: "Gia công, QC: surface finish requirement, Ra value, polishing, coating, ghi trên bản vẽ.", f: "surface (n), finish (n/v), roughness (n), polish (v)" },
  "load-bearing": { m: "load (tải) + bearing (chịu đỡ) → chịu tải trọng của công trình.", e: "Sai: remove the load bearing wall freely → Đúng: never remove a load-bearing wall without an engineer.", u: "Xây dựng: load-bearing wall, load-bearing structure, sửa nhà cần kiểm tra tường chịu lực.", f: "load-bearing (adj), bear (v), load (n), structural (adj)" },
  "material handling": { m: "handle (cầm, xử lý) vật tư → bốc, xếp, di chuyển hàng trong kho xưởng.", e: "Sai: materials handle → Đúng: material handling (equipment). Dùng dạng '-ing'.", u: "Kho vận: material handling equipment, forklift, pallet jack, conveyor, AGV.", f: "handle (v), handling (n), forklift (n), logistics (n)" },
  "statute": { m: "Latin 'statuere' = dựng lên, như 'statue' (tượng) → luật được 'dựng' thành văn bản.", e: "Sai: statue → Đúng: statute (đạo luật). 'Statue' là tượng; 'status' là địa vị.", u: "Pháp luật: under the statute, statute of limitations (thời hiệu), statutory rights.", f: "statute (n), statutory (adj), statute book (n), legislation (n)" },
  "constitution": { m: "con- (cùng) + stitute (dựng) → cùng dựng nên nhà nước → hiến pháp.", e: "Sai: the constitution law → Đúng: the constitution / constitutional law. Viết hoa khi chỉ hiến pháp một nước cụ thể.", u: "Luật, chính trị: amend the Constitution, constitutional rights, unconstitutional. Nghĩa khác: thể trạng.", f: "constitution (n), constitutional (adj), unconstitutional (adj), constitute (v)" },
  "decree": { m: "de- + cree (quyết định, như 'decide') → văn bản chính phủ quyết định → nghị định.", e: "Sai: according to the Decree number 15 → Đúng: under Decree No. 15/2022/ND-CP.", u: "Pháp lý Việt Nam: Decree guiding the Law on Enterprises, issue a decree. Thứ bậc: law > decree > circular.", f: "decree (n/v), by decree, ordinance (n), regulation (n)" },
  "circular": { m: "Nghĩa gốc 'tròn' → văn bản gửi vòng tới các cơ quan → thông tư.", e: "Sai: circular is only a shape → Đúng: in Vietnamese law, a Circular guides a Decree, e.g. Circular No. 78/2021/TT-BTC.", u: "Pháp lý Việt Nam: Circular issued by the Ministry of Finance, guiding circular. Văn phòng: thư thông báo chung.", f: "circular (n/adj), circulate (v), circulation (n), guidance (n)" },
  "enact": { m: "en- (đưa vào) + act (đạo luật) → đưa thành đạo luật → ban hành.", e: "Sai: enact a contract → Đúng: enact a law / legislation. 'Enact' dùng cho luật do quốc hội thông qua.", u: "Lập pháp: enact legislation, enacted by the National Assembly. IELTS Writing: governments should enact stricter laws.", f: "enact (v), enactment (n), act (n), legislate (v)" },
  "repeal": { m: "re- (lại, rút) + appeal (kêu gọi) → rút lại luật → bãi bỏ.", e: "Sai: repeal the court decision → Đúng: repeal a law; overturn/reverse a court decision.", u: "Lập pháp: repeal a law, repealed provisions, the new law repeals the old one.", f: "repeal (v/n), revoke (v), abolish (v), annul (v)" },
  "come into force": { m: "Hình ảnh: luật 'bước vào' trạng thái có sức mạnh (force) → có hiệu lực.", e: "Sai: The law will come in force on 1 July → Đúng: The law will come into force on 1 July.", u: "Pháp lý: come into force / take effect / enter into force (điều ước), effective date của văn bản.", f: "take effect, enter into force, in force (adj), effective date (n)" },
  "legal entity": { m: "entity (thực thể) được pháp luật công nhận → có quyền, nghĩa vụ như một 'người'.", e: "Sai: legal person entity company → Đúng: the company is a legal entity. Chủ doanh nghiệp tư nhân không phải pháp nhân.", u: "Doanh nghiệp: separate legal entity, establish a legal entity, legal entity name trên hợp đồng.", f: "legal entity (n), legal person (n), juridical person (n), corporation (n)" },
  "jurisdiction": { m: "juris (luật) + diction (nói) → quyền 'nói luật' trong một phạm vi → thẩm quyền.", e: "Sai: The court has no jurisdiction about this case → Đúng: The court has no jurisdiction over this case.", u: "Luật: fall under the jurisdiction of, governing law and jurisdiction clause trong hợp đồng quốc tế.", f: "jurisdiction (n), jurisdictional (adj), judicial (adj), competence (n)" },
  "supreme court": { m: "supreme (cao nhất) + court (tòa) → tòa án cấp cao nhất.", e: "Sai: the Supreme Court of People → Đúng: the Supreme People's Court (Việt Nam). Viết hoa tên riêng.", u: "Tư pháp: appeal to the Supreme Court, Supreme Court ruling, precedent. IELTS: hệ thống tư pháp.", f: "Supreme Court (n), court of appeal (n), high court (n), judiciary (n)" },
  "prosecutor": { m: "pro- (về phía trước) + secute (theo đuổi) → người đưa vụ án ra tòa theo đuổi buộc tội.", e: "Sai: The prosecutor defended the accused → Đúng: The prosecutor charged the accused; the defence lawyer defended him.", u: "Tố tụng hình sự: public prosecutor, People's Procuracy, the prosecution's case.", f: "prosecute (v), prosecution (n), prosecutor (n), procurator (n)" },
  "defendant": { m: "defend (bảo vệ, chống đỡ) + -ant → người bị kiện, phải tự bảo vệ.", e: "Sai: defendent → Đúng: defendant. Đừng nhầm với plaintiff (nguyên đơn).", u: "Tòa án: the defendant pleaded not guilty, the defendant's lawyer. Dân sự: bị đơn; hình sự: bị cáo.", f: "defend (v), defendant (n), defence/defense (n), plaintiff (n, đối lập)" },
  "plaintiff": { m: "Liên tưởng 'complaint' (khiếu nại) → người khởi kiện đi phàn nàn → nguyên đơn.", e: "Sai: The plaintiff was sued by the defendant → Đúng: The plaintiff sued the defendant.", u: "Tố tụng dân sự: the plaintiff filed a lawsuit, plaintiff's claim. Anh-Anh hiện dùng 'claimant'.", f: "plaintiff (n), claimant (n), complainant (n), defendant (n, đối lập)" },
  "testimony": { m: "testi- (người làm chứng, như 'testify') → lời khai trước tòa.", e: "Sai: She gave a testify → Đúng: She gave testimony / She testified.", u: "Tòa án: witness testimony, sworn testimony, give testimony in court. Nghĩa rộng: bằng chứng cho điều gì.", f: "testify (v), testimony (n), testimonial (n), witness (n)" },
  "burden of proof": { m: "Hình ảnh: gánh nặng (burden) phải chứng minh đè lên vai một bên.", e: "Sai: the burden of proof is on the defendant in criminal cases → Đúng: it lies with the prosecution.", u: "Luật: the burden of proof lies with / rests on the plaintiff, shift the burden of proof.", f: "burden (n), proof (n), prove (v), onus (n)" },
  "lawsuit": { m: "law (luật) + suit (đơn kiện, gốc 'sue') → vụ kiện.", e: "Sai: make a lawsuit to him → Đúng: file a lawsuit against him / sue him.", u: "Pháp lý, TOEIC: file a lawsuit, settle a lawsuit, class-action lawsuit.", f: "lawsuit (n), sue (v), suit (n), litigation (n), lawyer (n)" },
  "litigation": { m: "Latin 'lis' (tranh chấp) → đưa tranh chấp ra tòa → kiện tụng.", e: "Sai: The company is in a litigation → Đúng: The company is in litigation / involved in litigation. Không đếm được.", u: "Luật sư: litigation lawyer, avoid costly litigation, litigation vs arbitration.", f: "litigate (v), litigation (n), litigant (n), litigious (adj)" },
  "hearing": { m: "hear (nghe) → buổi tòa nghe các bên trình bày → phiên điều trần.", e: "Sai: The hearing was opened at court → Đúng: The hearing was held in court.", u: "Tòa án: court hearing, preliminary hearing, adjourn the hearing. Quốc hội: public hearing.", f: "hear (v), hearing (n), trial (n), session (n)" },
  "verdict": { m: "ver- (thật) + dict (nói) → lời nói ra sự thật → phán quyết.", e: "Sai: The jury made a verdict → Đúng: The jury reached/returned a verdict.", u: "Tòa án: guilty verdict, not guilty verdict. Đời thường: What's your verdict on the new phone?", f: "verdict (n), judgment (n), ruling (n), sentence (n)" },
  "ruling": { m: "rule (quyết định, cai trị) → quyết định chính thức của tòa hoặc cơ quan.", e: "Sai: The court ruled a ruling → Đúng: The court issued a ruling / The court ruled that…", u: "Pháp lý: court ruling, appeal against a ruling, landmark ruling.", f: "rule (v/n), ruling (n/adj), judgment (n), decision (n)" },
  "acquit": { m: "a- + quit (tự do, như 'quit') → thả tự do, tuyên vô tội.", e: "Sai: He was acquitted from murder → Đúng: He was acquitted of murder. Giới từ 'of'.", u: "Tòa hình sự: acquit the defendant, acquitted of all charges, acquittal.", f: "acquit (v), acquittal (n), acquitted (adj), convict (v, đối lập)" },
  "convict": { m: "con- (hoàn toàn) + vict (chinh phục, như 'victory') → tòa chứng minh và tuyên có tội.", e: "Sai: He was convicted for theft → Đúng: He was convicted of theft. Danh từ 'convict' nhấn âm đầu: /ˈkɑːnvɪkt/.", u: "Hình sự: be convicted of fraud, conviction, previous convictions. Danh từ 'convict' = phạm nhân.", f: "convict (v/n), conviction (n), convicted (adj), acquit (v, đối lập)" },
  "presumption of innocence": { m: "presume (cho rằng trước) + innocence → mặc định vô tội cho đến khi chứng minh có tội.", e: "Sai: presumption of innocent → Đúng: presumption of innocence. Dùng danh từ 'innocence'.", u: "Luật hình sự: innocent until proven guilty, protect the presumption of innocence, quyền con người.", f: "presume (v), presumption (n), innocence (n), innocent (adj)" },
  "criminal law": { m: "crime (tội phạm) → luật về tội phạm và hình phạt.", e: "Sai: crime law → Đúng: criminal law. Dùng tính từ 'criminal'.", u: "Pháp luật: Criminal Code, criminal law vs civil law, criminal liability, criminal record.", f: "crime (n), criminal (adj/n), criminology (n), Criminal Code (n)" },
  "civil law": { m: "civil (dân sự) → luật điều chỉnh quan hệ giữa người với người: tài sản, hợp đồng.", e: "Sai: civil law is about crimes → Đúng: civil law deals with disputes between individuals or organisations.", u: "Pháp luật: Civil Code, civil lawsuit, civil law system (khác common law).", f: "civil (adj), Civil Code (n), civil liability (n), common law (n)" },
  "administrative law": { m: "administer (quản lý) → luật về hoạt động quản lý của cơ quan nhà nước.", e: "Sai: administration law → Đúng: administrative law. Dùng tính từ.", u: "Pháp luật: administrative law, administrative violation, administrative fine, kiện quyết định hành chính.", f: "administer (v), administration (n), administrative (adj), administrator (n)" },
  "labor law": { m: "labor (lao động) → luật về quan hệ giữa người lao động và người sử dụng lao động.", e: "Sai: labour's law → Đúng: labor law (Mỹ) / labour law (Anh). Không dùng sở hữu cách.", u: "Nhân sự: Labor Code, comply with labor law, overtime, minimum wage, labor contract.", f: "labor/labour (n), Labor Code (n), employment law (n), labor contract (n)" },
  "commercial law": { m: "commerce (thương mại) → luật về mua bán, kinh doanh, doanh nghiệp.", e: "Sai: commerce law → Đúng: commercial law. Dùng tính từ 'commercial'.", u: "Pháp lý doanh nghiệp: Commercial Law 2005, commercial disputes, commercial contracts.", f: "commerce (n), commercial (adj), business law (n), trade law (n)" },
  "intellectual property": { m: "intellect (trí tuệ) + property (tài sản) → tài sản sinh ra từ trí óc. Viết tắt IP.", e: "Sai: intelligent property → Đúng: intellectual property. 'Intelligent' là thông minh.", u: "Luật, kinh doanh: protect intellectual property, IP rights, patent, trademark, copyright.", f: "IP (n), patent (n), trademark (n), copyright (n), intellect (n)" },
  "infringement": { m: "in- + fringe (bẻ gãy, như 'fracture') → bẻ gãy quyền của người khác → xâm phạm.", e: "Sai: infringement to the patent → Đúng: infringement of the patent / patent infringement.", u: "Sở hữu trí tuệ: copyright infringement, trademark infringement, sue for infringement.", f: "infringe (v), infringement (n), infringer (n), violation (n)" },
  "terms and conditions": { m: "terms (điều khoản) + conditions (điều kiện) → các quy định khi dùng dịch vụ, mua hàng.", e: "Sai: terms and condition → Đúng: terms and conditions. Cả hai từ đều số nhiều.", u: "Thương mại, TOEIC: read the terms and conditions, accept the T&Cs, subject to terms and conditions.", f: "T&Cs, terms of service (n), fine print (n), clause (n)" },
  "breach of contract": { m: "breach (lỗ thủng, gốc 'break') → làm thủng, phá vỡ hợp đồng.", e: "Sai: break of contract → Đúng: breach of contract. Động từ: breach the contract.", u: "Hợp đồng: sue for breach of contract, material breach, damages for breach.", f: "breach (n/v), contract (n), violation (n), default (n)" },
  "force majeure": { m: "Tiếng Pháp 'sức mạnh lớn hơn' → sự kiện vượt khả năng kiểm soát: thiên tai, chiến tranh.", e: "Sai: force major → Đúng: force majeure, phát âm /ˌfɔːrs mæˈʒɜːr/.", u: "Hợp đồng: force majeure clause, force majeure event, miễn trách nhiệm khi thiên tai, dịch bệnh.", f: "force majeure (n), act of God (n), unforeseeable (adj), exemption (n)" },
  "damages": { m: "damage (thiệt hại) thêm '-s' → tiền bù cho thiệt hại.", e: "Sai: claim a damage → Đúng: claim damages. Nghĩa 'tiền bồi thường' luôn số nhiều.", u: "Pháp lý: pay damages, award damages, compensatory damages, punitive damages.", f: "damage (n/v), damages (n), compensation (n), indemnity (n)" },
  "rights": { m: "right (đúng) → điều đúng mà ai cũng được hưởng → quyền.", e: "Sai: human right is important → Đúng: human rights are important. Thường dùng số nhiều.", u: "Luật, IELTS Writing: human rights, consumer rights, workers' rights, exercise one's rights.", f: "right (n/adj), rightful (adj), entitlement (n), obligations (n, đối lập)" },
  "dispute resolution": { m: "dispute (tranh chấp) + resolve (giải quyết) → cách giải quyết tranh chấp.", e: "Sai: dispute resolve → Đúng: dispute resolution. Danh từ ghép.", u: "Hợp đồng: dispute resolution clause, negotiation, mediation, arbitration, litigation, ADR.", f: "dispute (n/v), resolve (v), resolution (n), ADR (n)" },
  "arbitration": { m: "arbiter (người phân xử) → bên thứ ba trung lập phán quyết thay tòa → trọng tài.", e: "Sai: go to the arbitrage → Đúng: go to arbitration. 'Arbitrage' là kinh doanh chênh lệch giá.", u: "Thương mại quốc tế: VIAC, SIAC, arbitration clause, binding arbitration, arbitral award.", f: "arbitrate (v), arbitration (n), arbitrator (n), arbitral (adj)" },
  "mediation": { m: "medi- (ở giữa, như 'medium') → người đứng giữa giúp hai bên thỏa thuận → hòa giải.", e: "Sai: The mediator forced a decision → Đúng: The mediator helped both sides reach an agreement.", u: "Giải quyết tranh chấp: commercial mediation, mediation session, labor mediation. Khác arbitration ở chỗ không phán quyết.", f: "mediate (v), mediation (n), mediator (n), conciliation (n)" },
  "notary": { m: "note (ghi chép) → người ghi nhận, xác thực giấy tờ → công chứng viên.", e: "Sai: go to notary to notary documents → Đúng: go to a notary to have documents notarized.", u: "Hành chính: notary public, notary office (văn phòng công chứng), notarial certificate.", f: "notary (n), notarize (v), notarial (adj), notarization (n)" },
  "notarize": { m: "notary + -ize → để công chứng viên xác nhận giấy tờ là thật.", e: "Sai: I notarized my documents at the notary (khi người khác làm) → Đúng: I had my documents notarized.", u: "Thủ tục: notarized copy, notarized contract, notarized translation khi nộp hồ sơ.", f: "notarize/notarise (v), notarized (adj), notarization (n), certify (v)" },
  "certified copy": { m: "certify (chứng nhận) → bản sao được cơ quan xác nhận giống bản gốc.", e: "Sai: a copy certificate → Đúng: a certified copy. 'Certificate' là giấy chứng nhận.", u: "Hồ sơ: certified copy of passport, submit certified copies, chứng thực tại UBND phường.", f: "certify (v), certified (adj), certification (n), true copy (n)" },
  "power of attorney": { m: "attorney (người được ủy nhiệm) → giấy trao quyền (power) cho người khác làm thay.", e: "Sai: power of attorneys → Đúng: power of attorney / powers of attorney.", u: "Pháp lý: grant power of attorney, notarized power of attorney, ký thay khi mua bán nhà đất.", f: "attorney (n), proxy (n), authorization (n), letter of authorization (n)" },
  "land use rights": { m: "rights to use land → quyền dùng đất, không phải quyền sở hữu đất (thuộc toàn dân).", e: "Sai: land owner certificate → Đúng: land use rights certificate (sổ đỏ). Ở Việt Nam người dân không sở hữu đất.", u: "Bất động sản: land use rights certificate, transfer of land use rights, land use term.", f: "land use right(s) (n), red book (n), land tenure (n), title deed (n)" },
  "marriage registration": { m: "register (đăng ký) kết hôn → thủ tục ghi nhận hôn nhân hợp pháp.", e: "Sai: register marriage at church → Đúng: register the marriage at the commune People's Committee.", u: "Hộ tịch: marriage registration certificate, register a marriage with a foreigner, certificate of marital status.", f: "marry (v), marriage (n), register (v), registration (n), marital (adj)" },
  "birth certificate": { m: "certificate (giấy chứng nhận) + birth → giấy ghi nhận ngày sinh, cha mẹ.", e: "Sai: birth certification → Đúng: birth certificate. 'Certificate' là tờ giấy.", u: "Hộ tịch, du học: birth certificate copy, certified translation, register a birth.", f: "birth (n), certificate (n), certify (v), birth registration (n)" },
  "identity card": { m: "identity (danh tính) + card → thẻ chứng minh mình là ai. Viết tắt ID card.", e: "Sai: identify card → Đúng: identity card / ID card. 'Identify' là động từ.", u: "Hành chính: citizen identity card, show your ID card, chip-based ID, VNeID.", f: "identity (n), identify (v), identification (n), ID (n)" },
  "household registration": { m: "household (hộ gia đình) + registration → đăng ký thành viên theo hộ (hộ khẩu).", e: "Sai: family book registration → Đúng: household registration book (sổ hộ khẩu).", u: "Hành chính Việt Nam: permanent/temporary residence registration, household registration abolished, cư trú.", f: "household (n), register (v), registration (n), residence registration (n)" },
  "residence permit": { m: "reside (cư trú) + permit (giấy phép) → giấy cho phép người nước ngoài ở lại.", e: "Sai: resident permission card → Đúng: residence permit / temporary residence card.", u: "Xuất nhập cảnh: apply for a residence permit, temporary residence card (TRC), expat, renew a permit.", f: "reside (v), residence (n), resident (n), permit (n/v), visa (n)" },
  "work permit": { m: "permit (giấy phép) để làm việc → giấy cho người nước ngoài được làm việc hợp pháp.", e: "Sai: working permission → Đúng: work permit. Sai: apply a work permit → Đúng: apply for a work permit.", u: "Nhân sự, xuất nhập cảnh: work permit exemption, foreign workers, Department of Labour.", f: "permit (n/v), permission (n), work visa (n), labor license (n)" },
  "business registration certificate": { m: "Giấy chứng nhận (certificate) ghi nhận doanh nghiệp đã đăng ký (registration) hợp pháp.", e: "Sai: business license registration → Đúng: business registration certificate (enterprise registration certificate).", u: "Pháp lý doanh nghiệp: tax code, company name, registered capital, nộp khi mở tài khoản, ký hợp đồng.", f: "register (v), registration (n), business license (n), enterprise registration (n)" },
  "dossier": { m: "Gốc Pháp 'dos' = lưng (gáy hồ sơ) → tập tài liệu có nhãn ở gáy → hồ sơ.", e: "Sai: submit the dossiers papers → Đúng: submit the dossier. Phát âm /ˈdɒsieɪ/.", u: "Thủ tục hành chính: complete dossier, application dossier, dossier is returned for supplementation.", f: "dossier (n), file (n), application (n), documents (n)" },
  "administrative procedure": { m: "Các bước (procedure) làm việc với cơ quan quản lý (administrative) → thủ tục hành chính.", e: "Sai: administration procedures → Đúng: administrative procedures. Dùng tính từ.", u: "Hành chính công: simplify administrative procedures, cut red tape, online public services.", f: "procedure (n), procedural (adj), red tape (n), paperwork (n)" },
  "one-stop shop": { m: "Hình ảnh: chỉ dừng (stop) một chỗ là làm xong mọi việc → bộ phận một cửa.", e: "Sai: one stop shop of People's Committee (thiếu gạch nối) → Đúng: the People's Committee's one-stop shop.", u: "Hành chính: submit documents at the one-stop shop. Kinh doanh: a one-stop shop for all your needs.", f: "one-stop (adj), single window (n), service counter (n)" },
  "public service": { m: "service (dịch vụ) cho công chúng (public) do nhà nước cung cấp.", e: "Sai: public services portal of nation → Đúng: the National Public Service Portal.", u: "Hành chính: online public services, public service delivery. IELTS: governments should fund public services.", f: "public (adj/n), service (n), public sector (n), civil service (n)" },
  "civil servant": { m: "servant (người phục vụ) dân (civil) → người làm việc trong bộ máy nhà nước.", e: "Sai: He is a civil service → Đúng: He is a civil servant / works in the civil service.", u: "Nhà nước, IELTS Speaking: work as a civil servant, stable job, civil service exam.", f: "civil servant (n), civil service (n), public servant (n), bureaucrat (n)" },
  "public official": { m: "official (người có chức vụ) + public → người giữ chức vụ nhà nước.", e: "Sai: a public officer official → Đúng: a public official / government official.", u: "Pháp luật, báo chí: corrupt public officials, anti-corruption law, declare assets.", f: "official (n/adj), officially (adv), office (n), officer (n)" },
  "people’s committee": { m: "Ủy ban (committee) của nhân dân (people's) → cơ quan hành chính địa phương.", e: "Sai: People Committee → Đúng: People's Committee. Có sở hữu cách 's.", u: "Hành chính Việt Nam: provincial/commune People's Committee, chairman of the People's Committee, chứng thực, hộ tịch.", f: "committee (n), People's Council (n), local authority (n)" },
  "national assembly": { m: "assembly (sự tập hợp) toàn quốc → nơi đại biểu cả nước họp → Quốc hội.", e: "Sai: The National Assembly enact the law → Đúng: The National Assembly enacts/passes laws. Danh từ tập thể số ít.", u: "Lập pháp: National Assembly deputies, pass a law, National Assembly session. Tương đương parliament.", f: "assembly (n), assemble (v), parliament (n), legislature (n), deputy (n)" },
  "competent authority": { m: "competent (đủ năng lực, thẩm quyền) + authority → cơ quan có quyền giải quyết việc đó.", e: "Sai: authority competent → Đúng: competent authority. Tính từ đứng trước.", u: "Văn bản pháp lý: approved by the competent authority, submit to the competent authorities.", f: "competent (adj), competence (n), authority (n), authorize (v)" },
  "state agency": { m: "agency (cơ quan) của nhà nước (state) → cơ quan nhà nước.", e: "Sai: state's agencies of government → Đúng: state agencies / government agencies.", u: "Hành chính: state agency officials, coordinate between state agencies, state management.", f: "state (n/adj), agency (n), government agency (n), authority (n)" },
  "decentralization": { m: "de- (rời khỏi) + centre (trung tâm) → quyền lực rời trung ương, chia xuống địa phương → phân cấp.", e: "Sai: decentralize of power → Đúng: decentralization of power. Sai: the decentralization to provinces power → Đúng: decentralizing power to provinces.", u: "Văn bản hành chính: decentralization of authority to local governments, fiscal decentralization. IELTS Writing chủ đề chính phủ cũng dùng được.", f: "decentralize (v), decentralized (adj), centralization (n, trái nghĩa), delegation (n, gần nghĩa)" },
  "public administration": { m: "public (công) + administration (quản lý, điều hành) → bộ máy điều hành việc công → hành chính công.", e: "Sai: public administrator system → Đúng: public administration system. Sai: study a public administration → Đúng: study public administration.", u: "Chuyên ngành luật, quản lý nhà nước: master's in public administration (MPA), public administration reform, efficiency of public administration.", f: "administer (v), administrative (adj), administrator (n), civil service (gần nghĩa)" },
  "administrative reform": { m: "administrative (thuộc hành chính) + reform (re- làm lại + form hình dạng) → tạo lại hình dạng bộ máy hành chính.", e: "Sai: administration reformation → Đúng: administrative reform. Sai: do reform administrative procedures → Đúng: reform administrative procedures.", u: "Văn kiện nhà nước: administrative reform programme, streamline procedures, cut red tape. Thường đi với one-stop shop, e-government.", f: "reform (n/v), reformer (n), administrative procedure, streamlining (n), red tape (thủ tục rườm rà)" },
  "official letter": { m: "official (chính thức, của cơ quan) + letter (thư) → thư mang tính chính thức của cơ quan → công văn.", e: "Sai: send an officially letter → Đúng: send an official letter. Sai: official letter number 123 → Đúng: Official Letter No. 123.", u: "Hành chính, pháp lý: issue an official letter, Official Letter No. 45/CV-UBND, reply to an official letter within ten days.", f: "official (adj/n), officially (adv), dispatch (n, công văn gửi đi), circular (n, thông tư)" },
  "denunciation": { m: "de- + nounce (gọi tên, như 'announce') → gọi đích danh người sai phạm trước cơ quan → tố cáo.", e: "Sai: denounciation → Đúng: denunciation (mất 'o'). Sai: make a denunciation to him → Đúng: denounce him to the authorities.", u: "Luật khiếu nại, tố cáo: complaints and denunciations, file a denunciation, protect denouncers' identity. Phân biệt complaint (khiếu nại).", f: "denounce (v), denouncer (n), complaint (n, khiếu nại), whistleblowing (n, gần nghĩa)" },
  "administrative sanction": { m: "sanction gốc 'sanctus' (thiêng) → biện pháp chế tài được luật thừa nhận; administrative → do cơ quan hành chính áp dụng.", e: "Sai: be sanction administratively → Đúng: be subject to administrative sanctions. Sai: an administrative fine sanction → Đúng: an administrative fine.", u: "Pháp luật xử lý vi phạm: impose administrative sanctions, Decree on administrative sanctions for traffic violations, warning, fine, license suspension.", f: "sanction (n/v), sanctioned (adj), penalty (n), administrative violation, impose a fine" },
  "bribery": { m: "bribe (của đút lót) + -ery (hành vi) → hành vi đưa/nhận đút lót → hối lộ.", e: "Sai: He was arrested for bribe → Đúng: He was arrested for bribery. Sai: bribe to an official → Đúng: bribe an official.", u: "Luật hình sự, tuân thủ doanh nghiệp: anti-bribery policy, accept/offer a bribe, bribery charges. IELTS Writing chủ đề tham nhũng.", f: "bribe (n/v), briber (n), corruption (n), kickback (n, tiền lại quả), graft (n)" },
  "fraud": { m: "Liên tưởng 'frau-d' như 'phrau' → phù phép lừa người khác để chiếm lợi → gian lận, lừa đảo.", e: "Sai: He is fraud → Đúng: He is a fraud / He committed fraud. Sai: make fraud → Đúng: commit fraud.", u: "Luật, ngân hàng: commit fraud, credit card fraud, tax fraud, fraud investigation. TOEIC Part 7: email cảnh báo lừa đảo.", f: "fraudulent (adj), fraudulently (adv), fraudster (n), defraud (v), scam (n, gần nghĩa)" },
  "tax evasion": { m: "evade = né tránh (như 'escape') → né nghĩa vụ thuế trái luật → trốn thuế.", e: "Sai: tax avoidance (lách thuế hợp pháp) dùng thay tax evasion → Đúng: tax evasion là trốn thuế bất hợp pháp. Sai: evasion tax → Đúng: tax evasion.", u: "Luật thuế, kế toán: charged with tax evasion, crack down on tax evasion, offshore accounts. IELTS Writing: chính phủ và thuế.", f: "evade (v), evasive (adj), tax evader (n), tax avoidance (lách thuế hợp pháp)" },
  "money laundering": { m: "Hình ảnh: 'giặt' (launder) tiền bẩn cho sạch, che giấu nguồn gốc phi pháp → rửa tiền.", e: "Sai: money washing → Đúng: money laundering. Sai: launder of money → Đúng: launder money / money laundering.", u: "Ngân hàng, luật: anti-money laundering (AML) regulations, know your customer (KYC), report suspicious transactions.", f: "launder (v), launderer (n), AML (anti-money laundering), dirty money, shell company" },
  "indictment": { m: "Phát âm /ɪnˈdaɪtmənt/, chữ 'c' câm. in- + dict (nói) → văn bản nói rõ tội danh → cáo trạng.", e: "Sai: đọc 'in-dic-ment' → Đúng: /ɪnˈdaɪt/. Sai: indict him for court → Đúng: indict him on charges of fraud.", u: "Tố tụng hình sự: issue an indictment, be indicted on charges of, the prosecution's indictment. Tin tức pháp luật dùng nhiều.", f: "indict (v), indictable (adj), charge (n/v), bill of indictment" },
  "prosecution": { m: "pro- (tiến tới) + secut (đuổi theo) → đuổi theo kẻ phạm tội đến cùng tại tòa → truy tố; bên công tố.", e: "Sai: The prosecution are lawyer of defendant → Đúng: the defence represents the defendant; the prosecution brings charges. Đừng nhầm persecution (ngược đãi).", u: "Tòa án: face prosecution, the prosecution's witness, public prosecutor. Đối lập với the defence trong phiên tòa.", f: "prosecute (v), prosecutor (n), prosecutorial (adj), persecution (n, dễ nhầm)" },
  "statute of limitations": { m: "statute (đạo luật) + limitations (giới hạn) → luật giới hạn thời gian được khởi kiện → thời hiệu.", e: "Sai: statue of limitations (tượng) → Đúng: statute. Sai: the statute of limitation is ended → Đúng: the statute of limitations has expired.", u: "Tố tụng dân sự, hình sự: the statute of limitations has run out, within the statute of limitations for filing a claim.", f: "statute (n), statutory (adj), time limit, limitation period (UK)" },
  "precedent": { m: "pre- (trước) + cede (đi) → vụ việc đi trước làm khuôn cho sau → tiền lệ, án lệ.", e: "Sai: set a precedence → Đúng: set a precedent. Sai: a president case → Đúng: a precedent case.", u: "Luật: set a precedent, binding precedent, without precedent. IELTS Writing: 'set a dangerous precedent' khi bàn chính sách.", f: "precede (v), precedented / unprecedented (adj), case law (n), precedence (n, ưu tiên)" },
  "legal aid": { m: "legal (pháp lý) + aid (giúp đỡ) → giúp đỡ pháp lý miễn phí cho người nghèo → trợ giúp pháp lý.", e: "Sai: a legal aids → Đúng: legal aid (không đếm được). Sai: receive legal helping → Đúng: receive legal aid.", u: "Luật, xã hội: be eligible for legal aid, legal aid centre, free legal aid for low-income people. IELTS Writing: công bằng xã hội.", f: "aid (n/v), pro bono (adv/adj, làm miễn phí), legal assistance, legal clinic" },
  "legal counsel": { m: "counsel (lời khuyên; người khuyên) → người hoặc lời khuyên về luật → cố vấn pháp lý.", e: "Sai: legal council (hội đồng) → Đúng: legal counsel. Sai: a legal counsels → Đúng: legal counsel / in-house counsels.", u: "Doanh nghiệp: in-house legal counsel, seek legal counsel before signing, general counsel. TOEIC Part 7: tin tuyển dụng.", f: "counsel (n/v), counselor (n), counselling (n), attorney (n), legal adviser" },
  "memorandum of understanding": { m: "memorandum (điều cần ghi nhớ, như 'memo') + understanding (hiểu nhau) → văn bản ghi điều hai bên đã hiểu nhau.", e: "Sai: memorandum of understand → Đúng: memorandum of understanding. Sai: MOU is binding contract → Đúng: an MOU is usually non-binding.", u: "Hợp tác quốc tế, kinh doanh: sign an MOU, MOU between two universities, non-binding MOU before a formal contract.", f: "memorandum (n), memoranda (n, số nhiều), MOU, letter of intent, agreement (n)" },
  "minutes": { m: "Gốc 'minute' = nhỏ, chi tiết → ghi chép chi tiết từng ý cuộc họp → biên bản (luôn số nhiều).", e: "Sai: write a minute of the meeting → Đúng: take the minutes of the meeting. Sai: the minute shows → Đúng: the minutes show.", u: "Văn phòng, hành chính: take/keep minutes, approve the minutes of the last meeting. TOEIC Part 3, 7: thư ký gửi biên bản.", f: "minute-taker (n), minute (v, ghi biên bản), record (n), meeting notes" },
  "validity": { m: "valid (hợp lệ, có giá trị) + -ity (tính chất) → tính hợp lệ → hiệu lực, giá trị pháp lý.", e: "Sai: the contract's valid period → Đúng: the contract's period of validity. Sai: check the valid of → Đúng: check the validity of.", u: "Luật, hành chính: validity of a contract, passport validity, period of validity. IELTS Writing học thuật: validity of an argument.", f: "valid (adj), validate (v), validation (n), invalid (adj), invalidate (v)" },
  "citizenship": { m: "citizen (công dân) + -ship (tư cách, như 'membership') → tư cách công dân → quốc tịch, quyền công dân.", e: "Sai: get the citizen of Canada → Đúng: get Canadian citizenship. Sai: dual nationalities citizenship → Đúng: dual citizenship.", u: "Luật quốc tịch, di trú: apply for citizenship, dual citizenship, renounce citizenship. IELTS Speaking: global citizenship, nghĩa vụ công dân.", f: "citizen (n), citizenry (n), nationality (n), naturalization (n, nhập tịch)" },
  "human rights": { m: "human (con người) + rights (các quyền) → những quyền ai sinh ra làm người cũng có → quyền con người.", e: "Sai: human right is important → Đúng: human rights are important. Sai: violate human's rights → Đúng: violate human rights.", u: "Luật quốc tế, IELTS Writing: protect/violate human rights, human rights abuses, Universal Declaration of Human Rights.", f: "right (n), rightful (adj), civil rights, fundamental freedoms, human rights activist (n)" },
  "rule of law": { m: "Hình ảnh: luật pháp 'cai trị' (rule) cao nhất, cả nhà nước cũng phải tuân theo → pháp quyền.", e: "Sai: law of rule → Đúng: rule of law. Sai: a country of rule law → Đúng: a country governed by the rule of law.", u: "Hiến pháp, chính trị: uphold the rule of law, socialist rule-of-law state. IELTS Writing: chính phủ, trật tự xã hội.", f: "rule (n/v), law-abiding (adj), lawful (adj), constitutionalism (n), legal order" },
  "contractual": { m: "contract (hợp đồng) + -ual (thuộc về, như 'actual') → thuộc về hợp đồng, theo hợp đồng.", e: "Sai: contract obligation → Đúng: contractual obligation. Sai: contractually terms → Đúng: contractual terms.", u: "Hợp đồng thương mại: contractual obligations, contractual dispute, breach of contractual terms, be contractually bound.", f: "contract (n/v), contractor (n), contractually (adv), contracting party (n)" },
  "custody": { m: "Gốc 'custos' = người canh giữ → được canh giữ: bị tạm giam, hoặc quyền giữ và nuôi con.", e: "Sai: He is in custodies → Đúng: He is in custody. Sai: win the custody for child → Đúng: win custody of the child.", u: "Luật hình sự: be taken into custody, police custody. Luật gia đình: joint custody, custody battle after divorce.", f: "custodian (n), custodial (adj), detention (n), guardianship (n)" },
  "enforcement": { m: "en- (làm cho) + force (sức mạnh) → dùng sức mạnh để luật được tuân theo → thi hành, thực thi.", e: "Sai: law enforcing agency → Đúng: law enforcement agency. Sai: the enforcement the rules → Đúng: the enforcement of the rules.", u: "Luật, quản lý: law enforcement, enforcement of judgments, strict enforcement. IELTS Writing: luật không hiệu quả nếu thiếu enforcement.", f: "enforce (v), enforceable (adj), enforcer (n), unenforceable (adj), implementation (n)" },
  "legal capacity": { m: "capacity (sức chứa, khả năng) → khả năng pháp lý tự mình xác lập quyền, nghĩa vụ → năng lực hành vi.", e: "Sai: legal capability → Đúng: legal capacity. Sai: minors have full legal capacity → Đúng: minors have limited legal capacity.", u: "Luật dân sự: full legal capacity, lack legal capacity, persons with restricted legal capacity, capacity to enter into contracts.", f: "capacity (n), capable (adj), incapacity (n), competence (n), mental capacity" },
  "marketing mix": { m: "mix (hỗn hợp) → 'trộn' 4 nguyên liệu Product, Price, Place, Promotion thành chiến lược.", e: "Sai: a marketing mixes → Đúng: the marketing mix. Sai: marketing mix has 4Ps elements → Đúng: the marketing mix consists of the 4Ps.", u: "Marketing: adjust the marketing mix, 4Ps / 7Ps of the marketing mix. Bài tập, báo cáo chiến lược thường phân tích phần này.", f: "4Ps, 7Ps, product, price, place, promotion, marketing strategy" },
  "target audience": { m: "Hình ảnh: tấm bia (target) mà thông điệp nhắm bắn vào → nhóm khán giả mục tiêu.", e: "Sai: target audiences people → Đúng: target audience. Sai: aim at the target audience to → Đúng: reach / appeal to the target audience.", u: "Marketing, truyền thông: identify the target audience, reach the target audience. IELTS Writing quảng cáo: ads aimed at children.", f: "target (n/v), target market, audience (n), target customer, buyer persona" },
  "market segmentation": { m: "segment (đoạn, khúc) → cắt thị trường thành từng khúc theo tuổi, thu nhập, sở thích → phân khúc.", e: "Sai: market segment (một phân khúc) dùng cho quá trình → Đúng: market segmentation. Sai: segmentate the market → Đúng: segment the market.", u: "Marketing: market segmentation by demographics, geography, behaviour; STP model (Segmentation, Targeting, Positioning).", f: "segment (n/v), segmented (adj), targeting (n), positioning (n), STP" },
  "positioning": { m: "position (vị trí) → đặt thương hiệu vào một vị trí rõ ràng trong tâm trí khách hàng → định vị.", e: "Sai: position brand in market → Đúng: position the brand as affordable luxury. Sai: brand's positioning is cheap → Đúng: the brand is positioned as budget.", u: "Marketing: brand positioning, positioning statement, reposition a product, competitive positioning map.", f: "position (n/v), reposition (v), positioning statement, perceptual map" },
  "brand awareness": { m: "aware (biết, nhận ra) → bao nhiêu người nhận ra và nhớ thương hiệu → mức độ nhận biết.", e: "Sai: raise brand aware → Đúng: raise brand awareness. Sai: increase awareness of brand's → Đúng: increase awareness of the brand.", u: "Marketing: build/raise brand awareness, brand awareness campaign, measure awareness via surveys. TOEIC Part 4: quảng bá sản phẩm mới.", f: "aware (adj), awareness (n), brand recall, brand recognition, top-of-mind" },
  "brand equity": { m: "equity (vốn, tài sản) → tên thương hiệu cũng là một tài sản, giúp bán giá cao hơn.", e: "Sai: brand equality → Đúng: brand equity. Sai: brand equity is the logo → Đúng: brand equity is the value the brand adds.", u: "Marketing, quản trị: build brand equity, strong brand equity allows premium pricing, brand valuation.", f: "equity (n), brand value, brand loyalty, brand image, goodwill (n, kế toán)" },
  "brand identity": { m: "identity (danh tính, như ID card) → 'chứng minh thư' của thương hiệu: logo, màu, giọng điệu.", e: "Sai: brand identify → Đúng: brand identity. Nhầm brand image (khách nghĩ gì) với brand identity (công ty tạo ra gì).", u: "Branding, thiết kế: develop a strong brand identity, consistent brand identity across channels, brand identity guidelines.", f: "identity (n), identify (v), visual identity, brand image, brand guidelines" },
  "rebranding": { m: "re- (lại) + brand (thương hiệu) → làm lại thương hiệu: đổi tên, logo, hình ảnh.", e: "Sai: re-brand the company image's → Đúng: rebrand the company. Sai: do a rebranding for → Đúng: undergo a rebranding.", u: "Marketing: undergo a rebranding, rebranding campaign, rebrand to target younger consumers. Tin kinh doanh TOEIC Part 7.", f: "rebrand (v), rebranded (adj), brand refresh, repositioning (n)" },
  "value proposition": { m: "proposition (lời đề xuất) → lời đề xuất giá trị: vì sao khách nên chọn mình mà không chọn đối thủ.", e: "Sai: value proposal → Đúng: value proposition. Sai: our value proposition are → Đúng: our value proposition is.", u: "Marketing, khởi nghiệp: clear value proposition, customer value proposition, value proposition canvas, pitch deck.", f: "propose (v), proposition (n), unique selling point, benefit (n), customer value" },
  "unique selling point": { m: "unique (độc nhất) + selling point (điểm giúp bán hàng) → điều chỉ mình có, đối thủ không có.", e: "Sai: unique selling points is → Đúng: the unique selling point is. Sai: special sell point → Đúng: unique selling point (USP).", u: "Marketing, quảng cáo: identify the product's USP, its USP is long battery life. Phỏng vấn: 'What is your USP?'.", f: "USP, unique selling proposition, selling point, competitive advantage, differentiator (n)" },
  "buyer persona": { m: "persona (mặt nạ nhân vật) → nhân vật hư cấu đại diện cho khách hàng lý tưởng.", e: "Sai: buyer personal → Đúng: buyer persona. Sai: create personas of buyer → Đúng: create buyer personas.", u: "Marketing số, content: create buyer personas with age, job, pain points, goals; dùng để viết content, chạy quảng cáo.", f: "persona (n), personas / personae (pl), customer profile, ideal customer, target audience" },
  "focus group": { m: "Hình ảnh: một nhóm nhỏ ngồi 'tập trung' (focus) bàn về một sản phẩm → nhóm thảo luận tập trung.", e: "Sai: focusing group → Đúng: focus group. Sai: do a focus group to customers → Đúng: conduct a focus group with customers.", u: "Nghiên cứu thị trường: conduct/run focus groups, focus group participants, qualitative research. TOEIC Part 3: mời tham gia khảo sát.", f: "focus (n/v), moderator (n), survey (n), in-depth interview, qualitative research" },
  "consumer behavior": { m: "behavior (hành vi) của người tiêu dùng → cách họ chọn, mua, dùng, bỏ sản phẩm.", e: "Sai: consumer behaviors are change → Đúng: consumer behavior is changing. Sai: consumers behavior → Đúng: consumer behavior.", u: "Marketing, IELTS Writing: shifts in consumer behavior, study consumer behavior, online shopping changes consumer behavior.", f: "behave (v), behavioral (adj), behaviour (UK), purchasing behavior, buying habits" },
  "competitor analysis": { m: "competitor (đối thủ, gốc compete = thi đấu) → mổ xẻ điểm mạnh, yếu của đối thủ → phân tích cạnh tranh.", e: "Sai: competition analyse → Đúng: competitor analysis. Sai: analysis competitor → Đúng: analyze competitors / conduct a competitor analysis.", u: "Marketing, kế hoạch kinh doanh: conduct a competitor analysis, benchmark against competitors, competitive landscape.", f: "compete (v), competitive (adj), competition (n), competitive analysis, benchmarking (n)" },
  "swot analysis": { m: "Viết tắt: Strengths, Weaknesses, Opportunities, Threats → 2 yếu tố trong, 2 yếu tố ngoài.", e: "Sai: SWOT analyse → Đúng: SWOT analysis. Sai: threats are internal factors → Đúng: threats are external factors.", u: "Marketing, quản trị: carry out a SWOT analysis, kế hoạch kinh doanh. IELTS Speaking: nói về điểm mạnh, điểm yếu của dự án.", f: "strengths, weaknesses, opportunities, threats, PEST analysis, situation analysis" },
  "niche market": { m: "niche (/niːʃ/, hốc tường nhỏ) → một góc thị trường nhỏ, chuyên biệt → thị trường ngách.", e: "Sai: đọc 'nít-chờ' → Đúng: /niːʃ/ hoặc /nɪtʃ/. Sai: a niche markets → Đúng: a niche market.", u: "Marketing, khởi nghiệp: target a niche market, find a niche, niche products like vegan cosmetics. IELTS Speaking: kinh doanh nhỏ.", f: "niche (n/adj), mass market (trái nghĩa), market segment, specialist market" },
  "advertising": { m: "ad- (hướng tới) + vert (quay) → làm khách quay sự chú ý về sản phẩm → quảng cáo.", e: "Sai: an advertising → Đúng: an advertisement / an ad (advertising không đếm được). Sai: advertise for product → Đúng: advertise a product.", u: "IELTS Writing Task 2: impact of advertising on children. Marketing: advertising budget, advertising agency. TOEIC: advertising campaign.", f: "advertise (v), advertisement (n), advertiser (n), ad (n), commercial (n, quảng cáo TV)" },
  "slogan": { m: "Gốc Gaelic 'tiếng hô xung trận' → câu hô ngắn, dễ nhớ của chiến dịch → khẩu hiệu.", e: "Sai: slogan of Nike is Just do it → Đúng: Nike's slogan is 'Just Do It'. Sai: a long slogan paragraph → Đúng: a catchy slogan.", u: "Quảng cáo, chính trị: catchy slogan, campaign slogan, come up with a slogan. IELTS Speaking: kể về một quảng cáo ấn tượng.", f: "tagline (n), motto (n), catchphrase (n), jingle (n, nhạc quảng cáo)" },
  "tagline": { m: "tag (cái nhãn gắn) + line (câu) → câu ngắn gắn liền sau tên thương hiệu.", e: "Sai: tag line of the brand's → Đúng: the brand's tagline. Nhầm tagline (gắn lâu dài) với slogan (theo từng chiến dịch).", u: "Branding, quảng cáo: memorable tagline, write a tagline for the logo, tagline appears under the brand name.", f: "tag (n/v), slogan (n), strapline (UK), catchphrase (n), motto (n)" },
  "copywriting": { m: "copy (văn bản quảng cáo, không phải 'sao chép') + writing → viết chữ cho quảng cáo.", e: "Sai: hiểu copywriting là chép lại / bản quyền → Đúng: viết lời quảng cáo. Nhầm với copyright (bản quyền).", u: "Marketing, agency: persuasive copywriting, SEO copywriting, ad copy for landing pages. IELTS Speaking: nghề nghiệp sáng tạo.", f: "copy (n), copywriter (n), copyedit (v), content writing, copyright (n, dễ nhầm)" },
  "call to action": { m: "Hình ảnh: lời 'gọi' (call) khách 'hành động' ngay: Mua ngay, Đăng ký → nút CTA.", e: "Sai: a call for action button → Đúng: a call-to-action button. Sai: CTA unclear make customer confused → Đúng: an unclear CTA confuses customers.", u: "Marketing số, email: strong call to action, CTA button 'Sign up now', place the CTA above the fold.", f: "CTA, call-to-action (adj), action button, prompt (n), conversion (n)" },
  "landing page": { m: "Hình ảnh: máy bay 'hạ cánh' (land) → trang khách đáp xuống khi bấm quảng cáo → trang đích.", e: "Sai: landing website → Đúng: landing page. Sai: home page và landing page giống nhau → Đúng: landing page phục vụ một mục tiêu duy nhất.", u: "Marketing số: optimize the landing page, landing page conversion, A/B test landing pages, lead capture form.", f: "land (v), home page (n), web page, squeeze page, microsite (n)" },
  "conversion rate": { m: "convert (chuyển đổi) → người xem 'chuyển thành' người mua; rate = tỷ lệ phần trăm.", e: "Sai: conversion rate is increase → Đúng: the conversion rate has increased. Sai: rate of convert → Đúng: rate of conversion.", u: "Marketing số, thương mại điện tử: improve the conversion rate, conversion rate optimization (CRO), conversion rate of 3%.", f: "convert (v), conversion (n), CRO, conversion funnel, bounce rate (n)" },
  "click-through rate": { m: "click through = bấm qua đường link → tỷ lệ người thấy quảng cáo và bấm vào.", e: "Sai: click through ratio → Đúng: click-through rate (CTR). Sai: CTR is high mean sales high → Đúng: a high CTR does not guarantee sales.", u: "Quảng cáo số, email marketing: average click-through rate, CTR = clicks / impressions, improve CTR with better headlines.", f: "CTR, click (n/v), impression (n), clickthrough (n), engagement rate" },
  "influencer": { m: "influence (ảnh hưởng, 'chảy vào' suy nghĩ người khác) + -er (người) → người có sức ảnh hưởng.", e: "Sai: She is an influence on Instagram → Đúng: She is an influencer on Instagram. Sai: influence to young people → Đúng: influence young people.", u: "Marketing: influencer marketing, partner with influencers, micro-influencer. IELTS Speaking/Writing: influencers and young people's spending.", f: "influence (n/v), influential (adj), KOL (key opinion leader), content creator (n)" },
  "endorsement": { m: "en- + dorse (lưng, mặt sau) → ký mặt sau tờ séc để xác nhận → chứng thực, bảo chứng.", e: "Sai: celebrity endorse → Đúng: celebrity endorsement. Sai: endorse for the product → Đúng: endorse the product.", u: "Quảng cáo: celebrity endorsement, endorsement deal worth millions. IELTS Writing: should athletes earn from endorsements?", f: "endorse (v), endorser (n), sponsorship (n), testimonial (n), backing (n)" },
  "public relations": { m: "relations (các mối quan hệ) với public (công chúng) → xây dựng hình ảnh tốt với công chúng → PR.", e: "Sai: public relation is important → Đúng: public relations is important (động từ số ít). Sai: do PR for → Đúng: handle PR for.", u: "Truyền thông: PR agency, public relations officer, PR campaign. TOEIC Part 7: tuyển nhân viên PR.", f: "PR, publicist (n), publicity (n), media relations, communications (n)" },
  "press release": { m: "press (báo chí) + release (phát hành) → văn bản phát cho báo chí → thông cáo báo chí.", e: "Sai: issue a press news → Đúng: issue a press release. Sai: press releasing → Đúng: press release.", u: "PR, doanh nghiệp: issue/send out a press release, according to a press release. TOEIC Part 7: thông báo sản phẩm mới.", f: "release (n/v), news release, media statement, press kit, announcement (n)" },
  "press conference": { m: "press (báo chí) + conference (hội nghị) → buổi gặp báo chí để trả lời câu hỏi → họp báo.", e: "Sai: open a press conference → Đúng: hold a press conference. Sai: press meeting → Đúng: press conference / news conference.", u: "PR, chính trị: hold/give a press conference, at a press conference, take questions from reporters. TOEIC Part 4: tin tức.", f: "conference (n), news conference, press briefing, media event, spokesperson (n)" },
  "media coverage": { m: "cover (che phủ) → truyền thông 'phủ' tin về sự kiện nhiều hay ít → mức độ đưa tin.", e: "Sai: media covers too much → Đúng: the event received extensive media coverage. Sai: a media coverages → Đúng: media coverage (không đếm được).", u: "PR: gain/receive media coverage, positive/negative media coverage. IELTS Writing: media coverage of crime or celebrities.", f: "cover (v), coverage (n), press coverage, publicity (n), news report" },
  "crisis communication": { m: "crisis (khủng hoảng) + communication → cách công ty 'lên tiếng' khi gặp khủng hoảng.", e: "Sai: crisis communicate plan → Đúng: crisis communication plan. Sai: crisises → Đúng: crises (số nhiều của crisis).", u: "PR: crisis communication plan, handle a product recall, issue a public apology quickly and transparently.", f: "crisis (n), crises (pl), crisis management, damage control, spokesperson (n)" },
  "reputation management": { m: "reputation (tiếng tăm, gốc 'repute' = nghĩ lại về ai) + management → chăm sóc tiếng tăm thương hiệu.", e: "Sai: manage the reputations of brand → Đúng: manage the brand's reputation. Sai: reputative → Đúng: reputable (adj).", u: "PR, mạng xã hội: online reputation management, respond to negative reviews, protect corporate reputation.", f: "reputation (n), reputable (adj), repute (n), image management, brand image" },
  "content marketing": { m: "content (nội dung) → thu hút khách bằng nội dung hữu ích (blog, video) thay vì quảng cáo trực tiếp.", e: "Sai: contents marketing → Đúng: content marketing. Sai: make many contents → Đúng: create a lot of content (thường không đếm được).", u: "Marketing số: content marketing strategy, blog posts, videos, e-books; build trust, improve SEO, attract leads.", f: "content (n), content creator (n), content strategy, inbound marketing, storytelling (n)" },
  "social media marketing": { m: "Quảng bá trên social media (Facebook, TikTok, Instagram) → tiếp thị qua mạng xã hội (SMM).", e: "Sai: social network marketing on Facebook pages's → Đúng: social media marketing on Facebook. Sai: socials media → Đúng: social media.", u: "Marketing số: social media marketing campaign, engagement, followers. IELTS Speaking: how businesses use social media.", f: "SMM, social media (n), social media manager (n), influencer marketing, community management" },
  "email marketing": { m: "Gửi email đến danh sách khách để giới thiệu, khuyến mãi → tiếp thị qua email.", e: "Sai: send emails marketing → Đúng: run email marketing campaigns. Sai: e-mail spams to customers → Đúng: avoid spamming customers.", u: "Marketing số: email marketing campaign, newsletter, open rate, unsubscribe link, segment the mailing list.", f: "email (n/v), newsletter (n), mailing list, open rate, opt-in (n/adj)" },
  "pay-per-click": { m: "pay (trả) per (mỗi) click (lượt nhấp) → chỉ trả tiền khi có người nhấp quảng cáo.", e: "Sai: pay for click advertising → Đúng: pay-per-click advertising. Sai: pay per each click → Đúng: pay per click (PPC).", u: "Quảng cáo số: pay-per-click campaign on Google Ads, set a PPC budget, cost per click (CPC).", f: "PPC, cost per click (CPC), search advertising, cost per mille (CPM), bidding (n)" },
  "keyword": { m: "key (chìa khóa) + word → từ 'chìa khóa' người dùng gõ để tìm kiếm → từ khóa.", e: "Sai: key words research → Đúng: keyword research. Sai: stuff the keyword in text → Đúng: avoid keyword stuffing.", u: "SEO, marketing số: keyword research, target keywords, long-tail keyword. IELTS Reading: tìm keywords trong câu hỏi.", f: "keyword research, long-tail keyword, search term, SEO (n), keyword stuffing" },
  "organic traffic": { m: "organic (tự nhiên, không 'bón' tiền) → lượt truy cập đến từ tìm kiếm tự nhiên, không trả phí.", e: "Sai: organic traffics → Đúng: organic traffic (không đếm được). Sai: organic traffic from ads → Đúng: paid traffic from ads.", u: "SEO, marketing số: increase organic traffic, organic vs. paid traffic, track traffic in Google Analytics.", f: "organic (adj), organically (adv), paid traffic, website traffic, organic reach" },
  "analytics": { m: "analyze (phân tích) → -tics (ngành, như 'statistics') → khoa học phân tích dữ liệu để ra quyết định.", e: "Sai: an analytics → Đúng: analytics (danh từ không đếm được). Sai: analytic data shows → Đúng: the analytics show / analytical data.", u: "Marketing số: web analytics, Google Analytics, data analytics dashboard, track user behavior và đo hiệu quả chiến dịch.", f: "analyze (v), analysis (n), analyst (n), analytical (adj), data analytics" },
  "customer acquisition cost": { m: "acquire (giành được) → chi phí bỏ ra để 'giành được' một khách hàng mới (CAC).", e: "Sai: customer acquire cost → Đúng: customer acquisition cost. Sai: CAC is cost for keep customer → Đúng: CAC is the cost of gaining a customer.", u: "Marketing, khởi nghiệp: lower customer acquisition cost, CAC = marketing spend / new customers, compare CAC with CLV.", f: "acquire (v), acquisition (n), CAC, cost per acquisition (CPA), customer lifetime value" },
  "customer lifetime value": { m: "lifetime (cả đời) value → tổng tiền một khách mang lại trong suốt thời gian gắn bó (CLV).", e: "Sai: customer life time value → Đúng: customer lifetime value. Sai: CLV is lower than CAC is good → Đúng: CLV should exceed CAC.", u: "Marketing, phân tích kinh doanh: increase customer lifetime value, CLV to CAC ratio, retention and upselling strategies.", f: "CLV, LTV, lifetime (n), retention (n), customer acquisition cost" },
  "lead generation": { m: "lead (khách hàng tiềm năng, đầu mối) + generation (tạo ra) → tạo ra danh sách khách tiềm năng.", e: "Sai: lead generate → Đúng: lead generation / generate leads. Sai: lead là người dẫn đầu ở đây → Đúng: lead là khách tiềm năng.", u: "Marketing B2B: lead generation strategy, lead magnet, qualified leads, lead nurturing qua email.", f: "lead (n), generate (v), lead magnet, prospect (n), sales qualified lead (SQL)" },
  "sales funnel": { m: "Hình ảnh: cái phễu (funnel) miệng rộng nhiều người biết, đáy hẹp ít người mua → phễu bán hàng.", e: "Sai: sale funnel → Đúng: sales funnel. Sai: customers go in funnel → Đúng: customers move through the sales funnel.", u: "Marketing, bán hàng: top/middle/bottom of the funnel, AIDA model, drop-off at each funnel stage.", f: "funnel (n/v), marketing funnel, conversion funnel, pipeline (n), AIDA" },
  "customer journey": { m: "journey (hành trình) → mọi chặng khách đi qua: biết đến, tìm hiểu, mua, quay lại.", e: "Sai: customer trip → Đúng: customer journey. Sai: map customer's journeys → Đúng: map the customer journey.", u: "Marketing, UX: customer journey map, improve the customer journey, identify pain points at each stage.", f: "journey (n), customer experience (CX), touchpoint (n), journey mapping, buyer's journey" },
  "touchpoint": { m: "touch (chạm) + point (điểm) → mỗi lần khách 'chạm' vào thương hiệu: web, cửa hàng, hotline.", e: "Sai: touch points of customer's → Đúng: customer touchpoints. Sai: a touchpoint is only the shop → Đúng: touchpoints include online and offline contacts.", u: "Marketing, dịch vụ khách hàng: key touchpoints, consistent experience across all touchpoints, digital touchpoints.", f: "touch (n/v), point of contact, customer journey, channel (n), interaction (n)" },
  "retargeting": { m: "re- (lại) + target (nhắm) → nhắm lại vào người đã ghé web nhưng chưa mua → quảng cáo bám đuổi.", e: "Sai: re-target ads follow customer → Đúng: retargeting ads follow visitors. Sai: retargeting to new customers → Đúng: retargeting past visitors.", u: "Quảng cáo số: retargeting campaign, Facebook pixel, retargeting abandoned carts, remarketing via email.", f: "retarget (v), remarketing (n), target (n/v), pixel (n), abandoned cart" },
  "a/b testing": { m: "A và B là hai phiên bản → chia khách làm hai nhóm, xem bản nào hiệu quả hơn.", e: "Sai: test A/B for the website → Đúng: run an A/B test on the website. Sai: A/B testing many changes at once → Đúng: test one variable at a time.", u: "Marketing số, UX: A/B testing email subject lines, headlines, CTA buttons; split testing to boost conversion rate.", f: "A/B test (n), split testing, multivariate testing, variant (n), control group" },
  "user-generated content": { m: "user (người dùng) + generated (được tạo) → nội dung do chính khách tạo ra: review, ảnh, video.", e: "Sai: user generating content → Đúng: user-generated content (UGC). Sai: a UGCs → Đúng: UGC (không đếm được).", u: "Marketing, mạng xã hội: encourage user-generated content, UGC campaign with a branded hashtag, reviews build trust.", f: "UGC, generate (v), review (n), testimonial (n), branded hashtag" },
  "viral": { m: "virus → lan nhanh như virus, người này chia sẻ cho người kia → lan truyền mạnh.", e: "Sai: The video is very viral → Đúng: The video went viral. Sai: viral a video → Đúng: make a video go viral.", u: "Marketing, mạng xã hội: go viral, viral marketing, viral video. IELTS Speaking: kể về một video lan truyền.", f: "virus (n), virality (n), go viral, word of mouth, trending (adj)" },
  "loyalty program": { m: "loyal (trung thành) → chương trình thưởng điểm cho khách trung thành, mua nhiều được ưu đãi.", e: "Sai: loyal program → Đúng: loyalty program. Sai: join to loyalty program → Đúng: join a loyalty program.", u: "Bán lẻ, marketing: loyalty program members, earn/redeem points, loyalty card. TOEIC Part 7: email mời tham gia chương trình.", f: "loyal (adj), loyalty (n), rewards program, loyalty card, membership scheme" },
  "free sample": { m: "sample (mẫu thử) + free → cho dùng thử miễn phí để khách mua sau.", e: "Sai: a free samples → Đúng: a free sample / free samples. Sai: give free sample for customers → Đúng: give free samples to customers.", u: "Marketing, bán lẻ: hand out free samples, request a free sample, product sampling. TOEIC Part 3, 4: khuyến mãi tại cửa hàng.", f: "sample (n/v), sampling (n), free trial, giveaway (n), tester (n)" },
  "point of sale": { m: "point (điểm) of sale (bán) → điểm diễn ra giao dịch thanh toán, cả máy tính tiền POS.", e: "Sai: point of sell → Đúng: point of sale. Sai: point of sales system → Đúng: point-of-sale (POS) system.", u: "Bán lẻ, marketing: POS system, point-of-sale display, impulse purchases at the point of sale.", f: "POS, checkout (n), cash register, point-of-purchase (POP), terminal (n)" },
  "merchandising": { m: "merchandise (hàng hóa) → sắp xếp, trưng bày hàng cho bắt mắt, kích thích mua.", e: "Sai: merchandize display → Đúng: merchandising display. Sai: a merchandises → Đúng: merchandise (không đếm được).", u: "Bán lẻ: visual merchandising, merchandising team, planogram, shelf placement. TOEIC: retail job descriptions.", f: "merchandise (n/v), merchandiser (n), merchant (n), visual merchandising, merch (n, hàng lưu niệm)" },
  "pricing strategy": { m: "pricing (việc định giá) + strategy (chiến lược) → kế hoạch đặt giá để thu hút và có lãi.", e: "Sai: price strategy of product's → Đúng: the product's pricing strategy. Sai: strategy pricing → Đúng: pricing strategy.", u: "Marketing, kinh doanh: competitive pricing strategy, premium vs. penetration pricing, psychological pricing (giá 99.000).", f: "price (n/v), pricing (n), premium pricing, penetration pricing, price skimming" },
  "premium pricing": { m: "premium (hảo hạng) → đặt giá cao để khẳng định chất lượng và sự sang trọng.", e: "Sai: premium price strategy is cheap → Đúng: premium pricing means setting high prices. Sai: pricing premium → Đúng: premium pricing.", u: "Marketing: Apple uses premium pricing, justify premium pricing with brand equity, luxury goods.", f: "premium (n/adj), prestige pricing, price skimming, luxury (n), penetration pricing (trái nghĩa)" },
  "penetration pricing": { m: "penetrate (xuyên vào) → giá thấp để 'xuyên' nhanh vào thị trường, giành thị phần.", e: "Sai: penetrate pricing → Đúng: penetration pricing. Sai: penetration pricing is high price → Đúng: it uses low introductory prices.", u: "Marketing: use penetration pricing to enter a new market, low introductory price, gain market share quickly.", f: "penetrate (v), penetration (n), market penetration, price skimming (trái nghĩa), introductory price" },
  "product launch": { m: "launch (phóng tên lửa) → 'phóng' sản phẩm mới ra thị trường → ra mắt sản phẩm.", e: "Sai: launch out a product → Đúng: launch a product. Sai: product launching event → Đúng: product launch event.", u: "Marketing, TOEIC Part 3, 4, 7: postpone the product launch, launch event, launch date. Phỏng vấn: kinh nghiệm ra mắt sản phẩm.", f: "launch (n/v), relaunch (v/n), rollout (n), debut (n/v), go-to-market" },
  "product life cycle": { m: "Như đời người: sinh (introduction), lớn (growth), trưởng thành (maturity), già (decline).", e: "Sai: product life circle → Đúng: product life cycle. Sai: in maturity stage sales grow fast → Đúng: sales grow fastest in the growth stage.", u: "Marketing: four stages of the product life cycle, extend the product life cycle, chiến lược theo từng giai đoạn.", f: "life cycle (n), lifecycle (n), introduction, growth, maturity, decline" },
  "differentiation": { m: "different (khác) → -iate → -ation: làm cho sản phẩm khác đối thủ → khác biệt hóa.", e: "Sai: differentiate from between → Đúng: differentiate A from B. Sai: product differentiate → Đúng: product differentiation.", u: "Marketing, chiến lược: product differentiation, differentiation strategy (Porter), stand out from competitors.", f: "differentiate (v), different (adj), difference (n), differentiator (n), USP" },
  "brand ambassador": { m: "ambassador (đại sứ) → người đại diện 'ngoại giao' cho thương hiệu trước công chúng.", e: "Sai: brand embassy → Đúng: brand ambassador. Sai: become ambassador of brand → Đúng: become a brand ambassador for the brand.", u: "Marketing: appoint a brand ambassador, celebrity brand ambassador, employees as brand ambassadors.", f: "ambassador (n), embassy (n), spokesperson (n), endorser (n), influencer (n)" },
  "media planning": { m: "plan (lên kế hoạch) chọn kênh media nào, lúc nào, bao nhiêu → hoạch định truyền thông.", e: "Sai: media plan is buying ads → Đúng: media planning chooses channels; media buying purchases ad space. Sai: plan media → Đúng: media planning.", u: "Agency quảng cáo: media planning team, media plan with reach and frequency, allocate budget across channels.", f: "media plan (n), media planner (n), media buying, reach (n), frequency (n)" },
  "media buying": { m: "buy (mua) chỗ quảng cáo trên TV, báo, web → mua phương tiện truyền thông.", e: "Sai: buy medias → Đúng: buy media / media buying. Sai: media buyings → Đúng: media buying (không đếm được).", u: "Agency quảng cáo: media buying agency, negotiate ad rates, programmatic media buying, ad placement.", f: "media buyer (n), ad space, ad placement, programmatic buying, media planning" },
  "billboard": { m: "bill (tờ áp phích) + board (tấm bảng) → tấm bảng lớn dán quảng cáo ven đường.", e: "Sai: a billboard on the TV → Đúng: a billboard by the road. Sai: bill board → Đúng: billboard.", u: "Quảng cáo ngoài trời: put up a billboard, digital billboard, highway billboard. IELTS Writing: quảng cáo trong thành phố.", f: "hoarding (UK), poster (n), signboard (n), out-of-home advertising, digital signage" },
  "banner ad": { m: "banner (băng rôn, dải cờ) → quảng cáo hình chữ nhật dài trên trang web.", e: "Sai: banner advertise → Đúng: banner ad / banner advertisement. Sai: click into banner → Đúng: click on a banner ad.", u: "Quảng cáo số: display banner ads, banner blindness, banner ad sizes, CPM-based banner campaigns.", f: "banner (n), display ad, ad (n), pop-up ad, banner blindness" },
  "out-of-home advertising": { m: "out of home (ngoài nhà) → quảng cáo bắt gặp khi ra đường: billboard, xe buýt, nhà chờ.", e: "Sai: outside home advertising → Đúng: out-of-home advertising (OOH). Sai: OOH is TV ads → Đúng: OOH appears in public spaces.", u: "Marketing: OOH campaign, transit advertising, digital out-of-home (DOOH), high-traffic locations.", f: "OOH, DOOH, billboard (n), outdoor advertising, transit advertising" },
  "print media": { m: "print (in ấn) + media → các kênh in trên giấy: báo, tạp chí, tờ rơi.", e: "Sai: printed medias → Đúng: print media. Sai: print media are dying fast → Đúng: print media is declining.", u: "Marketing, IELTS Writing: decline of print media, print vs. digital media, newspapers losing readers.", f: "print (n/v), printed (adj), press (n), digital media, broadcast media" },
  "storytelling": { m: "story (câu chuyện) + telling (kể) → truyền thông điệp thương hiệu bằng câu chuyện cảm xúc.", e: "Sai: story telling skill's → Đúng: storytelling skills. Sai: tell storytelling → Đúng: use storytelling.", u: "Marketing, thuyết trình: brand storytelling, emotional storytelling in ads. IELTS Speaking: kỹ năng kể chuyện.", f: "storyteller (n), story (n), narrative (n), brand story, content marketing" },
  "brand voice": { m: "voice (giọng nói) → thương hiệu cũng có 'giọng': thân thiện, nghiêm túc, hài hước.", e: "Sai: brand's sound → Đúng: brand voice. Sai: brand voice changes every post → Đúng: keep a consistent brand voice.", u: "Content, social media: consistent brand voice, define tone of voice, brand voice guidelines for copywriters.", f: "tone of voice, brand personality, brand guidelines, voice (n), style guide" },
  "creative brief": { m: "brief (ngắn gọn) → bản tóm tắt ngắn nêu mục tiêu, đối tượng, thông điệp cho đội sáng tạo.", e: "Sai: a creative briefing paper's → Đúng: a creative brief. Sai: brief là đơn giản thôi → Đúng: brief là bản hướng dẫn dự án.", u: "Agency quảng cáo: write a creative brief, client brief, objectives, target audience, key message, deliverables, deadline.", f: "brief (n/v), briefing (n), debrief (v), client brief, project scope" },
  "account manager": { m: "account (khách hàng/tài khoản) → người phụ trách và chăm sóc khách hàng của agency.", e: "Sai: account manager là quản lý kế toán → Đúng: account manager chăm sóc khách hàng. Sai: manager of account → Đúng: account manager.", u: "Agency, sales B2B: key account manager, client servicing, TOEIC Part 7: tin tuyển dụng account manager.", f: "account (n), key account, account executive (AE), client service (n), account director" },
  "copywriter": { m: "copy (chữ quảng cáo) + writer → người viết chữ quảng cáo; không phải người sao chép.", e: "Sai: copyrighter → Đúng: copywriter. Sai: he works as copywriting → Đúng: he works as a copywriter.", u: "Agency, marketing: senior copywriter, work with the art director, write headlines and slogans. IELTS Speaking: dream job.", f: "copywriting (n), copy (n), content writer (n), art director (n), editor (n)" },
  "art director": { m: "director (người chỉ đạo) về art (nghệ thuật, hình ảnh) → người quyết định phong cách hình ảnh.", e: "Sai: director of art painting → Đúng: art director (quảng cáo, phim). Sai: art direct → Đúng: art direction.", u: "Agency, phim ảnh: art director and copywriter team, oversee visual style, approve layouts and mock-ups.", f: "art direction (n), creative director (n), designer (n), copywriter (n), visual identity" },
  "mock-up": { m: "mock (giả, nhái) + up → bản mẫu 'giả' cho thấy thiết kế trông như thật.", e: "Sai: a mock → Đúng: a mock-up / mockup. Sai: mock up a design's → Đúng: mock up a design.", u: "Thiết kế, marketing: create a mock-up of the packaging, website mock-up, present mock-ups to the client.", f: "mock up (v), mockup (n), prototype (n), wireframe (n), draft (n)" },
  "visual identity": { m: "visual (thị giác) + identity → mọi thứ mắt nhìn thấy của thương hiệu: logo, màu, font.", e: "Sai: visualize identity → Đúng: visual identity. Sai: visual identity is only logo → Đúng: it includes colours, fonts and imagery.", u: "Thiết kế, branding: refresh the visual identity, visual identity system, consistent colours and typography.", f: "visual (adj), visualize (v), brand identity, logo (n), typography (n)" },
  "infographic": { m: "info (thông tin) + graphic (đồ họa) → biến số liệu thành hình ảnh dễ hiểu.", e: "Sai: an infographics → Đúng: an infographic / infographics. Sai: info graphic → Đúng: infographic.", u: "Content marketing, báo chí: design an infographic, share infographics on social media. IELTS Writing Task 1: đọc biểu đồ.", f: "infographics (n, pl), graphic (n/adj), data visualization, chart (n), diagram (n)" },
  "hashtag": { m: "hash (dấu #) + tag (nhãn) → nhãn có dấu # giúp gom bài cùng chủ đề.", e: "Sai: put a hash tag → Đúng: use a hashtag. Sai: #summer sale (có dấu cách) → Đúng: #summersale.", u: "Mạng xã hội: branded hashtag, trending hashtag, hashtag campaign. IELTS Speaking: thói quen dùng mạng xã hội.", f: "hashtag (v), tag (n/v), trending topic, branded hashtag, mention (n)" },
  "follower": { m: "follow (theo dõi) + -er (người) → người bấm theo dõi tài khoản của bạn.", e: "Sai: She has 1 million follows → Đúng: She has 1 million followers. Sai: gain followers' number → Đúng: gain followers.", u: "Mạng xã hội, marketing: grow followers, follower count, buy fake followers. IELTS Speaking: social media và người nổi tiếng.", f: "follow (v), following (n), unfollow (v), subscriber (n), fan base (n)" },
  "omnichannel": { m: "omni- (tất cả, như 'omnivore') + channel (kênh) → mọi kênh liên thông, trải nghiệm liền mạch.", e: "Sai: omnichannel = có nhiều kênh rời rạc → Đúng: đó là multichannel; omnichannel kết nối các kênh. Sai: omni channel → Đúng: omnichannel.", u: "Bán lẻ, marketing: omnichannel strategy, omnichannel retail, buy online pick up in store (BOPIS).", f: "multichannel (adj), cross-channel (adj), channel (n), seamless experience, O2O" },
  "integrated marketing communications": { m: "integrated (tích hợp) → mọi kênh truyền thông nói cùng một thông điệp, phối hợp nhịp nhàng.", e: "Sai: integrating marketing communication → Đúng: integrated marketing communications (IMC). Sai: IMC are → Đúng: IMC is.", u: "Marketing: IMC plan, combine advertising, PR, digital and events with one consistent message.", f: "integrate (v), integration (n), IMC, promotional mix, 360-degree campaign" },
  "inbound marketing": { m: "inbound (hướng vào trong) → kéo khách tự tìm đến nhờ nội dung hữu ích, SEO.", e: "Sai: inbound marketing = gọi điện chào hàng → Đúng: đó là outbound. Sai: in-bound → Đúng: inbound.", u: "Marketing số: inbound marketing strategy, attract-engage-delight, blogs, SEO, lead magnets (HubSpot).", f: "inbound (adj), outbound marketing (trái nghĩa), content marketing, pull marketing" },
  "outbound marketing": { m: "outbound (hướng ra ngoài) → doanh nghiệp chủ động 'đẩy' thông điệp ra: TV, cold call.", e: "Sai: outbound marketing là khách tự tìm → Đúng: doanh nghiệp chủ động tiếp cận. Sai: out bound → Đúng: outbound.", u: "Marketing: outbound tactics like cold calling, TV ads, direct mail; so sánh chi phí với inbound marketing.", f: "outbound (adj), push marketing, cold calling, direct mail, inbound marketing (trái nghĩa)" },
  "guerrilla marketing": { m: "guerrilla (du kích) → đánh bất ngờ, chi phí thấp, sáng tạo để gây chú ý.", e: "Sai: gorilla marketing (con khỉ đột) → Đúng: guerrilla marketing. Sai: guerilla → cả hai cách viết đều được, guerrilla phổ biến hơn.", u: "Marketing: low-budget guerrilla marketing, street art, flash mob, ambient advertising. IELTS Speaking: quảng cáo sáng tạo.", f: "guerrilla (n/adj), ambient marketing, stunt (n), viral marketing, ambush marketing" },
  "experiential marketing": { m: "experience (trải nghiệm) → cho khách trực tiếp trải nghiệm thương hiệu thay vì chỉ xem quảng cáo.", e: "Sai: experience marketing → Đúng: experiential marketing. Sai: experimental marketing (thí nghiệm) → Đúng: experiential.", u: "Marketing, sự kiện: pop-up store, product demo, immersive brand activation. IELTS Speaking: kể về một sự kiện thương hiệu.", f: "experience (n/v), experiential (adj), brand activation, event marketing, engagement marketing" },
  "affiliate marketing": { m: "affiliate (chi nhánh, đối tác liên kết) → đối tác giới thiệu sản phẩm, nhận hoa hồng khi bán được.", e: "Sai: affiliation marketing → Đúng: affiliate marketing. Sai: earn commission from affiliate's link → Đúng: earn commission through affiliate links.", u: "Thương mại điện tử: affiliate program, affiliate link, commission per sale, Shopee/Amazon affiliates.", f: "affiliate (n/v), affiliation (n), commission (n), referral (n), partner marketing" },
  "b2b": { m: "Business-to-Business: '2' đọc là 'to' → doanh nghiệp bán cho doanh nghiệp.", e: "Sai: B2B customers are individual → Đúng: B2B customers are businesses. Sai: B to B company's → Đúng: a B2B company.", u: "Kinh doanh, marketing: B2B sales, B2B marketing via LinkedIn, long sales cycles, multiple decision-makers.", f: "B2C, B2G (business-to-government), C2C, enterprise (adj), wholesale (n)" },
  "b2c": { m: "Business-to-Consumer → doanh nghiệp bán thẳng cho người tiêu dùng cuối.", e: "Sai: B2C sells to companies → Đúng: B2C sells to individual consumers. Sai: B2C market are → Đúng: the B2C market is.", u: "Bán lẻ, thương mại điện tử: B2C e-commerce, B2C brands, emotional advertising, short buying decisions.", f: "B2B, D2C (direct-to-consumer), C2C, retail (n), consumer (n)" },
  "churn rate": { m: "churn (khuấy, đảo) → khách 'đảo' đi, rời bỏ dịch vụ → tỷ lệ khách rời bỏ.", e: "Sai: churn rate high is good → Đúng: a high churn rate is bad. Sai: customer churns rate → Đúng: customer churn rate.", u: "SaaS, viễn thông: reduce churn rate, monthly churn, retention strategies, churn analysis.", f: "churn (n/v), attrition (n), retention rate (trái nghĩa), cancellation (n)" },
  "customer satisfaction": { m: "satisfy (làm hài lòng) → mức độ khách thấy hài lòng với sản phẩm, dịch vụ.", e: "Sai: customer satisfy → Đúng: customer satisfaction. Sai: satisfaction of customer's → Đúng: customer satisfaction / satisfaction among customers.", u: "TOEIC Part 4, 7: customer satisfaction survey, improve customer satisfaction. Marketing: CSAT score.", f: "satisfy (v), satisfied (adj), satisfactory (adj), dissatisfaction (n), CSAT" },
  "net promoter score": { m: "promoter (người quảng bá) → hỏi 'Bạn có giới thiệu chúng tôi không?' từ 0–10.", e: "Sai: net promote score → Đúng: net promoter score (NPS). Sai: NPS = average of scores → Đúng: NPS = promoters minus detractors.", u: "Marketing, CX: measure NPS, promoters (9–10), passives, detractors (0–6), track customer loyalty.", f: "NPS, promoter (n), detractor (n), passive (n), CSAT, customer loyalty" },
  "testimonial": { m: "testi- (làm chứng, như 'testify') → lời khách làm chứng sản phẩm tốt.", e: "Sai: testimony (lời khai trước tòa) dùng trên website → Đúng: customer testimonials. Sai: testimonial of customers say → Đúng: testimonials from customers say.", u: "Marketing, website: display customer testimonials, video testimonials, social proof. TOEIC Part 7: quảng cáo kèm lời khen.", f: "testify (v), testimony (n), review (n), endorsement (n), social proof" },
  "case study": { m: "case (trường hợp) + study (nghiên cứu) → phân tích sâu một trường hợp cụ thể làm bằng chứng.", e: "Sai: a case studies → Đúng: a case study / case studies. Sai: make case study about → Đúng: conduct a case study of.", u: "Marketing B2B: publish client case studies. Học thuật, IELTS Writing: 'a case study of Singapore shows...'.", f: "case (n), case studies (pl), success story, example (n), white paper" },
  "white paper": { m: "Gốc chính phủ Anh: báo cáo bìa trắng → tài liệu chuyên sâu, có số liệu, giải thích vấn đề.", e: "Sai: white paper là giấy trắng → Đúng: tài liệu chuyên sâu. Sai: write white papers' report → Đúng: publish a white paper.", u: "Marketing B2B, công nghệ: download our white paper, gated content, establish thought leadership, generate leads.", f: "whitepaper (n), report (n), e-book (n), case study, thought leadership" },
  "webinar": { m: "web + seminar (hội thảo) → hội thảo tổ chức qua mạng → webinar.", e: "Sai: join in a webinar → Đúng: join / attend a webinar. Sai: webminar → Đúng: webinar.", u: "Marketing, đào tạo: host a webinar, register for a free webinar, Q&A session. TOEIC Part 4, 7: thông báo hội thảo online.", f: "seminar (n), online event, livestream (n), virtual conference, workshop (n)" },
  "trade show": { m: "trade (thương mại) + show (triển lãm) → doanh nghiệp cùng ngành dựng gian hàng trưng bày.", e: "Sai: join a trade show as booth → Đúng: exhibit at a trade show. Sai: trading show → Đúng: trade show / trade fair.", u: "TOEIC Part 3, 4, 7: attend a trade show, set up a booth, exhibitor. Marketing B2B: gặp khách tiềm năng.", f: "trade fair, exhibition (n), exhibitor (n), booth (n), expo (n)" },
  "event marketing": { m: "event (sự kiện) → quảng bá thương hiệu qua sự kiện khách tham gia trực tiếp hoặc online.", e: "Sai: events marketing → Đúng: event marketing. Sai: marketing event là ngành → Đúng: event marketing là ngành; marketing event là một sự kiện.", u: "Marketing: event marketing strategy, launch party, sponsor festivals, measure event ROI, generate leads at events.", f: "event (n), experiential marketing, sponsorship (n), activation (n), trade show" },
  "media kit": { m: "kit (bộ dụng cụ) cho media (báo chí) → bộ tài liệu sẵn: thông tin, ảnh, số liệu.", e: "Sai: media kits's information → Đúng: the media kit includes. Sai: press kid → Đúng: press kit / media kit.", u: "PR, influencer: send a media kit to journalists, influencer media kit with audience stats and rates.", f: "press kit, kit (n), fact sheet, press release, rate card" },
  "editorial calendar": { m: "editorial (biên tập) + calendar (lịch) → lịch đăng bài: chủ đề gì, ngày nào, kênh nào.", e: "Sai: editor calendar → Đúng: editorial calendar. Sai: plan content by random → Đúng: plan content with an editorial calendar.", u: "Content marketing, báo chí: create an editorial calendar, content calendar, publishing schedule, assign deadlines.", f: "editorial (adj/n), editor (n), content calendar, publishing schedule, content plan" },
  "marketing budget": { m: "budget (ngân sách) → khoản tiền dành riêng cho hoạt động marketing trong kỳ.", e: "Sai: marketing budget is over → Đúng: we went over the marketing budget. Sai: cut down budget of marketing → Đúng: cut the marketing budget.", u: "Marketing, TOEIC Part 3, 7: allocate the marketing budget, budget cuts, approve the budget, ROI.", f: "budget (n/v), budgetary (adj), allocate (v), spend (n), ROI" },
  "cross-selling": { m: "cross (ngang qua) → bán thêm sản phẩm 'bên cạnh' liên quan: mua điện thoại, gợi ý ốp lưng.", e: "Sai: cross-selling = bán bản đắt hơn → Đúng: đó là upselling. Sai: cross sell to → Đúng: cross-sell products to customers.", u: "Bán hàng, ngân hàng, e-commerce: cross-selling opportunities, 'frequently bought together', bancassurance.", f: "cross-sell (v), upselling (n), bundling (n), add-on (n), recommendation (n)" },
  "upselling": { m: "up (lên) → mời khách nâng 'lên' bản xịn hơn, size lớn hơn → bán gia tăng.", e: "Sai: up-sell the customer to buy → Đúng: upsell the customer to the premium plan. Sai: upselling = bán thêm món khác → Đúng: cross-selling.", u: "Bán hàng, nhà hàng, SaaS: upselling techniques, upsell to a premium plan, increase average order value.", f: "upsell (v), cross-selling (n), upgrade (n/v), add-on (n), premium plan" },
  "demographics": { m: "demo (dân, như 'democracy') + graph (viết) → số liệu mô tả dân số: tuổi, giới, thu nhập.", e: "Sai: the demographic of users are → Đúng: the demographics of users are. Sai: demography data → Đúng: demographic data.", u: "Marketing, IELTS Writing: target demographics, demographic changes, ageing population. Task 1: số liệu dân số.", f: "demographic (adj/n), demography (n), demographer (n), population (n), psychographics (n)" },
  "psychographics": { m: "psycho (tâm lý) + graph (mô tả) → mô tả lối sống, giá trị, sở thích của khách.", e: "Sai: psychographics = tuổi, thu nhập → Đúng: đó là demographics. Sai: psychographic of customers → Đúng: customers' psychographics.", u: "Marketing: psychographic segmentation, lifestyle, values, interests, attitudes; dùng để xây buyer persona.", f: "psychographic (adj), demographics (n), lifestyle (n), values (n), segmentation (n)" },
  "consumer insight": { m: "insight (nhìn vào bên trong) → hiểu sâu điều thầm kín khách cần, động lực thật khi mua.", e: "Sai: consumer insight = số liệu bán hàng → Đúng: sự thấu hiểu động cơ khách. Sai: insights of consumer's → Đúng: consumer insights.", u: "Marketing, nghiên cứu thị trường: uncover consumer insights, insight-driven campaign, creative brief starts with an insight.", f: "insight (n), insightful (adj), customer insight, market research, consumer behavior" },
  "dashboard": { m: "Gốc: bảng chắn bùn ở xe, sau là bảng đồng hồ → màn hình tổng hợp số liệu chính.", e: "Sai: dash board → Đúng: dashboard. Sai: see data in dashboard → Đúng: see data on the dashboard.", u: "Marketing, phân tích: marketing dashboard, real-time dashboard, KPIs on a dashboard, Google Data Studio / Power BI.", f: "dashboard (n), KPI, report (n), data visualization, control panel" },
  "metric": { m: "metr- (đo, như 'meter') → con số dùng để đo hiệu quả → chỉ số đo lường.", e: "Sai: metrics is important → Đúng: metrics are important. Sai: a metric system (hệ mét) dùng sai → Đúng: a key metric.", u: "Marketing, quản trị: key metrics, vanity metrics, track metrics like CTR, CAC, churn. Báo cáo hiệu quả hàng tháng.", f: "metrics (n, pl), measure (v), measurement (n), KPI, benchmark (n)" },
  "cost per mille": { m: "mille = 1.000 (tiếng Latin) → chi phí cho mỗi 1.000 lượt hiển thị (CPM).", e: "Sai: cost per million → Đúng: cost per mille (mỗi nghìn). Sai: cost per mile → Đúng: cost per mille.", u: "Quảng cáo số: CPM rate, CPM-based campaigns for awareness, compare CPM with CPC, media buying.", f: "CPM, cost per thousand, impression (n), CPC, pay-per-click" },
  "sponsored post": { m: "sponsor (tài trợ) → bài đăng mà nhãn hàng trả tiền cho người đăng.", e: "Sai: sponsor post → Đúng: sponsored post. Sai: không ghi #ad → Đúng: disclose sponsored posts clearly.", u: "Influencer marketing: paid sponsored posts, disclosure rules (#ad, #sponsored), rate per sponsored post.", f: "sponsor (n/v), sponsorship (n), paid partnership, native advertising, #ad" },
  "native advertising": { m: "native (bản địa, hòa vào môi trường) → quảng cáo trông giống nội dung thường của trang.", e: "Sai: nature advertising → Đúng: native advertising. Sai: native ads are hidden ads → Đúng: native ads must still be labeled.", u: "Quảng cáo số: native ads in news feeds, sponsored content, advertorial; tranh luận đạo đức về minh bạch.", f: "native (adj), native ad (n), advertorial (n), sponsored content, in-feed ad" },
  "brand guidelines": { m: "guidelines (hướng dẫn) → 'luật chơi' dùng logo, màu, font, giọng điệu thống nhất.", e: "Sai: brand guideline book's → Đúng: the brand guidelines. Sai: follow the brand guide line → Đúng: follow the brand guidelines.", u: "Branding, thiết kế: brand guidelines document, brand book, logo usage rules, consistent across agencies.", f: "guideline (n), brand book, style guide, visual identity, brand standards" },
  "earned media": { m: "earn (kiếm được nhờ công sức) → được nhắc đến miễn phí nhờ báo chí, khách chia sẻ.", e: "Sai: earned media = quảng cáo trả tiền → Đúng: đó là paid media. Sai: earn media → Đúng: earned media.", u: "PR, marketing: PESO model (Paid, Earned, Shared, Owned), earned media value, word of mouth, press mentions.", f: "earn (v), paid media, owned media, shared media, word of mouth" },
  "owned media": { m: "own (sở hữu) → kênh doanh nghiệp tự sở hữu: website, fanpage, blog, app.", e: "Sai: own media → Đúng: owned media. Sai: Facebook ads là owned media → Đúng: Facebook ads là paid media.", u: "Marketing: owned media channels, control the message on owned media, website và newsletter.", f: "own (v), owner (n), paid media, earned media, owned channels" },
  "paid media": { m: "paid (đã trả tiền) → kênh phải trả tiền để xuất hiện: quảng cáo Google, Facebook, TV.", e: "Sai: pay media → Đúng: paid media. Sai: paid media are free → Đúng: paid media requires a budget.", u: "Marketing: paid media campaigns, paid search, paid social, balance paid, owned and earned media.", f: "pay (v), paid (adj), paid search, paid social, advertising (n)" },
  "media relations": { m: "relations (quan hệ) với media (báo chí) → giữ mối quan hệ tốt với nhà báo.", e: "Sai: media relation are → Đúng: media relations is/are. Nhầm media relations (với nhà báo) với public relations (với công chúng nói chung).", u: "PR: media relations manager, build media relations, pitch stories to journalists, manage interviews.", f: "public relations, press relations, journalist (n), pitch (v), press office" },
  "internal communications": { m: "internal (nội bộ) + communications → truyền thông hướng vào nhân viên trong công ty.", e: "Sai: inner communication → Đúng: internal communications. Sai: internal communications for customers → Đúng: for employees.", u: "HR, PR doanh nghiệp: internal communications team, newsletters, town hall meetings, employee engagement.", f: "internal (adj), external communications (trái nghĩa), employee engagement, intranet (n)" },
  "market penetration": { m: "penetrate (xuyên vào) → mức độ sản phẩm 'xuyên' vào thị trường, chiếm bao nhiêu khách.", e: "Sai: market penetrate rate → Đúng: market penetration rate. Sai: penetrate into market → Đúng: penetrate the market.", u: "Chiến lược kinh doanh: increase market penetration, Ansoff matrix, smartphone penetration rate in Vietnam.", f: "penetrate (v), penetration (n), penetration pricing, market share (n), Ansoff matrix" },
  "go-to-market strategy": { m: "go to market (ra chợ) → kế hoạch đưa sản phẩm 'ra chợ': bán cho ai, qua kênh nào.", e: "Sai: go to market strategies is → Đúng: a go-to-market strategy is. Sai: going-to-market → Đúng: go-to-market (GTM).", u: "Khởi nghiệp, sản phẩm: define the GTM strategy, target market, pricing, channels, launch plan.", f: "GTM, product launch, launch plan, market entry strategy, positioning (n)" },
  "personalization": { m: "personal (cá nhân) + -ize → -ation: tùy chỉnh nội dung, ưu đãi cho từng người.", e: "Sai: personalize marketing → Đúng: personalized marketing. Sai: personalisation (UK) sai chính tả → Đúng: cả hai đều đúng, Anh dùng -s-.", u: "Marketing số: email personalization, personalized recommendations, data privacy concerns. IELTS Writing: công nghệ và quyền riêng tư.", f: "personalize (v), personalized (adj), customization (n), tailor (v), segmentation (n)" },
  "marketing automation": { m: "automate (tự động hóa) → phần mềm tự gửi email, đăng bài, chấm điểm khách.", e: "Sai: marketing automatic → Đúng: marketing automation. Sai: automate marketing replace all staff → Đúng: automation supports staff.", u: "Marketing số: marketing automation platform (HubSpot), automated email workflows, lead scoring, drip campaigns.", f: "automate (v), automated (adj), automation (n), workflow (n), drip campaign" },
  "climate change": { m: "climate (khí hậu dài hạn) + change → khí hậu thay đổi lâu dài, không phải thời tiết một ngày.", e: "Sai: the climate is changing day by day → Đúng: the weather changes daily; climate change is long-term. Sai: a climate change → Đúng: climate change.", u: "IELTS Writing Task 2: tackle/combat climate change, effects of climate change. Môi trường: climate policy, climate action.", f: "climatic (adj), climate crisis, global warming, climate action, climate-resilient (adj)" },
  "global warming": { m: "global (toàn cầu) + warming (ấm lên) → nhiệt độ trung bình Trái Đất tăng dần.", e: "Sai: the global warming → Đúng: global warming (không mạo từ). Sai: global warming makes Earth hot weather → Đúng: global warming raises average temperatures.", u: "IELTS Writing, Speaking: causes of global warming, greenhouse gases, fossil fuels. Môi trường: limit warming to 1.5°C.", f: "warm (v/adj), warming (n), climate change, greenhouse effect, heating (n)" },
  "greenhouse gas": { m: "greenhouse (nhà kính) → khí giữ nhiệt quanh Trái Đất như mái nhà kính trồng rau.", e: "Sai: green house gases → Đúng: greenhouse gases. Sai: emit greenhouse gas emissions → Đúng: emit greenhouse gases.", u: "IELTS Writing, môi trường: reduce greenhouse gas emissions, CO2, methane, nitrous oxide; GHG inventory.", f: "GHG, greenhouse effect, emissions (n), carbon dioxide, methane" },
  "greenhouse effect": { m: "Hình ảnh: nhà kính giữ ấm cây → khí quyển giữ nhiệt Mặt Trời làm Trái Đất ấm lên.", e: "Sai: greenhouse affect → Đúng: greenhouse effect. Sai: greenhouse effect is only bad → Đúng: it is natural; humans have intensified it.", u: "IELTS Writing, khoa học: the enhanced greenhouse effect, trap heat, explain the process in Task 1 diagrams.", f: "effect (n), greenhouse gas, global warming, heat-trapping (adj)" },
  "carbon dioxide": { m: "di- (hai) + oxide (ôxit) → một carbon và hai oxy: CO2.", e: "Sai: carbon dioxit → Đúng: carbon dioxide. Sai: carbon monoxide (CO, khí độc) dùng thay CO2 → Đúng: carbon dioxide.", u: "Môi trường, IELTS Writing: CO2 emissions, absorb carbon dioxide, atmospheric CO2 levels. Task 1: biểu đồ phát thải.", f: "CO2, carbon (n), carbon monoxide, emissions (n), oxide (n)" },
  "methane": { m: "meth- (gốc methyl) → khí CH4 từ ruộng lúa, bò, bãi rác; giữ nhiệt mạnh hơn CO2.", e: "Sai: methan → Đúng: methane /ˈmiːθeɪn/ (Mỹ /ˈmeθeɪn/). Sai: methane is less harmful than CO2 → Đúng: it traps more heat per molecule.", u: "Môi trường, nông nghiệp: methane emissions from livestock and rice paddies, landfill methane, biogas.", f: "CH4, biogas (n), greenhouse gas, natural gas, methane leak" },
  "net zero": { m: "net (ròng) → phát thải ra trừ đi lượng hấp thụ/bù lại = 0.", e: "Sai: net zero = không thải chút nào → Đúng: phát thải còn lại được bù trừ. Sai: reach to net zero → Đúng: reach net zero by 2050.", u: "Chính sách khí hậu: net-zero target, net-zero emissions by 2050 (Việt Nam cam kết tại COP26), net-zero buildings.", f: "net-zero (adj), carbon neutral, decarbonization (n), carbon offset" },
  "carbon neutral": { m: "neutral (trung tính, cân bằng) → lượng carbon thải ra được cân bằng bằng bù trừ.", e: "Sai: carbon neutralize company → Đúng: a carbon-neutral company. Sai: become carbon neutrality → Đúng: achieve carbon neutrality.", u: "Môi trường, doanh nghiệp: become carbon neutral by 2030, carbon-neutral flights, ESG reports.", f: "carbon neutrality (n), neutralize (v), net zero, carbon offset, low-carbon (adj)" },
  "carbon offset": { m: "offset (bù lại) → trả tiền trồng rừng, năng lượng sạch để bù lượng carbon mình thải.", e: "Sai: buy carbon offsetting credits's → Đúng: buy carbon offsets. Sai: offset carbon by plant tree → Đúng: offset carbon by planting trees.", u: "Môi trường, hàng không: carbon offset scheme, carbon credits, criticism of greenwashing through offsets.", f: "offset (n/v), carbon credit (n), carbon market, carbon neutral, greenwashing (n)" },
  "carbon capture": { m: "capture (bắt giữ) → 'bắt' CO2 từ ống khói hoặc không khí rồi chôn dưới lòng đất.", e: "Sai: carbon capturing and storages → Đúng: carbon capture and storage (CCS). Sai: capture of carbons → Đúng: carbon capture.", u: "Công nghệ môi trường: carbon capture and storage (CCS), direct air capture, decarbonize heavy industry.", f: "CCS, capture (n/v), sequestration (n), direct air capture, carbon sink (n)" },
  "solar power": { m: "sol (Mặt Trời, như 'solar system') → điện tạo từ ánh nắng Mặt Trời.", e: "Sai: sun power → Đúng: solar power. Sai: solar powers are → Đúng: solar power is (không đếm được).", u: "IELTS Writing, năng lượng: invest in solar power, solar panels, rooftop solar ở Ninh Thuận. Task 1: cơ cấu nguồn điện.", f: "solar (adj), solar panel, photovoltaic (PV), solar energy, solar farm" },
  "hydropower": { m: "hydro- (nước, như 'hydrogen') + power → điện tạo từ sức nước chảy qua đập.", e: "Sai: hydro power plants's → Đúng: hydropower plants. Sai: hydropower is no impact → Đúng: hydropower can harm river ecosystems.", u: "Năng lượng, môi trường: hydropower dam, Hòa Bình hydropower plant, impact on fish and downstream sediment.", f: "hydroelectric (adj), hydroelectricity (n), dam (n), reservoir (n), renewable energy" },
  "geothermal energy": { m: "geo (đất) + thermal (nhiệt) → năng lượng từ nhiệt nóng trong lòng đất.", e: "Sai: geothermic energies → Đúng: geothermal energy. Sai: geo-thermal → Đúng: geothermal.", u: "Năng lượng tái tạo: geothermal power plant (Iceland), geothermal heat pumps. IELTS Reading: bài về năng lượng.", f: "geothermal (adj), thermal (adj), heat pump, renewable energy, geyser (n)" },
  "air quality": { m: "air (không khí) + quality (chất lượng) → không khí sạch hay bẩn, đo bằng chỉ số AQI.", e: "Sai: air quality is very bad level → Đúng: air quality is very poor. Sai: the qualities of air → Đúng: air quality.", u: "IELTS Speaking/Writing: poor air quality in Hanoi, Air Quality Index (AQI), wear masks, monitor air quality.", f: "AQI, air pollution, air purifier (n), quality (n), clean air" },
  "particulate matter": { m: "particle (hạt nhỏ) → hạt bụi li ti lơ lửng; PM2.5 nhỏ hơn 2,5 micromet.", e: "Sai: particular matter → Đúng: particulate matter. Sai: PM2.5 matters are → Đúng: PM2.5 levels are.", u: "Môi trường, y tế: PM2.5 and PM10 concentrations, fine particulate matter causes respiratory disease.", f: "particle (n), particulate (adj/n), PM2.5, PM10, fine dust" },
  "smog": { m: "smoke (khói) + fog (sương mù) → smog: sương khói ô nhiễm bao phủ thành phố.", e: "Sai: smoke and fog over city (dài dòng) → Đúng: smog over the city. Sai: a thick smogs → Đúng: thick smog.", u: "IELTS Writing, môi trường: smog in big cities, photochemical smog, traffic and factories cause smog.", f: "smoggy (adj), haze (n), air pollution, fog (n), smoke (n)" },
  "acid rain": { m: "acid (axit) + rain → mưa lẫn khí SO2, NOx từ nhà máy nên có tính axit.", e: "Sai: acidic rain → Đúng: acid rain (cụm cố định). Sai: an acid rain → Đúng: acid rain (không đếm được).", u: "Khoa học, IELTS Writing: acid rain damages forests, lakes and buildings; sulfur dioxide from coal power plants.", f: "acid (n/adj), acidic (adj), acidity (n), sulfur dioxide, acidification (n)" },
  "contamination": { m: "con- + tam (chạm vào) → chất bẩn 'chạm vào' làm hỏng nguồn nước, thực phẩm → nhiễm bẩn.", e: "Sai: the water is contaminate → Đúng: the water is contaminated. Sai: contamination with bacteria of food → Đúng: bacterial contamination of food.", u: "Môi trường, thực phẩm: groundwater contamination, soil contamination, cross-contamination in kitchens.", f: "contaminate (v), contaminated (adj), contaminant (n), pollution (n), decontamination (n)" },
  "pollutant": { m: "pollute (làm ô nhiễm) + -ant (chất, như 'deodorant') → chất gây ô nhiễm.", e: "Sai: pollutions in the air → Đúng: pollutants in the air. Sai: pollutant gas's → Đúng: gaseous pollutants.", u: "Môi trường, IELTS Writing: release pollutants, air pollutants, industrial pollutants into rivers.", f: "pollute (v), pollution (n), polluter (n), polluted (adj), contaminant (n)" },
  "toxic waste": { m: "toxic (độc) + waste (chất thải) → chất thải chứa chất độc, gây hại sức khỏe.", e: "Sai: toxic wastes dumped → Đúng: toxic waste was dumped. Sai: toxicity waste → Đúng: toxic waste.", u: "Môi trường, IELTS Writing: dump toxic waste into rivers, toxic waste disposal, factories must treat waste.", f: "toxic (adj), toxin (n), toxicity (n), hazardous waste, chemical waste" },
  "hazardous waste": { m: "hazard (mối nguy) → chất thải nguy hại: dễ cháy, ăn mòn, độc, phóng xạ.", e: "Sai: harzardous → Đúng: hazardous. Sai: hazard waste → Đúng: hazardous waste.", u: "Quản lý môi trường: hazardous waste management, medical waste, batteries, licensed disposal facilities.", f: "hazard (n), hazardous (adj), toxic waste, medical waste, e-waste (n)" },
  "wastewater": { m: "waste (đã dùng, bỏ đi) + water → nước sau khi dùng ở nhà, nhà máy → nước thải.", e: "Sai: waste waters treatment → Đúng: wastewater treatment. Sai: discharge wastewater untreated into → Đúng: discharge untreated wastewater into.", u: "Môi trường, kỹ thuật: wastewater treatment plant, industrial wastewater, discharge standards.", f: "sewage (n), effluent (n), wastewater treatment, discharge (n/v)" },
  "sewage": { m: "sewer (cống) → thứ chảy trong cống: nước thải sinh hoạt, chất thải.", e: "Sai: sewages → Đúng: sewage (không đếm được). Sai: sewer (cống) dùng thay sewage (nước thải) → Đúng: sewage flows into the sewer.", u: "Môi trường đô thị: raw sewage, sewage treatment, sewage system overflows when it floods.", f: "sewer (n), sewerage (n, hệ thống cống), wastewater (n), drainage (n)" },
  "recycling": { m: "re- (lại) + cycle (vòng) → đưa đồ cũ quay lại vòng sản xuất → tái chế.", e: "Sai: recycle the waste to new products → Đúng: recycle waste into new products. Sai: do the recycle → Đúng: do the recycling.", u: "IELTS Speaking/Writing: recycling bins, encourage recycling, reduce-reuse-recycle. Môi trường: recycling rate.", f: "recycle (v), recyclable (adj), recycled (adj), reuse (v), upcycling (n)" },
  "waste management": { m: "quản lý waste từ thu gom, phân loại, tái chế đến xử lý cuối cùng.", e: "Sai: manage of waste → Đúng: waste management. Sai: wastes management → Đúng: waste management.", u: "Môi trường, đô thị: solid waste management, landfill, waste sorting at source. IELTS Writing: giải pháp cho rác thải.", f: "waste (n/v), landfill (n), incineration (n), sorting (n), recycling (n)" },
  "microplastic": { m: "micro- (cực nhỏ) + plastic → mảnh nhựa nhỏ hơn 5 mm, vào cả cá và nước uống.", e: "Sai: micro plastics → Đúng: microplastics. Sai: microplastic are found → Đúng: microplastics are found.", u: "Môi trường biển, IELTS Writing: microplastics in oceans, food chain, ban microbeads in cosmetics.", f: "microplastics (n, pl), plastic (n), microbead (n), nanoplastic (n), plastic pollution" },
  "single-use plastic": { m: "single-use (dùng một lần) → ống hút, túi nilon dùng xong vứt ngay.", e: "Sai: one-time use plastic → Đúng: single-use plastic. Sai: single use plastics bags → Đúng: single-use plastic bags.", u: "IELTS Speaking/Writing: ban single-use plastics, plastic straws, reusable alternatives. Chính sách môi trường Việt Nam.", f: "disposable (adj), reusable (adj), plastic waste, plastic ban, throwaway (adj)" },
  "biodegradable": { m: "bio (sinh vật) + degrade (phân rã) + -able → vi sinh vật phân hủy được.", e: "Sai: biodegradable plastic disappear fast → Đúng: it may still take years to decompose. Sai: bio-degradeable → Đúng: biodegradable.", u: "Môi trường, bao bì: biodegradable packaging, biodegradable bags. IELTS Writing: thay thế nhựa truyền thống.", f: "biodegrade (v), biodegradation (n), compostable (adj), non-biodegradable (adj), decompose (v)" },
  "compost": { m: "com- (cùng) + post (đặt) → đặt rác hữu cơ cùng nhau cho mục → phân ủ.", e: "Sai: make composts from → Đúng: make compost from kitchen waste. Sai: compost the plastic → Đúng: compost food scraps.", u: "Nông nghiệp, IELTS Speaking: home composting, compost bin, organic waste. Môi trường: giảm rác chôn lấp.", f: "compost (v), composting (n), compostable (adj), fertilizer (n), organic waste" },
  "circular economy": { m: "circular (tròn) → vòng tròn khép kín: dùng, tái chế, dùng lại; không bỏ đi.", e: "Sai: circle economy → Đúng: circular economy. Sai: circular economy is only recycling → Đúng: it also includes redesign, reuse and repair.", u: "Chính sách môi trường, IELTS Writing: shift to a circular economy, linear 'take-make-dispose' model.", f: "circular (adj), linear economy (trái nghĩa), recycling (n), reuse (n), sustainability (n)" },
  "sustainability": { m: "sustain (duy trì) + -able + -ity → duy trì được lâu dài mà không làm cạn tài nguyên.", e: "Sai: sustainable development's → Đúng: sustainable development. Sai: sustainability of environment friendly → Đúng: environmental sustainability.", u: "IELTS Writing, ESG doanh nghiệp: environmental sustainability, sustainability report, sustainable development goals (SDGs).", f: "sustain (v), sustainable (adj), sustainably (adv), unsustainable (adj), SDGs" },
  "habitat loss": { m: "habitat (nơi ở, gốc 'habit' = cư trú) + loss → động vật mất chỗ sống.", e: "Sai: habitats lose → Đúng: habitat loss. Sai: animals lost habitat because deforestation → Đúng: because of deforestation.", u: "Sinh thái, IELTS Writing: habitat loss due to deforestation and urbanization threatens wildlife.", f: "habitat (n), habitation (n), habitat destruction, deforestation (n), biodiversity loss" },
  "endangered species": { m: "en- + danger → bị đặt vào nguy hiểm → loài đứng trước nguy cơ tuyệt chủng.", e: "Sai: endangered specie → Đúng: endangered species (số ít và nhiều giống nhau). Sai: dangerous species → Đúng: endangered species.", u: "IELTS Speaking/Writing: protect endangered species, poaching, saola và voọc ở Việt Nam, IUCN Red List.", f: "endanger (v), extinct (adj), extinction (n), threatened species, wildlife (n)" },
  "reforestation": { m: "re- (lại) + forest (rừng) + -ation → trồng lại rừng ở nơi bị chặt.", e: "Sai: reforest of land → Đúng: reforestation of land. Nhầm afforestation (trồng rừng nơi chưa từng có) với reforestation.", u: "Môi trường, IELTS Writing: reforestation programs, combat deforestation, plant mangroves to protect coasts.", f: "reforest (v), afforestation (n), deforestation (n), forest (n), tree planting" },
  "desertification": { m: "desert (sa mạc) + -ify (biến thành) + -ation → đất bị biến thành sa mạc.", e: "Sai: desertation → Đúng: desertification. Sai: desert hóa → Đúng: desertification.", u: "Môi trường, IELTS Writing: overgrazing and drought cause desertification; Sahel; Ninh Thuận đối mặt sa mạc hóa.", f: "desert (n), desertify (v), land degradation, drought (n), aridity (n)" },
  "soil erosion": { m: "erode (gặm mòn) → mưa gió 'gặm' lớp đất mặt trôi đi → xói mòn đất.", e: "Sai: soil erode → Đúng: soil erosion. Sai: erosion of the soils → Đúng: soil erosion.", u: "Nông nghiệp, môi trường: prevent soil erosion, terraces, deforestation on slopes. IELTS Writing Task 1: quy trình.", f: "erode (v), erosion (n), erosive (adj), landslide (n), land degradation" },
  "saltwater intrusion": { m: "intrude (xâm phạm) → nước mặn 'xâm' sâu vào sông, đất liền.", e: "Sai: salt water intrude → Đúng: saltwater intrusion. Sai: salty intrusion → Đúng: saltwater / salinity intrusion.", u: "Môi trường Việt Nam: saltwater intrusion in the Mekong Delta harms rice crops; drought and sea level rise.", f: "intrude (v), intrusion (n), salinization (n), salinity (n), salinity intrusion" },
  "sea level rise": { m: "sea level (mực nước biển) + rise (dâng) → băng tan, nước nở ra làm biển dâng cao.", e: "Sai: sea level raise → Đúng: sea level rise. Sai: sea levels are raising → Đúng: sea levels are rising.", u: "IELTS Writing, môi trường: rising sea levels threaten coastal cities, Mekong Delta flooding, climate adaptation.", f: "rise (n/v), rising sea levels, coastal flooding, inundation (n), climate change" },
  "extreme weather": { m: "extreme (cực đoan) → thời tiết vượt mức bình thường: bão mạnh, hạn hán, mưa lớn.", e: "Sai: extreme weathers → Đúng: extreme weather (không đếm được). Sai: extremely weather → Đúng: extreme weather.", u: "IELTS Writing/Speaking: extreme weather events are more frequent due to climate change; storms, floods, heatwaves.", f: "extreme (adj/n), extremely (adv), extreme weather event, severe weather, natural disaster" },
  "natural disaster": { m: "disaster (dis- xấu + aster ngôi sao) → 'sao xấu' từ thiên nhiên → thiên tai.", e: "Sai: nature disaster → Đúng: natural disaster. Sai: a natural disasters → Đúng: a natural disaster.", u: "IELTS Writing, Speaking: prepare for natural disasters, floods, typhoons in central Vietnam, disaster relief.", f: "disaster (n), disastrous (adj), catastrophe (n), calamity (n), disaster relief" },
  "heatwave": { m: "heat (nóng) + wave (đợt sóng) → 'đợt sóng' nóng kéo dài nhiều ngày.", e: "Sai: heat waves weather → Đúng: a heatwave / heat wave. Sai: the heatwave is happen → Đúng: a heatwave is happening.", u: "IELTS Speaking: summer heatwaves, heatstroke risk. Môi trường: record-breaking heatwave in Europe, more frequent heatwaves.", f: "heat wave, heatstroke (n), heat (n/v), scorching (adj), extreme heat" },
  "adaptation": { m: "adapt (thích nghi, ad- + apt hợp) → làm cho phù hợp với điều kiện mới.", e: "Sai: adaption → Đúng: adaptation. Sai: adapt with climate → Đúng: adapt to climate change.", u: "Khí hậu, IELTS Writing: climate adaptation vs. mitigation, adaptation measures like sea walls, drought-resistant crops.", f: "adapt (v), adaptive (adj), adaptable (adj), adaptability (n), adjustment (n)" },
  "mitigation": { m: "mitig- (làm dịu, như 'mild') → làm dịu, giảm nhẹ nguyên nhân gây hại.", e: "Sai: mitigate of risks → Đúng: mitigation of risks / mitigate risks. Sai: mitigation = thích ứng → Đúng: mitigation giảm nguyên nhân.", u: "Khí hậu: climate mitigation cuts emissions; risk mitigation trong quản lý dự án. IELTS Writing học thuật.", f: "mitigate (v), mitigating (adj), alleviation (n), reduction (n), adaptation (n)" },
  "resilience": { m: "resile (bật lại) → như lò xo bị nén vẫn bật lại → khả năng chống chịu, phục hồi.", e: "Sai: resilient of the city → Đúng: the resilience of the city. Sai: resilence → Đúng: resilience.", u: "Khí hậu, đô thị: climate resilience, build resilience to floods. IELTS Speaking: resilience khi nói về tính cách.", f: "resilient (adj), resiliently (adv), robustness (n), recovery (n), adaptability (n)" },
  "environmental impact assessment": { m: "assess (đánh giá) impact (tác động) lên môi trường trước khi xây dự án → ĐTM.", e: "Sai: environment impact assessment → Đúng: environmental impact assessment (EIA). Sai: assess environmental after building → Đúng: before approval.", u: "Luật môi trường, xây dựng: conduct an EIA, EIA report approval, public consultation before major projects.", f: "EIA, assess (v), assessment (n), impact (n), environmental (adj)" },
  "ozone layer": { m: "ozone (O3) → lớp 'kem chống nắng' của Trái Đất chặn tia cực tím.", e: "Sai: ozone class → Đúng: ozone layer. Sai: ozone hole causes global warming → Đúng: ozone depletion and global warming are different.", u: "Khoa học, IELTS Reading/Writing: depletion of the ozone layer, CFCs, Montreal Protocol, UV radiation.", f: "ozone (n), ozone depletion, CFCs, ultraviolet (UV) radiation, stratosphere (n)" },
  "ocean acidification": { m: "ocean hấp thụ CO2 → nước biển chua hơn (acid hóa), làm mòn vỏ sò, san hô.", e: "Sai: ocean acidify → Đúng: ocean acidification. Sai: acidization of ocean → Đúng: ocean acidification.", u: "Sinh thái biển, IELTS Reading: ocean acidification threatens coral reefs and shellfish; linked to CO2 absorption.", f: "acid (n), acidic (adj), acidify (v), acidity (n), pH (n)" },
  "coral bleaching": { m: "bleach (tẩy trắng) → nước nóng làm san hô đẩy tảo ra, mất màu, trắng bệch.", e: "Sai: coral bleach event → Đúng: coral bleaching event. Sai: corals are bleached because of chemicals → Đúng: mainly because of warmer water.", u: "Sinh thái biển: mass coral bleaching on the Great Barrier Reef, rising sea temperatures, reef recovery.", f: "bleach (v/n), coral reef (n), bleached (adj), ocean warming, ocean acidification" },
  "glacier": { m: "glaci- (băng giá, như 'glacial') → khối băng khổng lồ chậm chạp trôi xuống thung lũng → sông băng.", e: "Sai: đọc 'gla-xi-ơ' sai trọng âm → Đúng: /ˈɡleɪʃər/ (Mỹ). Sai: glaciers is melting → Đúng: glaciers are melting.", u: "Khí hậu, IELTS Writing: melting glaciers contribute to sea level rise, glacial retreat in the Himalayas.", f: "glacial (adj), glaciation (n), ice sheet, iceberg (n), ice cap (n)" },
  "permafrost": { m: "perma(nent) (vĩnh viễn) + frost (băng giá) → đất đóng băng quanh năm.", e: "Sai: permanent frost → Đúng: permafrost. Sai: permafrosts are thawing → Đúng: permafrost is thawing.", u: "Khí hậu: thawing permafrost releases methane, Arctic permafrost, feedback loop speeding up warming.", f: "frost (n), thaw (v), Arctic (adj), tundra (n), frozen ground" },
  "water scarcity": { m: "scarce (khan hiếm) + -ity → tình trạng không đủ nước sạch cho nhu cầu.", e: "Sai: water scarce problem → Đúng: water scarcity. Sai: scarcity of waters → Đúng: scarcity of water.", u: "IELTS Writing Task 2: water scarcity in developing countries, drought, solutions like rainwater harvesting.", f: "scarce (adj), scarcity (n), water shortage, drought (n), water stress" },
  "groundwater": { m: "ground (đất) + water → nước tích trong các tầng đất đá dưới lòng đất → nước ngầm.", e: "Sai: underground waters → Đúng: groundwater (không đếm được). Sai: ground water level downs → Đúng: the groundwater level is falling.", u: "Môi trường: groundwater depletion, over-extraction causes land subsidence in Hà Nội and Mekong Delta, aquifer.", f: "aquifer (n), well (n), surface water, water table, subsidence (n)" },
  "watershed": { m: "water + shed (đổ ra): vùng đất nơi mọi giọt mưa đổ về cùng một dòng sông → lưu vực.", e: "Sai: the watershed of river Mekong → Đúng: the Mekong River watershed. Nghĩa bóng 'bước ngoặt': a watershed moment.", u: "Ngành môi trường: watershed management, watershed protection, đánh giá ô nhiễm trong lưu vực. IELTS Writing: 'a watershed moment in history'.", f: "watershed (n), catchment area (n, đồng nghĩa), river basin (n), drainage basin (n)" },
  "wetland": { m: "wet (ướt) + land (đất) → vùng đất luôn ướt sũng: đầm lầy, bãi bồi, rừng tràm.", e: "Sai: a wet land area → Đúng: a wetland. Thường dùng số nhiều: Sai: protect wetland → Đúng: protect wetlands.", u: "Ngành môi trường: wetland conservation, Ramsar wetlands (Tràm Chim, Xuân Thủy). IELTS Writing: wetlands act as natural flood barriers.", f: "wetland (n), wetlands (n, số nhiều), marsh (n), swamp (n), peatland (n)" },
  "mangrove": { m: "Hình ảnh rừng đước Cà Mau: rễ chống như cà kheo cắm xuống bùn nước mặn.", e: "Sai: mangrove forest are disappearing → Đúng: mangrove forests are disappearing. Sai: a mangroves → Đúng: a mangrove.", u: "Ngành môi trường: mangrove restoration, coastal protection, carbon xanh (blue carbon). IELTS Writing: mangroves reduce storm surge damage.", f: "mangrove (n), mangrove forest (n), mangrove swamp (n), blue carbon (n)" },
  "invasive species": { m: "invade (xâm chiếm) → invasive: loài ngoại lai xâm chiếm, lấn át loài bản địa, như ốc bươu vàng.", e: "Sai: an invasive specie → Đúng: an invasive species. 'Species' số ít và số nhiều giống nhau.", u: "Ngành môi trường: control invasive species, biosecurity, đánh giá rủi ro sinh thái. IELTS Writing: invasive species threaten native biodiversity.", f: "invade (v), invasion (n), invasive (adj), alien species (n), native species (n, trái nghĩa)" },
  "photosynthesis": { m: "photo (ánh sáng) + synthesis (tổng hợp) → dùng ánh sáng tổng hợp đường từ CO₂ và nước.", e: "Sai: plants do photosynthesis at night → Đúng: plants carry out photosynthesis in daylight. Sai: photosynthetis → Đúng: photosynthesis.", u: "Ngành sinh học – môi trường: rates of photosynthesis, chlorophyll, hấp thụ carbon. IELTS Reading/Writing: describe how forests absorb CO₂ through photosynthesis.", f: "photosynthesis (n), photosynthesize (v), photosynthetic (adj), chlorophyll (n)" },
  "carbon cycle": { m: "cycle = vòng tròn: carbon đi từ không khí → cây → động vật → đất → trở lại không khí.", e: "Sai: the cycle of carbons → Đúng: the carbon cycle. Sai: carbon cycle is disrupted → Đúng: the carbon cycle is disrupted.", u: "Ngành khí hậu: carbon sinks, carbon fluxes, mô hình hóa chu trình carbon. IELTS Writing: burning fossil fuels disrupts the carbon cycle.", f: "carbon cycle (n), carbon sink (n), carbon emissions (n), nitrogen cycle (n)" },
  "water cycle": { m: "Nước bốc hơi → ngưng tụ thành mây → mưa rơi → chảy về biển: một vòng khép kín.", e: "Sai: the circle of water → Đúng: the water cycle. Sai: water cycle have four stages → Đúng: the water cycle has four stages.", u: "IELTS Writing Task 1: process diagram về evaporation, condensation, precipitation. Ngành thủy văn: thay đổi vòng tuần hoàn nước do khí hậu.", f: "water cycle (n), hydrological cycle (n, thuật ngữ), evaporation (n), precipitation (n)" },
  "organism": { m: "organ (cơ quan) + -ism → thực thể có các cơ quan sống: từ vi khuẩn đến con voi.", e: "Sai: living organisms is everywhere → Đúng: living organisms are everywhere. Đừng nhầm với 'orgasm'; phát âm /ˈɔːɡənɪzəm/.", u: "Ngành sinh học – môi trường: microorganisms, genetically modified organisms (GMOs). IELTS Writing: pollution harms aquatic organisms.", f: "organism (n), microorganism (n), organic (adj), organ (n), GMO (n)" },
  "genetic diversity": { m: "gene khác nhau trong cùng loài như bộ bài nhiều quân → loài dễ thích nghi, khó bị diệt.", e: "Sai: diversity of genetic → Đúng: genetic diversity. Sai: a genetic diversity is low → Đúng: genetic diversity is low.", u: "Ngành bảo tồn: maintain genetic diversity, gene bank, giống cây trồng bản địa. IELTS Writing: inbreeding reduces genetic diversity in endangered species.", f: "genetic (adj), gene (n), genetics (n), biodiversity (n), species diversity (n)" },
  "natural selection": { m: "Thiên nhiên 'chọn lọc' như người chọn giống: cá thể thích nghi tốt sống sót, sinh sản nhiều hơn.", e: "Sai: the nature selection → Đúng: natural selection (không mạo từ). Sai: natural selection is 'mạnh nhất sống sót' → đúng hơn: phù hợp nhất.", u: "Ngành sinh học: Darwin's theory, adaptation, evolution. IELTS Reading: bài về tiến hóa; Writing: explain antibiotic resistance via natural selection.", f: "natural selection (n), evolution (n), adaptation (n), survival of the fittest (phrase)" },
  "dna": { m: "Viết tắt deoxyribonucleic acid: 'bản thiết kế' xoắn kép chứa thông tin di truyền của mọi sinh vật.", e: "Sai: the DNAs of him → Đúng: his DNA. DNA thường không đếm được; viết hoa: DNA, không viết 'dna'.", u: "Ngành sinh học – môi trường: environmental DNA (eDNA), DNA sequencing, DNA testing. IELTS Speaking: 'It's in my DNA' = bản chất của tôi.", f: "DNA (n), RNA (n), gene (n), genome (n), chromosome (n)" },
  "molecule": { m: "Nhỏ hơn hạt bụi, lớn hơn nguyên tử: nhiều atom nắm tay nhau tạo thành molecule, như H₂O.", e: "Sai: a molecule of water have three atoms → Đúng: a water molecule has three atoms. Phát âm /ˈmɒlɪkjuːl/.", u: "Ngành hóa – môi trường: greenhouse gas molecules, molecular structure. IELTS Reading: bài khoa học về CO₂ molecules trapping heat.", f: "molecule (n), molecular (adj), atom (n), compound (n), molecular biology (n)" },
  "atom": { m: "Gốc Hy Lạp a-tomos = không thể cắt → hạt nhỏ nhất người xưa tưởng không chia được.", e: "Sai: atom of carbon is small → Đúng: a carbon atom is tiny. Tính từ: atomic, không phải 'atomical'.", u: "Ngành vật lý – năng lượng: atomic energy, splitting the atom. IELTS Reading: bài lịch sử khoa học về cấu trúc nguyên tử.", f: "atom (n), atomic (adj), atomic bomb (n), nucleus (n), electron (n)" },
  "chemical reaction": { m: "Chất A gặp chất B 'phản ứng' như hai người gặp nhau → sinh ra chất mới hoàn toàn.", e: "Sai: make a chemical reaction → Đúng: cause/trigger a chemical reaction. Sai: chemistry reaction → Đúng: chemical reaction.", u: "Ngành hóa – môi trường: reactions forming acid rain, ozone depletion. IELTS Writing Task 1: process diagrams có bước chemical reaction.", f: "chemical (adj/n), chemistry (n), react (v), reaction (n), reactant (n), product (n)" },
  "catalyst": { m: "Người mai mối đám cưới: giúp phản ứng xảy ra nhanh nhưng bản thân không đổi.", e: "Sai: catalyst of change → Đúng: a catalyst for change. Sai: catalysis (quá trình) dùng thay catalyst (chất).", u: "Ngành hóa – môi trường: catalytic converters giảm khí thải xe. IELTS Writing: 'The internet acted as a catalyst for globalisation.'", f: "catalyst (n), catalyse/catalyze (v), catalysis (n), catalytic (adj), catalytic converter (n)" },
  "velocity": { m: "veloc- (nhanh, như 'velociraptor' – kẻ cướp nhanh) → tốc độ có hướng: vận tốc.", e: "Sai: velocity of 50 km → Đúng: a velocity of 50 km/h. Velocity có hướng, speed không; đừng dùng lẫn trong bài vật lý.", u: "Ngành vật lý – môi trường: wind velocity, flow velocity của sông. Kinh doanh: 'velocity of money', sales velocity.", f: "velocity (n), speed (n), accelerate (v), acceleration (n), high-velocity (adj)" },
  "radiation": { m: "radi- (tia, như radius bán kính) → năng lượng tỏa ra theo tia từ một tâm.", e: "Sai: radiations from phone → Đúng: radiation from phones (không đếm được). Sai: be radiated → Đúng: be exposed to radiation.", u: "Ngành năng lượng – y tế: radiation exposure, solar radiation, UV radiation. IELTS Writing: concerns about radiation from nuclear plants.", f: "radiate (v), radiation (n), radiant (adj), radioactive (adj), radioactivity (n)" },
  "nuclear energy": { m: "nucleus (hạt nhân) → nuclear: năng lượng lấy từ việc tách hạt nhân nguyên tử.", e: "Sai: nuclear energies → Đúng: nuclear energy (không đếm được). Phát âm /ˈnjuːkliə/, không phải 'nu-cu-lar'.", u: "IELTS Writing Task 2: pros and cons of nuclear energy, low emissions vs waste. Ngành năng lượng: nuclear power plant, reactor safety.", f: "nuclear (adj), nucleus (n), nuclear power (n), nuclear plant (n), nuclear waste (n)" },
  "control group": { m: "Nhóm 'đứng yên để so sánh': không nhận thuốc/tác động, làm mốc đối chiếu với nhóm thí nghiệm.", e: "Sai: the controlled group → Đúng: the control group. Sai: compare with control group → Đúng: compare with the control group.", u: "Ngành nghiên cứu khoa học: experimental group vs control group, randomized controlled trial. IELTS Reading: bài thí nghiệm hay hỏi chi tiết này.", f: "control group (n), experimental group (n), controlled experiment (n), placebo (n)" },
  "specimen": { m: "speci- (nhìn, như 'spectacle') → vật mẫu được giữ lại để nhìn, nghiên cứu.", e: "Sai: collect many specimen → Đúng: collect many specimens. Phát âm /ˈspesɪmən/, nhấn âm đầu.", u: "Ngành sinh học – môi trường: collect water specimens, museum specimens, label specimens. Y tế: blood specimen, urine specimen.", f: "specimen (n), specimens (n, số nhiều), sample (n, gần nghĩa), species (n, cùng gốc)" },
  "scientific method": { m: "Công thức 5 bước: quan sát → giả thuyết → thí nghiệm → phân tích → kết luận.", e: "Sai: the science method → Đúng: the scientific method. Sai: follow scientific method → Đúng: follow the scientific method.", u: "Ngành nghiên cứu: apply the scientific method, hypothesis testing. IELTS Reading: bài về lịch sử khoa học; Speaking: chủ đề science.", f: "scientific (adj), science (n), scientist (n), scientifically (adv), hypothesis (n)" },
  "empirical evidence": { m: "empirical = dựa trên trải nghiệm, quan sát thực tế → bằng chứng đo được, không phải suy đoán.", e: "Sai: an empirical evidence → Đúng: empirical evidence (không đếm được). Sai: empiric evidence → Đúng: empirical evidence.", u: "IELTS Writing Task 2: 'There is little empirical evidence that...'. Ngành nghiên cứu môi trường: empirical data, field observations.", f: "empirical (adj), empirically (adv), empiricism (n), evidence (n), evidence-based (adj)" },
  "climate model": { m: "Trái Đất thu nhỏ trong máy tính: mô phỏng không khí, đại dương để dự báo khí hậu tương lai.", e: "Sai: climate models predicts → Đúng: climate models predict. Sai: weather model (dự báo ngày) dùng thay climate model.", u: "Ngành khí hậu: run climate models, projections, IPCC scenarios. IELTS Writing: 'Climate models project sea levels to rise significantly.'", f: "climate model (n), climate modelling (n), projection (n), simulation (n), scenario (n)" },
  "typhoon": { m: "Bão Tây Thái Bình Dương (đổ vào Việt Nam) gọi typhoon; ở Đại Tây Dương gọi hurricane.", e: "Sai: the typhoon hit to Vietnam → Đúng: the typhoon hit Vietnam. Sai: a strong storm typhoon → Đúng: a powerful typhoon.", u: "Ngành môi trường – thiên tai: typhoon season, early warning, evacuation. IELTS Speaking: describe a natural disaster you experienced.", f: "typhoon (n), hurricane (n), cyclone (n), tropical storm (n), storm surge (n)" },
  "flash flood": { m: "flash = chớp nhoáng → lũ đến nhanh như tia chớp sau mưa lớn, thường ở vùng núi.", e: "Sai: a sweep flood → Đúng: a flash flood. Sai: flash flood happened suddenly → Đúng: a flash flood struck suddenly.", u: "Ngành thiên tai: flash flood warning, mountainous areas, deforestation. IELTS Writing: deforestation increases the risk of flash floods.", f: "flash flood (n), flood (n/v), flooding (n), landslide (n), inundation (n)" },
  "landslide": { m: "land (đất) + slide (trượt) → cả sườn đồi trượt xuống. Nghĩa bóng: thắng áp đảo.", e: "Sai: the land slided → Đúng: there was a landslide. Sai: win by landslide → Đúng: win by a landslide.", u: "Ngành thiên tai: landslide risk mapping, slope stability, heavy rainfall. IELTS Speaking: 'won the election by a landslide'.", f: "landslide (n), landslip (n, Anh), mudslide (n), rockfall (n), landslide victory (n)" },
  "natural resources": { m: "Thứ thiên nhiên 'cho sẵn': nước, rừng, khoáng sản, dầu mỏ → của cải không do người làm ra.", e: "Sai: nature resources → Đúng: natural resources. Sai: Vietnam is rich of natural resources → Đúng: rich in natural resources.", u: "IELTS Writing Task 2: depletion of natural resources, sustainable use. Ngành môi trường: resource management, extraction, quản lý tài nguyên.", f: "natural resource (n), resourceful (adj), resource depletion (n), raw materials (n)" },
  "non-renewable": { m: "non (không) + renew (làm mới) + able → dùng hết là hết, không tự làm mới được: than, dầu.", e: "Sai: unrenewable energy → Đúng: non-renewable energy. Sai: non renewable (thiếu gạch nối) → Đúng: non-renewable.", u: "IELTS Writing Task 2: shift from non-renewable to renewable energy. Ngành năng lượng: non-renewable resources, fossil fuel dependence.", f: "non-renewable (adj), renewable (adj, trái nghĩa), renewables (n), renew (v), fossil fuels (n)" },
  "overfishing": { m: "over (quá) + fishing → đánh bắt nhiều hơn tốc độ cá kịp sinh sản → biển cạn cá.", e: "Sai: over-fish too much (lặp nghĩa) → Đúng: overfishing. Sai: the overfishing are serious → Đúng: overfishing is serious.", u: "Ngành thủy sản – môi trường: fish stocks, fishing quotas, marine reserves. IELTS Writing: overfishing threatens ocean ecosystems and livelihoods.", f: "overfish (v), overfishing (n), overfished (adj), fish stock (n), bycatch (n)" },
  "runoff": { m: "run (chạy) + off (ra khỏi) → nước mưa chạy tràn khỏi mặt đất, cuốn theo phân bón.", e: "Sai: run off water from farms → Đúng: runoff from farms. Danh từ viết liền 'runoff'; động từ tách 'run off'.", u: "Ngành môi trường – nông nghiệp: agricultural runoff, stormwater runoff, ô nhiễm nguồn nước. IELTS Writing: fertiliser runoff pollutes rivers.", f: "runoff (n), run off (phr v), stormwater (n), surface water (n), leaching (n)" },
  "algal bloom": { m: "bloom = nở hoa → tảo 'nở' bùng phát phủ xanh mặt nước, hút cạn oxy.", e: "Sai: algae bloom are toxic → Đúng: algal blooms are toxic. Sai: alga bloom → Đúng: algal bloom.", u: "Ngành môi trường nước: harmful algal blooms, eutrophication, fish kills. IELTS Reading: bài về ô nhiễm hồ do phân bón.", f: "alga (n), algae (n, số nhiều), algal (adj), eutrophication (n), red tide (n)" },
  "organic farming": { m: "organic = hữu cơ, tự nhiên → trồng trọt không thuốc trừ sâu, phân bón hóa học.", e: "Sai: organic farm (khi nói phương pháp) → Đúng: organic farming. Sai: organical food → Đúng: organic food.", u: "IELTS Writing Task 2: is organic farming better for the environment? Ngành nông nghiệp: organic certification, crop yields.", f: "organic (adj), organically (adv), organic farming (n), organic produce (n), conventional farming (n)" },
  "emissions trading": { m: "Hình ảnh chợ: công ty thải ít bán phần 'được thải' còn dư cho công ty thải nhiều.", e: "Sai: emission trade → Đúng: emissions trading. Sai: buy emissions → Đúng: buy emission allowances/credits.", u: "Ngành khí hậu – chính sách: emissions trading scheme (ETS), cap-and-trade, carbon credits. IELTS Writing: market solutions to pollution.", f: "emissions trading (n), cap-and-trade (n), carbon credit (n), emission allowance (n)" },
  "carbon tax": { m: "Thải càng nhiều carbon càng nộp nhiều thuế → 'ai gây ô nhiễm người đó trả tiền'.", e: "Sai: tax of carbon → Đúng: carbon tax. Sai: put carbon tax to companies → Đúng: impose a carbon tax on companies.", u: "IELTS Writing Task 2: should governments impose a carbon tax? Ngành chính sách môi trường: carbon pricing, polluter pays principle.", f: "carbon tax (n), carbon pricing (n), green tax (n), eco-tax (n), polluter pays (phrase)" },
  "environmental regulation": { m: "regulate (điều chỉnh) → luật lệ 'điều chỉnh' hành vi doanh nghiệp để bảo vệ môi trường.", e: "Sai: comply environmental regulations → Đúng: comply with environmental regulations. Sai: strict regulation of environment → Đúng: strict environmental regulations.", u: "Ngành môi trường – pháp chế: compliance, permits, EIA. IELTS Writing: tougher environmental regulations on factories.", f: "regulate (v), regulation (n), regulatory (adj), regulator (n), deregulation (n)" },
  "eco-friendly": { m: "eco (sinh thái) + friendly (thân thiện) → 'làm bạn' với môi trường, không gây hại.", e: "Sai: friendly with environment products → Đúng: eco-friendly products. Sai: more eco friendly (thiếu gạch nối) → Đúng: more eco-friendly.", u: "IELTS Speaking: Do you buy eco-friendly products? Ngành marketing xanh: eco-friendly packaging; cẩn thận greenwashing.", f: "eco-friendly (adj), environmentally friendly (adj), green (adj), sustainable (adj), eco-conscious (adj)" },
  "green technology": { m: "green = xanh, sạch → công nghệ giúp giảm ô nhiễm: pin mặt trời, xử lý nước thải.", e: "Sai: technology green → Đúng: green technology. Sai: a green technologies → Đúng: green technologies.", u: "IELTS Writing Task 2: investing in green technology to tackle climate change. Ngành năng lượng: cleantech startups, green innovation.", f: "green technology (n), clean technology/cleantech (n), green tech (n), green innovation (n)" },
  "electric vehicle": { m: "electric = chạy điện → xe dùng pin thay xăng; viết tắt EV, như VinFast VF.", e: "Sai: electrical vehicle → Đúng: electric vehicle. Sai: charge an EV's battery at gas station → Đúng: at a charging station.", u: "IELTS Writing/Speaking: should cities promote electric vehicles? Ngành ô tô – năng lượng: EV charging infrastructure, battery range.", f: "electric vehicle/EV (n), electric car (n), hybrid (n), charging station (n), electrify (v)" },
  "energy storage": { m: "storage = kho chứa → 'cất' điện mặt trời ban ngày vào pin để dùng ban đêm.", e: "Sai: store of energy system → Đúng: energy storage system. Sai: energy storages → Đúng: energy storage (không đếm được).", u: "Ngành năng lượng tái tạo: battery energy storage system (BESS), grid stability. IELTS Writing: storage solves solar intermittency.", f: "store (v), storage (n), energy storage system (n), battery (n), grid (n)" },
  "life cycle assessment": { m: "Theo dõi sản phẩm 'từ nôi đến mộ': khai thác, sản xuất, sử dụng, vứt bỏ → đo tác động.", e: "Sai: life circle assessment → Đúng: life cycle assessment. Sai: do LCA for → Đúng: conduct an LCA of a product.", u: "Ngành môi trường – sản xuất: conduct an LCA, cradle-to-grave, carbon footprint của sản phẩm. Báo cáo ESG.", f: "life cycle assessment/LCA (n), life cycle analysis (n), cradle-to-grave (adj), carbon footprint (n)" },
  "ecological footprint": { m: "Dấu chân in trên đất: mỗi người 'giẫm' lên bao nhiêu diện tích để nuôi lối sống mình.", e: "Sai: reduce ecological foot print → Đúng: reduce our ecological footprint. Sai: make footprint smaller → Đúng: shrink/reduce your footprint.", u: "IELTS Writing Task 2: individuals should reduce their ecological footprint. Ngành môi trường: global hectares, sustainability indicators.", f: "ecological footprint (n), carbon footprint (n), ecology (n), ecological (adj), ecologically (adv)" },
  "carrying capacity": { m: "Như chiếc thuyền chỉ 'chở' được số người nhất định → môi trường chỉ nuôi nổi bấy nhiêu cá thể.", e: "Sai: carry capacity → Đúng: carrying capacity. Sai: exceed the capacity carrying → Đúng: exceed the carrying capacity.", u: "Ngành sinh thái – du lịch: carrying capacity of an island, tourist numbers. IELTS Writing: overpopulation exceeding carrying capacity.", f: "carrying capacity (n), capacity (n), overpopulation (n), overcapacity (n), sustainable limit (n)" },
  "indicator species": { m: "indicator = đèn báo → loài như 'đèn báo' sức khỏe môi trường; ví dụ địa y báo không khí sạch.", e: "Sai: an indicator specie → Đúng: an indicator species. Sai: indicate species → Đúng: indicator species.", u: "Ngành sinh thái – quan trắc: frogs and lichens as indicator species. IELTS Reading: bài về đo ô nhiễm qua sinh vật.", f: "indicate (v), indicator (n), bioindicator (n), keystone species (n), flagship species (n)" },
  "bioaccumulation": { m: "bio (sinh vật) + accumulate (tích tụ) → chất độc dồn dần trong cơ thể, nhất là cá lớn.", e: "Sai: bio-accumulate of mercury → Đúng: bioaccumulation of mercury. Đừng nhầm với biomagnification (khuếch đại qua chuỗi thức ăn).", u: "Ngành độc học môi trường: mercury in fish, pesticides, food chain. IELTS Reading: bài về DDT và chim săn mồi.", f: "bioaccumulate (v), bioaccumulation (n), bioaccumulative (adj), biomagnification (n)" },
  "environmental monitoring": { m: "monitor = màn hình theo dõi → 'canh chừng' không khí, nước, đất bằng đo đạc định kỳ.", e: "Sai: monitor of environment → Đúng: environmental monitoring. Sai: do monitoring the air → Đúng: monitor air quality.", u: "Ngành môi trường: monitoring stations, air quality index, báo cáo quan trắc. IELTS Writing: governments should invest in environmental monitoring.", f: "monitor (v/n), monitoring (n), monitoring station (n), surveillance (n), sampling (n)" },
  "remote sensing": { m: "remote (từ xa) + sensing (cảm nhận) → 'nhìn' Trái Đất từ vệ tinh, máy bay mà không chạm tới.", e: "Sai: far sensing → Đúng: remote sensing. Sai: remote sensing data shows → Đúng: remote sensing data show/shows (đều chấp nhận).", u: "Ngành môi trường – GIS: satellite imagery, deforestation mapping, flood monitoring. IELTS Reading: bài về công nghệ vệ tinh.", f: "remote sensing (n), sensor (n), satellite imagery (n), GIS (n), drone survey (n)" },
  "protected area": { m: "protect (bảo vệ) → vùng 'rào' lại bằng luật để giữ thiên nhiên, như vườn quốc gia Cúc Phương.", e: "Sai: protection area → Đúng: protected area. Sai: hunt in protected area → Đúng: hunt in a protected area.", u: "Ngành bảo tồn: marine protected areas (MPAs), national parks, buffer zones. IELTS Writing: expand protected areas to save wildlife.", f: "protected area (n), national park (n), nature reserve (n), wildlife sanctuary (n), buffer zone (n)" },
  "urban heat island": { m: "Thành phố bê tông như 'hòn đảo nóng' giữa vùng quê mát mẻ xung quanh.", e: "Sai: urban hot island → Đúng: urban heat island. Sai: heat island effect of urban → Đúng: the urban heat island effect.", u: "Ngành quy hoạch đô thị: green roofs, urban trees giảm nhiệt. IELTS Writing Task 2: urbanisation and the urban heat island effect.", f: "urban heat island (n), UHI effect (n), urbanisation (n), green roof (n), heatwave (n)" },
  "aquifer": { m: "aqua (nước) + -fer (mang, như 'transfer') → lớp đá 'mang' nước dưới lòng đất.", e: "Sai: aquifier → Đúng: aquifer. Sai: water from underground aquifer → Đúng: water from an underground aquifer.", u: "Ngành thủy văn: groundwater depletion, aquifer recharge, sụt lún ĐBSCL. IELTS Writing: over-extraction of aquifers causes land subsidence.", f: "aquifer (n), groundwater (n), water table (n), recharge (n/v), aqua (gốc: nước)" },
  "booking": { m: "book (sổ) → ghi tên khách vào sổ trước → đặt chỗ, đặt phòng.", e: "Sai: make a book for two nights → Đúng: make a booking for two nights. Sai: booking a room on internet → Đúng: book a room online.", u: "Lễ tân: confirm/amend/cancel a booking, booking reference. TOEIC Part 3, 7: email xác nhận đặt phòng, đổi ngày.", f: "book (v), booking (n), booked (adj), reservation (n, đồng nghĩa), rebook (v)" },
  "check-in": { m: "Khách 'đánh dấu có mặt' (check) khi bước vào (in) khách sạn → nhận phòng.", e: "Sai: check-in at the hotel (động từ) → Đúng: check in at the hotel. Danh từ có gạch nối: check-in time is 2 p.m.", u: "Lễ tân: check-in time, early check-in, online check-in. TOEIC Part 2, 3: hỏi giờ nhận phòng, giấy tờ cần mang.", f: "check in (phr v), check-in (n/adj), check-in counter (n), early check-in (n), check-out (n)" },
  "check-out": { m: "check (kiểm hóa đơn) + out (ra) → thanh toán, trả chìa khóa rồi rời khách sạn.", e: "Sai: I will check-out at noon → Đúng: I will check out at noon. Danh từ: late check-out is available.", u: "Lễ tân: late check-out, express check-out, settle the bill. TOEIC Part 7: thông báo giờ trả phòng, phí trả muộn.", f: "check out (phr v), check-out (n), checkout (n, Mỹ), late check-out (n), express check-out (n)" },
  "front desk": { m: "Cái bàn (desk) ở phía trước (front) sảnh → nơi khách gặp đầu tiên: quầy lễ tân.", e: "Sai: ask at the reception desk front → Đúng: ask at the front desk. Sai: call to front desk → Đúng: call the front desk.", u: "Khách sạn: front desk agent, front desk operations, 24-hour front desk. TOEIC Part 1, 3: hội thoại tại quầy lễ tân.", f: "front desk (n), reception (n), receptionist (n), front desk agent (n), front office (n)" },
  "bellboy": { m: "Ngày xưa khách rung chuông (bell) gọi cậu bé (boy) mang vali lên phòng.", e: "Sai: give the bellboy a tips → Đúng: give the bellboy a tip. Lịch sự, trung tính hơn: bellhop, porter, bell attendant.", u: "Khách sạn: bell desk, luggage assistance, escort guests to rooms. TOEIC Part 1: tranh nhân viên đẩy xe hành lý.", f: "bellboy (n), bellhop (n, Mỹ), porter (n), bell attendant (n), bell desk (n)" },
  "housekeeping": { m: "keep the house (giữ nhà sạch) → bộ phận giữ cho mọi phòng gọn gàng, sạch sẽ.", e: "Sai: call housekeeper department → Đúng: call housekeeping. Sai: housekeepings → Đúng: housekeeping (không đếm được).", u: "Khách sạn: housekeeping department, executive housekeeper, room status report. TOEIC Part 4: thông báo lịch dọn phòng.", f: "housekeeping (n), housekeeper (n), executive housekeeper (n), room attendant (n)" },
  "room attendant": { m: "attend (phục vụ, chăm lo) → người chăm lo từng phòng: dọn giường, thay khăn, bổ sung đồ.", e: "Sai: room attender → Đúng: room attendant. Sai: the room attendant cleaned my room yesterday night → Đúng: last night.", u: "Bộ phận buồng: room attendant checklist, cleaning 14 rooms per shift. TOEIC Part 7: tin tuyển dụng nhân viên dọn phòng.", f: "attend (v), attendant (n), room attendant (n), chambermaid (n, cũ), housekeeper (n)" },
  "single room": { m: "single = một → phòng dành cho một người, thường một giường đơn.", e: "Sai: a room single → Đúng: a single room. Sai: book one single → Đúng: book a single room.", u: "Lễ tân: room types, single supplement khi đi tour một mình. TOEIC Part 3: khách hỏi giá phòng đơn và phòng đôi.", f: "single room (n), single occupancy (n), single supplement (n), double room (n), twin room (n)" },
  "double room": { m: "double = gấp đôi → phòng cho hai người dùng chung một giường lớn.", e: "Nhầm: double room = hai giường → Đúng: double room = một giường đôi; hai giường đơn là twin room.", u: "Lễ tân: double occupancy, upgrade a double room. TOEIC Part 3: khách đặt nhầm loại phòng, nhân viên xử lý.", f: "double room (n), double bed (n), double occupancy (n), twin room (n), king room (n)" },
  "twin room": { m: "twin = sinh đôi → hai chiếc giường đơn giống hệt nhau đặt cạnh nhau.", e: "Sai: twins room → Đúng: twin room. Sai: twin room has one big bed → Đúng: a twin room has two single beds.", u: "Lễ tân – lữ hành: twin sharing cho đoàn khách, đồng nghiệp đi công tác. TOEIC Part 3: phân biệt twin và double.", f: "twin room (n), twin beds (n), twin share (n), double room (n), triple room (n)" },
  "room rate": { m: "rate = mức giá theo đơn vị → giá phòng tính cho một đêm.", e: "Sai: the room's price per night rate → Đúng: the room rate. Sai: room rate is include breakfast → Đúng: the room rate includes breakfast.", u: "Khách sạn: rack rate, corporate rate, best available rate (BAR). TOEIC Part 7: bảng giá phòng, khuyến mãi mùa thấp điểm.", f: "room rate (n), rate (n), rack rate (n), corporate rate (n), daily rate (n)" },
  "occupancy rate": { m: "occupy (chiếm chỗ) → tỷ lệ phần trăm số phòng 'có người chiếm' trên tổng số phòng.", e: "Sai: occupation rate → Đúng: occupancy rate. Sai: occupancy rate increased to 15% → Đúng: rose by 15 percentage points / to 85%.", u: "Quản lý khách sạn: KPI hàng ngày, so sánh với ADR, RevPAR. IELTS Writing Task 1: biểu đồ tỷ lệ lấp đầy theo tháng.", f: "occupy (v), occupancy (n), occupant (n), occupied (adj), occupancy rate (n)" },
  "fully booked": { m: "fully (hoàn toàn) + booked (đã đặt) → mọi phòng đã có người đặt: hết chỗ.", e: "Sai: the hotel is full booked → Đúng: the hotel is fully booked. Sai: we are fully booking → Đúng: we are fully booked.", u: "Lễ tân: 'I'm sorry, we're fully booked that night.' TOEIC Part 3: khách phải đổi ngày hoặc khách sạn.", f: "fully booked (adj), booked up (adj), sold out (adj), no vacancy (phrase), overbooked (adj)" },
  "overbooking": { m: "over (vượt quá) + booking → nhận đặt nhiều hơn số phòng có, phòng trường hợp khách không đến.", e: "Sai: the hotel overbooked me → Đúng: the hotel was overbooked, so I was moved. Sai: over booking → Đúng: overbooking.", u: "Quản trị doanh thu: overbooking strategy, walk a guest sang khách sạn khác. TOEIC Part 3: khách bị chuyển khách sạn.", f: "overbook (v), overbooking (n), overbooked (adj), walk a guest (phrase), no-show (n)" },
  "no-show": { m: "Khách 'không xuất hiện' (no show) dù đã đặt phòng, không báo hủy.", e: "Sai: the guest was no show → Đúng: the guest was a no-show. Sai: no show fee → Đúng: no-show fee/charge.", u: "Khách sạn – nhà hàng: no-show charge, guaranteed booking, no-show rate. TOEIC Part 7: chính sách thu phí khách không đến.", f: "no-show (n), no-show charge (n), show up (phr v), cancellation (n), guaranteed booking (n)" },
  "cancellation policy": { m: "cancel (hủy) → policy (chính sách): quy định hủy trước bao lâu thì được hoàn tiền.", e: "Sai: cancelation policy (Anh dùng cancellation) → Đúng: cancellation policy. Sai: policy of cancel → Đúng: cancellation policy.", u: "Khách sạn – OTA: free cancellation, non-refundable rate, 48-hour policy. TOEIC Part 7: điều khoản hủy phòng trong email xác nhận.", f: "cancel (v), cancellation (n), cancellation fee (n), non-refundable (adj), refund (n/v)" },
  "room service": { m: "Dịch vụ đến tận phòng (room): gọi điện là món ăn được mang lên.", e: "Sai: order a room service → Đúng: order room service (không mạo từ). Sai: call room service for cleaning → Đúng: call housekeeping.", u: "F&B: 24-hour room service, in-room dining menu, tray pickup. TOEIC Part 2, 3: khách gọi đồ ăn lên phòng.", f: "room service (n), in-room dining (n), room service menu (n), tray (n), order (v)" },
  "amenities": { m: "amen- (dễ chịu, như 'amiable') → những thứ làm kỳ nghỉ dễ chịu: hồ bơi, wifi, dầu gội.", e: "Sai: the hotel has many amenity → Đúng: the hotel has many amenities. Sai: amenities includes → Đúng: amenities include.", u: "Khách sạn: in-room amenities, guest amenities, amenity kit. TOEIC Part 7: quảng cáo khách sạn liệt kê tiện nghi.", f: "amenity (n), amenities (n, số nhiều), facility (n), facilities (n), amenity kit (n)" },
  "minibar": { m: "mini (nhỏ) + bar (quầy rượu) → quầy đồ uống thu nhỏ đặt trong tủ lạnh phòng.", e: "Sai: use things in minibar free → Đúng: minibar items are charged to your room. Sai: mini bar → Đúng: minibar.", u: "Khách sạn: minibar charges, minibar check khi trả phòng, restock. TOEIC Part 3: tranh chấp hóa đơn minibar.", f: "minibar (n), minibar charge (n), restock (v), incidental charges (n), in-room fridge (n)" },
  "wake-up call": { m: "Cuộc gọi đánh thức (wake up). Nghĩa bóng: hồi chuông cảnh tỉnh.", e: "Sai: please wake-up call me at 6 → Đúng: please give me a wake-up call at 6. Sai: wake up call (thiếu gạch nối) → Đúng: wake-up call.", u: "Lễ tân: request/schedule a wake-up call. IELTS Writing: 'The pandemic was a wake-up call for healthcare systems.'", f: "wake up (phr v), wake-up call (n), alarm call (n, Anh), morning call (n)" },
  "key card": { m: "Chìa khóa (key) dạng thẻ (card): chạm vào khóa từ là cửa mở.", e: "Sai: my key card is not work → Đúng: my key card isn't working. Sai: active the key card → Đúng: activate/reactivate the key card.", u: "Lễ tân: encode/deactivate key cards, lost key card. TOEIC Part 2, 3: khách báo thẻ phòng không hoạt động.", f: "key card (n), keycard (n), room key (n), encode (v), deactivate (v)" },
  "guest folio": { m: "folio = trang sổ → 'trang sổ' riêng ghi mọi khoản khách tiêu trong thời gian lưu trú.", e: "Sai: guest's folios bill → Đúng: the guest folio. Sai: post charge in folio → Đúng: post a charge to the guest folio.", u: "Tiền sảnh – kế toán: post charges, split folio, master folio cho đoàn. Dùng khi đối chiếu hóa đơn lúc trả phòng.", f: "folio (n), guest folio (n), master folio (n), post (v, ghi sổ), invoice (n)" },
  "incidental charges": { m: "incidental = phát sinh ngẫu nhiên → chi phí ngoài tiền phòng: minibar, giặt ủi, điện thoại.", e: "Sai: incident charges → Đúng: incidental charges. Sai: pay incidentals charge → Đúng: pay incidental charges / incidentals.", u: "Lễ tân: deposit for incidentals, credit card pre-authorisation. TOEIC Part 7: email nhắc về đặt cọc chi phí phát sinh.", f: "incident (n), incidental (adj), incidentals (n), extra charges (n), deposit (n)" },
  "property management system": { m: "property = cơ sở lưu trú → phần mềm 'não bộ' quản lý đặt phòng, nhận phòng, hóa đơn.", e: "Sai: hotel management software property → Đúng: property management system (PMS). Sai: input into PMS system (lặp) → Đúng: enter into the PMS.", u: "Vận hành khách sạn: PMS như Opera, Cloudbeds; tích hợp channel manager. Tin tuyển dụng yêu cầu thành thạo PMS.", f: "property management system/PMS (n), channel manager (n), booking engine (n), Opera PMS (n)" },
  "revenue management": { m: "Bán đúng phòng, đúng giá, đúng lúc, đúng khách → tối đa hóa doanh thu (revenue).", e: "Sai: revenues management → Đúng: revenue management. Sai: manage revenue by cheap prices only → Đúng: adjust prices according to demand.", u: "Quản trị khách sạn – hàng không: dynamic pricing, forecasting demand, revenue manager. Phỏng vấn ngành hospitality.", f: "revenue (n), revenue management (n), revenue manager (n), yield management (n), dynamic pricing (n)" },
  "average daily rate": { m: "Tổng doanh thu phòng chia số phòng bán được → giá trung bình (average) mỗi đêm (daily).", e: "Sai: average day rate → Đúng: average daily rate (ADR). Nhầm: ADR chia cho phòng đã bán, không phải tổng số phòng.", u: "Quản lý khách sạn: báo cáo ADR, so sánh với đối thủ (comp set), kết hợp occupancy để tính RevPAR.", f: "average daily rate/ADR (n), occupancy rate (n), RevPAR (n), room revenue (n)" },
  "revpar": { m: "Rev(enue) Per Available Room → doanh thu chia cho mọi phòng có thể bán, kể cả phòng trống.", e: "Sai: RevPAR = revenue ÷ rooms sold → Đúng: RevPAR = room revenue ÷ rooms available (= ADR × occupancy).", u: "Quản trị doanh thu: chỉ số đánh giá hiệu quả khách sạn, báo cáo cho chủ đầu tư, so sánh thị trường.", f: "RevPAR (n), ADR (n), occupancy (n), GOPPAR (n), TRevPAR (n)" },
  "food and beverage": { m: "food (đồ ăn) + beverage (đồ uống) → bộ phận lo mọi thứ ăn uống, viết tắt F&B.", e: "Sai: food and drink department (trong khách sạn chuẩn) → Đúng: food and beverage department. Phát âm beverage /ˈbevərɪdʒ/.", u: "Khách sạn – nhà hàng: F&B manager, F&B revenue, banquet. TOEIC Part 7: tuyển dụng F&B supervisor.", f: "food and beverage/F&B (n), beverage (n), F&B manager (n), banquet (n), outlet (n)" },
  "à la carte": { m: "Tiếng Pháp: 'theo tấm thẻ (thực đơn)' → chọn và trả tiền từng món riêng.", e: "Sai: a la carte menu buffet → Đúng: an à la carte menu (không phải buffet). Sai: order ala carte → Đúng: order à la carte.", u: "Nhà hàng: à la carte menu vs set menu vs buffet. TOEIC Part 3: khách hỏi gọi món lẻ hay theo suất.", f: "à la carte (adj/adv), table d'hôte (n), set menu (n), buffet (n), menu (n)" },
  "set menu": { m: "set = cố định, sắp sẵn → thực đơn đã định sẵn các món, một giá chung.", e: "Sai: setting menu → Đúng: set menu. Sai: order the set menu of three dishes → Đúng: order the three-course set menu.", u: "Nhà hàng – sự kiện: set lunch, banquet set menu cho đoàn. TOEIC Part 7: thực đơn tiệc công ty, giá theo đầu người.", f: "set menu (n), set lunch (n), fixed-price menu (n), prix fixe (n), à la carte (adj)" },
  "catering": { m: "cater (cung cấp đồ ăn, đáp ứng) → mang suất ăn đến sự kiện, công ty, chuyến bay.", e: "Sai: the catering for the wedding were good → Đúng: the catering was good. Sai: cater the party → Đúng: cater for/cater the party (Mỹ).", u: "Ngành F&B – sự kiện: catering company, in-flight catering, corporate catering. TOEIC Part 4, 7: đặt suất ăn cho hội nghị.", f: "cater (v), caterer (n), catering (n), catering service (n), cater to (phr v, đáp ứng)" },
  "dietary requirements": { m: "diet (chế độ ăn) → dietary: yêu cầu riêng như chay, không gluten, halal, dị ứng.", e: "Sai: diet requirements → Đúng: dietary requirements. Sai: do you have any special eating? → Đúng: do you have any dietary requirements?", u: "Nhà hàng – sự kiện: ghi nhận dietary requirements khi đặt tiệc. TOEIC Part 7: mẫu đăng ký hội nghị có ô này.", f: "diet (n), dietary (adj), dietary restrictions (n), vegetarian (adj/n), halal (adj)" },
  "food allergy": { m: "allergy = phản ứng quá mức của cơ thể → ăn đậu phộng, tôm là nổi mẩn, khó thở.", e: "Sai: I allergy with peanuts → Đúng: I'm allergic to peanuts / I have a peanut allergy. Sai: allergic with → Đúng: allergic to.", u: "Nhà hàng: allergen information, cross-contamination, cảnh báo trên thực đơn. IELTS Speaking: talk about food you can't eat.", f: "allergy (n), allergic (adj), allergen (n), intolerance (n), anaphylaxis (n)" },
  "sommelier": { m: "Từ Pháp, đọc /səˈmeljeɪ/ → chuyên gia rượu vang gợi ý chai hợp với món ăn.", e: "Sai: sommelier đọc 'som-me-li-er' → Đúng: /səˈmeljeɪ/. Sai: ask a wine waiter sommelier → Đúng: ask the sommelier.", u: "Nhà hàng cao cấp: wine pairing, wine list, head sommelier. TOEIC Part 7: bài về sự kiện thử rượu vang.", f: "sommelier (n), wine steward (n), wine pairing (n), wine list (n), vintage (n)" },
  "bartender": { m: "bar (quầy) + tender (người trông coi) → người đứng quầy pha chế đồ uống.", e: "Sai: barman (giới tính) cho mọi người → Đúng: bartender (trung tính). Sai: bar tender → Đúng: bartender.", u: "F&B: bartender pha cocktail, mixology, quản lý quầy bar. IELTS Speaking: describe a job you'd like to try.", f: "bartender (n), barman/barmaid (n), mixologist (n), mixology (n), bar staff (n)" },
  "executive chef": { m: "executive = điều hành → đầu bếp đứng đầu cả bếp, lên thực đơn, quản lý chi phí.", e: "Sai: chief chef → Đúng: executive chef / head chef. Phát âm chef /ʃef/, không phải 'chép'.", u: "Bếp khách sạn: executive chef, sous chef, chef de partie (thứ bậc bếp). TOEIC Part 7: thông báo bổ nhiệm bếp trưởng.", f: "chef (n), executive chef (n), head chef (n), sous chef (n), culinary (adj)" },
  "tour operator": { m: "operate (vận hành) → công ty 'vận hành' tour: ghép xe, khách sạn, hướng dẫn viên thành gói.", e: "Sai: tour operater → Đúng: tour operator. Nhầm: tour operator (tạo tour) khác travel agent (bán lại tour).", u: "Ngành lữ hành: inbound tour operator, contract hotels, itinerary design. TOEIC Part 7: hợp đồng giữa khách sạn và công ty lữ hành.", f: "operate (v), operator (n), tour operator (n), travel agent (n), DMC (n)" },
  "travel agency": { m: "agency = đại lý → văn phòng làm 'trung gian' bán vé, tour, phòng cho khách.", e: "Sai: travel agent company → Đúng: travel agency (công ty); travel agent = nhân viên/đại lý. Sai: travel agencies is → Đúng: are.", u: "Du lịch: book through a travel agency, commission. TOEIC Part 3: khách gọi điện đổi lịch trình với đại lý.", f: "travel agency (n), travel agent (n), agency (n), online travel agency/OTA (n)" },
  "package tour": { m: "package = gói hàng → vé máy bay, khách sạn, ăn, tham quan gói chung một giá.", e: "Sai: packet tour → Đúng: package tour. Sai: go to a package tour → Đúng: go on a package tour.", u: "IELTS Speaking: Do you prefer package tours or independent travel? Lữ hành: package holiday, all-in price.", f: "package tour (n), package holiday (n, Anh), packaged (adj), independent travel (n)" },
  "sightseeing": { m: "see the sights → đi ngắm (see) các thắng cảnh (sights) nổi tiếng.", e: "Sai: go sightsee → Đúng: go sightseeing. Sai: do a sightseeing → Đúng: do some sightseeing.", u: "IELTS Speaking Part 1/2: describe a trip, go sightseeing in Hội An. Du lịch: sightseeing tour, hop-on hop-off bus.", f: "sightseeing (n), sightseer (n), sights (n), sightseeing tour (n), see the sights (phrase)" },
  "tour guide": { m: "guide = dẫn đường → người dẫn đoàn, thuyết minh lịch sử, văn hóa điểm đến.", e: "Sai: guide tour (khi nói người) → Đúng: tour guide. Sai: work like a tour guide → Đúng: work as a tour guide.", u: "Lữ hành: licensed tour guide, local guide, thuyết minh. IELTS Speaking: describe a job you'd like to do.", f: "guide (n/v), tour guide (n), guided tour (n), guidebook (n), tour leader (n)" },
  "tour leader": { m: "leader = người dẫn đầu → đi cùng đoàn suốt chuyến, lo hậu cần; khác guide thuyết minh tại điểm.", e: "Nhầm: tour leader = tour guide → Đúng: tour leader quản lý đoàn suốt hành trình; guide thuyết minh tại chỗ.", u: "Lữ hành outbound: tour leader đi cùng đoàn ra nước ngoài, xử lý sự cố, giờ giấc. TOEIC Part 4: thông báo của trưởng đoàn.", f: "tour leader (n), tour manager (n), tour escort (n), tour guide (n), group leader (n)" },
  "inbound tourism": { m: "in (vào) + bound (hướng tới) → khách nước ngoài đi vào Việt Nam.", e: "Sai: inbound tourism = du lịch trong nước → Đúng: inbound = khách quốc tế đến; nội địa là domestic tourism.", u: "Ngành du lịch: inbound tourist arrivals, inbound tour operator. IELTS Writing Task 1: số liệu khách quốc tế đến.", f: "inbound (adj), inbound tourism (n), international arrivals (n), outbound tourism (n), domestic tourism (n)" },
  "outbound tourism": { m: "out (ra) + bound (hướng tới) → người Việt đi du lịch ra nước ngoài.", e: "Sai: outside tourism → Đúng: outbound tourism. Sai: outbound tourists come to Vietnam → Đúng: inbound tourists come to Vietnam.", u: "Ngành lữ hành: outbound tour, visa services, chi tiêu ở nước ngoài. IELTS Writing Task 1: so sánh inbound và outbound.", f: "outbound (adj), outbound tourism (n), outbound travel (n), inbound tourism (n)" },
  "domestic tourism": { m: "domestic = trong nhà, trong nước → người dân đi du lịch ngay trong nước mình.", e: "Sai: domestical tourism → Đúng: domestic tourism. Sai: home tourism → Đúng: domestic tourism.", u: "Ngành du lịch: kích cầu du lịch nội địa sau dịch. IELTS Writing: domestic tourism boosts local economies.", f: "domestic (adj), domestic tourism (n), domestic flight (n), staycation (n), local travel (n)" },
  "community-based tourism": { m: "Cộng đồng (community) làm chủ: dân bản đón khách, chia lợi nhuận, giữ văn hóa.", e: "Sai: community base tourism → Đúng: community-based tourism. Thiếu gạch nối: community based → community-based.", u: "Ngành du lịch bền vững: CBT ở Sa Pa, Mai Châu. IELTS Writing: tourism should benefit local communities.", f: "community-based tourism/CBT (n), ecotourism (n), homestay (n), sustainable tourism (n), local community (n)" },
  "homestay": { m: "home (nhà) + stay (ở lại) → ở trong nhà dân, ăn cùng, sống cùng gia đình bản địa.", e: "Sai: stay at a homestay house → Đúng: stay at a homestay. Sai: home stay → Đúng: homestay.", u: "IELTS Speaking: describe a place you stayed. Du lịch: homestay ở Hà Giang, du học sinh ở homestay với host family.", f: "homestay (n), host family (n), guesthouse (n), B&B (n), farmstay (n)" },
  "boutique hotel": { m: "boutique = cửa hàng nhỏ sang trọng → khách sạn ít phòng, thiết kế độc đáo, cá tính riêng.", e: "Sai: a hotel boutique → Đúng: a boutique hotel. Phát âm boutique /buːˈtiːk/, không phải 'bâu-tích'.", u: "Ngành khách sạn: boutique hotel concept, design-led, personalised service. IELTS Speaking: describe a hotel you stayed in.", f: "boutique (n/adj), boutique hotel (n), design hotel (n), lifestyle hotel (n), chain hotel (n)" },
  "star rating": { m: "Ngôi sao (star) gắn trên biển khách sạn: càng nhiều sao càng nhiều dịch vụ.", e: "Sai: a five stars hotel → Đúng: a five-star hotel. Sai: rating of star → Đúng: star rating.", u: "Khách sạn: star rating criteria, upgrade to 4-star. TOEIC Part 7: quảng cáo khách sạn năm sao.", f: "star rating (n), five-star (adj), star-rated (adj), classification (n), grading (n)" },
  "all-inclusive": { m: "all (tất cả) + inclusive (bao gồm) → trả một lần, ăn uống, đồ uống, hoạt động đều đã gồm.", e: "Sai: all inclusive package (thiếu gạch nối) → Đúng: an all-inclusive package. Sai: all-include → Đúng: all-inclusive.", u: "Khu nghỉ dưỡng: all-inclusive resort, all-inclusive rate. TOEIC Part 7: so sánh gói nghỉ dưỡng trọn gói.", f: "all-inclusive (adj/n), inclusive (adj), include (v), full board (n), half board (n)" },
  "half board": { m: "half (nửa) + board (bữa ăn, như 'bed and board') → phòng + sáng + một bữa chính.", e: "Sai: half-board includes three meals → Đúng: half board includes breakfast and dinner. Sai: half bed → Đúng: half board.", u: "Khách sạn – lữ hành châu Âu: half board (HB) trong báo giá. TOEIC Part 7: so sánh BB, HB, FB.", f: "half board/HB (n), full board/FB (n), bed and breakfast/BB (n), room only/RO (n)" },
  "full board": { m: "full (đầy đủ) + board (bữa ăn) → phòng kèm đủ sáng, trưa, tối.", e: "Sai: full board includes drinks → Đúng: full board usually excludes drinks; drinks included = all-inclusive.", u: "Lữ hành: full board package cho đoàn, khu nghỉ xa trung tâm. TOEIC Part 7: đọc báo giá FB.", f: "full board/FB (n), full pension (n), half board (n), all-inclusive (adj), meal plan (n)" },
  "bed and breakfast": { m: "Đúng nghĩa đen: một chiếc giường (bed) + bữa sáng (breakfast) → nhà nghỉ nhỏ kiểu gia đình.", e: "Sai: bed & breakfasts is cheap → Đúng: B&Bs are cheap. Sai: bed and breakfast include → Đúng: includes.", u: "Khách sạn – lữ hành: B&B rate, room with breakfast. IELTS Speaking: describe accommodation when travelling.", f: "bed and breakfast/B&B (n), guesthouse (n), room only (n), half board (n), inn (n)" },
  "peak season": { m: "peak = đỉnh núi → giai đoạn lượng khách lên 'đỉnh', giá cao nhất.", e: "Sai: in the peak season time → Đúng: in (the) peak season. Sai: peek season → Đúng: peak season.", u: "Khách sạn – lữ hành: peak season surcharge, high demand. IELTS Writing: crowding during peak season harms heritage sites.", f: "peak season (n), high season (n), peak (adj/n/v), off-peak (adj), shoulder season (n)" },
  "off-season": { m: "off (tắt, ngoài) + season → ngoài mùa du lịch: vắng khách, giá rẻ.", e: "Sai: in off season (thiếu gạch nối) → Đúng: in the off-season. Sai: low seasons price → Đúng: off-season prices.", u: "Khách sạn: off-season discounts, maintenance during low season. IELTS Speaking: I prefer travelling in the off-season to avoid crowds.", f: "off-season (n/adj), low season (n), off-peak (adj), peak season (n), shoulder season (n)" },
  "shoulder season": { m: "Như vai (shoulder) nằm giữa đầu và thân → mùa nằm giữa cao điểm và thấp điểm.", e: "Sai: middle season → Đúng: shoulder season. Sai: on shoulder season → Đúng: in the shoulder season.", u: "Quản trị doanh thu: định giá mùa giao thời, khuyến mãi kéo khách. Du lịch: shoulder season deals.", f: "shoulder season (n), peak season (n), off-season (n), seasonality (n), mid-season (n)" },
  "tourist attraction": { m: "attract (thu hút) → nơi 'hút' khách du lịch: Vịnh Hạ Long, phố cổ Hội An.", e: "Sai: a tourism attraction place → Đúng: a tourist attraction. Sai: attractive tourist → Đúng: tourist attraction.", u: "IELTS Speaking Part 2: describe a tourist attraction in your country. Writing: should attractions charge entry fees?", f: "attract (v), attraction (n), attractive (adj), tourist attraction (n), landmark (n)" },
  "heritage site": { m: "heritage = thứ thừa kế (inherit) từ tổ tiên → nơi được gìn giữ cho đời sau.", e: "Sai: a World Heritage → Đúng: a World Heritage Site. Sai: heritage place of UNESCO → Đúng: a UNESCO World Heritage Site.", u: "IELTS Writing: tourism damages heritage sites. Du lịch: Huế, Mỹ Sơn, Tràng An; heritage conservation.", f: "heritage (n), heritage site (n), inherit (v), cultural heritage (n), World Heritage Site (n)" },
  "travel insurance": { m: "insure (bảo đảm) → mua 'tấm khiên' chi trả khi ốm, mất hành lý, hủy chuyến lúc đi xa.", e: "Sai: buy a travel insurance → Đúng: buy/take out travel insurance (không đếm được). Sai: insurance of travel → Đúng: travel insurance.", u: "Lữ hành: travel insurance policy, claim, coverage. TOEIC Part 7: điều khoản bảo hiểm trong hợp đồng tour.", f: "insure (v), insurance (n), insurer (n), policy (n), claim (n/v), coverage (n)" },
  "boarding pass": { m: "board (lên tàu, máy bay) + pass (giấy thông hành) → giấy phép bước lên máy bay.", e: "Sai: boarding card ticket → Đúng: boarding pass / boarding card. Sai: show the boarding pass for gate → Đúng: show it at the gate.", u: "Hàng không – lữ hành: mobile boarding pass, gate number, seat number. TOEIC Part 4: thông báo tại cửa ra máy bay.", f: "board (v), boarding (n), boarding pass (n), boarding gate (n), check-in (n)" },
  "baggage allowance": { m: "allow (cho phép) → lượng hành lý hãng 'cho phép' mang theo không mất phí.", e: "Sai: baggages allowance → Đúng: baggage allowance (baggage không đếm được). Sai: exceed allowance baggage → Đúng: exceed the baggage allowance.", u: "Hàng không: checked baggage allowance, carry-on, excess baggage fee. TOEIC Part 4, 7: quy định hành lý hãng bay.", f: "allow (v), allowance (n), baggage/luggage (n), excess baggage (n), carry-on (n)" },
  "layover": { m: "lay over (nằm lại) → dừng lại ở sân bay trung chuyển chờ chuyến tiếp theo.", e: "Sai: a layover in Singapore airport for 2 hours long → Đúng: a two-hour layover in Singapore. Anh dùng stopover cho dừng lâu.", u: "Hàng không – lữ hành: long layover, transit visa, connecting flight. TOEIC Part 3: hội thoại về lịch trình bay.", f: "layover (n), stopover (n), transit (n), connecting flight (n), lay over (phr v)" },
  "airport transfer": { m: "transfer = chuyển từ chỗ này sang chỗ khác → xe chở khách từ sân bay về khách sạn.", e: "Sai: airport pick-up and transfer service car → Đúng: airport transfer. Sai: arrange transfer to airport for → Đúng: arrange an airport transfer.", u: "Khách sạn – lữ hành: complimentary airport transfer, private transfer. TOEIC Part 7: email xác nhận giờ đón khách.", f: "transfer (n/v), airport transfer (n), pick-up (n), shuttle (n), drop-off (n)" },
  "shuttle bus": { m: "shuttle = con thoi dệt vải chạy đi chạy lại → xe chạy qua lại cố định giữa hai điểm.", e: "Sai: take the shuttle bus to go to airport → Đúng: take the shuttle bus to the airport. Sai: suttle → Đúng: shuttle.", u: "Khách sạn: free shuttle bus, shuttle schedule. TOEIC Part 4: thông báo lịch xe đưa đón hội nghị.", f: "shuttle (n/v), shuttle bus (n), shuttle service (n), airport shuttle (n), space shuttle (n)" },
  "car rental": { m: "rent (thuê) → rental: dịch vụ cho thuê xe tự lái theo ngày.", e: "Sai: rent car service → Đúng: car rental service. Anh thường nói car hire. Sai: rental a car → Đúng: rent a car.", u: "Lữ hành: car rental desk, rental agreement, insurance excess. TOEIC Part 7: hợp đồng thuê xe, phí trả xe muộn.", f: "rent (v), rental (n/adj), car rental (n), car hire (n, Anh), rental agreement (n)" },
  "guest satisfaction": { m: "satisfy (làm hài lòng) → mức khách 'thỏa mãn' sau kỳ lưu trú, đo bằng khảo sát.", e: "Sai: guests satisfaction → Đúng: guest satisfaction. Sai: satisfy of guests → Đúng: guest satisfaction.", u: "Quản lý khách sạn: guest satisfaction score, survey, KPI. TOEIC Part 7: báo cáo khảo sát hài lòng của khách.", f: "satisfy (v), satisfaction (n), satisfied (adj), satisfactory (adj), dissatisfaction (n)" },
  "guest complaint": { m: "complain (phàn nàn) → complaint: lời than phiền của khách cần xử lý nhanh.", e: "Sai: the guest complained about → đúng; nhưng Sai: a complain → Đúng: a complaint. Sai: handle complaint of guest → Đúng: handle a guest complaint.", u: "Khách sạn: handle/resolve guest complaints, LEARN model, service recovery. TOEIC Part 3: hội thoại khách phàn nàn.", f: "complain (v), complaint (n), complainant (n), service recovery (n), feedback (n)" },
  "duty manager": { m: "on duty = đang trực → quản lý trực ca, xử lý sự cố khi cấp trên vắng mặt.", e: "Sai: the manager on duty of night → Đúng: the night duty manager. Sai: call duty manger → Đúng: duty manager.", u: "Khách sạn: duty manager handles escalations, VIP, emergencies. TOEIC Part 3: khách yêu cầu gặp quản lý ca.", f: "duty (n), on duty (phrase), duty manager (n), night manager (n), shift (n)" },
  "general manager": { m: "general = tổng quát → người quản lý tổng thể mọi bộ phận khách sạn, viết tắt GM.", e: "Sai: general director (khách sạn) → Đúng: general manager. Sai: GM of hotel → Đúng: the hotel's GM.", u: "Khách sạn: general manager oversees operations, P&L. TOEIC Part 7: thông báo bổ nhiệm GM mới.", f: "general manager/GM (n), manager (n), management (n), managerial (adj), executive committee (n)" },
  "guest relations": { m: "relations = quan hệ → bộ phận 'giữ mối quan hệ' với khách: chào đón, chăm sóc khách VIP.", e: "Sai: guest relation officer → Đúng: guest relations officer (relations số nhiều). Sai: relationship guest → Đúng: guest relations.", u: "Khách sạn: guest relations officer (GRO), courtesy calls, VIP amenities. TOEIC Part 7: tuyển dụng nhân viên quan hệ khách.", f: "relate (v), relations (n), guest relations officer/GRO (n), public relations (n), concierge (n)" },
  "vip guest": { m: "VIP = Very Important Person → khách rất quan trọng, được đón tiếp đặc biệt.", e: "Sai: a very VIP guest (lặp) → Đúng: a VIP guest. Viết hoa: VIP, không viết 'vip'.", u: "Khách sạn: VIP arrival, VIP amenities, upgrade. TOEIC Part 4: chuẩn bị đón khách VIP.", f: "VIP (n/adj), VIP lounge (n), VIP treatment (n), high-profile guest (n), dignitary (n)" },
  "walk-in guest": { m: "walk in = đi bộ vào → khách bước thẳng vào quầy, không đặt trước.", e: "Sai: walking guest → Đúng: walk-in guest. Sai: walk in guest (thiếu gạch nối) → Đúng: walk-in guest.", u: "Lễ tân: walk-in rate, room availability check. TOEIC Part 3: khách vãng lai hỏi còn phòng không.", f: "walk-in (adj/n), walk in (phr v), walk-in guest (n), reservation (n), no-show (n)" },
  "turndown service": { m: "turn down the bed = lật góc chăn → buổi tối dọn lại phòng, chuẩn bị giường để ngủ.", e: "Sai: turn-down the bed service → Đúng: turndown service. Nhầm: turn down (từ chối) khác turndown service.", u: "Bộ phận buồng: evening turndown, chocolate on pillow, khách sạn 5 sao. TOEIC Part 7: dịch vụ đi kèm phòng cao cấp.", f: "turndown service (n), turn down (phr v), evening service (n), housekeeping (n)" },
  "laundry service": { m: "laundry = đồ cần giặt → dịch vụ nhận đồ trong túi giặt, trả lại sạch, ủi phẳng.", e: "Sai: laundries service → Đúng: laundry service. Sai: do the laundry service for me → Đúng: send my clothes to the laundry.", u: "Khách sạn: laundry list, same-day/express laundry, dry cleaning. TOEIC Part 3: khách hỏi giờ trả đồ giặt.", f: "launder (v), laundry (n), laundromat (n), dry cleaning (n), laundry bag (n)" },
  "lost and found": { m: "Những thứ đã mất (lost) và được tìm thấy (found) → nơi giữ đồ thất lạc.", e: "Sai: lost and find → Đúng: lost and found. Sai: go to lost-found office → Đúng: go to the lost and found.", u: "Khách sạn – sân bay: lost and found log, claim an item. TOEIC Part 3, 4: khách bỏ quên đồ trong phòng.", f: "lost and found (n), lost property (n, Anh), lose (v), find (v), unclaimed (adj)" },
  "fitness center": { m: "fit (khỏe, cân đối) → trung tâm giúp giữ dáng: máy chạy, tạ, yoga.", e: "Sai: fitness centre room gym (lặp) → Đúng: fitness center/gym. Anh viết centre, Mỹ viết center.", u: "Tiện nghi khách sạn: 24-hour fitness center. IELTS Speaking: Do you go to the gym? TOEIC Part 7: giờ mở cửa phòng gym.", f: "fit (adj), fitness (n), fitness center/centre (n), gym (n), health club (n)" },
  "mice": { m: "Viết tắt Meetings, Incentives, Conferences, Exhibitions → mảng du lịch kết hợp công việc.", e: "Sai: hiểu là 'mice' (con chuột) → Đúng: MICE (viết hoa) = du lịch hội nghị. Sai: MICE tourisms → Đúng: MICE tourism.", u: "Ngành du lịch – sự kiện: MICE market, MICE destination, convention centre. Phỏng vấn ngành lữ hành, sales khách sạn.", f: "MICE (n), MICE tourism (n), business events (n), conference (n), incentive trip (n)" },
  "incentive trip": { m: "incentive = phần thưởng khích lệ → công ty thưởng nhân viên giỏi một chuyến du lịch.", e: "Sai: incentive travel trip (lặp) → Đúng: incentive trip / incentive travel. Sai: incentive tour for to staff → Đúng: for staff.", u: "MICE: tổ chức incentive trip cho đại lý bảo hiểm, team-building. TOEIC Part 7: thông báo phần thưởng doanh số.", f: "incentive (n), incentivise (v), incentive trip (n), incentive travel (n), reward (n)" },
  "conference room": { m: "conference = hội nghị → căn phòng có bàn dài, máy chiếu để họp.", e: "Sai: conference hall room → Đúng: conference room. Sai: book conference room → Đúng: book the conference room.", u: "Khách sạn – văn phòng: book a conference room, AV equipment, seating layout. TOEIC Part 3: đặt phòng họp.", f: "confer (v), conference (n), conference room (n), meeting room (n), function room (n)" },
  "familiarization trip": { m: "familiar (quen thuộc) → mời đại lý đi thử để 'làm quen' điểm đến, gọi tắt famtrip.", e: "Sai: familiar trip → Đúng: familiarization trip / famtrip. Anh viết familiarisation.", u: "Lữ hành – marketing điểm đến: famtrip cho đại lý, nhà báo, KOL. TOEIC Part 7: thư mời tham gia famtrip.", f: "familiar (adj), familiarize (v), familiarization (n), famtrip (n), site inspection (n)" },
  "group booking": { m: "group = đoàn → một lần đặt nhiều phòng cho cả đoàn, thường được giá tốt.", e: "Sai: booking group for 20 rooms → Đúng: a group booking of 20 rooms. Sai: groups booking → Đúng: group booking.", u: "Khách sạn – lữ hành: group rate, rooming list, deposit. TOEIC Part 7: email đặt phòng cho đoàn hội nghị.", f: "group booking (n), group rate (n), rooming list (n), block booking (n), allotment (n)" },
  "allotment": { m: "allot (chia phần) → khách sạn 'chia phần' số phòng giữ sẵn cho công ty lữ hành.", e: "Sai: allottment → Đúng: allotment. Sai: release allotment rooms late → Đúng: release unsold rooms by the release date.", u: "Hợp đồng khách sạn – lữ hành: allotment contract, release period, cut-off date. Dùng nhiều trong bộ phận sales.", f: "allot (v), allotment (n), release date (n), cut-off date (n), room block (n)" },
  "rack rate": { m: "Giá 'treo trên giá' (rack) ở quầy lễ tân → giá niêm yết cao nhất, chưa giảm.", e: "Sai: the rack rate is the cheapest → Đúng: the rack rate is the full published price. Sai: rack price → Đúng: rack rate.", u: "Quản trị doanh thu: discount off the rack rate, corporate rate. TOEIC Part 7: so sánh giá niêm yết và giá ưu đãi.", f: "rack rate (n), published rate (n), discounted rate (n), BAR (n), corporate rate (n)" },
  "corporate rate": { m: "corporate = thuộc công ty → giá ưu đãi dành cho doanh nghiệp có hợp đồng.", e: "Sai: company rate price → Đúng: corporate rate. Sai: give corporate rate to → Đúng: offer a corporate rate to.", u: "Sales khách sạn: negotiated corporate rate, corporate account. TOEIC Part 7: email đàm phán giá cho công ty.", f: "corporate (adj), corporation (n), corporate rate (n), corporate account (n), negotiated rate (n)" },
  "online travel agency": { m: "Đại lý du lịch (travel agency) nhưng trên mạng (online) → Booking.com, Agoda; viết tắt OTA.", e: "Sai: an online travel agent website → Đúng: an online travel agency (OTA). Sai: OTAs takes → Đúng: OTAs take commission.", u: "Khách sạn: OTA commission, channel manager, parity rate. Marketing du lịch: giảm phụ thuộc OTA, tăng direct booking.", f: "online travel agency/OTA (n), travel agency (n), channel manager (n), commission (n), direct booking (n)" },
  "direct booking": { m: "direct = trực tiếp → khách đặt thẳng qua web/điện thoại khách sạn, không qua trung gian.", e: "Sai: book directly booking → Đúng: make a direct booking / book directly. Sai: direct booking with OTA → Đúng: via the hotel's website.", u: "Marketing khách sạn: best rate guarantee, booking engine, tiết kiệm hoa hồng OTA. TOEIC Part 7: ưu đãi đặt trực tiếp.", f: "direct (adj/adv), directly (adv), direct booking (n), booking engine (n), OTA (n)" },
  "online review": { m: "review = xem lại, nhận xét → lời đánh giá khách viết trên mạng sau khi trải nghiệm.", e: "Sai: write a review online about hotel → Đúng: write an online review of the hotel. Sai: reviews about → Đúng: reviews of/about.", u: "IELTS Writing/Speaking: Do you trust online reviews? Khách sạn: respond to online reviews, TripAdvisor rating.", f: "review (n/v), reviewer (n), online review (n), rating (n), feedback (n)" },
  "guest experience": { m: "Mọi khoảnh khắc khách 'trải qua' từ lúc đặt phòng đến lúc rời đi.", e: "Sai: experience of guest → Đúng: guest experience. Sai: a guests experiences → Đúng: the guest experience.", u: "Khách sạn: enhance the guest experience, guest experience manager, touchpoints. Phỏng vấn ngành hospitality hay hỏi.", f: "experience (n/v), experienced (adj), guest experience (n), customer experience/CX (n), touchpoint (n)" },
  "personalized service": { m: "personal (cá nhân) → dịch vụ 'may đo' theo sở thích từng khách: nhớ tên, gối ưa thích.", e: "Sai: personal service (dịch vụ riêng tư) → Đúng: personalized service. Anh viết personalised.", u: "Khách sạn cao cấp: guest preferences, CRM, guest profile. IELTS Writing: technology enables personalized service.", f: "personal (adj), personalize (v), personalized (adj), personalization (n), tailor-made (adj)" },
  "service standard": { m: "standard = chuẩn mực → quy định cụ thể: nghe máy trong 3 hồi chuông, chào khách bằng tên.", e: "Sai: standard of services → Đúng: service standards. Sai: meet the standard service → Đúng: meet service standards.", u: "Khách sạn: SOP, brand standards, mystery shopper. TOEIC Part 7: thông báo đào tạo tiêu chuẩn dịch vụ.", f: "standard (n/adj), standardize (v), service standards (n), SOP (n), quality assurance (n)" },
  "front office": { m: "front (phía trước) + office → khối 'mặt tiền' tiếp xúc khách: lễ tân, đặt phòng, concierge.", e: "Sai: front office = front desk → Đúng: front office là cả bộ phận; front desk chỉ là quầy lễ tân.", u: "Khách sạn: front office manager, front office operations. Ngân hàng: front office vs back office.", f: "front office (n), back office (n), front desk (n), front office manager/FOM (n), reception (n)" },
  "night audit": { m: "audit = kiểm tra sổ sách → mỗi đêm đối chiếu doanh thu, đóng ngày trên hệ thống.", e: "Sai: audit in night → Đúng: night audit. Sai: night auditer → Đúng: night auditor.", u: "Tiền sảnh – kế toán: run the night audit, end-of-day report, PMS. Tin tuyển dụng: night auditor.", f: "audit (n/v), auditor (n), night audit (n), night auditor (n), end-of-day report (n)" },
  "valet parking": { m: "valet = người hầu (tiếng Pháp) → nhân viên nhận chìa khóa, đỗ xe hộ khách.", e: "Sai: valet park → Đúng: valet parking. Phát âm valet /ˈvæleɪ/ hoặc /ˈvælɪt/.", u: "Khách sạn – nhà hàng: valet parking fee, valet ticket. TOEIC Part 2, 3: khách hỏi chỗ đỗ xe.", f: "valet (n/v), valet parking (n), parking attendant (n), self-parking (n), car park (n)" },
  "hostel": { m: "Gần 'hotel' nhưng rẻ hơn: giường tầng, phòng chung, hợp dân ba lô.", e: "Sai: hostel = hotel → Đúng: a hostel has shared dorms. Đừng nhầm với hostile (thù địch).", u: "IELTS Speaking: describe a cheap place you stayed. Du lịch: youth hostel, dorm bed, backpacker market.", f: "hostel (n), youth hostel (n), dormitory/dorm (n), hotel (n), guesthouse (n)" },
  "backpacker": { m: "back (lưng) + pack (ba lô) → người đeo ba lô trên lưng, đi bụi, tiết kiệm.", e: "Sai: back-packer tourist → Đúng: backpacker. Sai: go backpack → Đúng: go backpacking.", u: "IELTS Speaking: Have you ever gone backpacking? Du lịch: backpacker street Phạm Ngũ Lão, budget travel.", f: "backpack (n/v), backpacker (n), backpacking (n), budget traveller (n), hostel (n)" },
  "local cuisine": { m: "cuisine (tiếng Pháp: nhà bếp) → phong cách nấu ăn riêng của một vùng: phở, bún bò.", e: "Sai: local cuisines food → Đúng: local cuisine. Phát âm cuisine /kwɪˈziːn/.", u: "IELTS Speaking: talk about local cuisine in your hometown. Du lịch ẩm thực: food tour, culinary tourism.", f: "cuisine (n), culinary (adj), local cuisine (n), street food (n), gastronomy (n)" },
  "tourism board": { m: "board = hội đồng → cơ quan quảng bá điểm đến, như 'Tổng cục Du lịch'.", e: "Sai: tourist board (vẫn dùng ở Anh) nhưng Sai: tourism broad → Đúng: tourism board.", u: "Ngành du lịch: national tourism board, destination marketing, travel fairs. TOEIC Part 7: chiến dịch quảng bá.", f: "tourism board (n), tourist board (n), destination marketing organisation/DMO (n), tourism authority (n)" },
  "overtourism": { m: "over (quá mức) + tourism → quá đông khách khiến dân địa phương và di sản 'ngộp thở'.", e: "Sai: over tourism (tách) → Đúng: overtourism. Sai: the overtourism are → Đúng: overtourism is.", u: "IELTS Writing Task 2: overtourism in Venice, Hội An; giải pháp như entry fees, visitor caps. Ngành quản lý điểm đến.", f: "overtourism (n), mass tourism (n), crowding (n), carrying capacity (n), sustainable tourism (n)" },
  "sustainable tourism": { m: "sustain (duy trì) → du lịch duy trì lâu dài: bảo vệ môi trường, văn hóa, lợi ích dân bản.", e: "Sai: sustainability tourism → Đúng: sustainable tourism. Sai: develop tourism sustainable → Đúng: develop tourism sustainably.", u: "IELTS Writing Task 2: how to promote sustainable tourism. Ngành du lịch: certification, eco-lodges, carbon offset.", f: "sustain (v), sustainable (adj), sustainability (n), sustainably (adv), ecotourism (n)" },
  "hospitality management": { m: "hospitality = lòng hiếu khách → ngành quản lý 'sự hiếu khách': khách sạn, nhà hàng, resort.", e: "Sai: hospital management → Đúng: hospitality management. Sai: study hospitality manage → Đúng: study hospitality management.", u: "IELTS Speaking: What do you study? – hospitality management. Hồ sơ du học, CV ngành khách sạn.", f: "hospitable (adj), hospitality (n), hospitality industry (n), hotel management (n), host (n/v)" },
  "guest profile": { m: "profile = hồ sơ, chân dung → 'chân dung' khách: sở thích, lịch sử lưu trú, dị ứng.", e: "Sai: profile of the guests history → Đúng: the guest profile. Sai: update guest's profiles → Đúng: update guest profiles.", u: "Tiền sảnh – CRM: update guest profiles in the PMS, guest preferences, repeat guests. Cơ sở cho personalized service.", f: "profile (n/v), guest profile (n), guest history (n), CRM (n), preference (n)" },
  "early departure": { m: "depart (rời đi) → khách rời sớm hơn ngày dự kiến trong đặt phòng.", e: "Sai: early check-out departure → Đúng: early departure. Sai: depart early fee → Đúng: early departure fee.", u: "Lễ tân: early departure fee, update room status, forecast. TOEIC Part 3: khách báo rời sớm vì việc gấp.", f: "depart (v), departure (n), early departure (n), check-out (n), extension of stay (n)" },
  "extension of stay": { m: "extend (kéo dài) → kéo dài thời gian ở (stay) thêm vài đêm.", e: "Sai: extend my staying → Đúng: extend my stay. Sai: stay extension of → Đúng: an extension of stay.", u: "Lễ tân: request an extension of stay, check availability, rate change. TOEIC Part 3: khách xin ở thêm một đêm.", f: "extend (v), extension (n), extended stay (n), stay (n/v), early departure (n)" },
  "hotel chain": { m: "chain = chuỗi xích → nhiều khách sạn cùng thương hiệu nối với nhau như mắt xích.", e: "Sai: chain hotels group → Đúng: a hotel chain. Sai: a chain of hotel → Đúng: a chain of hotels.", u: "Ngành khách sạn: international hotel chains (Marriott, Accor), franchise, brand standards. IELTS Writing: chains vs local businesses.", f: "chain (n), hotel chain (n), chain hotel (n), franchise (n), independent hotel (n)" },
  "management contract": { m: "Chủ đầu tư giữ tòa nhà, ký hợp đồng thuê tập đoàn 'quản lý' vận hành thay.", e: "Sai: contract management (quản lý hợp đồng) → Đúng: management contract. Sai: sign management contract with → Đúng: sign a management contract with.", u: "Đầu tư khách sạn: owner vs operator, management fee, franchise. Dùng trong báo cáo, đàm phán dự án.", f: "management contract (n), management fee (n), operator (n), owner (n), franchise agreement (n)" },
  "pre-arrival": { m: "pre (trước) + arrival (lúc đến) → mọi việc làm trước khi khách tới: email, chuẩn bị phòng.", e: "Sai: prearrival (viết liền) thường ít dùng → Đúng: pre-arrival. Sai: before-arrival email → Đúng: pre-arrival email.", u: "Khách sạn: pre-arrival email, pre-arrival checklist, upsell. TOEIC Part 7: email hỏi giờ đến, yêu cầu đặc biệt.", f: "arrive (v), arrival (n), pre-arrival (adj), post-departure (adj), pre-registration (n)" },
  "amenity kit": { m: "kit = bộ đồ dùng → túi nhỏ gồm bàn chải, kem đánh răng, lược, mặt nạ ngủ.", e: "Sai: amenities kits → Đúng: amenity kits. Sai: an amenity kit are → Đúng: an amenity kit is.", u: "Khách sạn – hàng không: in-flight amenity kit hạng thương gia, bathroom amenities. TOEIC Part 1, 7.", f: "amenity (n), amenity kit (n), toiletries (n), travel kit (n), amenities (n)" },
  "do not disturb": { m: "Tấm biển treo tay nắm cửa: 'đừng (do not) quấy rầy (disturb)'.", e: "Sai: don't disturbing → Đúng: do not disturb. Sai: hang the not disturb sign → Đúng: hang the 'Do Not Disturb' sign.", u: "Khách sạn: DND sign, housekeeping protocol, welfare check. TOEIC Part 1: tranh biển treo cửa phòng.", f: "disturb (v), disturbance (n), DND (n), privacy sign (n), make up room (phrase)" },
  "emergency exit": { m: "emergency (khẩn cấp) + exit (lối ra) → lối thoát khi cháy, có đèn xanh chỉ dẫn.", e: "Sai: emergency out → Đúng: emergency exit. Sai: block emergency exit → Đúng: do not block the emergency exit.", u: "An toàn khách sạn – hàng không: evacuation plan, fire safety. TOEIC Part 4: thông báo an toàn trên máy bay.", f: "emergency (n), exit (n/v), emergency exit (n), fire exit (n), evacuation (n)" },
  "tipping": { m: "tip = tiền thưởng nhỏ → thói quen đưa thêm tiền cho người phục vụ.", e: "Sai: give tipping to the waiter → Đúng: tip the waiter / give the waiter a tip. Sai: tipping is include → Đúng: included.", u: "IELTS Speaking: Is tipping common in your country? Du lịch: tipping etiquette, gratuity. TOEIC Part 7.", f: "tip (n/v), tipping (n), gratuity (n), service charge (n), tipper (n)" },
  "service charge": { m: "Phí (charge) cho việc phục vụ (service) → thường 5–10% cộng vào hóa đơn.", e: "Sai: service fee of 10 percent is plus → Đúng: a 10% service charge is added. Nhầm: service charge khác tip tự nguyện.", u: "Nhà hàng – khách sạn: '++' pricing, service charge and VAT. TOEIC Part 7: hóa đơn có phí phục vụ.", f: "service charge (n), surcharge (n), gratuity (n), VAT (n), tip (n)" },
  "currency exchange": { m: "currency (tiền tệ) + exchange (đổi) → đổi đô la sang đồng tại quầy, sân bay.", e: "Sai: change money exchange → Đúng: currency exchange. Sai: exchange money at bank → Đúng: exchange money at a bank.", u: "Khách sạn – sân bay: currency exchange counter, exchange rate, commission. TOEIC Part 2: khách hỏi nơi đổi tiền.", f: "currency (n), exchange (n/v), exchange rate (n), foreign currency (n), bureau de change (n)" },
  "seasonality": { m: "season (mùa) + -ality → tính chất 'theo mùa': lúc đông nghịt, lúc vắng hoe.", e: "Sai: the seasonal of tourism → Đúng: the seasonality of tourism. Sai: seasonality is affect → Đúng: affects.", u: "Ngành du lịch: managing seasonality, seasonal staff, off-season promotion. IELTS Writing Task 1: biểu đồ lượng khách theo tháng.", f: "season (n), seasonal (adj), seasonally (adv), seasonality (n), off-season (n)" },
  "day tour": { m: "Tour đi về trong một ngày (day), không ở lại qua đêm.", e: "Sai: one-day tour trip → Đúng: a day tour / a day trip. Sai: join day tour → Đúng: join a day tour.", u: "Lữ hành: day tour to Ninh Bình, half-day tour, pick-up at hotel. TOEIC Part 4: thông báo lịch trình tour.", f: "day tour (n), day trip (n), half-day tour (n), excursion (n), overnight tour (n)" },
  "deluxe room": { m: "deluxe = sang trọng (Pháp: de luxe) → phòng hạng cao hơn standard, rộng, view đẹp.", e: "Sai: delux room → Đúng: deluxe room. Sai: upgrade to the deluxe → Đúng: upgrade to a deluxe room.", u: "Khách sạn: room categories (standard, superior, deluxe, suite), upsell. TOEIC Part 7: bảng giá các hạng phòng.", f: "deluxe (adj), luxury (n), luxurious (adj), superior room (n), suite (n)" },
  "connecting rooms": { m: "connect (nối) → hai phòng có cửa thông nhau bên trong, hợp gia đình.", e: "Nhầm: connecting rooms = adjoining rooms → Đúng: adjoining là cạnh nhau, chưa chắc có cửa thông.", u: "Đặt phòng gia đình: request connecting rooms, subject to availability. TOEIC Part 3: khách đi cùng con nhỏ.", f: "connect (v), connection (n), connecting rooms (n), adjoining rooms (n), family room (n)" },
  "welcome drink": { m: "Ly đồ uống 'chào mừng' khách vừa đến, thường là nước ép hoặc trà gừng.", e: "Sai: a drink of welcome → Đúng: a welcome drink. Sai: serve welcoming drink → Đúng: serve a welcome drink.", u: "Khách sạn – resort: welcome drink at check-in, cold towel. TOEIC Part 1, 7: dịch vụ chào đón khách.", f: "welcome (n/v/adj), welcome drink (n), welcome amenity (n), cold towel (n)" },
  "waiting list": { m: "wait (chờ) → danh sách người đang chờ có chỗ trống thì được gọi.", e: "Sai: put me in the waiting list → Đúng: put me on the waiting list. Mỹ hay dùng waitlist.", u: "Khách sạn – nhà hàng – hàng không: be on the waiting list, waitlisted. TOEIC Part 3: hết chỗ, ghi tên chờ.", f: "wait (v), waiting list (n), waitlist (n/v), waitlisted (adj), standby (n)" },
  "registration card": { m: "register (đăng ký) → tấm phiếu khách ký khi nhận phòng, ghi thông tin lưu trú.", e: "Sai: sign in registration card → Đúng: sign the registration card. Sai: register card → Đúng: registration card.", u: "Lễ tân: registration card, passport details, guest signature. TOEIC Part 3: thủ tục nhận phòng.", f: "register (v), registration (n), registration card (n), reg card (n), check-in (n)" },
  "linen": { m: "Vốn là vải lanh → nay chỉ mọi đồ vải của khách sạn: ga, gối, khăn tắm.", e: "Sai: linens is changed daily (Anh) → Đúng: linen is changed daily. Đừng nhầm với 'line' (dòng).", u: "Bộ phận buồng: linen change, linen room, laundry. Chính sách xanh: reuse towels and linen.", f: "linen (n), bed linen (n), table linen (n), linen room (n), towel (n)" },
  "adventure tourism": { m: "adventure = phiêu lưu → du lịch mạo hiểm: leo núi, chèo thuyền, thám hiểm hang Sơn Đoòng.", e: "Sai: adventurous tourism → Đúng: adventure tourism. Sai: a adventure trip → Đúng: an adventure trip.", u: "IELTS Speaking: Do you like adventure travel? Du lịch: adventure tourism Quảng Bình, safety standards.", f: "adventure (n), adventurous (adj), adventurer (n), adventure tourism (n), ecotourism (n)" },
  "syllabus": { m: "Danh sách bài học suốt khóa → đề cương môn học, giáo viên phát buổi đầu.", e: "Sai: syllabuses/syllabi đều đúng, nhưng Sai: the syllabus of the course are → Đúng: the course syllabus is. Đừng nhầm syllable (âm tiết).", u: "Ngành giáo dục: course syllabus, cover the syllabus, align with outcomes. IELTS Speaking: talk about your studies.", f: "syllabus (n), syllabi/syllabuses (n, số nhiều), curriculum (n), course outline (n)" },
  "learning outcome": { m: "outcome = kết quả đầu ra → điều người học 'làm được' khi kết thúc môn.", e: "Sai: learning outcomes is → Đúng: learning outcomes are. Sai: students will know → Đúng: students will be able to analyse/explain.", u: "Ngành giáo dục: intended learning outcomes (ILOs), kiểm định chương trình. Viết đề cương: dùng động từ Bloom.", f: "learning outcome (n), outcome-based education (n), objective (n), competency (n)" },
  "lesson plan": { m: "Bản 'kế hoạch' (plan) cho một tiết học: mục tiêu, hoạt động, thời gian, tài liệu.", e: "Sai: make lesson plan → Đúng: write/prepare a lesson plan. Sai: plan of lesson → Đúng: lesson plan.", u: "Ngành sư phạm: lesson planning, warm-up, CELTA/TESOL. Phỏng vấn giáo viên: present a sample lesson plan.", f: "lesson plan (n), lesson planning (n), scheme of work (n), unit plan (n)" },
  "pedagogy": { m: "Gốc Hy Lạp paidagogos: người dẫn trẻ đi học → nghệ thuật, khoa học dạy học.", e: "Sai: pedagogy method → Đúng: pedagogical method. Phát âm /ˈpedəɡɒdʒi/.", u: "Ngành giáo dục: innovative pedagogy, pedagogical approach. IELTS Writing: modern pedagogy focuses on student engagement.", f: "pedagogy (n), pedagogical (adj), pedagogically (adv), pedagogue (n), andragogy (n)" },
  "teaching method": { m: "method = cách thức → cách thầy cô truyền đạt: giảng giải, thảo luận, dự án.", e: "Sai: method of teach → Đúng: teaching method. Sai: teaching methods is → Đúng: teaching methods are.", u: "IELTS Writing Task 2: traditional vs modern teaching methods. Ngành sư phạm: methodology, communicative approach.", f: "teach (v), teaching (n), teaching method (n), methodology (n), approach (n)" },
  "student-centered learning": { m: "Học sinh ở 'trung tâm' lớp học: tự khám phá, thầy chỉ hướng dẫn.", e: "Sai: student center learning → Đúng: student-centered learning. Anh viết student-centred.", u: "IELTS Writing: student-centred learning encourages independence. Ngành giáo dục: đổi mới phương pháp, giảm thuyết giảng.", f: "student-centered (adj), learner-centered (adj), teacher-centered (adj, trái nghĩa), active learning (n)" },
  "active learning": { m: "active = chủ động → học bằng làm, thảo luận, giải quyết vấn đề thay vì ngồi nghe.", e: "Sai: learn actively learning → Đúng: active learning. Sai: active learnings → Đúng: active learning (không đếm được).", u: "Ngành giáo dục: active learning strategies, think-pair-share. IELTS Writing: active learning improves retention.", f: "active (adj), actively (adv), active learning (n), passive learning (n), engagement (n)" },
  "blended learning": { m: "blend = trộn như sinh tố → kết hợp học trên lớp và học trực tuyến.", e: "Sai: blending learning → Đúng: blended learning. Sai: blended learning are → Đúng: blended learning is.", u: "Ngành giáo dục: blended learning model, LMS. IELTS Writing Task 2: will online learning replace classrooms?", f: "blend (v/n), blended (adj), blended learning (n), hybrid learning (n), e-learning (n)" },
  "distance learning": { m: "distance = khoảng cách → thầy và trò ở xa nhau, học qua mạng hoặc thư.", e: "Sai: far learning → Đúng: distance learning. Sai: study by distance learning course → Đúng: study through a distance learning course.", u: "IELTS Speaking/Writing: advantages of distance learning for working adults. Giáo dục: open university, đào tạo từ xa.", f: "distance learning (n), distance education (n), remote learning (n), online course (n)" },
  "e-learning": { m: "e = electronic (điện tử) → học qua máy tính, Internet.", e: "Sai: elearning (thiếu gạch nối) → Đúng: e-learning. Sai: an e-learning → Đúng: an e-learning course/platform.", u: "IELTS Writing Task 2: e-learning vs traditional classes. Ngành đào tạo doanh nghiệp: e-learning modules, LMS.", f: "e-learning (n), online learning (n), e-learning platform (n), LMS (n), MOOC (n)" },
  "flipped classroom": { m: "flip = lật ngược → xem bài giảng ở nhà, lên lớp làm bài tập, thảo luận.", e: "Sai: flip classroom → Đúng: flipped classroom. Sai: a classroom flipped model → Đúng: the flipped classroom model.", u: "Ngành sư phạm: flipped classroom approach, pre-class videos. IELTS Writing: technology transforms teaching models.", f: "flip (v), flipped (adj), flipped classroom (n), flipped learning (n), blended learning (n)" },
  "learner autonomy": { m: "autonomy = tự chủ (auto: tự) → người học tự đặt mục tiêu, tự chọn cách học.", e: "Sai: learner's autonomous → Đúng: learner autonomy. Sai: develop autonomy of learners → Đúng: develop learner autonomy.", u: "Ngành giảng dạy ngoại ngữ: promote learner autonomy, self-study. IELTS Writing: universities should foster independence.", f: "autonomy (n), autonomous (adj), autonomously (adv), self-directed learning (n), independence (n)" },
  "critical thinking": { m: "critical = phân tích kỹ → không tin ngay, đặt câu hỏi, cân nhắc bằng chứng.", e: "Sai: criticize thinking → Đúng: critical thinking. Nhầm: critical không chỉ là 'chỉ trích'.", u: "IELTS Writing Task 2: schools should teach critical thinking. Ngành giáo dục, tuyển dụng: critical thinking skills.", f: "critic (n), critical (adj), critically (adv), critique (n/v), criticism (n)" },
  "formative assessment": { m: "form (định hình) → đánh giá trong lúc học để 'định hình' lại cách dạy.", e: "Sai: formation assessment → Đúng: formative assessment. Nhầm: formative (trong quá trình) khác summative (cuối kỳ).", u: "Ngành giáo dục: quizzes, feedback, exit tickets. IELTS Writing: continuous assessment vs final exams.", f: "form (v), formative (adj), formative assessment (n), summative assessment (n), feedback (n)" },
  "summative assessment": { m: "sum (tổng) → đánh giá 'tổng kết' cuối kỳ, cho điểm cuối cùng.", e: "Sai: summary assessment → Đúng: summative assessment. Sai: summative assessments is → Đúng: are.", u: "Ngành giáo dục: final exam, end-of-term test. IELTS Writing: should students be judged by one final exam?", f: "sum (n), summative (adj), summative assessment (n), formative assessment (n), final exam (n)" },
  "rubric": { m: "Gốc Latin 'đỏ' (chữ đỏ hướng dẫn) → bảng tiêu chí, mức điểm cho từng phần.", e: "Sai: rubrics of marking (khi chỉ một bảng) → Đúng: a marking rubric. Phát âm /ˈruːbrɪk/.", u: "Ngành giáo dục: grading rubric, band descriptors IELTS là một dạng rubric. Đánh giá bài luận, dự án.", f: "rubric (n), marking scheme (n), band descriptors (n), criteria (n), assessment (n)" },
  "grading": { m: "grade (điểm, bậc) → việc chấm và xếp bài vào các bậc điểm A, B, C.", e: "Sai: grading the students' paper → Đúng: grading students' papers. Anh hay dùng marking.", u: "Ngành giáo dục: grading criteria, grade inflation. IELTS Writing: Should grading be replaced by feedback?", f: "grade (n/v), grading (n), grader (n), marking (n, Anh), grade inflation (n)" },
  "transcript": { m: "trans (qua) + script (viết) → bản 'chép lại' toàn bộ điểm các môn → bảng điểm.", e: "Sai: transcript of score → Đúng: academic transcript. Nhầm: transcript cũng là 'bản ghi lời thoại'.", u: "Hồ sơ du học: official transcript, certified translation. IELTS Listening: bản ghi lời (tapescript).", f: "transcribe (v), transcript (n), transcription (n), academic record (n), diploma (n)" },
  "grade point average": { m: "Điểm (grade point) các môn tính trung bình (average) → GPA, thang 4.0.", e: "Sai: my GPA is 8.0/4.0 → Đúng: my GPA is 3.6 out of 4.0. Sai: average point grade → Đúng: grade point average.", u: "Hồ sơ du học, học bổng: minimum GPA, cumulative GPA. IELTS Speaking: talk about academic achievements.", f: "grade point average/GPA (n), cumulative GPA (n), grade (n), credit (n), honours (n)" },
  "prerequisite": { m: "pre (trước) + requisite (cần thiết) → điều cần có trước khi được học/làm.", e: "Sai: prerequisite of → Đúng: a prerequisite for. Sai: pre-requisite (ít dùng) → Đúng: prerequisite.", u: "Đại học: course prerequisites, Calculus I is a prerequisite for II. IELTS Writing: education is a prerequisite for success.", f: "prerequisite (n/adj), requisite (adj), require (v), requirement (n), corequisite (n)" },
  "elective": { m: "elect (bầu, chọn) → môn sinh viên tự chọn theo sở thích.", e: "Sai: take an elect course → Đúng: take an elective. Sai: optional elective (lặp) → Đúng: an elective.", u: "Đại học: choose electives, elective modules. IELTS Speaking: talk about your favourite subject.", f: "elect (v), election (n), elective (n/adj), optional (adj), compulsory (adj, trái nghĩa)" },
  "compulsory subject": { m: "compulsory = bắt buộc (compel: ép) → môn ai cũng phải học, không được bỏ.", e: "Sai: compulsive subject → Đúng: compulsory subject. Compulsive = ám ảnh, không kiềm chế được.", u: "IELTS Writing Task 2: should art be a compulsory subject? Giáo dục: core subjects, compulsory education.", f: "compel (v), compulsory (adj), compulsion (n), mandatory (adj), elective (n)" },
  "postgraduate": { m: "post (sau) + graduate (tốt nghiệp) → học tiếp sau khi tốt nghiệp đại học.", e: "Sai: post-graduated student → Đúng: postgraduate student. Mỹ hay dùng graduate student.", u: "IELTS Speaking: Do you plan to do postgraduate study? Du học: postgraduate diploma, master's, PhD.", f: "graduate (n/v), graduation (n), postgraduate (adj/n), undergraduate (adj/n), graduate school (n)" },
  "bachelor's degree": { m: "bachelor = cử nhân (cũng là 'chàng độc thân') → bằng đại học đầu tiên, 4 năm.", e: "Sai: bachelor degree of English → Đúng: a bachelor's degree in English. Nhớ dấu sở hữu 's.", u: "IELTS Speaking: I hold a bachelor's degree in economics. Hồ sơ xin việc, du học: BA, BSc.", f: "bachelor's degree (n), BA/BSc (n), undergraduate (n), degree (n), graduate (n/v)" },
  "master's degree": { m: "master = bậc thầy → bằng 'thành thạo' chuyên sâu sau cử nhân.", e: "Sai: master degree in → Đúng: a master's degree in. Sai: study master → Đúng: do a master's.", u: "IELTS Speaking: plans to pursue a master's degree abroad. Du học: MA, MSc, MBA; thesis.", f: "master's degree (n), master's (n), MA/MSc/MBA (n), postgraduate (adj), thesis (n)" },
  "doctorate": { m: "doctor (Latin: người thầy) → học vị cao nhất, viết luận án.", e: "Sai: doctorate degree of → Đúng: a doctorate in. Sai: she is doctorate → Đúng: she holds a doctorate.", u: "Học thuật: earn a doctorate, PhD candidate. IELTS Speaking: talk about higher education plans.", f: "doctor (n), doctorate (n), doctoral (adj), PhD (n), dissertation (n)" },
  "phd candidate": { m: "Candidate = ứng viên: người đã qua kỳ thi tư cách, đang 'ứng cử' cho tấm bằng tiến sĩ.", e: "Sai: a PhD student candidate of → Đúng: a PhD candidate in economics at Hanoi University.", u: "Hồ sơ học bổng, email gửi giáo sư: 'I am a PhD candidate in linguistics'. IELTS Speaking: nói về kế hoạch học lên cao.", f: "PhD student, doctoral candidate, doctoral researcher, ABD (all but dissertation)" },
  "dissertation": { m: "dissert- (bàn luận dài) → bài luận dài, công phu để lấy bằng.", e: "Sai: do a dissertation about → Đúng: write a dissertation on climate policy. Sai: dissertation defence xong rồi submit → Đúng: submit, then defend.", u: "Ngành giáo dục, hồ sơ cao học: dissertation supervisor, dissertation chapter, submit/defend a dissertation. Anh-Anh: dissertation thạc sĩ; Mỹ: luận án tiến sĩ.", f: "dissertation (n), thesis (n), dissertate (v, hiếm)" },
  "thesis defense": { m: "Defense = phòng thủ: bạn đứng 'bảo vệ' luận văn trước hội đồng chất vấn.", e: "Sai: protect my thesis → Đúng: defend my thesis. Sai: thesis defend → Đúng: thesis defense (Anh-Anh: defence).", u: "Lịch học vụ, email khoa: 'Your thesis defense is scheduled for 10 June'. Thường đi với committee, panel, oral defense.", f: "defend (v), defense/defence (n), viva (Anh-Anh), oral examination" },
  "tenure": { m: "ten- (giữ, như 'tenant') → giữ ghế dạy lâu dài, khó bị sa thải.", e: "Sai: get a tenure → Đúng: get tenure / be granted tenure. Sai: tenure teacher → Đúng: tenured professor.", u: "Môi trường đại học Mỹ: tenure track, tenure review, tenured faculty. Cũng dùng chung: 'during his tenure as CEO' = nhiệm kỳ.", f: "tenure (n), tenured (adj), tenure-track (adj), tenant (n, cùng gốc)" },
  "tuition fee": { m: "Tuition = sự dạy dỗ (tutor cùng gốc) → tiền trả cho việc được dạy.", e: "Sai: school fee of university → Đúng: university tuition fees. Sai: pay tuition fee for → Đúng: pay tuition fees for the course.", u: "IELTS Writing Task 2: 'Should university education be free?' – rising tuition fees, tuition-free. Thông báo trường: tuition fee waiver.", f: "tuition (n), tutor (n/v), fees (n), tuition-free (adj), fee waiver" },
  "enrolment": { m: "en- + roll (danh sách) → ghi tên vào sổ danh sách của trường.", e: "Sai: enrolment in university last year (động từ) → Đúng: I enrolled at university last year. Anh-Mỹ viết enrollment.", u: "Báo cáo giáo dục: enrolment rates, school enrolment, enrolment deadline. IELTS Task 1: mô tả biểu đồ số học sinh nhập học.", f: "enrol/enroll (v), enrolment/enrollment (n), enrolled (adj), re-enrol (v)" },
  "entrance exam": { m: "Entrance = lối vào: kỳ thi là 'cửa vào' trường đại học.", e: "Sai: pass the entrance exam to → Đúng: pass the entrance exam for/to Hanoi Medical University. Sai: entry exam (ít dùng) → Đúng: entrance exam.", u: "IELTS Speaking Part 2: kể kỳ thi quan trọng – the national university entrance exam, fierce competition, cram schools.", f: "entrance (n), enter (v), admission test, entrance examination, sit/take an exam" },
  "academic year": { m: "Year tính theo lịch học, không theo lịch dương: thường từ tháng 9 đến tháng 6.", e: "Sai: in academic year 2025 → Đúng: in the 2025–2026 academic year. Sai: school's year → Đúng: academic year.", u: "Thông báo trường, hợp đồng giảng dạy: 'at the start of the academic year', term, semester. IELTS Speaking: nói về lịch học.", f: "school year, semester, term, academic calendar, academically (adv)" },
  "tutorial": { m: "Tutor (gia sư) + -ial → buổi gia sư cho nhóm nhỏ; trên mạng là bài hướng dẫn.", e: "Sai: attend the tutorial lesson online video → Đúng: watch a video tutorial / attend a weekly tutorial.", u: "Đại học Anh, Úc: lecture vs tutorial (nhóm nhỏ thảo luận). Ngành IT: tutorial = bài hướng dẫn từng bước.", f: "tutor (n/v), tutorial (n/adj), tutoring (n), tutee (n)" },
  "professional development": { m: "Develop chính mình về mặt nghề: khóa học, hội thảo giúp giáo viên lên tay nghề.", e: "Sai: professional develop → Đúng: professional development. Sai: join a professional development → Đúng: attend a professional development course.", u: "Ngành giáo dục, nhân sự: PD sessions, continuing professional development (CPD). Hay xuất hiện trong CV, mô tả công việc.", f: "CPD, in-service training, upskilling, career development" },
  "teacher training": { m: "Train teachers: 'đào tạo người đi đào tạo' – ngành sư phạm.", e: "Sai: teachers training college → Đúng: teacher training college. Danh từ đứng trước dùng số ít: teacher.", u: "Chính sách giáo dục: invest in teacher training, pre-service/in-service teacher training. IELTS Writing: giải pháp nâng chất lượng giáo dục.", f: "teacher education, pre-service training, in-service training, pedagogy (n)" },
  "classroom management": { m: "Manage the classroom: giữ trật tự, nề nếp, thời gian như quản lý một 'công ty nhỏ'.", e: "Sai: manage class room → Đúng: classroom management (classroom viết liền). Sai: good management class → Đúng: good classroom management.", u: "Phỏng vấn giáo viên, TESOL/CELTA: classroom management strategies, behaviour management, routines.", f: "behaviour management, classroom routines, discipline (n), manage (v)" },
  "differentiated instruction": { m: "Differentiate = làm cho khác: mỗi nhóm học sinh nhận cách dạy khác nhau.", e: "Sai: different instruction → Đúng: differentiated instruction (phân từ quá khứ). Sai: differentiate teaching for → Đúng: differentiate instruction for.", u: "Giáo án, đánh giá giáo viên: use differentiated instruction for mixed-ability classes, tiered tasks, scaffolding.", f: "differentiate (v), differentiation (n), personalised learning, mixed-ability teaching" },
  "inclusive education": { m: "Include = bao gồm: mọi trẻ, kể cả khuyết tật, học chung một lớp.", e: "Sai: including education → Đúng: inclusive education. Sai: integrate education for disabled → Đúng: inclusive education for children with disabilities.", u: "IELTS Writing Task 2 về bình đẳng giáo dục; báo cáo UNESCO: promote inclusive education, inclusive classrooms.", f: "include (v), inclusion (n), inclusive (adj), inclusivity (n), integration (n)" },
  "special needs": { m: "Needs đặc biệt: học sinh cần hỗ trợ riêng do khuyết tật hay khó khăn học tập.", e: "Sai: special need students → Đúng: students with special needs / special needs students (needs số nhiều).", u: "Ngành giáo dục: special educational needs (SEN), special needs teacher, SENCO. Nói lịch sự, tránh từ miệt thị.", f: "SEN, special education, learning disability, additional needs" },
  "numeracy": { m: "Numer- (số, như 'number') → khả năng làm việc với con số; cặp với literacy.", e: "Sai: calculation skill of children → Đúng: children's numeracy skills. Sai: a numeracy → Đúng: numeracy (không đếm được).", u: "Báo cáo giáo dục, IELTS Writing: literacy and numeracy, basic numeracy, numeracy rates among adults.", f: "numerate (adj), innumerate (adj), numeracy (n), literacy (n), numerical (adj)" },
  "vocational training": { m: "Vocation = nghề (vocal cùng gốc 'tiếng gọi') → học nghề theo 'tiếng gọi' nghề nghiệp.", e: "Sai: vocation training → Đúng: vocational training. Sai: learn a vocational → Đúng: take a vocational course.", u: "IELTS Writing Task 2: university vs vocational training; vocational schools, apprenticeships, practical skills for the job market.", f: "vocation (n), vocational (adj), technical and vocational education (TVET), apprenticeship (n)" },
  "lifelong learning": { m: "Life-long = dài bằng đời người: học không dừng sau tốt nghiệp.", e: "Sai: life long learning → Đúng: lifelong learning (viết liền). Sai: learning lifelong → Đúng: lifelong learning.", u: "IELTS Speaking/Writing: 'Lifelong learning is essential in a changing job market'; online courses, adult education.", f: "lifelong (adj), continuing education, adult education, self-directed learning" },
  "accreditation": { m: "ac- + credit (niềm tin) → được cấp 'tín nhiệm' chính thức về chất lượng.", e: "Sai: the university is accreditation → Đúng: the university is accredited / has received accreditation.", u: "Hồ sơ đại học, du học: international accreditation, AACSB/ABET accreditation, check a program's accreditation status.", f: "accredit (v), accredited (adj), accreditation (n), unaccredited (adj), credential (n)" },
  "research question": { m: "Câu hỏi 'xương sống' mà cả công trình nghiên cứu phải trả lời.", e: "Sai: research questions is → Đúng: the research questions are. Sai: answer for research question → Đúng: address the research question.", u: "Luận văn, đề cương: formulate research questions, RQ1/RQ2, 'This study addresses the following research questions'.", f: "hypothesis (n), research objective, research aim, inquiry (n)" },
  "research gap": { m: "Gap = khoảng hở: chỗ trống mà các nghiên cứu trước chưa lấp.", e: "Sai: fill in the gap of research → Đúng: fill/address a research gap in the literature.", u: "Phần mở đầu bài báo, luận văn: identify a research gap, 'little attention has been paid to…'.", f: "knowledge gap, gap in the literature, unexplored area, under-researched (adj)" },
  "literature review": { m: "Literature ở đây là 'các công trình đã công bố', không phải văn chương.", e: "Sai: review literature of → Đúng: a literature review on X. Sai: review of literatures → Đúng: review of the literature (không đếm được).", u: "Chương 2 luận văn: conduct a systematic literature review, synthesise prior studies, 'the literature suggests…'.", f: "lit review, systematic review, meta-analysis, review (v/n)" },
  "research proposal": { m: "Propose = đề xuất: bản 'chào hàng' nghiên cứu để xin duyệt hay xin tài trợ.", e: "Sai: write a research propose → Đúng: write a research proposal. Sai: proposal about → Đúng: proposal for/on.", u: "Hồ sơ PhD, xin grant: submit a research proposal, outline methodology, timeline and budget.", f: "propose (v), proposal (n), research plan, study protocol" },
  "qualitative research": { m: "Quality = chất → nghiên cứu về 'chất': phỏng vấn, quan sát, ý nghĩa.", e: "Sai: qualitative research with 500 surveys statistics → Đúng: quantitative research uses statistics; qualitative uses interviews.", u: "Phương pháp luận: semi-structured interviews, focus groups, thematic analysis, small purposive samples.", f: "qualitative (adj), qualitatively (adv), quality (n), quantitative research (đối lập)" },
  "quantitative research": { m: "Quantity = lượng → nghiên cứu về 'lượng': con số, khảo sát, thống kê.", e: "Sai: quantity research → Đúng: quantitative research. Chú ý phát âm: QUAN-ti-ta-tive.", u: "Phương pháp luận: large-scale surveys, regression analysis, hypothesis testing. IELTS Task 1 dùng dữ liệu kiểu này.", f: "quantitative (adj), quantify (v), quantity (n), quantitatively (adv)" },
  "mixed methods": { m: "Mix = trộn: kết hợp cả định lượng lẫn định tính trong một nghiên cứu.", e: "Sai: mix method research → Đúng: mixed-methods research (có gạch nối khi làm tính từ).", u: "Luận văn, bài báo: a mixed-methods design, triangulation of survey and interview data.", f: "mixed-methods (adj), triangulation (n), multi-method approach" },
  "research ethics": { m: "Ethics = đạo đức: các 'luật chơi' bảo vệ người tham gia nghiên cứu.", e: "Sai: research ethic is → Đúng: research ethics are/is (luôn có -s). Sai: ethics approve → Đúng: ethics approval.", u: "Đề cương nghiên cứu: obtain ethics approval, informed consent, anonymity, ethics committee/IRB.", f: "ethical (adj), unethical (adj), ethically (adv), ethics committee, informed consent" },
  "sampling": { m: "Sample (mẫu) + -ing → hành động chọn ra 'mẫu thử' đại diện cho cả tổng thể.", e: "Sai: sampling size → Đúng: sample size. Sai: random sample method → Đúng: random sampling method.", u: "Chương phương pháp: random sampling, convenience sampling, stratified sampling, sampling bias.", f: "sample (n/v), sampling (n), sampler (n), sampling frame" },
  "sample size": { m: "Size của 'mẫu': bao nhiêu người tham gia khảo sát.", e: "Sai: the sample size is too few → Đúng: the sample size is too small. Sai: sampling size → Đúng: sample size.", u: "Bài báo khoa học: 'a sample size of 300 respondents', limitation: small sample size limits generalisability.", f: "sample (n), n (ký hiệu), population (n), respondents (n)" },
  "data collection": { m: "Collect data: giai đoạn 'đi gom' số liệu trước khi phân tích.", e: "Sai: collect datas → Đúng: collect data (data không thêm -s). Sai: data collecting process → Đúng: data collection process.", u: "Luận văn: data collection instruments, questionnaires, interviews; 'Data were collected over three months'.", f: "collect (v), collection (n), data gathering, fieldwork (n)" },
  "data analysis": { m: "Analyse = tách nhỏ ra xem: mổ xẻ số liệu để tìm ý nghĩa.", e: "Sai: analysis the data → Đúng: analyse/analyze the data (analysis là danh từ). Sai: data analyse → Đúng: data analysis.", u: "Chương kết quả, tin tuyển dụng: data analysis using SPSS/Python, data analyst. IELTS Task 1 cũng là phân tích dữ liệu.", f: "analyse/analyze (v), analysis (n), analyses (n, pl), analyst (n), analytical (adj)" },
  "statistical significance": { m: "Significant = đáng kể: kết quả 'không phải do may rủi', thường p < 0.05.", e: "Sai: the result is significance → Đúng: the result is statistically significant / reached statistical significance.", u: "Bài báo định lượng: p-value, 'statistically significant difference (p < .01)'. Phân biệt với ý nghĩa thực tiễn.", f: "significant (adj), significance (n), statistically (adv), p-value, insignificant (adj)" },
  "correlation": { m: "cor- (cùng) + relation (quan hệ) → hai biến 'cùng đi với nhau'.", e: "Sai: correlation of A with B prove → Đúng: a correlation between A and B does not prove causation.", u: "IELTS Writing Task 1/2 và bài báo: a strong positive correlation between income and education.", f: "correlate (v), correlation (n), correlated (adj), correlational (adj), coefficient (n)" },
  "causation": { m: "Cause (gây ra) + -ation: A thật sự là nguyên nhân sinh ra B.", e: "Sai: correlation mean causation → Đúng: correlation does not imply causation. Sai: causation of → Đúng: causation between/the cause of.", u: "Viết học thuật, phản biện số liệu: establish causation, causal relationship, confounding variables.", f: "cause (v/n), causal (adj), causality (n), causative (adj)" },
  "academic writing": { m: "Writing kiểu 'học thuật': trang trọng, có dẫn chứng, khách quan.", e: "Sai: write academic → Đúng: write academically / do academic writing. Tránh: I think, don't trong bài học thuật.", u: "IELTS Writing Task 2, luận văn: formal register, hedging (may, suggest), cohesive devices, citations.", f: "academic (adj/n), academically (adv), academia (n), scholarly writing" },
  "citation": { m: "Cite = trích dẫn → citation: 'ghi nguồn' ý tưởng bạn mượn.", e: "Sai: cite from → Đúng: cite Smith (2020). Sai: citation the author → Đúng: cite the author.", u: "Viết bài báo: in-text citation, citation style (APA, Harvard), citation count. Google Scholar đếm citations.", f: "cite (v), citation (n), quote (v), quotation (n), reference (n/v)" },
  "reference list": { m: "Danh sách các nguồn đã thật sự trích dẫn trong bài, đặt ở cuối.", e: "Sai: references list → Đúng: reference list. Sai: list sources not cited → Đúng: only include works cited in the text.", u: "Luận văn, bài báo APA: format the reference list alphabetically, include DOIs. Khác bibliography (có cả tài liệu đọc thêm).", f: "references (n), bibliography (n), works cited, reference (v)" },
  "bibliography": { m: "biblio- (sách, như 'Bible') + -graphy (viết) → bảng ghi các sách đã dùng.", e: "Sai: bibliography only for cited works → Đúng: a bibliography may also list works consulted but not cited.", u: "Luận văn, sách chuyên khảo: annotated bibliography, compile a bibliography. Phong cách Chicago hay dùng.", f: "bibliographic (adj), bibliographer (n), reference list, works cited" },
  "plagiarism": { m: "Gốc Latin 'plagiarius' = kẻ bắt cóc → 'bắt cóc' chữ của người khác.", e: "Sai: do plagiarism → Đúng: commit plagiarism / plagiarise. Sai: plagiarism the essay → Đúng: plagiarise the essay.", u: "Quy chế học thuật: plagiarism checker (Turnitin), self-plagiarism, academic misconduct.", f: "plagiarise/plagiarize (v), plagiarism (n), plagiarist (n), plagiarised (adj)" },
  "academic integrity": { m: "Integrity = sự nguyên vẹn (integer) → giữ trung thực, không gian lận trong học tập.", e: "Sai: violate academic integration → Đúng: violate academic integrity. Integrity ≠ integration.", u: "Quy chế trường, đề cương môn: academic integrity policy, breach of academic integrity, cheating, plagiarism.", f: "integrity (n), honesty (n), academic honesty, misconduct (n)" },
  "academic journal": { m: "Journal = 'nhật ký' của giới khoa học: nơi công bố nghiên cứu có bình duyệt.", e: "Sai: publish on a journal → Đúng: publish in a journal. Sai: magazine khoa học → Đúng: peer-reviewed journal.", u: "Giảng viên, nghiên cứu sinh: peer-reviewed journal, Scopus-indexed journal, submit to a journal.", f: "journal (n), journalism (n, khác nghĩa), periodical (n), publication (n)" },
  "impact factor": { m: "Đo 'sức tác động': trung bình mỗi bài của tạp chí được trích dẫn bao nhiêu lần.", e: "Sai: journal has high impact → Đúng: the journal has a high impact factor (IF of 5.2).", u: "Đánh giá công bố, xét tuyển giảng viên: Q1 journal, impact factor, h-index, Journal Citation Reports.", f: "IF, h-index, citation metrics, journal ranking, quartile (Q1–Q4)" },
  "manuscript": { m: "manu- (tay) + script (viết) → bản viết tay; nay là bản thảo gửi tạp chí.", e: "Sai: send the paper manuscript to publish → Đúng: submit the manuscript for publication.", u: "Quy trình công bố: manuscript submission, revised manuscript, manuscript under review. Ngành xuất bản cũng dùng.", f: "manuscript (n), manual (adj, cùng gốc), draft (n), typescript (n)" },
  "conference paper": { m: "Paper trình bày tại hội thảo, thường ngắn và nhanh hơn bài tạp chí.", e: "Sai: present a paper at the conference room → Đúng: present a paper at a conference. Sai: conference's paper → Đúng: conference paper.", u: "Lý lịch khoa học: conference proceedings, call for papers, present a conference paper, poster session.", f: "proceedings (n), presentation (n), abstract (n), journal article" },
  "research grant": { m: "Grant = ban cấp: số tiền được 'trao' để thực hiện đề tài.", e: "Sai: receive a research fund grant money → Đúng: receive/win a research grant from the foundation.", u: "Giảng viên, nhà khoa học: apply for a research grant, grant proposal, funding body, grant holder.", f: "grant (n/v), funding (n), fellowship (n), scholarship (n), grantee (n)" },
  "principal investigator": { m: "Principal = chính, investigator = người điều tra → người 'cầm trịch' cả đề tài.", e: "Sai: principle investigator → Đúng: principal investigator (principal = chính, principle = nguyên tắc).", u: "Hồ sơ grant, thử nghiệm lâm sàng: the PI is responsible for the project; co-investigator, research team.", f: "PI, co-investigator (Co-I), project leader, investigate (v)" },
  "pilot study": { m: "Pilot = phi công 'bay thử' trước: chạy thử quy mô nhỏ trước khi làm thật.", e: "Sai: test study before → Đúng: conduct a pilot study before the main study.", u: "Phương pháp nghiên cứu: pilot the questionnaire, pilot study results, refine instruments. Cũng có 'pilot project' trong kinh doanh.", f: "pilot (v/n/adj), pilot test, feasibility study, trial run" },
  "longitudinal study": { m: "Longitude = kinh độ (đường dài) → theo dõi cùng đối tượng suốt thời gian dài.", e: "Sai: long study → Đúng: longitudinal study. Đối lập: cross-sectional study (một thời điểm).", u: "Nghiên cứu y tế, giáo dục: a 20-year longitudinal study tracking participants; follow-up waves.", f: "longitudinal (adj), cross-sectional study, cohort study, panel data" },
  "academic advisor": { m: "Advisor = người cho lời khuyên về chọn môn, lộ trình học.", e: "Sai: advisor of academic → Đúng: academic advisor. Lưu ý: advisor/adviser đều đúng; advice là danh từ, advise là động từ.", u: "Đại học Mỹ: meet your academic advisor to plan courses; khác supervisor (hướng dẫn luận văn).", f: "advise (v), advice (n), advisor/adviser (n), advisory (adj), supervisor (n)" },
  "extracurricular activities": { m: "extra- (ngoài) + curricular (chương trình) → hoạt động ngoài chương trình học.", e: "Sai: extra curriculum activities → Đúng: extracurricular activities (viết liền, tính từ -ar).", u: "IELTS Speaking Part 1/3: clubs, sports, volunteering; hồ sơ du học: list extracurricular activities.", f: "extracurricular (adj), curriculum (n), curricular (adj), co-curricular (adj)" },
  "alumni": { m: "Số nhiều Latin: alumnus (nam), alumna (nữ) → alumni là nhiều cựu sinh viên.", e: "Sai: an alumni → Đúng: an alumnus / a graduate. Sai: alumnis → Đúng: alumni (đã là số nhiều).", u: "Trường đại học: alumni network, alumni association, notable alumni; tuyển sinh hay dùng để quảng bá.", f: "alumnus (n, sg), alumna (n, sg, nữ), alumnae (n, pl, nữ), alum (n, khẩu ngữ)" },
  "academic probation": { m: "Probation = thời gian 'thử thách': điểm kém nên bị theo dõi, cảnh cáo.", e: "Sai: be in academic probation → Đúng: be on academic probation.", u: "Quy chế đại học Mỹ: GPA below 2.0 leads to academic probation; risk of dismissal.", f: "probation (n), probationary (adj), academic warning, academic suspension" },
  "dropout rate": { m: "Drop out = rơi ra khỏi: tỷ lệ người 'rơi' khỏi trường giữa chừng.", e: "Sai: drop out rate is high of students → Đúng: the student dropout rate is high. Động từ: drop out of school.", u: "IELTS Writing Task 1/2: high dropout rates in rural areas; báo cáo giáo dục, chính sách.", f: "drop out (v), dropout (n), attrition rate, retention rate" },
  "standardized test": { m: "Standard = chuẩn: mọi thí sinh cùng đề, cùng cách chấm.", e: "Sai: standard test → Đúng: standardized test. Anh-Anh viết standardised.", u: "IELTS Writing Task 2: pros and cons of standardized tests; SAT, GRE, IELTS là ví dụ.", f: "standardize (v), standardization (n), standard (n/adj), high-stakes testing" },
  "competency": { m: "Compete (cạnh tranh) → có năng lực đủ để 'cạnh tranh', làm được việc.", e: "Sai: have competency of English → Đúng: have competency in English. Số nhiều: competencies.", u: "Giáo dục theo năng lực, nhân sự: competency-based curriculum, core competencies, competency framework.", f: "competent (adj), competence (n), competency (n), incompetent (adj)" },
  "higher education": { m: "Higher = 'bậc cao hơn' phổ thông: đại học, cao học.", e: "Sai: high education → Đúng: higher education. Sai: a higher education → Đúng: higher education (thường không có a).", u: "IELTS Writing Task 2: access to higher education, higher education institutions (HEIs), free higher education.", f: "tertiary education, university education, post-secondary education" },
  "primary education": { m: "Primary = đầu tiên: bậc học đầu tiên của trẻ.", e: "Sai: primary school education level one → Đúng: primary education. Mỹ thường nói elementary school.", u: "IELTS Writing: universal primary education, compulsory education; báo cáo UNESCO, World Bank.", f: "primary school, elementary school (Mỹ), basic education" },
  "secondary education": { m: "Secondary = thứ hai: bậc thứ hai sau tiểu học, gồm THCS và THPT.", e: "Sai: second education → Đúng: secondary education. Sai: secondary school for university → Đúng: secondary school (trung học).", u: "IELTS Writing Task 1/2: secondary school enrolment, lower/upper secondary, completion rates.", f: "secondary school, high school (Mỹ), lower secondary, upper secondary" },
  "early childhood education": { m: "Early childhood = những năm đầu đời (0–8 tuổi): mầm non, mẫu giáo.", e: "Sai: early child education → Đúng: early childhood education. Sai: kindergarden → Đúng: kindergarten.", u: "IELTS Writing: benefits of early childhood education; ngành mầm non: ECE teacher, preschool.", f: "ECE, preschool (n), kindergarten (n), nursery (n), early years" },
  "education policy": { m: "Policy = chính sách: 'luật chơi' do nhà nước đặt cho hệ thống giáo dục.", e: "Sai: educational politics → Đúng: education policy (policy = chính sách, politics = chính trị).", u: "IELTS Writing Task 2, báo cáo nhà nước: government education policy, policymakers, policy reform.", f: "policymaker (n), policy (n), educational policy, regulation (n)" },
  "educational reform": { m: "Re- (lại) + form (định hình) → định hình lại hệ thống giáo dục.", e: "Sai: reform of education are → Đúng: educational reform is / reforms are. Sai: reformation → Đúng: reform.", u: "IELTS Writing Task 2: curriculum reform, implement educational reforms, resistance to reform.", f: "reform (n/v), reformer (n), education reform, overhaul (n/v)" },
  "learning management system": { m: "Hệ thống 'quản lý việc học' trên mạng: giao bài, nộp bài, chấm điểm.", e: "Sai: learning manage system → Đúng: learning management system (LMS). Sai: upload on LMS → Đúng: upload to the LMS.", u: "Ngành giáo dục, e-learning: Moodle, Canvas, Google Classroom là LMS; post materials on the LMS.", f: "LMS, e-learning platform, virtual learning environment (VLE)" },
  "mooc": { m: "Massive Open Online Course: 'Massive' = hàng ngàn người học cùng lúc, miễn phí hoặc rẻ.", e: "Sai: learn a MOOCs → Đúng: take a MOOC on Coursera. Đọc là /muːk/.", u: "IELTS Speaking/Writing: online learning – MOOCs make education accessible; ví dụ Coursera, edX.", f: "MOOCs (pl), online course, e-learning, distance learning" },
  "peer feedback": { m: "Peer = bạn ngang hàng: bạn cùng lớp góp ý bài cho nhau.", e: "Sai: give feedbacks to peers → Đúng: give peer feedback (feedback không đếm được).", u: "Lớp học viết, đánh giá: peer review, peer assessment, constructive peer feedback.", f: "peer review, peer assessment, feedback (n), peer (n)" },
  "group work": { m: "Work theo nhóm: nhiều người cùng làm một nhiệm vụ.", e: "Sai: do a group works → Đúng: do group work / a group project. Sai: work group (khác nghĩa) → Đúng: group work.", u: "IELTS Speaking: 'Do you prefer working alone or in groups?'; teamwork, collaboration, group assignment.", f: "teamwork (n), collaboration (n), group project, pair work" },
  "oral presentation": { m: "Oral = bằng miệng (cùng gốc 'os' = miệng): trình bày nói trước lớp.", e: "Sai: make an oral presentation about a slide → Đúng: give/deliver an oral presentation on the topic.", u: "Đánh giá đại học, hội thảo: give an oral presentation, Q&A session, presentation skills; IELTS Speaking Part 2.", f: "orally (adv), oral (adj), presentation (n), present (v), presenter (n)" },
  "invigilator": { m: "in- + vigil (canh thức) → người 'thức canh' phòng thi.", e: "Sai: supervisor of exam room → Đúng: invigilator (Anh-Anh) / proctor (Mỹ). Sai: invigilate an exam room → Đúng: invigilate an exam.", u: "Ngày thi IELTS: follow the invigilator's instructions; trường học: exam invigilation duties.", f: "invigilate (v), invigilation (n), proctor (n/v, Mỹ), examiner (n)" },
  "mock exam": { m: "Mock = giả, nhái: bài thi 'giả' giống hệt thi thật để luyện.", e: "Sai: test exam trial → Đúng: mock exam / practice test. Sai: make a mock exam → Đúng: take/sit a mock exam.", u: "Luyện thi IELTS/TOEIC: take a full mock test under exam conditions; trường Anh: mocks.", f: "mock (adj/n), mock test, practice test, trial exam, mocks (n, pl)" },
  "academic calendar": { m: "Calendar 'học thuật': lịch các mốc khai giảng, thi, nghỉ của trường.", e: "Sai: school's timetable year → Đúng: academic calendar. Timetable = thời khóa biểu hằng tuần.", u: "Website đại học: check the academic calendar for registration and exam dates; term dates.", f: "academic year, timetable (n), term dates, semester schedule" },
  "course registration": { m: "Register = ghi tên: đăng ký môn học mỗi kỳ.", e: "Sai: register course → Đúng: register for a course. Sai: course register period → Đúng: course registration period.", u: "Đại học: course registration opens on…, add/drop period, registration portal, prerequisites.", f: "register (v), registration (n), registrar (n), enrol (v), add/drop" },
  "visiting scholar": { m: "Visit = đến thăm: học giả 'đến thăm' làm việc một thời gian ở trường khác.", e: "Sai: visit scholar → Đúng: visiting scholar. Sai: scholar visiting at → Đúng: a visiting scholar at Harvard.", u: "Hợp tác học thuật: host a visiting scholar, visiting professor, visiting researcher programme.", f: "visiting professor, visiting fellow, scholar (n), scholarly (adj), scholarship (n)" },
  "research assistant": { m: "Assistant = người trợ giúp: người hỗ trợ giáo sư thu thập, xử lý dữ liệu.", e: "Sai: assistant research → Đúng: research assistant (RA). Sai: work as research assistant → Đúng: work as a research assistant.", u: "CV nghiên cứu sinh, tuyển dụng đại học: RA position, graduate research assistantship.", f: "RA, assistantship (n), assist (v), assistance (n), research associate" },
  "teaching assistant": { m: "Trợ giúp việc dạy: chấm bài, dạy nhóm nhỏ, hỗ trợ giảng viên.", e: "Sai: assistant teacher of lecturer → Đúng: teaching assistant (TA). Sai: be a TA of the course → Đúng: be a TA for the course.", u: "Đại học Mỹ: TA sessions, office hours; trường phổ thông Anh: teaching assistant hỗ trợ giáo viên.", f: "TA, teaching assistantship, tutor (n), graduate assistant" },
  "scientific article": { m: "Article = bài viết: bài công bố kết quả nghiên cứu khoa học.", e: "Sai: a science article on a newspaper (khác nghĩa) → Đúng: a scientific article in a peer-reviewed journal.", u: "Giới nghiên cứu: publish a scientific article, research article, review article; IMRaD structure.", f: "research article, journal article, scientific paper, science (n), scientist (n)" },
  "co-author": { m: "co- (cùng) + author: người cùng viết, tên đứng chung trên bài báo.", e: "Sai: author together with Dr Lan → Đúng: co-author a paper with Dr Lan. Sai: co-author of two → Đúng: co-author of two papers.", u: "Công bố khoa học: first author, corresponding author, co-authored paper; danh sách tác giả.", f: "co-author (n/v), authorship (n), co-authored (adj), corresponding author" },
  "open access": { m: "Mở cửa 'truy cập': ai cũng đọc miễn phí, không cần trả phí đăng ký.", e: "Sai: open access the paper → Đúng: publish the paper open access / in an open-access journal.", u: "Xuất bản khoa học: open-access journal, article processing charge (APC), paywall.", f: "open-access (adj), paywall (n), subscription journal, APC" },
  "learning style": { m: "Style = kiểu: kiểu học hợp với mình, ví dụ nghe, nhìn, vận động.", e: "Sai: my learning style is learn by see → Đúng: I'm a visual learner / I learn best by seeing.", u: "IELTS Speaking Part 1/3: 'How do you prefer to learn?'; visual, auditory, kinaesthetic learners.", f: "visual learner, auditory learner, kinaesthetic learner, learning preference" },
  "academic performance": { m: "Performance = thành tích: 'màn trình diễn' của học sinh qua điểm số.", e: "Sai: academic result performance is good → Đúng: her academic performance is excellent / she performs well academically.", u: "IELTS Writing Task 2: factors affecting academic performance, e.g. sleep, screen time, family support.", f: "perform (v), performance (n), academic achievement, grades (n), GPA" },
  "supply chain management": { m: "Supply chain = 'dây xích' nối nhà cung cấp → nhà máy → kho → khách; quản lý cả sợi xích.", e: "Sai: supply chains management → Đúng: supply chain management (SCM). Sai: manage the supply → Đúng: manage the supply chain.", u: "Ngành logistics, tuyển dụng: SCM specialist, end-to-end supply chain visibility, supply chain disruption.", f: "SCM, supply chain (n), supplier (n), logistics management, procurement (n)" },
  "freight forwarder": { m: "Forward = chuyển tiếp: bên 'chuyển tiếp' hàng, thuê tàu, làm chứng từ thay chủ hàng.", e: "Sai: freight forwarding company is forwarder of ship → Đúng: the freight forwarder books space with the shipping line.", u: "Ngành xuất nhập khẩu: forwarder issues house B/L (HBL), quotes ocean freight, arranges customs and trucking.", f: "forward (v), forwarding (n), forwarder (n), NVOCC, logistics provider" },
  "shipping line": { m: "Line = tuyến: hãng sở hữu tàu chạy các tuyến cố định.", e: "Sai: ship line → Đúng: shipping line / carrier. Sai: book with the forwarder's ship → Đúng: book space with the shipping line.", u: "Logistics: shipping line issues master B/L (MBL); ví dụ Maersk, MSC; vessel schedule, booking confirmation.", f: "carrier (n), ocean carrier, liner (n), vessel operator" },
  "shipper": { m: "Ship = gửi hàng → shipper là người gửi (người bán), không phải người giao hàng.", e: "Sai: shipper = người giao hàng xe máy → Đúng: courier/delivery rider. Shipper là người gửi hàng trên B/L.", u: "Vận đơn, hợp đồng: shipper's name and address, shipper's load and count (SLAC).", f: "ship (v), shipment (n), shipping (n), consignor (n, đồng nghĩa)" },
  "consignee": { m: "Đuôi -ee = người nhận (như employee): người được gửi hàng tới.", e: "Sai: consigner nhận hàng → Đúng: the consignee receives the goods; consignor sends them.", u: "Vận đơn: consignee field, 'to order' B/L, consignee clears customs at destination.", f: "consign (v), consignor (n), consignment (n), consignee (n)" },
  "notify party": { m: "Notify = báo tin: bên được hãng tàu 'báo' khi hàng cập cảng.", e: "Sai: notice party → Đúng: notify party. Sai: notify party is always owner → Đúng: it may differ from the consignee.", u: "Ô trên B/L: 'Notify party: same as consignee'; quan trọng khi vận đơn theo lệnh ngân hàng.", f: "notify (v), notification (n), arrival notice, consignee (n)" },
  "teu": { m: "Twenty-foot Equivalent Unit: lấy một công-te-nơ 20 feet làm 'đơn vị chuẩn'.", e: "Sai: a 40-foot container is 1 TEU → Đúng: a 40-foot container is 2 TEUs (1 FEU).", u: "Logistics, báo cáo cảng: port throughput of 5 million TEU, vessel capacity 20,000 TEU.", f: "FEU (forty-foot), container (n), throughput (n), slot (n)" },
  "fcl": { m: "Full Container Load: một chủ hàng 'bao trọn' cả công-te-nơ.", e: "Sai: ship FCL with other shippers → Đúng: FCL is for one shipper; sharing a container is LCL.", u: "Báo giá cước: FCL rate per 20'/40', FCL vs LCL decision based on volume (thường > 15 CBM).", f: "FCL (n/adj), LCL (đối lập), full container load, container (n)" },
  "lcl": { m: "Less than Container Load: hàng ít, 'ghép chung' với hàng người khác.", e: "Sai: LCL charge by container → Đúng: LCL is charged per CBM or revenue ton.", u: "Xuất nhập khẩu SME: LCL shipment, CFS charges, consolidation by forwarder.", f: "LCL (n/adj), FCL (đối lập), consolidation (n), groupage (n)" },
  "consolidation": { m: "con- (cùng) + solid (đặc) → gom nhiều lô lẻ 'đặc lại' thành một.", e: "Sai: consolidate cargos → Đúng: consolidate cargo/shipments. Sai: consolidator nhận hàng → Đúng: consolidator gom hàng.", u: "Logistics: LCL consolidation at CFS, consolidated shipment, consolidation reduces freight cost.", f: "consolidate (v), consolidated (adj), consolidator (n), deconsolidation (n)" },
  "bill of lading": { m: "Lade = chất hàng (load) → 'giấy chất hàng' lên tàu, cũng là chứng từ sở hữu.", e: "Sai: bill of loading → Đúng: bill of lading (B/L). Số nhiều: bills of lading.", u: "Xuất nhập khẩu: original B/L, telex release, surrendered B/L, on-board B/L; cần để nhận hàng.", f: "B/L, MBL, HBL, seaway bill, laden (adj, cùng gốc)" },
  "air waybill": { m: "Waybill = giấy đi đường: chứng từ đi kèm lô hàng máy bay.", e: "Sai: air bill of lading → Đúng: air waybill (AWB); AWB không phải chứng từ sở hữu.", u: "Hàng không: MAWB, HAWB, AWB number to track cargo, issued by airline or agent.", f: "AWB, MAWB, HAWB, waybill (n), sea waybill" },
  "commercial invoice": { m: "Hóa đơn 'thương mại': ghi giá bán thật để tính thuế và thanh toán.", e: "Sai: commerce invoice → Đúng: commercial invoice. Sai: invoice to customs fake price → Đúng: declare the true value.", u: "Bộ chứng từ: commercial invoice, packing list, B/L, C/O; dùng khai hải quan và L/C.", f: "invoice (n/v), invoicing (n), proforma invoice, commerce (n)" },
  "proforma invoice": { m: "Pro forma (Latin) = 'cho có mẫu': hóa đơn nháp gửi trước khi giao hàng.", e: "Sai: pay by proforma invoice is final → Đúng: a proforma invoice is a quotation, not a demand for tax purposes.", u: "Giao dịch: send a PI for deposit, open L/C based on PI; dùng xin giấy phép nhập khẩu.", f: "PI, pro forma (adj), quotation (n), commercial invoice" },
  "packing list": { m: "List cách 'đóng gói': mỗi kiện chứa gì, nặng bao nhiêu.", e: "Sai: package list → Đúng: packing list. Sai: packing list has price → Đúng: it shows quantities and weights, not prices.", u: "Bộ chứng từ, kiểm hóa: carton numbers, gross/net weight, dimensions khớp với invoice.", f: "pack (v), packing (n), package (n), packaging (n), packer (n)" },
  "certificate of origin": { m: "Giấy 'khai sinh' của hàng: chứng minh hàng được sản xuất ở nước nào.", e: "Sai: certificate of original → Đúng: certificate of origin (C/O). Sai: C/O form → Đúng: C/O form D/E.", u: "Xuất nhập khẩu: C/O form D (ATIGA), form E (ACFTA) để hưởng thuế ưu đãi.", f: "C/O, origin (n), originate (v), rules of origin" },
  "telegraphic transfer": { m: "Telegraph = điện báo: xưa chuyển tiền bằng 'điện', nay là chuyển khoản quốc tế.", e: "Sai: pay by TT transfer → Đúng: pay by T/T / telegraphic transfer. Sai: TT in advanced → Đúng: T/T in advance.", u: "Điều kiện thanh toán: 30% T/T deposit, 70% T/T against copy B/L; SWIFT transfer.", f: "T/T, wire transfer, bank transfer, SWIFT, remittance (n)" },
  "documents against payment": { m: "Trả tiền rồi mới 'đổi' lấy chứng từ để nhận hàng.", e: "Sai: document against pay → Đúng: documents against payment (D/P). Khác D/A: chấp nhận thanh toán.", u: "Thanh toán quốc tế: D/P at sight, collection through banks, rẻ hơn L/C nhưng rủi ro hơn.", f: "D/P, D/A (documents against acceptance), documentary collection, L/C" },
  "payment terms": { m: "Terms = điều khoản: thỏa thuận trả tiền khi nào, bằng cách nào.", e: "Sai: payment term is 30 days net → Đúng: payment terms are net 30. Sai: pay term → Đúng: payment terms.", u: "Hợp đồng, TOEIC Part 7: net 30, 50% deposit, L/C at sight, negotiate payment terms.", f: "terms of payment, net 30, credit terms, due date" },
  "incoterms": { m: "International Commercial Terms: bộ 'luật chung' chia rủi ro, chi phí giữa bán và mua.", e: "Sai: incoterm 2020 FOB → Đúng: FOB Hai Phong, Incoterms 2020 (ghi cảng và phiên bản).", u: "Hợp đồng ngoại thương: chọn FOB, CIF, EXW, DDP; ICC ban hành, phiên bản 2020.", f: "Incoterms 2020, ICC, trade terms, FOB, CIF, EXW, DDP" },
  "fob": { m: "Free On Board: người bán lo đến khi hàng 'lên boong tàu', rủi ro chuyển sang người mua.", e: "Sai: FOB Los Angeles cho hàng xuất từ VN → Đúng: FOB Ho Chi Minh City (ghi cảng xếp hàng).", u: "Báo giá xuất khẩu: FOB price, FOB Hai Phong; người mua thuê tàu, mua bảo hiểm.", f: "FOB, FCA (gần nghĩa), CIF, Incoterms" },
  "cif": { m: "Cost + Insurance + Freight: người bán trả tiền hàng, bảo hiểm và cước đến cảng đích.", e: "Sai: CIF nghĩa người bán chịu rủi ro đến đích → Đúng: risk passes when goods are on board at origin.", u: "Hợp đồng nhập khẩu: CIF Hai Phong, trị giá tính thuế thường dựa trên CIF.", f: "CIF, CFR (không bảo hiểm), CIP, Incoterms" },
  "exw": { m: "Ex Works = 'giao tại xưởng': người bán chỉ để hàng ở cửa nhà máy.", e: "Sai: EXW seller loads truck and clears export → Đúng: under EXW the buyer handles loading and export clearance.", u: "Báo giá: EXW price thấp nhất, người mua lo mọi chi phí; rủi ro thủ tục xuất khẩu.", f: "EXW, ex-works (adj), FCA, Incoterms" },
  "ddp": { m: "Delivered Duty Paid: người bán lo 'trọn gói' tới cửa người mua, kể cả thuế nhập.", e: "Sai: DDP buyer pays import duty → Đúng: under DDP the seller pays import duties and taxes.", u: "Thương mại điện tử, giao hàng quốc tế: DDP shipping, door-to-door, seller bears the most risk.", f: "DDP, DAP (chưa nộp thuế), DPU, Incoterms" },
  "customs clearance": { m: "Clear = làm sạch, gỡ: 'gỡ' hàng khỏi sự giữ lại của hải quan.", e: "Sai: clear the customs for → Đúng: clear goods through customs / complete customs clearance.", u: "Logistics: import/export customs clearance, clearance documents, delayed clearance; dịch vụ khai thuê.", f: "clear (v), clearance (n), customs broker, declaration (n)" },
  "customs declaration": { m: "Declare = khai báo: tờ khai 'nói rõ' hàng gì, giá trị bao nhiêu.", e: "Sai: declare customs form → Đúng: file/submit a customs declaration. Sai: custom declaration → Đúng: customs declaration.", u: "Xuất nhập khẩu: VNACCS e-declaration, declaration number, green/yellow/red channel.", f: "declare (v), declaration (n), declarant (n), customs (n)" },
  "customs broker": { m: "Broker = người môi giới: chuyên gia 'làm hộ' thủ tục hải quan.", e: "Sai: custom broker → Đúng: customs broker (customs có -s khi là hải quan).", u: "Logistics: hire a licensed customs broker, broker fees, đại lý hải quan khai báo thay chủ hàng.", f: "brokerage (n), broker (n/v), customs agent, clearing agent" },
  "hs code": { m: "Harmonized System: 'mã số chung' toàn thế giới cho mỗi loại hàng.", e: "Sai: wrong HS code no problem → Đúng: an incorrect HS code can lead to wrong duty and penalties.", u: "Khai hải quan: classify goods under HS code 8471.30, tra biểu thuế, xác định thuế suất.", f: "tariff code, commodity code, classification (n), HTS (Mỹ)" },
  "import duty": { m: "Duty = nghĩa vụ phải đóng: tiền 'phải nộp' khi đưa hàng vào nước.", e: "Sai: import tax duty fee → Đúng: import duty. Sai: pay duty for → Đúng: pay duty on imported goods.", u: "Logistics, kinh tế: import duty rate, duty-free, tính trên trị giá CIF; IELTS Writing về thương mại.", f: "duty (n), dutiable (adj), duty-free (adj), tariff (n), customs duty" },
  "vat": { m: "Value Added Tax: đánh vào phần 'giá trị tăng thêm' ở mỗi khâu.", e: "Sai: VAT tax → Đúng: VAT (đã có Tax). Sai: price include VAT → Đúng: the price includes VAT.", u: "Hóa đơn, nhập khẩu: import VAT, VAT invoice, VAT-exclusive price; TOEIC hóa đơn.", f: "VAT, VAT-registered (adj), sales tax (Mỹ), GST" },
  "quota": { m: "Quota = 'phần được chia': lượng tối đa được phép nhập hoặc xuất.", e: "Sai: quota of import is limited → Đúng: an import quota limits the quantity. Số nhiều: quotas.", u: "Thương mại: import quota, tariff-rate quota; doanh nghiệp: sales quota.", f: "quota (n), tariff-rate quota, allocation (n), quotient (n, cùng gốc)" },
  "export licence": { m: "Licence = giấy phép: được 'phép' đưa hàng ra nước ngoài.", e: "Sai: export license (Anh-Anh danh từ) → Anh-Anh: licence (n), license (v); Mỹ: license cả hai.", u: "Hàng kiểm soát: apply for an export licence, dual-use goods, licence requirements.", f: "license (v), licensed (adj), licensee (n), permit (n)" },
  "customs inspection": { m: "Inspect = nhìn vào bên trong: hải quan mở hàng ra kiểm.", e: "Sai: customs check up → Đúng: customs inspection / goods are subject to inspection.", u: "Luồng đỏ: physical inspection, X-ray scanning, inspection fees, delay in release.", f: "inspect (v), inspection (n), inspector (n), examination (n)" },
  "bonded warehouse": { m: "Bond = cam kết: kho mà hàng 'cam kết' chưa nộp thuế, chờ thông quan hay tái xuất.", e: "Sai: bond warehouse → Đúng: bonded warehouse. Sai: goods in bonded warehouse paid tax → Đúng: duties are suspended.", u: "Logistics: store goods in a bonded warehouse, duty deferral, re-export without paying duty.", f: "bond (n), bonded (adj), in bond, free trade zone, customs warehouse" },
  "warehousing": { m: "Warehouse (kho) + -ing → hoạt động/dịch vụ cất giữ hàng trong kho.", e: "Sai: warehouse service of storage → Đúng: warehousing services. Sai: warehousings → Đúng: warehousing (không đếm được).", u: "3PL: warehousing and distribution, warehousing costs, storage and handling.", f: "warehouse (n/v), warehousing (n), storage (n), storekeeper (n)" },
  "distribution center": { m: "Distribute = phân phát: kho trung chuyển để phân hàng tới cửa hàng.", e: "Sai: distribute center → Đúng: distribution center (Anh-Anh: centre).", u: "Bán lẻ, logistics: regional distribution center, DC operations, store replenishment.", f: "DC, distribute (v), distribution (n), distributor (n), warehouse (n)" },
  "fulfillment center": { m: "Fulfill = hoàn thành: kho 'hoàn tất' đơn từ nhận, đóng gói đến gửi đi.", e: "Sai: fulfil center → Đúng: fulfillment center (Mỹ) / fulfilment centre (Anh).", u: "Thương mại điện tử: Amazon fulfillment center, order fulfillment, same-day shipping.", f: "fulfill/fulfil (v), fulfillment (n), order fulfillment, e-commerce warehouse" },
  "stock level": { m: "Level = mức: lượng hàng còn 'nằm' trong kho tại một thời điểm.", e: "Sai: stock is low level → Đúng: stock levels are low. Sai: stocks level → Đúng: stock level(s).", u: "Quản lý kho, TOEIC Part 3/4: monitor stock levels, reorder point, low stock alert.", f: "inventory level, stock (n/v), restock (v), reorder point" },
  "safety stock": { m: "Lượng hàng 'dự phòng an toàn' để không hết hàng khi nhu cầu tăng đột biến.", e: "Sai: safe stock → Đúng: safety stock (buffer stock). Sai: keep safety stocks too many → Đúng: keep excessive safety stock.", u: "Quản trị tồn kho: calculate safety stock, buffer against lead-time variability.", f: "buffer stock, reserve stock, reorder point, inventory (n)" },
  "stockout": { m: "Stock + out = 'hết sạch' hàng trong kho.", e: "Sai: the item is stockout → Đúng: the item is out of stock / we had a stockout.", u: "Bán lẻ, logistics: stockout costs, lost sales, prevent stockouts with forecasting.", f: "out of stock, stock-out (n), shortage (n), backorder (n)" },
  "lead time": { m: "Lead (dẫn) time: thời gian 'dẫn' từ đặt hàng đến khi nhận được.", e: "Sai: lead time is fast → Đúng: lead time is short. Đọc /liːd/, không phải /led/.", u: "Mua hàng, TOEIC: production lead time of 30 days, reduce lead time, delivery lead time.", f: "turnaround time, delivery time, cycle time, lead-time (adj)" },
  "sales contract": { m: "Hợp đồng ghi điều khoản 'mua bán': giá, số lượng, giao hàng.", e: "Sai: sale contract → Đúng: sales contract / contract of sale. Sai: sign contract with → Đúng: sign a sales contract with.", u: "Ngoại thương: sales contract specifies Incoterms, payment terms, shipment date; L/C phải khớp.", f: "purchase contract, sales agreement, purchase order (PO), contract (n/v)" },
  "sourcing": { m: "Source = nguồn: đi tìm 'nguồn' cung cấp hàng, nguyên liệu.", e: "Sai: source a supplier for buy → Đúng: source products from Vietnam / find a supplier.", u: "Mua hàng: global sourcing, sourcing agent, strategic sourcing, nearshoring.", f: "source (n/v), sourcing (n), outsourcing (n), procurement (n)" },
  "third-party logistics": { m: "Bên thứ ba (không phải bán, không phải mua) lo logistics thuê.", e: "Sai: third party logistic → Đúng: third-party logistics (3PL) – có gạch nối, logistics có -s.", u: "Ngành logistics: outsource to a 3PL, 3PL warehouse, 4PL quản lý cả chuỗi.", f: "3PL, 4PL, logistics provider, outsourcing (n)" },
  "last-mile delivery": { m: "Dặm cuối cùng: chặng từ kho gần nhất tới tận cửa khách.", e: "Sai: last mile shipping → Đúng: last-mile delivery. Sai: final mile is cheapest → Đúng: it is often the most expensive leg.", u: "E-commerce: last-mile delivery costs, delivery riders, parcel lockers, drones.", f: "final-mile delivery, first-mile, middle-mile, doorstep delivery" },
  "reverse logistics": { m: "Reverse = ngược: hàng đi ngược từ khách về người bán (đổi trả, tái chế).", e: "Sai: back logistics → Đúng: reverse logistics. Sai: reverse logistic → Đúng: reverse logistics.", u: "E-commerce, môi trường: product returns, refurbishment, recycling, circular economy.", f: "returns management, reverse supply chain, take-back (n)" },
  "cold chain": { m: "Chain 'lạnh': dây chuyền giữ nhiệt độ thấp liên tục từ đầu đến cuối.", e: "Sai: cool chain is broken → Đúng: the cold chain is broken (mất kiểm soát nhiệt độ).", u: "Thực phẩm, dược phẩm, vắc-xin: cold chain logistics, temperature-controlled storage.", f: "cold-chain (adj), refrigerated transport, reefer (n), temperature control" },
  "reefer container": { m: "Reefer = 'refrigerator' nói tắt: công-te-nơ có máy lạnh.", e: "Sai: refrigerator container → Đúng: reefer container (reefer). Sai: set reefer at → Đúng: set the reefer to -18°C.", u: "Xuất khẩu thủy sản, trái cây: reefer plug-in, set temperature, reefer surcharge.", f: "reefer (n), refrigerated container, refrigerate (v), dry container" },
  "perishable goods": { m: "Perish = hư, chết: hàng mau 'hư' như rau, cá, hoa.", e: "Sai: perishing goods → Đúng: perishable goods / perishables.", u: "Logistics, TOEIC: perishable goods require cold storage and fast transit; shelf life.", f: "perish (v), perishable (adj), perishables (n), non-perishable (adj)" },
  "dangerous goods": { m: "Goods 'nguy hiểm': dễ cháy, nổ, độc, phải khai báo riêng.", e: "Sai: danger goods → Đúng: dangerous goods (DG) / hazardous materials (hazmat).", u: "Vận tải: DG declaration, IMDG code (biển), IATA DGR (hàng không), MSDS.", f: "DG, hazmat, hazardous materials, IMDG, MSDS" },
  "pallet": { m: "Tấm 'đế' bằng gỗ/nhựa để xếp hàng, xe nâng xỏ càng vào.", e: "Sai: palette (bảng màu) → Đúng: pallet. Sai: put on pallet → Đúng: load the goods onto pallets.", u: "Kho bãi: palletized cargo, pallet racking, Euro pallet, stretch-wrapped pallets.", f: "palletize (v), palletized (adj), skid (n), pallet jack" },
  "forklift": { m: "Fork (cái nĩa) + lift (nâng): xe có hai 'răng nĩa' nâng hàng.", e: "Sai: drive a fork lift car → Đúng: operate a forklift (truck).", u: "Kho bãi, an toàn lao động: forklift operator, forklift licence, forklift safety training.", f: "forklift truck, lift truck, pallet jack, reach truck" },
  "loading dock": { m: "Dock = bến: cửa kho nơi xe tải lùi vào bốc dỡ hàng.", e: "Sai: load dock → Đúng: loading dock. Sai: at loading dock → Đúng: at the loading dock.", u: "Kho bãi, TOEIC Part 1/3: trucks at the loading dock, dock door, dock scheduling.", f: "dock (n/v), loading bay, dock door, unloading (n)" },
  "picking and packing": { m: "Pick = nhặt: nhặt đúng hàng trên kệ rồi đóng gói gửi khách.", e: "Sai: pick and pack the order wrongly order → Đúng: pick and pack orders accurately; avoid picking errors.", u: "Fulfillment: pick-and-pack service, picking list, picking accuracy, wave picking.", f: "pick (v), picker (n), pick-and-pack (adj), packing (n)" },
  "barcode": { m: "Bar (vạch) + code (mã): dãy vạch đen trắng máy quét đọc được.", e: "Sai: bar code scan → Đúng: scan the barcode. Cả barcode và bar code đều đúng.", u: "Kho, bán lẻ: barcode scanner, barcode labels, SKU, QR code, inventory tracking.", f: "barcode (n/v), barcoded (adj), QR code, SKU, RFID" },
  "tracking number": { m: "Track = theo dấu: dãy số để 'lần theo' bưu kiện.", e: "Sai: tracking code number of → Đúng: the tracking number for your order is…", u: "E-commerce, TOEIC email: 'Your tracking number is…', track your package online.", f: "track (v), tracking (n), waybill number, AWB number" },
  "shipment tracking": { m: "Theo dõi 'chuyến hàng' đang ở đâu, đến lúc nào.", e: "Sai: track shipment status by → Đúng: track the shipment online / check shipment tracking.", u: "Logistics, chăm sóc khách hàng: real-time shipment tracking, track and trace, visibility.", f: "track and trace, tracking (n), shipment (n), visibility (n)" },
  "transit time": { m: "Transit = đi qua: thời gian hàng 'trên đường' từ cảng đi đến cảng đến.", e: "Sai: transport time → Đúng: transit time. Sai: transit time is 20 days long → Đúng: transit time is 20 days.", u: "Báo giá cước: transit time 25 days via Singapore, direct service vs transshipment.", f: "transit (n/v), in transit, lead time, sailing time" },
  "port of loading": { m: "Cảng nơi hàng được 'chất' lên tàu.", e: "Sai: loading port of → Đúng: port of loading (POL). Sai: port of load → Đúng: port of loading.", u: "B/L, booking: POL Cat Lai, POD Los Angeles; ghi rõ trên chứng từ và L/C.", f: "POL, port of shipment, origin port, port of discharge" },
  "port of discharge": { m: "Discharge = dỡ ra: cảng nơi hàng được dỡ khỏi tàu.", e: "Sai: port of unload → Đúng: port of discharge (POD). Khác final destination nếu còn đi nội địa.", u: "B/L, booking: POD Rotterdam, place of delivery; đối chiếu với L/C.", f: "POD, destination port, port of loading, place of delivery" },
  "transshipment": { m: "trans- (chuyển qua) + shipment: hàng 'đổi tàu' giữa đường.", e: "Sai: transshipment allow → Đúng: transshipment allowed/permitted. Sai: transship cargos → Đúng: transship cargo. Anh-Anh còn viết transhipment.", u: "Vận tải biển, L/C: transshipment via Singapore, transshipment port, 'transshipment prohibited'.", f: "transship (v), transshipment (n), hub port, direct service" },
  "estimated time of arrival": { m: "Estimated = ước tính: thời gian 'dự kiến' đến, chưa chắc chắn.", e: "Sai: expected arrival time ETA is → Đúng: the ETA is 15 May. Sai: estimate time → Đúng: estimated time.", u: "Logistics, du lịch, TOEIC: 'ETA Hai Phong: 20/6', update the ETA, delay notice.", f: "ETA, ETD, arrival (n), arrive (v), estimate (v/n)" },
  "estimated time of departure": { m: "Departure = sự rời đi: thời gian dự kiến tàu hay máy bay khởi hành.", e: "Sai: ETD is the time tàu đến → Đúng: ETD is departure; ETA is arrival.", u: "Booking confirmation: ETD Cat Lai 10/6, cargo must arrive before cut-off; vessel delay.", f: "ETD, ETA, depart (v), departure (n), sailing date" },
  "cut-off time": { m: "Cut off = cắt: sau giờ này 'cắt', không nhận hàng hoặc chứng từ nữa.", e: "Sai: cutoff time to send SI is after → Đúng: submit the SI before the cut-off time.", u: "Vận tải biển: CY cut-off, SI cut-off, VGM cut-off; trễ thì rớt tàu (rolled).", f: "cut-off (n/adj), cut off (v), deadline (n), closing time" },
  "demurrage": { m: "Demur = trì hoãn: tiền phạt vì để công-te-nơ 'nằm' lâu trong cảng.", e: "Sai: demurrage and detention are same → Đúng: demurrage is inside the port; detention is outside.", u: "Logistics: demurrage charges after free time, D&D, negotiate extra free days.", f: "demurrage (n), detention (n), D&D, storage charge" },
  "detention": { m: "Detain = giữ lại: phí vì 'giữ' công-te-nơ của hãng tàu ngoài cảng quá hạn.", e: "Sai: pay detention for container in port → Đúng: detention applies when the container is outside the terminal.", u: "Xuất nhập khẩu: detention charges per day, return the empty container on time.", f: "detain (v), detention (n), demurrage (n), per diem (n)" },
  "free time": { m: "Thời gian 'miễn phí' trước khi bắt đầu bị tính DEM/DET.", e: "Sai: free days time → Đúng: free time (e.g. 7 days free time). Sai: free time over → Đúng: free time has expired.", u: "Đàm phán với hãng tàu: request 14 days combined free time at destination.", f: "free days, grace period, demurrage (n), detention (n)" },
  "surcharge": { m: "sur- (thêm, trên) + charge (phí): khoản phí 'cộng thêm' ngoài cước chính.", e: "Sai: subcharge → Đúng: surcharge. Sai: surcharge for fuel → Đúng: fuel surcharge (BAF).", u: "Báo giá cước: BAF, CAF, PSS, peak season surcharge; TOEIC: hidden surcharges.", f: "surcharge (n/v), charge (n/v), BAF, PSS, extra fee" },
  "terminal handling charge": { m: "Phí 'xử lý' tại terminal: xếp dỡ, di chuyển công-te-nơ trong cảng.", e: "Sai: terminal handle charge → Đúng: terminal handling charge (THC), thường thu theo công-te-nơ.", u: "Báo giá: THC at origin and destination, local charges, invoiced by shipping line.", f: "THC, handling (n), local charges, port charges" },
  "freight collect": { m: "Collect = thu: cước được 'thu' ở cảng đến, người nhận trả.", e: "Sai: freight is collected by shipper at origin → Đúng: under freight collect, the consignee pays at destination.", u: "B/L ghi 'Freight Collect' thường đi với FOB; ngược với freight prepaid (CIF/CFR).", f: "freight prepaid (đối lập), collect (v), FOB" },
  "freight prepaid": { m: "Pre- (trước) + paid: cước đã trả trước tại nơi đi.", e: "Sai: freight pre-pay → Đúng: freight prepaid. Sai: prepaid by consignee → Đúng: prepaid by the shipper.", u: "B/L ghi 'Freight Prepaid' với CIF, CFR; người bán trả cước cho hãng tàu.", f: "freight collect (đối lập), prepay (v), prepaid (adj), CIF" },
  "cargo insurance": { m: "Bảo hiểm cho 'cargo' (hàng chở trên tàu, máy bay).", e: "Sai: insurance of cargos → Đúng: cargo insurance (cargo thường không đếm được).", u: "Ngoại thương: buy cargo insurance, ICC (A)/(B)/(C), insured value 110% CIF, claim.", f: "marine insurance, insure (v), insurer (n), policy (n), claim (n)" },
  "insurance certificate": { m: "Chứng thư 'chứng minh' lô hàng đã được bảo hiểm.", e: "Sai: insurance certify → Đúng: insurance certificate. Sai: certificate of insure → Đúng: certificate of insurance.", u: "Bộ chứng từ L/C với CIF: present an insurance certificate or policy, endorsed in blank.", f: "insurance policy, certificate of insurance, certify (v), insurer (n)" },
  "inspection certificate": { m: "Chứng thư sau khi 'giám định' chất lượng, số lượng hàng.", e: "Sai: inspect certificate → Đúng: inspection certificate. Sai: issued from SGS → Đúng: issued by SGS.", u: "Ngoại thương: pre-shipment inspection, certificate issued by SGS/Vinacontrol, L/C requirement.", f: "inspection (n), inspect (v), inspector (n), survey report" },
  "phytosanitary certificate": { m: "phyto- (cây) + sanitary (vệ sinh) → giấy chứng nhận cây trồng 'sạch' sâu bệnh.", e: "Sai: phyto certificate for meat → Đúng: phytosanitary certificates are for plants; meat needs a veterinary/health certificate.", u: "Xuất khẩu nông sản, gỗ: phytosanitary certificate issued by plant protection authority.", f: "phytosanitary (adj), sanitary (adj), health certificate, quarantine (n)" },
  "fumigation": { m: "Fume = khói: dùng 'khói' hóa chất diệt côn trùng trong hàng, pallet.", e: "Sai: fumigate certificate → Đúng: fumigation certificate. Sai: fumigation the container → Đúng: fumigate the container.", u: "Xuất khẩu gỗ, nông sản: fumigation certificate, ISPM 15 pallets, methyl bromide.", f: "fumigate (v), fumigation (n), fumigant (n), fumes (n)" },
  "shipping mark": { m: "Mark = dấu: ký hiệu in trên thùng để nhận diện lô hàng.", e: "Sai: shipping marks is → Đúng: shipping marks are. Sai: ship mark → Đúng: shipping mark.", u: "Đóng gói: shipping marks show consignee, PO number, carton no., 'Made in Vietnam'.", f: "marking (n), mark (n/v), label (n), carton marks" },
  "gross weight": { m: "Gross = tổng: trọng lượng hàng cộng cả bao bì.", e: "Sai: gross weight is lighter than net → Đúng: gross weight is always heavier than net weight.", u: "Packing list, B/L: G.W., N.W., VGM; dùng tính cước và kiểm tra tải.", f: "G.W., net weight, tare weight, VGM" },
  "net weight": { m: "Net = tịnh: chỉ riêng hàng, đã bỏ bao bì.", e: "Sai: nett weight includes box → Đúng: net weight excludes packaging.", u: "Packing list, nhãn thực phẩm: N.W. 500g, net weight vs gross weight.", f: "N.W., gross weight, tare weight, net (adj)" },
  "volumetric weight": { m: "Volume = thể tích: hàng nhẹ mà cồng kềnh bị tính cước theo 'kích thước'.", e: "Sai: volume weight calculated by weight → Đúng: volumetric weight = L×W×H / 6000 (air).", u: "Hàng không, chuyển phát: chargeable weight is the greater of actual and volumetric weight.", f: "dimensional weight, chargeable weight, volume (n), volumetric (adj)" },
  "cubic meter": { m: "Cubic = khối lập phương: 1m × 1m × 1m.", e: "Sai: meter cube → Đúng: cubic meter (CBM, m³). Anh-Anh viết cubic metre.", u: "LCL, báo giá: rate per CBM, calculate CBM from carton dimensions.", f: "CBM, cube (n), cubic (adj), volume (n)" },
  "multimodal transport": { m: "multi- (nhiều) + mode (phương thức): một lô hàng đi bằng nhiều loại phương tiện.", e: "Sai: multi-mode transportation → Đúng: multimodal transport. Sai: multimodal transports → Đúng: multimodal transport (không đếm được).", u: "Logistics: sea-rail-road multimodal transport, MTO, one contract and one document.", f: "multimodal (adj), intermodal (adj), combined transport, mode (n)" },
  "road freight": { m: "Freight đi 'đường bộ': xe tải, container truck.", e: "Sai: road transport freights → Đúng: road freight. Sai: by road freight → Đúng: by road.", u: "Logistics: road freight rates, FTL/LTL, cross-border road freight to China.", f: "road haulage, trucking (n), FTL, LTL" },
  "rail freight": { m: "Freight đi 'đường ray': tàu hỏa chở hàng.", e: "Sai: train freight → Đúng: rail freight. Sai: send by train freight → Đúng: send by rail.", u: "Logistics: China–Europe rail freight, rail terminal, lower emissions than road.", f: "rail (n), railway (n), freight train, rail transport" },
  "air freight": { m: "Freight đi 'đường không': nhanh nhưng đắt.", e: "Sai: airfreight by plane cargo → Đúng: ship by air freight. Sai: air freights → Đúng: air freight.", u: "Logistics: air freight rates per kg, chargeable weight, urgent shipments, AWB.", f: "air cargo, airfreight (v/n), air shipment, air waybill" },
  "sea freight": { m: "Freight đi 'đường biển': rẻ, chậm, chở số lượng lớn.", e: "Sai: by sea freight ship → Đúng: by sea / via sea freight. Đồng nghĩa: ocean freight.", u: "Báo giá: sea freight rate, FCL/LCL, transit time; IELTS Task 1 về vận tải.", f: "ocean freight, shipping (n), maritime (adj), sea cargo" },
  "inland waterway": { m: "Inland = trong đất liền: sông, kênh dùng chở hàng.", e: "Sai: inside waterway → Đúng: inland waterway. Sai: by waterway inland → Đúng: by inland waterway.", u: "Logistics Việt Nam: barge transport on Mekong, inland waterway terminals, giảm tải đường bộ.", f: "barge (n), river transport, waterway (n), inland (adj)" },
  "dry port": { m: "Port 'khô': cảng nằm sâu trong đất liền, không có nước, làm thủ tục như cảng biển.", e: "Sai: land port (cửa khẩu) → Đúng: dry port / inland container depot (ICD).", u: "Logistics: ICD Song Than, dry port connected by rail/barge to seaports.", f: "ICD, inland container depot, inland port, seaport (n)" },
  "container yard": { m: "Yard = sân, bãi: bãi chứa công-te-nơ tại cảng.", e: "Sai: container field → Đúng: container yard (CY). Sai: deliver at CY port → Đúng: deliver to the CY.", u: "Vận tải biển: CY cut-off, CY/CY term, pick up empty container at the depot.", f: "CY, terminal (n), depot (n), CFS" },
  "container freight station": { m: "Station 'hàng lẻ': nơi gom và chia hàng LCL vào/ra công-te-nơ.", e: "Sai: CFS for full container → Đúng: CFS handles LCL cargo; FCL goes to the CY.", u: "Logistics: CFS charge, stuffing/unstuffing at CFS, LCL consolidation.", f: "CFS, CY, consolidation (n), stuffing (n), devanning (n)" },
  "port congestion": { m: "Congest = dồn ứ: tàu xếp hàng chờ cập cầu như kẹt xe.", e: "Sai: port is congestion → Đúng: the port is congested / there is port congestion.", u: "Logistics news: port congestion causes delays, congestion surcharge, waiting time at anchorage.", f: "congested (adj), congestion (n), bottleneck (n), backlog (n)" },
  "route optimization": { m: "Optimize = làm tối ưu: chọn đường ngắn, rẻ, nhanh nhất cho xe giao hàng.", e: "Sai: optimize route → Đúng: optimize routes / route optimization. Anh-Anh: optimisation.", u: "Logistics, công nghệ: route optimization software reduces fuel cost and delivery time.", f: "optimize (v), optimal (adj), optimization (n), route planning" },
  "haulage": { m: "Haul = kéo: dịch vụ 'kéo' công-te-nơ bằng xe đầu kéo.", e: "Sai: haulage the container → Đúng: haul the container. Haulage là danh từ.", u: "Logistics Anh-Anh: carrier haulage vs merchant haulage, haulage company, haulage rates.", f: "haul (v/n), haulier/hauler (n), trucking (n), drayage (n, Mỹ)" },
  "trucking": { m: "Truck (xe tải) + -ing → dịch vụ chở hàng bằng xe tải.", e: "Sai: trucking the goods to port → Đúng: truck the goods to the port. Sai: truckings → Đúng: trucking.", u: "Logistics Việt Nam: trucking service, trucking fee from factory to Cat Lai port.", f: "truck (n/v), trucker (n), haulage (n), road freight" },
  "door-to-door": { m: "Từ 'cửa' người gửi đến 'cửa' người nhận: lo trọn mọi chặng.", e: "Sai: door to door service (không gạch nối khi làm tính từ) → Đúng: a door-to-door service.", u: "Logistics, chuyển phát: door-to-door delivery, all-inclusive rate, DDP/DAP.", f: "port-to-port, door-to-port, end-to-end, house-to-house" },
  "delivery note": { m: "Note = phiếu: tờ giấy đi kèm hàng, người nhận ký xác nhận.", e: "Sai: delivery bill → Đúng: delivery note (Anh) / delivery slip. Sai: sign on the delivery note → Đúng: sign the delivery note.", u: "Kho bãi, TOEIC: check goods against the delivery note, discrepancies.", f: "delivery slip, packing slip, proof of delivery, deliver (v)" },
  "proof of delivery": { m: "Proof = bằng chứng: chữ ký hay ảnh chứng minh hàng đã giao.", e: "Sai: delivery proof prove → Đúng: provide proof of delivery (POD). Sai: proves of delivery → Đúng: proof of delivery.", u: "Logistics, e-commerce: electronic POD, signature on delivery, dispute resolution.", f: "POD, prove (v), proof (n), delivery confirmation, delivery note" },
  "cross-border e-commerce": { m: "Cross border = vượt biên giới: bán hàng online cho khách nước khác.", e: "Sai: crossborder e-commerces → Đúng: cross-border e-commerce (không đếm được).", u: "Thương mại, IELTS Writing: cross-border e-commerce platforms, parcel shipping, customs de minimis.", f: "cross-border (adj), e-commerce (n), online retail, de minimis" },
  "re-export": { m: "re- (lại) + export: nhập vào rồi 'xuất lại' sang nước khác.", e: "Sai: export again → Đúng: re-export. Sai: re-exportation goods → Đúng: re-exported goods.", u: "Hải quan: temporary import for re-export, re-export via bonded warehouse.", f: "re-export (n/v), re-exportation (n), re-exporter (n), transit (n)" },
  "trade balance": { m: "Balance = cái cân: so xuất khẩu với nhập khẩu, bên nào nặng hơn.", e: "Sai: trade balance is negative profit → Đúng: a trade deficit / trade surplus.", u: "IELTS Writing Task 1/2, kinh tế: trade surplus, trade deficit, balance of trade.", f: "balance of trade, trade surplus, trade deficit, balance of payments" },
  "trade barrier": { m: "Barrier = rào chắn: thuế, hạn ngạch dựng lên cản hàng ngoại.", e: "Sai: remove barrier trade → Đúng: remove trade barriers. Sai: trade barriers is → Đúng: trade barriers are.", u: "IELTS Writing Task 2 về toàn cầu hóa: tariff and non-tariff barriers, free trade agreements.", f: "tariff (n), protectionism (n), non-tariff barrier, quota (n)" },
  "anti-dumping duty": { m: "Dump = đổ bỏ: thuế chống hàng bị 'đổ' sang bán dưới giá thành.", e: "Sai: antidumping tax impose on → Đúng: impose anti-dumping duties on steel imports.", u: "Thương mại quốc tế: anti-dumping investigation, WTO rules, Việt Nam xuất khẩu thép, tôm.", f: "dumping (n), dump (v), countervailing duty, safeguard measure" },
  "rules of origin": { m: "Các 'luật' xác định hàng được coi là sản xuất ở đâu.", e: "Sai: rule of origins → Đúng: rules of origin. Sai: meet the origin rules → Đúng: meet the rules of origin.", u: "FTA, xuất khẩu: comply with rules of origin to get preferential tariffs; RVC 40%.", f: "origin (n), C/O, regional value content (RVC), FTA" },
  "tariff preference": { m: "Preference = sự ưu tiên: thuế thấp hơn dành cho hàng nước đối tác.", e: "Sai: tariff preferential → Đúng: tariff preference / preferential tariff.", u: "FTA, hải quan: enjoy tariff preferences under EVFTA, preferential tariff rate.", f: "preferential (adj), prefer (v), preference (n), MFN tariff" },
  "minimum order quantity": { m: "Số lượng 'tối thiểu' nhà cung cấp chịu nhận cho một đơn.", e: "Sai: minimum quantity order → Đúng: minimum order quantity (MOQ). Sai: below MOQ is → Đúng: orders below the MOQ are…", u: "Sourcing, đàm phán: MOQ of 500 pcs, negotiate a lower MOQ, unit price by quantity.", f: "MOQ, order quantity, bulk order, minimum (n/adj)" },
  "sample order": { m: "Đơn 'thử' nhỏ để kiểm tra chất lượng trước khi đặt hàng loạt.", e: "Sai: order a sample order → Đúng: place a sample order. Sai: samples order → Đúng: sample order (danh từ đứng trước dùng số ít).", u: "Sourcing: sample order, sample fee, approved sample, then bulk order.", f: "trial order, sample (n/v), bulk order, prototype (n)" },
  "demand forecasting": { m: "Forecast = dự báo: đoán trước khách sẽ mua bao nhiêu.", e: "Sai: forecast demand forecasting → Đúng: forecast demand / demand forecasting. Sai: forecasted → thường dùng forecast (V2/V3).", u: "Supply chain: accurate demand forecasting reduces stockouts and excess inventory.", f: "forecast (n/v), forecaster (n), demand planning, prediction (n)" },
  "bullwhip effect": { m: "Hình ảnh: vẩy cán roi nhẹ, đầu roi quất mạnh → biến động nhỏ ở khách, lớn ở nhà cung cấp.", e: "Sai: whip effect → Đúng: bullwhip effect. Sai: bullwhip effect reduce demand → Đúng: it amplifies demand fluctuations.", u: "Quản trị chuỗi cung ứng: causes of the bullwhip effect, information sharing to reduce it.", f: "demand amplification, Forrester effect, supply chain variability" },
  "warehouse management system": { m: "Phần mềm 'quản lý kho': vị trí hàng, nhập, xuất, tồn.", e: "Sai: warehouse manage system → Đúng: warehouse management system (WMS).", u: "Logistics, IT: implement a WMS, barcode scanning, real-time inventory, integrate with ERP.", f: "WMS, ERP, TMS, inventory system" },
  "first in, first out": { m: "Hàng vào trước thì ra trước, như xếp hàng mua vé.", e: "Sai: first in first output → Đúng: first in, first out (FIFO). Đối lập: LIFO.", u: "Kho thực phẩm, dược, kế toán: apply FIFO to avoid expired stock; FIFO inventory valuation.", f: "FIFO, LIFO, FEFO (first expired, first out)" },
  "cycle count": { m: "Cycle = vòng: đếm kho 'xoay vòng' từng khu, không cần đóng kho.", e: "Sai: cycle counting all warehouse once a year → Đúng: cycle counts check small sections regularly.", u: "Quản lý kho: daily cycle counts, inventory accuracy, thay cho full physical count.", f: "cycle counting (n), stocktake (n), physical inventory, count (v)" },
  "backorder": { m: "Back = về sau: đơn được giữ lại, giao 'sau' khi có hàng.", e: "Sai: the item is backordering → Đúng: the item is on backorder / is backordered.", u: "E-commerce, TOEIC email: 'This item is on backorder and will ship in 2 weeks.'", f: "backorder (n/v), backordered (adj), stockout (n), pre-order (n)" },
  "cross-docking": { m: "Hàng chuyển 'băng qua' dock: từ xe nhận sang xe giao, không cất kho.", e: "Sai: cross docking store goods long → Đúng: cross-docking minimizes storage time.", u: "Phân phối bán lẻ: cross-docking at the distribution center, faster flow, lower holding cost.", f: "cross-dock (n/v), transloading (n), flow-through, warehouse (n)" },
  "logistics hub": { m: "Hub = trục bánh xe: điểm trung tâm nơi hàng tỏa đi mọi hướng.", e: "Sai: logistic hub → Đúng: logistics hub. Sai: become hub logistics → Đúng: become a logistics hub.", u: "Kinh tế, IELTS Writing: Vietnam aims to become a regional logistics hub; hub-and-spoke.", f: "hub (n), hub-and-spoke (adj), logistics centre, gateway (n)" },
  "customs bond": { m: "Bond = cam kết bảo lãnh: đảm bảo thuế sẽ được nộp cho hải quan.", e: "Sai: custom bond → Đúng: customs bond. Sai: bonded customs → Đúng: customs bond.", u: "Nhập khẩu Mỹ: continuous bond, single-entry bond, required for ISF and entry.", f: "surety bond, bonded (adj), bond (n), guarantee (n)" },
  "shipping instructions": { m: "Instructions = chỉ dẫn: thông tin để hãng tàu làm vận đơn.", e: "Sai: shipping instruction is late → Đúng: the shipping instructions (SI) are late. Thường dùng số nhiều.", u: "Vận tải biển: submit SI before SI cut-off; check consignee, notify party, cargo details.", f: "SI, instruct (v), instruction (n), booking (n), draft B/L" },
  "customs valuation": { m: "Value = giá trị: cách hải quan 'định giá' hàng để tính thuế.", e: "Sai: customs value calculating → Đúng: customs valuation. Sai: valuation of customs → Đúng: customs valuation.", u: "Hải quan: transaction value method, WTO valuation agreement, CIF-based customs value.", f: "value (n/v), valuation (n), customs value, transaction value" },
}); })(typeof self !== "undefined" ? self : this);
